// Multi-tradition mythological depth for animal guides.
// Layered ON TOP of Ayşe Nilgün Fırat's daily guidance — never replaces it.
// Each animal can be progressively enriched; missing fields render gracefully.

type Bilingual = { tr: string; en: string };
type BilingualTradition = { culture: Bilingual; meaning: Bilingual };

export interface AnimalLore {
  jung?: Bilingual;
  dream?: Bilingual;
  shadow?: Bilingual;
  traditions?: BilingualTradition[];
  myths?: Bilingual[];
  whenAppears?: Bilingual;
}

export interface Tradition {
  culture: string;
  meaning: string;
}

export const ANIMAL_LORE: Record<string, AnimalLore> = {
  // ─── a001 Bozkurt ───────────────────────────────────────────────────────
  a001: {
    jung: {
      tr: 'Bozkurt, kolektif bilinçaltında "Yol Gösteren Lider" arketipidir — kaybolmuş benliği eve döndüren içsel ses. Karanlık ormanda ışığı bulduran içgüdü.',
      en: 'The Grey Wolf is the "Guiding Leader" archetype within the Collective Unconscious — the inner voice that returns the lost Self home. The instinct that finds light in the dark forest.',
      de: 'Der Graue Wolf ist der Archetyp des "führenden Anführers" im kollektiven Unbewussten — die innere Stimme, die das verlorene Selbst nach Hause zurückbringt. Der Instinkt, der im dunklen Wald das Licht findet.',
      es: 'El Lobo Gris es el arquetipo del "Líder Guía" dentro del Inconsciente Colectivo — la voz interior que devuelve a casa al Yo perdido. El instinto que encuentra la luz en el bosque oscuro.',
      pt: 'O Lobo Cinzento é o arquétipo do "Líder Guia" dentro do Inconsciente Coletivo — a voz interior que traz de volta a casa o Eu perdido. O instinto que encontra a luz na floresta escura.',
      fr: 'Le Loup Gris est l\'archétype du "Leader Guide" au sein de l\'Inconscient Collectif — la voix intérieure qui ramène le Soi perdu à la maison. L\'instinct qui trouve la lumière dans la forêt obscure.',
      ja: '灰色オオカミは集合的無意識における「導く指導者」の元型である——失われた自己を家へと連れ戻す内なる声。暗い森の中で光を見いだす本能。',
    },
    dream: {
      tr: 'Rüyada bozkurt — yolunu kaybettiğini ama içsel pusulanın hâlâ çalıştığını söyler. Sürünün sesi geliyor; dinle.',
      en: 'A wolf in dream — tells you that you have lost your way, but your inner compass still works. The call of the pack is coming; listen.',
      de: 'Ein Wolf im Traum — sagt dir, dass du deinen Weg verloren hast, doch dein innerer Kompass funktioniert noch. Der Ruf des Rudels kommt; höre hin.',
      es: 'Un lobo en sueños — te dice que has perdido tu camino, pero tu brújula interior aún funciona. La llamada de la manada se acerca; escucha.',
      pt: 'Um lobo em sonho — diz-te que perdeste o teu caminho, mas a tua bússola interior ainda funciona. O chamado da matilha aproxima-se; escuta.',
      fr: 'Un loup en rêve — te dit que tu as perdu ton chemin, mais que ta boussole intérieure fonctionne encore. L\'appel de la meute arrive ; écoute.',
      ja: '夢の中のオオカミ——あなたは道を見失っているが、内なる羅針盤はまだ働いていると告げる。群れの呼び声が近づいている。耳を傾けよ。',
    },
    shadow: {
      tr: 'Sürü zihniyetinde kaybolma. Bozkurt enerjisi kontrol edilemezse otoriter sertlik, kurt sürüsünün acımasızlığı çıkar.',
      en: 'Losing oneself in pack mentality. If the wolf energy goes unchecked, it manifests as authoritarian harshness and the ruthlessness of the wolf pack.',
      de: 'Sich in der Mentalität des Rudels verlieren. Bleibt die Wolfsenergie ungezügelt, äußert sie sich als autoritäre Härte und die Erbarmungslosigkeit des Wolfsrudels.',
      es: 'Perderse en la mentalidad de manada. Si la energía del lobo no se controla, se manifiesta como dureza autoritaria y la crueldad de la manada.',
      pt: 'Perderes-te na mentalidade de matilha. Se a energia do lobo não for controlada, manifesta-se como dureza autoritária e a crueldade da matilha.',
      fr: 'Se perdre dans la mentalité de meute. Si l\'énergie du loup n\'est pas maîtrisée, elle se manifeste par une dureté autoritaire et la cruauté de la meute.',
      ja: '群れの心理に自己を見失うこと。オオカミのエネルギーが制御されなければ、権威的な厳しさと群れの非情さとして現れる。',
    },
    whenAppears: {
      tr: 'Yalnız kaldığında, liderlik testinde, ailene/topluluğuna döndüğünde.',
      en: 'When you are alone, facing a test of leadership, returning to your family or community.',
      de: 'Wenn du allein bist, eine Prüfung der Führung bestehst, zu deiner Familie oder Gemeinschaft zurückkehrst.',
      es: 'Cuando estás solo, enfrentas una prueba de liderazgo, regresas a tu familia o comunidad.',
      pt: 'Quando estás sozinho, enfrentas uma prova de liderança, regressas à tua família ou comunidade.',
      fr: 'Quand tu es seul, face à une épreuve de leadership, en revenant vers ta famille ou ta communauté.',
      ja: 'ひとりでいるとき、指導力の試練に直面したとき、家族や共同体へ戻るとき。',
    },
    traditions: [
      { culture: { tr: 'Türk Şamanizmi', en: 'Turkic Shamanism', de: 'Türkischer Schamanismus', es: 'Chamanismo Túrquico', pt: 'Xamanismo Túrquico', fr: 'Chamanisme Turc', ja: 'テュルク・シャーマニズム' }, meaning: { tr: 'Asena/Bozkurt — kutsal ata. Göktürk efsanesinde kaybolan halkı kurtaran ana. Devlet kurucu enerji.', en: 'Asena/Grey Wolf — the sacred ancestor. In the Göktürk legend, the mother who saved the lost people. State-founding energy.', de: 'Asena/Grauer Wolf — der heilige Ahn. In der Göktürk-Legende die Mutter, die das verlorene Volk rettete. Staatsgründende Energie.', es: 'Asena/Lobo Gris — el ancestro sagrado. En la leyenda Göktürk, la madre que salvó al pueblo perdido. Energía fundadora de estados.', pt: 'Asena/Lobo Cinzento — o ancestral sagrado. Na lenda Göktürk, a mãe que salvou o povo perdido. Energia fundadora de estados.', fr: 'Asena/Loup Gris — l\'ancêtre sacré. Dans la légende Göktürk, la mère qui sauva le peuple perdu. Énergie fondatrice d\'États.', ja: 'アセナ／灰色オオカミ——神聖な祖先。突厥（ギョクテュルク）伝説では、失われた民を救った母。国家を建てるエネルギー。' } },
      { culture: { tr: 'Roma Mitolojisi', en: 'Roman Mythology', de: 'Römische Mythologie', es: 'Mitología Romana', pt: 'Mitologia Romana', fr: 'Mythologie Romaine', ja: 'ローマ神話' }, meaning: { tr: 'Lupa — Romulus ve Remus\'u emziren dişi kurt. Şehir kurucu, medeniyet besleyici.', en: 'Lupa — the she-wolf who suckled Romulus and Remus. City-founder, nurturer of civilization.', de: 'Lupa — die Wölfin, die Romulus und Remus säugte. Stadtgründerin, Nährerin der Zivilisation.', es: 'Lupa — la loba que amamantó a Rómulo y Remo. Fundadora de ciudades, nutriz de la civilización.', pt: 'Lupa — a loba que amamentou Rómulo e Remo. Fundadora de cidades, nutriz da civilização.', fr: 'Lupa — la louve qui allaita Romulus et Remus. Fondatrice de cité, nourricière de la civilisation.', ja: 'ルーパ——ロムルスとレムスに乳を与えた雌オオカミ。都市の創建者、文明の養い手。' } },
      { culture: { tr: 'İskandinav', en: 'Norse', de: 'Nordisch', es: 'Nórdico', pt: 'Nórdico', fr: 'Nordique', ja: '北欧' }, meaning: { tr: 'Fenrir — kontrol edilemeyen kozmik güç. Aynı zamanda Odin\'in iki yol arkadaşı Geri ve Freki.', en: 'Fenrir — uncontrollable cosmic force. Also Odin\'s two companions, Geri and Freki.', de: 'Fenrir — unkontrollierbare kosmische Kraft. Auch Odins zwei Gefährten Geri und Freki.', es: 'Fenrir — fuerza cósmica incontrolable. También los dos compañeros de Odín, Geri y Freki.', pt: 'Fenrir — força cósmica incontrolável. Também os dois companheiros de Odin, Geri e Freki.', fr: 'Fenrir — force cosmique incontrôlable. Aussi les deux compagnons d\'Odin, Geri et Freki.', ja: 'フェンリル——制御不能な宇宙の力。同時にオーディンの二匹の供、ゲリとフレキ。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Lakota geleneğinde "öğretmen". Sürü, aile, sadakat dersleri verir.', en: 'In Lakota tradition, the "teacher". Imparts lessons of pack, family, and loyalty.', de: 'In der Lakota-Tradition der "Lehrer". Vermittelt Lektionen über Rudel, Familie und Treue.', es: 'En la tradición Lakota, el "maestro". Imparte lecciones de manada, familia y lealtad.', pt: 'Na tradição Lakota, o "mestre". Transmite lições de matilha, família e lealdade.', fr: 'Dans la tradition Lakota, le "maître". Transmet des leçons de meute, de famille et de loyauté.', ja: 'ラコタの伝統では「教師」。群れ、家族、忠誠の教えを授ける。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Cu Chulainn\'in koruyucusu. Ay\'ın bekçisi, geçişlerin habercisi.', en: 'Protector of Cú Chulainn. Guardian of the Moon, herald of transitions.', de: 'Beschützer von Cú Chulainn. Wächter des Mondes, Herold der Übergänge.', es: 'Protector de Cú Chulainn. Guardián de la Luna, heraldo de las transiciones.', pt: 'Protetor de Cú Chulainn. Guardião da Lua, arauto das transições.', fr: 'Protecteur de Cú Chulainn. Gardien de la Lune, héraut des transitions.', ja: 'クー・フーリンの守護者。月の番人、移り変わりの使者。' } },
    ],
    myths: [
      { tr: 'Göktürk Efsanesi: Düşman tarafından yok edilen Türk soyundan sağ kalan tek çocuğu Asena dişi kurdu kurtarır, mağarada büyütür. Türk halkı bu çocuğun soyundan türer.', en: 'Göktürk Legend: Asena, the she-wolf, rescues the sole surviving child of the Turkic lineage destroyed by enemies and raises him in a cave. The Turkic people descend from this child.', de: 'Göktürk-Legende: Asena, die Wölfin, rettet das einzige überlebende Kind der von Feinden vernichteten türkischen Linie und zieht es in einer Höhle auf. Das türkische Volk stammt von diesem Kind ab.', es: 'Leyenda Göktürk: Asena, la loba, rescata al único niño superviviente del linaje túrquico destruido por enemigos y lo cría en una cueva. El pueblo túrquico desciende de este niño.', pt: 'Lenda Göktürk: Asena, a loba, resgata a única criança sobrevivente da linhagem túrquica destruída pelos inimigos e cria-a numa caverna. O povo túrquico descende desta criança.', fr: 'Légende Göktürk : Asena, la louve, sauve le seul enfant survivant de la lignée turque anéantie par les ennemis et l\'élève dans une grotte. Le peuple turc descend de cet enfant.', ja: '突厥伝説：アセナという雌オオカミが、敵に滅ぼされたテュルクの血筋の唯一の生き残りの子を救い、洞窟で育てる。テュルクの民はこの子の末裔である。' },
      { tr: 'Roma\'nın Kuruluşu: Romulus ve Remus\'u nehre bırakılınca dişi kurt Lupa bulup emzirir. Roma şehri bu çocuklar tarafından kurulur.', en: 'The Founding of Rome: When Romulus and Remus were left by the river, the she-wolf Lupa found and suckled them. The city of Rome was founded by these children.', de: 'Die Gründung Roms: Als Romulus und Remus am Fluss ausgesetzt wurden, fand die Wölfin Lupa sie und säugte sie. Die Stadt Rom wurde von diesen Kindern gegründet.', es: 'La fundación de Roma: Cuando Rómulo y Remo fueron abandonados junto al río, la loba Lupa los encontró y amamantó. La ciudad de Roma fue fundada por estos niños.', pt: 'A fundação de Roma: Quando Rómulo e Remo foram deixados junto ao rio, a loba Lupa encontrou-os e amamentou-os. A cidade de Roma foi fundada por estas crianças.', fr: 'La fondation de Rome : Lorsque Romulus et Remus furent abandonnés près du fleuve, la louve Lupa les trouva et les allaita. La ville de Rome fut fondée par ces enfants.', ja: 'ローマの建国：ロムルスとレムスが川辺に捨てられたとき、雌オオカミのルーパが見つけて乳を与えた。ローマの都はこの子らによって築かれた。' },
    ],
  },

  // ─── a002 Kartal ────────────────────────────────────────────────────────
  a002: {
    jung: { tr: 'Kartal, "Yüksek Benlik" arketipidir. Egodan kopup ruhsal perspektife geçişin sembolü. Üçüncü gözün hayvan formu.', en: 'The Eagle is the "Higher Self" archetype. A symbol of detaching from ego into spiritual perspective. The animal form of the third eye.', de: 'Der Adler ist der Archetyp des "höheren Selbst". Ein Symbol für die Ablösung vom Ego hin zur spirituellen Perspektive. Die Tiergestalt des dritten Auges.', es: 'El Águila es el arquetipo del "Yo Superior". Símbolo del desapego del ego hacia la perspectiva espiritual. La forma animal del tercer ojo.', pt: 'A Águia é o arquétipo do "Eu Superior". Símbolo do desapego do ego rumo à perspetiva espiritual. A forma animal do terceiro olho.', fr: 'L\'Aigle est l\'archétype du "Soi supérieur". Symbole du détachement de l\'ego vers la perspective spirituelle. La forme animale du troisième œil.', ja: 'ワシは「高次の自己」の元型である。自我から離れて霊的な視座へと至る象徴。第三の目の動物形。' },
    dream: { tr: 'Kartalın uçtuğunu görmek — düşüncenin yükseldiğine, sorunun küçüldüğüne işaret. Kartal seni avlıyorsa: yüksek bir gerçek aşağıdan seni yakalamaya geliyor.', en: 'Seeing an eagle in flight — indicates that thought is rising and the problem is shrinking. If the eagle is hunting you: a higher truth is coming from above to catch you.', de: 'Einen Adler im Flug zu sehen — zeigt an, dass das Denken sich erhebt und das Problem schrumpft. Jagt dich der Adler: Eine höhere Wahrheit kommt von oben, um dich zu fassen.', es: 'Ver un águila en vuelo — indica que el pensamiento se eleva y el problema se reduce. Si el águila te caza: una verdad superior viene desde arriba a atraparte.', pt: 'Ver uma águia em voo — indica que o pensamento se eleva e o problema diminui. Se a águia te caça: uma verdade superior vem do alto para te apanhar.', fr: 'Voir un aigle en vol — indique que la pensée s\'élève et que le problème rétrécit. Si l\'aigle te chasse : une vérité supérieure vient d\'en haut te saisir.', ja: '飛ぶワシを見ること——思考が高まり、問題が小さくなっている兆し。ワシがあなたを狩るなら、より高き真実が上から捕らえに来ている。' },
    shadow: { tr: 'Soğuk uzaklık. Toprağa bağlanmamış zihinsellik. Mesafeden bakmak insandan kopmaya dönüşürse — kartal düşer.', en: 'Cold distance. Mentality unrooted from the earth. When viewing from afar turns into disconnection from humanity — the eagle falls.', de: 'Kalte Distanz. Eine Geistigkeit ohne Wurzeln in der Erde. Wird das Betrachten aus der Ferne zur Entfremdung von den Menschen — stürzt der Adler.', es: 'Distancia fría. Mentalidad sin raíces en la tierra. Cuando mirar desde lejos se vuelve desconexión de la humanidad — el águila cae.', pt: 'Distância fria. Mentalidade sem raízes na terra. Quando olhar de longe se torna desconexão da humanidade — a águia cai.', fr: 'Froide distance. Une mentalité sans racines dans la terre. Quand regarder de loin devient rupture avec l\'humanité — l\'aigle tombe.', ja: '冷たい距離。大地に根を持たない精神性。遠くから眺めることが人間からの断絶に変わるとき——ワシは墜ちる。' },
    whenAppears: { tr: 'Büyük kararlar öncesi, perspektif kaybettiğinde, hayalle gerçek arasında köprü kurarken.', en: 'Before major decisions, when you have lost perspective, while bridging dream and reality.', de: 'Vor großen Entscheidungen, wenn du die Perspektive verloren hast, während du Traum und Wirklichkeit überbrückst.', es: 'Antes de grandes decisiones, cuando has perdido la perspectiva, mientras tiendes un puente entre el sueño y la realidad.', pt: 'Antes de grandes decisões, quando perdeste a perspetiva, enquanto fazes a ponte entre o sonho e a realidade.', fr: 'Avant de grandes décisions, quand tu as perdu la perspective, en jetant un pont entre le rêve et la réalité.', ja: '大きな決断の前、視座を失ったとき、夢と現実の架け橋をかけるとき。' },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Zeus\'un kuşu. Tanrının iradesini taşıyan haberci. Ganimedes\'i Olympos\'a taşıyan ruhsal yükselici.', en: 'Zeus\'s bird. The messenger carrying the god\'s will. The spiritual ascender who carried Ganymede to Olympus.', de: 'Zeus\' Vogel. Der Bote, der den Willen des Gottes trägt. Der spirituelle Aufsteiger, der Ganymed zum Olymp trug.', es: 'El ave de Zeus. El mensajero que porta la voluntad del dios. El ascendente espiritual que llevó a Ganimedes al Olimpo.', pt: 'A ave de Zeus. O mensageiro que carrega a vontade do deus. O ascendente espiritual que levou Ganimedes ao Olimpo.', fr: 'L\'oiseau de Zeus. Le messager portant la volonté du dieu. L\'ascendant spirituel qui porta Ganymède à l\'Olympe.', ja: 'ゼウスの鳥。神の意志を運ぶ使者。ガニュメデスをオリュンポスへ運んだ霊的な昇り手。' } },
      { culture: { tr: 'Hitit', en: 'Hittite', de: 'Hethitisch', es: 'Hitita', pt: 'Hitita', fr: 'Hittite', ja: 'ヒッタイト' }, meaning: { tr: 'Çift başlı kartal — gökle yerin birleşim noktası. Anadolu\'nun en kadim devlet sembolü.', en: 'The double-headed eagle — the meeting point of sky and earth. Anatolia\'s most ancient symbol of statehood.', de: 'Der doppelköpfige Adler — der Treffpunkt von Himmel und Erde. Anatoliens ältestes Symbol der Staatlichkeit.', es: 'El águila bicéfala — el punto de encuentro entre el cielo y la tierra. El símbolo de estatalidad más antiguo de Anatolia.', pt: 'A águia bicéfala — o ponto de encontro entre o céu e a terra. O símbolo de estatalidade mais antigo da Anatólia.', fr: 'L\'aigle bicéphale — le point de rencontre du ciel et de la terre. Le plus ancien symbole d\'État de l\'Anatolie.', ja: '双頭のワシ——天と地の交わる点。アナトリア最古の国家の象徴。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Wakan Tanka\'nın (Büyük Ruh) habercisi. Tüy en kutsal hediye.', en: 'Messenger of Wakan Tanka (the Great Spirit). The feather is the most sacred gift.', de: 'Bote des Wakan Tanka (des Großen Geistes). Die Feder ist das heiligste Geschenk.', es: 'Mensajero de Wakan Tanka (el Gran Espíritu). La pluma es el regalo más sagrado.', pt: 'Mensageiro de Wakan Tanka (o Grande Espírito). A pena é o presente mais sagrado.', fr: 'Messager de Wakan Tanka (le Grand Esprit). La plume est le présent le plus sacré.', ja: 'ワカン・タンカ（偉大なる霊）の使者。羽は最も神聖な贈り物。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Aziz Yuhanna\'nın sembolü. Diriliş ve ilahi vahiy.', en: 'Symbol of Saint John. Resurrection and divine revelation.', de: 'Symbol des heiligen Johannes. Auferstehung und göttliche Offenbarung.', es: 'Símbolo de San Juan. Resurrección y revelación divina.', pt: 'Símbolo de São João. Ressurreição e revelação divina.', fr: 'Symbole de saint Jean. Résurrection et révélation divine.', ja: '聖ヨハネの象徴。復活と神の啓示。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Garuda — Vishnu\'nun bineği. Yılan-bilgisini taşıyan ruhsal güç.', en: 'Garuda — Vishnu\'s mount. The spiritual force bearing serpent-wisdom.', de: 'Garuda — Vishnus Reittier. Die spirituelle Kraft, die das Schlangen-Wissen trägt.', es: 'Garuda — la montura de Vishnú. La fuerza espiritual portadora de la sabiduría-serpiente.', pt: 'Garuda — a montaria de Vishnu. A força espiritual que carrega a sabedoria-serpente.', fr: 'Garuda — la monture de Vishnou. La force spirituelle portant la sagesse-serpent.', ja: 'ガルダ——ヴィシュヌの乗り物。蛇の知恵を担う霊的な力。' } },
    ],
    myths: [
      { tr: 'Prometheus: Tanrılardan ateşi çalan Prometheus\'u her gün kartal yer. Burada kartal — ego cezalandırıcı, ama aynı zamanda yenilenme döngüsünün taşıyıcısı.', en: 'Prometheus: The eagle daily devours Prometheus, who stole fire from the gods. Here the eagle is the ego-punisher, yet also the bearer of the cycle of renewal.', de: 'Prometheus: Der Adler frisst täglich Prometheus, der den Göttern das Feuer stahl. Hier ist der Adler der Ego-Bestrafer, doch zugleich der Träger des Erneuerungskreislaufs.', es: 'Prometeo: El águila devora cada día a Prometeo, que robó el fuego a los dioses. Aquí el águila es el castigador del ego, pero también el portador del ciclo de renovación.', pt: 'Prometeu: A águia devora todos os dias Prometeu, que roubou o fogo aos deuses. Aqui a águia é a punidora do ego, mas também a portadora do ciclo de renovação.', fr: 'Prométhée : L\'aigle dévore chaque jour Prométhée, qui déroba le feu aux dieux. Ici l\'aigle est le punisseur de l\'ego, mais aussi le porteur du cycle de renouveau.', ja: 'プロメテウス：神々から火を盗んだプロメテウスを、ワシは毎日喰らう。ここでワシは自我を罰する者であり、同時に再生の循環の担い手でもある。' },
      { tr: 'Hitit Çifte Kartalı: Selçuklu\'dan modern Türk devletine kadar — iki yöne bakan tek kartal. Geçmiş ve gelecek.', en: 'The Hittite Double Eagle: From the Seljuks to the modern Turkish state — a single eagle gazing in two directions. Past and future.', de: 'Der hethitische Doppeladler: Von den Seldschuken bis zum modernen türkischen Staat — ein einziger Adler, der in zwei Richtungen blickt. Vergangenheit und Zukunft.', es: 'El águila bicéfala hitita: Desde los selyúcidas hasta el Estado turco moderno — una sola águila que mira en dos direcciones. Pasado y futuro.', pt: 'A águia bicéfala hitita: Dos seljúcidas ao Estado turco moderno — uma só águia que olha em duas direções. Passado e futuro.', fr: 'L\'aigle bicéphale hittite : Des Seldjoukides à l\'État turc moderne — un seul aigle regardant dans deux directions. Passé et futur.', ja: 'ヒッタイトの双頭のワシ：セルジューク朝から近代トルコ国家まで——二つの方向を見つめる一羽のワシ。過去と未来。' },
    ],
  },

  // ─── a003 At ────────────────────────────────────────────────────────────
  a003: {
    jung: { tr: '"Yaşam Gücü/Libido" arketipi. At, içsel enerjinin sembolüdür — eyerlenmiş hâli irade, vahşi hâli içgüdü. Animanın bineği.', en: 'The "Life Force/Libido" archetype. The horse symbolizes inner energy — saddled it is will, wild it is instinct. The Anima\'s mount.', de: 'Der Archetyp "Lebenskraft/Libido". Das Pferd symbolisiert die innere Energie — gesattelt ist es Wille, wild ist es Instinkt. Das Reittier der Anima.', es: 'El arquetipo de la "Fuerza Vital/Libido". El caballo simboliza la energía interior — ensillado es voluntad, salvaje es instinto. La montura del Ánima.', pt: 'O arquétipo da "Força Vital/Libido". O cavalo simboliza a energia interior — selado é vontade, selvagem é instinto. A montaria da Anima.', fr: 'L\'archétype de la "Force Vitale/Libido". Le cheval symbolise l\'énergie intérieure — sellé il est volonté, sauvage il est instinct. La monture de l\'Anima.', ja: '「生命力／リビドー」の元型。馬は内なるエネルギーの象徴——鞍をつければ意志、野生のままなら本能。アニマの乗り物。' },
    dream: { tr: 'Rüyada at — özgürlük çağrısı. Beyaz at: yükselen ruhsallık. Siyah at: bastırılmış arzu. At dizginsizse: hayatın seni sürüklüyor.', en: 'A horse in dream — a call to freedom. White horse: rising spirituality. Black horse: repressed desire. If the horse is unbridled: life is dragging you along.', de: 'Ein Pferd im Traum — ein Ruf zur Freiheit. Weißes Pferd: aufsteigende Spiritualität. Schwarzes Pferd: unterdrücktes Verlangen. Ist das Pferd zügellos: Das Leben reißt dich mit.', es: 'Un caballo en sueños — una llamada a la libertad. Caballo blanco: espiritualidad en ascenso. Caballo negro: deseo reprimido. Si el caballo va sin freno: la vida te arrastra.', pt: 'Um cavalo em sonho — um chamado à liberdade. Cavalo branco: espiritualidade em ascensão. Cavalo negro: desejo reprimido. Se o cavalo está desenfreado: a vida arrasta-te.', fr: 'Un cheval en rêve — un appel à la liberté. Cheval blanc : spiritualité ascendante. Cheval noir : désir refoulé. Si le cheval est débridé : la vie t\'entraîne.', ja: '夢の中の馬——自由への呼びかけ。白い馬は高まる霊性。黒い馬は抑圧された欲望。手綱なき馬なら、人生があなたを引きずっている。' },
    shadow: { tr: 'Kontrolsüz tutku. Atın gemini bırakmak — disiplinsiz tutkuyla harcanan ömür. Ya da: hep eyerli kalmak, asla koşamamak.', en: 'Uncontrolled passion. To let go of the reins — a life spent on undisciplined passion. Or: always staying saddled, never being able to run.', de: 'Unkontrollierte Leidenschaft. Die Zügel loszulassen — ein Leben, verschwendet an undisziplinierte Leidenschaft. Oder: stets gesattelt zu bleiben, niemals laufen zu können.', es: 'Pasión descontrolada. Soltar las riendas — una vida malgastada en pasión sin disciplina. O bien: permanecer siempre ensillado, sin poder correr nunca.', pt: 'Paixão descontrolada. Largar as rédeas — uma vida gasta em paixão sem disciplina. Ou então: permanecer sempre selado, sem nunca poder correr.', fr: 'Passion incontrôlée. Lâcher les rênes — une vie gaspillée en passion indisciplinée. Ou : rester toujours sellé, sans jamais pouvoir courir.', ja: '制御なき情熱。手綱を放すこと——節度なき情熱に費やされる生涯。あるいは、常に鞍をつけたまま、決して走れぬこと。' },
    whenAppears: { tr: 'Bir yola çıkma anında, büyük göç/seyahat öncesi, içsel bir tutkunun uyanışında, özgürleşme zamanı.', en: 'At the moment of setting out, before a great migration or journey, at the awakening of an inner passion, in time of liberation.', de: 'Im Moment des Aufbruchs, vor einer großen Wanderung oder Reise, beim Erwachen einer inneren Leidenschaft, in der Zeit der Befreiung.', es: 'En el momento de partir, antes de una gran migración o viaje, en el despertar de una pasión interior, en tiempo de liberación.', pt: 'No momento de partir, antes de uma grande migração ou viagem, no despertar de uma paixão interior, em tempo de libertação.', fr: 'Au moment de partir, avant une grande migration ou un voyage, à l\'éveil d\'une passion intérieure, en temps de libération.', ja: '旅立ちの瞬間、大いなる移動や旅の前、内なる情熱の目覚めのとき、解放の時に。' },
    traditions: [
      { culture: { tr: 'Türk Mitolojisi', en: 'Turkic Mythology', de: 'Türkische Mythologie', es: 'Mitología Túrquica', pt: 'Mitologia Túrquica', fr: 'Mythologie Turque', ja: 'テュルク神話' }, meaning: { tr: 'At "yiğidin kanadı" — Dede Korkut destanlarında ayrılmaz yoldaş. Tulpar — uçan kanatlı at, Tanrı bineği.', en: 'The horse is "the hero\'s wing" — the inseparable companion in the Dede Korkut epics. Tulpar — the flying winged horse, the divine mount.', de: 'Das Pferd ist "der Flügel des Helden" — der unzertrennliche Gefährte in den Dede-Korkut-Epen. Tulpar — das fliegende geflügelte Pferd, das göttliche Reittier.', es: 'El caballo es "el ala del héroe" — el compañero inseparable en las epopeyas de Dede Korkut. Tulpar — el caballo alado volador, la montura divina.', pt: 'O cavalo é "a asa do herói" — o companheiro inseparável nas epopeias de Dede Korkut. Tulpar — o cavalo alado voador, a montaria divina.', fr: 'Le cheval est "l\'aile du héros" — le compagnon inséparable dans les épopées de Dede Korkut. Tulpar — le cheval ailé volant, la monture divine.', ja: '馬は「勇者の翼」——デデ・コルクト叙事詩における離れがたき相棒。トゥルパル——空飛ぶ翼ある馬、神の乗り物。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Pegasus — Medusa\'nın kanından doğan kanatlı at. İlham perilerinin bineği. Şair-savaşçı sembolü.', en: 'Pegasus — the winged horse born of Medusa\'s blood. Mount of the Muses. Symbol of the poet-warrior.', de: 'Pegasus — das geflügelte Pferd, geboren aus Medusas Blut. Reittier der Musen. Symbol des Dichter-Kriegers.', es: 'Pegaso — el caballo alado nacido de la sangre de Medusa. Montura de las Musas. Símbolo del poeta-guerrero.', pt: 'Pégaso — o cavalo alado nascido do sangue de Medusa. Montaria das Musas. Símbolo do poeta-guerreiro.', fr: 'Pégase — le cheval ailé né du sang de Méduse. Monture des Muses. Symbole du poète-guerrier.', ja: 'ペガサス——メデューサの血から生まれた翼ある馬。ムーサたちの乗り物。詩人にして戦士の象徴。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Epona — at tanrıçası. Ölülerin ruhlarını öteye taşıyan rehber.', en: 'Epona — the horse goddess. The guide who carries the souls of the dead to the beyond.', de: 'Epona — die Pferdegöttin. Die Führerin, die die Seelen der Toten ins Jenseits geleitet.', es: 'Epona — la diosa caballo. La guía que lleva las almas de los muertos al más allá.', pt: 'Epona — a deusa cavalo. A guia que leva as almas dos mortos para o além.', fr: 'Épona — la déesse-cheval. Le guide qui mène les âmes des morts vers l\'au-delà.', ja: 'エポナ——馬の女神。死者の魂を彼岸へと導く案内者。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Ashvamedha — at kurbanı kralın kozmik egemenliği için. Vishnu\'nun Kalki avatarı beyaz at üstündedir.', en: 'Ashvamedha — the horse sacrifice for the king\'s cosmic sovereignty. Vishnu\'s Kalki avatar rides a white horse.', de: 'Ashvamedha — das Pferdeopfer für die kosmische Souveränität des Königs. Vishnus Kalki-Avatar reitet ein weißes Pferd.', es: 'Ashvamedha — el sacrificio del caballo por la soberanía cósmica del rey. El avatar Kalki de Vishnú monta un caballo blanco.', pt: 'Ashvamedha — o sacrifício do cavalo pela soberania cósmica do rei. O avatar Kalki de Vishnu monta um cavalo branco.', fr: 'Ashvamedha — le sacrifice du cheval pour la souveraineté cosmique du roi. L\'avatar Kalki de Vishnou monte un cheval blanc.', ja: 'アシュヴァメーダ——王の宇宙的支配のための馬の供犠。ヴィシュヌのカルキ・アヴァターラは白い馬に乗る。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Vahiy kitabında dört atlı — fetih, savaş, kıtlık, ölüm. Apokaliptik haberci.', en: 'The four horsemen of Revelation — conquest, war, famine, death. Apocalyptic messengers.', de: 'Die vier Reiter der Offenbarung — Eroberung, Krieg, Hungersnot, Tod. Apokalyptische Boten.', es: 'Los cuatro jinetes del Apocalipsis — conquista, guerra, hambre, muerte. Mensajeros apocalípticos.', pt: 'Os quatro cavaleiros do Apocalipse — conquista, guerra, fome, morte. Mensageiros apocalípticos.', fr: 'Les quatre cavaliers de l\'Apocalypse — conquête, guerre, famine, mort. Messagers apocalyptiques.', ja: '黙示録の四騎士——征服、戦争、飢饉、死。黙示録の使者たち。' } },
    ],
    myths: [
      { tr: 'Pegasus ve Bellerophon: Bellerophon kanatlı Pegasus\'u ehlileştirir, Khimera canavarını öldürür. Ama Olympos\'a çıkmaya kalkınca Zeus onu düşürür — kibrin cezası.', en: 'Pegasus and Bellerophon: Bellerophon tames the winged Pegasus and slays the Chimera. But when he tries to ascend to Olympus, Zeus throws him down — the punishment of hubris.', de: 'Pegasus und Bellerophon: Bellerophon zähmt den geflügelten Pegasus und tötet die Chimäre. Doch als er zum Olymp aufsteigen will, stürzt Zeus ihn herab — die Strafe der Hybris.', es: 'Pegaso y Belerofonte: Belerofonte doma al alado Pegaso y mata a la Quimera. Pero cuando intenta ascender al Olimpo, Zeus lo derriba — el castigo de la soberbia.', pt: 'Pégaso e Belerofonte: Belerofonte doma o alado Pégaso e mata a Quimera. Mas quando tenta subir ao Olimpo, Zeus derruba-o — o castigo da soberba.', fr: 'Pégase et Bellérophon : Bellérophon dompte le Pégase ailé et tue la Chimère. Mais lorsqu\'il tente de monter à l\'Olympe, Zeus le précipite — le châtiment de l\'orgueil.', ja: 'ペガサスとベレロポーン：ベレロポーンは翼あるペガサスを馴らし、怪物キマイラを討つ。だがオリュンポスへ昇ろうとしたとき、ゼウスは彼を落とす——傲慢の罰。' },
      { tr: 'Dede Korkut\'ta At: "Yiğidin başı omuzun üstünde, yiğidin atı yanı başında." Anadolu kahramanı ile atı arasındaki kardeşlik.', en: 'The Horse in Dede Korkut: "The hero\'s head upon his shoulders, the hero\'s horse at his side." The brotherhood between the Anatolian hero and his horse.', de: 'Das Pferd bei Dede Korkut: "Der Kopf des Helden auf seinen Schultern, das Pferd des Helden an seiner Seite." Die Bruderschaft zwischen dem anatolischen Helden und seinem Pferd.', es: 'El caballo en Dede Korkut: "La cabeza del héroe sobre sus hombros, el caballo del héroe a su lado." La hermandad entre el héroe anatolio y su caballo.', pt: 'O cavalo em Dede Korkut: "A cabeça do herói sobre os seus ombros, o cavalo do herói a seu lado." A irmandade entre o herói anatólio e o seu cavalo.', fr: 'Le cheval dans Dede Korkut : "La tête du héros sur ses épaules, le cheval du héros à ses côtés." La fraternité entre le héros anatolien et son cheval.', ja: 'デデ・コルクトの馬：「勇者の頭は肩の上に、勇者の馬はその傍らに。」アナトリアの英雄とその馬との兄弟の絆。' },
    ],
  },

  // ─── a004 Turna ─────────────────────────────────────────────────────────
  a004: {
    jung: { tr: '"Sadık Hac Yolcusu" arketipi. Turna, döngüsel uzun yolculuğun, kararlılığın ve sadakatin sembolü. Aşk için göç eden kalp.', en: 'The "Faithful Pilgrim" archetype. The crane is a symbol of the cyclical long journey, determination, and loyalty. The heart that migrates for love.', de: 'Der Archetyp des "treuen Pilgers". Der Kranich ist ein Symbol der zyklischen langen Reise, der Entschlossenheit und der Treue. Das Herz, das aus Liebe wandert.', es: 'El arquetipo del "Peregrino Fiel". La grulla es símbolo del largo viaje cíclico, la determinación y la lealtad. El corazón que migra por amor.', pt: 'O arquétipo do "Peregrino Fiel". A grou é símbolo da longa viagem cíclica, da determinação e da lealdade. O coração que migra por amor.', fr: 'L\'archétype du "Pèlerin fidèle". La grue est un symbole du long voyage cyclique, de la détermination et de la loyauté. Le cœur qui migre par amour.', ja: '「忠実な巡礼者」の元型。ツルは、巡る長い旅、不屈、そして忠誠の象徴。愛のために渡る心。' },
    dream: { tr: 'Turna rüyada — uzun bekleyişlerin meyvesinin yaklaştığını söyler. Sürü hâlinde uçuyorsa: dostluk/topluluk bir şey kuruyor. Yalnızsa: sevdiğine yöneliş.', en: 'A crane in dream — tells you the fruit of long waiting is near. Flying in a flock: friendship/community is building something. Alone: turning toward your beloved.', de: 'Ein Kranich im Traum — sagt dir, dass die Frucht langen Wartens nahe ist. Fliegt er im Schwarm: Freundschaft/Gemeinschaft baut etwas auf. Allein: Hinwendung zu deiner Geliebten.', es: 'Una grulla en sueños — te dice que el fruto de la larga espera está cerca. Si vuela en bandada: la amistad/comunidad está construyendo algo. Sola: vuelta hacia tu amado.', pt: 'Uma grou em sonho — diz-te que o fruto da longa espera está perto. Se voa em bando: a amizade/comunidade está a construir algo. Sozinha: voltar-te para o teu amado.', fr: 'Une grue en rêve — te dit que le fruit d\'une longue attente est proche. Volant en nuée : l\'amitié/la communauté bâtit quelque chose. Seule : un retour vers ton bien-aimé.', ja: '夢の中のツル——長き待ちの実りが近いと告げる。群れで飛ぶなら、友情や共同体が何かを築いている。一羽なら、愛する者への向き直り。' },
    shadow: { tr: 'Bir ümitle ömür boyu beklemek. Turna döngüsü kararlılık olabilir, ama gerçeklikten kaçışsa — donmuş hayat.', en: 'Waiting a lifetime on a single hope. The crane\'s cycle may be determination, but if it is flight from reality — a frozen life.', de: 'Ein Leben lang auf eine einzige Hoffnung warten. Der Kreislauf des Kranichs mag Entschlossenheit sein, doch ist er Flucht vor der Wirklichkeit — ein erstarrtes Leben.', es: 'Esperar toda una vida sobre una sola esperanza. El ciclo de la grulla puede ser determinación, pero si es huida de la realidad — una vida congelada.', pt: 'Esperar uma vida inteira sobre uma única esperança. O ciclo da grou pode ser determinação, mas se for fuga à realidade — uma vida congelada.', fr: 'Attendre toute une vie sur un seul espoir. Le cycle de la grue peut être détermination, mais s\'il est fuite devant la réalité — une vie figée.', ja: 'ただ一つの望みを抱いて生涯を待ち続けること。ツルの循環は不屈でありうるが、現実からの逃避であれば——凍りついた人生。' },
    whenAppears: { tr: 'Uzun ayrılık sonrası kavuşmada, evlilik/sözleşme öncesinde, sabırla beklenmiş bir habere yakın.', en: 'At a reunion after long separation, before marriage or covenant, near news patiently awaited.', de: 'Bei einem Wiedersehen nach langer Trennung, vor Heirat oder Bund, nahe einer geduldig erwarteten Nachricht.', es: 'En un reencuentro tras larga separación, antes del matrimonio o pacto, cerca de una noticia esperada con paciencia.', pt: 'Num reencontro após longa separação, antes do casamento ou aliança, perto de uma notícia esperada com paciência.', fr: 'Lors de retrouvailles après une longue séparation, avant le mariage ou l\'alliance, à l\'approche d\'une nouvelle patiemment attendue.', ja: '長い別れののちの再会のとき、結婚や誓いの前、辛抱強く待った報せの近づくとき。' },
    traditions: [
      { culture: { tr: 'Alevi-Bektaşi', en: 'Alevi-Bektashi', de: 'Alevitisch-Bektaschi', es: 'Aleví-Bektashi', pt: 'Alevi-Bektashi', fr: 'Alévi-Bektachi', ja: 'アレヴィー・ベクタシ' }, meaning: { tr: 'Hz. Ali\'nin kutsal kuşu. Semah\'ta turna duruşu — kanatların aşk için açılışı. Cemde rehber kuş.', en: 'The sacred bird of Imam Ali. The crane posture in the Semah — wings opening for love. The guide-bird of the cem ceremony.', de: 'Der heilige Vogel des Imam Ali. Die Kranichhaltung im Semah — das Öffnen der Flügel für die Liebe. Der Führungsvogel der Cem-Zeremonie.', es: 'El ave sagrada del Imán Alí. La postura de la grulla en el Semah — las alas abriéndose por amor. El ave guía de la ceremonia cem.', pt: 'A ave sagrada do Imã Ali. A postura da grou no Semah — as asas abrindo-se por amor. A ave guia da cerimónia cem.', fr: 'L\'oiseau sacré de l\'imam Ali. La posture de la grue dans le Semah — les ailes s\'ouvrant pour l\'amour. L\'oiseau guide de la cérémonie cem.', ja: 'イマーム・アリーの聖なる鳥。セマーにおけるツルの姿勢——愛のために翼を開くこと。ジェム儀礼の導きの鳥。' } },
      { culture: { tr: 'Türk Halk', en: 'Turkish Folk', de: 'Türkische Volkskultur', es: 'Folclore Turco', pt: 'Folclore Turco', fr: 'Folklore Turc', ja: 'トルコ民俗' }, meaning: { tr: '"Turnalar geldi" ezgisi — sevdiğine haber, gurbet kavuşması. Anadolu\'nun en içli kuşu.', en: 'The "Cranes have come" song — news to the beloved, reunion from exile. Anatolia\'s most soulful bird.', de: 'Das Lied "Die Kraniche sind gekommen" — Botschaft an die Geliebte, Wiedersehen aus der Fremde. Anatoliens gefühlvollster Vogel.', es: 'La canción "Han llegado las grullas" — noticia al amado, reencuentro tras el exilio. El ave más sentida de Anatolia.', pt: 'A canção "As grous chegaram" — notícia ao amado, reencontro após o exílio. A ave mais sentida da Anatólia.', fr: 'La chanson "Les grues sont venues" — nouvelle à l\'aimé, retrouvailles après l\'exil. L\'oiseau le plus émouvant de l\'Anatolie.', ja: '「ツルが来た」の調べ——愛する者への報せ、異郷からの再会。アナトリアで最も情のこもった鳥。' } },
      { culture: { tr: 'Japonya', en: 'Japanese', de: 'Japanisch', es: 'Japonés', pt: 'Japonês', fr: 'Japonais', ja: '日本' }, meaning: { tr: 'Tsuru — 1000 yıl yaşar, uzun ömür sembolü. 1000 turna katlamak (senbazuru) — bir dileğin kabulü.', en: 'Tsuru — lives 1,000 years, symbol of longevity. Folding 1,000 cranes (senbazuru) — the granting of a wish.', de: 'Tsuru — lebt 1.000 Jahre, Symbol der Langlebigkeit. 1.000 Kraniche zu falten (Senbazuru) — die Erfüllung eines Wunsches.', es: 'Tsuru — vive 1000 años, símbolo de longevidad. Plegar 1000 grullas (senbazuru) — la concesión de un deseo.', pt: 'Tsuru — vive 1000 anos, símbolo de longevidade. Dobrar 1000 grous (senbazuru) — a concretização de um desejo.', fr: 'Tsuru — vit 1 000 ans, symbole de longévité. Plier 1 000 grues (senbazuru) — l\'exaucement d\'un vœu.', ja: '鶴（つる）——千年生きる、長寿の象徴。千羽鶴を折ること（千羽鶴）——願いの成就。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Taoist ölümsüzlerin bineği. Erdem ve bilgelik sembolü.', en: 'Mount of the Taoist immortals. Symbol of virtue and wisdom.', de: 'Reittier der taoistischen Unsterblichen. Symbol der Tugend und Weisheit.', es: 'Montura de los inmortales taoístas. Símbolo de la virtud y la sabiduría.', pt: 'Montaria dos imortais taoistas. Símbolo da virtude e da sabedoria.', fr: 'Monture des immortels taoïstes. Symbole de la vertu et de la sagesse.', ja: '道教の仙人の乗り物。徳と知恵の象徴。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Hermes\'in alfabesi turnaların uçuş dizilişinden. Yazının habercisi.', en: 'Hermes\'s alphabet came from the flight formations of cranes. Herald of writing.', de: 'Das Alphabet des Hermes entstand aus den Flugformationen der Kraniche. Herold der Schrift.', es: 'El alfabeto de Hermes nació de las formaciones de vuelo de las grullas. Heraldo de la escritura.', pt: 'O alfabeto de Hermes nasceu das formações de voo das grous. Arauto da escrita.', fr: 'L\'alphabet d\'Hermès naquit des formations de vol des grues. Héraut de l\'écriture.', ja: 'ヘルメスの文字はツルの飛行の隊列から生まれた。文字の使者。' } },
    ],
    myths: [
      { tr: 'Pir Sultan ve Turnalar: "Yürü bre Hızır Paşa / Senin de çarkın kırılır" — Anadolu\'da turnalar Pir Sultan\'a haber taşıyan, sözü ileten kuşlar.', en: 'Pir Sultan and the Cranes: "Go forth, Hızır Pasha / Your wheel too shall break" — in Anatolia, cranes are the birds that bear news and carry the word to Pir Sultan.', de: 'Pir Sultan und die Kraniche: "Geh nur, Hızır Pascha / Auch dein Rad wird brechen" — in Anatolien sind Kraniche die Vögel, die Pir Sultan Nachrichten überbringen und das Wort weitertragen.', es: 'Pir Sultan y las grullas: "Anda, Hızır Pachá / También tu rueda se romperá" — en Anatolia, las grullas son las aves que llevan noticias y transmiten la palabra a Pir Sultan.', pt: 'Pir Sultan e as grous: "Vai lá, Hızır Pachá / Também a tua roda se quebrará" — na Anatólia, as grous são as aves que levam notícias e transmitem a palavra a Pir Sultan.', fr: 'Pir Sultan et les grues : "Va donc, Hızır Pacha / Ta roue aussi se brisera" — en Anatolie, les grues sont les oiseaux qui portent les nouvelles et transmettent la parole à Pir Sultan.', ja: 'ピール・スルタンとツル：「行くがいい、フズル・パシャ／お前の車輪もまた砕けよう」——アナトリアでは、ツルはピール・スルタンに報せを運び、言葉を伝える鳥。' },
      { tr: 'Senbazuru: Hiroshima\'da bombadan etkilenen Sadako adlı kız iyileşmek için 1000 turna katlamaya başlar. Hikayesi dünyada barış sembolü olur.', en: 'Senbazuru: Sadako, a girl affected by the Hiroshima bombing, begins folding 1,000 cranes to heal. Her story becomes a worldwide symbol of peace.', de: 'Senbazuru: Sadako, ein vom Atombombenabwurf auf Hiroshima betroffenes Mädchen, beginnt 1.000 Kraniche zu falten, um zu genesen. Ihre Geschichte wird zu einem weltweiten Symbol des Friedens.', es: 'Senbazuru: Sadako, una niña afectada por la bomba de Hiroshima, comienza a plegar 1000 grullas para sanar. Su historia se convierte en un símbolo mundial de paz.', pt: 'Senbazuru: Sadako, uma menina afetada pela bomba de Hiroshima, começa a dobrar 1000 grous para sarar. A sua história torna-se um símbolo mundial de paz.', fr: 'Senbazuru : Sadako, une fillette touchée par la bombe d\'Hiroshima, se met à plier 1 000 grues pour guérir. Son histoire devient un symbole mondial de paix.', ja: '千羽鶴：広島の原爆の影響を受けた禎子という少女が、癒えるために千羽の鶴を折りはじめる。その物語は世界の平和の象徴となる。' },
    ],
  },

  // ─── a005 Hüma Kuşu ─────────────────────────────────────────────────────
  a005: {
    jung: { tr: '"Kutsal Kader" arketipi. Hüma, kişiyi seçen ilahi mukadderatın sembolü — gölgesi başına düşene saltanat veren mitik kuş.', en: 'The "Sacred Destiny" archetype. Huma is the symbol of divine fate that chooses a person — the mythic bird that bestows sovereignty upon whoever its shadow falls on.', de: 'Der Archetyp des "heiligen Schicksals". Huma ist das Symbol des göttlichen Schicksals, das einen Menschen erwählt — der mythische Vogel, der demjenigen die Herrschaft verleiht, auf den sein Schatten fällt.', es: 'El arquetipo del "Destino Sagrado". Huma es el símbolo del destino divino que elige a una persona — el ave mítica que otorga la soberanía a aquel sobre quien cae su sombra.', pt: 'O arquétipo do "Destino Sagrado". Huma é o símbolo do destino divino que escolhe uma pessoa — a ave mítica que concede a soberania àquele sobre quem cai a sua sombra.', fr: 'L\'archétype du "Destin sacré". Huma est le symbole du destin divin qui choisit une personne — l\'oiseau mythique qui confère la souveraineté à celui sur qui tombe son ombre.', ja: '「聖なる運命」の元型。フマーは、人を選ぶ神の定めの象徴——その影が落ちた者に王権を授ける神話の鳥。' },
    dream: { tr: 'Hüma rüyada — bir lütfun, beklenmedik bir nimetin yaklaştığını söyler. Üstüne konuyorsa: kaderin sana yöneliyor. Yüksekten geçiyorsa: izle, takip et.', en: 'Huma in dream — tells you a grace, an unexpected blessing, is near. If it lands on you: destiny turns toward you. If it passes overhead: watch, follow.', de: 'Huma im Traum — sagt dir, dass eine Gnade, ein unerwarteter Segen nahe ist. Landet er auf dir: Das Schicksal wendet sich dir zu. Zieht er über dir vorbei: beobachte, folge.', es: 'Huma en sueños — te dice que una gracia, una bendición inesperada, está cerca. Si se posa sobre ti: el destino se vuelve hacia ti. Si pasa por encima: observa, sigue.', pt: 'Huma em sonho — diz-te que uma graça, uma bênção inesperada, está perto. Se pousa em ti: o destino volta-se para ti. Se passa por cima: observa, segue.', fr: 'Huma en rêve — te dit qu\'une grâce, une bénédiction inattendue, est proche. S\'il se pose sur toi : le destin se tourne vers toi. S\'il passe au-dessus : observe, suis-le.', ja: '夢の中のフマー——恵み、思いがけぬ祝福が近いと告げる。あなたに止まるなら、運命があなたへ向き直る。頭上を過ぎるなら、見つめ、追え。' },
    shadow: { tr: 'Kaderi beklemek için hareket etmemek. "Hüma kuşum nerede?" diye oturup hayatı kaçırmak. Mistik bir bahane.', en: 'Not acting while waiting for fate. Sitting and asking "Where is my Huma?" while missing life. A mystical excuse.', de: 'Nicht zu handeln, während man auf das Schicksal wartet. Dazusitzen und zu fragen "Wo ist mein Huma?", während man das Leben verpasst. Eine mystische Ausrede.', es: 'No actuar mientras se espera al destino. Sentarse a preguntar "¿Dónde está mi Huma?" mientras se pierde la vida. Una excusa mística.', pt: 'Não agir enquanto se espera o destino. Sentar-se a perguntar "Onde está o meu Huma?" enquanto se perde a vida. Uma desculpa mística.', fr: 'Ne pas agir en attendant le destin. Rester assis à demander "Où est mon Huma ?" tout en passant à côté de la vie. Une excuse mystique.', ja: '運命を待つあまり動かぬこと。「私のフマーはどこに?」と座り込み、人生を取り逃がすこと。神秘めいた言い訳。' },
    whenAppears: { tr: 'Beklenmedik bir fırsat çıkmadan önce, hak ettiğin tanınma anında, kader anlarında.', en: 'Before an unexpected opportunity arises, at the moment of the recognition you deserve, in moments of destiny.', de: 'Bevor eine unerwartete Gelegenheit entsteht, im Moment der Anerkennung, die du verdienst, in Schicksalsmomenten.', es: 'Antes de que surja una oportunidad inesperada, en el momento del reconocimiento que mereces, en momentos de destino.', pt: 'Antes de surgir uma oportunidade inesperada, no momento do reconhecimento que mereces, em momentos de destino.', fr: 'Avant qu\'une occasion inattendue ne surgisse, au moment de la reconnaissance que tu mérites, dans les moments de destin.', ja: '思いがけぬ好機が訪れる前、あなたが値する評価を受ける瞬間、運命の刻に。' },
    traditions: [
      { culture: { tr: 'Pers/İran', en: 'Persian/Iranian', de: 'Persisch/Iranisch', es: 'Persa/Iraní', pt: 'Persa/Iraniano', fr: 'Perse/Iranien', ja: 'ペルシア／イラン' }, meaning: { tr: 'Hümay-i Saadet — saadet kuşu. Asla yere konmaz, hep havadadır. Gölgesi başa düşene padişahlık nasip olur.', en: 'Humay-i Saadet — the bird of felicity. Never lands, ever airborne. Whoever its shadow falls upon is destined for kingship.', de: 'Humay-i Saadet — der Vogel der Glückseligkeit. Landet nie, ist stets in der Luft. Wem sein Schatten aufs Haupt fällt, dem ist das Königtum bestimmt.', es: 'Humay-i Saadet — el ave de la felicidad. Nunca se posa, siempre en el aire. Aquel sobre cuya cabeza cae su sombra está destinado a la realeza.', pt: 'Humay-i Saadet — a ave da felicidade. Nunca pousa, sempre no ar. Aquele sobre cuja cabeça cai a sua sombra está destinado à realeza.', fr: 'Humay-i Saadet — l\'oiseau de la félicité. Ne se pose jamais, toujours en vol. Celui sur la tête duquel tombe son ombre est destiné à la royauté.', ja: 'フマーイ・サアーダト——至福の鳥。決して地に降りず、常に空にある。その影が頭上に落ちた者は王権を授かる定め。' } },
      { culture: { tr: 'Türk-İslam', en: 'Turco-Islamic', de: 'Türkisch-Islamisch', es: 'Turco-Islámico', pt: 'Turco-Islâmico', fr: 'Turco-Islamique', ja: 'トルコ・イスラーム' }, meaning: { tr: 'Osmanlı sarayında "Hüma" bahtın simgesi. Tahta çıkacak şehzadeyi belirleyen kutsal kuş.', en: 'In the Ottoman court, Huma was the symbol of fortune. The sacred bird that designated which prince would ascend the throne.', de: 'Am osmanischen Hof war Huma das Symbol des Glücks. Der heilige Vogel, der bestimmte, welcher Prinz den Thron besteigen würde.', es: 'En la corte otomana, Huma era el símbolo de la fortuna. El ave sagrada que designaba qué príncipe ascendería al trono.', pt: 'Na corte otomana, Huma era o símbolo da fortuna. A ave sagrada que designava qual príncipe subiria ao trono.', fr: 'À la cour ottomane, Huma était le symbole de la fortune. L\'oiseau sacré qui désignait quel prince monterait sur le trône.', ja: 'オスマン宮廷において、フマーは幸運の象徴。どの皇子が玉座に就くかを定める聖なる鳥。' } },
      { culture: { tr: 'Sufi', en: 'Sufi', de: 'Sufisch', es: 'Sufí', pt: 'Sufi', fr: 'Soufi', ja: 'スーフィー' }, meaning: { tr: 'Yüksekte uçar, asla durmaz — "tarikat-ı seyr" sembolü. Aşkın kuşu hep yolda.', en: 'Flies high, never stopping — the symbol of "the path of wayfaring". The bird of love is ever on the road.', de: 'Fliegt hoch, hält niemals an — das Symbol des "Pfads der Wanderung". Der Vogel der Liebe ist stets unterwegs.', es: 'Vuela alto, nunca se detiene — el símbolo del "camino del viandante". El ave del amor siempre está en camino.', pt: 'Voa alto, nunca para — o símbolo do "caminho do viandante". A ave do amor está sempre a caminho.', fr: 'Vole haut, ne s\'arrête jamais — le symbole de "la voie du cheminement". L\'oiseau de l\'amour est toujours en chemin.', ja: '高く飛び、決して止まらぬ——「遍歴の道」の象徴。愛の鳥は常に旅の途上にある。' } },
      { culture: { tr: 'Hint', en: 'Hindu', de: 'Hinduistisch', es: 'Hindú', pt: 'Hindu', fr: 'Hindou', ja: 'ヒンドゥー' }, meaning: { tr: 'Garuda\'nın akrabası — gökyüzü tanrılarının habercisi.', en: 'A kin of Garuda — herald of the sky gods.', de: 'Ein Verwandter Garudas — Herold der Himmelsgötter.', es: 'Pariente de Garuda — heraldo de los dioses del cielo.', pt: 'Parente de Garuda — arauto dos deuses do céu.', fr: 'Un parent de Garuda — héraut des dieux du ciel.', ja: 'ガルダの縁者——天空の神々の使者。' } },
      { culture: { tr: 'Anadolu Halk', en: 'Anatolian Folk', de: 'Anatolische Volkskultur', es: 'Folclore Anatolio', pt: 'Folclore Anatólio', fr: 'Folklore Anatolien', ja: 'アナトリア民俗' }, meaning: { tr: '"Hüma kuşunun gölgesi başına düşsün" duası — büyük kısmet temennisi.', en: '"May the shadow of the Huma fall upon you" — a blessing wishing great fortune.', de: '"Möge der Schatten des Huma auf dich fallen" — ein Segen, der großes Glück wünscht.', es: '"Que la sombra del Huma caiga sobre ti" — una bendición que desea gran fortuna.', pt: '"Que a sombra do Huma caia sobre ti" — uma bênção que deseja grande fortuna.', fr: '"Que l\'ombre du Huma tombe sur toi" — une bénédiction souhaitant une grande fortune.', ja: '「フマーの影があなたの頭上に落ちますように」という祈り——大いなる幸運を願う言葉。' } },
    ],
    myths: [
      { tr: 'Hüma ve Sultan: Anadolu efsanesinde tahta çıkacak şehzadeyi seçmek için Hüma kuşu salınır. Kimin başına gölgesi düşerse o sultan olur — kader önceden bellidir, ama kuşun seçimine güven gerekir.', en: 'Huma and the Sultan: In Anatolian legend, the Huma bird is released to choose which prince will ascend the throne. Whoever its shadow falls upon becomes sultan — destiny is foreordained, yet one must trust the bird\'s choice.', de: 'Huma und der Sultan: In anatolischer Legende lässt man den Huma-Vogel frei, um zu wählen, welcher Prinz den Thron besteigt. Wem sein Schatten aufs Haupt fällt, der wird Sultan — das Schicksal ist vorbestimmt, doch man muss der Wahl des Vogels vertrauen.', es: 'Huma y el Sultán: En la leyenda anatolia, se suelta al ave Huma para elegir qué príncipe ascenderá al trono. Aquel sobre quien cae su sombra se convierte en sultán — el destino está predestinado, pero hay que confiar en la elección del ave.', pt: 'Huma e o Sultão: Na lenda anatólia, solta-se a ave Huma para escolher qual príncipe subirá ao trono. Aquele sobre quem cai a sua sombra torna-se sultão — o destino está predestinado, mas é preciso confiar na escolha da ave.', fr: 'Huma et le Sultan : Dans la légende anatolienne, on libère l\'oiseau Huma pour choisir quel prince montera sur le trône. Celui sur qui tombe son ombre devient sultan — le destin est prédéterminé, mais il faut faire confiance au choix de l\'oiseau.', ja: 'フマーとスルタン：アナトリアの伝説では、どの皇子が玉座に就くかを選ぶためにフマーが放たれる。その影が頭上に落ちた者がスルタンとなる——運命はあらかじめ定められているが、鳥の選択を信じねばならない。' },
      { tr: 'Attar\'ın Hüması: "Mantık-üt Tayr"da Hüma ölümsüzlüğün ve göklerin kuşudur — Simurg\'a ulaşmaya çalışan otuz kuşun rehberlerinden.', en: 'Attar\'s Huma: In "The Conference of the Birds," Huma is the bird of immortality and the heavens — one of the guides for the thirty birds seeking the Simurgh.', de: 'Attars Huma: In "Die Konferenz der Vögel" ist Huma der Vogel der Unsterblichkeit und der Himmel — einer der Führer der dreißig Vögel, die den Simurgh suchen.', es: 'El Huma de Attar: En "La conferencia de los pájaros", Huma es el ave de la inmortalidad y de los cielos — uno de los guías de los treinta pájaros que buscan al Simurgh.', pt: 'O Huma de Attar: Em "A Conferência dos Pássaros", Huma é a ave da imortalidade e dos céus — um dos guias dos trinta pássaros que procuram o Simurgh.', fr: 'Le Huma d\'Attar : Dans "La Conférence des oiseaux", Huma est l\'oiseau de l\'immortalité et des cieux — l\'un des guides des trente oiseaux en quête du Simorgh.', ja: 'アッタールのフマー：『鳥の言葉』において、フマーは不死と天空の鳥——シームルグを求める三十羽の鳥たちの導き手の一つ。' },
    ],
  },

  // ─── a006 Anka ──────────────────────────────────────────────────────────
  a006: {
    jung: { tr: '"Ölüm-Diriliş" arketipi. En radikal dönüşüm sembolü. Eski benlik ölmeden yeni doğamaz — ateş hem yıkıcı hem yaratıcı.', en: 'The "Death-Rebirth" archetype. The most radical symbol of transformation. The new cannot be born until the old Self dies — fire is both destroyer and creator.', de: 'Der Archetyp "Tod-Wiedergeburt". Das radikalste Symbol der Verwandlung. Das Neue kann nicht geboren werden, ehe das alte Selbst stirbt — das Feuer ist Zerstörer und Schöpfer zugleich.', es: 'El arquetipo de "Muerte-Renacimiento". El símbolo más radical de la transformación. Lo nuevo no puede nacer hasta que el viejo Yo muere — el fuego es destructor y creador a la vez.', pt: 'O arquétipo de "Morte-Renascimento". O símbolo mais radical da transformação. O novo não pode nascer até que o velho Eu morra — o fogo é destruidor e criador ao mesmo tempo.', fr: 'L\'archétype "Mort-Renaissance". Le symbole le plus radical de la transformation. Le neuf ne peut naître avant que l\'ancien Soi ne meure — le feu est à la fois destructeur et créateur.', ja: '「死と再生」の元型。最も根源的な変容の象徴。古き自己が死なねば新しきは生まれない——火は破壊者であり創造者でもある。' },
    dream: { tr: 'Anka rüyada — bir döngünün sona ermesi gerekiyor. Yanıyorsa: dirilişin eşiğindesin. Küllerden çıkıyorsa: çoktan dönüştün, sadece bunu kabul et.', en: 'Phoenix in dream — a cycle must end. If it burns: you are on the threshold of resurrection. If it rises from ashes: you have already transformed, only accept it.', de: 'Phönix im Traum — ein Kreislauf muss enden. Brennt er: Du stehst an der Schwelle der Auferstehung. Erhebt er sich aus der Asche: Du hast dich bereits gewandelt, nimm es nur an.', es: 'Fénix en sueños — un ciclo debe terminar. Si arde: estás en el umbral de la resurrección. Si se alza de las cenizas: ya te has transformado, solo acéptalo.', pt: 'Fénix em sonho — um ciclo deve terminar. Se arde: estás no limiar da ressurreição. Se se ergue das cinzas: já te transformaste, apenas aceita-o.', fr: 'Phénix en rêve — un cycle doit s\'achever. S\'il brûle : tu es au seuil de la résurrection. S\'il renaît de ses cendres : tu t\'es déjà transformé, accepte-le seulement.', ja: '夢の中のフェニックス——一つの循環が終わらねばならない。燃えているなら、あなたは復活の境にある。灰から立ち上がるなら、あなたはすでに変容している。ただそれを受け入れよ。' },
    shadow: { tr: 'Sürekli kriz yaratma. "Kendini yakıp yeniden doğmak" bir yaşam biçimi olursa — stabilite kaybedilir. Drama bağımlılığı.', en: 'Constantly creating crisis. If "burning oneself and being reborn" becomes a way of life — stability is lost. Addiction to drama.', de: 'Ständig Krisen erzeugen. Wird "sich selbst zu verbrennen und wiedergeboren zu werden" zur Lebensweise — geht die Stabilität verloren. Sucht nach Dramatik.', es: 'Crear crisis constantemente. Si "quemarse y renacer" se vuelve una forma de vida — se pierde la estabilidad. Adicción al drama.', pt: 'Criar crises constantemente. Se "queimar-se e renascer" se torna um modo de vida — perde-se a estabilidade. Vício no drama.', fr: 'Créer sans cesse des crises. Si "se brûler et renaître" devient un mode de vie — la stabilité est perdue. Une dépendance au drame.', ja: '絶えず危機を作り出すこと。「自らを焼いて生まれ変わる」ことが生き方になれば——安定は失われる。劇的なものへの依存。' },
    whenAppears: { tr: 'Ciddi bir kayıp sonrası, mesleki çöküşte, kimlik krizinde, "bu kadar yeter" dediğin anda.', en: 'After a serious loss, in professional collapse, in identity crisis, at the moment you say "enough".', de: 'Nach einem schweren Verlust, im beruflichen Zusammenbruch, in der Identitätskrise, in dem Moment, in dem du "genug" sagst.', es: 'Tras una pérdida grave, en el colapso profesional, en crisis de identidad, en el momento en que dices "basta".', pt: 'Após uma perda grave, no colapso profissional, em crise de identidade, no momento em que dizes "basta".', fr: 'Après une perte grave, dans l\'effondrement professionnel, en crise d\'identité, à l\'instant où tu dis "assez".', ja: '深刻な喪失ののち、職業上の崩壊、アイデンティティの危機、「もう十分だ」と言う瞬間に。' },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Phoenix — 500 yılda bir kendini yakıp küllerinden doğan kuş. Helios\'a adanmış.', en: 'Phoenix — the bird that immolates itself and is reborn from its ashes every 500 years. Dedicated to Helios.', de: 'Phönix — der Vogel, der sich alle 500 Jahre selbst verbrennt und aus seiner Asche wiedergeboren wird. Dem Helios geweiht.', es: 'Fénix — el ave que se inmola y renace de sus cenizas cada 500 años. Consagrada a Helios.', pt: 'Fénix — a ave que se imola e renasce das suas cinzas a cada 500 anos. Consagrada a Hélios.', fr: 'Phénix — l\'oiseau qui s\'immole et renaît de ses cendres tous les 500 ans. Consacré à Hélios.', ja: 'フェニックス——五百年ごとに自らを焼き、灰から生まれ変わる鳥。ヘリオスに捧げられている。' } },
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Bennu — Ra\'nın kuşu. Heliopolis tapınağında her gün yeniden doğan güneş ruhu.', en: 'Bennu — Ra\'s bird. The solar spirit reborn each day in the temple of Heliopolis.', de: 'Bennu — Ras Vogel. Der Sonnengeist, der täglich im Tempel von Heliopolis wiedergeboren wird.', es: 'Bennu — el ave de Ra. El espíritu solar que renace cada día en el templo de Heliópolis.', pt: 'Bennu — a ave de Rá. O espírito solar que renasce a cada dia no templo de Heliópolis.', fr: 'Bennou — l\'oiseau de Rê. L\'esprit solaire qui renaît chaque jour dans le temple d\'Héliopolis.', ja: 'ベンヌ——ラーの鳥。ヘリオポリスの神殿で毎日生まれ変わる太陽の霊。' } },
      { culture: { tr: 'İslam-Sufi', en: 'Islamic-Sufi', de: 'Islamisch-Sufisch', es: 'Islámico-Sufí', pt: 'Islâmico-Sufi', fr: 'Islamo-Soufi', ja: 'イスラーム・スーフィー' }, meaning: { tr: 'Simurg — Attar\'ın eserinde 30 kuş Simurg\'u arar. Sonunda fark ederler ki: 30 kuş kendileridir (Si=30, Murg=kuş).', en: 'Simurgh — in Attar\'s work, thirty birds seek the Simurgh. In the end they realize: the thirty birds are themselves (Si = thirty, Murgh = bird).', de: 'Simurgh — in Attars Werk suchen dreißig Vögel den Simurgh. Am Ende erkennen sie: Die dreißig Vögel sind sie selbst (Si = dreißig, Murgh = Vogel).', es: 'Simurgh — en la obra de Attar, treinta pájaros buscan al Simurgh. Al final comprenden: los treinta pájaros son ellos mismos (Si = treinta, Murgh = pájaro).', pt: 'Simurgh — na obra de Attar, trinta pássaros procuram o Simurgh. No fim compreendem: os trinta pássaros são eles próprios (Si = trinta, Murgh = pássaro).', fr: 'Simorgh — dans l\'œuvre d\'Attar, trente oiseaux cherchent le Simorgh. À la fin, ils comprennent : les trente oiseaux sont eux-mêmes (Si = trente, Morgh = oiseau).', ja: 'シームルグ——アッタールの作品では三十羽の鳥がシームルグを探す。最後に彼らは悟る——三十羽の鳥とは自分たち自身である（スィー＝三十、モルグ＝鳥）。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Fenghuang — uyum, erdem ve barış sembolü. İmparatoriçenin kuşu.', en: 'Fenghuang — symbol of harmony, virtue, and peace. The empress\'s bird.', de: 'Fenghuang — Symbol der Harmonie, Tugend und des Friedens. Der Vogel der Kaiserin.', es: 'Fenghuang — símbolo de armonía, virtud y paz. El ave de la emperatriz.', pt: 'Fenghuang — símbolo de harmonia, virtude e paz. A ave da imperatriz.', fr: 'Fenghuang — symbole d\'harmonie, de vertu et de paix. L\'oiseau de l\'impératrice.', ja: '鳳凰——調和、徳、そして平和の象徴。皇后の鳥。' } },
      { culture: { tr: 'Türk Mitolojisi', en: 'Turkic Mythology', de: 'Türkische Mythologie', es: 'Mitología Túrquica', pt: 'Mitologia Túrquica', fr: 'Mythologie Turque', ja: 'テュルク神話' }, meaning: { tr: 'Tuğrul/Anka — Türk hanedanlarının amblemi. Saltanatın ölümsüzlüğü.', en: 'Tuğrul/Anka — emblem of the Turkic dynasties. The immortality of sovereignty.', de: 'Tuğrul/Anka — Wappen der türkischen Dynastien. Die Unsterblichkeit der Herrschaft.', es: 'Tuğrul/Anka — emblema de las dinastías túrquicas. La inmortalidad de la soberanía.', pt: 'Tuğrul/Anka — emblema das dinastias túrquicas. A imortalidade da soberania.', fr: 'Tuğrul/Anka — emblème des dynasties turques. L\'immortalité de la souveraineté.', ja: 'トゥールル／アンカ——テュルク王朝の紋章。王権の不死。' } },
    ],
    myths: [
      { tr: 'Attar\'ın Simurg\'u: Dünyanın bütün kuşları kralları Simurg\'u bulmak için yolculuğa çıkar. Tehlikeli vadileri geçerler, çoğu ölür. Sonunda 30 kuş kalır ve aynaya bakarlar — Simurg kendileridir. Sufi\'de "kendini bulma"nın en güçlü metaforu.', en: 'Attar\'s Simurgh: All the world\'s birds set out to find their king, the Simurgh. They cross perilous valleys; most perish. In the end, thirty birds remain and look into a mirror — the Simurgh is themselves. In Sufism, the most powerful metaphor for self-realization.', de: 'Attars Simurgh: Alle Vögel der Welt machen sich auf, ihren König, den Simurgh, zu finden. Sie durchqueren gefährliche Täler; die meisten kommen um. Am Ende bleiben dreißig Vögel und blicken in einen Spiegel — der Simurgh sind sie selbst. Im Sufismus die kraftvollste Metapher der Selbstverwirklichung.', es: 'El Simurgh de Attar: Todos los pájaros del mundo parten en busca de su rey, el Simurgh. Cruzan valles peligrosos; la mayoría perece. Al final quedan treinta pájaros y se miran en un espejo — el Simurgh son ellos mismos. En el sufismo, la metáfora más poderosa de la autorrealización.', pt: 'O Simurgh de Attar: Todos os pássaros do mundo partem em busca do seu rei, o Simurgh. Atravessam vales perigosos; a maioria perece. No fim restam trinta pássaros e olham-se num espelho — o Simurgh são eles próprios. No sufismo, a metáfora mais poderosa da autorrealização.', fr: 'Le Simorgh d\'Attar : Tous les oiseaux du monde partent en quête de leur roi, le Simorgh. Ils traversent des vallées périlleuses ; la plupart périssent. À la fin, trente oiseaux subsistent et se regardent dans un miroir — le Simorgh, c\'est eux-mêmes. Dans le soufisme, la plus puissante métaphore de la réalisation de soi.', ja: 'アッタールのシームルグ：世界中の鳥たちが王シームルグを探す旅に出る。危険な谷を越え、多くが死ぬ。最後に三十羽が残り、鏡を覗き込む——シームルグとは彼ら自身だった。スーフィズムにおける「自己発見」の最も力強い比喩。' },
      { tr: 'Mısır Bennu Kuşu: Her sabah Heliopolis tapınağında güneşle birlikte doğan, akşam ölüp tekrar dirilen kutsal kuş. Tanrı Ra\'nın ruhu.', en: 'The Egyptian Bennu Bird: The sacred bird reborn each morning with the sun in the temple of Heliopolis, dying each evening only to rise again. The soul of the god Ra.', de: 'Der ägyptische Bennu-Vogel: Der heilige Vogel, der jeden Morgen mit der Sonne im Tempel von Heliopolis wiedergeboren wird, jeden Abend stirbt, nur um wieder aufzuerstehen. Die Seele des Gottes Ra.', es: 'El ave Bennu egipcia: El ave sagrada que renace cada mañana con el sol en el templo de Heliópolis, muere cada tarde solo para alzarse de nuevo. El alma del dios Ra.', pt: 'A ave Bennu egípcia: A ave sagrada que renasce a cada manhã com o sol no templo de Heliópolis, morre a cada tarde apenas para se erguer de novo. A alma do deus Rá.', fr: 'L\'oiseau Bennou égyptien : L\'oiseau sacré qui renaît chaque matin avec le soleil dans le temple d\'Héliopolis, meurt chaque soir pour ressusciter à nouveau. L\'âme du dieu Rê.', ja: 'エジプトのベンヌ鳥：ヘリオポリスの神殿で毎朝太陽とともに生まれ、夕べに死してまた蘇る聖なる鳥。神ラーの魂。' },
    ],
  },

  // ─── a007 Geyik ─────────────────────────────────────────────────────────
  a007: {
    jung: { tr: '"Kalbin Habercisi" arketipi. Geyik anima/animus köprüsü — vahşi olduğu kadar nazik, kaçtığı kadar yaklaşan. Maskülen-feminen dengesinin sembolü.', en: 'The "Herald of the Heart" archetype. The deer is the Anima/Animus bridge — as wild as it is gentle, as fleeing as it is approaching. Symbol of the masculine-feminine balance.', de: 'Der Archetyp des "Herolds des Herzens". Der Hirsch ist die Brücke zwischen Anima und Animus — so wild wie sanft, so fliehend wie nahend. Symbol des Gleichgewichts von Männlichem und Weiblichem.', es: 'El arquetipo del "Heraldo del Corazón". El ciervo es el puente entre el Ánima y el Ánimus — tan salvaje como tierno, tan huidizo como cercano. Símbolo del equilibrio masculino-femenino.', pt: 'O arquétipo do "Arauto do Coração". O veado é a ponte entre a Anima e o Animus — tão selvagem quanto gentil, tão fugidio quanto próximo. Símbolo do equilíbrio masculino-feminino.', fr: 'L\'archétype du "Héraut du cœur". Le cerf est le pont entre l\'Anima et l\'Animus — aussi sauvage que doux, aussi fuyant qu\'approchant. Symbole de l\'équilibre masculin-féminin.', ja: '「心の使者」の元型。鹿はアニマとアニムスの架け橋——荒々しくも優しく、逃げながらも近づく。男性性と女性性の均衡の象徴。' },
    dream: { tr: 'Geyik rüyada görünürse — kalp meselesi açılıyor demektir. Geyiği takip ediyorsan, ruhun bir sevgiye yönlendiriliyor. Kaçıyorsa, korkuyorsun.', en: 'If a deer appears in dream — a matter of the heart is opening. If you follow the deer, your soul is being guided toward a love. If it flees, you are afraid.', de: 'Erscheint ein Hirsch im Traum — öffnet sich eine Angelegenheit des Herzens. Folgst du dem Hirsch, wird deine Seele zu einer Liebe geführt. Flieht er, hast du Angst.', es: 'Si un ciervo aparece en sueños — un asunto del corazón se abre. Si sigues al ciervo, tu alma es guiada hacia un amor. Si huye, tienes miedo.', pt: 'Se um veado aparece em sonho — um assunto do coração abre-se. Se segues o veado, a tua alma é guiada para um amor. Se foge, tens medo.', fr: 'Si un cerf apparaît en rêve — une affaire du cœur s\'ouvre. Si tu suis le cerf, ton âme est guidée vers un amour. S\'il fuit, tu as peur.', ja: '夢に鹿が現れるなら——心の事柄が開かれていく。鹿を追うなら、あなたの魂はある愛へと導かれている。逃げるなら、あなたは恐れている。' },
    shadow: { tr: 'Aşırı hassasiyet. Hep tetikte yaşamak. Sürekli kaçış halinde olmak savunma değil, hapis olur.', en: 'Excessive sensitivity. Living always on edge. Being in constant flight becomes not defense but imprisonment.', de: 'Übermäßige Empfindsamkeit. Stets auf der Hut zu leben. Im ständigen Fluchtzustand zu sein wird nicht zur Verteidigung, sondern zur Gefangenschaft.', es: 'Sensibilidad excesiva. Vivir siempre en alerta. Estar en huida constante se vuelve no defensa sino prisión.', pt: 'Sensibilidade excessiva. Viver sempre em alerta. Estar em fuga constante torna-se não defesa, mas prisão.', fr: 'Sensibilité excessive. Vivre toujours sur le qui-vive. Être en fuite constante devient non une défense mais une prison.', ja: '過度の敏感さ。常に身構えて生きること。絶えず逃げ続けることは、防御ではなく牢獄となる。' },
    whenAppears: { tr: 'Şefkat sınavında, vahşi ile nazik arasında seçim yaparken, sürpriz bir aşk veya kalp açılışında.', en: 'In a test of tenderness, while choosing between wild and gentle, at a surprise love or opening of the heart.', de: 'In einer Prüfung der Zärtlichkeit, während du zwischen Wildheit und Sanftheit wählst, bei einer überraschenden Liebe oder Herzensöffnung.', es: 'En una prueba de ternura, al elegir entre lo salvaje y lo tierno, ante un amor sorpresa o una apertura del corazón.', pt: 'Numa prova de ternura, ao escolher entre o selvagem e o gentil, perante um amor surpresa ou uma abertura do coração.', fr: 'Dans une épreuve de tendresse, en choisissant entre le sauvage et le doux, lors d\'un amour surprise ou d\'une ouverture du cœur.', ja: '優しさの試練のとき、荒々しさと穏やかさのあいだで選ぶとき、不意の愛や心の開きのときに。' },
    traditions: [
      { culture: { tr: 'Türk Mitolojisi', en: 'Turkic Mythology', de: 'Türkische Mythologie', es: 'Mitología Túrquica', pt: 'Mitologia Túrquica', fr: 'Mythologie Turque', ja: 'テュルク神話' }, meaning: { tr: 'Hakan Oğuz Han\'a yol gösteren kutsal ak geyik. Devleti kuran rehber.', en: 'The sacred white deer that guided Oğuz Khan. The guide who founded the state.', de: 'Der heilige weiße Hirsch, der Oğuz Khan den Weg wies. Der Führer, der den Staat gründete.', es: 'El sagrado ciervo blanco que guió a Oğuz Kan. El guía que fundó el estado.', pt: 'O sagrado veado branco que guiou Oğuz Khan. O guia que fundou o estado.', fr: 'Le cerf blanc sacré qui guida Oğuz Khan. Le guide qui fonda l\'État.', ja: 'オグズ・ハンに道を示した聖なる白い鹿。国家を建てた導き手。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Cernunnos — boynuzlu geyik tanrısı. Vahşi doğanın kralı, döngüsel ölüm-doğum.', en: 'Cernunnos — the horned stag god. King of wild nature, cyclical death and birth.', de: 'Cernunnos — der gehörnte Hirschgott. König der wilden Natur, zyklischer Tod und Geburt.', es: 'Cernunnos — el dios ciervo astado. Rey de la naturaleza salvaje, muerte y nacimiento cíclicos.', pt: 'Cernunnos — o deus veado com hastes. Rei da natureza selvagem, morte e nascimento cíclicos.', fr: 'Cernunnos — le dieu-cerf cornu. Roi de la nature sauvage, mort et naissance cycliques.', ja: 'ケルヌンノス——角ある牡鹿の神。野生の自然の王、巡る死と誕生。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Aziz Eustace\'in görmesi — boynuzları arasında haç taşıyan geyik. İlahi çağrı.', en: 'The vision of Saint Eustace — a stag bearing a cross between its antlers. The divine summons.', de: 'Die Vision des heiligen Eustachius — ein Hirsch, der ein Kreuz zwischen seinem Geweih trägt. Der göttliche Ruf.', es: 'La visión de San Eustaquio — un ciervo que lleva una cruz entre sus astas. El llamado divino.', pt: 'A visão de Santo Eustáquio — um veado que traz uma cruz entre as hastes. O chamado divino.', fr: 'La vision de saint Eustache — un cerf portant une croix entre ses bois. L\'appel divin.', ja: '聖エウスタキウスの幻視——角のあいだに十字架を掲げる牡鹿。神の召命。' } },
      { culture: { tr: 'Şamanik', en: 'Shamanic', de: 'Schamanisch', es: 'Chamánico', pt: 'Xamânico', fr: 'Chamanique', ja: 'シャーマニズム' }, meaning: { tr: 'Sibirya şamanları ruhlar alemine geyikle yolculuk eder. Üç dünya arasında köprü.', en: 'Siberian shamans journey to the spirit realm on the deer. A bridge between the three worlds.', de: 'Sibirische Schamanen reisen auf dem Hirsch ins Geisterreich. Eine Brücke zwischen den drei Welten.', es: 'Los chamanes siberianos viajan al reino de los espíritus sobre el ciervo. Un puente entre los tres mundos.', pt: 'Os xamãs siberianos viajam ao reino dos espíritos sobre o veado. Uma ponte entre os três mundos.', fr: 'Les chamanes sibériens voyagent vers le royaume des esprits sur le cerf. Un pont entre les trois mondes.', ja: 'シベリアのシャーマンは鹿に乗って霊界へ旅する。三つの世界をつなぐ橋。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Artemis\'in kutsal hayvanı. Bakire avcı tanrıçanın bineği ve simgesi.', en: 'Artemis\'s sacred animal. Mount and emblem of the virgin huntress goddess.', de: 'Das heilige Tier der Artemis. Reittier und Wappen der jungfräulichen Jagdgöttin.', es: 'El animal sagrado de Artemisa. Montura y emblema de la diosa cazadora virgen.', pt: 'O animal sagrado de Ártemis. Montaria e emblema da deusa caçadora virgem.', fr: 'L\'animal sacré d\'Artémis. Monture et emblème de la déesse chasseresse vierge.', ja: 'アルテミスの聖なる動物。処女の狩猟女神の乗り物にして象徴。' } },
    ],
    myths: [
      { tr: 'Oğuz Han Destanı: Oğuz Han avlanırken karşısına bir ak geyik çıkar, onu izleyerek yeni topraklara ulaşır ve devletini kurar.', en: 'The Oğuz Khan Epic: While hunting, Oğuz Khan encounters a white deer; following it, he reaches new lands and founds his state.', de: 'Das Oğuz-Khan-Epos: Während der Jagd begegnet Oğuz Khan einem weißen Hirsch; ihm folgend erreicht er neue Länder und gründet seinen Staat.', es: 'La epopeya de Oğuz Kan: Mientras caza, Oğuz Kan se topa con un ciervo blanco; siguiéndolo, alcanza nuevas tierras y funda su estado.', pt: 'A epopeia de Oğuz Khan: Enquanto caça, Oğuz Khan depara-se com um veado branco; seguindo-o, alcança novas terras e funda o seu estado.', fr: 'L\'épopée d\'Oğuz Khan : En chassant, Oğuz Khan rencontre un cerf blanc ; le suivant, il atteint de nouvelles terres et fonde son État.', ja: 'オグズ・ハン叙事詩：狩りの最中、オグズ・ハンの前に白い鹿が現れる。それを追って新たな地に至り、国家を建てる。' },
      { tr: 'Aziz Eustace: Romalı bir general avlanırken bir geyikle karşılaşır, boynuzları arasında haç görür — bu görüntüyle Hristiyanlığa geçer.', en: 'Saint Eustace: While hunting, a Roman general encounters a stag and sees a cross between its antlers — by this vision he converts to Christianity.', de: 'Heiliger Eustachius: Während der Jagd begegnet ein römischer General einem Hirsch und sieht ein Kreuz zwischen dessen Geweih — durch diese Vision bekehrt er sich zum Christentum.', es: 'San Eustaquio: Mientras caza, un general romano se encuentra con un ciervo y ve una cruz entre sus astas — por esta visión se convierte al cristianismo.', pt: 'Santo Eustáquio: Enquanto caça, um general romano encontra um veado e vê uma cruz entre as suas hastes — por esta visão converte-se ao cristianismo.', fr: 'Saint Eustache : En chassant, un général romain rencontre un cerf et voit une croix entre ses bois — par cette vision, il se convertit au christianisme.', ja: '聖エウスタキウス：狩りの最中、ローマの将軍が牡鹿に出会い、その角のあいだに十字架を見る——この幻視によって彼はキリスト教に改宗する。' },
    ],
  },

  // ─── a008 Baykuş ────────────────────────────────────────────────────────
  a008: {
    jung: { tr: '"Bilge Yaşlı" arketipi — Senex. Karanlıkta görme yeteneği; bilinçaltını okuma kapasitesi. Gece zekası.', en: 'The "Wise Elder" archetype — Senex. The ability to see in darkness; the capacity to read the unconscious. Nocturnal intelligence.', de: 'Der Archetyp des "weisen Alten" — Senex. Die Fähigkeit, im Dunkeln zu sehen; die Fähigkeit, das Unbewusste zu lesen. Nächtliche Intelligenz.', es: 'El arquetipo del "Anciano Sabio" — Senex. La capacidad de ver en la oscuridad; la capacidad de leer el inconsciente. Inteligencia nocturna.', pt: 'O arquétipo do "Ancião Sábio" — Senex. A capacidade de ver na escuridão; a capacidade de ler o inconsciente. Inteligência noturna.', fr: 'L\'archétype du "Vieux Sage" — Senex. La faculté de voir dans l\'obscurité ; la capacité de lire l\'inconscient. Intelligence nocturne.', ja: '「賢き老人」の元型——セネックス。闇の中で見る力、無意識を読み解く力。夜の知性。' },
    dream: { tr: 'Baykuş rüyada — bir sırrın çözülmek üzere olduğunu söyler. Ya da bir aldatma fark ediliyor. Baykuşun bakışı: gerçeği görme zamanı geldi.', en: 'Owl in dream — says a secret is about to be unraveled. Or a deception is being noticed. The owl\'s gaze: the time to see the truth has come.', de: 'Eule im Traum — sagt, dass ein Geheimnis kurz davor ist, sich zu entschlüsseln. Oder eine Täuschung wird bemerkt. Der Blick der Eule: Die Zeit, die Wahrheit zu sehen, ist gekommen.', es: 'Búho en sueños — dice que un secreto está a punto de revelarse. O que se advierte un engaño. La mirada del búho: ha llegado el momento de ver la verdad.', pt: 'Coruja em sonho — diz que um segredo está prestes a ser revelado. Ou que se nota um engano. O olhar da coruja: chegou o momento de ver a verdade.', fr: 'Hibou en rêve — dit qu\'un secret est sur le point d\'être dénoué. Ou qu\'une tromperie est aperçue. Le regard du hibou : le temps de voir la vérité est venu.', ja: '夢の中のフクロウ——ある秘密が解き明かされようとしていると告げる。あるいは欺きが見抜かれつつある。フクロウのまなざし——真実を見る時が来た。' },
    shadow: { tr: 'Kötümser bilgelik. Her şeyi "görmek" insanı yalnızlaştırırsa baykuş — küskün münzeviye dönüşür. Bilgi acıya dönüşür.', en: 'Pessimistic wisdom. If "seeing everything" isolates a person, the owl turns into a resentful hermit. Knowledge becomes pain.', de: 'Pessimistische Weisheit. Wenn "alles zu sehen" einen Menschen vereinsamt, wird die Eule zum verbitterten Einsiedler. Wissen wird zu Schmerz.', es: 'Sabiduría pesimista. Si "verlo todo" aísla a una persona, el búho se vuelve un ermitaño resentido. El conocimiento se torna dolor.', pt: 'Sabedoria pessimista. Se "ver tudo" isola uma pessoa, a coruja torna-se um eremita ressentido. O conhecimento torna-se dor.', fr: 'Sagesse pessimiste. Si "tout voir" isole une personne, le hibou devient un ermite aigri. Le savoir devient douleur.', ja: '悲観的な知恵。「すべてを見る」ことが人を孤立させるなら、フクロウは恨みを抱く隠者となる。知は苦痛に変わる。' },
    whenAppears: { tr: 'Aldatıldığında, gizli bir gerçek hissettiğinde, içe çekilme döneminde, sezgin keskinleştiğinde.', en: 'When you are deceived, when you sense a hidden truth, in a period of withdrawal, when your intuition sharpens.', de: 'Wenn du getäuscht wirst, wenn du eine verborgene Wahrheit spürst, in einer Zeit des Rückzugs, wenn deine Intuition sich schärft.', es: 'Cuando te engañan, cuando intuyes una verdad oculta, en un período de retiro, cuando tu intuición se agudiza.', pt: 'Quando és enganado, quando pressentes uma verdade oculta, num período de recolhimento, quando a tua intuição se aguça.', fr: 'Quand on te trompe, quand tu pressens une vérité cachée, en période de retrait, quand ton intuition s\'aiguise.', ja: '欺かれたとき、隠された真実を感じ取るとき、内に退く時期、直感が研ぎ澄まされるときに。' },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Athena\'nın kuşu. Bilgelik tanrıçasının zeka simgesi. Atina sikkelerinde basılı.', en: 'Athena\'s bird. Symbol of the wisdom goddess\'s intellect. Stamped on Athenian coins.', de: 'Athenes Vogel. Symbol des Verstandes der Weisheitsgöttin. Auf athenische Münzen geprägt.', es: 'El ave de Atenea. Símbolo del intelecto de la diosa de la sabiduría. Acuñada en las monedas atenienses.', pt: 'A ave de Atena. Símbolo do intelecto da deusa da sabedoria. Cunhada nas moedas atenienses.', fr: 'L\'oiseau d\'Athéna. Symbole de l\'intellect de la déesse de la sagesse. Frappé sur les monnaies athéniennes.', ja: 'アテナの鳥。知恵の女神の知性の象徴。アテネの貨幣に刻まれている。' } },
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Ölüler diyarının bekçisi. Geçişin ve gece âleminin hayvanı.', en: 'Guardian of the land of the dead. Animal of transition and the nocturnal realm.', de: 'Wächter des Totenreichs. Tier des Übergangs und des nächtlichen Reichs.', es: 'Guardián de la tierra de los muertos. Animal de la transición y del reino nocturno.', pt: 'Guardião da terra dos mortos. Animal da transição e do reino noturno.', fr: 'Gardien du pays des morts. Animal de la transition et du royaume nocturne.', ja: '死者の国の番人。移行と夜の領域の動物。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Hopi geleneğinde uyarıcı — kötü haberi taşıyan ama doğruyu söyleyen.', en: 'In Hopi tradition, the warner — bearer of bad news yet speaker of truth.', de: 'In der Hopi-Tradition der Warner — Überbringer schlechter Nachrichten, doch Sprecher der Wahrheit.', es: 'En la tradición hopi, el que advierte — portador de malas noticias pero portavoz de la verdad.', pt: 'Na tradição hopi, o que avisa — portador de más notícias, mas porta-voz da verdade.', fr: 'Dans la tradition hopi, l\'avertisseur — porteur de mauvaises nouvelles mais diseur de vérité.', ja: 'ホピの伝統における警告者——悪い報せを運ぶが、真実を語る者。' } },
      { culture: { tr: 'Türk Halk İnancı', en: 'Turkish Folk Belief', de: 'Türkischer Volksglaube', es: 'Creencia Popular Turca', pt: 'Crença Popular Turca', fr: 'Croyance Populaire Turque', ja: 'トルコ民間信仰' }, meaning: { tr: 'Anadolu\'da uğursuz sayılan ama gerçekte kadim bilgeliği taşıyan. Atalardan miras zihinsel direnç.', en: 'In Anatolia regarded as ill-omened, yet truly the bearer of ancient wisdom. Mental endurance inherited from the ancestors.', de: 'In Anatolien als Unglücksbote angesehen, in Wahrheit jedoch Träger uralter Weisheit. Von den Ahnen ererbte geistige Standhaftigkeit.', es: 'En Anatolia considerado de mal agüero, pero en verdad portador de sabiduría ancestral. Resistencia mental heredada de los antepasados.', pt: 'Na Anatólia considerada de mau agouro, mas na verdade portadora de sabedoria ancestral. Resistência mental herdada dos antepassados.', fr: 'En Anatolie tenu pour de mauvais augure, mais en vérité porteur d\'une sagesse ancestrale. Endurance mentale héritée des ancêtres.', ja: 'アナトリアでは不吉とされるが、実は古の知恵を担う存在。先祖から受け継がれた精神の強靭さ。' } },
      { culture: { tr: 'Hint', en: 'Hindu', de: 'Hinduistisch', es: 'Hindú', pt: 'Hindu', fr: 'Hindou', ja: 'ヒンドゥー' }, meaning: { tr: 'Lakshmi\'nin bineği. Bolluk tanrıçasının gözleri — karanlıkta bile bereketi görür.', en: 'Lakshmi\'s mount. The eyes of the goddess of abundance — sees prosperity even in darkness.', de: 'Lakshmis Reittier. Die Augen der Göttin des Überflusses — sie sieht Wohlstand selbst im Dunkeln.', es: 'La montura de Lakshmi. Los ojos de la diosa de la abundancia — ve la prosperidad incluso en la oscuridad.', pt: 'A montaria de Lakshmi. Os olhos da deusa da abundância — vê a prosperidade mesmo na escuridão.', fr: 'La monture de Lakshmi. Les yeux de la déesse de l\'abondance — voit la prospérité même dans l\'obscurité.', ja: 'ラクシュミーの乗り物。豊穣の女神の目——闇の中でさえ繁栄を見いだす。' } },
    ],
    myths: [
      { tr: 'Athena ve Baykuş: Bilgelik tanrıçası Athena\'nın omzunda taşıdığı baykuş, sahibinin sezgilerini ve görüsünü taşır. Atina\'nın sembolü.', en: 'Athena and the Owl: The owl carried on the shoulder of Athena, goddess of wisdom, bears its mistress\'s intuition and vision. Symbol of Athens.', de: 'Athene und die Eule: Die Eule, die auf der Schulter der Weisheitsgöttin Athene sitzt, trägt die Intuition und das Sehen ihrer Herrin. Symbol Athens.', es: 'Atenea y el búho: El búho que lleva sobre el hombro Atenea, diosa de la sabiduría, porta la intuición y la visión de su dueña. Símbolo de Atenas.', pt: 'Atena e a coruja: A coruja que Atena, deusa da sabedoria, leva ao ombro, carrega a intuição e a visão da sua dona. Símbolo de Atenas.', fr: 'Athéna et le hibou : Le hibou porté sur l\'épaule d\'Athéna, déesse de la sagesse, porte l\'intuition et la vision de sa maîtresse. Symbole d\'Athènes.', ja: 'アテナとフクロウ：知恵の女神アテナが肩に乗せるフクロウは、主の直感と洞察を担う。アテネの象徴。' },
      { tr: 'Anadolu\'da Baykuş: "Baykuş öttü, kötü oldu" inanışı yüzyıllar boyu sürmüş — ama gerçek şaman geleneğinde baykuş atadan haberdir.', en: 'The Owl in Anatolia: The belief "the owl hooted, ill has come" lasted centuries — but in true shamanic tradition the owl is a message from the ancestors.', de: 'Die Eule in Anatolien: Der Glaube "Die Eule rief, Unheil ist gekommen" hielt sich über Jahrhunderte — doch in der wahren schamanischen Tradition ist die Eule eine Botschaft der Ahnen.', es: 'El búho en Anatolia: La creencia "el búho ululó, mal ha venido" duró siglos — pero en la verdadera tradición chamánica el búho es un mensaje de los antepasados.', pt: 'A coruja na Anatólia: A crença "a coruja piou, o mal chegou" durou séculos — mas na verdadeira tradição xamânica a coruja é uma mensagem dos antepassados.', fr: 'Le hibou en Anatolie : La croyance "le hibou a hululé, le malheur est venu" dura des siècles — mais dans la vraie tradition chamanique, le hibou est un message des ancêtres.', ja: 'アナトリアのフクロウ：「フクロウが鳴いた、災いが来た」という言い伝えは何世紀も続いた——だが真のシャーマンの伝統では、フクロウは先祖からの報せである。' },
    ],
  },

  // ─── a009 Aslan ─────────────────────────────────────────────────────────
  a009: {
    jung: { tr: '"Kral" arketipi. Sezar, Pir, Hükümdar. İçsel otoritenin sembolü. Egoyu hizmete dönüştürme gücü.', en: 'The "King" archetype. Caesar, Pir, Sovereign. Symbol of inner authority. The power to transform ego into service.', de: 'Der Archetyp des "Königs". Cäsar, Pir, Herrscher. Symbol der inneren Autorität. Die Macht, das Ego in Dienst zu verwandeln.', es: 'El arquetipo del "Rey". César, Pir, Soberano. Símbolo de la autoridad interior. El poder de transformar el ego en servicio.', pt: 'O arquétipo do "Rei". César, Pir, Soberano. Símbolo da autoridade interior. O poder de transformar o ego em serviço.', fr: 'L\'archétype du "Roi". César, Pir, Souverain. Symbole de l\'autorité intérieure. Le pouvoir de transformer l\'ego en service.', ja: '「王」の元型。皇帝、ピール、君主。内なる権威の象徴。自我を奉仕へと変える力。' },
    dream: { tr: 'Aslan rüyada — içindeki kral uyanıyor. Üzerine atıyor mu? Bastırdığın bir gücün geri istiyor. Yanında yatıyor mu? Otoritene barıştın.', en: 'Lion in dream — the king within you awakens. Does it pounce? A force you have suppressed wants itself back. Does it lie beside you? You have made peace with your authority.', de: 'Löwe im Traum — der König in dir erwacht. Springt er dich an? Eine Kraft, die du unterdrückt hast, will sich zurück. Liegt er neben dir? Du hast Frieden mit deiner Autorität geschlossen.', es: 'León en sueños — el rey que llevas dentro despierta. ¿Se abalanza? Una fuerza que has reprimido se reclama a sí misma. ¿Yace a tu lado? Has hecho las paces con tu autoridad.', pt: 'Leão em sonho — o rei dentro de ti desperta. Salta sobre ti? Uma força que reprimiste reclama-se de volta. Deita-se ao teu lado? Fizeste as pazes com a tua autoridade.', fr: 'Lion en rêve — le roi en toi s\'éveille. Bondit-il ? Une force que tu as réprimée se réclame. Se couche-t-il à tes côtés ? Tu as fait la paix avec ton autorité.', ja: '夢の中のライオン——あなたの内なる王が目覚める。襲いかかってくるか? 抑え込んだ力が取り戻されたがっている。傍らに横たわるか? あなたは自らの権威と和解した。' },
    shadow: { tr: 'Kibir ve narsisizm. Kral arketipi denetlenmezse — tiranlık, açlık doymayan ego, gösteriş için var olma.', en: 'Arrogance and narcissism. When the King archetype goes unchecked — tyranny, an ego whose hunger is never sated, existing for display.', de: 'Hochmut und Narzissmus. Bleibt der König-Archetyp ungezügelt — Tyrannei, ein Ego, dessen Hunger nie gestillt wird, Dasein zur Schau.', es: 'Arrogancia y narcisismo. Cuando el arquetipo del Rey no se controla — tiranía, un ego cuya hambre nunca se sacia, existir para la ostentación.', pt: 'Arrogância e narcisismo. Quando o arquétipo do Rei não é controlado — tirania, um ego cuja fome nunca se sacia, existir para a ostentação.', fr: 'Arrogance et narcissisme. Quand l\'archétype du Roi n\'est pas maîtrisé — tyrannie, un ego dont la faim n\'est jamais rassasiée, exister pour le spectacle.', ja: '傲慢と自己愛。王の元型が制御されなければ——暴政、決して満たされぬ飢えを抱く自我、見せびらかすために存在すること。' },
    whenAppears: { tr: 'Otorite sınavında, lider olarak çıkma zamanında, haksızlığa uğradığında, sesini yükseltmen gerekirken.', en: 'In a test of authority, when it is time to rise as a leader, when you have been wronged, when you must raise your voice.', de: 'In einer Prüfung der Autorität, wenn es Zeit ist, als Anführer hervorzutreten, wenn dir Unrecht geschah, wenn du deine Stimme erheben musst.', es: 'En una prueba de autoridad, cuando es hora de alzarte como líder, cuando has sido agraviado, cuando debes alzar la voz.', pt: 'Numa prova de autoridade, quando é hora de te ergueres como líder, quando foste injustiçado, quando deves erguer a voz.', fr: 'Dans une épreuve d\'autorité, quand il est temps de t\'élever en chef, quand on t\'a fait du tort, quand tu dois élever la voix.', ja: '権威の試練のとき、指導者として立ち上がるべきとき、不当な扱いを受けたとき、声を上げねばならぬときに。' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Sekhmet — aslan başlı tanrıça. Şiddetli iyileştirici. Sahmet adaletin koruyucusu.', en: 'Sekhmet — the lion-headed goddess. Fierce healer. Sekhmet, guardian of justice.', de: 'Sachmet — die löwenköpfige Göttin. Wilde Heilerin. Sachmet, Hüterin der Gerechtigkeit.', es: 'Sejmet — la diosa con cabeza de león. Sanadora feroz. Sejmet, guardiana de la justicia.', pt: 'Sekhmet — a deusa com cabeça de leão. Curandeira feroz. Sekhmet, guardiã da justiça.', fr: 'Sekhmet — la déesse à tête de lionne. Guérisseuse féroce. Sekhmet, gardienne de la justice.', ja: 'セクメト——ライオンの頭をもつ女神。猛き癒し手。セクメト、正義の守護者。' } },
      { culture: { tr: 'Hitit', en: 'Hittite', de: 'Hethitisch', es: 'Hitita', pt: 'Hitita', fr: 'Hittite', ja: 'ヒッタイト' }, meaning: { tr: 'Tapınak bekçisi. Anadolu\'da Hattuşa kapılarında taş aslanlar — sınırın koruyucuları.', en: 'Temple guardian. In Anatolia, the stone lions at the gates of Hattusa — protectors of the threshold.', de: 'Tempelwächter. In Anatolien die steinernen Löwen an den Toren von Hattuša — Beschützer der Schwelle.', es: 'Guardián del templo. En Anatolia, los leones de piedra en las puertas de Hattusa — protectores del umbral.', pt: 'Guardião do templo. Na Anatólia, os leões de pedra às portas de Hattusa — protetores do limiar.', fr: 'Gardien du temple. En Anatolie, les lions de pierre aux portes de Hattusa — protecteurs du seuil.', ja: '神殿の守り手。アナトリアのハットゥシャの門の石のライオン——境界の守護者。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Aziz Markos\'un sembolü. Diriliş ve İsa\'nın krallığı. "Yahuda\'nın aslanı".', en: 'Symbol of Saint Mark. Resurrection and the kingship of Christ. The "Lion of Judah".', de: 'Symbol des heiligen Markus. Auferstehung und das Königtum Christi. Der "Löwe von Juda".', es: 'Símbolo de San Marcos. Resurrección y la realeza de Cristo. El "León de Judá".', pt: 'Símbolo de São Marcos. Ressurreição e a realeza de Cristo. O "Leão de Judá".', fr: 'Symbole de saint Marc. Résurrection et royauté du Christ. Le "Lion de Juda".', ja: '聖マルコの象徴。復活とキリストの王権。「ユダの獅子」。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Narasimha — Vishnu\'nun aslan-insan avatarı. Adaletsizliği yıkıcı kutsal öfke.', en: 'Narasimha — Vishnu\'s lion-man avatar. Holy wrath destructive of injustice.', de: 'Narasimha — Vishnus Löwen-Mensch-Avatar. Heiliger Zorn, der das Unrecht vernichtet.', es: 'Narasimha — el avatar hombre-león de Vishnú. Ira sagrada destructora de la injusticia.', pt: 'Narasimha — o avatar homem-leão de Vishnu. Ira sagrada destruidora da injustiça.', fr: 'Narasimha — l\'avatar homme-lion de Vishnou. Colère sacrée destructrice de l\'injustice.', ja: 'ナラシンハ——ヴィシュヌのライオン人間のアヴァターラ。不正を打ち砕く聖なる憤怒。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Nemea aslanı — Herakles\'in ilk işi. Bastırılması gereken vahşi güç.', en: 'The Nemean Lion — Heracles\'s first labor. The wild force that must be subdued.', de: 'Der Nemeische Löwe — Herakles\' erste Tat. Die wilde Kraft, die bezwungen werden muss.', es: 'El León de Nemea — el primer trabajo de Heracles. La fuerza salvaje que debe ser sometida.', pt: 'O Leão de Nemeia — o primeiro trabalho de Héracles. A força selvagem que deve ser subjugada.', fr: 'Le Lion de Némée — le premier travail d\'Héraclès. La force sauvage qui doit être domptée.', ja: 'ネメアの獅子——ヘラクレスの最初の難業。屈服させねばならぬ野生の力。' } },
    ],
    myths: [
      { tr: 'Sekhmet: Mısır mitolojisinde insanları kötülüklerinden temizlemek için gönderilen aslan başlı tanrıça. Hem yıkıcı hem de şifa veren güç.', en: 'Sekhmet: In Egyptian mythology, the lion-headed goddess sent to purge humanity of its evils. A force both destructive and healing.', de: 'Sachmet: In der ägyptischen Mythologie die löwenköpfige Göttin, gesandt, um die Menschheit von ihren Übeln zu reinigen. Eine Kraft, zugleich zerstörerisch und heilend.', es: 'Sejmet: En la mitología egipcia, la diosa con cabeza de león enviada para purgar a la humanidad de sus males. Una fuerza a la vez destructora y sanadora.', pt: 'Sekhmet: Na mitologia egípcia, a deusa com cabeça de leão enviada para purgar a humanidade dos seus males. Uma força ao mesmo tempo destruidora e curadora.', fr: 'Sekhmet : Dans la mythologie égyptienne, la déesse à tête de lionne envoyée pour purger l\'humanité de ses maux. Une force à la fois destructrice et guérisseuse.', ja: 'セクメト：エジプト神話において、人類をその悪から浄めるために遣わされたライオンの頭をもつ女神。破壊にして癒しの力。' },
      { tr: 'Hitit Aslan Kapısı: Bu aslanlar 3500 yıldır şehri korumaya devam ediyor — Anadolu\'nun ilk kralları aslanı sınırın bekçisi yaptı.', en: 'The Hittite Lion Gate: These lions have guarded the city for 3,500 years — the first kings of Anatolia made the lion the keeper of the threshold.', de: 'Das hethitische Löwentor: Diese Löwen bewachen die Stadt seit 3.500 Jahren — die ersten Könige Anatoliens machten den Löwen zum Hüter der Schwelle.', es: 'La Puerta de los Leones hitita: Estos leones han guardado la ciudad durante 3500 años — los primeros reyes de Anatolia hicieron del león el guardián del umbral.', pt: 'O Portão dos Leões hitita: Estes leões guardam a cidade há 3500 anos — os primeiros reis da Anatólia fizeram do leão o guardião do limiar.', fr: 'La Porte des Lions hittite : Ces lions gardent la cité depuis 3 500 ans — les premiers rois de l\'Anatolie firent du lion le gardien du seuil.', ja: 'ヒッタイトのライオン門：これらのライオンは三千五百年にわたり都を守り続けている——アナトリア最初の王たちはライオンを境界の番人とした。' },
    ],
  },

  // ─── a010 Ayı ──────────────────────────────────────────────────────────
  a010: {
    jung: { tr: '"Büyük Ana" arketipi — kollayıcı, besleyici, ama sınırını çiğnemeye gelen olursa yıkıcı. İçsel kaynaklara çekilme.', en: 'The "Great Mother" archetype — protective, nourishing, yet destructive if her boundary is crossed. Withdrawal into inner resources.', de: 'Der Archetyp der "Großen Mutter" — beschützend, nährend, doch zerstörerisch, wenn ihre Grenze überschritten wird. Rückzug in die inneren Ressourcen.', es: 'El arquetipo de la "Gran Madre" — protectora, nutricia, pero destructora si se traspasa su límite. Repliegue hacia los recursos interiores.', pt: 'O arquétipo da "Grande Mãe" — protetora, nutridora, mas destruidora se o seu limite for ultrapassado. Recolhimento aos recursos interiores.', fr: 'L\'archétype de la "Grande Mère" — protectrice, nourricière, mais destructrice si sa frontière est franchie. Repli vers les ressources intérieures.', ja: '「太母」の元型——守り、養うが、その境界を侵されれば破壊的となる。内なる資源への退避。' },
    dream: { tr: 'Ayı rüyada — uyku, dinlenme, içe dönüşe çağrı. Saldırıyorsa: bir sınırın çiğneniyor. Yavrularını koruyorsa: kendine ait olanı savunmalısın.', en: 'Bear in dream — a call to sleep, rest, turning inward. If attacking: a boundary of yours is being crossed. If protecting cubs: you must defend what is yours.', de: 'Bär im Traum — ein Ruf zu Schlaf, Ruhe, Einkehr. Greift er an: Eine deiner Grenzen wird überschritten. Schützt er seine Jungen: Du musst verteidigen, was dein ist.', es: 'Oso en sueños — una llamada al sueño, al descanso, al recogimiento. Si ataca: se traspasa un límite tuyo. Si protege a sus crías: debes defender lo que es tuyo.', pt: 'Urso em sonho — um chamado ao sono, ao descanso, ao recolhimento. Se ataca: um limite teu está a ser ultrapassado. Se protege as crias: deves defender o que é teu.', fr: 'Ours en rêve — un appel au sommeil, au repos, à l\'introspection. S\'il attaque : une de tes frontières est franchie. S\'il protège ses petits : tu dois défendre ce qui est tien.', ja: '夢の中のクマ——眠り、休息、内省への呼びかけ。襲うなら、あなたの境界が侵されている。子を守るなら、自分のものを守らねばならない。' },
    shadow: { tr: 'Aşırı içekapanma, depresyon, hibernasyonun bitmemesi. Ayı uyandığında çıkmazsa — soğukta donar.', en: 'Excessive withdrawal, depression, hibernation that never ends. If the bear does not emerge when it wakes — it freezes in the cold.', de: 'Übermäßiger Rückzug, Depression, ein Winterschlaf, der nie endet. Kommt der Bär nicht hervor, wenn er erwacht — erfriert er in der Kälte.', es: 'Repliegue excesivo, depresión, una hibernación que nunca termina. Si el oso no emerge al despertar — se congela en el frío.', pt: 'Recolhimento excessivo, depressão, uma hibernação que nunca termina. Se o urso não emerge ao acordar — congela no frio.', fr: 'Repli excessif, dépression, une hibernation qui ne finit jamais. Si l\'ours ne sort pas à son réveil — il gèle dans le froid.', ja: '過度の引きこもり、抑うつ、終わらぬ冬眠。目覚めても出てこなければ——クマは寒さの中で凍えてしまう。' },
    whenAppears: { tr: 'Sosyal yorgunlukta, bir krizden sonra şifaya çekildiğinde, koruyucu enerjini bulman gerekirken.', en: 'In social exhaustion, when withdrawing to heal after a crisis, when you must find your protective energy.', de: 'Bei sozialer Erschöpfung, wenn du dich nach einer Krise zur Heilung zurückziehst, wenn du deine schützende Energie finden musst.', es: 'En el agotamiento social, cuando te repliegas a sanar tras una crisis, cuando debes encontrar tu energía protectora.', pt: 'No esgotamento social, quando te recolhes para sarar após uma crise, quando deves encontrar a tua energia protetora.', fr: 'Dans l\'épuisement social, quand tu te retires pour guérir après une crise, quand tu dois trouver ton énergie protectrice.', ja: '社会的な疲弊のとき、危機ののち癒えるために退くとき、自らの守る力を見いだすべきときに。' },
    traditions: [
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Şifa hayvanı. Tıp adamları "Ayı Tıbbı" toplar. Mağaraya çekilip rüyada öğrenme.', en: 'The healing animal. Medicine people gather "Bear Medicine". Withdrawing into the cave to learn in dream.', de: 'Das Heiltier. Die Medizinleute sammeln die "Bärenmedizin". Sich in die Höhle zurückziehen, um im Traum zu lernen.', es: 'El animal sanador. Los hombres-medicina recogen la "Medicina del Oso". Replegarse en la cueva para aprender en el sueño.', pt: 'O animal curador. Os homens-medicina recolhem a "Medicina do Urso". Recolher-se à caverna para aprender em sonho.', fr: 'L\'animal guérisseur. Les hommes-médecine recueillent la "Médecine de l\'Ours". Se retirer dans la grotte pour apprendre en rêve.', ja: '癒しの動物。メディスンマンは「クマの薬」を集める。洞窟に退き、夢の中で学ぶこと。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Artos — savaşçı kraliçenin sembolü. Kral Arthur\'un adı buradan gelir.', en: 'Artos — symbol of the warrior queen. The name of King Arthur derives from this.', de: 'Artos — Symbol der Kriegerkönigin. Der Name König Arthurs leitet sich davon ab.', es: 'Artos — símbolo de la reina guerrera. El nombre del rey Arturo deriva de aquí.', pt: 'Artos — símbolo da rainha guerreira. O nome do rei Artur deriva daqui.', fr: 'Artos — symbole de la reine guerrière. Le nom du roi Arthur en dérive.', ja: 'アルトス——戦士の女王の象徴。アーサー王の名はここに由来する。' } },
      { culture: { tr: 'Sibirya/Şamanik', en: 'Siberian/Shamanic', de: 'Sibirisch/Schamanisch', es: 'Siberiano/Chamánico', pt: 'Siberiano/Xamânico', fr: 'Sibérien/Chamanique', ja: 'シベリア／シャーマニズム' }, meaning: { tr: 'Ayı törenleri — avlandıktan sonra ruhuna saygı duruşu. Atalar ayıdan türemiş kabul edilir.', en: 'Bear ceremonies — a salute to the bear\'s spirit after the hunt. Ancestors are held to descend from the bear.', de: 'Bärenzeremonien — eine Ehrung des Bärengeistes nach der Jagd. Die Ahnen gelten als vom Bären abstammend.', es: 'Ceremonias del oso — un saludo al espíritu del oso tras la caza. Se cree que los antepasados descienden del oso.', pt: 'Cerimónias do urso — uma saudação ao espírito do urso após a caça. Crê-se que os antepassados descendem do urso.', fr: 'Cérémonies de l\'ours — un salut à l\'esprit de l\'ours après la chasse. On tient les ancêtres pour descendants de l\'ours.', ja: 'クマの儀礼——狩りののち、クマの霊への敬意の表明。先祖はクマの末裔とされる。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Artemis\'in formu. Kalypso\'nun mağarası — ayı annenin sığınağı.', en: 'A form of Artemis. Calypso\'s cave — the sanctuary of the bear-mother.', de: 'Eine Gestalt der Artemis. Kalypsos Höhle — die Zuflucht der Bärenmutter.', es: 'Una forma de Artemisa. La cueva de Calipso — el santuario de la madre-osa.', pt: 'Uma forma de Ártemis. A caverna de Calipso — o santuário da mãe-ursa.', fr: 'Une forme d\'Artémis. La grotte de Calypso — le sanctuaire de la mère-ourse.', ja: 'アルテミスの一つの姿。カリュプソの洞窟——母グマの聖域。' } },
      { culture: { tr: 'İskandinav', en: 'Norse', de: 'Nordisch', es: 'Nórdico', pt: 'Nórdico', fr: 'Nordique', ja: '北欧' }, meaning: { tr: 'Berserkir — savaşçılar ayı postu giyerek savaş çılgınlığına girer. Vahşi koruyucu güç.', en: 'Berserkir — warriors entering battle-frenzy by donning bear skins. Wild protective power.', de: 'Berserker — Krieger, die durch das Anlegen von Bärenfellen in Kampfwut verfallen. Wilde, schützende Kraft.', es: 'Berserkir — guerreros que entran en furia de batalla al vestir pieles de oso. Poder protector salvaje.', pt: 'Berserkir — guerreiros que entram em fúria de batalha ao vestir peles de urso. Poder protetor selvagem.', fr: 'Berserkir — guerriers entrant en furie guerrière en revêtant des peaux d\'ours. Puissance protectrice sauvage.', ja: 'ベルセルク——クマの毛皮をまとって戦いの狂乱に入る戦士たち。荒々しき守りの力。' } },
    ],
    myths: [
      { tr: 'Kallisto: Yunan mitolojisinde Artemis\'in nymph\'i. Zeus\'la birleştiği için ayıya dönüştürülüp gökyüzüne fırlatılır — Büyük Ayı takımyıldızı olur.', en: 'Callisto: In Greek mythology, a nymph of Artemis. For uniting with Zeus, she is transformed into a bear and cast into the sky — becoming the constellation Ursa Major.', de: 'Kallisto: In der griechischen Mythologie eine Nymphe der Artemis. Weil sie sich mit Zeus vereinte, wird sie in einen Bären verwandelt und an den Himmel geschleudert — sie wird zum Sternbild Großer Bär.', es: 'Calisto: En la mitología griega, una ninfa de Artemisa. Por unirse a Zeus, es transformada en osa y lanzada al cielo — convirtiéndose en la constelación de la Osa Mayor.', pt: 'Calisto: Na mitologia grega, uma ninfa de Ártemis. Por se unir a Zeus, é transformada em ursa e lançada ao céu — tornando-se a constelação da Ursa Maior.', fr: 'Callisto : Dans la mythologie grecque, une nymphe d\'Artémis. Pour s\'être unie à Zeus, elle est transformée en ourse et lancée dans le ciel — devenant la constellation de la Grande Ourse.', ja: 'カリスト：ギリシア神話におけるアルテミスのニンフ。ゼウスと結ばれたために熊に変えられ、天へと放たれる——おおぐま座となる。' },
      { tr: 'Şamanik Ayı Töreni: Sibirya\'da avlanan ayının ruhuna özür dilenir, eti törensel paylaşılır. Ayı atadır, kabul edilir.', en: 'The Shamanic Bear Ceremony: In Siberia, apology is offered to the soul of the hunted bear, and its meat is shared ceremonially. The bear is acknowledged as ancestor.', de: 'Die schamanische Bärenzeremonie: In Sibirien wird der Seele des erlegten Bären um Verzeihung gebeten, sein Fleisch zeremoniell geteilt. Der Bär wird als Ahn anerkannt.', es: 'La ceremonia chamánica del oso: En Siberia se pide disculpas al alma del oso cazado, y su carne se comparte ceremonialmente. Se reconoce al oso como antepasado.', pt: 'A cerimónia xamânica do urso: Na Sibéria pede-se desculpa à alma do urso caçado, e a sua carne é partilhada cerimonialmente. O urso é reconhecido como antepassado.', fr: 'La cérémonie chamanique de l\'ours : En Sibérie, on demande pardon à l\'âme de l\'ours chassé, et sa chair est partagée cérémoniellement. L\'ours est reconnu comme ancêtre.', ja: 'シャーマンのクマの儀礼：シベリアでは狩られたクマの魂に詫び、その肉を儀礼的に分かち合う。クマは祖先として認められる。' },
    ],
  },

  // ─── a011 Tilki ─────────────────────────────────────────────────────────
  a011: {
    jung: { tr: '"Hilebaz/Trickster" arketipi. Kuralları sorgulayan, beklenmedik yoldan çözüm bulan zeka. Logosa karşı mythos.', en: 'The "Trickster" archetype. An intelligence that questions rules and finds solutions on unexpected paths. Mythos against Logos.', de: 'Der Archetyp des "Schelms/Tricksters". Eine Intelligenz, die Regeln hinterfragt und auf unerwarteten Wegen Lösungen findet. Mythos gegen Logos.', es: 'El arquetipo del "Embaucador/Trickster". Una inteligencia que cuestiona las reglas y halla soluciones por caminos inesperados. Mythos contra Logos.', pt: 'O arquétipo do "Trapaceiro/Trickster". Uma inteligência que questiona as regras e encontra soluções por caminhos inesperados. Mythos contra Logos.', fr: 'L\'archétype du "Filou/Trickster". Une intelligence qui questionne les règles et trouve des solutions par des voies inattendues. Le mythos contre le logos.', ja: '「トリックスター（いたずら者）」の元型。規則を問い、思いがけぬ道で解を見いだす知。ロゴスに対するミュトス。' },
    dream: { tr: 'Tilki rüyada — bir durumda dolambaçlı yola gitmeni söylüyor. Direkt yaklaşma çözmüyor. Ya da: biri seni kandırıyor, gözünü aç.', en: 'Fox in dream — tells you to take the indirect path in a situation. The direct approach is not working. Or: someone is deceiving you — open your eyes.', de: 'Fuchs im Traum — sagt dir, in einer Lage den indirekten Weg zu wählen. Der direkte Zugang funktioniert nicht. Oder: Jemand täuscht dich — öffne die Augen.', es: 'Zorro en sueños — te dice que tomes el camino indirecto en una situación. El enfoque directo no funciona. O: alguien te engaña — abre los ojos.', pt: 'Raposa em sonho — diz-te para tomares o caminho indireto numa situação. A abordagem direta não funciona. Ou: alguém te engana — abre os olhos.', fr: 'Renard en rêve — te dit d\'emprunter la voie indirecte dans une situation. L\'approche directe ne marche pas. Ou : quelqu\'un te trompe — ouvre les yeux.', ja: '夢の中のキツネ——ある状況で回り道を行けと告げる。直接の接近では解けない。あるいは、誰かがあなたを欺いている——目を開け。' },
    shadow: { tr: 'Manipülasyon ve sahtekarlık. Zeka etik olmaksızın kullanılırsa tilki — yolsuz politikacı, dolandırıcı.', en: 'Manipulation and dishonesty. Intelligence used without ethics turns the fox into the corrupt politician, the swindler.', de: 'Manipulation und Unehrlichkeit. Wird Intelligenz ohne Ethik gebraucht, wird der Fuchs zum korrupten Politiker, zum Betrüger.', es: 'Manipulación y deshonestidad. La inteligencia usada sin ética convierte al zorro en el político corrupto, el estafador.', pt: 'Manipulação e desonestidade. A inteligência usada sem ética transforma a raposa no político corrupto, no vigarista.', fr: 'Manipulation et malhonnêteté. L\'intelligence employée sans éthique fait du renard le politicien corrompu, l\'escroc.', ja: '操作と不誠実。倫理なき知が用いられれば、キツネは腐敗した政治家、詐欺師となる。' },
    whenAppears: { tr: 'Doğrudan yaklaşımın işe yaramadığı bir durumda, yaratıcı stratejiye ihtiyaç duyduğunda, oyunun kurallarını yeniden yazman gereken anda.', en: 'In a situation where the direct approach fails, when you need creative strategy, when you must rewrite the rules of the game.', de: 'In einer Lage, in der der direkte Weg scheitert, wenn du kreative Strategie brauchst, wenn du die Regeln des Spiels neu schreiben musst.', es: 'En una situación donde el enfoque directo falla, cuando necesitas estrategia creativa, cuando debes reescribir las reglas del juego.', pt: 'Numa situação onde a abordagem direta falha, quando precisas de estratégia criativa, quando deves reescrever as regras do jogo.', fr: 'Dans une situation où l\'approche directe échoue, quand tu as besoin d\'une stratégie créative, quand tu dois réécrire les règles du jeu.', ja: '直接の手立てが通じぬ状況で、創造的な戦略を要するとき、ゲームの規則を書き換えねばならぬときに。' },
    traditions: [
      { culture: { tr: 'Japonya', en: 'Japanese', de: 'Japanisch', es: 'Japonés', pt: 'Japonês', fr: 'Japonais', ja: '日本' }, meaning: { tr: 'Kitsune — dokuz kuyruklu tilki ruhu. Şekil değiştirir, ya yardım eder ya tuzak kurar. İnari tanrıçanın habercisi.', en: 'Kitsune — the nine-tailed fox spirit. A shapeshifter who either aids or sets traps. Messenger of the goddess Inari.', de: 'Kitsune — der neunschwänzige Fuchsgeist. Ein Gestaltwandler, der entweder hilft oder Fallen stellt. Bote der Göttin Inari.', es: 'Kitsune — el espíritu zorro de nueve colas. Un cambiaformas que ayuda o tiende trampas. Mensajero de la diosa Inari.', pt: 'Kitsune — o espírito raposa de nove caudas. Um metamorfo que ajuda ou arma armadilhas. Mensageiro da deusa Inari.', fr: 'Kitsune — l\'esprit renard à neuf queues. Un métamorphe qui aide ou tend des pièges. Messager de la déesse Inari.', ja: 'キツネ——九尾の狐の霊。姿を変え、助けることも罠を仕掛けることもある。稲荷神の使い。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Coyote (kuzen ruh) — yaratıcı ve yıkıcı. Dünyaya hem akıl hem kaos getiren.', en: 'Coyote (kin-spirit) — creator and destroyer. The one who brought both reason and chaos to the world.', de: 'Kojote (verwandter Geist) — Schöpfer und Zerstörer. Der, der sowohl Vernunft als auch Chaos in die Welt brachte.', es: 'Coyote (espíritu pariente) — creador y destructor. El que trajo al mundo tanto la razón como el caos.', pt: 'Coiote (espírito aparentado) — criador e destruidor. Aquele que trouxe ao mundo tanto a razão como o caos.', fr: 'Coyote (esprit parent) — créateur et destructeur. Celui qui apporta au monde la raison comme le chaos.', ja: 'コヨーテ（縁ある霊）——創造者にして破壊者。世界に理性と混沌の双方をもたらした者。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Diplomasi ve sezginin sembolü. Druidler tilki tüyüyle rüya gönderir.', en: 'Symbol of diplomacy and intuition. The Druids sent dreams using fox fur.', de: 'Symbol der Diplomatie und Intuition. Die Druiden sandten mit Fuchspelz Träume.', es: 'Símbolo de la diplomacia y la intuición. Los druidas enviaban sueños con piel de zorro.', pt: 'Símbolo da diplomacia e da intuição. Os druidas enviavam sonhos com pele de raposa.', fr: 'Symbole de la diplomatie et de l\'intuition. Les druides envoyaient des rêves au moyen de fourrure de renard.', ja: '外交と直感の象徴。ドルイドはキツネの毛皮を用いて夢を送った。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Halk masallarında daima kazanan zeki kahraman. "Aklını kullanan tilki, zorlukları aşar."', en: 'In folk tales, the clever hero who always wins. "The fox who uses its wits overcomes hardship."', de: 'In Volksmärchen der kluge Held, der stets gewinnt. "Der Fuchs, der seinen Verstand gebraucht, überwindet die Not."', es: 'En los cuentos populares, el héroe astuto que siempre vence. "El zorro que usa su ingenio supera las dificultades."', pt: 'Nos contos populares, o herói astuto que sempre vence. "A raposa que usa a inteligência supera as dificuldades."', fr: 'Dans les contes populaires, le héros rusé qui gagne toujours. "Le renard qui use de son esprit surmonte les épreuves."', ja: '民話においては常に勝つ賢き英雄。「知恵を使うキツネは困難を乗り越える。」' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Hu jing — bin yaşına ulaşan tilki insana dönüşür. Şehvet ve hile sembolü.', en: 'Hu jing — a fox that reaches a thousand years turns into a human. Symbol of lust and deceit.', de: 'Hu jing — ein Fuchs, der tausend Jahre erreicht, verwandelt sich in einen Menschen. Symbol der Lust und der List.', es: 'Hu jing — un zorro que alcanza los mil años se convierte en humano. Símbolo de la lujuria y el engaño.', pt: 'Hu jing — uma raposa que atinge os mil anos transforma-se em humano. Símbolo da luxúria e do engano.', fr: 'Hu jing — un renard qui atteint mille ans se change en humain. Symbole de la luxure et de la ruse.', ja: '狐精——千年に達したキツネは人に化ける。色欲と欺きの象徴。' } },
    ],
    myths: [
      { tr: 'Kitsune Efsaneleri: Japonya\'da bir tilkinin 100 yaşına gelince beyaz olduğu, 1000 yaşına gelince 9 kuyruk açtığı ve tanrısallaştığı söylenir.', en: 'Kitsune Legends: In Japan it is said that at 100 years a fox turns white, and at 1,000 years it unfurls nine tails and becomes divine.', de: 'Kitsune-Legenden: In Japan heißt es, ein Fuchs werde mit 100 Jahren weiß und entfalte mit 1.000 Jahren neun Schwänze und werde göttlich.', es: 'Leyendas Kitsune: En Japón se dice que a los 100 años un zorro se vuelve blanco, y a los 1000 años despliega nueve colas y se vuelve divino.', pt: 'Lendas Kitsune: No Japão diz-se que aos 100 anos uma raposa se torna branca, e aos 1000 anos abre nove caudas e torna-se divina.', fr: 'Légendes Kitsune : Au Japon, on dit qu\'à 100 ans un renard devient blanc, et qu\'à 1 000 ans il déploie neuf queues et devient divin.', ja: 'キツネ伝説：日本では、キツネは百歳で白くなり、千歳で九つの尾を開き、神格を得るという。' },
      { tr: 'Aesop\'un Tilkisi: "Üzümlere ulaşamayınca ekşi olduğunu söyleyen tilki" — Batı medeniyetinin en eski hilebaz hikayesi.', en: 'Aesop\'s Fox: "The fox who, unable to reach the grapes, calls them sour" — Western civilization\'s oldest trickster tale.', de: 'Äsops Fuchs: "Der Fuchs, der die Trauben nicht erreichen kann und sie für sauer erklärt" — die älteste Schelmenfabel der westlichen Zivilisation.', es: 'El zorro de Esopo: "El zorro que, al no alcanzar las uvas, las llama agrias" — el más antiguo cuento del embaucador en la civilización occidental.', pt: 'A raposa de Esopo: "A raposa que, não alcançando as uvas, as diz azedas" — o mais antigo conto do trapaceiro na civilização ocidental.', fr: 'Le renard d\'Ésope : "Le renard qui, ne pouvant atteindre les raisins, les déclare trop verts" — le plus ancien conte de filou de la civilisation occidentale.', ja: 'イソップのキツネ：「ブドウに手が届かず、酸っぱいと言うキツネ」——西洋文明で最も古いトリックスターの話。' },
    ],
  },

  // ─── a012 Yunus ─────────────────────────────────────────────────────────
  a012: {
    jung: { tr: '"Sevinç Rehberi" arketipi. Yunus, duygu denizinde özgürce yüzen bilinç — neşeyle bilgelik aynı bedende.', en: 'The "Joy-Guide" archetype. The dolphin is consciousness swimming freely in the sea of feeling — joy and wisdom in one body.', de: 'Der Archetyp des "Freudenführers". Der Delfin ist das Bewusstsein, das frei im Meer der Gefühle schwimmt — Freude und Weisheit in einem Leib.', es: 'El arquetipo del "Guía de la Alegría". El delfín es la conciencia que nada libre en el mar del sentimiento — alegría y sabiduría en un mismo cuerpo.', pt: 'O arquétipo do "Guia da Alegria". O golfinho é a consciência que nada livre no mar do sentimento — alegria e sabedoria num mesmo corpo.', fr: 'L\'archétype du "Guide de la joie". Le dauphin est la conscience qui nage librement dans la mer du sentiment — joie et sagesse dans un même corps.', ja: '「歓びの導き手」の元型。イルカは感情の海を自由に泳ぐ意識——歓びと知恵が一つの体に。' },
    dream: { tr: 'Yunus rüyada — duygusal akış geri geldi. Suyun üzerinden atlıyorsa: kalbin neşeleniyor. Sana eşlik ediyorsa: yalnız değilsin, ruh dostları yakın.', en: 'Dolphin in dream — emotional flow has returned. Leaping above the water: your heart is rejoicing. Accompanying you: you are not alone, soul friends are near.', de: 'Delfin im Traum — der emotionale Fluss ist zurückgekehrt. Springt er über das Wasser: Dein Herz frohlockt. Begleitet er dich: Du bist nicht allein, Seelenfreunde sind nah.', es: 'Delfín en sueños — el flujo emocional ha vuelto. Si salta sobre el agua: tu corazón se alegra. Si te acompaña: no estás solo, amigos del alma están cerca.', pt: 'Golfinho em sonho — o fluxo emocional regressou. Se salta sobre a água: o teu coração regozija-se. Se te acompanha: não estás só, amigos da alma estão perto.', fr: 'Dauphin en rêve — le flux émotionnel est revenu. Bondissant au-dessus de l\'eau : ton cœur se réjouit. T\'accompagnant : tu n\'es pas seul, des amis d\'âme sont proches.', ja: '夢の中のイルカ——感情の流れが戻ってきた。水面を跳ねるなら、あなたの心は喜んでいる。付き添うなら、あなたは独りではなく、魂の友が近くにいる。' },
    shadow: { tr: 'Hep iyimser görünme baskısı. Her şeyi "neşeyle" karşılamaya çalışmak, gerçek acıyı bastırırsa — yunus boğulur.', en: 'The pressure to always appear optimistic. If meeting everything "with joy" suppresses real pain — the dolphin drowns.', de: 'Der Druck, stets optimistisch zu erscheinen. Wenn alles "mit Freude" zu begegnen den echten Schmerz unterdrückt — ertrinkt der Delfin.', es: 'La presión de parecer siempre optimista. Si recibir todo "con alegría" reprime el dolor real — el delfín se ahoga.', pt: 'A pressão de parecer sempre otimista. Se receber tudo "com alegria" reprime a dor real — o golfinho afoga-se.', fr: 'La pression de toujours paraître optimiste. Si accueillir tout "avec joie" refoule la vraie douleur — le dauphin se noie.', ja: '常に楽観的に見せねばならぬ重圧。何もかもを「歓びで」迎えようとして真の痛みを抑え込めば——イルカは溺れる。' },
    whenAppears: { tr: 'Uzun bir hüzünden sonra, çocuksu sevincini geri istediğinde, suyla/denizle iletişiminin açıldığı anda.', en: 'After a long sorrow, when you want your childlike joy back, at the moment communion with water or sea opens.', de: 'Nach langer Trauer, wenn du deine kindliche Freude zurückwillst, im Moment, da sich die Verbindung zu Wasser oder Meer öffnet.', es: 'Tras una larga tristeza, cuando quieres recuperar tu alegría infantil, en el momento en que se abre la comunión con el agua o el mar.', pt: 'Após uma longa tristeza, quando queres recuperar a tua alegria infantil, no momento em que se abre a comunhão com a água ou o mar.', fr: 'Après un long chagrin, quand tu veux retrouver ta joie d\'enfant, au moment où s\'ouvre la communion avec l\'eau ou la mer.', ja: '長い悲しみののち、幼子のような歓びを取り戻したいとき、水や海との交わりが開かれる瞬間に。' },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Apollon\'un kutsal hayvanı. Boğulanları kurtaran rehber. Delphi tapınağının habercisi.', en: 'Apollo\'s sacred animal. The guide who rescues the drowning. Herald of the temple of Delphi.', de: 'Apollons heiliges Tier. Der Führer, der die Ertrinkenden rettet. Herold des Tempels von Delphi.', es: 'El animal sagrado de Apolo. El guía que salva a los que se ahogan. Heraldo del templo de Delfos.', pt: 'O animal sagrado de Apolo. O guia que salva os que se afogam. Arauto do templo de Delfos.', fr: 'L\'animal sacré d\'Apollon. Le guide qui sauve ceux qui se noient. Héraut du temple de Delphes.', ja: 'アポロンの聖なる動物。溺れる者を救う導き手。デルフォイの神殿の使者。' } },
      { culture: { tr: 'Sumer', en: 'Sumerian', de: 'Sumerisch', es: 'Sumerio', pt: 'Sumério', fr: 'Sumérien', ja: 'シュメール' }, meaning: { tr: 'Enki — bilgelik tanrısı yunusla yolculuk eder. Tatlı su ve bilgeliğin kuşağı.', en: 'Enki — the god of wisdom travels with the dolphin. The companion of fresh water and wisdom.', de: 'Enki — der Gott der Weisheit reist mit dem Delfin. Der Gefährte des Süßwassers und der Weisheit.', es: 'Enki — el dios de la sabiduría viaja con el delfín. El compañero del agua dulce y la sabiduría.', pt: 'Enki — o deus da sabedoria viaja com o golfinho. O companheiro da água doce e da sabedoria.', fr: 'Enki — le dieu de la sagesse voyage avec le dauphin. Le compagnon de l\'eau douce et de la sagesse.', ja: 'エンキ——知恵の神はイルカと旅する。淡水と知恵の伴侶。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Mesih sembolü — denizden insanı çıkaran kurtarıcı. Erken katakomblarda sık çizilen motif.', en: 'Symbol of the Messiah — the savior who draws humanity from the sea. A frequent motif in the early catacombs.', de: 'Symbol des Messias — der Erlöser, der den Menschen aus dem Meer zieht. Ein häufiges Motiv in den frühen Katakomben.', es: 'Símbolo del Mesías — el salvador que saca al hombre del mar. Motivo frecuente en las primeras catacumbas.', pt: 'Símbolo do Messias — o salvador que tira o homem do mar. Motivo frequente nas primeiras catacumbas.', fr: 'Symbole du Messie — le sauveur qui retire l\'homme de la mer. Un motif fréquent dans les premières catacombes.', ja: 'メシアの象徴——海から人を引き上げる救い主。初期のカタコンベに頻出する図像。' } },
      { culture: { tr: 'Maori', en: 'Maori', de: 'Maori', es: 'Maorí', pt: 'Maori', fr: 'Maori', ja: 'マオリ' }, meaning: { tr: 'Taniwha — denizin ruhu, kabilenin koruyucusu. Yardım çağrısına gelir.', en: 'Taniwha — spirit of the sea, protector of the tribe. Comes when called for aid.', de: 'Taniwha — Geist des Meeres, Beschützer des Stammes. Kommt, wenn man um Hilfe ruft.', es: 'Taniwha — espíritu del mar, protector de la tribu. Acude cuando se le pide auxilio.', pt: 'Taniwha — espírito do mar, protetor da tribo. Vem quando é chamado em auxílio.', fr: 'Taniwha — esprit de la mer, protecteur de la tribu. Il vient quand on l\'appelle à l\'aide.', ja: 'タニファ——海の霊、部族の守護者。助けを求められれば現れる。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Akdeniz halklarının dost ruhu. Balıkçılara yol gösteren akrabası.', en: 'Friend-spirit of Mediterranean peoples. A kin who guides fishermen.', de: 'Freundgeist der Mittelmeervölker. Ein Verwandter, der den Fischern den Weg weist.', es: 'Espíritu amigo de los pueblos mediterráneos. Un pariente que guía a los pescadores.', pt: 'Espírito amigo dos povos mediterrânicos. Um parente que guia os pescadores.', fr: 'Esprit ami des peuples méditerranéens. Un parent qui guide les pêcheurs.', ja: '地中海の人々の友なる霊。漁師に道を示す縁者。' } },
    ],
    myths: [
      { tr: 'Arion ve Yunus: Yunan şairi Arion gemiciler tarafından denize atılır, bir yunus onu sırtında alıp kıyıya götürür. Sanat ve doğa arasındaki kardeşliğin sembolü.', en: 'Arion and the Dolphin: The Greek poet Arion is thrown into the sea by sailors; a dolphin takes him on its back to shore. A symbol of the kinship between art and nature.', de: 'Arion und der Delfin: Der griechische Dichter Arion wird von Seeleuten ins Meer geworfen; ein Delfin trägt ihn auf seinem Rücken ans Ufer. Ein Symbol der Verwandtschaft von Kunst und Natur.', es: 'Arión y el delfín: El poeta griego Arión es arrojado al mar por unos marineros; un delfín lo lleva a la orilla sobre su lomo. Símbolo del parentesco entre el arte y la naturaleza.', pt: 'Aríon e o golfinho: O poeta grego Aríon é lançado ao mar por marinheiros; um golfinho leva-o à costa sobre as suas costas. Símbolo do parentesco entre a arte e a natureza.', fr: 'Arion et le dauphin : Le poète grec Arion est jeté à la mer par des marins ; un dauphin le porte sur son dos jusqu\'au rivage. Symbole de la parenté entre l\'art et la nature.', ja: 'アリオンとイルカ：ギリシアの詩人アリオンは船乗りたちに海へ投げ込まれるが、イルカが背に乗せて岸へ運ぶ。芸術と自然の兄弟の絆の象徴。' },
      { tr: 'Yunus Emre ve Adı: Bir rivayete göre Yunus Emre adını, Yunus peygamberin balıktan çıkışı gibi içsel bir dirilişten alır — derinden yüzeye gelen aşk.', en: 'Yunus Emre and His Name: According to one tradition, the Sufi poet Yunus Emre takes his name from an inner resurrection like the prophet Jonah\'s emergence from the fish — love rising from the depths to the surface.', de: 'Yunus Emre und sein Name: Einer Überlieferung nach erhält der Sufi-Dichter Yunus Emre seinen Namen von einer inneren Auferstehung gleich dem Hervortreten des Propheten Jonas aus dem Fisch — Liebe, die aus der Tiefe an die Oberfläche steigt.', es: 'Yunus Emre y su nombre: Según una tradición, el poeta sufí Yunus Emre toma su nombre de una resurrección interior como la salida del profeta Jonás del pez — amor que sube de las profundidades a la superficie.', pt: 'Yunus Emre e o seu nome: Segundo uma tradição, o poeta sufi Yunus Emre toma o seu nome de uma ressurreição interior como a saída do profeta Jonas do peixe — amor que sobe das profundezas à superfície.', fr: 'Yunus Emre et son nom : Selon une tradition, le poète soufi Yunus Emre tient son nom d\'une résurrection intérieure semblable à la sortie du prophète Jonas du poisson — un amour montant des profondeurs à la surface.', ja: 'ユヌス・エムレとその名：ある伝承によれば、スーフィー詩人ユヌス・エムレはその名を、預言者ヨナが魚から出たような内なる復活から得た——深みから水面へと昇る愛。' },
    ],
  },

  // ─── a013 Kaplumbağa ────────────────────────────────────────────────────
  a013: {
    jung: { tr: '"Kadim Bilge" arketipi. Yavaş, sabırlı, uzun ömürlü. Kabuğunu evine taşıyan — içsel istikrarın sembolü.', en: 'The "Ancient Sage" archetype. Slow, patient, long-lived. The one who carries its home as its shell — symbol of inner stability.', de: 'Der Archetyp des "uralten Weisen". Langsam, geduldig, langlebig. Der, der sein Heim als Panzer trägt — Symbol der inneren Stabilität.', es: 'El arquetipo del "Sabio Antiguo". Lento, paciente, longevo. El que lleva su hogar como caparazón — símbolo de la estabilidad interior.', pt: 'O arquétipo do "Sábio Antigo". Lento, paciente, longevo. Aquele que carrega o seu lar como carapaça — símbolo da estabilidade interior.', fr: 'L\'archétype du "Sage ancien". Lent, patient, longévif. Celui qui porte sa demeure comme carapace — symbole de la stabilité intérieure.', ja: '「古き賢者」の元型。緩やかで、辛抱強く、長命。我が家を甲羅として背負う者——内なる安定の象徴。' },
    dream: { tr: 'Kaplumbağa rüyada — acele etmemen gerekiyor. Kabuğuna çekiliyorsa: korunma zamanı. Yumurtluyorsa: uzun vadeli tohumlar atıyorsun.', en: 'Turtle in dream — you must not rush. Withdrawing into its shell: time for protection. Laying eggs: you are planting long-term seeds.', de: 'Schildkröte im Traum — du darfst dich nicht hetzen. Zieht sie sich in den Panzer zurück: Zeit des Schutzes. Legt sie Eier: Du säst langfristige Samen.', es: 'Tortuga en sueños — no debes apresurarte. Si se repliega en su caparazón: tiempo de protección. Si pone huevos: estás sembrando semillas a largo plazo.', pt: 'Tartaruga em sonho — não deves apressar-te. Se se recolhe na carapaça: tempo de proteção. Se põe ovos: estás a semear sementes de longo prazo.', fr: 'Tortue en rêve — tu ne dois pas te précipiter. Se retirant dans sa carapace : temps de protection. Pondant des œufs : tu sèmes des graines à long terme.', ja: '夢の中のカメ——急いではならない。甲羅に引きこもるなら、守りの時。卵を産むなら、あなたは長き先の種を蒔いている。' },
    shadow: { tr: 'Aşırı temkin. "Sonra"ya erteleyerek ömrü tamamlamak. Kaplumbağa hızlıdır kendi yolunda — ama hiç çıkmazsa hapse dönüşür.', en: 'Excessive caution. Completing a lifetime by postponing to "later". The turtle is swift on its own path — but if it never emerges, the shell becomes a prison.', de: 'Übermäßige Vorsicht. Ein Leben damit zu vollenden, auf "später" zu verschieben. Die Schildkröte ist schnell auf ihrem eigenen Weg — kommt sie aber nie hervor, wird der Panzer zum Gefängnis.', es: 'Cautela excesiva. Completar una vida posponiéndolo todo para "después". La tortuga es veloz en su propio camino — pero si nunca emerge, el caparazón se vuelve prisión.', pt: 'Cautela excessiva. Completar uma vida adiando tudo para "depois". A tartaruga é veloz no seu próprio caminho — mas se nunca emerge, a carapaça torna-se prisão.', fr: 'Prudence excessive. Achever une vie en remettant tout à "plus tard". La tortue est rapide sur son propre chemin — mais si elle ne sort jamais, la carapace devient prison.', ja: '過度の慎重さ。何もかも「後で」に先延ばしして一生を終えること。カメは己の道では速い——だが決して出てこなければ、甲羅は牢獄となる。' },
    whenAppears: { tr: 'Acele kararlardan vazgeçmen gerektiğinde, uzun soluklu projelerde, yaşlılık bilgeliğine açıldığında.', en: 'When you must renounce hasty decisions, in long-haul projects, when opening to the wisdom of age.', de: 'Wenn du auf überstürzte Entscheidungen verzichten musst, bei langfristigen Vorhaben, wenn du dich der Weisheit des Alters öffnest.', es: 'Cuando debes renunciar a decisiones precipitadas, en proyectos de largo aliento, cuando te abres a la sabiduría de la edad.', pt: 'Quando deves renunciar a decisões precipitadas, em projetos de longo fôlego, quando te abres à sabedoria da idade.', fr: 'Quand tu dois renoncer aux décisions hâtives, dans les projets de longue haleine, quand tu t\'ouvres à la sagesse de l\'âge.', ja: '性急な決断を捨てねばならぬとき、長丁場のプロジェクトで、老いの知恵へと開かれるときに。' },
    traditions: [
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Dört kutsal hayvandan biri (Xuanwu). Kuzey, kış, su ve uzun ömrün koruyucusu. Yaratılışın temeli.', en: 'One of the Four Sacred Animals (Xuanwu). Guardian of the north, winter, water, and longevity. The foundation of creation.', de: 'Eines der Vier Heiligen Tiere (Xuanwu). Hüter des Nordens, des Winters, des Wassers und der Langlebigkeit. Das Fundament der Schöpfung.', es: 'Uno de los Cuatro Animales Sagrados (Xuanwu). Guardián del norte, el invierno, el agua y la longevidad. El fundamento de la creación.', pt: 'Um dos Quatro Animais Sagrados (Xuanwu). Guardião do norte, do inverno, da água e da longevidade. O fundamento da criação.', fr: 'L\'un des Quatre Animaux Sacrés (Xuanwu). Gardien du nord, de l\'hiver, de l\'eau et de la longévité. Le fondement de la création.', ja: '四神の一つ（玄武）。北、冬、水、そして長寿の守護者。創造の礎。' } },
      { culture: { tr: 'Hint', en: 'Hindu', de: 'Hinduistisch', es: 'Hindú', pt: 'Hindu', fr: 'Hindou', ja: 'ヒンドゥー' }, meaning: { tr: 'Vishnu\'nun Kurma avatarı — okyanus çalkalanırken dünyayı sırtında taşıyan kaplumbağa.', en: 'Vishnu\'s Kurma avatar — the turtle bearing the world on its back during the churning of the ocean.', de: 'Vishnus Kurma-Avatar — die Schildkröte, die während des Quirlens des Ozeans die Welt auf ihrem Rücken trägt.', es: 'El avatar Kurma de Vishnú — la tortuga que carga el mundo sobre su lomo durante el batido del océano.', pt: 'O avatar Kurma de Vishnu — a tartaruga que carrega o mundo sobre as costas durante a agitação do oceano.', fr: 'L\'avatar Kurma de Vishnou — la tortue qui porte le monde sur son dos durant le barattage de l\'océan.', ja: 'ヴィシュヌのクールマ・アヴァターラ——大海を攪拌するあいだ、世界をその背に担うカメ。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: '"Kaplumbağa Adası" — Kuzey Amerika kıtasının atası. Dünyanın kendisi onun sırtında.', en: '"Turtle Island" — the ancestor of the North American continent. The world itself rests on its back.', de: '"Schildkröteninsel" — der Ahn des nordamerikanischen Kontinents. Die Welt selbst ruht auf ihrem Rücken.', es: '"Isla Tortuga" — el ancestro del continente norteamericano. El mundo mismo reposa sobre su lomo.', pt: '"Ilha Tartaruga" — o ancestral do continente norte-americano. O próprio mundo repousa sobre as suas costas.', fr: '"L\'Île de la Tortue" — l\'ancêtre du continent nord-américain. Le monde lui-même repose sur son dos.', ja: '「亀の島」——北米大陸の祖。世界そのものがその背に乗っている。' } },
      { culture: { tr: 'Afrika', en: 'African', de: 'Afrikanisch', es: 'Africano', pt: 'Africano', fr: 'Africain', ja: 'アフリカ' }, meaning: { tr: 'Anansi masallarında zeki kahraman. Yavaşlığın altında gizli akıl.', en: 'In Anansi tales, the clever hero. Hidden cunning beneath slowness.', de: 'In den Anansi-Geschichten der kluge Held. Verborgene List unter der Langsamkeit.', es: 'En los cuentos de Anansi, el héroe astuto. Astucia oculta bajo la lentitud.', pt: 'Nos contos de Anansi, o herói astuto. Astúcia oculta sob a lentidão.', fr: 'Dans les contes d\'Anansi, le héros rusé. Une ruse cachée sous la lenteur.', ja: 'アナンシの物語における賢き英雄。緩慢さの下に隠された知略。' } },
      { culture: { tr: 'Japonya', en: 'Japanese', de: 'Japanisch', es: 'Japonés', pt: 'Japonês', fr: 'Japonais', ja: '日本' }, meaning: { tr: '"Minogame" — 10000 yıl yaşayan kaplumbağa. Uzun ömür ve şansın simgesi.', en: '"Minogame" — the turtle that lives 10,000 years. Symbol of longevity and luck.', de: '"Minogame" — die Schildkröte, die 10.000 Jahre lebt. Symbol der Langlebigkeit und des Glücks.', es: '"Minogame" — la tortuga que vive 10 000 años. Símbolo de la longevidad y la suerte.', pt: '"Minogame" — a tartaruga que vive 10 000 anos. Símbolo da longevidade e da sorte.', fr: '"Minogame" — la tortue qui vit 10 000 ans. Symbole de la longévité et de la chance.', ja: '「蓑亀（みのがめ）」——一万年生きるカメ。長寿と幸運の象徴。' } },
    ],
    myths: [
      { tr: 'Kurma Avatarı: Hint mitolojisinde tanrılar ve şeytanlar ölümsüzlük iksiri için okyanusu çalkalar. Vishnu kaplumbağa olur, dağı sırtında destekler — yaratılışın sabit ekseni.', en: 'The Kurma Avatar: In Hindu mythology, gods and demons churn the ocean for the elixir of immortality. Vishnu becomes a turtle and supports the mountain on his back — the steady axis of creation.', de: 'Der Kurma-Avatar: In der hinduistischen Mythologie quirlen Götter und Dämonen den Ozean nach dem Elixier der Unsterblichkeit. Vishnu wird zur Schildkröte und stützt den Berg auf seinem Rücken — die stete Achse der Schöpfung.', es: 'El avatar Kurma: En la mitología hindú, dioses y demonios baten el océano por el elixir de la inmortalidad. Vishnú se vuelve tortuga y sostiene la montaña sobre su lomo — el eje firme de la creación.', pt: 'O avatar Kurma: Na mitologia hindu, deuses e demónios agitam o oceano pelo elixir da imortalidade. Vishnu torna-se tartaruga e sustenta a montanha sobre as costas — o eixo firme da criação.', fr: 'L\'avatar Kurma : Dans la mythologie hindoue, dieux et démons barattent l\'océan pour l\'élixir d\'immortalité. Vishnou devient tortue et soutient la montagne sur son dos — l\'axe stable de la création.', ja: 'クールマ・アヴァターラ：ヒンドゥー神話において、神々と魔神は不死の霊薬を求めて大海を攪拌する。ヴィシュヌはカメとなり、山をその背で支える——創造の不動の軸。' },
      { tr: 'Kaplumbağa Adası: Kızılderili kozmolojisinde dünya sular üzerinde yüzen bir kaplumbağanın sırtında durur. Toprak — onun zırhının üstünde toplanmış çamur.', en: 'Turtle Island: In Native American cosmology, the world rests on the back of a turtle floating upon the waters. The earth is mud gathered atop its shell.', de: 'Schildkröteninsel: In der indianischen Kosmologie ruht die Welt auf dem Rücken einer Schildkröte, die auf den Wassern treibt. Die Erde ist Schlamm, der sich auf ihrem Panzer angesammelt hat.', es: 'Isla Tortuga: En la cosmología nativa americana, el mundo reposa sobre el lomo de una tortuga que flota sobre las aguas. La tierra es barro acumulado sobre su caparazón.', pt: 'Ilha Tartaruga: Na cosmologia nativo-americana, o mundo repousa sobre as costas de uma tartaruga que flutua sobre as águas. A terra é lama acumulada sobre a sua carapaça.', fr: 'L\'Île de la Tortue : Dans la cosmologie amérindienne, le monde repose sur le dos d\'une tortue flottant sur les eaux. La terre est de la boue amassée sur sa carapace.', ja: '亀の島：ネイティブ・アメリカンの宇宙観では、世界は水上に浮かぶカメの背に乗っている。大地とは、その甲羅の上に積もった泥である。' },
    ],
  },

  // ─── a014 Yılan ─────────────────────────────────────────────────────────
  a014: {
    jung: { tr: '"Dönüşüm" arketipi. Ouroboros — kuyruğunu yiyen yılan. Ölüm ve doğum aynı ağzın iki ucu. Kundalini enerjisinin omurga boyunca yükseliş hayvanı.', en: 'The "Transformation" archetype. Ouroboros — the serpent devouring its own tail. Death and birth are two ends of the same mouth. The animal of Kundalini energy rising along the spine.', de: 'Der Archetyp der "Verwandlung". Ouroboros — die Schlange, die ihren eigenen Schwanz verschlingt. Tod und Geburt sind zwei Enden desselben Mundes. Das Tier der Kundalini-Energie, die entlang der Wirbelsäule aufsteigt.', es: 'El arquetipo de la "Transformación". Ouroboros — la serpiente que devora su propia cola. Muerte y nacimiento son dos extremos de la misma boca. El animal de la energía Kundalini que asciende por la columna.', pt: 'O arquétipo da "Transformação". Ouroboros — a serpente que devora a própria cauda. Morte e nascimento são duas pontas da mesma boca. O animal da energia Kundalini que sobe pela coluna.', fr: 'L\'archétype de la "Transformation". Ouroboros — le serpent qui dévore sa propre queue. Mort et naissance sont les deux bouts d\'une même bouche. L\'animal de l\'énergie Kundalini qui s\'élève le long de la colonne.', ja: '「変容」の元型。ウロボロス——自らの尾を喰らう蛇。死と誕生は同じ口の両端。背骨に沿って昇るクンダリーニのエネルギーの動物。' },
    dream: { tr: 'Yılan rüyada — derin bir dönüşüm sürecindesin. Isırıyorsa: bastırdığın bir gerçek seni uyandırıyor. Deri değiştiriyorsa: eski sen ölüyor.', en: 'Serpent in dream — you are in a profound process of transformation. If it bites: a truth you have suppressed is waking you. If it sheds skin: the old self is dying.', de: 'Schlange im Traum — du bist in einem tiefgreifenden Verwandlungsprozess. Beißt sie: Eine Wahrheit, die du unterdrückt hast, weckt dich. Häutet sie sich: Das alte Selbst stirbt.', es: 'Serpiente en sueños — estás en un profundo proceso de transformación. Si muerde: una verdad que has reprimido te despierta. Si muda de piel: el viejo yo muere.', pt: 'Serpente em sonho — estás num profundo processo de transformação. Se morde: uma verdade que reprimiste desperta-te. Se muda de pele: o velho eu morre.', fr: 'Serpent en rêve — tu es dans un profond processus de transformation. S\'il mord : une vérité que tu as réprimée te réveille. S\'il mue : l\'ancien soi meurt.', ja: '夢の中の蛇——あなたは深い変容の過程にある。噛むなら、抑え込んだ真実があなたを目覚めさせている。脱皮するなら、古い自己が死につつある。' },
    shadow: { tr: 'Aldatma, manipülasyon, zehir. Yılan enerjisi dönüştürülmezse — pasif-agresif kontrol, gizli sokuş.', en: 'Deception, manipulation, venom. If serpent energy is not transmuted — passive-aggressive control, hidden striking.', de: 'Täuschung, Manipulation, Gift. Wird die Schlangenenergie nicht gewandelt — passiv-aggressive Kontrolle, verdeckter Biss.', es: 'Engaño, manipulación, veneno. Si la energía serpiente no se transmuta — control pasivo-agresivo, ataque oculto.', pt: 'Engano, manipulação, veneno. Se a energia serpente não for transmutada — controlo passivo-agressivo, ataque oculto.', fr: 'Tromperie, manipulation, venin. Si l\'énergie du serpent n\'est pas transmuée — contrôle passif-agressif, morsure cachée.', ja: '欺き、操作、毒。蛇のエネルギーが変成されなければ——受動的攻撃による支配、ひそかな一咬み。' },
    whenAppears: { tr: 'Kimlik değişiminde, eski bir kalıbı bırakırken, derin şifa sürecinde, cinsel uyanışta, ölüm-yas süreçlerinde.', en: 'In identity change, when releasing an old pattern, in deep healing, in sexual awakening, in death-grief processes.', de: 'Bei einem Identitätswandel, wenn du ein altes Muster loslässt, in tiefer Heilung, im sexuellen Erwachen, in Trauerprozessen um den Tod.', es: 'En un cambio de identidad, al soltar un viejo patrón, en una sanación profunda, en el despertar sexual, en procesos de duelo por la muerte.', pt: 'Numa mudança de identidade, ao largar um velho padrão, numa cura profunda, no despertar sexual, em processos de luto pela morte.', fr: 'Dans un changement d\'identité, en lâchant un vieux schéma, dans une guérison profonde, dans l\'éveil sexuel, dans les processus de deuil de la mort.', ja: 'アイデンティティの変化のとき、古い型を手放すとき、深い癒しの過程、性的な目覚め、死と喪の過程に。' },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Asklepios\'un asası — şifa tanrısının iki yılanı. Modern tıp sembolü.', en: 'The staff of Asclepius — the two serpents of the god of healing. The modern symbol of medicine.', de: 'Der Stab des Asklepios — die zwei Schlangen des Heilgottes. Das moderne Symbol der Medizin.', es: 'El bastón de Asclepio — las dos serpientes del dios de la curación. El símbolo moderno de la medicina.', pt: 'O bastão de Asclépio — as duas serpentes do deus da cura. O símbolo moderno da medicina.', fr: 'Le bâton d\'Asclépios — les deux serpents du dieu de la guérison. Le symbole moderne de la médecine.', ja: 'アスクレピオスの杖——癒しの神の二匹の蛇。現代医学の象徴。' } },
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Wadjet — kobra tanrıça. Firavunların alın koruyucusu. Bilgeliğin gözü.', en: 'Wadjet — the cobra goddess. Protector of the pharaohs\' brow. The eye of wisdom.', de: 'Wadjet — die Kobragöttin. Beschützerin der Stirn der Pharaonen. Das Auge der Weisheit.', es: 'Wadjet — la diosa cobra. Protectora de la frente de los faraones. El ojo de la sabiduría.', pt: 'Wadjet — a deusa cobra. Protetora da fronte dos faraós. O olho da sabedoria.', fr: 'Ouadjet — la déesse cobra. Protectrice du front des pharaons. L\'œil de la sagesse.', ja: 'ウアジェト——コブラの女神。ファラオの額の守護者。知恵の目。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Kundalini — omurganın dibinde uyuyan ilahi enerji. Yedi çakra boyunca yükseliş.', en: 'Kundalini — the divine energy asleep at the base of the spine. Ascent through the seven chakras.', de: 'Kundalini — die göttliche Energie, die am Grunde der Wirbelsäule schläft. Aufstieg durch die sieben Chakren.', es: 'Kundalini — la energía divina que duerme en la base de la columna. Ascenso a través de los siete chakras.', pt: 'Kundalini — a energia divina que dorme na base da coluna. Ascensão pelos sete chakras.', fr: 'Kundalini — l\'énergie divine endormie à la base de la colonne. Ascension à travers les sept chakras.', ja: 'クンダリーニ——背骨の根もとに眠る神聖なエネルギー。七つのチャクラを貫いて昇る。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Cennetten kovulma — bilginin acı meyvesi. Aynı zamanda Musa\'nın tunç yılanı: şifa.', en: 'Expulsion from Eden — the bitter fruit of knowledge. Yet also Moses\'s bronze serpent: healing.', de: 'Die Vertreibung aus Eden — die bittere Frucht der Erkenntnis. Doch auch die eherne Schlange des Mose: Heilung.', es: 'La expulsión del Edén — el fruto amargo del conocimiento. Pero también la serpiente de bronce de Moisés: la curación.', pt: 'A expulsão do Éden — o fruto amargo do conhecimento. Mas também a serpente de bronze de Moisés: a cura.', fr: 'L\'expulsion de l\'Éden — le fruit amer de la connaissance. Mais aussi le serpent d\'airain de Moïse : la guérison.', ja: 'エデンからの追放——知の苦き果実。同時にモーセの青銅の蛇——癒し。' } },
      { culture: { tr: 'Türk Mitolojisi', en: 'Turkic Mythology', de: 'Türkische Mythologie', es: 'Mitología Túrquica', pt: 'Mitologia Túrquica', fr: 'Mythologie Turque', ja: 'テュルク神話' }, meaning: { tr: 'Şahmeran — yılan kraliçesi. Bilgelik, şifa, ölümsüzlük sırrını bilen kadın-yılan.', en: 'Shahmaran — the serpent queen. The woman-serpent who knows the secrets of wisdom, healing, and immortality.', de: 'Şahmeran — die Schlangenkönigin. Die Frau-Schlange, die die Geheimnisse von Weisheit, Heilung und Unsterblichkeit kennt.', es: 'Shahmaran — la reina serpiente. La mujer-serpiente que conoce los secretos de la sabiduría, la curación y la inmortalidad.', pt: 'Shahmaran — a rainha serpente. A mulher-serpente que conhece os segredos da sabedoria, da cura e da imortalidade.', fr: 'Shahmaran — la reine serpent. La femme-serpent qui connaît les secrets de la sagesse, de la guérison et de l\'immortalité.', ja: 'シャフマラン——蛇の女王。知恵、癒し、不死の秘密を知る女にして蛇。' } },
      { culture: { tr: 'Aztek', en: 'Aztec', de: 'Aztekisch', es: 'Azteca', pt: 'Asteca', fr: 'Aztèque', ja: 'アステカ' }, meaning: { tr: 'Quetzalcoatl — tüylü yılan tanrı. Bilgelik, kültür, dönüşümün getiricisi.', en: 'Quetzalcoatl — the feathered serpent god. Bringer of wisdom, culture, and transformation.', de: 'Quetzalcoatl — der gefiederte Schlangengott. Bringer von Weisheit, Kultur und Wandel.', es: 'Quetzalcóatl — el dios serpiente emplumada. Portador de sabiduría, cultura y transformación.', pt: 'Quetzalcoatl — o deus serpente emplumada. Portador de sabedoria, cultura e transformação.', fr: 'Quetzalcoatl — le dieu serpent à plumes. Porteur de sagesse, de culture et de transformation.', ja: 'ケツァルコアトル——羽毛ある蛇の神。知恵、文化、そして変容をもたらす者。' } },
    ],
    myths: [
      { tr: 'Şahmeran Efsanesi: Anadolu\'nun en kadim mitlerinden. Mağarada yaşayan, yarı kadın yarı yılan bilgelik kraliçesi. İhanetle ölür, ama suyunu içen kişi büyük bir şifacı olur.', en: 'The Shahmaran Legend: One of Anatolia\'s most ancient myths. The half-woman half-serpent queen of wisdom who lives in a cave. She dies by betrayal, yet whoever drinks her water becomes a great healer.', de: 'Die Şahmeran-Legende: Einer der ältesten Mythen Anatoliens. Die halb Frau, halb Schlange seiende Königin der Weisheit, die in einer Höhle lebt. Sie stirbt durch Verrat, doch wer ihr Wasser trinkt, wird ein großer Heiler.', es: 'La leyenda de Shahmaran: Uno de los mitos más antiguos de Anatolia. La reina de la sabiduría, mitad mujer mitad serpiente, que vive en una cueva. Muere por traición, pero quien bebe su agua se vuelve un gran sanador.', pt: 'A lenda de Shahmaran: Um dos mitos mais antigos da Anatólia. A rainha da sabedoria, meia mulher meia serpente, que vive numa caverna. Morre por traição, mas quem bebe a sua água torna-se um grande curandeiro.', fr: 'La légende de Shahmaran : L\'un des mythes les plus anciens de l\'Anatolie. La reine de la sagesse, mi-femme mi-serpent, qui vit dans une grotte. Elle meurt par trahison, mais quiconque boit son eau devient un grand guérisseur.', ja: 'シャフマラン伝説：アナトリア最古の神話の一つ。洞窟に住む、半身が女で半身が蛇の知恵の女王。裏切りによって死ぬが、その水を飲んだ者は偉大な癒し手となる。' },
      { tr: 'Kundalini: Hint geleneğinde insanın kuyruk sokumunda uyuyan yılan. Meditasyon ve nefesle uyandırılır, omurga boyunca yükselip taç çakrada aydınlanmaya ulaştırır.', en: 'Kundalini: In Hindu tradition, the serpent asleep at the base of the human spine. Awakened through meditation and breath, it ascends along the spine and brings enlightenment at the crown chakra.', de: 'Kundalini: In der hinduistischen Tradition die Schlange, die am Grunde der menschlichen Wirbelsäule schläft. Durch Meditation und Atem geweckt, steigt sie entlang der Wirbelsäule auf und führt am Scheitelchakra zur Erleuchtung.', es: 'Kundalini: En la tradición hindú, la serpiente que duerme en la base de la columna humana. Despertada mediante la meditación y el aliento, asciende por la columna y conduce a la iluminación en el chakra de la corona.', pt: 'Kundalini: Na tradição hindu, a serpente que dorme na base da coluna humana. Despertada pela meditação e pela respiração, sobe pela coluna e conduz à iluminação no chakra da coroa.', fr: 'Kundalini : Dans la tradition hindoue, le serpent endormi à la base de la colonne humaine. Éveillé par la méditation et le souffle, il s\'élève le long de la colonne et mène à l\'illumination au chakra couronne.', ja: 'クンダリーニ：ヒンドゥーの伝統において、人の尾骨に眠る蛇。瞑想と呼吸によって目覚め、背骨を昇り、頭頂のチャクラで悟りへと至らせる。' },
    ],
  },

  // ─── a015 Kelebek ───────────────────────────────────────────────────────
  a015: {
    jung: { tr: '"Yeniden Doğan Ruh" arketipi. Psyche — Yunanca hem "ruh" hem "kelebek" anlamına gelir. Bilincin metamorfozu.', en: 'The "Reborn Soul" archetype. Psyche — in Greek means both "soul" and "butterfly". The metamorphosis of consciousness.', de: 'Der Archetyp der "wiedergeborenen Seele". Psyche — bedeutet im Griechischen sowohl "Seele" als auch "Schmetterling". Die Metamorphose des Bewusstseins.', es: 'El arquetipo del "Alma Renacida". Psique — en griego significa tanto "alma" como "mariposa". La metamorfosis de la conciencia.', pt: 'O arquétipo da "Alma Renascida". Psique — em grego significa tanto "alma" como "borboleta". A metamorfose da consciência.', fr: 'L\'archétype de l\'"Âme renaissante". Psyché — en grec signifie à la fois "âme" et "papillon". La métamorphose de la conscience.', ja: '「生まれ変わる魂」の元型。プシュケー——ギリシア語で「魂」と「蝶」の両方を意味する。意識の変身。' },
    dream: { tr: 'Kelebek rüyada — bir dönüşümün tamamlandığını söyler. Yumurtadan tırtıla, krizalitten kelebeğe — şu an hangi aşamadasın?', en: 'Butterfly in dream — tells you a transformation is being completed. Egg to caterpillar, chrysalis to butterfly — which stage are you in now?', de: 'Schmetterling im Traum — sagt dir, dass eine Verwandlung sich vollendet. Vom Ei zur Raupe, von der Puppe zum Schmetterling — in welcher Phase bist du jetzt?', es: 'Mariposa en sueños — te dice que una transformación se está completando. De huevo a oruga, de crisálida a mariposa — ¿en qué etapa estás ahora?', pt: 'Borboleta em sonho — diz-te que uma transformação se está a completar. De ovo a lagarta, de crisálida a borboleta — em que fase estás agora?', fr: 'Papillon en rêve — te dit qu\'une transformation s\'achève. De l\'œuf à la chenille, de la chrysalide au papillon — à quelle étape es-tu maintenant ?', ja: '夢の中の蝶——一つの変容が完成しつつあると告げる。卵から幼虫へ、蛹から蝶へ——あなたは今どの段階にいるのか?' },
    shadow: { tr: 'Hafiflik kaçıngana dönüşmek. "Sadece güzelin tarafını al" tutumu — derinliği kaçırma. Kelebek kanat çırpar ama yer çekimini unutur.', en: 'Lightness turning into avoidance. The "only take the beautiful side" stance — missing depth. The butterfly flutters but forgets gravity.', de: 'Leichtigkeit, die zur Vermeidung wird. Die Haltung "nimm nur die schöne Seite" — die Tiefe verfehlen. Der Schmetterling flattert, vergisst aber die Schwerkraft.', es: 'La ligereza que se vuelve evasión. La actitud de "toma solo el lado hermoso" — perder la profundidad. La mariposa revolotea pero olvida la gravedad.', pt: 'A leveza que se torna evasão. A atitude de "fica só com o lado belo" — perder a profundidade. A borboleta esvoaça mas esquece a gravidade.', fr: 'La légèreté qui devient évitement. L\'attitude "ne prends que le beau côté" — manquer la profondeur. Le papillon voltige mais oublie la gravité.', ja: '軽やかさが回避に転じること。「美しい面だけを取る」という態度——深みを取り逃がすこと。蝶は羽ばたくが、重力を忘れる。' },
    whenAppears: { tr: 'Bir kişilik dönemini bitirip yenisine geçerken, depresyon sonrası uyanışta, yaratıcılığın yeniden açılışında.', en: 'When ending one phase of personality and crossing into another, in awakening after depression, at the reopening of creativity.', de: 'Wenn du eine Phase der Persönlichkeit beendest und in eine neue übergehst, im Erwachen nach einer Depression, beim Wiedererblühen der Kreativität.', es: 'Al terminar una fase de la personalidad y pasar a otra, en el despertar tras la depresión, en la reapertura de la creatividad.', pt: 'Ao terminar uma fase da personalidade e passar a outra, no despertar após a depressão, na reabertura da criatividade.', fr: 'En achevant une phase de la personnalité et en passant à une autre, dans l\'éveil après la dépression, à la réouverture de la créativité.', ja: '人格の一つの時期を終えて次へ移るとき、抑うつののちの目覚め、創造性が再び開かれるときに。' },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Psyche — ruhun bizzat kendisi. Eros\'la aşkı: ruhun aşkı arayışı.', en: 'Psyche — the soul itself. Her love with Eros: the soul\'s search for love.', de: 'Psyche — die Seele selbst. Ihre Liebe mit Eros: die Suche der Seele nach Liebe.', es: 'Psique — el alma misma. Su amor con Eros: la búsqueda del alma por el amor.', pt: 'Psique — a própria alma. O seu amor com Eros: a busca da alma pelo amor.', fr: 'Psyché — l\'âme elle-même. Son amour avec Éros : la quête de l\'âme pour l\'amour.', ja: 'プシュケー——魂そのもの。エロスとの愛——魂の愛の探求。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'İki kelebek — Zhuangzi\'nin meşhur rüyası: "Ben kelebek mi olduğumu rüyada gören insanım, yoksa insan olduğunu rüyada gören kelebek miyim?"', en: 'Two butterflies — Zhuangzi\'s famous dream: "Am I a man who dreamed of being a butterfly, or a butterfly dreaming of being a man?"', de: 'Zwei Schmetterlinge — Zhuangzis berühmter Traum: "Bin ich ein Mensch, der träumte, ein Schmetterling zu sein, oder ein Schmetterling, der träumt, ein Mensch zu sein?"', es: 'Dos mariposas — el famoso sueño de Zhuangzi: "¿Soy un hombre que soñó ser mariposa, o una mariposa que sueña ser hombre?"', pt: 'Duas borboletas — o famoso sonho de Zhuangzi: "Sou um homem que sonhou ser borboleta, ou uma borboleta que sonha ser homem?"', fr: 'Deux papillons — le célèbre rêve de Zhuangzi : "Suis-je un homme qui rêva d\'être papillon, ou un papillon qui rêve d\'être homme ?"', ja: '二匹の蝶——荘子の有名な夢：「私は蝶になった夢を見た人間なのか、それとも人間になった夢を見ている蝶なのか?」' } },
      { culture: { tr: 'Aztek', en: 'Aztec', de: 'Aztekisch', es: 'Azteca', pt: 'Asteca', fr: 'Aztèque', ja: 'アステカ' }, meaning: { tr: 'Itzpapalotl — obsidyen kelebek tanrıça. Savaşçı ruhların eşlikçisi.', en: 'Itzpapalotl — the obsidian butterfly goddess. Companion of warrior souls.', de: 'Itzpapalotl — die Obsidian-Schmetterlingsgöttin. Begleiterin der Kriegerseelen.', es: 'Itzpapálotl — la diosa mariposa de obsidiana. Compañera de las almas guerreras.', pt: 'Itzpapalotl — a deusa borboleta de obsidiana. Companheira das almas guerreiras.', fr: 'Itzpapalotl — la déesse-papillon d\'obsidienne. Compagne des âmes guerrières.', ja: 'イツパパロトル——黒曜石の蝶の女神。戦士の魂の伴侶。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Ölmüş yakının ruhunun ziyareti. Mezarlıkta kelebek görmek — atalar konuşuyor.', en: 'The visit of a deceased loved one\'s soul. To see a butterfly in a cemetery — the ancestors are speaking.', de: 'Der Besuch der Seele eines verstorbenen Angehörigen. Einen Schmetterling auf dem Friedhof zu sehen — die Ahnen sprechen.', es: 'La visita del alma de un ser querido difunto. Ver una mariposa en un cementerio — los antepasados hablan.', pt: 'A visita da alma de um ente querido falecido. Ver uma borboleta num cemitério — os antepassados falam.', fr: 'La visite de l\'âme d\'un proche défunt. Voir un papillon dans un cimetière — les ancêtres parlent.', ja: '亡くなった近しい者の魂の訪れ。墓地で蝶を見ること——先祖が語っている。' } },
      { culture: { tr: 'Japonya', en: 'Japanese', de: 'Japanisch', es: 'Japonés', pt: 'Japonês', fr: 'Japonais', ja: '日本' }, meaning: { tr: 'Aşkın simgesi. İki kelebek bir arada — sadık eşler.', en: 'Symbol of love. Two butterflies together — faithful spouses.', de: 'Symbol der Liebe. Zwei Schmetterlinge beisammen — treue Eheleute.', es: 'Símbolo del amor. Dos mariposas juntas — esposos fieles.', pt: 'Símbolo do amor. Duas borboletas juntas — cônjuges fiéis.', fr: 'Symbole de l\'amour. Deux papillons ensemble — des époux fidèles.', ja: '愛の象徴。寄り添う二匹の蝶——貞節な夫婦。' } },
    ],
    myths: [
      { tr: 'Eros ve Psyche: Aşk tanrısı Eros\'a aşık olan ölümlü kız Psyche\'nin sınavları. Aşk ruhu arıyor, ruh aşkı arıyor — sonunda Olympos\'a yükseliyor.', en: 'Eros and Psyche: The trials of the mortal girl Psyche, in love with the god of love Eros. Love seeks the soul, the soul seeks love — at last she ascends to Olympus.', de: 'Eros und Psyche: Die Prüfungen des sterblichen Mädchens Psyche, das in den Liebesgott Eros verliebt ist. Die Liebe sucht die Seele, die Seele sucht die Liebe — am Ende steigt sie zum Olymp auf.', es: 'Eros y Psique: Las pruebas de la muchacha mortal Psique, enamorada del dios del amor Eros. El amor busca al alma, el alma busca al amor — al fin ella asciende al Olimpo.', pt: 'Eros e Psique: As provas da donzela mortal Psique, apaixonada pelo deus do amor Eros. O amor procura a alma, a alma procura o amor — por fim ela sobe ao Olimpo.', fr: 'Éros et Psyché : Les épreuves de la jeune mortelle Psyché, éprise du dieu de l\'amour Éros. L\'amour cherche l\'âme, l\'âme cherche l\'amour — enfin elle s\'élève à l\'Olympe.', ja: 'エロスとプシュケー：愛の神エロスに恋した人間の娘プシュケーの試練。愛は魂を求め、魂は愛を求める——ついに彼女はオリュンポスへ昇る。' },
      { tr: 'Zhuangzi\'nin Rüyası: Çinli Taocu filozofun en ünlü hikayesi — rüyada kelebek olur, uyandığında hangisinin gerçek olduğundan emin olamaz.', en: 'Zhuangzi\'s Dream: The most famous story of the Chinese Taoist philosopher — he becomes a butterfly in dream, and upon waking cannot be sure which is real.', de: 'Zhuangzis Traum: Die berühmteste Geschichte des chinesischen taoistischen Philosophen — im Traum wird er zum Schmetterling, und beim Erwachen kann er nicht sicher sein, welches das Wirkliche ist.', es: 'El sueño de Zhuangzi: La historia más famosa del filósofo taoísta chino — en sueños se vuelve mariposa, y al despertar no puede estar seguro de cuál es lo real.', pt: 'O sonho de Zhuangzi: A história mais famosa do filósofo taoista chinês — em sonho torna-se borboleta, e ao acordar não consegue ter a certeza de qual é o real.', fr: 'Le rêve de Zhuangzi : L\'histoire la plus célèbre du philosophe taoïste chinois — en rêve il devient papillon, et au réveil il ne peut être sûr lequel est réel.', ja: '荘子の夢：中国の道家の哲人の最も名高い物語——夢の中で蝶となり、目覚めてもどちらが現実か確信が持てない。' },
    ],
  },

  // ─── a016 Tavus ─────────────────────────────────────────────────────────
  a016: {
    jung: { tr: '"Görkemli Benlik" arketipi. Tavus kuşu — ifşa edilmiş güzellik, görünmeye cesaret eden ego.', en: 'The "Magnificent Self" archetype. The peacock — beauty unveiled, the ego that dares to be seen.', de: 'Der Archetyp des "prächtigen Selbst". Der Pfau — enthüllte Schönheit, das Ego, das sich zu zeigen wagt.', es: 'El arquetipo del "Yo Magnífico". El pavo real — la belleza revelada, el ego que se atreve a ser visto.', pt: 'O arquétipo do "Eu Magnífico". O pavão — a beleza revelada, o ego que ousa ser visto.', fr: 'L\'archétype du "Soi magnifique". Le paon — la beauté dévoilée, l\'ego qui ose être vu.', ja: '「壮麗なる自己」の元型。クジャク——あらわにされた美、見られることを敢えてする自我。' },
    dream: { tr: 'Tavus rüyada — kendini göstermek için izin alıyorsun. Kuyruğunu açıyorsa: sahip olduğun değeri kabul et. Kapalıysa: gücünü saklıyorsun.', en: 'Peacock in dream — you are seeking permission to show yourself. Spreading its tail: accept the worth you possess. Closed: you are hiding your power.', de: 'Pfau im Traum — du suchst die Erlaubnis, dich zu zeigen. Schlägt er sein Rad: Nimm den Wert an, den du besitzt. Geschlossen: Du verbirgst deine Kraft.', es: 'Pavo real en sueños — buscas permiso para mostrarte. Si despliega su cola: acepta el valor que posees. Cerrada: ocultas tu poder.', pt: 'Pavão em sonho — procuras permissão para te mostrares. Se abre a cauda: aceita o valor que possuis. Fechada: escondes o teu poder.', fr: 'Paon en rêve — tu cherches la permission de te montrer. Déployant sa queue : accepte la valeur que tu possèdes. Fermée : tu caches ta puissance.', ja: '夢の中のクジャク——あなたは自らを示す許しを求めている。尾を広げるなら、あなたの持つ価値を受け入れよ。閉じているなら、あなたは自分の力を隠している。' },
    shadow: { tr: 'Kibir, gösteriş, sahte parlaklık. Tavus enerjisi savunmasızlığını kaybederse — yalnız gösterişin içinde donar.', en: 'Vanity, display, false brilliance. If peacock energy loses its vulnerability — it freezes within mere show.', de: 'Eitelkeit, Zurschaustellung, falscher Glanz. Verliert die Pfauenenergie ihre Verletzlichkeit — erstarrt sie in bloßem Schein.', es: 'Vanidad, ostentación, brillo falso. Si la energía del pavo real pierde su vulnerabilidad — se congela dentro del mero espectáculo.', pt: 'Vaidade, ostentação, brilho falso. Se a energia do pavão perde a sua vulnerabilidade — congela dentro de mera aparência.', fr: 'Vanité, ostentation, faux éclat. Si l\'énergie du paon perd sa vulnérabilité — elle se fige dans le seul spectacle.', ja: '虚栄、見せびらかし、偽りの輝き。クジャクのエネルギーがその傷つきやすさを失えば——ただの見世物の中で凍りつく。' },
    whenAppears: { tr: 'Sahneye çıkma anında, görünür olma fırsatında, içsel güzelliğin tanınma talebinde.', en: 'At the moment of stepping onto the stage, at the chance to become visible, in the demand for inner beauty to be recognized.', de: 'Im Moment, da du die Bühne betrittst, bei der Gelegenheit, sichtbar zu werden, im Verlangen, dass innere Schönheit anerkannt wird.', es: 'En el momento de subir al escenario, ante la oportunidad de hacerte visible, en la demanda de que se reconozca la belleza interior.', pt: 'No momento de subir ao palco, perante a oportunidade de te tornares visível, na exigência de que a beleza interior seja reconhecida.', fr: 'Au moment de monter sur scène, à l\'occasion de devenir visible, dans la demande que la beauté intérieure soit reconnue.', ja: '舞台に上がる瞬間、人目に立つ機会、内なる美が認められることを求めるときに。' },
    traditions: [
      { culture: { tr: 'Hint', en: 'Hindu', de: 'Hinduistisch', es: 'Hindú', pt: 'Hindu', fr: 'Hindou', ja: 'ヒンドゥー' }, meaning: { tr: 'Sarasvati\'nin bineği — sanat ve bilgi tanrıçası. Kartikeya\'nın da kuşu.', en: 'Mount of Saraswati — goddess of arts and knowledge. Also the bird of Kartikeya.', de: 'Reittier der Sarasvati — Göttin der Künste und des Wissens. Auch der Vogel des Kartikeya.', es: 'Montura de Sarasvati — diosa de las artes y el conocimiento. También el ave de Kartikeya.', pt: 'Montaria de Sarasvati — deusa das artes e do conhecimento. Também a ave de Kartikeya.', fr: 'Monture de Sarasvatî — déesse des arts et du savoir. Aussi l\'oiseau de Kârttikeya.', ja: 'サラスヴァティの乗り物——芸術と知識の女神。カールッティケーヤの鳥でもある。' } },
      { culture: { tr: 'Yezidi', en: 'Yazidi', de: 'Jesidisch', es: 'Yazidí', pt: 'Yazidi', fr: 'Yézidi', ja: 'ヤズィーディー' }, meaning: { tr: 'Melek Tavus — Yezidiliğin merkezi figürü. Tanrı\'nın yeryüzündeki yansıması.', en: 'Melek Taus — the central figure of Yazidism. The reflection of God upon earth.', de: 'Melek Taus — die zentrale Gestalt des Jesidentums. Das Abbild Gottes auf Erden.', es: 'Melek Taus — la figura central del yazidismo. El reflejo de Dios sobre la tierra.', pt: 'Melek Taus — a figura central do yazidismo. O reflexo de Deus sobre a terra.', fr: 'Melek Taus — la figure centrale du yézidisme. Le reflet de Dieu sur la terre.', ja: 'メレク・タウス——ヤズィーディー教の中心的存在。地上における神の映し。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Hera\'nın kuşu. Argos\'un yüz gözünü tüylerine işler — uyanıklık ve sadakat.', en: 'Hera\'s bird. She weaves Argus\'s hundred eyes into its feathers — vigilance and loyalty.', de: 'Heras Vogel. Sie webt Argus\' hundert Augen in sein Gefieder — Wachsamkeit und Treue.', es: 'El ave de Hera. Ella teje los cien ojos de Argos en sus plumas — vigilancia y lealtad.', pt: 'A ave de Hera. Ela tece os cem olhos de Argos nas suas penas — vigilância e lealdade.', fr: 'L\'oiseau d\'Héra. Elle tisse les cent yeux d\'Argos dans ses plumes — vigilance et loyauté.', ja: 'ヘラの鳥。彼女はアルゴスの百の目をその羽に織り込む——警戒と忠誠。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Ölümsüzlük ve diriliş. Bizans mozaiklerinde sık görülür — kanatlarındaki "gözler" ilahi bakış.', en: 'Immortality and resurrection. Often seen in Byzantine mosaics — the "eyes" in its feathers are the divine gaze.', de: 'Unsterblichkeit und Auferstehung. Häufig in byzantinischen Mosaiken zu sehen — die "Augen" in seinem Gefieder sind der göttliche Blick.', es: 'Inmortalidad y resurrección. A menudo visto en mosaicos bizantinos — los "ojos" de sus plumas son la mirada divina.', pt: 'Imortalidade e ressurreição. Visto frequentemente em mosaicos bizantinos — os "olhos" das suas penas são o olhar divino.', fr: 'Immortalité et résurrection. Souvent vu dans les mosaïques byzantines — les "yeux" de ses plumes sont le regard divin.', ja: '不死と復活。ビザンツのモザイクにしばしば見られる——その羽の「目」は神のまなざし。' } },
      { culture: { tr: 'Türk-İslam', en: 'Turco-Islamic', de: 'Türkisch-Islamisch', es: 'Turco-Islámico', pt: 'Turco-Islâmico', fr: 'Turco-Islamique', ja: 'トルコ・イスラーム' }, meaning: { tr: 'Cennet kuşu. Sufi metinlerinde "tavus-i ervah" — ruhların gösterişli formu.', en: 'Bird of paradise. In Sufi texts, "tavus-i ervah" — the splendid form of souls.', de: 'Paradiesvogel. In Sufi-Texten "tavus-i ervah" — die prächtige Gestalt der Seelen.', es: 'Ave del paraíso. En los textos sufíes, "tavus-i ervah" — la forma espléndida de las almas.', pt: 'Ave do paraíso. Nos textos sufis, "tavus-i ervah" — a forma esplêndida das almas.', fr: 'Oiseau du paradis. Dans les textes soufis, "tavus-i ervah" — la forme splendide des âmes.', ja: '楽園の鳥。スーフィーの文献における「タウース・イ・エルヴァーフ」——魂の華やかな姿。' } },
    ],
    myths: [
      { tr: 'Hera ve Argos: Hera, sadık dev bekçisi Argos öldürülünce yüz gözünü tavusun kuyruğuna işler. O günden beri tavus, sadakatin ve uyanıklığın taşıyıcısıdır.', en: 'Hera and Argus: When her faithful giant watchman Argus is slain, Hera weaves his hundred eyes into the peacock\'s tail. Since that day, the peacock has been the bearer of loyalty and vigilance.', de: 'Hera und Argus: Als ihr treuer Riesenwächter Argus erschlagen wird, webt Hera seine hundert Augen in den Schweif des Pfaus. Seit jenem Tag ist der Pfau der Träger von Treue und Wachsamkeit.', es: 'Hera y Argos: Cuando su fiel guardián gigante Argos es asesinado, Hera teje sus cien ojos en la cola del pavo real. Desde ese día, el pavo real es portador de lealtad y vigilancia.', pt: 'Hera e Argos: Quando o seu fiel guardião gigante Argos é morto, Hera tece os seus cem olhos na cauda do pavão. Desde esse dia, o pavão é portador de lealdade e vigilância.', fr: 'Héra et Argos : Lorsque son fidèle gardien géant Argos est tué, Héra tisse ses cent yeux dans la queue du paon. Depuis ce jour, le paon est porteur de loyauté et de vigilance.', ja: 'ヘラとアルゴス：忠実な巨人の番人アルゴスが殺されたとき、ヘラはその百の目をクジャクの尾に織り込む。その日以来、クジャクは忠誠と警戒の担い手である。' },
      { tr: 'Melek Tavus: Yezidi geleneğinde Melek Tavus, Tanrı\'nın yedi meleğinden en büyüğüdür. Diğer dinlerde "düşmüş melek" olarak yorumlanmış ama Yezidilerce yücedir — perspektif meselesi.', en: 'Melek Taus: In Yazidi tradition, Melek Taus is the greatest of God\'s seven angels. Interpreted as a "fallen angel" in other religions but exalted by Yazidis — a matter of perspective.', de: 'Melek Taus: In der jesidischen Tradition ist Melek Taus der größte der sieben Engel Gottes. In anderen Religionen als "gefallener Engel" gedeutet, doch von den Jesiden verehrt — eine Frage der Perspektive.', es: 'Melek Taus: En la tradición yazidí, Melek Taus es el mayor de los siete ángeles de Dios. Interpretado como "ángel caído" en otras religiones pero exaltado por los yazidíes — una cuestión de perspectiva.', pt: 'Melek Taus: Na tradição yazidi, Melek Taus é o maior dos sete anjos de Deus. Interpretado como "anjo caído" noutras religiões mas exaltado pelos yazidis — uma questão de perspetiva.', fr: 'Melek Taus : Dans la tradition yézidie, Melek Taus est le plus grand des sept anges de Dieu. Interprété comme un "ange déchu" dans d\'autres religions mais exalté par les Yézidis — une question de perspective.', ja: 'メレク・タウス：ヤズィーディーの伝統では、メレク・タウスは神の七大天使のうち最も偉大なもの。他の宗教では「堕天使」と解されるが、ヤズィーディーにとっては崇高な存在——視座の問題。' },
    ],
  },

  // ─── a017 Leylek ────────────────────────────────────────────────────────
  a017: {
    jung: { tr: '"Doğum/Yeni Başlangıç" arketipi. Leylek, eski döngünün bitimi ve yeni ruhun gelişinin habercisi.', en: 'The "Birth/New Beginning" archetype. The stork is the herald of the old cycle\'s end and the new soul\'s arrival.', de: 'Der Archetyp "Geburt/Neuanfang". Der Storch ist der Herold vom Ende des alten Kreislaufs und der Ankunft der neuen Seele.', es: 'El arquetipo del "Nacimiento/Nuevo Comienzo". La cigüeña es la heralda del fin del viejo ciclo y de la llegada del alma nueva.', pt: 'O arquétipo do "Nascimento/Novo Começo". A cegonha é a arauta do fim do velho ciclo e da chegada da alma nova.', fr: 'L\'archétype "Naissance/Nouveau Commencement". La cigogne est le héraut de la fin de l\'ancien cycle et de l\'arrivée de l\'âme nouvelle.', ja: '「誕生／新たな始まり」の元型。コウノトリは、古き循環の終わりと新たな魂の到来を告げる使者。' },
    dream: { tr: 'Leylek rüyada — yeni bir başlangıç doğuyor. Üzerinde bebek varsa: yaratıcı bir doğuma hazırsın. Uçuyorsa: göç ve değişim zamanı.', en: 'Stork in dream — a new beginning is being born. With a baby upon it: you are ready for a creative birth. Flying: time of migration and change.', de: 'Storch im Traum — ein neuer Anfang wird geboren. Mit einem Baby darauf: Du bist bereit für eine schöpferische Geburt. Im Flug: Zeit der Wanderung und des Wandels.', es: 'Cigüeña en sueños — un nuevo comienzo está naciendo. Con un bebé encima: estás listo para un parto creativo. Volando: tiempo de migración y cambio.', pt: 'Cegonha em sonho — um novo começo está a nascer. Com um bebé em cima: estás pronto para um parto criativo. A voar: tempo de migração e mudança.', fr: 'Cigogne en rêve — un nouveau commencement naît. Avec un bébé sur elle : tu es prêt pour un enfantement créatif. En vol : temps de migration et de changement.', ja: '夢の中のコウノトリ——新たな始まりが生まれつつある。赤子を乗せているなら、あなたは創造的な誕生の準備ができている。飛んでいるなら、渡りと変化の時。' },
    shadow: { tr: '"Bir şeyler getirsin" diye pasif beklemek. Leylek getirir ama tohumu sen ekmelisin. Beklemek doğurmak değildir.', en: 'Waiting passively "for something to be brought". The stork delivers, but you must plant the seed. Waiting is not giving birth.', de: 'Passiv darauf zu warten, dass "etwas gebracht wird". Der Storch bringt, doch den Samen musst du säen. Warten ist kein Gebären.', es: 'Esperar pasivamente a que "traigan algo". La cigüeña entrega, pero la semilla debes plantarla tú. Esperar no es dar a luz.', pt: 'Esperar passivamente que "tragam algo". A cegonha entrega, mas a semente tens de a plantar tu. Esperar não é dar à luz.', fr: 'Attendre passivement qu\'"on apporte quelque chose". La cigogne livre, mais c\'est à toi de semer la graine. Attendre n\'est pas enfanter.', ja: '「何かを運んでくれる」と受け身で待つこと。コウノトリは届けるが、種を蒔くのはあなた自身。待つことは産むことではない。' },
    whenAppears: { tr: 'Hamilelik/doğum (gerçek ya da yaratıcı) öncesinde, ev kuruşunda, yeni bir döneme geçişte.', en: 'Before pregnancy/birth (literal or creative), in establishing a home, in transition to a new period.', de: 'Vor Schwangerschaft/Geburt (buchstäblich oder schöpferisch), beim Gründen eines Heims, im Übergang zu einem neuen Abschnitt.', es: 'Antes del embarazo/parto (literal o creativo), al establecer un hogar, en la transición a un nuevo período.', pt: 'Antes da gravidez/parto (literal ou criativo), ao estabelecer um lar, na transição para um novo período.', fr: 'Avant une grossesse/naissance (littérale ou créative), en fondant un foyer, dans la transition vers une nouvelle période.', ja: '妊娠や出産（実際の、あるいは創造的な）の前、家庭を築くとき、新たな時期への移行に。' },
    traditions: [
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: '"Hacı leylek" — kutsal yolcunun, hacca giden ruhun adı. Çatıya leylek yuvası: o ev bereketli.', en: '"Hacı leylek" — the name of the sacred pilgrim, the soul that goes on hajj. A stork\'s nest on the roof: that house is blessed.', de: '"Hacı leylek" — der Name des heiligen Pilgers, der Seele, die zur Hadsch zieht. Ein Storchennest auf dem Dach: Jenes Haus ist gesegnet.', es: '"Hacı leylek" — el nombre del peregrino sagrado, el alma que va a la peregrinación. Un nido de cigüeña en el tejado: esa casa está bendecida.', pt: '"Hacı leylek" — o nome do peregrino sagrado, a alma que vai à peregrinação. Um ninho de cegonha no telhado: aquela casa é abençoada.', fr: '"Hacı leylek" — le nom du pèlerin sacré, l\'âme qui part en pèlerinage. Un nid de cigogne sur le toit : cette maison est bénie.', ja: '「ハジュ・レイレキ（巡礼のコウノトリ）」——聖なる巡礼者、巡礼へ赴く魂の名。屋根のコウノトリの巣——その家は祝福されている。' } },
      { culture: { tr: 'Slav-Alman', en: 'Slavic-Germanic', de: 'Slawisch-Germanisch', es: 'Eslavo-Germánico', pt: 'Eslavo-Germânico', fr: 'Slavo-Germanique', ja: 'スラヴ・ゲルマン' }, meaning: { tr: 'Bebekleri getiren kuş. Doğum hediyesi olarak çocukları evlere taşır.', en: 'The bird that brings babies. It carries children to homes as a birth-gift.', de: 'Der Vogel, der die Babys bringt. Er trägt die Kinder als Geburtsgeschenk in die Häuser.', es: 'El ave que trae a los bebés. Lleva a los niños a los hogares como regalo de nacimiento.', pt: 'A ave que traz os bebés. Leva as crianças aos lares como presente de nascimento.', fr: 'L\'oiseau qui apporte les bébés. Il porte les enfants aux foyers comme présent de naissance.', ja: '赤子を運ぶ鳥。誕生の贈り物として子どもを家々へ運ぶ。' } },
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Ba — insanın ruhu leylek/lekleğe benzer kuş formunda gösterilir. Bedenden ayrılan ruh.', en: 'Ba — the human soul depicted as a stork-like bird. The soul departing the body.', de: 'Ba — die menschliche Seele, dargestellt als storchähnlicher Vogel. Die Seele, die den Leib verlässt.', es: 'Ba — el alma humana representada como un ave semejante a la cigüeña. El alma que abandona el cuerpo.', pt: 'Ba — a alma humana representada como uma ave semelhante à cegonha. A alma que deixa o corpo.', fr: 'Ba — l\'âme humaine représentée comme un oiseau semblable à la cigogne. L\'âme qui quitte le corps.', ja: 'バー——コウノトリに似た鳥の姿で描かれる人の魂。肉体を離れる魂。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Hera\'nın koruyuculuk simgesi. Anneler için kutsanmış kuş.', en: 'Symbol of Hera\'s protection. A bird blessed for mothers.', de: 'Symbol des Schutzes der Hera. Ein für Mütter gesegneter Vogel.', es: 'Símbolo de la protección de Hera. Un ave bendecida para las madres.', pt: 'Símbolo da proteção de Hera. Uma ave abençoada para as mães.', fr: 'Symbole de la protection d\'Héra. Un oiseau béni pour les mères.', ja: 'ヘラの守護の象徴。母たちのために祝福された鳥。' } },
      { culture: { tr: 'İslam Halk', en: 'Islamic Folk', de: 'Islamische Volkskultur', es: 'Folclore Islámico', pt: 'Folclore Islâmico', fr: 'Folklore Islamique', ja: 'イスラーム民俗' }, meaning: { tr: 'Hacca gidip dönen kuş olduğuna inanılır. "Hacı leylek" duası — yolculuğun bereketi.', en: 'Believed to be the bird that travels to Mecca and returns. The "Hacı leylek" blessing — the journey\'s benediction.', de: 'Man glaubt, es sei der Vogel, der nach Mekka reist und zurückkehrt. Der "Hacı leylek"-Segen — die Segnung der Reise.', es: 'Se cree que es el ave que viaja a La Meca y regresa. La bendición "Hacı leylek" — la bendición del viaje.', pt: 'Crê-se ser a ave que viaja a Meca e regressa. A bênção "Hacı leylek" — a bênção da viagem.', fr: 'On croit que c\'est l\'oiseau qui voyage à La Mecque et en revient. La bénédiction "Hacı leylek" — la bénédiction du voyage.', ja: 'メッカへ旅して戻る鳥と信じられている。「ハジュ・レイレキ」の祈り——旅の祝福。' } },
    ],
    myths: [
      { tr: 'Hacı Leylek: Anadolu inanışına göre leylekler her yıl hacca gider, dönerler. Onlara zarar veren bu kutsal yolculuğu bozmuş sayılır — büyük günah.', en: 'The Pilgrim Stork: According to Anatolian belief, storks go on hajj every year and return. To harm them is to disrupt this sacred journey — a great sin.', de: 'Der Pilgerstorch: Nach anatolischem Glauben ziehen Störche jedes Jahr zur Hadsch und kehren zurück. Wer ihnen schadet, gilt als jemand, der diese heilige Reise stört — eine große Sünde.', es: 'La cigüeña peregrina: Según la creencia anatolia, las cigüeñas van a la peregrinación cada año y regresan. Dañarlas equivale a perturbar este viaje sagrado — un gran pecado.', pt: 'A cegonha peregrina: Segundo a crença anatólia, as cegonhas vão à peregrinação todos os anos e regressam. Prejudicá-las equivale a perturbar esta viagem sagrada — um grande pecado.', fr: 'La cigogne pèlerine : Selon la croyance anatolienne, les cigognes partent chaque année en pèlerinage et reviennent. Leur nuire revient à troubler ce voyage sacré — un grand péché.', ja: '巡礼のコウノトリ：アナトリアの信仰によれば、コウノトリは毎年巡礼に赴き、戻ってくる。彼らに害をなす者はこの聖なる旅を乱した者とされる——大いなる罪。' },
      { tr: 'Babylonia\'da Leylek: Eski Mezopotamya tabletlerinde leylekler tanrı Marduk\'un haberci kuşlarıdır — kuraklığa rağmen suyu bulan rehber.', en: 'The Stork in Babylonia: In ancient Mesopotamian tablets, storks are the messenger birds of the god Marduk — the guide that finds water despite drought.', de: 'Der Storch in Babylonien: Auf alten mesopotamischen Tafeln sind Störche die Botenvögel des Gottes Marduk — der Führer, der trotz Dürre das Wasser findet.', es: 'La cigüeña en Babilonia: En antiguas tablillas mesopotámicas, las cigüeñas son las aves mensajeras del dios Marduk — la guía que halla el agua pese a la sequía.', pt: 'A cegonha na Babilónia: Em antigas tábuas mesopotâmicas, as cegonhas são as aves mensageiras do deus Marduk — a guia que encontra a água apesar da seca.', fr: 'La cigogne en Babylonie : Sur d\'anciennes tablettes mésopotamiennes, les cigognes sont les oiseaux messagers du dieu Marduk — le guide qui trouve l\'eau malgré la sécheresse.', ja: 'バビロニアのコウノトリ：古代メソポタミアの粘土板において、コウノトリは神マルドゥクの使いの鳥——干ばつにもかかわらず水を見いだす導き手。' },
    ],
  },

  // ─── a018 Şahin ─────────────────────────────────────────────────────────
  a018: {
    jung: { tr: '"Odaklanmış İrade" arketipi. Şahin — net görüş, isabetli karar, hedeflenmiş eylem. Kartal kadar yüksek değil ama daha keskin.', en: 'The "Focused Will" archetype. The falcon — clear sight, precise decision, targeted action. Not as high as the eagle, but sharper.', de: 'Der Archetyp des "fokussierten Willens". Der Falke — klarer Blick, treffsichere Entscheidung, gezieltes Handeln. Nicht so hoch wie der Adler, aber schärfer.', es: 'El arquetipo de la "Voluntad Enfocada". El halcón — vista clara, decisión precisa, acción dirigida. No tan alto como el águila, pero más agudo.', pt: 'O arquétipo da "Vontade Focada". O falcão — visão clara, decisão precisa, ação dirigida. Não tão alto como a águia, mas mais aguçado.', fr: 'L\'archétype de la "Volonté concentrée". Le faucon — vue claire, décision juste, action ciblée. Moins haut que l\'aigle, mais plus aiguisé.', ja: '「集中せる意志」の元型。ハヤブサ——明晰な視、的確な決断、狙い定めた行動。ワシほど高くはないが、より鋭い。' },
    dream: { tr: 'Şahin rüyada — bir şeye keskinleşmen gerekiyor. Avlanıyorsa: hedefini bul. Eline konuyorsa: gücün geri geliyor, ehlileşmiş halde.', en: 'Falcon in dream — you must sharpen toward something. Hunting: find your target. Landing on your hand: your power is returning, tamed.', de: 'Falke im Traum — du musst dich auf etwas zuspitzen. Jagt er: Finde dein Ziel. Landet er auf deiner Hand: Deine Kraft kehrt zurück, gezähmt.', es: 'Halcón en sueños — debes afilarte hacia algo. Si caza: encuentra tu objetivo. Si se posa en tu mano: tu poder regresa, domado.', pt: 'Falcão em sonho — deves aguçar-te rumo a algo. Se caça: encontra o teu alvo. Se pousa na tua mão: o teu poder regressa, domado.', fr: 'Faucon en rêve — tu dois t\'affûter vers quelque chose. S\'il chasse : trouve ta cible. S\'il se pose sur ta main : ta puissance revient, apprivoisée.', ja: '夢の中のハヤブサ——あなたは何かに向けて研ぎ澄まされねばならない。狩るなら、標的を見つけよ。あなたの手に止まるなら、力が——馴らされて——戻ってくる。' },
    shadow: { tr: 'Acımasız odak. Hedefe ulaşmak için her şeyi feda etmek. Şahin keskindir ama ısırırsa zalimleşir.', en: 'Ruthless focus. Sacrificing everything to reach the goal. The falcon is sharp, but if it bites, it becomes cruel.', de: 'Erbarmungsloser Fokus. Alles zu opfern, um das Ziel zu erreichen. Der Falke ist scharf, doch beißt er, wird er grausam.', es: 'Enfoque despiadado. Sacrificarlo todo para alcanzar la meta. El halcón es agudo, pero si muerde, se vuelve cruel.', pt: 'Foco impiedoso. Sacrificar tudo para alcançar o objetivo. O falcão é aguçado, mas se morde, torna-se cruel.', fr: 'Concentration impitoyable. Tout sacrifier pour atteindre le but. Le faucon est aiguisé, mais s\'il mord, il devient cruel.', ja: '非情な集中。目標に達するためにすべてを犠牲にすること。ハヤブサは鋭いが、咬めば残酷になる。' },
    whenAppears: { tr: 'Bir kararın netleşmesi gerektiğinde, dağılmış enerjini toplaman gerekirken, bir sözünü tutman gereken anda.', en: 'When a decision must become clear, when you must gather your scattered energy, at the moment you must keep your word.', de: 'Wenn eine Entscheidung klar werden muss, wenn du deine zerstreute Energie sammeln musst, in dem Moment, in dem du dein Wort halten musst.', es: 'Cuando una decisión debe aclararse, cuando debes reunir tu energía dispersa, en el momento en que debes cumplir tu palabra.', pt: 'Quando uma decisão deve tornar-se clara, quando deves reunir a tua energia dispersa, no momento em que deves cumprir a tua palavra.', fr: 'Quand une décision doit devenir claire, quand tu dois rassembler ton énergie dispersée, au moment où tu dois tenir parole.', ja: '決断が明確にならねばならぬとき、散らばった力を集めねばならぬとき、約束を守らねばならぬ瞬間に。' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Horus — şahin başlı tanrı. Krallığın, göğün ve adaletin sembolü. Firavunun ruhsal protokolü.', en: 'Horus — the falcon-headed god. Symbol of kingship, sky, and justice. The pharaoh\'s spiritual protocol.', de: 'Horus — der falkenköpfige Gott. Symbol des Königtums, des Himmels und der Gerechtigkeit. Das geistige Protokoll des Pharaos.', es: 'Horus — el dios con cabeza de halcón. Símbolo de la realeza, el cielo y la justicia. El protocolo espiritual del faraón.', pt: 'Hórus — o deus com cabeça de falcão. Símbolo da realeza, do céu e da justiça. O protocolo espiritual do faraó.', fr: 'Horus — le dieu à tête de faucon. Symbole de la royauté, du ciel et de la justice. Le protocole spirituel du pharaon.', ja: 'ホルス——ハヤブサの頭をもつ神。王権、天、そして正義の象徴。ファラオの霊的な指針。' } },
      { culture: { tr: 'Türk Şamanizmi', en: 'Turkic Shamanism', de: 'Türkischer Schamanismus', es: 'Chamanismo Túrquico', pt: 'Xamanismo Túrquico', fr: 'Chamanisme Turc', ja: 'テュルク・シャーマニズム' }, meaning: { tr: 'Şamanlar şahin formunda göğe yükselir. Sungar (sungur) — av kuşu, hanın gözü.', en: 'Shamans ascend to the sky in falcon form. Sungar — the hunting bird, the khan\'s eye.', de: 'Schamanen steigen in Falkengestalt zum Himmel auf. Sungar — der Jagdvogel, das Auge des Khans.', es: 'Los chamanes ascienden al cielo en forma de halcón. Sungar — el ave de caza, el ojo del kan.', pt: 'Os xamãs sobem ao céu em forma de falcão. Sungar — a ave de caça, o olho do cã.', fr: 'Les chamanes s\'élèvent au ciel sous forme de faucon. Sungar — l\'oiseau de chasse, l\'œil du khan.', ja: 'シャーマンはハヤブサの姿で天へ昇る。スンガル——狩りの鳥、ハーンの目。' } },
      { culture: { tr: 'Arap', en: 'Arabic', de: 'Arabisch', es: 'Árabe', pt: 'Árabe', fr: 'Arabe', ja: 'アラブ' }, meaning: { tr: 'Bedevi geleneğinde en değerli av yoldaşı. Avcılığın sanatı: şahinciliğin (şahincilik) UNESCO\'ya kayıtlı miras.', en: 'In Bedouin tradition, the most prized hunting companion. The art of falconry is UNESCO-listed heritage.', de: 'In der Beduinentradition der wertvollste Jagdgefährte. Die Kunst der Falknerei ist UNESCO-Erbe.', es: 'En la tradición beduina, el más preciado compañero de caza. El arte de la cetrería es patrimonio inscrito por la UNESCO.', pt: 'Na tradição beduína, o mais valioso companheiro de caça. A arte da falcoaria é património inscrito pela UNESCO.', fr: 'Dans la tradition bédouine, le plus précieux compagnon de chasse. L\'art de la fauconnerie est un patrimoine inscrit à l\'UNESCO.', ja: 'ベドウィンの伝統において、最も貴ばれる狩りの相棒。鷹狩りの技はユネスコ登録の遺産。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Garuda\'nın akrabası. Soma\'yı (kutsal içecek) tanrılara taşıyan kuş.', en: 'A kin of Garuda. The bird that carries Soma (the sacred draught) to the gods.', de: 'Ein Verwandter Garudas. Der Vogel, der den Göttern das Soma (den heiligen Trank) bringt.', es: 'Pariente de Garuda. El ave que lleva el Soma (la bebida sagrada) a los dioses.', pt: 'Parente de Garuda. A ave que leva o Soma (a bebida sagrada) aos deuses.', fr: 'Un parent de Garuda. L\'oiseau qui porte le Soma (le breuvage sacré) aux dieux.', ja: 'ガルダの縁者。ソーマ（聖なる飲み物）を神々へ運ぶ鳥。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Yiğit padişahların kolundaki şahin — irade ve sadakatin sembolü. Doğan ve şahinli sancaklar.', en: 'The falcon on the arm of valiant sultans — symbol of will and loyalty. Banners bearing falcons and hawks.', de: 'Der Falke auf dem Arm tapferer Sultane — Symbol von Wille und Treue. Banner mit Falken und Habichten.', es: 'El halcón en el brazo de sultanes valientes — símbolo de voluntad y lealtad. Estandartes con halcones y azores.', pt: 'O falcão no braço de sultões valentes — símbolo de vontade e lealdade. Estandartes com falcões e açores.', fr: 'Le faucon sur le bras de sultans vaillants — symbole de volonté et de loyauté. Bannières portant faucons et autours.', ja: '勇猛なスルタンの腕に止まるハヤブサ——意志と忠誠の象徴。ハヤブサやタカを掲げた軍旗。' } },
    ],
    myths: [
      { tr: 'Horus ve Set: Mısır mitolojisinde şahin başlı Horus, babası Osiris\'i öldüren amcası Set ile uzun savaşa girer. Horus\'un kaybettiği göz — sonradan "Uçat" şifa sembolü olur.', en: 'Horus and Set: In Egyptian mythology, the falcon-headed Horus wages a long war against his uncle Set, who killed his father Osiris. The eye Horus loses — later becomes the "Udjat" symbol of healing.', de: 'Horus und Seth: In der ägyptischen Mythologie führt der falkenköpfige Horus einen langen Krieg gegen seinen Onkel Seth, der seinen Vater Osiris tötete. Das Auge, das Horus verliert — wird später zum "Udjat", dem Symbol der Heilung.', es: 'Horus y Set: En la mitología egipcia, Horus con cabeza de halcón libra una larga guerra contra su tío Set, que mató a su padre Osiris. El ojo que Horus pierde — se convierte después en el "Udjat", símbolo de la curación.', pt: 'Hórus e Set: Na mitologia egípcia, Hórus com cabeça de falcão trava uma longa guerra contra o seu tio Set, que matou o seu pai Osíris. O olho que Hórus perde — torna-se depois o "Udjat", símbolo da cura.', fr: 'Horus et Seth : Dans la mythologie égyptienne, Horus à tête de faucon mène une longue guerre contre son oncle Seth, qui tua son père Osiris. L\'œil que perd Horus — devient plus tard l\'"Oudjat", symbole de la guérison.', ja: 'ホルスとセト：エジプト神話において、ハヤブサの頭をもつホルスは、父オシリスを殺した叔父セトと長き戦いを繰り広げる。ホルスが失った目は——のちに「ウジャト」、癒しの象徴となる。' },
      { tr: 'Selçuklu Şahincibaşılığı: Selçuklu sarayında "Emir-i Şikar" — şahincibaşı en yüksek makamlardan biriydi. Padişahın şahini onun gözüdür.', en: 'The Seljuk Master of Falcons: In the Seljuk court, the "Emir-i Şikar" — master of falcons — was one of the highest offices. The sultan\'s falcon is his eye.', de: 'Das seldschukische Falkenmeisteramt: Am seldschukischen Hof war der "Emir-i Şikar" — der Falkenmeister — eines der höchsten Ämter. Der Falke des Sultans ist sein Auge.', es: 'El maestro de halcones selyúcida: En la corte selyúcida, el "Emir-i Şikar" — maestro de halcones — era uno de los cargos más altos. El halcón del sultán es su ojo.', pt: 'O mestre de falcões seljúcida: Na corte seljúcida, o "Emir-i Şikar" — mestre de falcões — era um dos cargos mais altos. O falcão do sultão é o seu olho.', fr: 'Le maître fauconnier seldjoukide : À la cour seldjoukide, l\'"Emir-i Şikar" — maître fauconnier — était l\'une des plus hautes charges. Le faucon du sultan est son œil.', ja: 'セルジューク朝の鷹匠頭：セルジューク朝の宮廷において、「エミーリ・シカール」——鷹匠頭——は最高位の役職の一つだった。スルタンのハヤブサは彼の目である。' },
    ],
  },

  // ─── a019 Pars ──────────────────────────────────────────────────────────
  a019: {
    jung: { tr: '"Sessiz Avcı" arketipi. Pars — sessizlikte güç, beklemekte zafer. İçsel disiplinin sembolü.', en: 'The "Silent Hunter" archetype. The leopard — power in silence, victory in waiting. Symbol of inner discipline.', de: 'Der Archetyp des "stillen Jägers". Der Leopard — Macht in der Stille, Sieg im Warten. Symbol der inneren Disziplin.', es: 'El arquetipo del "Cazador Silencioso". El leopardo — poder en el silencio, victoria en la espera. Símbolo de la disciplina interior.', pt: 'O arquétipo do "Caçador Silencioso". O leopardo — poder no silêncio, vitória na espera. Símbolo da disciplina interior.', fr: 'L\'archétype du "Chasseur silencieux". Le léopard — la puissance dans le silence, la victoire dans l\'attente. Symbole de la discipline intérieure.', ja: '「静かなる狩人」の元型。ヒョウ——沈黙のうちの力、待つことのうちの勝利。内なる規律の象徴。' },
    dream: { tr: 'Pars rüyada — sabır ve doğru zamanlama hakkında ders. Pusuda yatıyorsa: harekete geçme anı yaklaşıyor. Avlanıyorsa: kararlılıkla ilerle.', en: 'Leopard in dream — a lesson in patience and right timing. Lying in ambush: the moment to act draws near. Hunting: advance with resolve.', de: 'Leopard im Traum — eine Lektion über Geduld und das rechte Timing. Liegt er im Hinterhalt: Der Moment zu handeln naht. Jagt er: Schreite entschlossen voran.', es: 'Leopardo en sueños — una lección de paciencia y de oportunidad justa. Si acecha: el momento de actuar se acerca. Si caza: avanza con resolución.', pt: 'Leopardo em sonho — uma lição sobre paciência e o momento certo. Se está à espreita: o momento de agir aproxima-se. Se caça: avança com determinação.', fr: 'Léopard en rêve — une leçon sur la patience et le bon moment. À l\'affût : l\'instant d\'agir approche. Chassant : avance avec résolution.', ja: '夢の中のヒョウ——忍耐と好機についての教え。待ち伏せているなら、動くべき瞬間が近づいている。狩るなら、決意をもって進め。' },
    shadow: { tr: 'Aşırı kontrol. Her hamleyi ölçmek, kendiliğindenliği öldürür. Pars hep hesaplıdır, ama insan değildir.', en: 'Excessive control. Measuring every move kills spontaneity. The leopard is always calculating — but it is not human.', de: 'Übermäßige Kontrolle. Jeden Schritt abzuwägen tötet die Spontaneität. Der Leopard ist stets berechnend — doch er ist kein Mensch.', es: 'Control excesivo. Medir cada movimiento mata la espontaneidad. El leopardo siempre calcula — pero no es humano.', pt: 'Controlo excessivo. Medir cada movimento mata a espontaneidade. O leopardo está sempre a calcular — mas não é humano.', fr: 'Contrôle excessif. Mesurer chaque geste tue la spontanéité. Le léopard calcule toujours — mais il n\'est pas humain.', ja: '過度の制御。一手ごとに測れば、自発性は死ぬ。ヒョウは常に計算している——だが人間ではない。' },
    whenAppears: { tr: 'Stratejik bir bekleyişte, çabuk hareket etmek yerine sezgiyi beklemen gerekirken, yalnız savaşırken.', en: 'In a strategic wait, when you must await intuition rather than act quickly, when fighting alone.', de: 'In einem strategischen Warten, wenn du eher die Intuition abwarten als rasch handeln musst, wenn du allein kämpfst.', es: 'En una espera estratégica, cuando debes aguardar la intuición en vez de actuar rápido, cuando luchas solo.', pt: 'Numa espera estratégica, quando deves aguardar a intuição em vez de agir depressa, quando lutas sozinho.', fr: 'Dans une attente stratégique, quand tu dois attendre l\'intuition plutôt qu\'agir vite, quand tu combats seul.', ja: '戦略的な待機のとき、急いで動くより直感を待たねばならぬとき、独りで戦うときに。' },
    traditions: [
      { culture: { tr: 'Pers/Türk', en: 'Persian/Turkic', de: 'Persisch/Türkisch', es: 'Persa/Túrquico', pt: 'Persa/Túrquico', fr: 'Perse/Turc', ja: 'ペルシア／テュルク' }, meaning: { tr: '"Pars" Eski Türkçe ve Farsça\'da kaplan/leoparddan ayrı bir hayvan — bağımsız ve yalnız savaşçı.', en: 'In Old Turkic and Persian, "pars" is an animal distinct from the tiger/leopard — the independent, solitary warrior.', de: 'Im Alttürkischen und Persischen ist "pars" ein vom Tiger/Leoparden verschiedenes Tier — der unabhängige, einsame Krieger.', es: 'En el turco antiguo y el persa, "pars" es un animal distinto del tigre/leopardo — el guerrero independiente y solitario.', pt: 'No turco antigo e no persa, "pars" é um animal distinto do tigre/leopardo — o guerreiro independente e solitário.', fr: 'En vieux-turc et en persan, "pars" est un animal distinct du tigre/léopard — le guerrier indépendant et solitaire.', ja: '古テュルク語とペルシア語において「パルス」はトラ／ヒョウとは別の動物——独立した孤高の戦士。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Dionysos\'un bineği — coşku ve vahşi bilgeliğin birleşimi. Şarap tanrısı parsın sırtında.', en: 'Dionysus\'s mount — the union of ecstasy and wild wisdom. The wine god rides upon the leopard.', de: 'Das Reittier des Dionysos — die Vereinigung von Ekstase und wilder Weisheit. Der Weingott reitet auf dem Leoparden.', es: 'La montura de Dioniso — la unión del éxtasis y la sabiduría salvaje. El dios del vino cabalga sobre el leopardo.', pt: 'A montaria de Dioniso — a união do êxtase e da sabedoria selvagem. O deus do vinho cavalga sobre o leopardo.', fr: 'La monture de Dionysos — l\'union de l\'extase et de la sagesse sauvage. Le dieu du vin chevauche le léopard.', ja: 'ディオニュソスの乗り物——恍惚と野生の知恵の結合。葡萄酒の神はヒョウの背に乗る。' } },
      { culture: { tr: 'Afrika', en: 'African', de: 'Afrikanisch', es: 'Africano', pt: 'Africano', fr: 'Africain', ja: 'アフリカ' }, meaning: { tr: 'Maasai geleneğinde — yalnız avcının onuru. Genç savaşçının olgunluk sınavı.', en: 'In Maasai tradition — the honor of the solitary hunter. The young warrior\'s test of maturity.', de: 'In der Maasai-Tradition — die Ehre des einsamen Jägers. Die Reifeprüfung des jungen Kriegers.', es: 'En la tradición masái — el honor del cazador solitario. La prueba de madurez del joven guerrero.', pt: 'Na tradição masai — a honra do caçador solitário. A prova de maturidade do jovem guerreiro.', fr: 'Dans la tradition massaï — l\'honneur du chasseur solitaire. L\'épreuve de maturité du jeune guerrier.', ja: 'マサイの伝統において——孤独な狩人の誉れ。若き戦士の成熟の試練。' } },
      { culture: { tr: 'Hint', en: 'Hindu', de: 'Hinduistisch', es: 'Hindú', pt: 'Hindu', fr: 'Hindou', ja: 'ヒンドゥー' }, meaning: { tr: 'Durga\'nın bineği — kötülüğü mahveden tanrıçanın bir formu.', en: 'Durga\'s mount — a form of the goddess who destroys evil.', de: 'Das Reittier der Durga — eine Gestalt der Göttin, die das Böse vernichtet.', es: 'La montura de Durga — una forma de la diosa que destruye el mal.', pt: 'A montaria de Durga — uma forma da deusa que destrói o mal.', fr: 'La monture de Durga — une forme de la déesse qui détruit le mal.', ja: 'ドゥルガーの乗り物——悪を滅ぼす女神の一つの姿。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Beş zehrin kovucusu. Tılsım hayvanı — gizli kötülüğü görür ve avlar.', en: 'The repeller of the five poisons. A talismanic animal — sees and hunts hidden evil.', de: 'Der Vertreiber der fünf Gifte. Ein Talismantier — sieht und jagt das verborgene Böse.', es: 'El que repele los cinco venenos. Un animal talismán — ve y caza el mal oculto.', pt: 'O que repele os cinco venenos. Um animal talismã — vê e caça o mal oculto.', fr: 'Le repousseur des cinq poisons. Un animal talisman — voit et chasse le mal caché.', ja: '五毒を退ける者。護符の動物——隠れた悪を見抜き、狩る。' } },
    ],
    myths: [
      { tr: 'Dionysos ve Pars: Yunan mitolojisinde şarap ve coşku tanrısı Dionysos parsın sırtında gezer. Pars\'ın bakışında hem ölüm hem zevk var — yaşam paradoksunun bineği.', en: 'Dionysus and the Leopard: In Greek mythology, the god of wine and ecstasy rides upon the leopard. In the leopard\'s gaze are both death and delight — the mount of life\'s paradox.', de: 'Dionysos und der Leopard: In der griechischen Mythologie reitet der Gott des Weines und der Ekstase auf dem Leoparden. Im Blick des Leoparden liegen Tod und Lust zugleich — das Reittier des Paradoxons des Lebens.', es: 'Dioniso y el leopardo: En la mitología griega, el dios del vino y el éxtasis cabalga sobre el leopardo. En la mirada del leopardo hay muerte y deleite — la montura de la paradoja de la vida.', pt: 'Dioniso e o leopardo: Na mitologia grega, o deus do vinho e do êxtase cavalga sobre o leopardo. No olhar do leopardo há morte e deleite — a montaria do paradoxo da vida.', fr: 'Dionysos et le léopard : Dans la mythologie grecque, le dieu du vin et de l\'extase chevauche le léopard. Dans le regard du léopard sont à la fois la mort et le plaisir — la monture du paradoxe de la vie.', ja: 'ディオニュソスとヒョウ：ギリシア神話において、葡萄酒と恍惚の神はヒョウの背に乗って巡る。ヒョウのまなざしには死と悦楽の双方がある——生の逆説の乗り物。' },
      { tr: 'Anadolu Parsı: Antik kaynaklarda Toros Dağları\'nda yaşayan Anadolu parsı yiğitliğin simgesiydi. Bugün neredeyse soyu tükenmiş — kaybedilen bilgeliğin sessiz işareti.', en: 'The Anatolian Leopard: In ancient sources, the Anatolian leopard of the Taurus Mountains was the symbol of valor. Today nearly extinct — the silent sign of lost wisdom.', de: 'Der anatolische Leopard: In antiken Quellen war der anatolische Leopard der Taurus-Berge das Symbol der Tapferkeit. Heute fast ausgestorben — das stille Zeichen verlorener Weisheit.', es: 'El leopardo anatolio: En fuentes antiguas, el leopardo anatolio de los montes Tauro era el símbolo del valor. Hoy casi extinto — el signo silencioso de la sabiduría perdida.', pt: 'O leopardo anatólio: Em fontes antigas, o leopardo anatólio dos montes Tauro era o símbolo do valor. Hoje quase extinto — o sinal silencioso da sabedoria perdida.', fr: 'Le léopard anatolien : Dans les sources antiques, le léopard anatolien des monts Taurus était le symbole de la vaillance. Aujourd\'hui presque éteint — le signe silencieux de la sagesse perdue.', ja: 'アナトリアヒョウ：古代の記録において、トロス山脈に棲むアナトリアヒョウは勇猛の象徴だった。今やほぼ絶滅した——失われた知恵の静かな徴。' },
    ],
  },

  // ─── a020 Arı ───────────────────────────────────────────────────────────
  a020: {
    jung: { tr: '"Hizmetkâr Yaratıcı" arketipi. Arı — birey ve kolektif aynı bedende. İlhamı tatlıya dönüştüren çalışkanlık.', en: 'The "Servant-Creator" archetype. The bee — individual and collective in one body. The diligence that turns inspiration into sweetness.', de: 'Der Archetyp des "dienenden Schöpfers". Die Biene — Individuum und Kollektiv in einem Leib. Der Fleiß, der Inspiration in Süße verwandelt.', es: 'El arquetipo del "Creador Servidor". La abeja — individuo y colectivo en un mismo cuerpo. La diligencia que convierte la inspiración en dulzura.', pt: 'O arquétipo do "Criador Servidor". A abelha — indivíduo e coletivo num mesmo corpo. A diligência que transforma a inspiração em doçura.', fr: 'L\'archétype du "Créateur serviteur". L\'abeille — individu et collectif dans un même corps. La diligence qui change l\'inspiration en douceur.', ja: '「奉仕する創造者」の元型。ミツバチ——個と集団が一つの体に。霊感を甘美へと変える勤勉さ。' },
    dream: { tr: 'Arı rüyada — verimli yaratıcılık çağrısı. Sokuyorsa: bastırdığın bir görev seni uyandırıyor. Bal yapıyorsa: emeklerin meyvesini verecek.', en: 'Bee in dream — a call to fruitful creativity. If it stings: a duty you have suppressed is waking you. Making honey: your labors will bear fruit.', de: 'Biene im Traum — ein Ruf zu fruchtbarer Schöpferkraft. Sticht sie: Eine Pflicht, die du unterdrückt hast, weckt dich. Macht sie Honig: Deine Mühen werden Früchte tragen.', es: 'Abeja en sueños — una llamada a la creatividad fecunda. Si pica: un deber que has reprimido te despierta. Si hace miel: tus esfuerzos darán fruto.', pt: 'Abelha em sonho — um chamado à criatividade fecunda. Se pica: um dever que reprimiste desperta-te. Se faz mel: os teus esforços darão fruto.', fr: 'Abeille en rêve — un appel à la créativité féconde. Si elle pique : un devoir que tu as réprimé te réveille. Faisant du miel : tes efforts porteront leurs fruits.', ja: '夢の中のミツバチ——実り豊かな創造性への呼びかけ。刺すなら、抑え込んだ務めがあなたを目覚めさせている。蜜を作るなら、あなたの労苦は実を結ぶ。' },
    shadow: { tr: 'Aşırı çalışkanlık. "Ben olmasam kovan çöker" sanrısı. Arı kolektifin parçasıdır, ama tükenmek de mümkündür.', en: 'Excessive industriousness. The delusion "without me the hive collapses". The bee is part of the collective, yet burnout is possible too.', de: 'Übermäßiger Fleiß. Der Wahn "ohne mich bricht der Stock zusammen". Die Biene ist Teil des Kollektivs, doch auch Erschöpfung ist möglich.', es: 'Laboriosidad excesiva. La ilusión de "sin mí la colmena se derrumba". La abeja es parte del colectivo, pero también es posible el agotamiento.', pt: 'Laboriosidade excessiva. A ilusão de "sem mim a colmeia desmorona". A abelha é parte do coletivo, mas o esgotamento também é possível.', fr: 'Zèle excessif. L\'illusion "sans moi la ruche s\'effondre". L\'abeille fait partie du collectif, mais l\'épuisement est aussi possible.', ja: '過度の勤勉。「私がいなければ巣は崩れる」という思い込み。ミツバチは集団の一部だが、燃え尽きることもまたありうる。' },
    whenAppears: { tr: 'Verimli bir döneme girerken, ortak bir projede yer alırken, ilham balına çevirmen gerektiğinde.', en: 'When entering a fertile period, while joining a shared project, when you must turn inspiration into honey.', de: 'Wenn du in eine fruchtbare Phase eintrittst, während du dich einem gemeinsamen Projekt anschließt, wenn du Inspiration in Honig verwandeln musst.', es: 'Al entrar en un período fértil, al sumarte a un proyecto compartido, cuando debes convertir la inspiración en miel.', pt: 'Ao entrar num período fértil, ao juntares-te a um projeto comum, quando deves transformar a inspiração em mel.', fr: 'En entrant dans une période féconde, en rejoignant un projet commun, quand tu dois changer l\'inspiration en miel.', ja: '実り多き時期に入るとき、共同の企てに加わるとき、霊感を蜜へと変えねばならぬときに。' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Ra\'nın gözyaşlarından doğan arılar — güneş tanrısının yeryüzü habercileri. Bal, tanrı kanı.', en: 'Bees born from Ra\'s tears — earthly messengers of the sun god. Honey is the gods\' blood.', de: 'Bienen, geboren aus den Tränen Ras — irdische Boten des Sonnengottes. Honig ist das Blut der Götter.', es: 'Abejas nacidas de las lágrimas de Ra — mensajeras terrenales del dios solar. La miel es la sangre de los dioses.', pt: 'Abelhas nascidas das lágrimas de Rá — mensageiras terrenas do deus solar. O mel é o sangue dos deuses.', fr: 'Des abeilles nées des larmes de Rê — messagères terrestres du dieu solaire. Le miel est le sang des dieux.', ja: 'ラーの涙から生まれたミツバチ——太陽神の地上の使者。蜜は神々の血。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Melissa — Zeus\'u arılarla emziren nympha. Şair Pythagoras\'ın gizemli arı sembolü.', en: 'Melissa — the nymph who suckled Zeus with bees. The mystic bee-symbol of the poet Pythagoras.', de: 'Melissa — die Nymphe, die Zeus mit Bienen nährte. Das mystische Bienensymbol des Pythagoras.', es: 'Melisa — la ninfa que amamantó a Zeus con abejas. El místico símbolo de la abeja del poeta Pitágoras.', pt: 'Melissa — a ninfa que amamentou Zeus com abelhas. O místico símbolo da abelha do poeta Pitágoras.', fr: 'Mélissa — la nymphe qui nourrit Zeus avec des abeilles. Le symbole mystique de l\'abeille de Pythagore.', ja: 'メリッサ——ミツバチでゼウスを養ったニンフ。詩人ピタゴラスの神秘的なミツバチの象徴。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Bilgi ve ilhamın taşıyıcısı. Bardlar (şairler) "arı dilini" konuşur.', en: 'Bearer of knowledge and inspiration. The bards (poets) speak "the language of the bee".', de: 'Träger von Wissen und Inspiration. Die Barden (Dichter) sprechen "die Sprache der Biene".', es: 'Portadora de conocimiento e inspiración. Los bardos (poetas) hablan "la lengua de la abeja".', pt: 'Portadora de conhecimento e inspiração. Os bardos (poetas) falam "a língua da abelha".', fr: 'Porteuse de savoir et d\'inspiration. Les bardes (poètes) parlent "la langue de l\'abeille".', ja: '知識と霊感の担い手。吟遊詩人（バルド）は「ミツバチの言葉」を語る。' } },
      { culture: { tr: 'İslam', en: 'Islamic', de: 'Islamisch', es: 'Islámico', pt: 'Islâmico', fr: 'Islamique', ja: 'イスラーム' }, meaning: { tr: 'Kuran\'da Nahl Suresi — arıya kendine ev yapması, çiçeklerden yemesi vahyedilir. Tanrı\'nın doğrudan rehberlik ettiği yaratık.', en: 'In the Qur\'an, Surah An-Nahl — it is revealed to the bee to build its house and feed on flowers. A creature directly guided by God.', de: 'Im Koran, die Sure An-Nahl — der Biene wird offenbart, sich ein Haus zu bauen und sich von Blüten zu nähren. Ein Geschöpf, das Gott unmittelbar leitet.', es: 'En el Corán, la sura An-Nahl — se le revela a la abeja que se haga casa y se alimente de las flores. Una criatura guiada directamente por Dios.', pt: 'No Alcorão, a sura An-Nahl — é revelado à abelha que faça a sua casa e se alimente das flores. Uma criatura guiada diretamente por Deus.', fr: 'Dans le Coran, la sourate An-Nahl — il est révélé à l\'abeille de se faire une demeure et de se nourrir des fleurs. Une créature directement guidée par Dieu.', ja: 'クルアーンの蜜蜂章（アン・ナフル）——ミツバチに、家を作り花から食べるよう啓示が下される。神に直接導かれる被造物。' } },
      { culture: { tr: 'Türk Halk', en: 'Turkish Folk', de: 'Türkische Volkskultur', es: 'Folclore Turco', pt: 'Folclore Turco', fr: 'Folklore Turc', ja: 'トルコ民俗' }, meaning: { tr: 'Anadolu\'da "arı tutmak" — bereketin simgesi. Kovanı olan ailenin ocağı tüter.', en: 'In Anatolia, to "keep bees" — a symbol of abundance. The hearth of the family with a hive smokes well.', de: 'In Anatolien das "Bienenhalten" — ein Symbol des Überflusses. Der Herd der Familie mit einem Bienenstock raucht gut.', es: 'En Anatolia, "tener abejas" — símbolo de abundancia. El hogar de la familia con colmena humea bien.', pt: 'Na Anatólia, "criar abelhas" — símbolo de abundância. O lar da família com colmeia fumega bem.', fr: 'En Anatolie, "tenir des abeilles" — symbole d\'abondance. Le foyer de la famille qui possède une ruche fume bien.', ja: 'アナトリアにおける「ミツバチを飼うこと」——豊穣の象徴。巣箱をもつ家の竈はよく煙る。' } },
    ],
    myths: [
      { tr: 'Melissa ve Zeus: Bebek Zeus dağda saklanmışken nympha Melissa onu arı balıyla besler. Bu yüzden arılar "Melissa\'nın kızları" olur — kutsal şifa taşıyıcıları.', en: 'Melissa and Zeus: While the infant Zeus is hidden on the mountain, the nymph Melissa feeds him with honey from the bees. Thus bees become "Melissa\'s daughters" — bearers of sacred healing.', de: 'Melissa und Zeus: Während der Säugling Zeus im Gebirge verborgen ist, nährt ihn die Nymphe Melissa mit dem Honig der Bienen. So werden die Bienen zu "Melissas Töchtern" — Trägerinnen heiliger Heilung.', es: 'Melisa y Zeus: Mientras el niño Zeus está oculto en la montaña, la ninfa Melisa lo alimenta con miel de las abejas. Así las abejas se vuelven "hijas de Melisa" — portadoras de sanación sagrada.', pt: 'Melissa e Zeus: Enquanto o menino Zeus está oculto na montanha, a ninfa Melissa alimenta-o com o mel das abelhas. Assim as abelhas tornam-se "filhas de Melissa" — portadoras de cura sagrada.', fr: 'Mélissa et Zeus : Tandis que l\'enfant Zeus est caché dans la montagne, la nymphe Mélissa le nourrit du miel des abeilles. Ainsi les abeilles deviennent "les filles de Mélissa" — porteuses de guérison sacrée.', ja: 'メリッサとゼウス：幼子ゼウスが山に隠されているあいだ、ニンフのメリッサがミツバチの蜜で彼を養う。こうしてミツバチは「メリッサの娘たち」となる——聖なる癒しの担い手。' },
      { tr: 'Nahl Suresi: Kuran\'da Allah arıya doğrudan ilham eder: "Dağlardan, ağaçlardan ev edin... çiçeklerden ye." Arı, vahiy alabilecek bilince yakın bir varlık olarak konumlanır.', en: 'Surah An-Nahl: In the Qur\'an, God directly inspires the bee: "Take houses in the mountains, in the trees... eat of the flowers." The bee is positioned as a being near to a consciousness capable of receiving revelation.', de: 'Die Sure An-Nahl: Im Koran inspiriert Gott die Biene unmittelbar: "Nimm dir Häuser in den Bergen, in den Bäumen ... iss von den Blüten." Die Biene wird als Wesen positioniert, das einem Bewusstsein nahe ist, das Offenbarung empfangen kann.', es: 'La sura An-Nahl: En el Corán, Dios inspira directamente a la abeja: "Toma casas en las montañas, en los árboles... come de las flores." La abeja se sitúa como un ser cercano a una conciencia capaz de recibir revelación.', pt: 'A sura An-Nahl: No Alcorão, Deus inspira diretamente a abelha: "Faz casas nas montanhas, nas árvores... come das flores." A abelha é colocada como um ser próximo de uma consciência capaz de receber revelação.', fr: 'La sourate An-Nahl : Dans le Coran, Dieu inspire directement l\'abeille : "Prends des demeures dans les montagnes, dans les arbres... mange des fleurs." L\'abeille est placée comme un être proche d\'une conscience capable de recevoir la révélation.', ja: '蜜蜂章（アン・ナフル）：クルアーンにおいて、神はミツバチに直接霊感を授ける——「山々に、木々に家を作り……花から食べよ。」ミツバチは、啓示を受けうる意識に近い存在として位置づけられる。' },
    ],
  },

  // ─── a021 Kırlangıç ─────────────────────────────────────────────────────
  a021: {
    jung: { tr: '"Bahar Müjdecisi" arketipi. Kırlangıç — yeniden başlayan döngünün, eve dönüşün sembolü.', en: 'The "Herald of Spring" archetype. The swallow — symbol of the cycle that begins anew, of homecoming.', de: 'Der Archetyp des "Frühlingsboten". Die Schwalbe — Symbol des Kreislaufs, der neu beginnt, der Heimkehr.', es: 'El arquetipo del "Heraldo de la Primavera". La golondrina — símbolo del ciclo que comienza de nuevo, del regreso al hogar.', pt: 'O arquétipo do "Arauto da Primavera". A andorinha — símbolo do ciclo que recomeça, do regresso a casa.', fr: 'L\'archétype du "Héraut du printemps". L\'hirondelle — symbole du cycle qui recommence, du retour au foyer.', ja: '「春の使者」の元型。ツバメ——新たに始まる循環、そして帰郷の象徴。' },
    dream: { tr: 'Kırlangıç rüyada — uzun bir kıştan sonra ısınma. Yuva yapıyorsa: bir şey kuruyorsun. Uçuyorsa: göç ve serbestlik.', en: 'Swallow in dream — warming after a long winter. Building a nest: you are establishing something. In flight: migration and freedom.', de: 'Schwalbe im Traum — Erwärmung nach einem langen Winter. Baut sie ein Nest: Du gründest etwas. Im Flug: Wanderung und Freiheit.', es: 'Golondrina en sueños — calor tras un largo invierno. Si hace nido: estás estableciendo algo. En vuelo: migración y libertad.', pt: 'Andorinha em sonho — aquecimento após um longo inverno. Se faz ninho: estás a estabelecer algo. Em voo: migração e liberdade.', fr: 'Hirondelle en rêve — le réchauffement après un long hiver. Construisant un nid : tu établis quelque chose. En vol : migration et liberté.', ja: '夢の中のツバメ——長い冬ののちの暖かさ。巣を作るなら、あなたは何かを築いている。飛んでいるなら、渡りと自由。' },
    shadow: { tr: 'Sürekli göç, asla yerleşememek. Kırlangıç döner ama her yerde misafir kalırsa — kök yok olur.', en: 'Constant migration, never able to settle. The swallow returns, but if it remains a guest everywhere — its roots vanish.', de: 'Ständige Wanderung, niemals sesshaft werden können. Die Schwalbe kehrt zurück, doch bleibt sie überall ein Gast — verschwinden ihre Wurzeln.', es: 'Migración constante, sin poder asentarse nunca. La golondrina regresa, pero si en todas partes sigue siendo huésped — sus raíces se desvanecen.', pt: 'Migração constante, sem nunca poder fixar-se. A andorinha regressa, mas se em toda a parte permanece hóspede — as suas raízes desaparecem.', fr: 'Migration constante, sans jamais pouvoir s\'établir. L\'hirondelle revient, mais si elle reste partout une invitée — ses racines disparaissent.', ja: '絶え間ない渡り、決して定住できぬこと。ツバメは戻るが、どこでも客のままであれば——その根は消える。' },
    whenAppears: { tr: 'Uzun bir bekleyiş sonrası başlangıçta, eve dönüş yolunda, mevsimsel/içsel bir geçişte.', en: 'At a beginning after long waiting, on the way home, in a seasonal or inner transition.', de: 'Bei einem Anfang nach langem Warten, auf dem Heimweg, in einem jahreszeitlichen oder inneren Übergang.', es: 'En un comienzo tras larga espera, en el camino a casa, en una transición estacional o interior.', pt: 'Num começo após longa espera, no caminho de volta a casa, numa transição sazonal ou interior.', fr: 'À un commencement après une longue attente, sur le chemin du retour, dans une transition saisonnière ou intérieure.', ja: '長い待ちののちの始まりに、家路の途上、季節の、あるいは内なる移り変わりに。' },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Aphrodite\'nin kuşu. Aşkın ve baharın habercisi. "İlk kırlangıç yaz getirmez" deyişi — sabır.', en: 'Aphrodite\'s bird. Herald of love and spring. The saying "one swallow does not make a summer" — patience.', de: 'Aphrodites Vogel. Herold der Liebe und des Frühlings. Das Sprichwort "Eine Schwalbe macht noch keinen Sommer" — Geduld.', es: 'El ave de Afrodita. Heraldo del amor y la primavera. El dicho "una golondrina no hace verano" — paciencia.', pt: 'A ave de Afrodite. Arauto do amor e da primavera. O ditado "uma andorinha não faz verão" — paciência.', fr: 'L\'oiseau d\'Aphrodite. Héraut de l\'amour et du printemps. Le dicton "une hirondelle ne fait pas le printemps" — la patience.', ja: 'アフロディーテの鳥。愛と春の使者。「一羽のツバメは夏をもたらさない」という言葉——忍耐。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Sadakatin kuşu. Bir kez eşleşince yıllarca aynı yuvaya döner.', en: 'The bird of loyalty. Once paired, it returns to the same nest for years.', de: 'Der Vogel der Treue. Einmal verpaart, kehrt sie jahrelang zum selben Nest zurück.', es: 'El ave de la lealtad. Una vez emparejada, regresa al mismo nido durante años.', pt: 'A ave da lealdade. Uma vez emparelhada, regressa ao mesmo ninho durante anos.', fr: 'L\'oiseau de la loyauté. Une fois appariée, elle revient au même nid pendant des années.', ja: '忠誠の鳥。ひとたび番えば、何年も同じ巣へ戻る。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Çatıya kırlangıç yuva yaparsa o ev kutsanmıştır. Yuvayı bozan uğursuz sayılır.', en: 'If a swallow nests on a roof, that house is blessed. Whoever destroys the nest is deemed ill-fortuned.', de: 'Baut eine Schwalbe ein Nest auf dem Dach, ist jenes Haus gesegnet. Wer das Nest zerstört, gilt als unglückbringend.', es: 'Si una golondrina anida en un tejado, esa casa está bendecida. Quien destruye el nido se considera de mal agüero.', pt: 'Se uma andorinha faz ninho num telhado, aquela casa está abençoada. Quem destrói o ninho é tido por agourento.', fr: 'Si une hirondelle niche sur un toit, cette maison est bénie. Quiconque détruit le nid est tenu pour porte-malheur.', ja: 'ツバメが屋根に巣を作れば、その家は祝福されている。巣を壊す者は不吉とされる。' } },
      { culture: { tr: 'Roma', en: 'Roman', de: 'Römisch', es: 'Romano', pt: 'Romano', fr: 'Romain', ja: 'ローマ' }, meaning: { tr: 'Penates\'in (ev tanrıları) kuşu — ailenin koruyucusu.', en: 'The bird of the Penates (household gods) — protector of the family.', de: 'Der Vogel der Penaten (Hausgötter) — Beschützer der Familie.', es: 'El ave de los Penates (dioses del hogar) — protector de la familia.', pt: 'A ave dos Penates (deuses do lar) — protetor da família.', fr: 'L\'oiseau des Pénates (dieux du foyer) — protecteur de la famille.', ja: 'ペナーテス（家庭の神々）の鳥——家族の守護者。' } },
      { culture: { tr: 'Japonya', en: 'Japanese', de: 'Japanisch', es: 'Japonés', pt: 'Japonês', fr: 'Japonais', ja: '日本' }, meaning: { tr: 'Tsubame — bahar, gençlik ve bereketin simgesi. Çiftçinin dostu.', en: 'Tsubame — symbol of spring, youth, and abundance. The farmer\'s friend.', de: 'Tsubame — Symbol des Frühlings, der Jugend und des Überflusses. Der Freund des Bauern.', es: 'Tsubame — símbolo de la primavera, la juventud y la abundancia. El amigo del campesino.', pt: 'Tsubame — símbolo da primavera, da juventude e da abundância. O amigo do camponês.', fr: 'Tsubame — symbole du printemps, de la jeunesse et de l\'abondance. L\'ami du paysan.', ja: 'ツバメ——春、若さ、そして豊穣の象徴。農夫の友。' } },
    ],
    myths: [
      { tr: 'Prokne ve Philomela: Yunan mitolojisinde iki kız kardeş, zulümden kurtulmak için kuşa dönüşür — biri kırlangıç, diğeri bülbül olur. Acının kanatlanması.', en: 'Procne and Philomela: In Greek mythology, two sisters transform into birds to escape cruelty — one becomes a swallow, the other a nightingale. The wing-taking of pain.', de: 'Prokne und Philomela: In der griechischen Mythologie verwandeln sich zwei Schwestern in Vögel, um der Grausamkeit zu entkommen — die eine wird zur Schwalbe, die andere zur Nachtigall. Das Beflügeln des Schmerzes.', es: 'Procne y Filomela: En la mitología griega, dos hermanas se transforman en aves para escapar de la crueldad — una se vuelve golondrina, la otra ruiseñor. El alzar el vuelo del dolor.', pt: 'Procne e Filomela: Na mitologia grega, duas irmãs transformam-se em aves para escapar à crueldade — uma torna-se andorinha, a outra rouxinol. O alar do voo da dor.', fr: 'Procné et Philomèle : Dans la mythologie grecque, deux sœurs se transforment en oiseaux pour échapper à la cruauté — l\'une devient hirondelle, l\'autre rossignol. L\'envol de la douleur.', ja: 'プロクネとピロメラ：ギリシア神話において、二人の姉妹が残虐から逃れるため鳥に変わる——一人はツバメ、もう一人はナイチンゲールとなる。苦しみが翼を得ること。' },
      { tr: 'Çatı Kırlangıcı: Anadolu\'da "ocağına kırlangıç konsun" duası — en güzel bereket dileği. O yuva yıkılırsa bereket kaybolur.', en: 'The Roof Swallow: In Anatolia, the blessing "may a swallow alight on your hearth" — the finest wish of abundance. If that nest falls, the blessing departs.', de: 'Die Dachschwalbe: In Anatolien der Segen "möge eine Schwalbe sich auf deinen Herd niederlassen" — der schönste Wunsch des Überflusses. Fällt jenes Nest, weicht der Segen.', es: 'La golondrina del tejado: En Anatolia, la bendición "que una golondrina se pose en tu hogar" — el más hermoso deseo de abundancia. Si ese nido cae, la bendición se marcha.', pt: 'A andorinha do telhado: Na Anatólia, a bênção "que uma andorinha pouse no teu lar" — o mais belo desejo de abundância. Se esse ninho cai, a bênção parte.', fr: 'L\'hirondelle du toit : En Anatolie, la bénédiction "qu\'une hirondelle se pose sur ton foyer" — le plus beau vœu d\'abondance. Si ce nid tombe, la bénédiction s\'en va.', ja: '屋根のツバメ：アナトリアにおける「あなたの竈にツバメが止まりますように」という祈り——最も美しい豊穣の願い。その巣が落ちれば、祝福は去る。' },
    ],
  },

  // ─── a022 Güvercin ──────────────────────────────────────────────────────
  a022: {
    jung: { tr: '"Kutsal Ruh/Sulh" arketipi. Güvercin — masum sevgi, barış, ilahi yumuşaklık.', en: 'The "Holy Spirit/Peace" archetype. The dove — innocent love, peace, divine gentleness.', de: 'Der Archetyp "Heiliger Geist/Friede". Die Taube — unschuldige Liebe, Frieden, göttliche Sanftheit.', es: 'El arquetipo del "Espíritu Santo/Paz". La paloma — amor inocente, paz, dulzura divina.', pt: 'O arquétipo do "Espírito Santo/Paz". A pomba — amor inocente, paz, doçura divina.', fr: 'L\'archétype "Saint-Esprit/Paix". La colombe — amour innocent, paix, douceur divine.', ja: '「聖霊／和平」の元型。ハト——無垢なる愛、平和、神聖なる柔らかさ。' },
    dream: { tr: 'Güvercin rüyada — bir affediş veya barışın yaklaştığını söyler. Beyaz güvercin: kutsal mesaj. Eline konuyorsa: lütuf seni buldu.', en: 'Dove in dream — tells you a forgiveness or peace is near. White dove: sacred message. Landing on your hand: grace has found you.', de: 'Taube im Traum — sagt dir, dass eine Vergebung oder ein Friede nahe ist. Weiße Taube: heilige Botschaft. Landet sie auf deiner Hand: Die Gnade hat dich gefunden.', es: 'Paloma en sueños — te dice que un perdón o una paz están cerca. Paloma blanca: mensaje sagrado. Si se posa en tu mano: la gracia te ha encontrado.', pt: 'Pomba em sonho — diz-te que um perdão ou uma paz estão perto. Pomba branca: mensagem sagrada. Se pousa na tua mão: a graça encontrou-te.', fr: 'Colombe en rêve — te dit qu\'un pardon ou une paix sont proches. Colombe blanche : message sacré. Se posant sur ta main : la grâce t\'a trouvé.', ja: '夢の中のハト——許しや平和が近いと告げる。白いハトは聖なる報せ。あなたの手に止まるなら、恩寵があなたを見いだした。' },
    shadow: { tr: '"Hep barışçıl olmak" baskısı. Güvercin masum ama saf değildir — sınırlarını koruyamamak, kurban moduna kayma.', en: 'The pressure of "always being peaceful". The dove is innocent but not naive — failure to defend boundaries slides into victim mode.', de: 'Der Druck, "stets friedfertig zu sein". Die Taube ist unschuldig, aber nicht naiv — wer seine Grenzen nicht verteidigt, gleitet in die Opferrolle.', es: 'La presión de "ser siempre pacífico". La paloma es inocente pero no ingenua — no defender los límites desliza hacia el modo víctima.', pt: 'A pressão de "ser sempre pacífico". A pomba é inocente mas não ingénua — não defender os limites desliza para o modo vítima.', fr: 'La pression d\'"être toujours pacifique". La colombe est innocente mais non naïve — ne pas défendre ses limites glisse vers le mode victime.', ja: '「常に平和的であれ」という重圧。ハトは無垢だが愚かではない——境界を守れぬことは被害者の役回りへと滑り落ちる。' },
    whenAppears: { tr: 'Bir çatışmanın bitiminde, affediş anında, kalbinin yumuşadığı ya da yumuşaması gerektiği zamanda.', en: 'At the end of a conflict, in the moment of forgiveness, when your heart softens or must soften.', de: 'Am Ende eines Konflikts, im Moment der Vergebung, wenn dein Herz weich wird oder weich werden muss.', es: 'Al final de un conflicto, en el momento del perdón, cuando tu corazón se ablanda o debe ablandarse.', pt: 'No fim de um conflito, no momento do perdão, quando o teu coração amolece ou deve amolecer.', fr: 'À la fin d\'un conflit, au moment du pardon, quand ton cœur s\'attendrit ou doit s\'attendrir.', ja: '争いの終わりに、許しの瞬間、あなたの心が和らぐ、あるいは和らがねばならぬときに。' },
    traditions: [
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Kutsal Ruh\'un simgesi. Vaftiz sırasında İsa\'nın üzerine inen güvercin. Mesajın saflığı.', en: 'Symbol of the Holy Spirit. The dove descending upon Christ at his baptism. The purity of the message.', de: 'Symbol des Heiligen Geistes. Die Taube, die bei der Taufe auf Christus herabkommt. Die Reinheit der Botschaft.', es: 'Símbolo del Espíritu Santo. La paloma que desciende sobre Cristo en su bautismo. La pureza del mensaje.', pt: 'Símbolo do Espírito Santo. A pomba que desce sobre Cristo no seu batismo. A pureza da mensagem.', fr: 'Symbole du Saint-Esprit. La colombe descendant sur le Christ lors de son baptême. La pureté du message.', ja: '聖霊の象徴。洗礼の際にキリストの上に降りてきたハト。報せの清らかさ。' } },
      { culture: { tr: 'Yahudilik', en: 'Judaism', de: 'Judentum', es: 'Judaísmo', pt: 'Judaísmo', fr: 'Judaïsme', ja: 'ユダヤ教' }, meaning: { tr: 'Nuh\'un gemisinden salınan güvercin zeytin dalıyla döner — tufanın bitimi, barış.', en: 'The dove released from Noah\'s ark returns with an olive branch — the end of the flood, peace.', de: 'Die aus Noahs Arche entlassene Taube kehrt mit einem Ölzweig zurück — das Ende der Sintflut, der Friede.', es: 'La paloma soltada del arca de Noé regresa con una rama de olivo — el fin del diluvio, la paz.', pt: 'A pomba solta da arca de Noé regressa com um ramo de oliveira — o fim do dilúvio, a paz.', fr: 'La colombe relâchée de l\'arche de Noé revient avec un rameau d\'olivier — la fin du déluge, la paix.', ja: 'ノアの箱舟から放たれたハトはオリーブの枝をくわえて戻る——大洪水の終わり、平和。' } },
      { culture: { tr: 'İslam', en: 'Islamic', de: 'Islamisch', es: 'Islámico', pt: 'Islâmico', fr: 'Islamique', ja: 'イスラーム' }, meaning: { tr: 'Hacerü\'l-Esved\'i taşıyan kuş efsanelerinde geçer. Mevlana\'da "aşk güvercini".', en: 'Appears in legends as the bird that carried the Black Stone. In Rumi, "the dove of love".', de: 'Erscheint in Legenden als der Vogel, der den Schwarzen Stein trug. Bei Rumi "die Taube der Liebe".', es: 'Aparece en leyendas como el ave que llevó la Piedra Negra. En Rumi, "la paloma del amor".', pt: 'Aparece em lendas como a ave que transportou a Pedra Negra. Em Rumi, "a pomba do amor".', fr: 'Apparaît dans les légendes comme l\'oiseau qui porta la Pierre Noire. Chez Rûmî, "la colombe de l\'amour".', ja: '黒石（ハジャル・アスワド）を運んだ鳥として伝説に現れる。ルーミーにおける「愛のハト」。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Afrodit\'in kuşu. Aşkın ve şehvetin temsilcisi — sertlik ve yumuşaklığı bir arada.', en: 'Aphrodite\'s bird. Representative of love and desire — firmness and gentleness together.', de: 'Aphrodites Vogel. Vertreter der Liebe und des Begehrens — Festigkeit und Sanftheit zugleich.', es: 'El ave de Afrodita. Representante del amor y el deseo — firmeza y dulzura a la vez.', pt: 'A ave de Afrodite. Representante do amor e do desejo — firmeza e doçura ao mesmo tempo.', fr: 'L\'oiseau d\'Aphrodite. Représentant de l\'amour et du désir — fermeté et douceur à la fois.', ja: 'アフロディーテの鳥。愛と欲望の表れ——強さと柔らかさが一つに。' } },
      { culture: { tr: 'Sumer', en: 'Sumerian', de: 'Sumerisch', es: 'Sumerio', pt: 'Sumério', fr: 'Sumérien', ja: 'シュメール' }, meaning: { tr: 'İnanna\'nın kuşu — aşk ve savaş tanrıçası. Güvercin paradoksu: hem yumuşak hem kararlı.', en: 'Inanna\'s bird — the goddess of love and war. The dove\'s paradox: both soft and resolute.', de: 'Inannas Vogel — die Göttin der Liebe und des Krieges. Das Paradox der Taube: zugleich sanft und entschlossen.', es: 'El ave de Inanna — la diosa del amor y la guerra. La paradoja de la paloma: a la vez suave y resuelta.', pt: 'A ave de Inanna — a deusa do amor e da guerra. O paradoxo da pomba: ao mesmo tempo suave e resoluta.', fr: 'L\'oiseau d\'Inanna — la déesse de l\'amour et de la guerre. Le paradoxe de la colombe : à la fois douce et résolue.', ja: 'イナンナの鳥——愛と戦いの女神。ハトの逆説——柔らかくも決然としている。' } },
    ],
    myths: [
      { tr: 'Nuh\'un Güvercini: Tufan sonrası gemiden salınan güvercin geri döner — kara yok. Bir hafta sonra tekrar salınır, ağzında zeytin dalıyla döner. Tufan bitti. İnsanlığın yeniden başlangıcı.', en: 'Noah\'s Dove: After the flood, the dove released from the ark returns — no land. A week later released again, it returns with an olive branch in its beak. The flood is over. Humanity\'s new beginning.', de: 'Noahs Taube: Nach der Sintflut kehrt die aus der Arche entlassene Taube zurück — kein Land. Eine Woche später erneut entlassen, kehrt sie mit einem Ölzweig im Schnabel zurück. Die Sintflut ist vorüber. Der Neuanfang der Menschheit.', es: 'La paloma de Noé: Tras el diluvio, la paloma soltada del arca regresa — no hay tierra. Una semana después, soltada de nuevo, vuelve con una rama de olivo en el pico. El diluvio ha terminado. El nuevo comienzo de la humanidad.', pt: 'A pomba de Noé: Após o dilúvio, a pomba solta da arca regressa — não há terra. Uma semana depois, solta de novo, volta com um ramo de oliveira no bico. O dilúvio terminou. O novo começo da humanidade.', fr: 'La colombe de Noé : Après le déluge, la colombe relâchée de l\'arche revient — point de terre. Une semaine plus tard, relâchée de nouveau, elle revient un rameau d\'olivier au bec. Le déluge est fini. Le nouveau commencement de l\'humanité.', ja: 'ノアのハト：大洪水ののち、箱舟から放たれたハトは戻ってくる——陸地はない。一週間後に再び放たれると、嘴にオリーブの枝をくわえて戻る。洪水は終わった。人類の新たな始まり。' },
      { tr: 'Afrodit\'in Güvercinleri: Kıbrıs\'ta Afrodit tapınağında yüzlerce güvercin yetiştirilirdi. Şiddetli aşk ile yumuşak barışın aynı tanrıçada birleşmesi.', en: 'Aphrodite\'s Doves: Hundreds of doves were raised in Aphrodite\'s temple on Cyprus. Fierce love and gentle peace united in one goddess.', de: 'Aphrodites Tauben: Im Tempel der Aphrodite auf Zypern wurden Hunderte von Tauben gehalten. Heftige Liebe und sanfter Friede vereint in einer einzigen Göttin.', es: 'Las palomas de Afrodita: En el templo de Afrodita en Chipre se criaban cientos de palomas. El amor feroz y la paz dulce unidos en una sola diosa.', pt: 'As pombas de Afrodite: No templo de Afrodite em Chipre criavam-se centenas de pombas. O amor feroz e a paz suave unidos numa só deusa.', fr: 'Les colombes d\'Aphrodite : Au temple d\'Aphrodite à Chypre, on élevait des centaines de colombes. L\'amour féroce et la paix douce unis en une seule déesse.', ja: 'アフロディーテのハト：キプロスのアフロディーテ神殿では何百ものハトが飼われていた。激しい愛と柔らかな平和が一人の女神に結ばれている。' },
    ],
  },

  // ─── a023 Bülbül ────────────────────────────────────────────────────────
  a023: {
    jung: { tr: '"Aşık Sanatçı" arketipi. Bülbül — acıdan beslenen güzellik. Kalbi yaralı olduğu için en güzel öten kuş.', en: 'The "Lover-Artist" archetype. The nightingale — beauty nourished by pain. The bird that sings most beautifully because its heart is wounded.', de: 'Der Archetyp des "liebenden Künstlers". Die Nachtigall — Schönheit, vom Schmerz genährt. Der Vogel, der am schönsten singt, weil sein Herz verwundet ist.', es: 'El arquetipo del "Artista Amante". El ruiseñor — belleza nutrida por el dolor. El ave que canta más hermosamente porque su corazón está herido.', pt: 'O arquétipo do "Artista Amante". O rouxinol — beleza nutrida pela dor. A ave que canta mais belamente porque o seu coração está ferido.', fr: 'L\'archétype de l\'"Artiste amoureux". Le rossignol — beauté nourrie par la douleur. L\'oiseau qui chante le plus beau parce que son cœur est blessé.', ja: '「愛する芸術家」の元型。ナイチンゲール——苦しみに育まれた美。心が傷ついているがゆえに最も美しく歌う鳥。' },
    dream: { tr: 'Bülbül rüyada — kalbin bir sözü var, söylenmek istiyor. Gül diken üzerinde ötüyorsa: aşkın acısı yaratıcılığa dönüşüyor.', en: 'Nightingale in dream — your heart has a word that wants to be said. Singing upon a rose-thorn: the pain of love is turning into creativity.', de: 'Nachtigall im Traum — dein Herz hat ein Wort, das gesagt werden will. Singt sie auf einem Rosendorn: Der Schmerz der Liebe verwandelt sich in Schöpferkraft.', es: 'Ruiseñor en sueños — tu corazón tiene una palabra que quiere ser dicha. Cantando sobre una espina de rosa: el dolor del amor se vuelve creatividad.', pt: 'Rouxinol em sonho — o teu coração tem uma palavra que quer ser dita. Cantando sobre um espinho de rosa: a dor do amor torna-se criatividade.', fr: 'Rossignol en rêve — ton cœur a un mot qui veut être dit. Chantant sur une épine de rose : la douleur de l\'amour se change en créativité.', ja: '夢の中のナイチンゲール——あなたの心には語られたがっている言葉がある。バラの棘の上で歌うなら、愛の苦しみが創造性へと変わりつつある。' },
    shadow: { tr: 'Acı romantizmi. Mutsuzluğu sanat için kutsallaştırmak. Bülbül acıdan öter — ama hep yaralı kalmak gerekmez.', en: 'The romanticism of pain. Sacralizing unhappiness for the sake of art. The nightingale sings from pain — but one need not remain forever wounded.', de: 'Die Romantik des Schmerzes. Das Unglück um der Kunst willen zu heiligen. Die Nachtigall singt aus dem Schmerz — doch man muss nicht für immer verwundet bleiben.', es: 'El romanticismo del dolor. Sacralizar la infelicidad por el arte. El ruiseñor canta desde el dolor — pero no es preciso permanecer herido para siempre.', pt: 'O romantismo da dor. Sacralizar a infelicidade em nome da arte. O rouxinol canta a partir da dor — mas não é preciso permanecer ferido para sempre.', fr: 'Le romantisme de la douleur. Sacraliser le malheur au nom de l\'art. Le rossignol chante depuis la douleur — mais il n\'est pas nécessaire de rester à jamais blessé.', ja: '苦しみのロマン化。芸術のために不幸を神聖視すること。ナイチンゲールは苦しみから歌う——だが永遠に傷ついたままでいる必要はない。' },
    whenAppears: { tr: 'Aşk acısında, sanata dökülmesi gereken bir hisde, yas ile şarkı arasında köprüde.', en: 'In the pain of love, in a feeling that must be poured into art, on the bridge between grief and song.', de: 'Im Liebesschmerz, in einem Gefühl, das in Kunst gegossen werden muss, auf der Brücke zwischen Trauer und Gesang.', es: 'En el dolor del amor, en un sentimiento que debe verterse en arte, en el puente entre el duelo y el canto.', pt: 'Na dor do amor, num sentimento que deve ser vertido em arte, na ponte entre o luto e o canto.', fr: 'Dans la douleur de l\'amour, dans un sentiment qui doit se couler en art, sur le pont entre le deuil et le chant.', ja: '愛の苦しみのうちに、芸術へと注がれねばならぬ感情のうちに、喪と歌のあいだの橋の上で。' },
    traditions: [
      { culture: { tr: 'Sufi-Fars', en: 'Sufi-Persian', de: 'Sufisch-Persisch', es: 'Sufí-Persa', pt: 'Sufi-Persa', fr: 'Soufi-Perse', ja: 'スーフィー・ペルシア' }, meaning: { tr: '"Bülbül ve Gül" — mistik aşkın en kadim metaforu. Bülbül âşık, gül maşuk. Aşk hep yaralayan ama hep çağıran.', en: '"The Nightingale and the Rose" — the most ancient metaphor of mystical love. The nightingale is the lover, the rose the beloved. Love always wounds, yet always calls.', de: '"Die Nachtigall und die Rose" — die älteste Metapher der mystischen Liebe. Die Nachtigall ist der Liebende, die Rose die Geliebte. Die Liebe verwundet stets, doch ruft sie stets.', es: '"El ruiseñor y la rosa" — la metáfora más antigua del amor místico. El ruiseñor es el amante, la rosa la amada. El amor siempre hiere, pero siempre llama.', pt: '"O rouxinol e a rosa" — a metáfora mais antiga do amor místico. O rouxinol é o amante, a rosa a amada. O amor sempre fere, mas sempre chama.', fr: '"Le rossignol et la rose" — la plus ancienne métaphore de l\'amour mystique. Le rossignol est l\'amant, la rose l\'aimée. L\'amour blesse toujours, mais appelle toujours.', ja: '「ナイチンゲールとバラ」——神秘的な愛の最も古い比喩。ナイチンゲールは恋する者、バラは愛される者。愛は常に傷つけるが、常に呼びかける。' } },
      { culture: { tr: 'Türk Divan Şiiri', en: 'Turkish Divan Poetry', de: 'Türkische Diwan-Dichtung', es: 'Poesía Divan Turca', pt: 'Poesia Divã Turca', fr: 'Poésie Divan Turque', ja: 'トルコ・ディーワーン詩' }, meaning: { tr: 'Fuzuli\'den Nedim\'e — bülbül şairin kendisi. "Aşk derdiyle hoşem el çek ilacımdan tabib."', en: 'From Fuzuli to Nedim — the nightingale is the poet himself. "I am content with love\'s ailment; physician, withhold your cure."', de: 'Von Fuzuli bis Nedim — die Nachtigall ist der Dichter selbst. "Ich bin zufrieden mit dem Leiden der Liebe; Arzt, halte dein Heilmittel zurück."', es: 'De Fuzuli a Nedim — el ruiseñor es el poeta mismo. "Estoy contento con el mal del amor; médico, retira tu cura."', pt: 'De Fuzuli a Nedim — o rouxinol é o próprio poeta. "Contento-me com o mal do amor; médico, retira a tua cura."', fr: 'De Fuzûlî à Nedîm — le rossignol est le poète lui-même. "Je me contente du mal d\'amour ; médecin, retire ton remède."', ja: 'フズーリーからネディムへ——ナイチンゲールは詩人その人。「愛の病に私は満ち足りている。医者よ、薬を引っ込めよ。」' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Philomela — kızını kaybeden anneye dönüşen bülbül. Acının sesi.', en: 'Philomela — the nightingale into which a mother who lost her daughter is transformed. The voice of pain.', de: 'Philomela — die Nachtigall, in die eine Mutter verwandelt wird, die ihre Tochter verlor. Die Stimme des Schmerzes.', es: 'Filomela — el ruiseñor en que se transforma una madre que perdió a su hija. La voz del dolor.', pt: 'Filomela — o rouxinol em que se transforma uma mãe que perdeu a filha. A voz da dor.', fr: 'Philomèle — le rossignol en lequel se transforme une mère qui a perdu sa fille. La voix de la douleur.', ja: 'ピロメラ——娘を失った母が変じたナイチンゲール。苦しみの声。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Saraylarda bülbül beslemek — saray edebinin işareti. Şiirin müzikal hâli.', en: 'Keeping nightingales in palaces — a sign of courtly refinement. The musical form of poetry.', de: 'Nachtigallen in Palästen zu halten — ein Zeichen höfischer Verfeinerung. Die musikalische Gestalt der Dichtung.', es: 'Criar ruiseñores en los palacios — signo de refinamiento cortesano. La forma musical de la poesía.', pt: 'Criar rouxinóis nos palácios — sinal de refinamento cortesão. A forma musical da poesia.', fr: 'Garder des rossignols dans les palais — signe de raffinement courtois. La forme musicale de la poésie.', ja: '宮廷でナイチンゲールを飼うこと——宮廷の洗練の徴。詩の音楽的な姿。' } },
      { culture: { tr: 'Anadolu Halk', en: 'Anatolian Folk', de: 'Anatolische Volkskultur', es: 'Folclore Anatolio', pt: 'Folclore Anatólio', fr: 'Folklore Anatolien', ja: 'アナトリア民俗' }, meaning: { tr: 'Halk türküleri "bülbül kondu dalına" — sevdiğine sözü taşıyan elçi.', en: 'Folk songs of "the nightingale alighting on the branch" — the envoy who carries word to the beloved.', de: 'Volkslieder von "der Nachtigall, die sich auf den Zweig setzt" — der Bote, der das Wort zur Geliebten trägt.', es: 'Canciones populares de "el ruiseñor que se posa en la rama" — el enviado que lleva la palabra al amado.', pt: 'Canções populares do "rouxinol que pousa no ramo" — o enviado que leva a palavra ao amado.', fr: 'Chants populaires du "rossignol qui se pose sur la branche" — l\'envoyé qui porte la parole à l\'aimé.', ja: '「枝に止まったナイチンゲール」の民謡——愛する者へ言葉を運ぶ使い。' } },
    ],
    myths: [
      { tr: 'Bülbül ve Gül: Fars-Türk edebiyatının en derin sembolü. Bülbül her gece güle âşık öter, gül ise dikenleriyle yanıt verir. Aşk — istemek değil, oluş hâli; ulaşmak değil, var olmak.', en: 'The Nightingale and the Rose: The deepest symbol of Persian-Turkish literature. Each night the nightingale sings to the rose; the rose replies with its thorns. Love is not desiring but being; not arriving but existing.', de: 'Die Nachtigall und die Rose: Das tiefste Symbol der persisch-türkischen Literatur. Jede Nacht singt die Nachtigall der Rose; die Rose antwortet mit ihren Dornen. Liebe ist nicht Begehren, sondern Sein; nicht Ankommen, sondern Existieren.', es: 'El ruiseñor y la rosa: El símbolo más profundo de la literatura persa-turca. Cada noche el ruiseñor canta a la rosa; la rosa responde con sus espinas. El amor no es desear sino ser; no llegar sino existir.', pt: 'O rouxinol e a rosa: O símbolo mais profundo da literatura persa-turca. Cada noite o rouxinol canta para a rosa; a rosa responde com os seus espinhos. O amor não é desejar mas ser; não chegar mas existir.', fr: 'Le rossignol et la rose : Le symbole le plus profond de la littérature perso-turque. Chaque nuit le rossignol chante à la rose ; la rose répond par ses épines. L\'amour n\'est pas désirer mais être ; non arriver mais exister.', ja: 'ナイチンゲールとバラ：ペルシア・トルコ文学の最も深い象徴。夜ごとナイチンゲールはバラに歌い、バラは棘で応える。愛とは求めることではなく在ること、到達することではなく存在すること。' },
      { tr: 'Philomela\'nın Dilsizleşmesi: Yunan mitolojisinde tecavüze uğrayan Philomela\'nın dili kesilir. Sessizliğini dokumalara işler, sonra bülbüle dönüşür. Dilsiz acının sese kavuşması.', en: 'The Silencing of Philomela: In Greek mythology, Philomela, after being raped, has her tongue cut out. She weaves her silence into a tapestry and is then transformed into a nightingale. The voiceless pain finding its voice.', de: 'Die Verstummung Philomelas: In der griechischen Mythologie wird der vergewaltigten Philomela die Zunge herausgeschnitten. Sie webt ihr Schweigen in einen Wandteppich und wird dann in eine Nachtigall verwandelt. Der stumme Schmerz, der seine Stimme findet.', es: 'El enmudecimiento de Filomela: En la mitología griega, a Filomela, tras ser violada, le cortan la lengua. Teje su silencio en un tapiz y luego es transformada en ruiseñor. El dolor sin voz hallando su voz.', pt: 'O emudecimento de Filomela: Na mitologia grega, a Filomela, após ser violada, cortam-lhe a língua. Ela tece o seu silêncio numa tapeçaria e é depois transformada em rouxinol. A dor sem voz a encontrar a sua voz.', fr: 'Le mutisme de Philomèle : Dans la mythologie grecque, Philomèle, après avoir été violée, a la langue tranchée. Elle tisse son silence dans une tapisserie, puis est transformée en rossignol. La douleur muette trouvant sa voix.', ja: 'ピロメラの沈黙：ギリシア神話において、陵辱されたピロメラは舌を切られる。彼女はその沈黙を織物に織り込み、やがてナイチンゲールに変えられる。声なき苦しみが声を得ること。' },
    ],
  },

  // ─── a024 Kaplan ────────────────────────────────────────────────────────
  a024: {
    jung: { tr: '"İlkel Güç" arketipi. Kaplan — bastırılamayan tutku, vahşi yaratıcılık. Aslan kraldır, kaplan tanrıdır.', en: 'The "Primal Power" archetype. The tiger — irrepressible passion, wild creativity. The lion is king; the tiger is god.', de: 'Der Archetyp der "Urkraft". Der Tiger — unbändige Leidenschaft, wilde Schöpferkraft. Der Löwe ist König; der Tiger ist Gott.', es: 'El arquetipo del "Poder Primigenio". El tigre — pasión irreprimible, creatividad salvaje. El león es rey; el tigre es dios.', pt: 'O arquétipo do "Poder Primordial". O tigre — paixão irreprimível, criatividade selvagem. O leão é rei; o tigre é deus.', fr: 'L\'archétype de la "Puissance primordiale". Le tigre — passion irrépressible, créativité sauvage. Le lion est roi ; le tigre est dieu.', ja: '「原初の力」の元型。トラ——抑えられぬ情熱、野生の創造性。ライオンは王であり、トラは神である。' },
    dream: { tr: 'Kaplan rüyada — büyük bir güç uyanıyor. Saldırıyorsa: bastırdığın bir tutku patlamak üzere. Yanında yürüyorsa: vahşi tarafınla barıştın.', en: 'Tiger in dream — a great power is awakening. Attacking: a passion you have suppressed is about to erupt. Walking beside you: you have made peace with your wild side.', de: 'Tiger im Traum — eine große Kraft erwacht. Greift er an: Eine Leidenschaft, die du unterdrückt hast, steht kurz vor dem Ausbruch. Geht er neben dir: Du hast Frieden mit deiner wilden Seite geschlossen.', es: 'Tigre en sueños — un gran poder despierta. Si ataca: una pasión que has reprimido está por estallar. Si camina a tu lado: has hecho las paces con tu lado salvaje.', pt: 'Tigre em sonho — um grande poder desperta. Se ataca: uma paixão que reprimiste está prestes a irromper. Se caminha ao teu lado: fizeste as pazes com o teu lado selvagem.', fr: 'Tigre en rêve — une grande puissance s\'éveille. S\'il attaque : une passion que tu as réprimée est sur le point de jaillir. Marchant à tes côtés : tu as fait la paix avec ta part sauvage.', ja: '夢の中のトラ——大いなる力が目覚めつつある。襲うなら、抑え込んだ情熱が噴き出そうとしている。傍らを歩むなら、あなたは自らの野生の側面と和解した。' },
    shadow: { tr: 'Kontrolsüz öfke, yıkıcı tutku. Kaplan ehlileşmezse evi yakar. Ama ehlileştirilemez de — sadece saygı duyulur.', en: 'Uncontrolled rage, destructive passion. Untamed, the tiger burns the house. Yet it cannot be tamed — only respected.', de: 'Unkontrollierter Zorn, zerstörerische Leidenschaft. Ungezähmt brennt der Tiger das Haus nieder. Doch er lässt sich nicht zähmen — nur achten.', es: 'Ira descontrolada, pasión destructiva. Sin domar, el tigre incendia la casa. Pero no puede ser domado — solo respetado.', pt: 'Ira descontrolada, paixão destruidora. Por domar, o tigre incendeia a casa. Mas não pode ser domado — apenas respeitado.', fr: 'Colère incontrôlée, passion destructrice. Non dompté, le tigre brûle la maison. Mais il ne peut être dompté — seulement respecté.', ja: '制御なき怒り、破壊的な情熱。馴らされなければ、トラは家を焼く。だが馴らすことはできない——ただ敬うほかない。' },
    whenAppears: { tr: 'Büyük bir tutkunun uyandığı, sınır koymak için kükremek gerektiğinde, yaratıcı bir çağrının dirilişinde.', en: 'When a great passion awakens, when you must roar to set a boundary, at the resurrection of a creative summons.', de: 'Wenn eine große Leidenschaft erwacht, wenn du brüllen musst, um eine Grenze zu setzen, bei der Wiederbelebung einer schöpferischen Berufung.', es: 'Cuando despierta una gran pasión, cuando debes rugir para poner un límite, en la resurrección de una llamada creativa.', pt: 'Quando desperta uma grande paixão, quando deves rugir para impor um limite, na ressurreição de um chamado criativo.', fr: 'Quand une grande passion s\'éveille, quand tu dois rugir pour poser une limite, à la résurrection d\'un appel créatif.', ja: '大いなる情熱が目覚めるとき、境界を引くために吼えねばならぬとき、創造的な呼び声がよみがえるときに。' },
    traditions: [
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Dört kutsal hayvandan biri (Bai Hu — Ak Kaplan). Batı, sonbahar, metal ve cesaretin koruyucusu.', en: 'One of the Four Sacred Animals (Bai Hu — White Tiger). Guardian of the west, autumn, metal, and courage.', de: 'Eines der Vier Heiligen Tiere (Bai Hu — Weißer Tiger). Hüter des Westens, des Herbstes, des Metalls und des Mutes.', es: 'Uno de los Cuatro Animales Sagrados (Bai Hu — Tigre Blanco). Guardián del oeste, el otoño, el metal y el coraje.', pt: 'Um dos Quatro Animais Sagrados (Bai Hu — Tigre Branco). Guardião do oeste, do outono, do metal e da coragem.', fr: 'L\'un des Quatre Animaux Sacrés (Bai Hu — Tigre Blanc). Gardien de l\'ouest, de l\'automne, du métal et du courage.', ja: '四神の一つ（白虎）。西、秋、金、そして勇気の守護者。' } },
      { culture: { tr: 'Hint', en: 'Hindu', de: 'Hinduistisch', es: 'Hindú', pt: 'Hindu', fr: 'Hindou', ja: 'ヒンドゥー' }, meaning: { tr: 'Durga\'nın bineği. Tanrıça kötülüğe karşı kaplanın sırtında savaşır.', en: 'Durga\'s mount. The goddess battles evil from the tiger\'s back.', de: 'Durgas Reittier. Die Göttin kämpft vom Rücken des Tigers gegen das Böse.', es: 'La montura de Durga. La diosa combate el mal desde el lomo del tigre.', pt: 'A montaria de Durga. A deusa combate o mal das costas do tigre.', fr: 'La monture de Durga. La déesse combat le mal sur le dos du tigre.', ja: 'ドゥルガーの乗り物。女神はトラの背から悪と戦う。' } },
      { culture: { tr: 'Kore', en: 'Korean', de: 'Koreanisch', es: 'Coreano', pt: 'Coreano', fr: 'Coréen', ja: '朝鮮' }, meaning: { tr: 'Kore mitolojisinin en kutsal hayvanı. Dağların ruhu, kahramanların rehberi.', en: 'The most sacred animal of Korean mythology. Spirit of the mountains, guide of heroes.', de: 'Das heiligste Tier der koreanischen Mythologie. Geist der Berge, Führer der Helden.', es: 'El animal más sagrado de la mitología coreana. Espíritu de las montañas, guía de los héroes.', pt: 'O animal mais sagrado da mitologia coreana. Espírito das montanhas, guia dos heróis.', fr: 'L\'animal le plus sacré de la mythologie coréenne. Esprit des montagnes, guide des héros.', ja: '朝鮮神話で最も神聖な動物。山々の霊、英雄の導き手。' } },
      { culture: { tr: 'Türk Mitolojisi', en: 'Turkic Mythology', de: 'Türkische Mythologie', es: 'Mitología Túrquica', pt: 'Mitologia Túrquica', fr: 'Mythologie Turque', ja: 'テュルク神話' }, meaning: { tr: 'Anadolu\'da yok ama Orta Asya kökenli Türklerde "Bars" — savaşçı sembolü, hakanlık alameti.', en: 'Absent in Anatolia, but among the Central Asian Turks "Bars" — symbol of the warrior, emblem of the khanate.', de: 'In Anatolien fehlend, doch bei den zentralasiatischen Türken "Bars" — Symbol des Kriegers, Wahrzeichen des Khanats.', es: 'Ausente en Anatolia, pero entre los turcos de Asia Central "Bars" — símbolo del guerrero, emblema del kanato.', pt: 'Ausente na Anatólia, mas entre os turcos da Ásia Central "Bars" — símbolo do guerreiro, emblema do canato.', fr: 'Absent en Anatolie, mais chez les Turcs d\'Asie centrale "Bars" — symbole du guerrier, emblème du khanat.', ja: 'アナトリアには見られないが、中央アジア起源のテュルクにおける「バルス」——戦士の象徴、ハーン位の標。' } },
      { culture: { tr: 'Şamanik', en: 'Shamanic', de: 'Schamanisch', es: 'Chamánico', pt: 'Xamânico', fr: 'Chamanique', ja: 'シャーマニズム' }, meaning: { tr: 'Tibetan Bön\'da kaplan dağın koruyucusu — yıkıcı kutsallık.', en: 'In Tibetan Bön, the tiger is the guardian of the mountain — destructive holiness.', de: 'Im tibetischen Bön ist der Tiger der Hüter des Berges — zerstörerische Heiligkeit.', es: 'En el bön tibetano, el tigre es el guardián de la montaña — santidad destructiva.', pt: 'No bön tibetano, o tigre é o guardião da montanha — santidade destruidora.', fr: 'Dans le bön tibétain, le tigre est le gardien de la montagne — sainteté destructrice.', ja: 'チベットのボン教において、トラは山の守護者——破壊的な神聖さ。' } },
    ],
    myths: [
      { tr: 'Bai Hu — Ak Kaplan: Çin kozmolojisinde batının koruyucu hayvanı. Kahramanların yetişmesini gözetler. Ölümsüzlük arayan kahraman ondan onay almalıdır.', en: 'Bai Hu — the White Tiger: In Chinese cosmology, the western guardian. He watches over heroes\' maturation. The hero seeking immortality must have his approval.', de: 'Bai Hu — der Weiße Tiger: In der chinesischen Kosmologie der Hüter des Westens. Er wacht über die Reifung der Helden. Der Held, der nach Unsterblichkeit strebt, muss seine Billigung erlangen.', es: 'Bai Hu — el Tigre Blanco: En la cosmología china, el guardián del oeste. Vela por la maduración de los héroes. El héroe que busca la inmortalidad debe obtener su aprobación.', pt: 'Bai Hu — o Tigre Branco: Na cosmologia chinesa, o guardião do oeste. Vela pelo amadurecimento dos heróis. O herói que busca a imortalidade deve obter a sua aprovação.', fr: 'Bai Hu — le Tigre Blanc : Dans la cosmologie chinoise, le gardien de l\'ouest. Il veille sur la maturation des héros. Le héros en quête d\'immortalité doit obtenir son approbation.', ja: '白虎（バイフー）：中国の宇宙観における西の守護者。英雄の成熟を見守る。不死を求める英雄はその承認を得ねばならない。' },
      { tr: 'Durga ve Kaplan: Hint mitolojisinde tanrıça Durga, hiçbir tanrının yenemediği şeytan Mahishasura\'yı kaplan sırtında öldürür. Vahşi gücün adaletle birleşmesi.', en: 'Durga and the Tiger: In Hindu mythology, the goddess Durga slays the demon Mahishasura, whom no god could defeat, from the back of the tiger. The union of wild power with justice.', de: 'Durga und der Tiger: In der hinduistischen Mythologie erschlägt die Göttin Durga vom Rücken des Tigers den Dämon Mahishasura, den kein Gott bezwingen konnte. Die Vereinigung wilder Macht mit Gerechtigkeit.', es: 'Durga y el tigre: En la mitología hindú, la diosa Durga mata desde el lomo del tigre al demonio Mahishasura, a quien ningún dios pudo vencer. La unión del poder salvaje con la justicia.', pt: 'Durga e o tigre: Na mitologia hindu, a deusa Durga mata das costas do tigre o demónio Mahishasura, que nenhum deus pôde vencer. A união do poder selvagem com a justiça.', fr: 'Durga et le tigre : Dans la mythologie hindoue, la déesse Durga tue, depuis le dos du tigre, le démon Mahishasura qu\'aucun dieu n\'a pu vaincre. L\'union de la puissance sauvage et de la justice.', ja: 'ドゥルガーとトラ：ヒンドゥー神話において、女神ドゥルガーは、いかなる神も倒せなかった魔神マヒシャースラをトラの背から討つ。野生の力と正義の結合。' },
    ],
  },

  // ─── a025 Köpek ─────────────────────────────────────────────────────────
  a025: {
    jung: { tr: '"Sadık Yoldaş" arketipi. Köpek — koşulsuz bağlılık, ehlileştirilmiş içgüdü. İnsanın yanındaki vahşi.', en: 'The "Faithful Companion" archetype. The dog — unconditional bond, tamed instinct. The wild one beside the human.', de: 'Der Archetyp des "treuen Gefährten". Der Hund — bedingungslose Bindung, gezähmter Instinkt. Der Wilde an der Seite des Menschen.', es: 'El arquetipo del "Compañero Fiel". El perro — vínculo incondicional, instinto domado. El salvaje junto al humano.', pt: 'O arquétipo do "Companheiro Fiel". O cão — vínculo incondicional, instinto domado. O selvagem ao lado do humano.', fr: 'L\'archétype du "Compagnon fidèle". Le chien — lien inconditionnel, instinct apprivoisé. Le sauvage aux côtés de l\'humain.', ja: '「忠実な伴侶」の元型。イヌ——無条件の絆、馴らされた本能。人の傍らにある野生。' },
    dream: { tr: 'Köpek rüyada — sadakatin testi. Sana saldırıyorsa: hayatında biri sınır çiğniyor. Yanında yürüyorsa: rehberin yakın, içgüdüne güven.', en: 'Dog in dream — a test of loyalty. Attacking you: someone in your life is crossing a boundary. Walking beside you: your guide is near, trust your instinct.', de: 'Hund im Traum — eine Prüfung der Treue. Greift er dich an: Jemand in deinem Leben überschreitet eine Grenze. Geht er neben dir: Dein Führer ist nah, vertraue deinem Instinkt.', es: 'Perro en sueños — una prueba de lealtad. Si te ataca: alguien en tu vida traspasa un límite. Si camina a tu lado: tu guía está cerca, confía en tu instinto.', pt: 'Cão em sonho — uma prova de lealdade. Se te ataca: alguém na tua vida ultrapassa um limite. Se caminha ao teu lado: o teu guia está perto, confia no teu instinto.', fr: 'Chien en rêve — une épreuve de loyauté. S\'il t\'attaque : quelqu\'un dans ta vie franchit une limite. Marchant à tes côtés : ton guide est proche, fais confiance à ton instinct.', ja: '夢の中のイヌ——忠誠の試練。あなたを襲うなら、あなたの人生で誰かが境界を侵している。傍らを歩むなら、導き手が近い。本能を信じよ。' },
    shadow: { tr: 'Aşırı sadakat — kendini kaybetme pahasına bağlılık. Köpek sahibine bağlıdır ama köle değildir; sevgi ile teslimiyet farkı.', en: 'Excessive loyalty — devotion at the cost of self-loss. The dog is bonded to its master but is not a slave; the difference between love and submission.', de: 'Übermäßige Treue — Hingabe um den Preis der Selbstaufgabe. Der Hund ist an seinen Herrn gebunden, doch kein Sklave; der Unterschied zwischen Liebe und Unterwerfung.', es: 'Lealtad excesiva — devoción al costo de perderse a sí mismo. El perro está unido a su amo pero no es esclavo; la diferencia entre amor y sumisión.', pt: 'Lealdade excessiva — devoção ao custo da perda de si. O cão está ligado ao dono mas não é escravo; a diferença entre amor e submissão.', fr: 'Loyauté excessive — dévotion au prix de la perte de soi. Le chien est lié à son maître mais n\'est pas esclave ; la différence entre amour et soumission.', ja: '過度の忠誠——自己を失う代償としての献身。イヌは主に結ばれているが奴隷ではない。愛と服従の違い。' },
    whenAppears: { tr: 'Bir dostluğun derinleşmesinde, koşulsuz sevgi sınavında, ölüm ya da kayıp eşiklerinde (köpek geçişe eşlik eder).', en: 'In the deepening of a friendship, in a test of unconditional love, on the thresholds of death or loss (the dog accompanies the passage).', de: 'In der Vertiefung einer Freundschaft, in einer Prüfung bedingungsloser Liebe, an den Schwellen von Tod oder Verlust (der Hund begleitet den Übergang).', es: 'En el ahondamiento de una amistad, en una prueba de amor incondicional, en los umbrales de la muerte o la pérdida (el perro acompaña el tránsito).', pt: 'No aprofundamento de uma amizade, numa prova de amor incondicional, nos limiares da morte ou da perda (o cão acompanha a passagem).', fr: 'Dans l\'approfondissement d\'une amitié, dans une épreuve d\'amour inconditionnel, sur les seuils de la mort ou de la perte (le chien accompagne le passage).', ja: '友情が深まるとき、無条件の愛の試練、死や喪失の境（イヌは移行に付き添う）に。' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Anubis — çakal başlı tanrı, ölüleri öbür dünyaya taşır. Geçişin koruyucusu.', en: 'Anubis — the jackal-headed god who carries the dead to the otherworld. Guardian of the passage.', de: 'Anubis — der schakalköpfige Gott, der die Toten ins Jenseits geleitet. Hüter des Übergangs.', es: 'Anubis — el dios con cabeza de chacal que lleva a los muertos al más allá. Guardián del tránsito.', pt: 'Anúbis — o deus com cabeça de chacal que leva os mortos ao além. Guardião da passagem.', fr: 'Anubis — le dieu à tête de chacal qui mène les morts dans l\'au-delà. Gardien du passage.', ja: 'アヌビス——ジャッカルの頭をもつ神。死者を彼岸へ運ぶ。移行の守護者。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Kerberos — Hades\'in üç başlı bekçi köpeği. Ölüler diyarının kapısı.', en: 'Cerberus — Hades\'s three-headed watchdog. The gate of the land of the dead.', de: 'Kerberos — der dreiköpfige Wachhund des Hades. Das Tor zum Totenreich.', es: 'Cerbero — el perro guardián de tres cabezas de Hades. La puerta del reino de los muertos.', pt: 'Cérbero — o cão guardião de três cabeças de Hades. O portão do reino dos mortos.', fr: 'Cerbère — le chien de garde à trois têtes d\'Hadès. La porte du royaume des morts.', ja: 'ケルベロス——ハデスの三頭の番犬。死者の国の門。' } },
      { culture: { tr: 'Türk-İslam', en: 'Turco-Islamic', de: 'Türkisch-Islamisch', es: 'Turco-Islámico', pt: 'Turco-Islâmico', fr: 'Turco-Islamique', ja: 'トルコ・イスラーム' }, meaning: { tr: 'Eshab-ı Kehf (Mağara Arkadaşları) ile birlikte 309 yıl uyuyan Kıtmir — Kuran\'da geçen tek köpek. Sadakatin kutsallaşması.', en: 'Qitmir, who slept 309 years with the Companions of the Cave (Ashab al-Kahf) — the only dog mentioned in the Qur\'an. The sanctification of loyalty.', de: 'Qitmir, der 309 Jahre mit den Gefährten der Höhle (Ashab al-Kahf) schlief — der einzige Hund, der im Koran erwähnt wird. Die Heiligung der Treue.', es: 'Qitmir, que durmió 309 años con los Compañeros de la Cueva (Ashab al-Kahf) — el único perro mencionado en el Corán. La santificación de la lealtad.', pt: 'Qitmir, que dormiu 309 anos com os Companheiros da Caverna (Ashab al-Kahf) — o único cão mencionado no Alcorão. A santificação da lealdade.', fr: 'Qitmir, qui dormit 309 ans avec les Compagnons de la Caverne (Ashab al-Kahf) — le seul chien mentionné dans le Coran. La sanctification de la loyauté.', ja: 'キトミール——洞窟の仲間たち（アスハーブ・カフフ）とともに三百九年眠った犬。クルアーンに記される唯一の犬。忠誠の聖化。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Cu Sith — peri köpekleri. Hem rehber hem haberci. Ölümün habercisi.', en: 'Cù-sìth — fairy dogs. Both guide and messenger. Herald of death.', de: 'Cù-sìth — Feenhunde. Zugleich Führer und Bote. Herold des Todes.', es: 'Cù-sìth — perros de las hadas. A la vez guía y mensajero. Heraldo de la muerte.', pt: 'Cù-sìth — cães das fadas. Ao mesmo tempo guia e mensageiro. Arauto da morte.', fr: 'Cù-sìth — chiens des fées. À la fois guide et messager. Héraut de la mort.', ja: 'クー・シー——妖精の犬。導き手であり使者でもある。死の使者。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Yama\'nın (ölüm tanrısı) iki dört gözlü köpeği — ruhun yolculuğunda eşlikçi.', en: 'The two four-eyed dogs of Yama (the god of death) — companions on the soul\'s journey.', de: 'Die zwei vieräugigen Hunde des Yama (des Todesgottes) — Begleiter auf der Reise der Seele.', es: 'Los dos perros de cuatro ojos de Yama (el dios de la muerte) — compañeros en el viaje del alma.', pt: 'Os dois cães de quatro olhos de Yama (o deus da morte) — companheiros na viagem da alma.', fr: 'Les deux chiens à quatre yeux de Yama (le dieu de la mort) — compagnons du voyage de l\'âme.', ja: 'ヤマ（死の神）の四つ目の二匹の犬——魂の旅の伴侶。' } },
    ],
    myths: [
      { tr: 'Ashab-ı Kehf ve Kıtmir: Kuran\'da geçen mağara arkadaşları zulümden kaçar, mağarada uyurlar. Yanlarında bir köpek de uyur. Üç yüz yıl sonra uyanırlar. Köpeğin adı: Kıtmir. Sadakatin ödüllendirilmesi.', en: 'The Companions of the Cave and Qitmir: The Cave Companions in the Qur\'an flee persecution and sleep in a cave. A dog sleeps with them. They wake after three hundred years. The dog\'s name: Qitmir. The reward of loyalty.', de: 'Die Gefährten der Höhle und Qitmir: Die Höhlengefährten im Koran fliehen vor Verfolgung und schlafen in einer Höhle. Ein Hund schläft bei ihnen. Nach dreihundert Jahren erwachen sie. Der Name des Hundes: Qitmir. Die Belohnung der Treue.', es: 'Los Compañeros de la Cueva y Qitmir: Los Compañeros de la Cueva en el Corán huyen de la persecución y duermen en una cueva. Un perro duerme con ellos. Despiertan tras trescientos años. El nombre del perro: Qitmir. La recompensa de la lealtad.', pt: 'Os Companheiros da Caverna e Qitmir: Os Companheiros da Caverna no Alcorão fogem da perseguição e dormem numa caverna. Um cão dorme com eles. Acordam após trezentos anos. O nome do cão: Qitmir. A recompensa da lealdade.', fr: 'Les Compagnons de la Caverne et Qitmir : Les Compagnons de la Caverne dans le Coran fuient la persécution et dorment dans une grotte. Un chien dort avec eux. Ils s\'éveillent après trois cents ans. Le nom du chien : Qitmir. La récompense de la loyauté.', ja: '洞窟の仲間たちとキトミール：クルアーンに記される洞窟の仲間たちは迫害を逃れ、洞窟で眠る。一匹の犬が彼らとともに眠る。三百年後に目覚める。犬の名はキトミール。忠誠への報い。' },
      { tr: 'Anubis ve Ölüm: Mısır mitolojisinde Anubis öleninin kalbini Maat tüyüyle tartar. Eğer kalp tüyden hafifse — cennet. Ağırsa — yokluk. Köpek başlı tanrı: adil terazi.', en: 'Anubis and Death: In Egyptian mythology, Anubis weighs the deceased\'s heart against the feather of Maat. If the heart is lighter than the feather — paradise. Heavier — oblivion. The dog-headed god: the just scale.', de: 'Anubis und der Tod: In der ägyptischen Mythologie wiegt Anubis das Herz des Verstorbenen gegen die Feder der Maat. Ist das Herz leichter als die Feder — das Paradies. Schwerer — die Vernichtung. Der hundsköpfige Gott: die gerechte Waage.', es: 'Anubis y la muerte: En la mitología egipcia, Anubis pesa el corazón del difunto contra la pluma de Maat. Si el corazón es más ligero que la pluma — el paraíso. Más pesado — la nada. El dios con cabeza de perro: la balanza justa.', pt: 'Anúbis e a morte: Na mitologia egípcia, Anúbis pesa o coração do falecido contra a pena de Maat. Se o coração é mais leve que a pena — o paraíso. Mais pesado — o nada. O deus com cabeça de cão: a balança justa.', fr: 'Anubis et la mort : Dans la mythologie égyptienne, Anubis pèse le cœur du défunt contre la plume de Maât. Si le cœur est plus léger que la plume — le paradis. Plus lourd — le néant. Le dieu à tête de chien : la balance juste.', ja: 'アヌビスと死：エジプト神話において、アヌビスは死者の心臓をマアトの羽と天秤にかける。心臓が羽より軽ければ——楽園。重ければ——虚無。犬の頭をもつ神——公正な秤。' },
    ],
  },

  // ─── a026 Çita ──────────────────────────────────────────────────────────
  a026: {
    jung: { tr: '"Şimşek Eylem" arketipi. Çita — fırsatı görüp anında harekete geçme. Hız, ama kısa süreli; tüm enerjiyi bir hamlede kullanma.', en: 'The "Lightning Action" archetype. The cheetah — seeing an opportunity and acting at once. Speed, but brief; spending all energy in a single move.', de: 'Der Archetyp der "Blitzhandlung". Der Gepard — eine Gelegenheit zu erkennen und sofort zu handeln. Geschwindigkeit, doch kurz; alle Energie in einem einzigen Zug verbraucht.', es: 'El arquetipo de la "Acción Relámpago". El guepardo — ver una oportunidad y actuar al instante. Velocidad, pero breve; gastar toda la energía en un solo movimiento.', pt: 'O arquétipo da "Ação Relâmpago". A chita — ver uma oportunidade e agir de imediato. Velocidade, mas breve; gastar toda a energia num único movimento.', fr: 'L\'archétype de l\'"Action foudroyante". Le guépard — voir une occasion et agir aussitôt. Vitesse, mais brève ; dépenser toute l\'énergie en un seul mouvement.', ja: '「電光の行動」の元型。チーター——好機を見て即座に動くこと。速さ、だが短く——全エネルギーを一手に使い切る。' },
    dream: { tr: 'Çita rüyada — bir fırsat çok kısa sürede gelip geçecek. Koşuyorsa: harekete geç, beklersen kaçar. Yorgunsa: aşırı acele ediyorsun, dinlen.', en: 'Cheetah in dream — an opportunity will come and go quickly. Running: act, if you wait it escapes. Tired: you are rushing too much, rest.', de: 'Gepard im Traum — eine Gelegenheit kommt und geht rasch. Läuft er: Handle, wartest du, entkommt sie. Ist er müde: Du eilst zu sehr, ruhe.', es: 'Guepardo en sueños — una oportunidad vendrá y se irá rápido. Si corre: actúa, si esperas se escapa. Si está cansado: te apresuras demasiado, descansa.', pt: 'Chita em sonho — uma oportunidade virá e passará depressa. Se corre: age, se esperas escapa. Se está cansada: estás a apressar-te demais, descansa.', fr: 'Guépard en rêve — une occasion viendra et passera vite. Courant : agis, si tu attends elle s\'échappe. Fatigué : tu te précipites trop, repose-toi.', ja: '夢の中のチーター——好機はすぐに来て去る。走っているなら、動け。待てば逃げる。疲れているなら、急ぎすぎている。休め。' },
    shadow: { tr: 'Sprint yaşamak. Her şeyi bir patlamada yapma takıntısı — sonrasında çöküş. Çita uzun mesafede kazanmaz, yıldız anlarda kazanır.', en: 'Living in sprints. The compulsion to do everything in one burst — followed by collapse. The cheetah does not win the long distance; it wins the star moments.', de: 'Im Sprint leben. Der Zwang, alles in einem einzigen Ausbruch zu tun — gefolgt vom Zusammenbruch. Der Gepard gewinnt nicht die lange Distanz; er gewinnt die Sternstunden.', es: 'Vivir en sprints. La compulsión de hacerlo todo en un estallido — seguida del colapso. El guepardo no gana la larga distancia; gana los momentos estelares.', pt: 'Viver em sprints. A compulsão de fazer tudo num só rebentamento — seguida do colapso. A chita não vence a longa distância; vence os momentos estelares.', fr: 'Vivre en sprints. La compulsion de tout faire en une seule explosion — suivie de l\'effondrement. Le guépard ne gagne pas la longue distance ; il gagne les moments d\'étoile.', ja: 'スプリントで生きること。何もかもを一気の爆発でやり遂げようとする強迫——その後の崩壊。チーターは長距離では勝たない。輝く一瞬で勝つ。' },
    whenAppears: { tr: 'Anlık kararlar gerektiğinde, fırsat penceresinin daraldığında, hızlı tepki ya da yenilenme arasında bir seçim anında.', en: 'When instant decisions are required, when the window of opportunity narrows, at a moment of choice between swift response and renewal.', de: 'Wenn augenblickliche Entscheidungen nötig sind, wenn sich das Fenster der Gelegenheit verengt, in einem Moment der Wahl zwischen rascher Reaktion und Erneuerung.', es: 'Cuando se requieren decisiones instantáneas, cuando la ventana de oportunidad se estrecha, en un momento de elección entre la respuesta veloz y la renovación.', pt: 'Quando se exigem decisões instantâneas, quando a janela de oportunidade se estreita, num momento de escolha entre a resposta veloz e a renovação.', fr: 'Quand des décisions instantanées sont requises, quand la fenêtre d\'opportunité se rétrécit, à un moment de choix entre la réaction rapide et le renouvellement.', ja: '即座の決断が求められるとき、好機の窓が狭まるとき、素早い反応と再生のあいだの選択の瞬間に。' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Mafdet — çita başlı tanrıça. Zehirden ve yılandan koruyan. Hızlı adaletin temsilcisi.', en: 'Mafdet — the cheetah-headed goddess. Protector from venom and serpents. Representative of swift justice.', de: 'Mafdet — die gepardenköpfige Göttin. Beschützerin vor Gift und Schlangen. Vertreterin der raschen Gerechtigkeit.', es: 'Mafdet — la diosa con cabeza de guepardo. Protectora contra el veneno y las serpientes. Representante de la justicia veloz.', pt: 'Mafdet — a deusa com cabeça de chita. Protetora contra o veneno e as serpentes. Representante da justiça veloz.', fr: 'Mafdet — la déesse à tête de guépard. Protectrice contre le venin et les serpents. Représentante de la justice rapide.', ja: 'マフデト——チーターの頭をもつ女神。毒と蛇から守る。迅速な正義の表れ。' } },
      { culture: { tr: 'Hint', en: 'Hindu', de: 'Hinduistisch', es: 'Hindú', pt: 'Hindu', fr: 'Hindou', ja: 'ヒンドゥー' }, meaning: { tr: 'Hızın ve dikkatin sembolü. Maharaja\'ların av eşlikçisi — kraliyet hızı.', en: 'Symbol of speed and attention. Hunting companion of the maharajas — royal velocity.', de: 'Symbol von Geschwindigkeit und Aufmerksamkeit. Jagdgefährte der Maharadschas — königliche Schnelligkeit.', es: 'Símbolo de la velocidad y la atención. Compañero de caza de los marajás — velocidad real.', pt: 'Símbolo da velocidade e da atenção. Companheiro de caça dos marajás — velocidade real.', fr: 'Symbole de la vitesse et de l\'attention. Compagnon de chasse des maharadjas — vélocité royale.', ja: '速さと注意の象徴。マハラジャの狩りの相棒——王者の速度。' } },
      { culture: { tr: 'Afrika', en: 'African', de: 'Afrikanisch', es: 'Africano', pt: 'Africano', fr: 'Africain', ja: 'アフリカ' }, meaning: { tr: 'Maasai geleneğinde — annenin yavruları için yaptığı fedakârlığın simgesi. Yalnız savaşan dişi.', en: 'In Maasai tradition — symbol of the mother\'s sacrifice for her cubs. The lone-fighting female.', de: 'In der Maasai-Tradition — Symbol der Aufopferung der Mutter für ihre Jungen. Das allein kämpfende Weibchen.', es: 'En la tradición masái — símbolo del sacrificio de la madre por sus crías. La hembra que lucha sola.', pt: 'Na tradição masai — símbolo do sacrifício da mãe pelas crias. A fêmea que luta sozinha.', fr: 'Dans la tradition massaï — symbole du sacrifice de la mère pour ses petits. La femelle qui combat seule.', ja: 'マサイの伝統において——子のために身を捧げる母の象徴。独りで戦う雌。' } },
      { culture: { tr: 'Pers', en: 'Persian', de: 'Persisch', es: 'Persa', pt: 'Persa', fr: 'Perse', ja: 'ペルシア' }, meaning: { tr: 'Yuyutsu — çitaların yetiştirildiği eski av kuralları. Hızın imparatorluğu.', en: 'Yuyutsu — the ancient hunting codes by which cheetahs were raised. The empire of speed.', de: 'Yuyutsu — die alten Jagdordnungen, nach denen Geparden aufgezogen wurden. Das Reich der Geschwindigkeit.', es: 'Yuyutsu — los antiguos códigos de caza con los que se criaban guepardos. El imperio de la velocidad.', pt: 'Yuyutsu — os antigos códigos de caça pelos quais as chitas eram criadas. O império da velocidade.', fr: 'Yuyutsu — les anciens codes de chasse selon lesquels on élevait les guépards. L\'empire de la vitesse.', ja: 'ユユツ——チーターを育てた古の狩りの掟。速さの帝国。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Rüzgârın hayvanı. Beş elementten hızla geçen.', en: 'The animal of the wind. The one that passes swiftly through the five elements.', de: 'Das Tier des Windes. Das, was rasch durch die fünf Elemente zieht.', es: 'El animal del viento. El que pasa veloz a través de los cinco elementos.', pt: 'O animal do vento. Aquele que passa veloz pelos cinco elementos.', fr: 'L\'animal du vent. Celui qui passe rapidement à travers les cinq éléments.', ja: '風の動物。五行を素早く駆け抜けるもの。' } },
    ],
    myths: [
      { tr: 'Mafdet: Mısır mitolojisinde Firavun\'un yatağını yılanlardan koruyan çita-tanrıça. Hıza atfedilen kutsallık: hız ölümden önce davranabilir.', en: 'Mafdet: In Egyptian mythology, the cheetah-goddess who guarded the pharaoh\'s bed from serpents. The holiness attributed to speed: speed can act before death.', de: 'Mafdet: In der ägyptischen Mythologie die Gepardengöttin, die das Bett des Pharaos vor Schlangen schützte. Die der Geschwindigkeit zugeschriebene Heiligkeit: Geschwindigkeit kann vor dem Tod handeln.', es: 'Mafdet: En la mitología egipcia, la diosa guepardo que protegía el lecho del faraón de las serpientes. La santidad atribuida a la velocidad: la velocidad puede actuar antes que la muerte.', pt: 'Mafdet: Na mitologia egípcia, a deusa-chita que protegia o leito do faraó das serpentes. A santidade atribuída à velocidade: a velocidade pode agir antes da morte.', fr: 'Mafdet : Dans la mythologie égyptienne, la déesse-guépard qui protégeait le lit du pharaon des serpents. La sainteté attribuée à la vitesse : la vitesse peut agir avant la mort.', ja: 'マフデト：エジプト神話において、ファラオの寝床を蛇から守ったチーターの女神。速さに帰せられる神聖さ——速さは死に先んじて動きうる。' },
      { tr: 'Çita Anneleri: Afrika halk hikâyelerinde çita anne yavruları için aslandan kaçarak ölümü göze alır. Hız, sevginin hizmetinde olduğunda kutsaldır.', en: 'Cheetah Mothers: In African folk tales, the cheetah mother risks death fleeing from the lion for her cubs. Speed is sacred when it serves love.', de: 'Gepardenmütter: In afrikanischen Volksmärchen riskiert die Gepardenmutter den Tod, indem sie für ihre Jungen vor dem Löwen flieht. Geschwindigkeit ist heilig, wenn sie der Liebe dient.', es: 'Madres guepardo: En los cuentos populares africanos, la madre guepardo arriesga la muerte huyendo del león por sus crías. La velocidad es sagrada cuando sirve al amor.', pt: 'Mães-chita: Nos contos populares africanos, a mãe-chita arrisca a morte fugindo do leão pelas crias. A velocidade é sagrada quando serve o amor.', fr: 'Mères guépards : Dans les contes populaires africains, la mère guépard risque la mort en fuyant le lion pour ses petits. La vitesse est sacrée quand elle sert l\'amour.', ja: 'チーターの母：アフリカの民話において、チーターの母は子のためにライオンから逃げ、死を賭す。速さは、愛に仕えるとき神聖となる。' },
    ],
  },

  // ─── a027 Ejderha ───────────────────────────────────────────────────────
  a027: {
    jung: { tr: '"Kozmik Bilinç" arketipi. Ejderha — yıkıcı ve yaratıcı en büyük güç. İçsel hazinenin bekçisi.', en: 'The "Cosmic Consciousness" archetype. The dragon — the greatest power, destructive and creative. Guardian of the inner treasure.', de: 'Der Archetyp des "kosmischen Bewusstseins". Der Drache — die größte Macht, zerstörerisch und schöpferisch. Hüter des inneren Schatzes.', es: 'El arquetipo de la "Conciencia Cósmica". El dragón — el mayor poder, destructor y creador. Guardián del tesoro interior.', pt: 'O arquétipo da "Consciência Cósmica". O dragão — o maior poder, destruidor e criador. Guardião do tesouro interior.', fr: 'L\'archétype de la "Conscience cosmique". Le dragon — la plus grande puissance, destructrice et créatrice. Gardien du trésor intérieur.', ja: '「宇宙意識」の元型。竜——破壊にして創造の、最も大いなる力。内なる宝の番人。' },
    dream: { tr: 'Ejderha rüyada — büyük bir güçle yüzleşiyorsun. Saldırıyorsa: ego seni sınıyor. Üstüne biniyorsan: derin bir gücü taşımayı öğrendin.', en: 'Dragon in dream — you are confronting a great power. Attacking: the ego is testing you. Riding it: you have learned to carry a deep force.', de: 'Drache im Traum — du stellst dich einer großen Macht. Greift er an: Das Ego prüft dich. Reitest du ihn: Du hast gelernt, eine tiefe Kraft zu tragen.', es: 'Dragón en sueños — te enfrentas a un gran poder. Si ataca: el ego te pone a prueba. Si lo montas: has aprendido a portar una fuerza profunda.', pt: 'Dragão em sonho — confrontas um grande poder. Se ataca: o ego põe-te à prova. Se o montas: aprendeste a carregar uma força profunda.', fr: 'Dragon en rêve — tu affrontes une grande puissance. S\'il attaque : l\'ego te met à l\'épreuve. Le chevauchant : tu as appris à porter une force profonde.', ja: '夢の中の竜——あなたは大いなる力と向き合っている。襲うなら、自我があなたを試している。乗りこなすなら、あなたは深い力を担うことを学んだ。' },
    shadow: { tr: 'Hazineyi koruma takıntısı. Ejderha sahip olduklarının üstüne yatar — paylaşmak yerine biriktirir. Egoizmin kozmik formu.', en: 'The compulsion to guard the hoard. The dragon lies upon what it owns — hoarding rather than sharing. The cosmic form of egoism.', de: 'Der Zwang, den Hort zu hüten. Der Drache liegt auf dem, was er besitzt — hortet, statt zu teilen. Die kosmische Gestalt des Egoismus.', es: 'La compulsión de custodiar el tesoro. El dragón yace sobre lo que posee — acumula en vez de compartir. La forma cósmica del egoísmo.', pt: 'A compulsão de guardar o tesouro. O dragão deita-se sobre o que possui — acumula em vez de partilhar. A forma cósmica do egoísmo.', fr: 'La compulsion de garder le trésor. Le dragon se couche sur ce qu\'il possède — il thésaurise au lieu de partager. La forme cosmique de l\'égoïsme.', ja: '宝を守ろうとする強迫。竜は所有するものの上に横たわる——分かち合うより蓄える。利己主義の宇宙的な姿。' },
    whenAppears: { tr: 'Devasa bir dönüşümün eşiğinde, kendi gücünle yüzleşmen gereken anda, içsel hazineye inişte.', en: 'On the threshold of a vast transformation, at the moment you must face your own power, in the descent to the inner treasure.', de: 'An der Schwelle einer gewaltigen Verwandlung, in dem Moment, in dem du dich deiner eigenen Macht stellen musst, beim Abstieg zum inneren Schatz.', es: 'En el umbral de una transformación inmensa, en el momento en que debes enfrentar tu propio poder, en el descenso al tesoro interior.', pt: 'No limiar de uma transformação imensa, no momento em que deves enfrentar o teu próprio poder, na descida ao tesouro interior.', fr: 'Au seuil d\'une transformation immense, au moment où tu dois affronter ton propre pouvoir, dans la descente vers le trésor intérieur.', ja: '途方もない変容の境に、自らの力と向き合わねばならぬ瞬間、内なる宝への下降に。' },
    traditions: [
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Long — imparatorun simgesi, su, yağmur, bereket. Dört yön ejderhası dünyayı kuşatır.', en: 'Long — emblem of the emperor, water, rain, abundance. The four-direction dragons encircle the world.', de: 'Long — Wappen des Kaisers, Wasser, Regen, Überfluss. Die Drachen der vier Himmelsrichtungen umringen die Welt.', es: 'Long — emblema del emperador, agua, lluvia, abundancia. Los dragones de las cuatro direcciones rodean el mundo.', pt: 'Long — emblema do imperador, água, chuva, abundância. Os dragões das quatro direções cercam o mundo.', fr: 'Long — emblème de l\'empereur, eau, pluie, abondance. Les dragons des quatre directions encerclent le monde.', ja: '龍（ロン）——皇帝の象徴、水、雨、豊穣。四方の竜が世界を取り囲む。' } },
      { culture: { tr: 'Türk Mitolojisi', en: 'Turkic Mythology', de: 'Türkische Mythologie', es: 'Mitología Túrquica', pt: 'Mitologia Túrquica', fr: 'Mythologie Turque', ja: 'テュルク神話' }, meaning: { tr: 'Evren — Türk-Moğol mitolojisinde gökyüzü ejderhası. Bayraklarda, kalkanlarda. Ölümsüzlüğün taşıyıcısı.', en: 'Evren — the sky dragon of Turco-Mongol mythology. On banners and shields. Bearer of immortality.', de: 'Evren — der Himmelsdrache der türkisch-mongolischen Mythologie. Auf Bannern und Schilden. Träger der Unsterblichkeit.', es: 'Evren — el dragón celeste de la mitología turco-mongola. En estandartes y escudos. Portador de la inmortalidad.', pt: 'Evren — o dragão celeste da mitologia turco-mongol. Em estandartes e escudos. Portador da imortalidade.', fr: 'Evren — le dragon céleste de la mythologie turco-mongole. Sur les bannières et les boucliers. Porteur de l\'immortalité.', ja: 'エヴレン——テュルク・モンゴル神話の天空の竜。軍旗や盾の上に。不死の担い手。' } },
      { culture: { tr: 'Avrupa Hristiyan', en: 'European Christian', de: 'Europäisch-Christlich', es: 'Cristiano Europeo', pt: 'Cristão Europeu', fr: 'Chrétien Européen', ja: 'ヨーロッパ・キリスト教' }, meaning: { tr: 'Aziz Yorgi\'nin (St. George) öldürdüğü canavar — bastırılması gereken pagan gücü.', en: 'The beast slain by Saint George — the pagan power that must be subdued.', de: 'Das von Sankt Georg erschlagene Ungeheuer — die heidnische Macht, die bezwungen werden muss.', es: 'La bestia que mata San Jorge — el poder pagano que debe ser sometido.', pt: 'A besta morta por São Jorge — o poder pagão que deve ser subjugado.', fr: 'La bête tuée par saint Georges — la puissance païenne qui doit être domptée.', ja: '聖ゲオルギウスが討った怪物——屈服させねばならぬ異教の力。' } },
      { culture: { tr: 'İskandinav', en: 'Norse', de: 'Nordisch', es: 'Nórdico', pt: 'Nórdico', fr: 'Nordique', ja: '北欧' }, meaning: { tr: 'Jörmungandr — dünyayı saran kuyruğunu yiyen ejderha. Sonun başlangıcı.', en: 'Jörmungandr — the dragon encircling the world, devouring its own tail. The beginning of the end.', de: 'Jörmungandr — der Drache, der die Welt umschlingt und seinen eigenen Schwanz verschlingt. Der Anfang vom Ende.', es: 'Jörmungandr — el dragón que rodea el mundo, devorando su propia cola. El comienzo del fin.', pt: 'Jörmungandr — o dragão que rodeia o mundo, devorando a própria cauda. O começo do fim.', fr: 'Jörmungand — le dragon qui encercle le monde, dévorant sa propre queue. Le commencement de la fin.', ja: 'ヨルムンガンド——世界を取り巻き、自らの尾を喰らう竜。終わりの始まり。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Vritra — kuraklığın ejderhası. İndra tarafından öldürülünce sular akar — yaratıcı yıkım.', en: 'Vritra — the dragon of drought. When slain by Indra, the waters flow — creative destruction.', de: 'Vritra — der Drache der Dürre. Von Indra erschlagen, fließen die Wasser — schöpferische Zerstörung.', es: 'Vritra — el dragón de la sequía. Al ser muerto por Indra, las aguas fluyen — destrucción creadora.', pt: 'Vritra — o dragão da seca. Ao ser morto por Indra, as águas fluem — destruição criadora.', fr: 'Vritra — le dragon de la sécheresse. Tué par Indra, les eaux coulent — destruction créatrice.', ja: 'ヴリトラ——干ばつの竜。インドラに討たれると水が流れ出す——創造的な破壊。' } },
    ],
    myths: [
      { tr: 'Çin Ejderhası ve Yağmur: Çin mitolojisinde ejderhalar nehir ve göllerde yaşar. Yağmur getirir, bereket yağdırır. Kuraklık — ejderhanın kızgınlığıdır, sevgisini geri kazanmak gerek.', en: 'The Chinese Dragon and Rain: In Chinese mythology, dragons dwell in rivers and lakes. They bring rain and pour abundance. Drought is the dragon\'s anger — one must win back its love.', de: 'Der chinesische Drache und der Regen: In der chinesischen Mythologie wohnen Drachen in Flüssen und Seen. Sie bringen Regen und gießen Überfluss aus. Dürre ist der Zorn des Drachen — man muss seine Liebe zurückgewinnen.', es: 'El dragón chino y la lluvia: En la mitología china, los dragones habitan ríos y lagos. Traen la lluvia y vierten la abundancia. La sequía es la ira del dragón — hay que reconquistar su amor.', pt: 'O dragão chinês e a chuva: Na mitologia chinesa, os dragões habitam rios e lagos. Trazem a chuva e derramam abundância. A seca é a ira do dragão — é preciso reconquistar o seu amor.', fr: 'Le dragon chinois et la pluie : Dans la mythologie chinoise, les dragons habitent les fleuves et les lacs. Ils apportent la pluie et déversent l\'abondance. La sécheresse est la colère du dragon — il faut reconquérir son amour.', ja: '中国の竜と雨：中国神話において、竜は川や湖に棲む。雨をもたらし、豊穣を降らせる。干ばつは竜の怒り——その愛を取り戻さねばならない。' },
      { tr: 'St. George ve Ejderha: Hristiyan ikonografisinde Aziz Yorgi, prensesi kurtarmak için ejderhayı öldürür. Doğu\'nun kutsadığı, Batı\'nın bastırdığı — perspektif tartışması.', en: 'St. George and the Dragon: In Christian iconography, Saint George slays the dragon to save the princess. What the East sanctifies, the West subdues — a question of perspective.', de: 'Sankt Georg und der Drache: In der christlichen Ikonografie erschlägt Sankt Georg den Drachen, um die Prinzessin zu retten. Was der Osten heiligt, bezwingt der Westen — eine Frage der Perspektive.', es: 'San Jorge y el dragón: En la iconografía cristiana, San Jorge mata al dragón para salvar a la princesa. Lo que el Oriente santifica, el Occidente lo somete — una cuestión de perspectiva.', pt: 'São Jorge e o dragão: Na iconografia cristã, São Jorge mata o dragão para salvar a princesa. O que o Oriente santifica, o Ocidente subjuga — uma questão de perspetiva.', fr: 'Saint Georges et le dragon : Dans l\'iconographie chrétienne, saint Georges tue le dragon pour sauver la princesse. Ce que l\'Orient sanctifie, l\'Occident le dompte — une question de perspective.', ja: '聖ゲオルギウスと竜：キリスト教の図像において、聖ゲオルギウスは姫を救うため竜を討つ。東洋が聖別するものを西洋は屈服させる——視座の論争。' },
    ],
  },

  // ─── a028 Karakulak ─────────────────────────────────────────────────────
  a028: {
    jung: { tr: '"Sessiz Sezgi" arketipi. Karakulak — kulağıyla görür, görünmeyeni duyur. Görünmeden gözlemleyen yargıç.', en: 'The "Silent Intuition" archetype. The caracal — sees with its ears, hears the unseen. The judge who observes without being seen.', de: 'Der Archetyp der "stillen Intuition". Der Karakal — sieht mit den Ohren, hört das Ungesehene. Der Richter, der beobachtet, ohne gesehen zu werden.', es: 'El arquetipo de la "Intuición Silenciosa". El caracal — ve con sus orejas, oye lo invisible. El juez que observa sin ser visto.', pt: 'O arquétipo da "Intuição Silenciosa". O caracal — vê com as orelhas, ouve o invisível. O juiz que observa sem ser visto.', fr: 'L\'archétype de l\'"Intuition silencieuse". Le caracal — voit avec ses oreilles, entend l\'invisible. Le juge qui observe sans être vu.', ja: '「静かなる直感」の元型。カラカル——耳で見て、見えぬものを聞く。見られずに観察する裁き手。' },
    dream: { tr: 'Karakulak rüyada — duyamadığın bir şeye dikkat çekiyor. Gizli bir mesaj, fısıltı, sezgi. Birinin söylemediği var.', en: 'Caracal in dream — draws attention to what you cannot hear. A hidden message, whisper, intuition. Someone has something they are not saying.', de: 'Karakal im Traum — lenkt die Aufmerksamkeit auf das, was du nicht hören kannst. Eine verborgene Botschaft, ein Flüstern, eine Ahnung. Jemand verschweigt etwas.', es: 'Caracal en sueños — llama la atención sobre lo que no puedes oír. Un mensaje oculto, un susurro, una intuición. Alguien calla algo.', pt: 'Caracal em sonho — chama a atenção para o que não consegues ouvir. Uma mensagem oculta, um sussurro, uma intuição. Alguém cala algo.', fr: 'Caracal en rêve — attire l\'attention sur ce que tu ne peux entendre. Un message caché, un murmure, une intuition. Quelqu\'un tait quelque chose.', ja: '夢の中のカラカル——あなたに聞こえないものへ注意を向ける。隠された報せ、ささやき、直感。誰かが言わずにいることがある。' },
    shadow: { tr: 'Sürekli kuşku. Her şeyin altında bir komplo aramak. Karakulak duyar ama yorumda yanılırsa paranoya doğar.', en: 'Constant suspicion. Searching for a conspiracy beneath everything. The caracal hears, but errors in interpretation give birth to paranoia.', de: 'Ständiger Argwohn. Unter allem eine Verschwörung zu suchen. Der Karakal hört, doch Irrtümer in der Deutung gebären Paranoia.', es: 'Sospecha constante. Buscar una conspiración bajo todo. El caracal oye, pero los errores de interpretación dan a luz la paranoia.', pt: 'Suspeita constante. Procurar uma conspiração sob tudo. O caracal ouve, mas os erros de interpretação dão à luz a paranoia.', fr: 'Soupçon constant. Chercher un complot sous toute chose. Le caracal entend, mais les erreurs d\'interprétation enfantent la paranoïa.', ja: '絶え間ない疑念。あらゆるものの裏に陰謀を探すこと。カラカルは聞くが、解釈を誤れば妄想が生まれる。' },
    whenAppears: { tr: 'Kelimelerin gerçeği örttüğü konuşmalarda, bir hissin doğrulanmasını beklerken, gizli niyetleri okuman gerekirken.', en: 'In conversations where words conceal the truth, while awaiting confirmation of a feeling, when you must read hidden intentions.', de: 'In Gesprächen, in denen Worte die Wahrheit verhüllen, während du auf die Bestätigung eines Gefühls wartest, wenn du verborgene Absichten lesen musst.', es: 'En conversaciones donde las palabras ocultan la verdad, mientras aguardas la confirmación de un presentimiento, cuando debes leer intenciones ocultas.', pt: 'Em conversas onde as palavras ocultam a verdade, enquanto aguardas a confirmação de um pressentimento, quando deves ler intenções ocultas.', fr: 'Dans les conversations où les mots voilent la vérité, en attendant la confirmation d\'un sentiment, quand tu dois lire des intentions cachées.', ja: '言葉が真実を覆い隠す会話のうちに、ある予感の裏づけを待つとき、隠された意図を読まねばならぬときに。' },
    traditions: [
      { culture: { tr: 'Anadolu Vahşi Yaşam', en: 'Anatolian Wildlife', de: 'Anatolische Tierwelt', es: 'Fauna Anatolia', pt: 'Vida Selvagem Anatólia', fr: 'Faune Anatolienne', ja: 'アナトリアの野生' }, meaning: { tr: 'Anadolu\'nun saklı avcısı. Toroslar\'da, çöllerinde gizlice yaşar. Sessiz biliciliğin sembolü.', en: 'Anatolia\'s hidden hunter. Lives secretly in the Taurus mountains and the deserts. Symbol of silent knowing.', de: 'Anatoliens verborgener Jäger. Lebt heimlich im Taurusgebirge und in den Wüsten. Symbol des stillen Wissens.', es: 'El cazador oculto de Anatolia. Vive en secreto en los montes Tauro y los desiertos. Símbolo del saber silencioso.', pt: 'O caçador oculto da Anatólia. Vive secretamente nos montes Tauro e nos desertos. Símbolo do saber silencioso.', fr: 'Le chasseur caché de l\'Anatolie. Il vit secrètement dans les monts Taurus et les déserts. Symbole du savoir silencieux.', ja: 'アナトリアの隠れた狩人。トロス山脈や砂漠に密かに棲む。静かなる知の象徴。' } },
      { culture: { tr: 'Pers/Arap', en: 'Persian/Arabic', de: 'Persisch/Arabisch', es: 'Persa/Árabe', pt: 'Persa/Árabe', fr: 'Perse/Arabe', ja: 'ペルシア／アラブ' }, meaning: { tr: 'Çöl çakallarının kuzeni. Bedevi geleneğinde "uzak haberi getiren" kabul edilir.', en: 'Cousin to the desert jackals. In Bedouin tradition, regarded as "the one who brings news from afar".', de: 'Vetter der Wüstenschakale. In der Beduinentradition gilt er als "der, der Nachricht aus der Ferne bringt".', es: 'Primo de los chacales del desierto. En la tradición beduina, considerado "el que trae noticias de lejos".', pt: 'Primo dos chacais do deserto. Na tradição beduína, tido como "aquele que traz notícias de longe".', fr: 'Cousin des chacals du désert. Dans la tradition bédouine, tenu pour "celui qui apporte des nouvelles de loin".', ja: '砂漠のジャッカルの縁者。ベドウィンの伝統では「遠くからの報せを運ぶ者」とされる。' } },
      { culture: { tr: 'Hint', en: 'Hindu', de: 'Hinduistisch', es: 'Hindú', pt: 'Hindu', fr: 'Hindou', ja: 'ヒンドゥー' }, meaning: { tr: 'Şiva\'nın gözünden saklananları gören — gizli adaletin habercisi.', en: 'The one who sees what is hidden from Shiva\'s eye — herald of hidden justice.', de: 'Der, der sieht, was vor Shivas Auge verborgen ist — Herold der verborgenen Gerechtigkeit.', es: 'El que ve lo oculto al ojo de Shiva — heraldo de la justicia oculta.', pt: 'Aquele que vê o que está oculto ao olho de Shiva — arauto da justiça oculta.', fr: 'Celui qui voit ce qui est caché à l\'œil de Shiva — héraut de la justice cachée.', ja: 'シヴァの目から隠されたものを見る者——隠れた正義の使者。' } },
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Anubis\'in çakal akrabası. Yer altı dünyasının habercisi.', en: 'Jackal-kin to Anubis. Messenger of the underworld.', de: 'Schakalverwandter des Anubis. Bote der Unterwelt.', es: 'Pariente chacal de Anubis. Mensajero del inframundo.', pt: 'Parente-chacal de Anúbis. Mensageiro do submundo.', fr: 'Parent-chacal d\'Anubis. Messager des enfers.', ja: 'アヌビスのジャッカルの縁者。冥界の使者。' } },
      { culture: { tr: 'Bedevi', en: 'Bedouin', de: 'Beduinisch', es: 'Beduino', pt: 'Beduíno', fr: 'Bédouin', ja: 'ベドウィン' }, meaning: { tr: 'Avcılık geleneğinde "sultanın kulağı". Padişaha en yakın av hayvanı.', en: 'In the hunting tradition, "the sultan\'s ear". The hunting animal closest to the ruler.', de: 'In der Jagdtradition "das Ohr des Sultans". Das dem Herrscher am nächsten stehende Jagdtier.', es: 'En la tradición de caza, "el oído del sultán". El animal de caza más cercano al gobernante.', pt: 'Na tradição de caça, "o ouvido do sultão". O animal de caça mais próximo do soberano.', fr: 'Dans la tradition de la chasse, "l\'oreille du sultan". L\'animal de chasse le plus proche du souverain.', ja: '狩りの伝統における「スルタンの耳」。君主に最も近い狩りの動物。' } },
    ],
    myths: [
      { tr: 'Karakulak ve Tilki: Anadolu masallarında karakulak tilkiden daha sessiz, daha sezgisel hayvan olarak resmedilir. Tilki konuşurken kandırır, karakulak susarak kandırılır mı diye bakar.', en: 'The Caracal and the Fox: In Anatolian tales, the caracal is depicted as quieter, more intuitive than the fox. The fox deceives by speaking; the caracal, by being silent, watches to see if it is being deceived.', de: 'Der Karakal und der Fuchs: In anatolischen Märchen wird der Karakal als stiller, intuitiver als der Fuchs dargestellt. Der Fuchs täuscht durch Reden; der Karakal beobachtet schweigend, ob er getäuscht wird.', es: 'El caracal y el zorro: En los cuentos anatolios, el caracal se presenta más callado, más intuitivo que el zorro. El zorro engaña hablando; el caracal, callando, observa si lo engañan.', pt: 'O caracal e a raposa: Nos contos anatólios, o caracal é retratado como mais calado, mais intuitivo do que a raposa. A raposa engana ao falar; o caracal, calando-se, observa se está a ser enganado.', fr: 'Le caracal et le renard : Dans les contes anatoliens, le caracal est dépeint plus silencieux, plus intuitif que le renard. Le renard trompe en parlant ; le caracal, en se taisant, observe s\'il est trompé.', ja: 'カラカルとキツネ：アナトリアの物語において、カラカルはキツネより静かで、より直感的な動物として描かれる。キツネは語って欺き、カラカルは黙して、欺かれていないか見極める。' },
      { tr: 'Sultan\'ın Karakulağı: Osmanlı sarayında padişaha "duyduklarını gizlice anlatan" yakın adamlara "karakulak" denirdi. Hayvanın saklı kulağı — politikanın metaforu.', en: 'The Sultan\'s Caracal: In the Ottoman court, close attendants who "secretly conveyed what they heard" to the sultan were called "karakulak". The animal\'s hidden ear — a metaphor for politics.', de: 'Der Karakal des Sultans: Am osmanischen Hof wurden vertraute Diener, die dem Sultan "heimlich übermittelten, was sie hörten", "karakulak" genannt. Das verborgene Ohr des Tieres — eine Metapher der Politik.', es: 'El caracal del sultán: En la corte otomana, a los allegados que "transmitían en secreto al sultán lo que oían" se les llamaba "karakulak". El oído oculto del animal — una metáfora de la política.', pt: 'O caracal do sultão: Na corte otomana, os próximos que "transmitiam em segredo ao sultão o que ouviam" eram chamados "karakulak". O ouvido oculto do animal — uma metáfora da política.', fr: 'Le caracal du sultan : À la cour ottomane, les proches qui "transmettaient en secret au sultan ce qu\'ils entendaient" étaient appelés "karakulak". L\'oreille cachée de l\'animal — une métaphore de la politique.', ja: 'スルタンのカラカル：オスマン宮廷では、スルタンに「聞いたことを密かに伝える」側近を「カラクラク」と呼んだ。動物の隠れた耳——政治の比喩。' },
    ],
  },

  // ─── a029 Maral ─────────────────────────────────────────────────────────
  a029: {
    jung: { tr: '"Sevda Çağrısı" arketipi. Maral — kederin ve şefkatin birleşimi. Yaralı kalbin sesi.', en: 'The "Call of Longing" archetype. The doe — union of sorrow and tenderness. The voice of the wounded heart.', de: 'Der Archetyp des "Rufs der Sehnsucht". Die Hirschkuh — Vereinigung von Kummer und Zärtlichkeit. Die Stimme des verwundeten Herzens.', es: 'El arquetipo del "Llamado del Anhelo". La cierva — unión de la pena y la ternura. La voz del corazón herido.', pt: 'O arquétipo do "Chamado do Anseio". A corça — união da mágoa e da ternura. A voz do coração ferido.', fr: 'L\'archétype de l\'"Appel du désir". La biche — union du chagrin et de la tendresse. La voix du cœur blessé.', ja: '「恋慕の呼び声」の元型。雌鹿——悲しみと優しさの結合。傷ついた心の声。' },
    dream: { tr: 'Maral rüyada — bir özlemin, bir sevdanın çağrısı. Kaçıyorsa: sevdiğine yetişemiyorsun. Sana yaklaşıyorsa: kalp açılıyor.', en: 'Doe in dream — the call of a longing, a love. Fleeing: you cannot catch up to your beloved. Approaching you: the heart is opening.', de: 'Hirschkuh im Traum — der Ruf einer Sehnsucht, einer Liebe. Flieht sie: Du kannst deine Geliebte nicht einholen. Nähert sie sich dir: Das Herz öffnet sich.', es: 'Cierva en sueños — el llamado de un anhelo, de un amor. Si huye: no logras alcanzar a tu amado. Si se acerca: el corazón se abre.', pt: 'Corça em sonho — o chamado de um anseio, de um amor. Se foge: não consegues alcançar o teu amado. Se se aproxima: o coração abre-se.', fr: 'Biche en rêve — l\'appel d\'un désir, d\'un amour. Fuyant : tu ne peux rejoindre ton bien-aimé. S\'approchant : le cœur s\'ouvre.', ja: '夢の中の雌鹿——ある憧れ、ある恋の呼び声。逃げるなら、愛する者に追いつけずにいる。近づくなら、心が開かれていく。' },
    shadow: { tr: '"Yaralı ceylan" rolü. Korunmaya muhtaç pozisyonu hayat tarzı yapmak — şefkat dilenmek.', en: 'The "wounded gazelle" role. Making the posture of needing protection a way of life — begging for tenderness.', de: 'Die Rolle der "verwundeten Gazelle". Die Haltung der Schutzbedürftigkeit zur Lebensweise zu machen — um Zärtlichkeit zu betteln.', es: 'El papel de la "gacela herida". Hacer de la postura de necesitar protección una forma de vida — mendigar ternura.', pt: 'O papel da "gazela ferida". Fazer da postura de precisar de proteção um modo de vida — mendigar ternura.', fr: 'Le rôle de la "gazelle blessée". Faire de la posture du besoin de protection un mode de vie — mendier la tendresse.', ja: '「傷ついたガゼル」の役回り。保護を必要とする姿勢を生き方にすること——優しさを乞うこと。' },
    whenAppears: { tr: 'Bir sevgilinin uzaklığında, ana-yavru bağında, hayatın yumuşaklığa çağırdığı anda.', en: 'In a beloved\'s distance, in the mother-child bond, at the moment life calls you to gentleness.', de: 'In der Ferne einer Geliebten, in der Bindung zwischen Mutter und Kind, in dem Moment, in dem das Leben dich zur Sanftheit ruft.', es: 'En la distancia de un amado, en el vínculo madre-hijo, en el momento en que la vida te llama a la dulzura.', pt: 'Na distância de um amado, no vínculo mãe-filho, no momento em que a vida te chama à doçura.', fr: 'Dans l\'éloignement d\'un bien-aimé, dans le lien mère-enfant, à l\'instant où la vie t\'appelle à la douceur.', ja: '愛する者の遠さのうちに、母と子の絆のうちに、人生が優しさへと呼びかける瞬間に。' },
    traditions: [
      { culture: { tr: 'Türk Halk Şiiri', en: 'Turkish Folk Poetry', de: 'Türkische Volksdichtung', es: 'Poesía Popular Turca', pt: 'Poesia Popular Turca', fr: 'Poésie Populaire Turque', ja: 'トルコ民謡詩' }, meaning: { tr: '"Karac\'oğlan\'ın Maralı" — Anadolu aşk şiirinin merkez sembolü. Sevgilinin gözleri, boynunun zarafeti.', en: '"Karacaoğlan\'s Doe" — the central symbol of Anatolian love poetry. The beloved\'s eyes, the grace of her neck.', de: '"Karacaoğlans Hirschkuh" — das zentrale Symbol der anatolischen Liebesdichtung. Die Augen der Geliebten, die Anmut ihres Halses.', es: '"La cierva de Karacaoğlan" — el símbolo central de la poesía amorosa anatolia. Los ojos de la amada, la gracia de su cuello.', pt: '"A corça de Karacaoğlan" — o símbolo central da poesia amorosa anatólia. Os olhos da amada, a graça do seu pescoço.', fr: '"La biche de Karacaoğlan" — le symbole central de la poésie d\'amour anatolienne. Les yeux de l\'aimée, la grâce de son cou.', ja: '「カラジャオウランの雌鹿」——アナトリア恋愛詩の中心的象徴。愛する者の瞳、その首のしなやかさ。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Aktaion mitinde — avcı Artemis\'i çıplak görür, ceza olarak geyiğe (maral) dönüştürülür ve kendi köpeklerince parçalanır.', en: 'In the Actaeon myth — the hunter sees Artemis naked; in punishment he is turned into a stag and torn apart by his own hounds.', de: 'Im Aktaion-Mythos — der Jäger sieht Artemis nackt; zur Strafe wird er in einen Hirsch verwandelt und von seinen eigenen Hunden zerrissen.', es: 'En el mito de Acteón — el cazador ve a Artemisa desnuda; como castigo es transformado en ciervo y despedazado por sus propios perros.', pt: 'No mito de Acteão — o caçador vê Ártemis nua; como castigo é transformado em veado e despedaçado pelos seus próprios cães.', fr: 'Dans le mythe d\'Actéon — le chasseur voit Artémis nue ; en punition, il est transformé en cerf et déchiré par ses propres chiens.', ja: 'アクタイオンの神話において——狩人はアルテミスの裸を見、罰として牡鹿に変えられ、自らの猟犬に引き裂かれる。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Beyaz maral — ruhlar âleminden gelen mesajcı. Kralı seçen kutsal.', en: 'The white doe — messenger from the spirit realm. The sacred one who chooses the king.', de: 'Die weiße Hirschkuh — Botin aus dem Geisterreich. Die Heilige, die den König erwählt.', es: 'La cierva blanca — mensajera del reino de los espíritus. La sagrada que elige al rey.', pt: 'A corça branca — mensageira do reino dos espíritos. A sagrada que escolhe o rei.', fr: 'La biche blanche — messagère du royaume des esprits. La sacrée qui choisit le roi.', ja: '白い雌鹿——霊界からの使者。王を選ぶ聖なるもの。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Sarama — tanrıların habercisi. Saf ruhun yer üstündeki formu.', en: 'Sarama — messenger of the gods. The earthly form of the pure soul.', de: 'Sarama — Botin der Götter. Die irdische Gestalt der reinen Seele.', es: 'Sarama — mensajera de los dioses. La forma terrenal del alma pura.', pt: 'Sarama — mensageira dos deuses. A forma terrena da alma pura.', fr: 'Saramâ — messagère des dieux. La forme terrestre de l\'âme pure.', ja: 'サラマー——神々の使者。清らかな魂の地上の姿。' } },
      { culture: { tr: 'Şamanik', en: 'Shamanic', de: 'Schamanisch', es: 'Chamánico', pt: 'Xamânico', fr: 'Chamanique', ja: 'シャーマニズム' }, meaning: { tr: 'Sibirya geleneğinde — bedensiz aşk ruhunun temsilcisi.', en: 'In Siberian tradition — representative of the bodiless spirit of love.', de: 'In der sibirischen Tradition — Vertreterin des körperlosen Geistes der Liebe.', es: 'En la tradición siberiana — representante del espíritu incorpóreo del amor.', pt: 'Na tradição siberiana — representante do espírito incorpóreo do amor.', fr: 'Dans la tradition sibérienne — représentante de l\'esprit sans corps de l\'amour.', ja: 'シベリアの伝統において——肉体なき愛の霊の表れ。' } },
    ],
    myths: [
      { tr: 'Karac\'oğlan ve Maralı: Anadolu\'nun en lirik halk şiirinde, Karac\'oğlan sevdiğini "marala" benzetir. Maral kaçar, şair kovalar — sevda, yetişilemeyen güzelliktir.', en: 'Karacaoğlan and His Doe: In Anatolia\'s most lyric folk poetry, Karacaoğlan likens his beloved to a doe. The doe flees, the poet pursues — love is the unattainable beauty.', de: 'Karacaoğlan und seine Hirschkuh: In Anatoliens lyrischster Volksdichtung vergleicht Karacaoğlan seine Geliebte mit einer Hirschkuh. Die Hirschkuh flieht, der Dichter verfolgt — die Liebe ist die unerreichbare Schönheit.', es: 'Karacaoğlan y su cierva: En la más lírica poesía popular de Anatolia, Karacaoğlan compara a su amada con una cierva. La cierva huye, el poeta persigue — el amor es la belleza inalcanzable.', pt: 'Karacaoğlan e a sua corça: Na mais lírica poesia popular da Anatólia, Karacaoğlan compara a amada a uma corça. A corça foge, o poeta persegue — o amor é a beleza inalcançável.', fr: 'Karacaoğlan et sa biche : Dans la plus lyrique poésie populaire de l\'Anatolie, Karacaoğlan compare son aimée à une biche. La biche fuit, le poète poursuit — l\'amour est la beauté inaccessible.', ja: 'カラジャオウランと雌鹿：アナトリア最も叙情的な民謡詩において、カラジャオウランは愛する者を「雌鹿」になぞらえる。雌鹿は逃げ、詩人は追う——恋とは、追いつけぬ美。' },
      { tr: 'Aktaion\'un Cezası: Yunan mitolojisinde avcı Aktaion, su perisi formundaki Artemis\'i görür. Tanrıça onu cezalandırmak için marala dönüştürür — kendi köpekleri tarafından parçalanır. Görenin görülmesi.', en: 'Actaeon\'s Punishment: In Greek mythology, the hunter Actaeon sees Artemis in her water-nymph form. To punish him, the goddess transforms him into a stag — he is torn apart by his own hounds. The seer is seen.', de: 'Aktaions Strafe: In der griechischen Mythologie sieht der Jäger Aktaion Artemis in ihrer Wassernymphengestalt. Zur Strafe verwandelt die Göttin ihn in einen Hirsch — er wird von seinen eigenen Hunden zerrissen. Der Sehende wird gesehen.', es: 'El castigo de Acteón: En la mitología griega, el cazador Acteón ve a Artemisa en su forma de ninfa del agua. Para castigarlo, la diosa lo transforma en ciervo — es despedazado por sus propios perros. El que ve es visto.', pt: 'O castigo de Acteão: Na mitologia grega, o caçador Acteão vê Ártemis na sua forma de ninfa das águas. Para o castigar, a deusa transforma-o em veado — é despedaçado pelos seus próprios cães. Aquele que vê é visto.', fr: 'Le châtiment d\'Actéon : Dans la mythologie grecque, le chasseur Actéon voit Artémis sous sa forme de nymphe des eaux. Pour le punir, la déesse le transforme en cerf — il est déchiré par ses propres chiens. Le voyant est vu.', ja: 'アクタイオンの罰：ギリシア神話において、狩人アクタイオンは水のニンフの姿のアルテミスを見る。罰として女神は彼を牡鹿に変える——彼は自らの猟犬に引き裂かれる。見る者が見られる。' },
    ],
  },

  // ─── a030 Timsah ────────────────────────────────────────────────────────
  a030: {
    jung: { tr: '"İlkel Bilinçaltı" arketipi. Timsah — sürüngen beynin dipteki sesi. Korkunun bedenleşmiş hâli, ama aynı zamanda hayatta kalmanın koruyucusu.', en: 'The "Primal Unconscious" archetype. The crocodile — the deep voice of the reptilian brain. The embodied form of fear, yet also the guardian of survival.', de: 'Der Archetyp des "Ur-Unbewussten". Das Krokodil — die tiefe Stimme des Reptiliengehirns. Die verkörperte Gestalt der Angst, doch zugleich der Hüter des Überlebens.', es: 'El arquetipo del "Inconsciente Primigenio". El cocodrilo — la voz profunda del cerebro reptiliano. La forma encarnada del miedo, pero también el guardián de la supervivencia.', pt: 'O arquétipo do "Inconsciente Primordial". O crocodilo — a voz profunda do cérebro reptiliano. A forma encarnada do medo, mas também o guardião da sobrevivência.', fr: 'L\'archétype de l\'"Inconscient primordial". Le crocodile — la voix profonde du cerveau reptilien. La forme incarnée de la peur, mais aussi le gardien de la survie.', ja: '「原初の無意識」の元型。ワニ——爬虫類脳の底からの声。恐れが肉体をまとった姿、だが同時に生存の守護者。' },
    dream: { tr: 'Timsah rüyada — bilinçaltında bekleyen bir tehlikenin veya gücün var. Suyun altındaysa: gölge taraf hareketsiz bekliyor. Karaya çıkıyorsa: yüzleşmen gereken bir şey ortaya çıktı.', en: 'Crocodile in dream — a danger or a power lies waiting in your unconscious. Underwater: the shadow side waits motionless. Coming ashore: something you must face has surfaced.', de: 'Krokodil im Traum — eine Gefahr oder eine Kraft lauert in deinem Unbewussten. Unter Wasser: Die Schattenseite wartet reglos. An Land kommend: Etwas, dem du dich stellen musst, ist aufgetaucht.', es: 'Cocodrilo en sueños — un peligro o un poder aguarda en tu inconsciente. Bajo el agua: el lado sombra espera inmóvil. Saliendo a tierra: algo que debes enfrentar ha emergido.', pt: 'Crocodilo em sonho — um perigo ou um poder espera no teu inconsciente. Debaixo de água: o lado sombra espera imóvel. Saindo para terra: algo que deves enfrentar emergiu.', fr: 'Crocodile en rêve — un danger ou une puissance attend dans ton inconscient. Sous l\'eau : le côté ombre attend immobile. Sortant sur la rive : quelque chose que tu dois affronter a fait surface.', ja: '夢の中のワニ——あなたの無意識に潜む危険か力がある。水中なら、影の側面が身じろぎもせず待っている。陸に上がるなら、向き合うべき何かが浮かび上がった。' },
    shadow: { tr: 'Soğuk zalimlik. Timsah enerjisi bilinçsizleşirse — duygusuz hayatta kalma, başkalarını yutarak yaşama.', en: 'Cold cruelty. When crocodile energy turns unconscious — emotionless survival, living by devouring others.', de: 'Kalte Grausamkeit. Wird die Krokodilenergie unbewusst — gefühlloses Überleben, ein Leben durch das Verschlingen anderer.', es: 'Crueldad fría. Cuando la energía del cocodrilo se vuelve inconsciente — supervivencia sin emoción, vivir devorando a otros.', pt: 'Crueldade fria. Quando a energia do crocodilo se torna inconsciente — sobrevivência sem emoção, viver devorando outros.', fr: 'Cruauté froide. Quand l\'énergie du crocodile devient inconsciente — survie sans émotion, vivre en dévorant les autres.', ja: '冷たい残酷さ。ワニのエネルギーが無意識のものとなれば——感情なき生存、他者を喰らって生きること。' },
    whenAppears: { tr: 'Derin korkularla yüzleşirken, gölge çalışmasında, bilinçaltına dalman gerektiğinde.', en: 'While confronting deep fears, in shadow work, when you must descend into the unconscious.', de: 'Während du dich tiefen Ängsten stellst, in der Schattenarbeit, wenn du ins Unbewusste hinabsteigen musst.', es: 'Al enfrentar miedos profundos, en el trabajo de sombra, cuando debes descender al inconsciente.', pt: 'Ao enfrentar medos profundos, no trabalho de sombra, quando deves descer ao inconsciente.', fr: 'En affrontant des peurs profondes, dans le travail de l\'ombre, quand tu dois descendre dans l\'inconscient.', ja: '深い恐れと向き合うとき、影の仕事において、無意識へと下りねばならぬときに。' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Sobek — timsah başlı tanrı. Nil\'in gücü, doğurganlık, ama aynı zamanda korkunun tanrısı. Firavunun yıkıcı yönü.', en: 'Sobek — the crocodile-headed god. The Nile\'s force, fertility, yet also the god of fear. The pharaoh\'s destructive aspect.', de: 'Sobek — der krokodilköpfige Gott. Die Kraft des Nils, Fruchtbarkeit, doch auch der Gott der Angst. Der zerstörerische Aspekt des Pharaos.', es: 'Sobek — el dios con cabeza de cocodrilo. La fuerza del Nilo, la fertilidad, pero también el dios del miedo. El aspecto destructor del faraón.', pt: 'Sobek — o deus com cabeça de crocodilo. A força do Nilo, a fertilidade, mas também o deus do medo. O aspeto destruidor do faraó.', fr: 'Sobek — le dieu à tête de crocodile. La force du Nil, la fertilité, mais aussi le dieu de la peur. L\'aspect destructeur du pharaon.', ja: 'セベク——ワニの頭をもつ神。ナイルの力、豊穣、だが同時に恐れの神。ファラオの破壊的な側面。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Makara — Varuna\'nın (su tanrısı) bineği. Suyun bilinçaltı bilgeliği.', en: 'Makara — the mount of Varuna (god of waters). The unconscious wisdom of the waters.', de: 'Makara — das Reittier des Varuna (Gott der Wasser). Die unbewusste Weisheit der Wasser.', es: 'Makara — la montura de Varuna (dios de las aguas). La sabiduría inconsciente de las aguas.', pt: 'Makara — a montaria de Varuna (deus das águas). A sabedoria inconsciente das águas.', fr: 'Makara — la monture de Varuna (dieu des eaux). La sagesse inconsciente des eaux.', ja: 'マカラ——ヴァルナ（水の神）の乗り物。水の無意識の知恵。' } },
      { culture: { tr: 'Maya/Aztek', en: 'Mayan/Aztec', de: 'Maya/Aztekisch', es: 'Maya/Azteca', pt: 'Maia/Asteca', fr: 'Maya/Aztèque', ja: 'マヤ／アステカ' }, meaning: { tr: 'Cipactli — dünyanın üzerinde yaratıldığı dev timsah. Yaratılışın platformu.', en: 'Cipactli — the giant crocodile upon which the world was created. The platform of creation.', de: 'Cipactli — das Riesenkrokodil, auf dem die Welt erschaffen wurde. Die Plattform der Schöpfung.', es: 'Cipactli — el cocodrilo gigante sobre el que se creó el mundo. La plataforma de la creación.', pt: 'Cipactli — o crocodilo gigante sobre o qual o mundo foi criado. A plataforma da criação.', fr: 'Cipactli — le crocodile géant sur lequel le monde fut créé. La plateforme de la création.', ja: 'シパクトリ——その上に世界が創られた巨大なワニ。創造の土台。' } },
      { culture: { tr: 'Afrika', en: 'African', de: 'Afrikanisch', es: 'Africano', pt: 'Africano', fr: 'Africain', ja: 'アフリカ' }, meaning: { tr: 'Yoruba geleneğinde — adaletin ve nehir tanrılarının habercisi.', en: 'In Yoruba tradition — herald of justice and the river gods.', de: 'In der Yoruba-Tradition — Herold der Gerechtigkeit und der Flussgötter.', es: 'En la tradición yoruba — heraldo de la justicia y de los dioses del río.', pt: 'Na tradição iorubá — arauto da justiça e dos deuses do rio.', fr: 'Dans la tradition yoruba — héraut de la justice et des dieux du fleuve.', ja: 'ヨルバの伝統において——正義と川の神々の使者。' } },
      { culture: { tr: 'Avustralya', en: 'Australian', de: 'Australisch', es: 'Australiano', pt: 'Australiano', fr: 'Australien', ja: 'オーストラリア' }, meaning: { tr: 'Aborjin rüya zamanında — toprak ve suyun kararlılığını koruyan ata varlık.', en: 'In Aboriginal Dreamtime — the ancestral being who guards the steadiness of earth and water.', de: 'In der Traumzeit der Aborigines — das Ahnenwesen, das die Beständigkeit von Erde und Wasser bewahrt.', es: 'En el Tiempo del Sueño aborigen — el ser ancestral que guarda la estabilidad de la tierra y el agua.', pt: 'No Tempo do Sonho aborígene — o ser ancestral que guarda a estabilidade da terra e da água.', fr: 'Dans le Temps du Rêve aborigène — l\'être ancestral qui garde la stabilité de la terre et de l\'eau.', ja: 'アボリジニのドリームタイムにおいて——大地と水の安定を守る祖霊的存在。' } },
    ],
    myths: [
      { tr: 'Sobek ve Nil: Mısırlılar Nil\'in taşmasını Sobek\'in iradesi sayardı. Tanrıyı memnun etmek için timsahlara altın takılır, tapınaklarda bakılırdı — korkulan ama saygı duyulan güç.', en: 'Sobek and the Nile: The Egyptians considered the Nile\'s flooding to be Sobek\'s will. To please the god, crocodiles were adorned with gold and tended in temples — a power feared yet revered.', de: 'Sobek und der Nil: Die Ägypter hielten die Überschwemmung des Nils für Sobeks Willen. Um den Gott zu erfreuen, wurden Krokodile mit Gold geschmückt und in Tempeln gepflegt — eine gefürchtete, doch verehrte Macht.', es: 'Sobek y el Nilo: Los egipcios consideraban la crecida del Nilo voluntad de Sobek. Para complacer al dios, se adornaba a los cocodrilos con oro y se les cuidaba en los templos — un poder temido pero venerado.', pt: 'Sobek e o Nilo: Os egípcios consideravam a cheia do Nilo vontade de Sobek. Para agradar ao deus, os crocodilos eram adornados com ouro e cuidados nos templos — um poder temido mas venerado.', fr: 'Sobek et le Nil : Les Égyptiens tenaient la crue du Nil pour la volonté de Sobek. Pour plaire au dieu, on parait les crocodiles d\'or et on les soignait dans les temples — une puissance crainte mais vénérée.', ja: 'セベクとナイル：エジプト人はナイルの氾濫をセベクの意志とみなした。神を喜ばせるため、ワニは黄金で飾られ、神殿で世話された——恐れられつつも敬われる力。' },
      { tr: 'Cipactli\'nin Yaratılışı: Aztek mitolojisinde Quetzalcoatl ve Tezcatlipoca, devasa timsah Cipactli\'yi parçalayarak dünyayı yaratır. Gökyüzü onun sırtı, yer onun karnı — yaratılış parçalanmadır.', en: 'Cipactli\'s Creation: In Aztec mythology, Quetzalcoatl and Tezcatlipoca create the world by dismembering the giant crocodile Cipactli. The sky is its back, the earth its belly — creation is dismemberment.', de: 'Cipactlis Schöpfung: In der aztekischen Mythologie erschaffen Quetzalcoatl und Tezcatlipoca die Welt, indem sie das Riesenkrokodil Cipactli zerstückeln. Der Himmel ist sein Rücken, die Erde sein Bauch — Schöpfung ist Zerstückelung.', es: 'La creación de Cipactli: En la mitología azteca, Quetzalcóatl y Tezcatlipoca crean el mundo desmembrando al cocodrilo gigante Cipactli. El cielo es su lomo, la tierra su vientre — la creación es desmembramiento.', pt: 'A criação de Cipactli: Na mitologia asteca, Quetzalcoatl e Tezcatlipoca criam o mundo desmembrando o crocodilo gigante Cipactli. O céu é as suas costas, a terra o seu ventre — a criação é desmembramento.', fr: 'La création de Cipactli : Dans la mythologie aztèque, Quetzalcoatl et Tezcatlipoca créent le monde en démembrant le crocodile géant Cipactli. Le ciel est son dos, la terre son ventre — la création est démembrement.', ja: 'シパクトリの創造：アステカ神話において、ケツァルコアトルとテスカトリポカは巨大なワニのシパクトリを切り裂いて世界を創る。天はその背、大地はその腹——創造とは引き裂きである。' },
    ],
  },

  // ─── a031 Kartal Baykuşu ────────────────────────────────────────────────
  a031: {
    jung: { tr: '"Karanlık Bilgelik" arketipi. Kartal baykuşu — gece kralı. Baykuşun sezgisi ve kartalın gücü birleşmiş.', en: 'The "Dark Wisdom" archetype. The eagle owl — king of the night. The owl\'s intuition and the eagle\'s power united.', de: 'Der Archetyp der "dunklen Weisheit". Der Uhu — König der Nacht. Die Intuition der Eule und die Kraft des Adlers vereint.', es: 'El arquetipo de la "Sabiduría Oscura". El búho real — rey de la noche. La intuición del búho y el poder del águila unidos.', pt: 'O arquétipo da "Sabedoria Escura". O bufo-real — rei da noite. A intuição da coruja e o poder da águia unidos.', fr: 'L\'archétype de la "Sagesse sombre". Le grand-duc — roi de la nuit. L\'intuition du hibou et la puissance de l\'aigle unies.', ja: '「闇の知恵」の元型。ワシミミズク——夜の王。フクロウの直感とワシの力が一つに。' },
    dream: { tr: 'Kartal baykuşu rüyada — derin bir gece bilgisi sana açılıyor. Hem otorite hem sezgi taşıyor. Karanlıkta görü kazanıyorsun.', en: 'Eagle owl in dream — a deep nocturnal knowledge is opening to you. It carries both authority and intuition. You are gaining vision in darkness.', de: 'Uhu im Traum — ein tiefes nächtliches Wissen öffnet sich dir. Er trägt sowohl Autorität als auch Intuition. Du gewinnst Sicht in der Dunkelheit.', es: 'Búho real en sueños — un profundo conocimiento nocturno se te abre. Porta autoridad e intuición a la vez. Ganas visión en la oscuridad.', pt: 'Bufo-real em sonho — um profundo conhecimento noturno abre-se a ti. Carrega autoridade e intuição. Ganhas visão na escuridão.', fr: 'Grand-duc en rêve — un profond savoir nocturne s\'ouvre à toi. Il porte à la fois l\'autorité et l\'intuition. Tu gagnes la vision dans l\'obscurité.', ja: '夢の中のワシミミズク——深い夜の知があなたに開かれていく。権威と直感の双方を担う。あなたは闇の中で見る力を得ている。' },
    shadow: { tr: 'Yargılayıcı bilgelik. "Ben gördüm, sen göremedin" üstünlüğü. Bilgi otoriteye dönüşürse — yalnız kalır.', en: 'Judgmental wisdom. The superiority of "I saw, you could not". When knowledge turns to authority — it ends alone.', de: 'Urteilende Weisheit. Die Überlegenheit des "Ich habe gesehen, du konntest nicht". Wird Wissen zu Autorität — bleibt es allein.', es: 'Sabiduría que juzga. La superioridad de "yo vi, tú no pudiste". Cuando el conocimiento se vuelve autoridad — queda solo.', pt: 'Sabedoria que julga. A superioridade de "eu vi, tu não pudeste". Quando o conhecimento se torna autoridade — fica só.', fr: 'Sagesse qui juge. La supériorité du "j\'ai vu, tu n\'as pu". Quand le savoir devient autorité — il finit seul.', ja: '裁く知恵。「私は見た、お前は見られなかった」という優越。知が権威に変われば——独りになる。' },
    whenAppears: { tr: 'Hem güç hem sezgi gerektiğinde, geceleyin alınması gereken kararlarda, derinlerden gelen liderlik anlarında.', en: 'When both power and intuition are required, in decisions that must be made at night, in moments of leadership rising from the depths.', de: 'Wenn sowohl Macht als auch Intuition gefragt sind, bei Entscheidungen, die nachts getroffen werden müssen, in Momenten der Führung, die aus der Tiefe steigt.', es: 'Cuando se requieren poder e intuición, en decisiones que deben tomarse de noche, en momentos de liderazgo que surgen de las profundidades.', pt: 'Quando se exigem poder e intuição, em decisões que devem ser tomadas à noite, em momentos de liderança que sobem das profundezas.', fr: 'Quand puissance et intuition sont requises, dans les décisions à prendre la nuit, dans les moments de leadership montant des profondeurs.', ja: '力と直感の双方が求められるとき、夜に下されねばならぬ決断において、深みから立ち上がる指導力の瞬間に。' },
    traditions: [
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Toroslar\'ın gece kralı. En büyük baykuş türü — dağ bilgeliğinin somut hâli.', en: 'King of the Taurus night. The largest of the owl species — the embodied form of mountain wisdom.', de: 'König der Taurus-Nacht. Die größte Eulenart — die verkörperte Gestalt der Bergweisheit.', es: 'Rey de la noche del Tauro. La mayor de las especies de búho — la forma encarnada de la sabiduría de la montaña.', pt: 'Rei da noite do Tauro. A maior das espécies de coruja — a forma encarnada da sabedoria da montanha.', fr: 'Roi de la nuit du Taurus. La plus grande des espèces de hibou — la forme incarnée de la sagesse de la montagne.', ja: 'トロス山脈の夜の王。フクロウの中で最大の種——山の知恵が肉体をまとった姿。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Athena\'nın baykuşunun büyük akrabası. Gerçek bilgeliğin gece görüsü.', en: 'Larger kin to Athena\'s owl. The nocturnal vision of true wisdom.', de: 'Größerer Verwandter von Athenes Eule. Die nächtliche Sicht der wahren Weisheit.', es: 'Pariente mayor del búho de Atenea. La visión nocturna de la verdadera sabiduría.', pt: 'Parente maior da coruja de Atena. A visão noturna da verdadeira sabedoria.', fr: 'Parent plus grand du hibou d\'Athéna. La vision nocturne de la vraie sagesse.', ja: 'アテナのフクロウのより大きな縁者。真の知恵の夜の視。' } },
      { culture: { tr: 'Türk Şamanizmi', en: 'Turkic Shamanism', de: 'Türkischer Schamanismus', es: 'Chamanismo Túrquico', pt: 'Xamanismo Túrquico', fr: 'Chamanisme Turc', ja: 'テュルク・シャーマニズム' }, meaning: { tr: 'Şaman gecesinde göğe yükselen baykuş ruhu — en üst saviyenin sembolü.', en: 'The owl-spirit ascending to the sky in the shaman\'s night — symbol of the highest realm.', de: 'Der Eulengeist, der in der Nacht des Schamanen zum Himmel aufsteigt — Symbol der höchsten Sphäre.', es: 'El espíritu-búho que asciende al cielo en la noche del chamán — símbolo del reino más alto.', pt: 'O espírito-coruja que sobe ao céu na noite do xamã — símbolo do reino mais alto.', fr: 'L\'esprit-hibou qui s\'élève au ciel dans la nuit du chamane — symbole du royaume le plus haut.', ja: 'シャーマンの夜に天へ昇るフクロウの霊——最も高き領域の象徴。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Cailleach\'in kuşu — yaşlı tanrıçanın gece habercisi.', en: 'The Cailleach\'s bird — the night-messenger of the old goddess.', de: 'Der Vogel der Cailleach — der Nachtbote der alten Göttin.', es: 'El ave de la Cailleach — el mensajero nocturno de la vieja diosa.', pt: 'A ave da Cailleach — o mensageiro noturno da velha deusa.', fr: 'L\'oiseau de la Cailleach — le messager nocturne de la vieille déesse.', ja: 'カリアッハの鳥——老いた女神の夜の使者。' } },
      { culture: { tr: 'Sibirya', en: 'Siberian', de: 'Sibirisch', es: 'Siberiano', pt: 'Siberiano', fr: 'Sibérien', ja: 'シベリア' }, meaning: { tr: 'Tundranın bekçisi. Yalnız avcının atası kabul edilir.', en: 'Guardian of the tundra. Held to be the ancestor of the solitary hunter.', de: 'Hüter der Tundra. Gilt als Ahn des einsamen Jägers.', es: 'Guardián de la tundra. Tenido por el ancestro del cazador solitario.', pt: 'Guardião da tundra. Tido como o ancestral do caçador solitário.', fr: 'Gardien de la toundra. Tenu pour l\'ancêtre du chasseur solitaire.', ja: 'ツンドラの番人。孤独な狩人の祖先とされる。' } },
    ],
    myths: [
      { tr: 'Kartal Baykuşu ve Avcı: Sibirya halk hikâyelerinde genç bir avcı yıllarca kartal baykuşundan ders alır — gece görüsü, sessiz hareket, doğru zamanlama. Sonunda kendisi gece kralı olur.', en: 'The Eagle Owl and the Hunter: In Siberian folk tales, a young hunter studies for years under the eagle owl — night vision, silent movement, right timing. At last he himself becomes king of the night.', de: 'Der Uhu und der Jäger: In sibirischen Volksmärchen lernt ein junger Jäger jahrelang beim Uhu — Nachtsicht, lautlose Bewegung, das rechte Timing. Am Ende wird er selbst König der Nacht.', es: 'El búho real y el cazador: En los cuentos populares siberianos, un joven cazador aprende durante años del búho real — visión nocturna, movimiento silencioso, oportunidad justa. Al fin él mismo se vuelve rey de la noche.', pt: 'O bufo-real e o caçador: Nos contos populares siberianos, um jovem caçador aprende durante anos com o bufo-real — visão noturna, movimento silencioso, o momento certo. Por fim ele próprio se torna rei da noite.', fr: 'Le grand-duc et le chasseur : Dans les contes populaires sibériens, un jeune chasseur apprend des années durant auprès du grand-duc — vision nocturne, mouvement silencieux, juste moment. À la fin, il devient lui-même roi de la nuit.', ja: 'ワシミミズクと狩人：シベリアの民話において、若い狩人は何年もワシミミズクから学ぶ——夜の視、音なき動き、的確な間合い。ついに彼自身が夜の王となる。' },
      { tr: 'Toros Dağları: Anadolu\'da bu kuşa rastlamak çok nadirdir. Onu gören kişinin "ata bilgeliğinden" haber aldığı söylenir. Kayboluşu — kaybedilen sezginin işareti.', en: 'The Taurus Mountains: To encounter this bird in Anatolia is very rare. Those who see it are said to receive word from "ancestral wisdom". Its disappearance — a sign of lost intuition.', de: 'Das Taurusgebirge: Diesem Vogel in Anatolien zu begegnen, ist sehr selten. Wer ihn sieht, soll Nachricht aus der "Ahnenweisheit" empfangen. Sein Verschwinden — ein Zeichen verlorener Intuition.', es: 'Los montes Tauro: Encontrar esta ave en Anatolia es muy raro. Se dice que quien la ve recibe noticia de la "sabiduría ancestral". Su desaparición — señal de la intuición perdida.', pt: 'Os montes Tauro: Encontrar esta ave na Anatólia é muito raro. Diz-se que quem a vê recebe notícia da "sabedoria ancestral". O seu desaparecimento — sinal da intuição perdida.', fr: 'Les monts Taurus : Rencontrer cet oiseau en Anatolie est très rare. On dit que celui qui le voit reçoit un message de la "sagesse ancestrale". Sa disparition — signe de l\'intuition perdue.', ja: 'トロス山脈：アナトリアでこの鳥に出会うことは極めて稀。見た者は「祖先の知恵」から報せを受けると言われる。その消失——失われた直感の徴。' },
    ],
  },

  // ─── a032 Boğa ──────────────────────────────────────────────────────────
  a032: {
    jung: { tr: '"Bedenlenmiş Güç" arketipi. Boğa — toprağa kök salmış erkek/dişil güç. Şehvet, bereket, ama aynı zamanda kontrol edilmesi gereken vahşilik.', en: 'The "Embodied Power" archetype. The bull — masculine/feminine force rooted in the earth. Lust, fertility, yet also a wildness that must be controlled.', de: 'Der Archetyp der "verkörperten Kraft". Der Stier — in der Erde wurzelnde männliche/weibliche Kraft. Lust, Fruchtbarkeit, doch auch eine Wildheit, die beherrscht werden muss.', es: 'El arquetipo del "Poder Encarnado". El toro — fuerza masculina/femenina enraizada en la tierra. Lujuria, fertilidad, pero también un salvajismo que debe ser controlado.', pt: 'O arquétipo do "Poder Encarnado". O touro — força masculina/feminina enraizada na terra. Luxúria, fertilidade, mas também uma selvajaria que deve ser controlada.', fr: 'L\'archétype de la "Puissance incarnée". Le taureau — force masculine/féminine enracinée dans la terre. Désir, fertilité, mais aussi une sauvagerie qui doit être maîtrisée.', ja: '「肉体化した力」の元型。雄牛——大地に根を張った男性／女性の力。情欲、豊穣、だが同時に制御されねばならぬ野生。' },
    dream: { tr: 'Boğa rüyada — bedenin ve içgüdülerinin sesi. Saldırıyorsa: bastırılmış arzu/öfke patlıyor. Otluyorsa: doyumlu bir döneme giriyorsun.', en: 'Bull in dream — the voice of body and instinct. Charging: a repressed desire or anger is exploding. Grazing: you are entering a period of contentment.', de: 'Stier im Traum — die Stimme von Körper und Instinkt. Stürmt er: Ein unterdrücktes Verlangen oder Zorn bricht aus. Grast er: Du trittst in eine Zeit der Zufriedenheit ein.', es: 'Toro en sueños — la voz del cuerpo y el instinto. Si embiste: un deseo o una ira reprimidos estallan. Si pace: entras en un período de contento.', pt: 'Touro em sonho — a voz do corpo e do instinto. Se investe: um desejo ou uma ira reprimidos irrompem. Se pasta: entras num período de contentamento.', fr: 'Taureau en rêve — la voix du corps et de l\'instinct. Chargeant : un désir ou une colère réprimés explosent. Paissant : tu entres dans une période de contentement.', ja: '夢の中の雄牛——体と本能の声。突進するなら、抑え込まれた欲望や怒りが噴き出している。草を食むなら、あなたは満ち足りた時期に入りつつある。' },
    shadow: { tr: 'Şiddet ve baskı. Boğa enerjisi kontrol edilmezse — zorbalığa, kıskançlığa, yıkıma dönüşür.', en: 'Violence and dominance. Uncontrolled, bull energy turns into bullying, jealousy, destruction.', de: 'Gewalt und Beherrschung. Ungezügelt verwandelt sich die Stierenergie in Schikane, Eifersucht, Zerstörung.', es: 'Violencia y dominación. Sin control, la energía del toro se vuelve abuso, celos, destrucción.', pt: 'Violência e domínio. Descontrolada, a energia do touro torna-se intimidação, ciúme, destruição.', fr: 'Violence et domination. Non maîtrisée, l\'énergie du taureau devient brutalité, jalousie, destruction.', ja: '暴力と支配。制御されなければ、雄牛のエネルギーは威圧、嫉妬、破壊へと変わる。' },
    whenAppears: { tr: 'Bedensel gücünle bağlandığında, cinsel/yaratıcı enerjini doğru yöne çevirmen gerekirken, kararını "ayakta dur" haline getirmen lazımken.', en: 'When you connect with your bodily power, when you must direct sexual/creative energy rightly, when you must turn your decision into a "stand your ground".', de: 'Wenn du dich mit deiner körperlichen Kraft verbindest, wenn du sexuelle/schöpferische Energie richtig lenken musst, wenn du deine Entscheidung in ein "Steh deinen Mann" verwandeln musst.', es: 'Cuando conectas con tu poder corporal, cuando debes dirigir bien la energía sexual/creativa, cuando debes convertir tu decisión en un "mantente firme".', pt: 'Quando te ligas ao teu poder corporal, quando deves dirigir bem a energia sexual/criativa, quando deves transformar a tua decisão num "mantém-te firme".', fr: 'Quand tu te relies à ta puissance corporelle, quand tu dois bien diriger l\'énergie sexuelle/créative, quand tu dois faire de ta décision un "tiens bon".', ja: '自らの身体の力とつながるとき、性的／創造的なエネルギーを正しく向けねばならぬとき、決断を「踏みとどまる」ことへと変えねばならぬときに。' },
    traditions: [
      { culture: { tr: 'Hitit/Anadolu', en: 'Hittite/Anatolian', de: 'Hethitisch/Anatolisch', es: 'Hitita/Anatolio', pt: 'Hitita/Anatólio', fr: 'Hittite/Anatolien', ja: 'ヒッタイト／アナトリア' }, meaning: { tr: 'Hattuşa\'da boğa tapınağı. Fırtına tanrısının (Teşup) kutsal bineği. Anadolu medeniyetinin ekseni.', en: 'The bull temple at Hattusa. Sacred mount of the storm god (Teshub). The axis of Anatolian civilization.', de: 'Der Stiertempel in Hattuša. Heiliges Reittier des Wettergottes (Teschub). Die Achse der anatolischen Zivilisation.', es: 'El templo del toro en Hattusa. Montura sagrada del dios de la tormenta (Teshub). El eje de la civilización anatolia.', pt: 'O templo do touro em Hattusa. Montaria sagrada do deus da tempestade (Teshub). O eixo da civilização anatólia.', fr: 'Le temple du taureau à Hattusa. Monture sacrée du dieu de l\'orage (Teshub). L\'axe de la civilisation anatolienne.', ja: 'ハットゥシャの雄牛の神殿。嵐の神（テシュブ）の聖なる乗り物。アナトリア文明の軸。' } },
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Apis — Memphis\'te yaşatılan kutsal boğa. Yeryüzünde Osiris\'in bedenleşmiş hâli.', en: 'Apis — the sacred bull kept at Memphis. The earthly incarnation of Osiris.', de: 'Apis — der heilige Stier, gehalten in Memphis. Die irdische Verkörperung des Osiris.', es: 'Apis — el toro sagrado mantenido en Menfis. La encarnación terrenal de Osiris.', pt: 'Ápis — o touro sagrado mantido em Mênfis. A encarnação terrena de Osíris.', fr: 'Apis — le taureau sacré gardé à Memphis. L\'incarnation terrestre d\'Osiris.', ja: 'アピス——メンフィスで生かされた聖なる雄牛。地上におけるオシリスの化身。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Minotaur — yarı insan yarı boğa. Knossos\'taki labirentin ortasındaki bastırılmış doğa.', en: 'Minotaur — half man, half bull. The repressed nature at the center of the labyrinth at Knossos.', de: 'Minotaurus — halb Mensch, halb Stier. Die unterdrückte Natur im Zentrum des Labyrinths von Knossos.', es: 'Minotauro — mitad hombre, mitad toro. La naturaleza reprimida en el centro del laberinto de Cnosos.', pt: 'Minotauro — meio homem, meio touro. A natureza reprimida no centro do labirinto de Cnossos.', fr: 'Minotaure — mi-homme, mi-taureau. La nature réprimée au centre du labyrinthe de Cnossos.', ja: 'ミノタウロス——半人半牛。クノッソスの迷宮の中心に潜む抑圧された本性。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Nandi — Şiva\'nın bineği. Tapınakların önünde otururken karşı tarafa, ilahi tarafa bakar.', en: 'Nandi — Shiva\'s mount. Seated before temples, he gazes across to the divine side.', de: 'Nandi — Shivas Reittier. Vor den Tempeln sitzend, blickt er hinüber zur göttlichen Seite.', es: 'Nandi — la montura de Shiva. Sentado ante los templos, mira hacia el lado divino.', pt: 'Nandi — a montaria de Shiva. Sentado diante dos templos, olha para o lado divino.', fr: 'Nandi — la monture de Shiva. Assis devant les temples, il regarde vers le côté divin.', ja: 'ナンディン——シヴァの乗り物。神殿の前に座し、神聖なる側を見つめる。' } },
      { culture: { tr: 'Mitra Kültü', en: 'Mithraic Cult', de: 'Mithras-Kult', es: 'Culto Mitraico', pt: 'Culto de Mitra', fr: 'Culte de Mithra', ja: 'ミトラ教' }, meaning: { tr: 'Mitra\'nın boğayı boğazlaması — kozmik yenilenme ayini. Roma askerinin sırı.', en: 'Mithras\'s slaying of the bull — the cosmic renewal rite. The secret of the Roman soldier.', de: 'Mithras\' Tötung des Stiers — der Ritus kosmischer Erneuerung. Das Geheimnis des römischen Soldaten.', es: 'La matanza del toro por Mitra — el rito de renovación cósmica. El secreto del soldado romano.', pt: 'A matança do touro por Mitra — o rito de renovação cósmica. O segredo do soldado romano.', fr: 'L\'immolation du taureau par Mithra — le rite du renouveau cosmique. Le secret du soldat romain.', ja: 'ミトラによる雄牛の屠り——宇宙的再生の儀礼。ローマ兵の秘儀。' } },
    ],
    myths: [
      { tr: 'Minotaur ve Labirent: Yunan mitolojisinde Kral Minos\'un karısı Pasiphae bir boğaya âşık olur. Doğan çocuk Minotaur — yarı insan yarı boğa. Daedalos\'un labirentinde tutulur — bastırılan şehvetin merkezde saklanması.', en: 'The Minotaur and the Labyrinth: In Greek mythology, Pasiphae, wife of King Minos, falls in love with a bull. The child born is the Minotaur — half man, half bull. He is kept in Daedalus\'s labyrinth — the repressed desire concealed at the center.', de: 'Der Minotaurus und das Labyrinth: In der griechischen Mythologie verliebt sich Pasiphae, die Frau des Königs Minos, in einen Stier. Das geborene Kind ist der Minotaurus — halb Mensch, halb Stier. Er wird im Labyrinth des Daedalus gehalten — das unterdrückte Verlangen, im Zentrum verborgen.', es: 'El Minotauro y el Laberinto: En la mitología griega, Pasífae, esposa del rey Minos, se enamora de un toro. El niño nacido es el Minotauro — mitad hombre, mitad toro. Es encerrado en el laberinto de Dédalo — el deseo reprimido oculto en el centro.', pt: 'O Minotauro e o Labirinto: Na mitologia grega, Pasífae, mulher do rei Minos, apaixona-se por um touro. A criança nascida é o Minotauro — meio homem, meio touro. É mantido no labirinto de Dédalo — o desejo reprimido oculto no centro.', fr: 'Le Minotaure et le Labyrinthe : Dans la mythologie grecque, Pasiphaé, femme du roi Minos, tombe amoureuse d\'un taureau. L\'enfant né est le Minotaure — mi-homme, mi-taureau. Il est enfermé dans le labyrinthe de Dédale — le désir réprimé caché au centre.', ja: 'ミノタウロスと迷宮：ギリシア神話において、ミノス王の妃パシパエは雄牛に恋する。生まれた子はミノタウロス——半人半牛。ダイダロスの迷宮に閉じ込められる——抑圧された欲望が中心に隠されること。' },
      { tr: 'Apis ve Memphis: Mısır\'da Apis adlı boğa Osiris\'in dünyadaki vücudu sayılırdı. Doğal ölünce büyük matem tutulur, yeni Apis doğana kadar Mısır yas içinde kalırdı.', en: 'Apis and Memphis: In Egypt, the bull called Apis was considered the earthly body of Osiris. Upon his natural death, great mourning was held, and Egypt remained in grief until a new Apis was born.', de: 'Apis und Memphis: In Ägypten galt der Stier namens Apis als der irdische Leib des Osiris. Bei seinem natürlichen Tod wurde große Trauer gehalten, und Ägypten blieb in Trauer, bis ein neuer Apis geboren wurde.', es: 'Apis y Menfis: En Egipto, el toro llamado Apis se consideraba el cuerpo terrenal de Osiris. A su muerte natural se guardaba gran luto, y Egipto permanecía afligido hasta que nacía un nuevo Apis.', pt: 'Ápis e Mênfis: No Egito, o touro chamado Ápis era considerado o corpo terreno de Osíris. À sua morte natural guardava-se grande luto, e o Egito permanecia em pesar até nascer um novo Ápis.', fr: 'Apis et Memphis : En Égypte, le taureau nommé Apis était considéré comme le corps terrestre d\'Osiris. À sa mort naturelle, on observait un grand deuil, et l\'Égypte restait en peine jusqu\'à la naissance d\'un nouvel Apis.', ja: 'アピスとメンフィス：エジプトにおいて、アピスという雄牛はオシリスの地上の体とされた。自然に死ぬと大いなる喪に服し、新たなアピスが生まれるまでエジプトは嘆きのうちにあった。' },
    ],
  },

  // ─── a033 Karınca ───────────────────────────────────────────────────────
  a033: {
    jung: { tr: '"Kolektif Sabır" arketipi. Karınca — küçük çabaların toplamı, görünmez emeğin sembolü. Disiplin ve toplumsallık.', en: 'The "Collective Patience" archetype. The ant — the sum of small efforts, symbol of invisible labor. Discipline and sociality.', de: 'Der Archetyp der "kollektiven Geduld". Die Ameise — die Summe kleiner Mühen, Symbol der unsichtbaren Arbeit. Disziplin und Gemeinschaftlichkeit.', es: 'El arquetipo de la "Paciencia Colectiva". La hormiga — la suma de pequeños esfuerzos, símbolo del trabajo invisible. Disciplina y sociabilidad.', pt: 'O arquétipo da "Paciência Coletiva". A formiga — a soma de pequenos esforços, símbolo do trabalho invisível. Disciplina e sociabilidade.', fr: 'L\'archétype de la "Patience collective". La fourmi — la somme des petits efforts, symbole du labeur invisible. Discipline et socialité.', ja: '「集団の忍耐」の元型。アリ——小さな努力の総和、見えざる労苦の象徴。規律と社会性。' },
    dream: { tr: 'Karınca rüyada — küçük adımların büyük bir yapı kurduğunu söyler. Yığın hâlinde: kolektif yaratım. Sana tırmanıyorsa: sıkıntılar birikiyor, ele al.', en: 'Ant in dream — tells you that small steps are building a great structure. In great numbers: collective creation. Climbing on you: troubles are accumulating — address them.', de: 'Ameise im Traum — sagt dir, dass kleine Schritte ein großes Gefüge errichten. In großer Zahl: kollektive Schöpfung. Krabbeln sie an dir empor: Schwierigkeiten häufen sich an — geh sie an.', es: 'Hormiga en sueños — te dice que los pequeños pasos construyen una gran estructura. En gran número: creación colectiva. Si trepa por ti: los problemas se acumulan, atiéndelos.', pt: 'Formiga em sonho — diz-te que os pequenos passos constroem uma grande estrutura. Em grande número: criação coletiva. Se trepa por ti: os problemas acumulam-se, trata deles.', fr: 'Fourmi en rêve — te dit que de petits pas bâtissent une grande structure. En grand nombre : création collective. Grimpant sur toi : les ennuis s\'accumulent, occupe-t\'en.', ja: '夢の中のアリ——小さな歩みが大いなる構造を築いていると告げる。群れをなすなら、集団の創造。あなたによじ登るなら、悩みが積もっている。対処せよ。' },
    shadow: { tr: 'Robot gibi yaşamak. Bireyselliğini kaybedip sadece "iş" haline gelmek. Karınca büyük bir parça, ama tek başına anlamlıdır.', en: 'Living like a robot. Losing individuality and becoming only "work". The ant is part of a great whole, yet meaningful in itself.', de: 'Wie ein Roboter zu leben. Die Individualität zu verlieren und nur noch "Arbeit" zu sein. Die Ameise ist Teil eines großen Ganzen, doch für sich genommen bedeutsam.', es: 'Vivir como un robot. Perder la individualidad y volverse solo "trabajo". La hormiga es parte de un gran todo, pero significativa en sí misma.', pt: 'Viver como um robô. Perder a individualidade e tornar-se apenas "trabalho". A formiga é parte de um grande todo, mas significativa em si mesma.', fr: 'Vivre comme un robot. Perdre son individualité et n\'être plus que du "travail". La fourmi fait partie d\'un grand tout, mais elle a un sens en elle-même.', ja: 'ロボットのように生きること。個を失い、ただの「仕事」になること。アリは大きな全体の一部だが、それ自体で意味をもつ。' },
    whenAppears: { tr: 'Uzun vadeli projelerde, küçük katkıların önemini fark ettiğinde, toplulukta görünmez ama vazgeçilmez rolde olduğun anda.', en: 'In long-term projects, when you grasp the importance of small contributions, at the moment you hold an invisible yet indispensable role in a community.', de: 'Bei langfristigen Vorhaben, wenn du die Bedeutung kleiner Beiträge erfasst, in dem Moment, in dem du in einer Gemeinschaft eine unsichtbare, doch unentbehrliche Rolle innehast.', es: 'En proyectos a largo plazo, cuando comprendes la importancia de las pequeñas contribuciones, en el momento en que ocupas un papel invisible pero indispensable en una comunidad.', pt: 'Em projetos de longo prazo, quando compreendes a importância das pequenas contribuições, no momento em que ocupas um papel invisível mas indispensável numa comunidade.', fr: 'Dans les projets à long terme, quand tu saisis l\'importance des petites contributions, au moment où tu tiens un rôle invisible mais indispensable dans une communauté.', ja: '長期のプロジェクトにおいて、小さな貢献の重みを悟るとき、共同体の中で見えないが欠かせぬ役割を担う瞬間に。' },
    traditions: [
      { culture: { tr: 'Süleyman ve Karınca', en: 'Solomon and the Ant', de: 'Salomo und die Ameise', es: 'Salomón y la hormiga', pt: 'Salomão e a formiga', fr: 'Salomon et la fourmi', ja: 'ソロモンとアリ' }, meaning: { tr: 'Kuran\'da Neml Suresi — Süleyman peygamber karıncaların lideriyle konuşur. Karıncanın sesi: "Yuvalarınıza girin ki Süleyman ordusu sizi çiğnemesin."', en: 'In the Qur\'an, Surah An-Naml — the prophet Solomon speaks with the leader of the ants. The ant\'s voice: "Enter your dwellings, lest Solomon and his hosts crush you."', de: 'Im Koran, die Sure An-Naml — der Prophet Salomo spricht mit der Anführerin der Ameisen. Die Stimme der Ameise: "Geht in eure Behausungen, damit Salomo und seine Heerscharen euch nicht zertreten."', es: 'En el Corán, la sura An-Naml — el profeta Salomón habla con la líder de las hormigas. La voz de la hormiga: "Entrad en vuestras moradas, no sea que Salomón y sus huestes os pisoteen."', pt: 'No Alcorão, a sura An-Naml — o profeta Salomão fala com a líder das formigas. A voz da formiga: "Entrai nas vossas moradas, para que Salomão e os seus exércitos não vos esmaguem."', fr: 'Dans le Coran, la sourate An-Naml — le prophète Salomon parle avec la cheffe des fourmis. La voix de la fourmi : "Entrez dans vos demeures, de peur que Salomon et ses armées ne vous écrasent."', ja: 'クルアーンの蟻章（アン・ナムル）——預言者ソロモンはアリの長と語る。アリの声：「巣に入りなさい。ソロモンとその軍勢があなたがたを踏みつぶさぬように。」' } },
      { culture: { tr: 'Afrika', en: 'African', de: 'Afrikanisch', es: 'Africano', pt: 'Africano', fr: 'Africain', ja: 'アフリカ' }, meaning: { tr: 'Anansi masallarında — kolektif aklın sembolü. Tek bireyin yapamadığını topluluk yapar.', en: 'In Anansi tales — symbol of the collective mind. What no single being can do, the community accomplishes.', de: 'In den Anansi-Geschichten — Symbol des kollektiven Geistes. Was kein Einzelner vermag, vollbringt die Gemeinschaft.', es: 'En los cuentos de Anansi — símbolo de la mente colectiva. Lo que ningún individuo puede hacer, lo logra la comunidad.', pt: 'Nos contos de Anansi — símbolo da mente coletiva. O que nenhum indivíduo pode fazer, a comunidade realiza.', fr: 'Dans les contes d\'Anansi — symbole de l\'esprit collectif. Ce qu\'aucun être seul ne peut faire, la communauté l\'accomplit.', ja: 'アナンシの物語において——集団の知の象徴。一個では成しえぬことを、共同体が成し遂げる。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Hopi geleneğinde karınca-insanlar yer altından geldi. Sabır ve birlik öğretmeni.', en: 'In Hopi tradition, the Ant People came from below the earth. Teacher of patience and unity.', de: 'In der Hopi-Tradition kamen die Ameisenmenschen aus dem Erdinneren. Lehrer der Geduld und der Einheit.', es: 'En la tradición hopi, el Pueblo Hormiga vino de debajo de la tierra. Maestro de la paciencia y la unidad.', pt: 'Na tradição hopi, o Povo Formiga veio de debaixo da terra. Mestre da paciência e da união.', fr: 'Dans la tradition hopi, le Peuple Fourmi vint de sous la terre. Maître de la patience et de l\'unité.', ja: 'ホピの伝統において、アリの民は地の底から来た。忍耐と団結の師。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Konfüçyüsçü gelenekte erdem örneği — disiplin, sadakat, hiyerarşi.', en: 'In the Confucian tradition, an example of virtue — discipline, loyalty, hierarchy.', de: 'In der konfuzianischen Tradition ein Vorbild der Tugend — Disziplin, Treue, Hierarchie.', es: 'En la tradición confuciana, ejemplo de virtud — disciplina, lealtad, jerarquía.', pt: 'Na tradição confuciana, exemplo de virtude — disciplina, lealdade, hierarquia.', fr: 'Dans la tradition confucéenne, un modèle de vertu — discipline, loyauté, hiérarchie.', ja: '儒教の伝統において徳の手本——規律、忠誠、序列。' } },
      { culture: { tr: 'Anadolu Halk', en: 'Anatolian Folk', de: 'Anatolische Volkskultur', es: 'Folclore Anatolio', pt: 'Folclore Anatólio', fr: 'Folklore Anatolien', ja: 'アナトリア民俗' }, meaning: { tr: '"Karınca kararınca" deyişi — herkes payına düşeni yapsın.', en: 'The saying "ant by ant\'s measure" — let each do their share.', de: 'Das Sprichwort "nach Ameisenmaß" — jeder tue seinen Teil.', es: 'El dicho "a medida de hormiga" — que cada uno haga su parte.', pt: 'O ditado "à medida da formiga" — que cada um faça a sua parte.', fr: 'Le dicton "à la mesure de la fourmi" — que chacun fasse sa part.', ja: '「アリの分相応に」という言葉——各々が自分の分を果たせ。' } },
    ],
    myths: [
      { tr: 'Süleyman ve Karınca Vadisi: Kuran\'da Süleyman ordusu karıncalar vadisinden geçerken bir karınca diğerlerini uyarır. Süleyman gülümser ve şükreder. En küçük yaratığın sözünü duyabilmek — gerçek liderliktir.', en: 'Solomon and the Valley of the Ants: In the Qur\'an, as Solomon\'s army passes through the valley of the ants, one ant warns the others. Solomon smiles and gives thanks. To hear the speech of the smallest creature — that is true leadership.', de: 'Salomo und das Tal der Ameisen: Im Koran warnt eine Ameise die anderen, als Salomos Heer das Tal der Ameisen durchquert. Salomo lächelt und dankt. Die Rede des kleinsten Geschöpfs hören zu können — das ist wahre Führung.', es: 'Salomón y el valle de las hormigas: En el Corán, cuando el ejército de Salomón cruza el valle de las hormigas, una hormiga advierte a las demás. Salomón sonríe y da gracias. Poder oír la palabra de la más pequeña criatura — eso es el verdadero liderazgo.', pt: 'Salomão e o vale das formigas: No Alcorão, quando o exército de Salomão atravessa o vale das formigas, uma formiga avisa as outras. Salomão sorri e dá graças. Poder ouvir a palavra da mais pequena criatura — eis a verdadeira liderança.', fr: 'Salomon et la vallée des fourmis : Dans le Coran, alors que l\'armée de Salomon traverse la vallée des fourmis, une fourmi avertit les autres. Salomon sourit et rend grâce. Pouvoir entendre la parole de la plus petite créature — voilà le vrai leadership.', ja: 'ソロモンとアリの谷：クルアーンにおいて、ソロモンの軍勢がアリの谷を通るとき、一匹のアリが他を警告する。ソロモンは微笑み、感謝する。最も小さき生き物の言葉を聞きうること——それこそ真の指導力である。' },
      { tr: 'Hopi Karınca-İnsanları: Hopi yaratılış mitinde, dünyanın yüzeyi bozulunca insanlar yer altına çekilir. Karınca-insanlar onları besler, korur, sonunda yeniden yüzeye taşır — kolektif şifa.', en: 'The Hopi Ant People: In the Hopi creation myth, when the surface of the world is corrupted, humans retreat underground. The Ant People feed and protect them, and finally bring them back to the surface — collective healing.', de: 'Die Hopi-Ameisenmenschen: Im Schöpfungsmythos der Hopi ziehen sich die Menschen unter die Erde zurück, als die Oberfläche der Welt verdorben wird. Die Ameisenmenschen nähren und schützen sie und bringen sie schließlich wieder an die Oberfläche — kollektive Heilung.', es: 'El Pueblo Hormiga hopi: En el mito de creación hopi, cuando la superficie del mundo se corrompe, los humanos se retiran bajo tierra. El Pueblo Hormiga los alimenta y protege, y al fin los devuelve a la superficie — sanación colectiva.', pt: 'O Povo Formiga hopi: No mito da criação hopi, quando a superfície do mundo se corrompe, os humanos recolhem-se debaixo da terra. O Povo Formiga alimenta-os e protege-os, e por fim traz-nos de volta à superfície — cura coletiva.', fr: 'Le Peuple Fourmi hopi : Dans le mythe de la création hopi, quand la surface du monde se corrompt, les humains se retirent sous terre. Le Peuple Fourmi les nourrit et les protège, et finit par les ramener à la surface — guérison collective.', ja: 'ホピのアリの民：ホピの創造神話において、世界の地表が穢れると人々は地下に退く。アリの民が彼らを養い、守り、ついには地上へ連れ戻す——集団の癒し。' },
    ],
  },

  // ─── a034 Hac Leyleği ───────────────────────────────────────────────────
  a034: {
    jung: { tr: '"Yolcu Hac\'ı" arketipi. Hac leyleği — ömrü yolculuğa adamış. Her yıl aynı kutsal yolu yenilemek.', en: 'The "Pilgrim Wayfarer" archetype. The pilgrim stork — a life devoted to journey. Renewing the same sacred path each year.', de: 'Der Archetyp des "pilgernden Wanderers". Der Pilgerstorch — ein der Reise geweihtes Leben. Jedes Jahr denselben heiligen Weg erneuern.', es: 'El arquetipo del "Peregrino Caminante". La cigüeña peregrina — una vida consagrada al viaje. Renovar cada año el mismo camino sagrado.', pt: 'O arquétipo do "Peregrino Andarilho". A cegonha peregrina — uma vida consagrada à viagem. Renovar a cada ano o mesmo caminho sagrado.', fr: 'L\'archétype du "Pèlerin cheminant". La cigogne pèlerine — une vie vouée au voyage. Renouveler chaque année le même chemin sacré.', ja: '「旅する巡礼者」の元型。巡礼のコウノトリ——旅に捧げられた生涯。毎年、同じ聖なる道を新たにすること。' },
    dream: { tr: 'Hac leyleği rüyada — ruhsal bir göç yaklaşıyor. Aynı yere her yıl giden bir döngünün parçasısın. Yola çıkmanın zamanı geldi.', en: 'Pilgrim stork in dream — a spiritual migration approaches. You are part of a cycle returning to the same place each year. The time has come to set out.', de: 'Pilgerstorch im Traum — eine geistige Wanderung naht. Du bist Teil eines Kreislaufs, der jedes Jahr an denselben Ort zurückkehrt. Die Zeit aufzubrechen ist gekommen.', es: 'Cigüeña peregrina en sueños — una migración espiritual se acerca. Eres parte de un ciclo que vuelve al mismo lugar cada año. Ha llegado el momento de partir.', pt: 'Cegonha peregrina em sonho — uma migração espiritual aproxima-se. És parte de um ciclo que regressa ao mesmo lugar todos os anos. Chegou o momento de partir.', fr: 'Cigogne pèlerine en rêve — une migration spirituelle approche. Tu fais partie d\'un cycle qui revient au même lieu chaque année. Le moment de partir est venu.', ja: '夢の中の巡礼のコウノトリ——霊的な渡りが近づいている。あなたは毎年同じ場所へ戻る循環の一部。旅立ちの時が来た。' },
    shadow: { tr: 'Sürekli "yolda" olmak ama hiç varmamak. Hac sembolik bir yolculuktur — eğer asla dönmüyorsan, kaçışa dönüşür.', en: 'Always being "on the way" but never arriving. The pilgrimage is a symbolic journey — if you never return, it becomes flight.', de: 'Stets "unterwegs" zu sein, doch niemals anzukommen. Die Pilgerfahrt ist eine symbolische Reise — kehrst du nie zurück, wird sie zur Flucht.', es: 'Estar siempre "en camino" pero nunca llegar. La peregrinación es un viaje simbólico — si nunca regresas, se vuelve huida.', pt: 'Estar sempre "a caminho" mas nunca chegar. A peregrinação é uma viagem simbólica — se nunca regressas, torna-se fuga.', fr: 'Être toujours "en chemin" mais ne jamais arriver. Le pèlerinage est un voyage symbolique — si tu ne reviens jamais, il devient fuite.', ja: '常に「道の途上」にあって、決して到着しないこと。巡礼は象徴的な旅——決して戻らなければ、逃避となる。' },
    whenAppears: { tr: 'Uzun, döngüsel bir göç döneminde, ruhsal bir hac niyetinde, "her yıl bu zamanda hep aynı" hissinde.', en: 'In a long, cyclical period of migration, in the intention of a spiritual pilgrimage, in the feeling "every year at this time, the same again".', de: 'In einer langen, zyklischen Wanderzeit, in der Absicht einer geistigen Pilgerfahrt, im Gefühl "jedes Jahr um diese Zeit dasselbe".', es: 'En un período largo y cíclico de migración, en la intención de una peregrinación espiritual, en la sensación de "cada año por estas fechas, lo mismo".', pt: 'Num período longo e cíclico de migração, na intenção de uma peregrinação espiritual, na sensação de "todos os anos por esta altura, o mesmo".', fr: 'Dans une longue période cyclique de migration, dans l\'intention d\'un pèlerinage spirituel, dans le sentiment "chaque année à cette époque, encore la même chose".', ja: '長く循環する渡りの時期に、霊的な巡礼の意図のうちに、「毎年この時期はいつも同じ」という感覚のうちに。' },
    traditions: [
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: '"Hacı leylek" — hacca gidip dönen kuş. Çatıdaki yuvası — kutsanmış ev.', en: '"Hacı leylek" — the bird that goes on pilgrimage and returns. Its rooftop nest — a blessed home.', de: '"Hacı leylek" — der Vogel, der zur Pilgerfahrt zieht und zurückkehrt. Sein Nest auf dem Dach — ein gesegnetes Heim.', es: '"Hacı leylek" — el ave que va de peregrinación y regresa. Su nido en el tejado — un hogar bendecido.', pt: '"Hacı leylek" — a ave que vai em peregrinação e regressa. O seu ninho no telhado — um lar abençoado.', fr: '"Hacı leylek" — l\'oiseau qui part en pèlerinage et revient. Son nid sur le toit — un foyer béni.', ja: '「ハジュ・レイレキ」——巡礼に赴き戻る鳥。屋根の巣——祝福された家。' } },
      { culture: { tr: 'İslam Halk', en: 'Islamic Folk', de: 'Islamische Volkskultur', es: 'Folclore Islámico', pt: 'Folclore Islâmico', fr: 'Folklore Islamique', ja: 'イスラーム民俗' }, meaning: { tr: 'Yıllık göçü hac olarak yorumlanır. Mekke\'ye gidip dönen ruh.', en: 'Its yearly migration is interpreted as pilgrimage. The soul that travels to Mecca and returns.', de: 'Seine jährliche Wanderung wird als Pilgerfahrt gedeutet. Die Seele, die nach Mekka reist und zurückkehrt.', es: 'Su migración anual se interpreta como peregrinación. El alma que viaja a La Meca y regresa.', pt: 'A sua migração anual é interpretada como peregrinação. A alma que viaja a Meca e regressa.', fr: 'Sa migration annuelle est interprétée comme un pèlerinage. L\'âme qui voyage à La Mecque et en revient.', ja: 'その年ごとの渡りは巡礼と解される。メッカへ旅して戻る魂。' } },
      { culture: { tr: 'Slav', en: 'Slavic', de: 'Slawisch', es: 'Eslavo', pt: 'Eslavo', fr: 'Slave', ja: 'スラヴ' }, meaning: { tr: 'Dolu Çar tanrısının habercisi. Bahar getiren kuş.', en: 'Messenger of the god Tsar of Hail. The bird that brings spring.', de: 'Bote des Gottes Zar des Hagels. Der Vogel, der den Frühling bringt.', es: 'Mensajero del dios Zar del Granizo. El ave que trae la primavera.', pt: 'Mensageiro do deus Czar do Granizo. A ave que traz a primavera.', fr: 'Messager du dieu Tsar de la Grêle. L\'oiseau qui apporte le printemps.', ja: '雹の皇帝なる神の使者。春をもたらす鳥。' } },
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Ba ruhunun kuş hâli — bedenden ayrılıp seyahat eden öz.', en: 'The bird-form of the Ba soul — the essence that leaves the body and travels.', de: 'Die Vogelgestalt der Ba-Seele — das Wesen, das den Leib verlässt und reist.', es: 'La forma de ave del alma Ba — la esencia que deja el cuerpo y viaja.', pt: 'A forma de ave da alma Ba — a essência que deixa o corpo e viaja.', fr: 'La forme d\'oiseau de l\'âme Ba — l\'essence qui quitte le corps et voyage.', ja: 'バーの魂の鳥の姿——肉体を離れて旅する本質。' } },
      { culture: { tr: 'Anadolu Halk', en: 'Anatolian Folk', de: 'Anatolische Volkskultur', es: 'Folclore Anatolio', pt: 'Folclore Anatólio', fr: 'Folklore Anatolien', ja: 'アナトリア民俗' }, meaning: { tr: '"Leylek bahar getirir" — döngüsel umut sembolü.', en: '"The stork brings spring" — symbol of cyclical hope.', de: '"Der Storch bringt den Frühling" — Symbol der zyklischen Hoffnung.', es: '"La cigüeña trae la primavera" — símbolo de la esperanza cíclica.', pt: '"A cegonha traz a primavera" — símbolo da esperança cíclica.', fr: '"La cigogne apporte le printemps" — symbole de l\'espoir cyclique.', ja: '「コウノトリは春を運ぶ」——巡る希望の象徴。' } },
    ],
    myths: [
      { tr: 'Hacca Giden Leylek: Anadolu inanışına göre leylekler her yıl Mekke yönüne göç eder, dönerler. Bu nedenle "hacı leylek" denir. Onlara zarar veren bir kutsalı bozmuş sayılır.', en: 'The Stork that Goes on Hajj: According to Anatolian belief, storks migrate each year toward Mecca and return. For this reason they are called "hacı leylek". To harm them is to break a sacred thing.', de: 'Der zur Hadsch ziehende Storch: Nach anatolischem Glauben ziehen Störche jedes Jahr Richtung Mekka und kehren zurück. Darum nennt man sie "hacı leylek". Wer ihnen schadet, gilt als einer, der ein Heiligtum verletzt hat.', es: 'La cigüeña que va a la peregrinación: Según la creencia anatolia, las cigüeñas migran cada año hacia La Meca y regresan. Por ello se les llama "hacı leylek". Dañarlas es romper algo sagrado.', pt: 'A cegonha que vai à peregrinação: Segundo a crença anatólia, as cegonhas migram todos os anos rumo a Meca e regressam. Por isso se chamam "hacı leylek". Prejudicá-las é quebrar algo sagrado.', fr: 'La cigogne qui part en pèlerinage : Selon la croyance anatolienne, les cigognes migrent chaque année vers La Mecque et reviennent. C\'est pourquoi on les appelle "hacı leylek". Leur nuire, c\'est briser une chose sacrée.', ja: '巡礼に赴くコウノトリ：アナトリアの信仰によれば、コウノトリは毎年メッカの方角へ渡り、戻ってくる。ゆえに「ハジュ・レイレキ」と呼ばれる。彼らに害をなすことは聖なるものを損なうこととされる。' },
      { tr: 'Leyleğin Yuvası: Bir Anadolu hikâyesi: Bir köylü çatısındaki leylek yuvasını yıkar. O yıl yağmur yağmaz, mahsul kurur. Köylü yuvayı tekrar yapana kadar bereket dönmez.', en: 'The Stork\'s Nest: An Anatolian tale: a peasant destroys the stork\'s nest on his roof. That year no rain falls and the crop withers. Abundance does not return until the peasant rebuilds the nest.', de: 'Das Storchennest: Ein anatolisches Märchen: Ein Bauer zerstört das Storchennest auf seinem Dach. In jenem Jahr fällt kein Regen und die Ernte verdorrt. Der Überfluss kehrt erst zurück, als der Bauer das Nest wieder aufbaut.', es: 'El nido de la cigüeña: Un cuento anatolio: un campesino destruye el nido de cigüeña de su tejado. Ese año no cae lluvia y la cosecha se seca. La abundancia no regresa hasta que el campesino reconstruye el nido.', pt: 'O ninho da cegonha: Um conto anatólio: um camponês destrói o ninho de cegonha no seu telhado. Nesse ano não cai chuva e a colheita seca. A abundância não regressa até que o camponês reconstrua o ninho.', fr: 'Le nid de la cigogne : Un conte anatolien : un paysan détruit le nid de cigogne sur son toit. Cette année-là, il ne pleut pas et la récolte se dessèche. L\'abondance ne revient que lorsque le paysan reconstruit le nid.', ja: 'コウノトリの巣：あるアナトリアの物語——農夫が屋根のコウノトリの巣を壊す。その年は雨が降らず、作物は枯れる。農夫が巣を作り直すまで、豊穣は戻らない。' },
    ],
  },

  // ─── a035 Ördek ─────────────────────────────────────────────────────────
  a035: {
    jung: { tr: '"Akış İçinde Durulluk" arketipi. Ördek — suda yüzer, yağmurda ıslanmaz. Etrafından geçen kaosa karışmayan iç huzur.', en: 'The "Stillness Within Flow" archetype. The duck — swims on water, untouched by rain. The inner peace that does not mingle with the chaos passing through.', de: 'Der Archetyp der "Stille im Fluss". Die Ente — schwimmt auf dem Wasser, vom Regen unberührt. Der innere Frieden, der sich nicht mit dem vorüberziehenden Chaos vermischt.', es: 'El arquetipo de la "Quietud en el Flujo". El pato — nada en el agua, intacto bajo la lluvia. La paz interior que no se mezcla con el caos que pasa.', pt: 'O arquétipo da "Quietude no Fluxo". O pato — nada na água, intocado pela chuva. A paz interior que não se mistura com o caos que passa.', fr: 'L\'archétype de la "Quiétude dans le flux". Le canard — nage sur l\'eau, intact sous la pluie. La paix intérieure qui ne se mêle pas au chaos qui passe.', ja: '「流れの中の静けさ」の元型。カモ——水に浮かび、雨に濡れぬ。通り過ぎる混沌に染まらぬ内なる平安。' },
    dream: { tr: 'Ördek rüyada — duygusal akıştan etkilenmeden durabilmen gerektiğini söyler. Yüzüyorsa: huzur içinde ilerliyorsun. Uçuyorsa: bir döngüden çıkış zamanı.', en: 'Duck in dream — tells you that you must remain unaffected by emotional currents. Swimming: you are moving forward in peace. Flying: time to exit a cycle.', de: 'Ente im Traum — sagt dir, dass du von emotionalen Strömungen unberührt bleiben musst. Schwimmt sie: Du schreitest in Frieden voran. Fliegt sie: Zeit, einen Kreislauf zu verlassen.', es: 'Pato en sueños — te dice que debes permanecer intacto ante las corrientes emocionales. Si nada: avanzas en paz. Si vuela: tiempo de salir de un ciclo.', pt: 'Pato em sonho — diz-te que deves permanecer intocado pelas correntes emocionais. Se nada: avanças em paz. Se voa: tempo de sair de um ciclo.', fr: 'Canard en rêve — te dit que tu dois rester insensible aux courants émotionnels. Nageant : tu avances en paix. Volant : il est temps de sortir d\'un cycle.', ja: '夢の中のカモ——感情の流れに動じずにいられねばならぬと告げる。泳いでいるなら、あなたは安らぎのうちに進んでいる。飛んでいるなら、一つの循環から抜け出す時。' },
    shadow: { tr: 'Aşırı ayrılık. "Etkilenmemek" duyarsızlığa dönüşürse — ördek su kuşu olur ama "kalp" kalmaz.', en: 'Excessive detachment. If "not being affected" turns into insensitivity — the duck remains a water bird, but the heart is gone.', de: 'Übermäßige Abgelöstheit. Wenn "Unberührtsein" zu Gefühllosigkeit wird — bleibt die Ente ein Wasservogel, doch das "Herz" ist fort.', es: 'Desapego excesivo. Si "no afectarse" se vuelve insensibilidad — el pato sigue siendo ave acuática, pero el "corazón" se ha ido.', pt: 'Desapego excessivo. Se "não ser afetado" se torna insensibilidade — o pato permanece ave aquática, mas o "coração" desapareceu.', fr: 'Détachement excessif. Si "ne pas être affecté" devient insensibilité — le canard reste un oiseau d\'eau, mais le "cœur" a disparu.', ja: '過度の超然。「動じないこと」が無感覚に転じれば——カモは水鳥のままだが、「心」は失われる。' },
    whenAppears: { tr: 'Kaotik bir ortamda merkezde kalman gerekirken, başkalarının dramından çıkmak istediğinde, suyun seni temizlediği bir anda.', en: 'When you must stay centered in a chaotic environment, when you wish to exit another\'s drama, in a moment when water cleanses you.', de: 'Wenn du in einer chaotischen Umgebung zentriert bleiben musst, wenn du aus dem Drama eines anderen aussteigen willst, in einem Moment, in dem das Wasser dich reinigt.', es: 'Cuando debes mantenerte centrado en un entorno caótico, cuando deseas salir del drama ajeno, en un momento en que el agua te limpia.', pt: 'Quando deves manter-te centrado num ambiente caótico, quando desejas sair do drama alheio, num momento em que a água te limpa.', fr: 'Quand tu dois rester centré dans un environnement chaotique, quand tu souhaites sortir du drame d\'autrui, dans un instant où l\'eau te purifie.', ja: '混沌とした環境で中心を保たねばならぬとき、他人の劇から抜け出したいとき、水があなたを清める瞬間に。' },
    traditions: [
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Mandarin ördekleri — sadık eşler. Düğün hediyesi olarak çift verilir.', en: 'Mandarin ducks — faithful spouses. Given in pairs as wedding gifts.', de: 'Mandarinenten — treue Eheleute. Als Hochzeitsgeschenk paarweise gegeben.', es: 'Patos mandarines — esposos fieles. Se regalan en parejas como obsequio de boda.', pt: 'Patos-mandarim — cônjuges fiéis. Oferecidos aos pares como presente de casamento.', fr: 'Canards mandarins — époux fidèles. Offerts par paires comme cadeau de mariage.', ja: 'オシドリ——貞節な夫婦。婚礼の贈り物として一対で贈られる。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Su ile gök arasında köprü. Hem yüzer hem uçar — iki dünya hayvanı.', en: 'A bridge between water and sky. It swims and flies — a two-world animal.', de: 'Eine Brücke zwischen Wasser und Himmel. Sie schwimmt und fliegt — ein Tier zweier Welten.', es: 'Un puente entre el agua y el cielo. Nada y vuela — animal de dos mundos.', pt: 'Uma ponte entre a água e o céu. Nada e voa — animal de dois mundos.', fr: 'Un pont entre l\'eau et le ciel. Il nage et vole — animal de deux mondes.', ja: '水と空をつなぐ橋。泳ぎもし飛びもする——二つの世界の動物。' } },
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Akhenaten döneminde — basitliğin ve halkın hayvanı. Tapınak motiflerinde aile sahnesi.', en: 'In the Akhenaten period — the animal of simplicity and the people. A family scene in temple motifs.', de: 'In der Echnaton-Zeit — das Tier der Einfachheit und des Volkes. Eine Familienszene in Tempelmotiven.', es: 'En la época de Akenatón — el animal de la sencillez y del pueblo. Una escena familiar en los motivos de los templos.', pt: 'Na época de Akhenaton — o animal da simplicidade e do povo. Uma cena familiar nos motivos dos templos.', fr: 'À l\'époque d\'Akhénaton — l\'animal de la simplicité et du peuple. Une scène de famille dans les motifs des temples.', ja: 'アクエンアテンの時代において——素朴さと民衆の動物。神殿の文様における家族の情景。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Göl köylerinde rızkın simgesi. "Ördek bolsa, ev tok" deyişi.', en: 'In lakeside villages, the symbol of sustenance. The saying "where ducks are plenty, the home is fed".', de: 'In Seedörfern das Symbol des Auskommens. Das Sprichwort "wo Enten reichlich sind, ist das Haus satt".', es: 'En los pueblos lacustres, símbolo del sustento. El dicho "donde abundan los patos, la casa está saciada".', pt: 'Nas aldeias lacustres, símbolo do sustento. O ditado "onde há patos em abundância, a casa está farta".', fr: 'Dans les villages lacustres, le symbole de la subsistance. Le dicton "là où les canards abondent, la maison est rassasiée".', ja: '湖畔の村における糧の象徴。「カモが多ければ、家は満たされる」という言葉。' } },
      { culture: { tr: 'Slav', en: 'Slavic', de: 'Slawisch', es: 'Eslavo', pt: 'Eslavo', fr: 'Slave', ja: 'スラヴ' }, meaning: { tr: 'Yumurtasında dünyanın saklandığı kuş — yaratılışın annesi.', en: 'The bird whose egg conceals the world — the mother of creation.', de: 'Der Vogel, in dessen Ei sich die Welt verbirgt — die Mutter der Schöpfung.', es: 'El ave en cuyo huevo se oculta el mundo — la madre de la creación.', pt: 'A ave em cujo ovo se oculta o mundo — a mãe da criação.', fr: 'L\'oiseau dans l\'œuf duquel se cache le monde — la mère de la création.', ja: 'その卵に世界が隠された鳥——創造の母。' } },
    ],
    myths: [
      { tr: 'Mandarin Ördekleri: Çin geleneğinde mandarin ördekleri eşlerini ömür boyu değiştirmez. Eşi ölünce diğeri de bekler. Bu yüzden düğünlerde çift mandarin ördeği hediye edilir — sadakat duası.', en: 'Mandarin Ducks: In Chinese tradition, mandarin ducks never change partners. When one dies, the other waits. For this reason a pair of mandarin ducks is given at weddings — a prayer of faithfulness.', de: 'Mandarinenten: In der chinesischen Tradition wechseln Mandarinenten ihren Partner ein Leben lang nicht. Stirbt der eine, wartet der andere. Darum schenkt man bei Hochzeiten ein Paar Mandarinenten — ein Gebet der Treue.', es: 'Patos mandarines: En la tradición china, los patos mandarines no cambian de pareja en toda su vida. Cuando uno muere, el otro espera. Por eso en las bodas se regala una pareja de patos mandarines — una oración de fidelidad.', pt: 'Patos-mandarim: Na tradição chinesa, os patos-mandarim não mudam de par toda a vida. Quando um morre, o outro espera. Por isso nos casamentos se oferece um par de patos-mandarim — uma oração de fidelidade.', fr: 'Canards mandarins : Dans la tradition chinoise, les canards mandarins ne changent jamais de partenaire de toute leur vie. Quand l\'un meurt, l\'autre attend. C\'est pourquoi, aux mariages, on offre une paire de canards mandarins — une prière de fidélité.', ja: 'オシドリ：中国の伝統において、オシドリは生涯連れ合いを変えない。片方が死ねば、もう片方は待つ。ゆえに婚礼ではオシドリの一対を贈る——貞節の祈り。' },
      { tr: 'Slav Yaratılış Ördekleri: Slav mitolojisinde dünya, suların üstünde yüzen iki ördeğin yumurtaladığı sarı yumurtadan doğdu. Akış üstünde yaratım.', en: 'The Slavic Creation Ducks: In Slavic mythology, the world was born from the yellow egg laid by two ducks floating on the waters. Creation upon flow.', de: 'Die slawischen Schöpfungsenten: In der slawischen Mythologie wurde die Welt aus dem gelben Ei geboren, das zwei auf den Wassern treibende Enten legten. Schöpfung auf dem Fluss.', es: 'Los patos creadores eslavos: En la mitología eslava, el mundo nació del huevo amarillo puesto por dos patos que flotaban sobre las aguas. Creación sobre el flujo.', pt: 'Os patos criadores eslavos: Na mitologia eslava, o mundo nasceu do ovo amarelo posto por dois patos que flutuavam sobre as águas. Criação sobre o fluxo.', fr: 'Les canards créateurs slaves : Dans la mythologie slave, le monde naquit de l\'œuf jaune pondu par deux canards flottant sur les eaux. Création sur le flux.', ja: 'スラヴ創造のカモ：スラヴ神話において、世界は水上に浮かぶ二羽のカモが産んだ黄色い卵から生まれた。流れの上の創造。' },
    ],
  },

  // ─── a036 Kuzgun ────────────────────────────────────────────────────────
  a036: {
    jung: { tr: '"Trickster Bilge" arketipi. Kuzgun — kâhin ile soytarı bir bedende. Karanlığın zekası, ölümün haberi, ama aynı zamanda yaratıcılık.', en: 'The "Trickster Sage" archetype. The raven — seer and jester in one body. The intelligence of darkness, the news of death, yet also creativity.', de: 'Der Archetyp des "weisen Tricksters". Der Rabe — Seher und Narr in einem Leib. Die Intelligenz der Finsternis, die Botschaft des Todes, doch auch Schöpferkraft.', es: 'El arquetipo del "Sabio Embaucador". El cuervo — vidente y bufón en un mismo cuerpo. La inteligencia de la oscuridad, la noticia de la muerte, pero también la creatividad.', pt: 'O arquétipo do "Sábio Trapaceiro". O corvo — vidente e bobo num mesmo corpo. A inteligência da escuridão, a notícia da morte, mas também a criatividade.', fr: 'L\'archétype du "Sage filou". Le corbeau — voyant et bouffon dans un même corps. L\'intelligence des ténèbres, la nouvelle de la mort, mais aussi la créativité.', ja: '「賢きトリックスター」の元型。ワタリガラス——預言者と道化が一つの体に。闇の知性、死の報せ、だが同時に創造性。' },
    dream: { tr: 'Kuzgun rüyada — bir uyarı geliyor. Ya da: zekanı saklamayı bırak. Konuşuyorsa: gizli bir bilgi açılıyor.', en: 'Raven in dream — a warning is coming. Or: stop hiding your intelligence. Speaking: a hidden knowledge is opening.', de: 'Rabe im Traum — eine Warnung naht. Oder: Hör auf, deinen Verstand zu verbergen. Spricht er: Ein verborgenes Wissen öffnet sich.', es: 'Cuervo en sueños — viene una advertencia. O: deja de ocultar tu inteligencia. Si habla: un conocimiento oculto se abre.', pt: 'Corvo em sonho — vem um aviso. Ou: deixa de esconder a tua inteligência. Se fala: um conhecimento oculto abre-se.', fr: 'Corbeau en rêve — un avertissement arrive. Ou : cesse de cacher ton intelligence. S\'il parle : un savoir caché s\'ouvre.', ja: '夢の中のワタリガラス——警告が来ている。あるいは、知性を隠すのをやめよ。語るなら、隠された知が開かれていく。' },
    shadow: { tr: 'Kara mizah ve alaycılık. Kuzgun her şeyi bilir gibi davranırsa — siniklik. Her şeyin "boş" olduğunu söyleyen ses.', en: 'Black humor and mockery. If the raven acts as though it knows everything — cynicism. The voice saying that all is "empty".', de: 'Schwarzer Humor und Spott. Tut der Rabe, als wüsste er alles — Zynismus. Die Stimme, die sagt, alles sei "leer".', es: 'Humor negro y burla. Si el cuervo actúa como si lo supiera todo — cinismo. La voz que dice que todo está "vacío".', pt: 'Humor negro e zombaria. Se o corvo age como se soubesse tudo — cinismo. A voz que diz que tudo é "vazio".', fr: 'Humour noir et moquerie. Si le corbeau agit comme s\'il savait tout — cynisme. La voix qui dit que tout est "vide".', ja: '黒い諧謔と嘲り。ワタリガラスがすべてを知るかのように振る舞えば——シニシズム。すべては「虚しい」と言う声。' },
    whenAppears: { tr: 'Uyarı işaretlerini görmen gerekirken, zekanın kara mizahla beslendiği anlarda, ölüm-yas süreçlerinde rehber gibi.', en: 'When you must see the warning signs, in moments when intelligence is fed by dark humor, as a guide in death-grief processes.', de: 'Wenn du die Warnzeichen sehen musst, in Momenten, da der Verstand sich von schwarzem Humor nährt, als Führer in Trauerprozessen um den Tod.', es: 'Cuando debes ver las señales de advertencia, en momentos en que la inteligencia se nutre del humor negro, como guía en los procesos de duelo por la muerte.', pt: 'Quando deves ver os sinais de aviso, em momentos em que a inteligência se nutre do humor negro, como guia nos processos de luto pela morte.', fr: 'Quand tu dois voir les signes avant-coureurs, dans les moments où l\'intelligence se nourrit d\'humour noir, comme guide dans les processus de deuil de la mort.', ja: '警告の徴を見抜かねばならぬとき、知性が黒い諧謔に養われる瞬間、死と喪の過程における導き手として。' },
    traditions: [
      { culture: { tr: 'İskandinav', en: 'Norse', de: 'Nordisch', es: 'Nórdico', pt: 'Nórdico', fr: 'Nordique', ja: '北欧' }, meaning: { tr: 'Odin\'in iki kuzgunu Huginn (düşünce) ve Muninn (hafıza). Her gün dünyayı dolaşır, hanlarına bilgi getirir.', en: 'Odin\'s two ravens, Huginn (thought) and Muninn (memory). Every day they fly across the world and bring news back to their lord.', de: 'Odins zwei Raben Huginn (Gedanke) und Muninn (Gedächtnis). Jeden Tag fliegen sie über die Welt und bringen ihrem Herrn Nachricht.', es: 'Los dos cuervos de Odín, Hugin (pensamiento) y Munin (memoria). Cada día vuelan por el mundo y traen noticias a su señor.', pt: 'Os dois corvos de Odin, Hugin (pensamento) e Munin (memória). Todos os dias voam pelo mundo e trazem notícias ao seu senhor.', fr: 'Les deux corbeaux d\'Odin, Hugin (pensée) et Munin (mémoire). Chaque jour ils survolent le monde et rapportent des nouvelles à leur seigneur.', ja: 'オーディンの二羽のワタリガラス、フギン（思考）とムニン（記憶）。毎日世界を巡り、主に報せを持ち帰る。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Morrigan — savaş tanrıçası kuzgun formunda görünür. Ölüme yakın olanları işaretler.', en: 'The Morrigan — the war goddess appears in raven form. She marks those near to death.', de: 'Die Morrigan — die Kriegsgöttin erscheint in Rabengestalt. Sie zeichnet jene, die dem Tod nahe sind.', es: 'La Morrigan — la diosa de la guerra aparece en forma de cuervo. Marca a los que están cerca de la muerte.', pt: 'A Morrigan — a deusa da guerra aparece em forma de corvo. Marca os que estão perto da morte.', fr: 'La Morrigan — la déesse de la guerre apparaît sous forme de corbeau. Elle marque ceux qui sont proches de la mort.', ja: 'モリガン——戦の女神はワタリガラスの姿で現れる。死の近い者に印をつける。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Haida ve Tlingit geleneğinde — yaratıcı trickster. Güneşi çalan, dünyayı şekillendiren.', en: 'In Haida and Tlingit tradition — the creative trickster. The one who stole the sun and shaped the world.', de: 'In der Tradition der Haida und Tlingit — der schöpferische Trickster. Der, der die Sonne stahl und die Welt formte.', es: 'En la tradición haida y tlingit — el embaucador creador. El que robó el sol y dio forma al mundo.', pt: 'Na tradição haida e tlingit — o trapaceiro criador. Aquele que roubou o sol e moldou o mundo.', fr: 'Dans la tradition haïda et tlingit — le filou créateur. Celui qui vola le soleil et façonna le monde.', ja: 'ハイダとトリンギットの伝統において——創造するトリックスター。太陽を盗み、世界を形づくった者。' } },
      { culture: { tr: 'Türk-Moğol', en: 'Turco-Mongol', de: 'Türkisch-Mongolisch', es: 'Turco-Mongol', pt: 'Turco-Mongol', fr: 'Turco-Mongol', ja: 'テュルク・モンゴル' }, meaning: { tr: 'Karakuş — şamanın yardımcısı. Atalardan haber getiren kara haberci.', en: 'Karakuş — the shaman\'s helper. The dark messenger who brings word from the ancestors.', de: 'Karakuş — der Helfer des Schamanen. Der dunkle Bote, der Nachricht von den Ahnen bringt.', es: 'Karakuş — el ayudante del chamán. El mensajero oscuro que trae noticias de los antepasados.', pt: 'Karakuş — o ajudante do xamã. O mensageiro escuro que traz notícias dos antepassados.', fr: 'Karakuş — l\'aide du chamane. Le messager sombre qui apporte des nouvelles des ancêtres.', ja: 'カラクシュ——シャーマンの助け手。先祖からの報せを運ぶ黒き使者。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Nuh\'un gemisinden ilk salınan kuş — geri dönmemiş. Sadakatsizliğin simgesi olarak yorumlanmış, ama bağımsızlık olarak da.', en: 'The first bird released from Noah\'s ark — it did not return. Interpreted as a symbol of disloyalty, yet also of independence.', de: 'Der erste Vogel, der aus Noahs Arche entlassen wurde — er kehrte nicht zurück. Gedeutet als Symbol der Untreue, doch auch der Unabhängigkeit.', es: 'La primera ave soltada del arca de Noé — no regresó. Interpretada como símbolo de deslealtad, pero también de independencia.', pt: 'A primeira ave solta da arca de Noé — não regressou. Interpretada como símbolo de deslealdade, mas também de independência.', fr: 'Le premier oiseau relâché de l\'arche de Noé — il ne revint pas. Interprété comme symbole de déloyauté, mais aussi d\'indépendance.', ja: 'ノアの箱舟から最初に放たれた鳥——戻ってこなかった。不忠の象徴と解されるが、独立の象徴とも。' } },
    ],
    myths: [
      { tr: 'Odin\'in Kuzgunları: İskandinav baş tanrı Odin\'in omuzlarında iki kuzgun durur — Huginn (düşünce) ve Muninn (hafıza). Her gün dünyayı dolaşır, akşam Odin\'in kulağına haber fısıldarlar. Bilgelik — gözlemleyebilmektir.', en: 'Odin\'s Ravens: Two ravens perch on the shoulders of the Norse high god Odin — Huginn (thought) and Muninn (memory). Each day they roam the world and at evening whisper news in Odin\'s ear. Wisdom is the capacity to observe.', de: 'Odins Raben: Auf den Schultern des nordischen Hochgottes Odin sitzen zwei Raben — Huginn (Gedanke) und Muninn (Gedächtnis). Jeden Tag durchstreifen sie die Welt und flüstern am Abend Odin Nachricht ins Ohr. Weisheit ist die Fähigkeit zu beobachten.', es: 'Los cuervos de Odín: Sobre los hombros del dios supremo nórdico Odín se posan dos cuervos — Hugin (pensamiento) y Munin (memoria). Cada día recorren el mundo y al anochecer susurran noticias al oído de Odín. La sabiduría es la capacidad de observar.', pt: 'Os corvos de Odin: Nos ombros do deus supremo nórdico Odin pousam dois corvos — Hugin (pensamento) e Munin (memória). Todos os dias percorrem o mundo e ao anoitecer sussurram notícias ao ouvido de Odin. A sabedoria é a capacidade de observar.', fr: 'Les corbeaux d\'Odin : Sur les épaules du dieu suprême nordique Odin se posent deux corbeaux — Hugin (pensée) et Munin (mémoire). Chaque jour ils parcourent le monde et le soir murmurent des nouvelles à l\'oreille d\'Odin. La sagesse est la capacité d\'observer.', ja: 'オーディンのワタリガラス：北欧の主神オーディンの肩に二羽のワタリガラスが止まる——フギン（思考）とムニン（記憶）。毎日世界を巡り、夕べにオーディンの耳に報せをささやく。知恵とは観察しうる力。' },
      { tr: 'Haida Kuzgunu: Haida mitolojisinde kuzgun, kutucu tanrıdan güneşi, ayı ve yıldızları çalar ve dünyaya dağıtır. Yaratıcı hilebaz — kuralı bozarak hayatı veren.', en: 'The Haida Raven: In Haida mythology, the raven steals the sun, moon, and stars from the hoarder-god and distributes them to the world. The creative trickster — the one who gives life by breaking the rule.', de: 'Der Haida-Rabe: In der Mythologie der Haida stiehlt der Rabe dem hortenden Gott Sonne, Mond und Sterne und verteilt sie über die Welt. Der schöpferische Trickster — der, der Leben gibt, indem er die Regel bricht.', es: 'El cuervo haida: En la mitología haida, el cuervo roba el sol, la luna y las estrellas al dios acaparador y los reparte por el mundo. El embaucador creador — el que da vida rompiendo la regla.', pt: 'O corvo haida: Na mitologia haida, o corvo rouba o sol, a lua e as estrelas ao deus avarento e distribui-os pelo mundo. O trapaceiro criador — aquele que dá vida quebrando a regra.', fr: 'Le corbeau haïda : Dans la mythologie haïda, le corbeau vole le soleil, la lune et les étoiles au dieu thésauriseur et les répand dans le monde. Le filou créateur — celui qui donne la vie en brisant la règle.', ja: 'ハイダのワタリガラス：ハイダ神話において、ワタリガラスは溜め込む神から太陽、月、星を盗み、世界へ撒く。創造するトリックスター——掟を破ることで命を与える者。' },
    ],
  },

  // ─── a037 Ak Kelebek ────────────────────────────────────────────────────
  a037: {
    jung: { tr: '"Saf Ruh" arketipi. Ak kelebek — kelebeklerin en hassas, en geçici formu. Ruhun beyaz ışığı.', en: 'The "Pure Soul" archetype. The white butterfly — the most delicate, most fleeting form of butterflies. The white light of the soul.', de: 'Der Archetyp der "reinen Seele". Der weiße Schmetterling — die zarteste, flüchtigste Gestalt der Schmetterlinge. Das weiße Licht der Seele.', es: 'El arquetipo del "Alma Pura". La mariposa blanca — la forma más delicada, más fugaz de las mariposas. La luz blanca del alma.', pt: 'O arquétipo da "Alma Pura". A borboleta branca — a forma mais delicada, mais fugaz das borboletas. A luz branca da alma.', fr: 'L\'archétype de l\'"Âme pure". Le papillon blanc — la forme la plus délicate, la plus fugace des papillons. La lumière blanche de l\'âme.', ja: '「清らかな魂」の元型。白い蝶——蝶の中で最も繊細で、最もはかない姿。魂の白い光。' },
    dream: { tr: 'Ak kelebek rüyada — bir saflık, bir aydınlık geri geliyor. Ölmüş yakının ruhu, ya da çocuksu özün ziyareti.', en: 'White butterfly in dream — a purity, a clarity is returning. The soul of a deceased loved one, or a visit from your childlike essence.', de: 'Weißer Schmetterling im Traum — eine Reinheit, eine Klarheit kehrt zurück. Die Seele eines verstorbenen Angehörigen oder ein Besuch deines kindlichen Wesens.', es: 'Mariposa blanca en sueños — una pureza, una claridad regresa. El alma de un ser querido difunto, o una visita de tu esencia infantil.', pt: 'Borboleta branca em sonho — uma pureza, uma clareza regressa. A alma de um ente querido falecido, ou uma visita da tua essência infantil.', fr: 'Papillon blanc en rêve — une pureté, une clarté revient. L\'âme d\'un proche défunt, ou une visite de ton essence d\'enfant.', ja: '夢の中の白い蝶——清らかさ、明るさが戻ってくる。亡くなった近しい者の魂、あるいは幼子のような本質の訪れ。' },
    shadow: { tr: 'Aşırı maneviyat — bedeni inkâr. Ak kelebek hep "yüksek titreşim"de yaşamaya çalışırsa, dünya işlerini ihmal eder.', en: 'Excessive spirituality — denial of the body. If the white butterfly tries to live always at "high vibration", it neglects worldly matters.', de: 'Übermäßige Spiritualität — Verleugnung des Körpers. Versucht der weiße Schmetterling stets in "hoher Schwingung" zu leben, vernachlässigt er die weltlichen Dinge.', es: 'Espiritualidad excesiva — negación del cuerpo. Si la mariposa blanca trata de vivir siempre en "alta vibración", descuida los asuntos del mundo.', pt: 'Espiritualidade excessiva — negação do corpo. Se a borboleta branca tenta viver sempre em "alta vibração", negligencia os assuntos do mundo.', fr: 'Spiritualité excessive — déni du corps. Si le papillon blanc tente de vivre toujours en "haute vibration", il néglige les affaires du monde.', ja: '過度の霊性——肉体の否定。白い蝶が常に「高い波動」で生きようとすれば、現世のことを顧みなくなる。' },
    whenAppears: { tr: 'Bir hafızanın berraklaştığı anda, atalarınla bağlantı kurmak istediğinde, çocuksu temiz neşeyi geri istediğin günlerde.', en: 'At the moment a memory clarifies, when you wish to connect with your ancestors, in the days you want your pure childlike joy back.', de: 'In dem Moment, in dem eine Erinnerung sich klärt, wenn du dich mit deinen Ahnen verbinden willst, an den Tagen, an denen du deine reine kindliche Freude zurückwillst.', es: 'En el momento en que un recuerdo se aclara, cuando deseas conectar con tus antepasados, en los días en que quieres recuperar tu pura alegría infantil.', pt: 'No momento em que uma memória se clarifica, quando desejas ligar-te aos teus antepassados, nos dias em que queres recuperar a tua pura alegria infantil.', fr: 'À l\'instant où un souvenir s\'éclaircit, quand tu souhaites te relier à tes ancêtres, aux jours où tu veux retrouver ta pure joie d\'enfant.', ja: 'ある記憶が明らかになる瞬間に、先祖とつながりたいとき、幼子のような清らかな歓びを取り戻したい日々に。' },
    traditions: [
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: '"Ak kelebek atadan haber" — yas evine giren ak kelebek, gidenden mesaj.', en: '"The white butterfly is news from the ancestor" — a white butterfly entering a house in mourning is a message from the departed.', de: '"Der weiße Schmetterling ist Nachricht vom Ahnen" — ein weißer Schmetterling, der ein Trauerhaus betritt, ist eine Botschaft des Verstorbenen.', es: '"La mariposa blanca es noticia del antepasado" — una mariposa blanca que entra en una casa de luto es un mensaje del difunto.', pt: '"A borboleta branca é notícia do antepassado" — uma borboleta branca que entra numa casa de luto é uma mensagem do falecido.', fr: '"Le papillon blanc est nouvelle de l\'ancêtre" — un papillon blanc qui entre dans une maison en deuil est un message du défunt.', ja: '「白い蝶は祖先からの報せ」——喪中の家に入る白い蝶は、逝った者からのことづて。' } },
      { culture: { tr: 'Japonya', en: 'Japanese', de: 'Japanisch', es: 'Japonés', pt: 'Japonês', fr: 'Japonais', ja: '日本' }, meaning: { tr: 'Hakuchō — ölmüş kişinin ruhunun ziyareti. Aile yıldönümlerinde gelir.', en: 'Hakuchō — the visit of a deceased person\'s soul. It comes on family anniversaries.', de: 'Hakuchō — der Besuch der Seele eines Verstorbenen. Er kommt zu Familiengedenktagen.', es: 'Hakuchō — la visita del alma de un difunto. Llega en los aniversarios familiares.', pt: 'Hakuchō — a visita da alma de um falecido. Vem nos aniversários familiares.', fr: 'Hakuchō — la visite de l\'âme d\'un défunt. Il vient aux anniversaires familiaux.', ja: '白蝶（はくちょう）——亡くなった人の魂の訪れ。家族の命日に現れる。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Ölmüş çocukların ruhu beyaz kelebek formunda dönermiş. Anneye teselli.', en: 'The souls of deceased children were said to return in the form of white butterflies. A consolation to the mother.', de: 'Die Seelen verstorbener Kinder sollen in Gestalt weißer Schmetterlinge zurückkehren. Ein Trost für die Mutter.', es: 'Se decía que las almas de los niños difuntos regresaban en forma de mariposas blancas. Un consuelo para la madre.', pt: 'Dizia-se que as almas das crianças falecidas regressavam em forma de borboletas brancas. Um consolo para a mãe.', fr: 'On disait que les âmes des enfants défunts revenaient sous forme de papillons blancs. Une consolation pour la mère.', ja: '亡くなった子の魂は白い蝶の姿で帰るとされた。母への慰め。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Diriliş sembolü. Mezar taşlarında işlenir — ruhun bedeni terk edip yükselişi.', en: 'Symbol of resurrection. Carved on tombstones — the soul leaving the body to ascend.', de: 'Symbol der Auferstehung. Auf Grabsteine gemeißelt — die Seele, die den Leib verlässt, um aufzusteigen.', es: 'Símbolo de la resurrección. Tallada en lápidas — el alma que deja el cuerpo para ascender.', pt: 'Símbolo da ressurreição. Esculpida em lápides — a alma que deixa o corpo para ascender.', fr: 'Symbole de la résurrection. Gravé sur les pierres tombales — l\'âme qui quitte le corps pour s\'élever.', ja: '復活の象徴。墓石に刻まれる——肉体を離れて昇る魂。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Saf aşkın simgesi. Sevdiğine söz vermenin işareti.', en: 'Symbol of pure love. The sign of pledging oneself to the beloved.', de: 'Symbol der reinen Liebe. Das Zeichen, sich der Geliebten zu versprechen.', es: 'Símbolo del amor puro. La señal de comprometerse con el amado.', pt: 'Símbolo do amor puro. O sinal de se prometer ao amado.', fr: 'Symbole de l\'amour pur. Le signe de se promettre à l\'aimé.', ja: '清らかな愛の象徴。愛する者に誓いを立てる徴。' } },
    ],
    myths: [
      { tr: 'Atadan Haber: Anadolu\'da ölmüş bir yakının yas haftalarında eve giren ak kelebek, onun ruhunun ziyareti sayılır. "Hoş geldin" denir, kovulmaz. Kelebek çıkana kadar dua edilir.', en: 'Word from the Ancestor: In Anatolia, a white butterfly entering the home during the mourning weeks of a deceased loved one is considered a visit from their soul. It is greeted with "welcome" and not driven away. Prayers are offered until the butterfly leaves.', de: 'Nachricht vom Ahnen: In Anatolien gilt ein weißer Schmetterling, der in den Trauerwochen eines Verstorbenen das Haus betritt, als Besuch seiner Seele. Man heißt ihn "willkommen" und vertreibt ihn nicht. Es wird gebetet, bis der Schmetterling geht.', es: 'Noticia del antepasado: En Anatolia, una mariposa blanca que entra en la casa durante las semanas de luto de un ser querido difunto se considera una visita de su alma. Se le da la "bienvenida" y no se la espanta. Se reza hasta que la mariposa se va.', pt: 'Notícia do antepassado: Na Anatólia, uma borboleta branca que entra em casa durante as semanas de luto de um ente querido falecido é considerada uma visita da sua alma. É saudada com "bem-vinda" e não é enxotada. Reza-se até a borboleta partir.', fr: 'Nouvelle de l\'ancêtre : En Anatolie, un papillon blanc qui entre dans la maison pendant les semaines de deuil d\'un proche défunt est tenu pour une visite de son âme. On lui dit "bienvenue" et on ne le chasse pas. On prie jusqu\'à ce que le papillon s\'en aille.', ja: '祖先からの報せ：アナトリアでは、亡くなった近しい者の喪の数週間に家に入る白い蝶は、その魂の訪れとされる。「ようこそ」と迎えられ、追い払われない。蝶が去るまで祈りが捧げられる。' },
      { tr: 'Hakuchō Geleneği: Japon ailelerinde ölüm yıldönümlerinde evin etrafında dolaşan beyaz kelebekler, atayı temsil eder. Tütsü yakılır, isim anılır — kelebek gelmeden gidemez.', en: 'The Hakuchō Tradition: In Japanese families, white butterflies circling the home on death anniversaries represent the ancestor. Incense is lit, the name is spoken — the butterfly cannot depart until it has come.', de: 'Die Hakuchō-Tradition: In japanischen Familien stehen weiße Schmetterlinge, die an Todestagen ums Haus kreisen, für den Ahnen. Räucherwerk wird entzündet, der Name genannt — der Schmetterling kann nicht gehen, ehe er gekommen ist.', es: 'La tradición Hakuchō: En las familias japonesas, las mariposas blancas que rodean la casa en los aniversarios de muerte representan al antepasado. Se enciende incienso, se pronuncia el nombre — la mariposa no puede partir hasta haber venido.', pt: 'A tradição Hakuchō: Nas famílias japonesas, as borboletas brancas que rodeiam a casa nos aniversários de morte representam o antepassado. Acende-se incenso, pronuncia-se o nome — a borboleta não pode partir antes de ter vindo.', fr: 'La tradition Hakuchō : Dans les familles japonaises, les papillons blancs qui tournent autour de la maison aux anniversaires de décès représentent l\'ancêtre. On allume de l\'encens, on prononce le nom — le papillon ne peut repartir avant d\'être venu.', ja: '白蝶の風習：日本の家庭では、命日に家のまわりを舞う白い蝶が祖先を表す。香が焚かれ、名が唱えられる——蝶は訪れずには去れない。' },
    ],
  },

  // ─── a038 Deve ──────────────────────────────────────────────────────────
  a038: {
    jung: { tr: '"Çöl Yolcusu" arketipi. Deve — uzun yola dayanıklılık, kurak dönemleri içsel kaynakla geçme.', en: 'The "Desert Wayfarer" archetype. The camel — endurance on the long road, traversing dry seasons by inner resource.', de: 'Der Archetyp des "Wüstenwanderers". Das Kamel — Ausdauer auf dem langen Weg, das Durchqueren dürrer Zeiten aus innerer Ressource.', es: 'El arquetipo del "Caminante del Desierto". El camello — resistencia en el largo camino, atravesar las estaciones secas con recurso interior.', pt: 'O arquétipo do "Andarilho do Deserto". O camelo — resistência no longo caminho, atravessar as estações secas com recurso interior.', fr: 'L\'archétype du "Marcheur du désert". Le chameau — endurance sur le long chemin, traverser les saisons sèches par la ressource intérieure.', ja: '「砂漠の旅人」の元型。ラクダ——長き道での耐久力、渇いた季節を内なる蓄えで渡ること。' },
    dream: { tr: 'Deve rüyada — uzun bir dayanıklılık testi var. Yük taşıyorsa: sorumluluk artıyor. Çölde yürüyorsa: ruhsal kuraklıkta da yolunu bulacaksın.', en: 'Camel in dream — a long test of endurance lies ahead. Bearing a load: responsibility is growing. Walking in the desert: you will find your way even through spiritual drought.', de: 'Kamel im Traum — eine lange Prüfung der Ausdauer liegt vor dir. Trägt es eine Last: Die Verantwortung wächst. Wandert es durch die Wüste: Du wirst deinen Weg auch durch geistige Dürre finden.', es: 'Camello en sueños — te espera una larga prueba de resistencia. Si lleva carga: la responsabilidad crece. Si camina por el desierto: hallarás tu camino aun en la sequía espiritual.', pt: 'Camelo em sonho — uma longa prova de resistência está à tua frente. Se carrega um fardo: a responsabilidade cresce. Se caminha no deserto: encontrarás o teu caminho mesmo na seca espiritual.', fr: 'Chameau en rêve — une longue épreuve d\'endurance t\'attend. Portant une charge : la responsabilité grandit. Marchant dans le désert : tu trouveras ta voie même dans la sécheresse spirituelle.', ja: '夢の中のラクダ——長い耐久の試練が待っている。荷を負うなら、責任が増している。砂漠を歩むなら、霊的な渇きの中でも道を見いだすだろう。' },
    shadow: { tr: 'Her yükü taşıma takıntısı. Deve "hayır" demeyi bilmeli — sınırsız fedakârlık çöküştür.', en: 'The compulsion to carry every burden. The camel must know how to say "no" — limitless sacrifice is collapse.', de: 'Der Zwang, jede Last zu tragen. Das Kamel muss "nein" zu sagen wissen — grenzenlose Aufopferung ist Zusammenbruch.', es: 'La compulsión de cargar con todo peso. El camello debe saber decir "no" — el sacrificio sin límites es colapso.', pt: 'A compulsão de carregar todo o fardo. O camelo deve saber dizer "não" — o sacrifício sem limites é colapso.', fr: 'La compulsion de porter chaque fardeau. Le chameau doit savoir dire "non" — le sacrifice sans limites est effondrement.', ja: 'あらゆる荷を背負おうとする強迫。ラクダは「否」と言うことを知らねばならない——際限なき犠牲は崩壊である。' },
    whenAppears: { tr: 'Uzun süreli bir yüke girerken, kıt kaynakla dayanman gerektiğinde, ruhsal çölde içsel kaynakları bulman lazımken.', en: 'When taking on a long-lasting burden, when you must endure with scarce resources, when you must find inner reserves in the spiritual desert.', de: 'Wenn du eine langanhaltende Last übernimmst, wenn du mit knappen Mitteln durchhalten musst, wenn du in der geistigen Wüste innere Reserven finden musst.', es: 'Al asumir una carga duradera, cuando debes resistir con recursos escasos, cuando debes hallar reservas interiores en el desierto espiritual.', pt: 'Ao assumir um fardo duradouro, quando deves resistir com recursos escassos, quando deves encontrar reservas interiores no deserto espiritual.', fr: 'En assumant un fardeau durable, quand tu dois tenir avec de maigres ressources, quand tu dois trouver des réserves intérieures dans le désert spirituel.', ja: '長く続く荷を引き受けるとき、乏しい蓄えで耐えねばならぬとき、霊的な砂漠で内なる蓄えを見いださねばならぬときに。' },
    traditions: [
      { culture: { tr: 'Arap-İslam', en: 'Arab-Islamic', de: 'Arabisch-Islamisch', es: 'Árabe-Islámico', pt: 'Árabe-Islâmico', fr: 'Arabo-Islamique', ja: 'アラブ・イスラーム' }, meaning: { tr: 'Hz. Salih\'in mucize devesi — Kuran\'da Naka. Kavmin sınanması; deveyi öldüren toplum cezalandırılır.', en: 'The miracle she-camel of the prophet Salih — Naqah in the Qur\'an. The trial of his people; the community that slays the camel is punished.', de: 'Das Wunderkamel des Propheten Salih — Naqah im Koran. Die Prüfung seines Volkes; die Gemeinschaft, die das Kamel tötet, wird bestraft.', es: 'La camella milagrosa del profeta Salih — Naqah en el Corán. La prueba de su pueblo; la comunidad que mata a la camella es castigada.', pt: 'A camela milagrosa do profeta Salih — Naqah no Alcorão. A prova do seu povo; a comunidade que mata a camela é castigada.', fr: 'La chamelle miraculeuse du prophète Salih — Naqah dans le Coran. L\'épreuve de son peuple ; la communauté qui tue la chamelle est punie.', ja: '預言者サーリフの奇跡の雌ラクダ——クルアーンにおけるナーカ。民の試練——ラクダを殺した共同体は罰せられる。' } },
      { culture: { tr: 'Sufi', en: 'Sufi', de: 'Sufisch', es: 'Sufí', pt: 'Sufi', fr: 'Soufi', ja: 'スーフィー' }, meaning: { tr: 'Mevlana\'nın Mesnevi\'sinde — sabır ve teslimiyetin sembolü.', en: 'In Rumi\'s Masnavi — symbol of patience and surrender.', de: 'In Rumis Masnavi — Symbol der Geduld und Hingabe.', es: 'En el Masnavi de Rumi — símbolo de la paciencia y la entrega.', pt: 'No Masnavi de Rumi — símbolo da paciência e da entrega.', fr: 'Dans le Masnavi de Rûmî — symbole de la patience et de l\'abandon.', ja: 'ルーミーの『マスナヴィー』において——忍耐と委ねの象徴。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Yörük kültüründe yaşam hattının kendisi. Deve kervansız Anadolu olmaz.', en: 'In Yörük culture, the very line of life. Anatolia is unthinkable without the camel caravan.', de: 'In der Yörük-Kultur die Lebensader selbst. Anatolien ist ohne die Kamelkarawane undenkbar.', es: 'En la cultura yörük, la línea misma de la vida. Anatolia es impensable sin la caravana de camellos.', pt: 'Na cultura yörük, a própria linha da vida. A Anatólia é impensável sem a caravana de camelos.', fr: 'Dans la culture yörük, la ligne de vie elle-même. L\'Anatolie est impensable sans la caravane de chameaux.', ja: 'ユリュク（遊牧民）の文化において、生命線そのもの。ラクダの隊商なくしてアナトリアはありえない。' } },
      { culture: { tr: 'İbrahimi', en: 'Abrahamic', de: 'Abrahamitisch', es: 'Abrahámico', pt: 'Abraâmico', fr: 'Abrahamique', ja: 'アブラハム諸宗教' }, meaning: { tr: 'İbrahim\'in deve kervanı — peygamberlerin yolunun bineği.', en: 'Abraham\'s camel caravan — the mount of the prophets\' way.', de: 'Abrahams Kamelkarawane — das Reittier des Weges der Propheten.', es: 'La caravana de camellos de Abraham — la montura del camino de los profetas.', pt: 'A caravana de camelos de Abraão — a montaria do caminho dos profetas.', fr: 'La caravane de chameaux d\'Abraham — la monture de la voie des prophètes.', ja: 'アブラハムのラクダの隊商——預言者たちの道の乗り物。' } },
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Çölün kapısı — yaşam ve ölüm arasında köprü.', en: 'The gate of the desert — bridge between life and death.', de: 'Das Tor der Wüste — Brücke zwischen Leben und Tod.', es: 'La puerta del desierto — puente entre la vida y la muerte.', pt: 'O portão do deserto — ponte entre a vida e a morte.', fr: 'La porte du désert — pont entre la vie et la mort.', ja: '砂漠の門——生と死をつなぐ橋。' } },
    ],
    myths: [
      { tr: 'Salih\'in Devesi: Kuran\'da Hz. Salih\'in kavmine mucize olarak bir deve verilir. Onu öldürmemeleri ve suyu paylaşmaları istenir. Kavim deveyi öldürür — kavim helak olur. Kutsal yüke saygı testi.', en: 'Salih\'s She-Camel: In the Qur\'an, a she-camel is given as a miracle to the people of the prophet Salih. They are commanded not to slay her and to share the water. The people kill the camel — the people are destroyed. A test of respect for the sacred burden.', de: 'Salihs Kamelstute: Im Koran wird dem Volk des Propheten Salih als Wunder eine Kamelstute gegeben. Sie sollen sie nicht töten und das Wasser teilen. Das Volk tötet das Kamel — das Volk wird vernichtet. Eine Prüfung der Achtung vor der heiligen Last.', es: 'La camella de Salih: En el Corán, se da una camella como milagro al pueblo del profeta Salih. Se les ordena no matarla y compartir el agua. El pueblo mata a la camella — el pueblo es destruido. Una prueba de respeto a la carga sagrada.', pt: 'A camela de Salih: No Alcorão, é dada uma camela como milagre ao povo do profeta Salih. É-lhes ordenado que não a matem e que partilhem a água. O povo mata a camela — o povo é destruído. Uma prova de respeito pelo fardo sagrado.', fr: 'La chamelle de Salih : Dans le Coran, une chamelle est donnée en miracle au peuple du prophète Salih. Il leur est ordonné de ne pas la tuer et de partager l\'eau. Le peuple tue la chamelle — le peuple est anéanti. Une épreuve de respect du fardeau sacré.', ja: 'サーリフの雌ラクダ：クルアーンにおいて、預言者サーリフの民に奇跡として一頭の雌ラクダが与えられる。殺さず、水を分かち合うよう命じられる。民はラクダを殺す——民は滅ぼされる。聖なる荷への敬意の試練。' },
      { tr: 'Yörük Devesi: Anadolu Yörüklerinde deve sadece bir hayvan değil, ailenin parçasıdır. İsim verilir, yas tutulur. Devesini kaybeden ev, evladını kaybetmiş kabul edilir.', en: 'The Yörük Camel: Among Anatolian Yörüks, the camel is not merely an animal but part of the family. It is named, mourned. A household that loses its camel is held to have lost a child.', de: 'Das Yörük-Kamel: Bei den anatolischen Yörük ist das Kamel nicht bloß ein Tier, sondern Teil der Familie. Es bekommt einen Namen, wird betrauert. Ein Haushalt, der sein Kamel verliert, gilt als einer, der ein Kind verlor.', es: 'El camello yörük: Entre los yörüks anatolios, el camello no es solo un animal sino parte de la familia. Se le da nombre, se le llora. Una casa que pierde su camello se considera que ha perdido a un hijo.', pt: 'O camelo yörük: Entre os yörüks anatólios, o camelo não é apenas um animal mas parte da família. Recebe um nome, é chorado. Uma casa que perde o seu camelo é tida como tendo perdido um filho.', fr: 'Le chameau yörük : Chez les Yörüks anatoliens, le chameau n\'est pas qu\'un animal mais un membre de la famille. On lui donne un nom, on le pleure. Un foyer qui perd son chameau est tenu pour avoir perdu un enfant.', ja: 'ユリュクのラクダ：アナトリアのユリュクにおいて、ラクダは単なる動物ではなく家族の一員。名を与えられ、悼まれる。ラクダを失った家は、わが子を失ったとみなされる。' },
    ],
  },

  // ─── a039 Balık ─────────────────────────────────────────────────────────
  a039: {
    jung: { tr: '"Bilinçaltı Akış" arketipi. Balık — suyun derinindeki bilgelik. Sezgi, doğurganlık, geçişlerin habercisi.', en: 'The "Unconscious Flow" archetype. The fish — the wisdom in the depths of water. Intuition, fertility, herald of transitions.', de: 'Der Archetyp des "unbewussten Flusses". Der Fisch — die Weisheit in der Tiefe des Wassers. Intuition, Fruchtbarkeit, Herold der Übergänge.', es: 'El arquetipo del "Flujo Inconsciente". El pez — la sabiduría en las profundidades del agua. Intuición, fertilidad, heraldo de las transiciones.', pt: 'O arquétipo do "Fluxo Inconsciente". O peixe — a sabedoria nas profundezas da água. Intuição, fertilidade, arauto das transições.', fr: 'L\'archétype du "Flux inconscient". Le poisson — la sagesse dans les profondeurs de l\'eau. Intuition, fertilité, héraut des transitions.', ja: '「無意識の流れ」の元型。魚——水の深みの知恵。直感、豊穣、移り変わりの使者。' },
    dream: { tr: 'Balık rüyada — derin bir bilgi yüzeye çıkıyor. Çok balık görüyorsan: bolluk yakın. Yakalıyorsan: bir hakikati avlıyorsun.', en: 'Fish in dream — a deep knowledge is surfacing. Seeing many fish: abundance is near. Catching them: you are hunting a truth.', de: 'Fisch im Traum — ein tiefes Wissen steigt an die Oberfläche. Siehst du viele Fische: Überfluss ist nah. Fängst du sie: Du jagst eine Wahrheit.', es: 'Pez en sueños — un conocimiento profundo aflora. Si ves muchos peces: la abundancia está cerca. Si los pescas: cazas una verdad.', pt: 'Peixe em sonho — um conhecimento profundo aflora. Se vês muitos peixes: a abundância está perto. Se os pescas: caças uma verdade.', fr: 'Poisson en rêve — un savoir profond remonte à la surface. Voyant beaucoup de poissons : l\'abondance est proche. Les attrapant : tu chasses une vérité.', ja: '夢の中の魚——深い知が水面へ浮かび上がる。多くの魚を見るなら、豊穣が近い。捕らえるなら、あなたは一つの真理を狩っている。' },
    shadow: { tr: 'Soğukluk, kayganlık. Balık tutulmaz — sezginin bedeni yok olur, eline geçmez.', en: 'Coldness, slipperiness. The fish cannot be held — intuition has no body, never quite reaches your hand.', de: 'Kälte, Glätte. Der Fisch lässt sich nicht halten — die Intuition hat keinen Leib, gelangt nie ganz in deine Hand.', es: 'Frialdad, resbalosidad. El pez no puede sujetarse — la intuición no tiene cuerpo, nunca llega del todo a tu mano.', pt: 'Frieza, escorregadia. O peixe não se segura — a intuição não tem corpo, nunca chega de todo à tua mão.', fr: 'Froideur, glissance. Le poisson ne se retient pas — l\'intuition n\'a pas de corps, n\'atteint jamais tout à fait ta main.', ja: '冷たさ、つかみどころのなさ。魚は捕まえられない——直感には体がなく、決して手には収まらない。' },
    whenAppears: { tr: 'Hamilelik (gerçek/yaratıcı), sezginin keskinleştiği, dünyanın altında bir akıntının seni taşıdığı anda.', en: 'In pregnancy (literal/creative), when intuition sharpens, at the moment an underground current is carrying you.', de: 'In der Schwangerschaft (buchstäblich/schöpferisch), wenn die Intuition sich schärft, in dem Moment, in dem eine unterirdische Strömung dich trägt.', es: 'En el embarazo (literal/creativo), cuando la intuición se agudiza, en el momento en que una corriente subterránea te lleva.', pt: 'Na gravidez (literal/criativa), quando a intuição se aguça, no momento em que uma corrente subterrânea te leva.', fr: 'Dans la grossesse (littérale/créative), quand l\'intuition s\'aiguise, à l\'instant où un courant souterrain t\'emporte.', ja: '妊娠（実際の／創造的な）のうちに、直感が研ぎ澄まされるとき、地下の流れがあなたを運ぶ瞬間に。' },
    traditions: [
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'İsa\'nın sembolü. "İkhthys" — Yunanca balık, İsa\'nın adının ilk harfleri. Erken Hristiyanların gizli sembolü.', en: 'Symbol of Christ. "Ichthys" — Greek for fish, an acronym of Christ\'s name. The secret symbol of the early Christians.', de: 'Symbol Christi. "Ichthys" — griechisch für Fisch, ein Akronym des Namens Christi. Das geheime Zeichen der frühen Christen.', es: 'Símbolo de Cristo. "Ichthys" — pez en griego, acrónimo del nombre de Cristo. El símbolo secreto de los primeros cristianos.', pt: 'Símbolo de Cristo. "Ichthys" — peixe em grego, acrónimo do nome de Cristo. O símbolo secreto dos primeiros cristãos.', fr: 'Symbole du Christ. "Ichthys" — poisson en grec, acronyme du nom du Christ. Le symbole secret des premiers chrétiens.', ja: 'キリストの象徴。「イクテュス」——ギリシア語で魚、キリストの名の頭字語。初期キリスト教徒の秘密の象徴。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Matsya — Vishnu\'nun balık avatarı. Tufandan insanlığı kurtarır.', en: 'Matsya — Vishnu\'s fish avatar. He saves humanity from the flood.', de: 'Matsya — Vishnus Fisch-Avatar. Er rettet die Menschheit vor der Sintflut.', es: 'Matsya — el avatar pez de Vishnú. Salva a la humanidad del diluvio.', pt: 'Matsya — o avatar peixe de Vishnu. Salva a humanidade do dilúvio.', fr: 'Matsya — l\'avatar poisson de Vishnou. Il sauve l\'humanité du déluge.', ja: 'マツヤ——ヴィシュヌの魚のアヴァターラ。大洪水から人類を救う。' } },
      { culture: { tr: 'Sumer', en: 'Sumerian', de: 'Sumerisch', es: 'Sumerio', pt: 'Sumério', fr: 'Sumérien', ja: 'シュメール' }, meaning: { tr: 'Oannes — balık-insan tanrı, sudan çıkıp insanlara medeniyet öğretti.', en: 'Oannes — the fish-man god who emerged from the waters to teach civilization to humanity.', de: 'Oannes — der Fisch-Mensch-Gott, der aus den Wassern stieg, um der Menschheit die Zivilisation zu lehren.', es: 'Oannes — el dios pez-hombre que salió de las aguas para enseñar la civilización a la humanidad.', pt: 'Oannes — o deus peixe-homem que saiu das águas para ensinar a civilização à humanidade.', fr: 'Oannès — le dieu poisson-homme qui sortit des eaux pour enseigner la civilisation à l\'humanité.', ja: 'オアンネス——水から現れ、人類に文明を教えた魚にして人なる神。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Bolluğun sembolü. Yeni yılda balık yenir — "yıllar boyu fazlalık" duası.', en: 'Symbol of abundance. Fish is eaten at New Year — the wish "surplus through the years".', de: 'Symbol des Überflusses. Zu Neujahr isst man Fisch — der Wunsch "Überfluss über die Jahre".', es: 'Símbolo de la abundancia. En Año Nuevo se come pescado — el deseo de "excedente a lo largo de los años".', pt: 'Símbolo da abundância. No Ano Novo come-se peixe — o desejo de "excedente ao longo dos anos".', fr: 'Symbole de l\'abondance. Au Nouvel An, on mange du poisson — le vœu "surplus au fil des années".', ja: '豊穣の象徴。新年に魚を食べる——「年々の余り」を願って。' } },
      { culture: { tr: 'Anadolu Halk', en: 'Anatolian Folk', de: 'Anatolische Volkskultur', es: 'Folclore Anatolio', pt: 'Folclore Anatólio', fr: 'Folklore Anatolien', ja: 'アナトリア民俗' }, meaning: { tr: 'Bereket sembolü. Düğünlerde balık motifi — doğurganlık duası.', en: 'Symbol of abundance. The fish motif at weddings — a blessing of fertility.', de: 'Symbol des Überflusses. Das Fischmotiv bei Hochzeiten — ein Segen der Fruchtbarkeit.', es: 'Símbolo de la abundancia. El motivo del pez en las bodas — una bendición de fertilidad.', pt: 'Símbolo da abundância. O motivo do peixe nos casamentos — uma bênção de fertilidade.', fr: 'Symbole de l\'abondance. Le motif du poisson aux mariages — une bénédiction de fertilité.', ja: '豊穣の象徴。婚礼における魚の文様——多産の祝福。' } },
    ],
    myths: [
      { tr: 'Matsya Avatarı: Hint mitolojisinde tufan yaklaşırken Vishnu küçük bir balık olarak Manu\'ya görünür. Büyür, devleşir, gemiyi çekerek insanlığı kurtarır. Sular bilinçaltı, balık o bilinçaltından çıkan kurtuluş.', en: 'The Matsya Avatar: In Hindu mythology, as the flood nears, Vishnu appears to Manu as a small fish. He grows immense and tows the ship, saving humanity. The waters are the unconscious; the fish is the salvation emerging from it.', de: 'Der Matsya-Avatar: In der hinduistischen Mythologie erscheint Vishnu, als die Sintflut naht, dem Manu als kleiner Fisch. Er wächst gewaltig und zieht das Schiff, die Menschheit rettend. Die Wasser sind das Unbewusste; der Fisch die daraus aufsteigende Errettung.', es: 'El avatar Matsya: En la mitología hindú, al acercarse el diluvio, Vishnú aparece a Manu como un pequeño pez. Crece inmenso y remolca la nave, salvando a la humanidad. Las aguas son el inconsciente; el pez es la salvación que emerge de él.', pt: 'O avatar Matsya: Na mitologia hindu, ao aproximar-se o dilúvio, Vishnu aparece a Manu como um pequeno peixe. Cresce imenso e reboca o navio, salvando a humanidade. As águas são o inconsciente; o peixe é a salvação que dele emerge.', fr: 'L\'avatar Matsya : Dans la mythologie hindoue, à l\'approche du déluge, Vishnou apparaît à Manu sous la forme d\'un petit poisson. Il grandit immensément et remorque le navire, sauvant l\'humanité. Les eaux sont l\'inconscient ; le poisson, le salut qui en émerge.', ja: 'マツヤ・アヴァターラ：ヒンドゥー神話において、大洪水が近づくと、ヴィシュヌは小さな魚としてマヌの前に現れる。巨大に育ち、船を曳いて人類を救う。水は無意識、魚はそこから現れる救い。' },
      { tr: 'İkhthys: Roma\'da Hristiyanlar zulüm altındayken birbirini tanımak için balık sembolünü kumda çizerdi. "Iesous Khristos Theou Yios Soter" baş harfleri — İsa, Tanrının Oğlu, Kurtarıcı.', en: 'Ichthys: While Christians were persecuted in Rome, they drew the fish symbol in the sand to recognize one another. The initials of "Iesous Khristos Theou Yios Soter" — Jesus Christ, Son of God, Savior.', de: 'Ichthys: Als die Christen in Rom verfolgt wurden, zeichneten sie das Fischsymbol in den Sand, um einander zu erkennen. Die Anfangsbuchstaben von "Iesous Khristos Theou Yios Soter" — Jesus Christus, Gottes Sohn, Erlöser.', es: 'Ichthys: Mientras los cristianos eran perseguidos en Roma, dibujaban el símbolo del pez en la arena para reconocerse. Las iniciales de "Iesous Khristos Theou Yios Soter" — Jesucristo, Hijo de Dios, Salvador.', pt: 'Ichthys: Enquanto os cristãos eram perseguidos em Roma, desenhavam o símbolo do peixe na areia para se reconhecerem. As iniciais de "Iesous Khristos Theou Yios Soter" — Jesus Cristo, Filho de Deus, Salvador.', fr: 'Ichthys : Tandis que les chrétiens étaient persécutés à Rome, ils traçaient le symbole du poisson dans le sable pour se reconnaître. Les initiales de "Iesous Khristos Theou Yios Soter" — Jésus-Christ, Fils de Dieu, Sauveur.', ja: 'イクテュス：ローマでキリスト教徒が迫害されていたとき、互いを見分けるために砂に魚の象徴を描いた。「イエースース・クリストス・テウー・ヒュイオス・ソーテール」の頭文字——イエス・キリスト、神の子、救い主。' },
    ],
  },

  // ─── a040 Horoz ─────────────────────────────────────────────────────────
  a040: {
    jung: { tr: '"Şafak Habercisi" arketipi. Horoz — uyanışı ilan eden, karanlığı yarıp ışığı çağıran ses.', en: 'The "Herald of Dawn" archetype. The rooster — the voice that announces awakening, that splits darkness and summons light.', de: 'Der Archetyp des "Boten der Morgenröte". Der Hahn — die Stimme, die das Erwachen verkündet, die Finsternis spaltet und das Licht herbeiruft.', es: 'El arquetipo del "Heraldo del Alba". El gallo — la voz que anuncia el despertar, que parte la oscuridad y convoca la luz.', pt: 'O arquétipo do "Arauto da Aurora". O galo — a voz que anuncia o despertar, que rasga a escuridão e convoca a luz.', fr: 'L\'archétype du "Héraut de l\'aube". Le coq — la voix qui annonce l\'éveil, qui fend les ténèbres et appelle la lumière.', ja: '「夜明けの使者」の元型。雄鶏——目覚めを告げ、闇を裂いて光を呼ぶ声。' },
    dream: { tr: 'Horoz rüyada — uyanma vakti! Bilinçaltında gördüğün bir şey gün ışığına çıkmak istiyor. Ötüyorsa: ilan zamanı, sus durmak günah.', en: 'Rooster in dream — time to wake! Something you have seen in your unconscious wants to come to daylight. Crowing: time to declare; staying silent is sin.', de: 'Hahn im Traum — Zeit aufzuwachen! Etwas, das du in deinem Unbewussten gesehen hast, will ans Tageslicht. Kräht er: Zeit zu verkünden; zu schweigen ist Sünde.', es: 'Gallo en sueños — ¡hora de despertar! Algo que has visto en tu inconsciente quiere salir a la luz del día. Si canta: tiempo de declarar; callar es pecado.', pt: 'Galo em sonho — hora de acordar! Algo que viste no teu inconsciente quer vir à luz do dia. Se canta: tempo de declarar; calar é pecado.', fr: 'Coq en rêve — l\'heure de se réveiller ! Quelque chose que tu as vu dans ton inconscient veut venir au grand jour. Chantant : le temps de déclarer ; se taire est péché.', ja: '夢の中の雄鶏——目覚めの時! あなたが無意識で見た何かが、日の光のもとへ出たがっている。鳴くなら、告げる時——黙していることは罪。' },
    shadow: { tr: 'Kibirli gösteriş. Horoz sabahları ilan eder ama "ben olmasam güneş doğmaz" sanrısı — egonun çiçeklenmesi.', en: 'Conceited display. The rooster heralds the mornings, but the delusion "without me the sun would not rise" — the ego in bloom.', de: 'Eitle Zurschaustellung. Der Hahn verkündet die Morgen, doch der Wahn "ohne mich ginge die Sonne nicht auf" — das Ego in voller Blüte.', es: 'Ostentación vanidosa. El gallo anuncia las mañanas, pero la ilusión "sin mí no saldría el sol" — el ego en flor.', pt: 'Ostentação vaidosa. O galo anuncia as manhãs, mas a ilusão "sem mim o sol não nasceria" — o ego em flor.', fr: 'Ostentation vaniteuse. Le coq annonce les matins, mais l\'illusion "sans moi le soleil ne se lèverait pas" — l\'ego en fleur.', ja: '虚栄の見せびらかし。雄鶏は朝を告げるが、「私がいなければ陽は昇らぬ」という思い込み——自我の開花。' },
    whenAppears: { tr: 'Uyanmak, ilan etmek, sözünü yüksek sesle söylemek gerektiğinde, karanlık dönem bittiğinde.', en: 'When you must wake, declare, speak your word aloud, when a dark period has ended.', de: 'Wenn du erwachen, verkünden, dein Wort laut aussprechen musst, wenn eine dunkle Zeit geendet hat.', es: 'Cuando debes despertar, declarar, decir tu palabra en voz alta, cuando un período oscuro ha terminado.', pt: 'Quando deves acordar, declarar, dizer a tua palavra em voz alta, quando um período sombrio terminou.', fr: 'Quand tu dois t\'éveiller, déclarer, dire ta parole à voix haute, quand une période sombre a pris fin.', ja: '目覚め、告げ、自らの言葉を声高に語らねばならぬとき、暗い時期が終わったときに。' },
    traditions: [
      { culture: { tr: 'Türk Halk', en: 'Turkish Folk', de: 'Türkische Volkskultur', es: 'Folclore Turco', pt: 'Folclore Turco', fr: 'Folklore Turc', ja: 'トルコ民俗' }, meaning: { tr: 'Sabahın müjdecisi — ezandan önce öten kuş. Anadolu köyünün saatçisi.', en: 'Herald of the morning — the bird that crows before the call to prayer. The clockkeeper of the Anatolian village.', de: 'Bote des Morgens — der Vogel, der vor dem Gebetsruf kräht. Der Uhrmacher des anatolischen Dorfes.', es: 'Heraldo de la mañana — el ave que canta antes de la llamada a la oración. El relojero del pueblo anatolio.', pt: 'Arauto da manhã — a ave que canta antes do chamado à oração. O relojoeiro da aldeia anatólia.', fr: 'Héraut du matin — l\'oiseau qui chante avant l\'appel à la prière. L\'horloger du village anatolien.', ja: '朝の告げ手——礼拝の呼びかけ（アザーン）の前に鳴く鳥。アナトリアの村の時計番。' } },
      { culture: { tr: 'Pers', en: 'Persian', de: 'Persisch', es: 'Persa', pt: 'Persa', fr: 'Perse', ja: 'ペルシア' }, meaning: { tr: 'Zerdüştlükte — kötülüğü kovan, ışığı çağıran kutsal kuş.', en: 'In Zoroastrianism — the sacred bird that drives off evil and summons light.', de: 'Im Zoroastrismus — der heilige Vogel, der das Böse vertreibt und das Licht herbeiruft.', es: 'En el zoroastrismo — el ave sagrada que ahuyenta el mal y convoca la luz.', pt: 'No zoroastrismo — a ave sagrada que afugenta o mal e convoca a luz.', fr: 'Dans le zoroastrisme — l\'oiseau sacré qui chasse le mal et appelle la lumière.', ja: 'ゾロアスター教において——悪を退け、光を呼ぶ聖なる鳥。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Petrus\'un üç kez İsa\'yı inkâr etmesi horozun ötüşüyle bağlı — vicdanın sesi.', en: 'Peter\'s threefold denial of Christ is bound to the rooster\'s crow — the voice of conscience.', de: 'Petrus\' dreifache Verleugnung Christi ist an den Hahnenschrei gebunden — die Stimme des Gewissens.', es: 'La triple negación de Cristo por Pedro está ligada al canto del gallo — la voz de la conciencia.', pt: 'A tripla negação de Cristo por Pedro está ligada ao canto do galo — a voz da consciência.', fr: 'Le triple reniement du Christ par Pierre est lié au chant du coq — la voix de la conscience.', ja: 'ペテロが三度キリストを否んだことは雄鶏の鳴き声と結びついている——良心の声。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'On iki burç hayvanından biri. Dürüstlük, sadakat, çalışkanlığın sembolü.', en: 'One of the twelve zodiac animals. Symbol of honesty, loyalty, and diligence.', de: 'Eines der zwölf Tierkreiszeichen. Symbol der Ehrlichkeit, Treue und des Fleißes.', es: 'Uno de los doce animales del zodíaco. Símbolo de la honestidad, la lealtad y la diligencia.', pt: 'Um dos doze animais do zodíaco. Símbolo da honestidade, da lealdade e da diligência.', fr: 'L\'un des douze animaux du zodiaque. Symbole de l\'honnêteté, de la loyauté et de la diligence.', ja: '十二支の一つ。誠実、忠誠、勤勉の象徴。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Yer altı dünyasının uyarıcısı — ruhların uyanış saatini bildirir.', en: 'The warner of the underworld — announcer of the hour the souls awaken.', de: 'Der Warner der Unterwelt — Verkünder der Stunde, da die Seelen erwachen.', es: 'El que advierte del inframundo — anunciador de la hora en que despiertan las almas.', pt: 'O que avisa do submundo — anunciador da hora em que as almas despertam.', fr: 'L\'avertisseur des enfers — annonciateur de l\'heure où les âmes s\'éveillent.', ja: '冥界の警告者——魂が目覚める刻を告げる者。' } },
    ],
    myths: [
      { tr: 'Petrus ve Horoz: Hristiyan İncil\'inde Petrus, İsa\'yı korkudan üç kez inkâr eder. Horoz öttüğünde fark eder ve ağlar. Horoz — vicdanın geri dönüş sesi.', en: 'Peter and the Rooster: In the Christian Gospel, Peter denies Christ three times out of fear. When the rooster crows, he realizes and weeps. The rooster — the voice of conscience\'s return.', de: 'Petrus und der Hahn: Im christlichen Evangelium verleugnet Petrus Christus aus Furcht dreimal. Als der Hahn kräht, erkennt er es und weint. Der Hahn — die Stimme der zurückkehrenden Gewissenhaftigkeit.', es: 'Pedro y el gallo: En el Evangelio cristiano, Pedro niega a Cristo tres veces por miedo. Cuando el gallo canta, lo comprende y llora. El gallo — la voz del retorno de la conciencia.', pt: 'Pedro e o galo: No Evangelho cristão, Pedro nega Cristo três vezes por medo. Quando o galo canta, apercebe-se e chora. O galo — a voz do regresso da consciência.', fr: 'Pierre et le coq : Dans l\'Évangile chrétien, Pierre renie le Christ trois fois par peur. Quand le coq chante, il s\'en rend compte et pleure. Le coq — la voix du retour de la conscience.', ja: 'ペテロと雄鶏：キリスト教の福音書において、ペテロは恐れから三度キリストを否む。雄鶏が鳴くと、彼は気づいて泣く。雄鶏——立ち返る良心の声。' },
      { tr: 'Zerdüşt Horozu: Eski Pers geleneğinde horozun ötüşüyle birlikte gece şeytanları kovulurdu. Şafak — kötülüğün geri çekilmesi. Horoz tanrısal düzenin müjdecisi.', en: 'The Zoroastrian Rooster: In ancient Persian tradition, the night demons were driven out at the rooster\'s crow. The dawn — the retreat of evil. The rooster, herald of divine order.', de: 'Der zoroastrische Hahn: In der alten persischen Tradition wurden die Nachtdämonen mit dem Hahnenschrei vertrieben. Die Morgenröte — der Rückzug des Bösen. Der Hahn, Bote der göttlichen Ordnung.', es: 'El gallo zoroástrico: En la antigua tradición persa, los demonios de la noche eran expulsados con el canto del gallo. El alba — la retirada del mal. El gallo, heraldo del orden divino.', pt: 'O galo zoroástrico: Na antiga tradição persa, os demónios da noite eram expulsos com o canto do galo. A aurora — a retirada do mal. O galo, arauto da ordem divina.', fr: 'Le coq zoroastrien : Dans l\'ancienne tradition perse, les démons de la nuit étaient chassés au chant du coq. L\'aube — le recul du mal. Le coq, héraut de l\'ordre divin.', ja: 'ゾロアスターの雄鶏：古のペルシアの伝統において、雄鶏の鳴き声とともに夜の悪霊が追い払われた。夜明け——悪の退却。雄鶏は神聖な秩序の告げ手。' },
    ],
  },

  // ─── a041 Tavşan ────────────────────────────────────────────────────────
  a041: {
    jung: { tr: '"Ay Çocuğu / Trickster" arketipi. Tavşan — sezgiyle hareket eden çevik akıl. Hızla kaybolup hızla geri gelen.', en: 'The "Moon Child / Trickster" archetype. The rabbit — the agile intellect moving by intuition. The one who vanishes swiftly and returns swiftly.', de: 'Der Archetyp des "Mondkindes / Tricksters". Das Kaninchen — der flinke Verstand, der sich nach Intuition bewegt. Das, was rasch verschwindet und rasch zurückkehrt.', es: 'El arquetipo del "Niño de la Luna / Embaucador". El conejo — el intelecto ágil que se mueve por intuición. El que desaparece veloz y vuelve veloz.', pt: 'O arquétipo da "Criança da Lua / Trapaceiro". O coelho — o intelecto ágil que se move pela intuição. Aquele que desaparece veloz e regressa veloz.', fr: 'L\'archétype de l\'"Enfant de la Lune / Filou". Le lapin — l\'intellect agile qui se meut par l\'intuition. Celui qui disparaît vite et revient vite.', ja: '「月の子／トリックスター」の元型。ウサギ——直感で動く俊敏な知。素早く消え、素早く戻る者。' },
    dream: { tr: 'Tavşan rüyada — bir fırsat hızla geçiyor, dikkatli ol. Kaçıyorsa: korkudan değil, sezgiden hareket et. Çoğalıyorsa: bereket geliyor.', en: 'Rabbit in dream — an opportunity is passing quickly, be alert. Fleeing: move by intuition, not by fear. Multiplying: abundance is coming.', de: 'Kaninchen im Traum — eine Gelegenheit zieht rasch vorbei, sei wachsam. Flieht es: Handle aus Intuition, nicht aus Furcht. Vermehrt es sich: Überfluss naht.', es: 'Conejo en sueños — una oportunidad pasa rápido, mantente alerta. Si huye: muévete por intuición, no por miedo. Si se multiplica: la abundancia viene.', pt: 'Coelho em sonho — uma oportunidade passa depressa, fica atento. Se foge: move-te pela intuição, não pelo medo. Se se multiplica: a abundância vem.', fr: 'Lapin en rêve — une occasion passe vite, sois attentif. Fuyant : agis par intuition, non par peur. Se multipliant : l\'abondance vient.', ja: '夢の中のウサギ——好機が素早く過ぎていく、油断するな。逃げるなら、恐れではなく直感で動け。増えるなら、豊穣が来る。' },
    shadow: { tr: 'Aşırı korku. Her gölgeden ürkmek, hayatı kaçırmak. Tavşan hızlıdır ama gizlenmek hep çözüm değildir.', en: 'Excessive fear. Startling at every shadow, missing life. The rabbit is swift, but hiding is not always the answer.', de: 'Übermäßige Furcht. Vor jedem Schatten zu erschrecken, das Leben zu verpassen. Das Kaninchen ist schnell, doch Verstecken ist nicht immer die Antwort.', es: 'Miedo excesivo. Sobresaltarse ante cada sombra, perderse la vida. El conejo es veloz, pero esconderse no siempre es la respuesta.', pt: 'Medo excessivo. Assustar-se com cada sombra, perder a vida. O coelho é veloz, mas esconder-se nem sempre é a resposta.', fr: 'Peur excessive. Sursauter à chaque ombre, manquer la vie. Le lapin est rapide, mais se cacher n\'est pas toujours la réponse.', ja: '過度の恐れ。あらゆる影にびくつき、人生を取り逃がすこと。ウサギは素早いが、隠れることが常に答えとは限らない。' },
    whenAppears: { tr: 'Hızlı bir karar gerektiğinde, doğurgan bir döneme girerken, ay döngüsünün başlangıcında.', en: 'When a swift decision is needed, when entering a fertile period, at the start of a lunar cycle.', de: 'Wenn eine schnelle Entscheidung nötig ist, wenn du in eine fruchtbare Phase eintrittst, zu Beginn eines Mondzyklus.', es: 'Cuando se necesita una decisión rápida, al entrar en un período fértil, al comienzo de un ciclo lunar.', pt: 'Quando é necessária uma decisão rápida, ao entrar num período fértil, no início de um ciclo lunar.', fr: 'Quand une décision rapide est nécessaire, en entrant dans une période féconde, au début d\'un cycle lunaire.', ja: '素早い決断が必要なとき、実り多き時期に入るとき、月の周期の始まりに。' },
    traditions: [
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Ay\'da ölümsüzlük iksiri döven yeşim tavşan. Mid-Autumn Festival\'ın sembolü.', en: 'The jade rabbit pounding the elixir of immortality on the moon. Symbol of the Mid-Autumn Festival.', de: 'Das Jade-Kaninchen, das auf dem Mond das Elixier der Unsterblichkeit stampft. Symbol des Mondfestes.', es: 'El conejo de jade que machaca el elixir de la inmortalidad en la luna. Símbolo del Festival de Medio Otoño.', pt: 'O coelho de jade que pila o elixir da imortalidade na lua. Símbolo do Festival do Meio do Outono.', fr: 'Le lapin de jade qui pile l\'élixir d\'immortalité sur la lune. Symbole de la fête de la mi-automne.', ja: '月で不死の霊薬を搗く玉兎。中秋節の象徴。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Cerridwen\'in kazanından doğan dönüşüm sembolü. Bereket tanrıçasının yoldaşı.', en: 'A symbol of transformation born from Cerridwen\'s cauldron. Companion of the goddess of abundance.', de: 'Ein Symbol der Verwandlung, geboren aus Cerridwens Kessel. Gefährte der Göttin des Überflusses.', es: 'Un símbolo de transformación nacido del caldero de Cerridwen. Compañero de la diosa de la abundancia.', pt: 'Um símbolo de transformação nascido do caldeirão de Cerridwen. Companheiro da deusa da abundância.', fr: 'Un symbole de transformation né du chaudron de Cerridwen. Compagnon de la déesse de l\'abondance.', ja: 'ケリドウェンの大釜から生まれた変容の象徴。豊穣の女神の伴侶。' } },
      { culture: { tr: 'Anadolu Halk', en: 'Anatolian Folk', de: 'Anatolische Volkskultur', es: 'Folclore Anatolio', pt: 'Folclore Anatólio', fr: 'Folklore Anatolien', ja: 'アナトリア民俗' }, meaning: { tr: '"Tavşan masalı" — zekasıyla kurttan ve tilkiden kurtulan küçük kahraman.', en: '"The Rabbit\'s Tale" — the small hero who, by his wits, escapes the wolf and the fox.', de: '"Das Märchen vom Hasen" — der kleine Held, der durch seinen Verstand dem Wolf und dem Fuchs entkommt.', es: '"El cuento del conejo" — el pequeño héroe que, por su ingenio, escapa del lobo y del zorro.', pt: '"O conto do coelho" — o pequeno herói que, pela sua esperteza, escapa ao lobo e à raposa.', fr: '"Le conte du lapin" — le petit héros qui, par son esprit, échappe au loup et au renard.', ja: '「ウサギの昔話」——知恵によってオオカミとキツネから逃れる小さな英雄。' } },
      { culture: { tr: 'Aztek', en: 'Aztec', de: 'Aztekisch', es: 'Azteca', pt: 'Asteca', fr: 'Aztèque', ja: 'アステカ' }, meaning: { tr: 'Centzon Totochtin — 400 tavşan tanrı. Pulque (içki) ve coşkunun habercisi.', en: 'Centzon Totochtin — the four hundred rabbit gods. Heralds of pulque (drink) and ecstasy.', de: 'Centzon Totochtin — die vierhundert Kaninchengötter. Boten des Pulque (Getränk) und der Ekstase.', es: 'Centzon Totochtin — los cuatrocientos dioses conejo. Heraldos del pulque (bebida) y del éxtasis.', pt: 'Centzon Totochtin — os quatrocentos deuses coelho. Arautos do pulque (bebida) e do êxtase.', fr: 'Centzon Totochtin — les quatre cents dieux lapins. Hérauts du pulque (boisson) et de l\'extase.', ja: 'センツォン・トトチティン——四百のウサギの神々。プルケ（酒）と恍惚の使者。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Paskalya tavşanı — dirilişin ve baharın simgesi. Yumurta dağıtan haberci.', en: 'The Easter Bunny — symbol of resurrection and spring. The herald who distributes eggs.', de: 'Der Osterhase — Symbol der Auferstehung und des Frühlings. Der Bote, der Eier verteilt.', es: 'El conejo de Pascua — símbolo de la resurrección y la primavera. El heraldo que reparte huevos.', pt: 'O coelho da Páscoa — símbolo da ressurreição e da primavera. O arauto que distribui ovos.', fr: 'Le lapin de Pâques — symbole de la résurrection et du printemps. Le héraut qui distribue les œufs.', ja: 'イースターのウサギ——復活と春の象徴。卵を配る使者。' } },
    ],
    myths: [
      { tr: 'Ay Tavşanı: Çin mitolojisinde Ay\'da bir tavşan yaşar ve ölümsüzlük iksiri döver. Mid-Autumn Festival\'da çocuklar onun şerefine ay kekleri yer — kozmik bereket.', en: 'The Moon Rabbit: In Chinese mythology, a rabbit lives on the moon and pounds the elixir of immortality. At the Mid-Autumn Festival, children eat mooncakes in its honor — cosmic abundance.', de: 'Das Mondkaninchen: In der chinesischen Mythologie lebt ein Kaninchen auf dem Mond und stampft das Elixier der Unsterblichkeit. Zum Mondfest essen Kinder ihm zu Ehren Mondkuchen — kosmischer Überfluss.', es: 'El conejo de la luna: En la mitología china, un conejo vive en la luna y machaca el elixir de la inmortalidad. En el Festival de Medio Otoño, los niños comen pasteles de luna en su honor — abundancia cósmica.', pt: 'O coelho da lua: Na mitologia chinesa, um coelho vive na lua e pila o elixir da imortalidade. No Festival do Meio do Outono, as crianças comem bolos da lua em sua honra — abundância cósmica.', fr: 'Le lapin de la lune : Dans la mythologie chinoise, un lapin vit sur la lune et pile l\'élixir d\'immortalité. À la fête de la mi-automne, les enfants mangent des gâteaux de lune en son honneur — abondance cosmique.', ja: '月のウサギ：中国神話において、ウサギは月に住み、不死の霊薬を搗く。中秋節に子どもたちはその栄誉をたたえて月餅を食べる——宇宙の豊穣。' },
      { tr: 'Tavşan ve Kaplumbağa: Aesop\'un en bilinen fablında hızlı tavşan, yavaş kaplumbağaya yarışta kaybeder. Hız her zaman kazanmaz — sebat kazanır.', en: 'The Hare and the Tortoise: In Aesop\'s best-known fable, the swift hare loses the race to the slow tortoise. Speed does not always win — perseverance does.', de: 'Der Hase und die Schildkröte: In Äsops bekanntester Fabel verliert der schnelle Hase das Rennen gegen die langsame Schildkröte. Geschwindigkeit gewinnt nicht immer — Beharrlichkeit tut es.', es: 'La liebre y la tortuga: En la fábula más conocida de Esopo, la veloz liebre pierde la carrera ante la lenta tortuga. La velocidad no siempre gana — la perseverancia sí.', pt: 'A lebre e a tartaruga: Na fábula mais conhecida de Esopo, a veloz lebre perde a corrida para a lenta tartaruga. A velocidade nem sempre vence — a perseverança vence.', fr: 'Le lièvre et la tortue : Dans la fable la plus connue d\'Ésope, le lièvre rapide perd la course contre la tortue lente. La vitesse ne gagne pas toujours — la persévérance, oui.', ja: 'ウサギとカメ：イソップの最も名高い寓話において、速いウサギは遅いカメに競走で負ける。速さは常に勝つわけではない——勝つのは忍耐。' },
    ],
  },

  // ─── a042 Akrep ─────────────────────────────────────────────────────────
  a042: {
    jung: { tr: '"Yıkıcı Dönüştürücü" arketipi. Akrep — Yılan ile aynı boyda, hatta daha derin. Yas ile yenilenmeyi bir ısırışta birleştiren.', en: 'The "Destructive Transformer" archetype. The scorpion — equal to or deeper than the serpent. The one who unites mourning and renewal in a single sting.', de: 'Der Archetyp des "zerstörerischen Verwandlers". Der Skorpion — der Schlange ebenbürtig, ja tiefer. Der, der Trauer und Erneuerung in einem einzigen Stich vereint.', es: 'El arquetipo del "Transformador Destructor". El escorpión — igual o más profundo que la serpiente. El que une el duelo y la renovación en una sola picadura.', pt: 'O arquétipo do "Transformador Destruidor". O escorpião — igual ou mais profundo que a serpente. Aquele que une o luto e a renovação numa só picada.', fr: 'L\'archétype du "Transformateur destructeur". Le scorpion — l\'égal du serpent, voire plus profond. Celui qui unit le deuil et le renouveau en une seule piqûre.', ja: '「破壊する変容者」の元型。サソリ——蛇に並び、いやそれより深い。喪と再生を一刺しに結ぶ者。' },
    dream: { tr: 'Akrep rüyada — bastırılan bir konu yüzeye çıkıyor. Sokuyorsa: bir gerçek seni dönüştürecek. Sırtında taşıyorsan: zor bir bilgiyi taşıyorsun.', en: 'Scorpion in dream — a suppressed matter is surfacing. Stinging: a truth will transform you. Carrying it on your back: you are bearing a difficult knowledge.', de: 'Skorpion im Traum — eine unterdrückte Angelegenheit steigt an die Oberfläche. Sticht er: Eine Wahrheit wird dich verwandeln. Trägst du ihn auf dem Rücken: Du trägst ein schwieriges Wissen.', es: 'Escorpión en sueños — un asunto reprimido aflora. Si pica: una verdad te transformará. Si lo llevas a la espalda: portas un conocimiento difícil.', pt: 'Escorpião em sonho — um assunto reprimido aflora. Se pica: uma verdade transformar-te-á. Se o levas às costas: carregas um conhecimento difícil.', fr: 'Scorpion en rêve — une affaire réprimée remonte à la surface. Piquant : une vérité te transformera. Le portant sur ton dos : tu portes un savoir difficile.', ja: '夢の中のサソリ——抑え込まれた事柄が浮かび上がる。刺すなら、ある真実があなたを変える。背に負うなら、あなたは難しい知を担っている。' },
    shadow: { tr: 'Zehir saçmak. Akrep yaralandığında çevresine kuyruğunu sallar — yaralı kişi başkalarını yaralar. İçsel acı tedavi edilmezse zehirleyici olur.', en: 'Spreading venom. Wounded, the scorpion swings its tail at all around — the wounded one wounds others. Inner pain untreated becomes toxic.', de: 'Gift verspritzen. Verwundet schlägt der Skorpion mit dem Schwanz nach allem ringsum — der Verwundete verwundet andere. Unbehandelter innerer Schmerz wird giftig.', es: 'Esparcir veneno. Herido, el escorpión agita su cola hacia todo lo que lo rodea — el herido hiere a otros. El dolor interior no tratado se vuelve tóxico.', pt: 'Espalhar veneno. Ferido, o escorpião agita a cauda contra tudo à sua volta — o ferido fere os outros. A dor interior não tratada torna-se tóxica.', fr: 'Répandre le venin. Blessé, le scorpion lance sa queue contre tout ce qui l\'entoure — le blessé blesse les autres. La douleur intérieure non soignée devient toxique.', ja: '毒を撒くこと。傷ついたサソリは周囲に尾を振るう——傷ついた者は他者を傷つける。手当てされぬ内なる痛みは毒となる。' },
    whenAppears: { tr: 'Yas, yıkım, kıskançlık veya ihanet gibi derin duygu süreçlerinde, dönüştürücü acıyla yüzleşmen gerektiğinde.', en: 'In deep emotional processes such as grief, destruction, jealousy, or betrayal, when you must face transformative pain.', de: 'In tiefen emotionalen Prozessen wie Trauer, Zerstörung, Eifersucht oder Verrat, wenn du dem verwandelnden Schmerz begegnen musst.', es: 'En procesos emocionales profundos como el duelo, la destrucción, los celos o la traición, cuando debes enfrentar el dolor transformador.', pt: 'Em processos emocionais profundos como o luto, a destruição, o ciúme ou a traição, quando deves enfrentar a dor transformadora.', fr: 'Dans des processus émotionnels profonds tels le deuil, la destruction, la jalousie ou la trahison, quand tu dois affronter la douleur transformatrice.', ja: '喪、破壊、嫉妬、裏切りといった深い感情の過程において、変容をもたらす痛みと向き合わねばならぬときに。' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Serqet — akrep tanrıça. Ölüleri öbür dünyada koruyan. Zehiri tedaviye dönüştüren.', en: 'Serqet — the scorpion goddess. Protector of the dead in the otherworld. The one who turns venom into cure.', de: 'Serqet — die Skorpiongöttin. Beschützerin der Toten im Jenseits. Die, die Gift in Heilung verwandelt.', es: 'Serqet — la diosa escorpión. Protectora de los muertos en el más allá. La que convierte el veneno en cura.', pt: 'Serqet — a deusa escorpião. Protetora dos mortos no além. Aquela que transforma o veneno em cura.', fr: 'Serqet — la déesse scorpion. Protectrice des morts dans l\'au-delà. Celle qui change le venin en remède.', ja: 'セルケト——サソリの女神。彼岸で死者を守る者。毒を癒しへと変える者。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Orion\'u öldüren akrep — Artemis tarafından gönderilen kozmik adalet. Yıldız takımı oldular.', en: 'The scorpion that killed Orion — cosmic justice sent by Artemis. They became constellations.', de: 'Der Skorpion, der Orion tötete — kosmische Gerechtigkeit, von Artemis gesandt. Sie wurden zu Sternbildern.', es: 'El escorpión que mató a Orión — justicia cósmica enviada por Artemisa. Se convirtieron en constelaciones.', pt: 'O escorpião que matou Oríon — justiça cósmica enviada por Ártemis. Tornaram-se constelações.', fr: 'Le scorpion qui tua Orion — justice cosmique envoyée par Artémis. Ils devinrent des constellations.', ja: 'オリオンを殺したサソリ——アルテミスが遣わした宇宙の正義。彼らは星座となった。' } },
      { culture: { tr: 'Astroloji', en: 'Astrology', de: 'Astrologie', es: 'Astrología', pt: 'Astrologia', fr: 'Astrologie', ja: '占星術' }, meaning: { tr: 'Akrep burcu — ölüm ve diriliş, tabu, gizli bilgi. Pluto\'nun ev sahibi.', en: 'The sign of Scorpio — death and resurrection, taboo, hidden knowledge. The house of Pluto.', de: 'Das Sternzeichen Skorpion — Tod und Auferstehung, Tabu, verborgenes Wissen. Das Haus des Pluto.', es: 'El signo de Escorpio — muerte y resurrección, tabú, conocimiento oculto. La casa de Plutón.', pt: 'O signo de Escorpião — morte e ressurreição, tabu, conhecimento oculto. A casa de Plutão.', fr: 'Le signe du Scorpion — mort et résurrection, tabou, savoir caché. La maison de Pluton.', ja: '蠍座——死と復活、タブー、隠された知。冥王星（プルート）の宮。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Köy efsanelerinde akrebin yuvasını bozan başına iş alır. Sınırlı varlığın saygısı.', en: 'In village legends, whoever disturbs the scorpion\'s nest brings trouble upon themselves. The reverence due to bounded being.', de: 'In Dorfsagen zieht sich Unheil zu, wer das Nest des Skorpions stört. Die Ehrfurcht vor dem begrenzten Wesen.', es: 'En las leyendas de aldea, quien perturba el nido del escorpión atrae problemas sobre sí. La reverencia debida al ser limitado.', pt: 'Nas lendas de aldeia, quem perturba o ninho do escorpião atrai problemas sobre si. A reverência devida ao ser limitado.', fr: 'Dans les légendes villageoises, qui dérange le nid du scorpion s\'attire des ennuis. Le respect dû à l\'être limité.', ja: '村の伝説では、サソリの巣を乱す者は身に災いを招く。境ある存在への敬意。' } },
      { culture: { tr: 'İslam', en: 'Islamic', de: 'Islamisch', es: 'Islámico', pt: 'Islâmico', fr: 'Islamique', ja: 'イスラーム' }, meaning: { tr: 'Hadis-i şerifte cennette zararı olmayan, dünyada koruyucu sayılır — kötülük yalnız kendine değer.', en: 'In hadith, harmless in paradise and a protector in this world — evil reaches only itself.', de: 'Im Hadith im Paradies harmlos und in dieser Welt ein Beschützer — das Böse erreicht nur sich selbst.', es: 'En el hadiz, inofensivo en el paraíso y protector en este mundo — el mal solo alcanza a sí mismo.', pt: 'No hadith, inofensivo no paraíso e protetor neste mundo — o mal só atinge a si próprio.', fr: 'Dans le hadith, inoffensif au paradis et protecteur en ce monde — le mal n\'atteint que lui-même.', ja: 'ハディースにおいて、楽園では害なく、現世では守り手とされる——悪はおのれにしか及ばない。' } },
    ],
    myths: [
      { tr: 'Serqet ve Mumya: Mısır firavunları mumyalanırken karaciğer kavanozunu akrep tanrıça Serqet korurdu. Zehrin antiseptik gücü — ölümle yenilenmenin birleşmesi.', en: 'Serqet and the Mummy: When Egyptian pharaohs were mummified, the jar of the liver was guarded by the scorpion goddess Serqet. The antiseptic power of venom — the union of death and renewal.', de: 'Serqet und die Mumie: Bei der Mumifizierung der ägyptischen Pharaonen wurde das Gefäß der Leber von der Skorpiongöttin Serqet bewacht. Die antiseptische Kraft des Giftes — die Vereinigung von Tod und Erneuerung.', es: 'Serqet y la momia: Cuando se momificaba a los faraones egipcios, el vaso del hígado era guardado por la diosa escorpión Serqet. El poder antiséptico del veneno — la unión de la muerte y la renovación.', pt: 'Serqet e a múmia: Quando os faraós egípcios eram mumificados, o vaso do fígado era guardado pela deusa escorpião Serqet. O poder antisséptico do veneno — a união da morte e da renovação.', fr: 'Serqet et la momie : Lors de la momification des pharaons égyptiens, le vase du foie était gardé par la déesse scorpion Serqet. Le pouvoir antiseptique du venin — l\'union de la mort et du renouveau.', ja: 'セルケトとミイラ：エジプトのファラオがミイラにされる際、肝臓の壺はサソリの女神セルケトが守った。毒の防腐の力——死と再生の結合。' },
      { tr: 'Orion ve Akrep: Yunan mitolojisinde dev avcı Orion kibirinden cezalandırılır — küçük bir akrep onu öldürür. İkisi de gökyüzüne yerleşir, biri doğarken diğeri batar — sonsuz kovalama.', en: 'Orion and the Scorpion: In Greek mythology, the giant hunter Orion is punished for his arrogance — a small scorpion kills him. Both are placed in the sky, one rising as the other sets — eternal pursuit.', de: 'Orion und der Skorpion: In der griechischen Mythologie wird der Riesenjäger Orion für seinen Hochmut bestraft — ein kleiner Skorpion tötet ihn. Beide werden an den Himmel gesetzt, der eine geht auf, während der andere untergeht — ewige Verfolgung.', es: 'Orión y el escorpión: En la mitología griega, el gigante cazador Orión es castigado por su arrogancia — un pequeño escorpión lo mata. Ambos son colocados en el cielo, uno sale mientras el otro se pone — persecución eterna.', pt: 'Oríon e o escorpião: Na mitologia grega, o gigante caçador Oríon é castigado pela sua arrogância — um pequeno escorpião mata-o. Ambos são colocados no céu, um nasce enquanto o outro se põe — perseguição eterna.', fr: 'Orion et le scorpion : Dans la mythologie grecque, le géant chasseur Orion est puni de son orgueil — un petit scorpion le tue. Tous deux sont placés dans le ciel, l\'un se lève tandis que l\'autre se couche — poursuite éternelle.', ja: 'オリオンとサソリ：ギリシア神話において、巨人の狩人オリオンはその傲慢ゆえに罰せられる——小さなサソリが彼を殺す。二人は天に据えられ、一方が昇るときもう一方が沈む——永遠の追跡。' },
    ],
  },

  // ─── a043 Kurbağa ───────────────────────────────────────────────────────
  a043: {
    jung: { tr: '"Eşiğin Habercisi" arketipi. Kurbağa — sudan karaya, çocukluktan yetişkinliğe geçen. Metamorfozun en görünür hâli.', en: 'The "Herald of the Threshold" archetype. The frog — the one who passes from water to land, from childhood to adulthood. The most visible form of metamorphosis.', de: 'Der Archetyp des "Boten der Schwelle". Der Frosch — der, der vom Wasser zum Land, von der Kindheit zum Erwachsensein übergeht. Die sichtbarste Gestalt der Metamorphose.', es: 'El arquetipo del "Heraldo del Umbral". La rana — la que pasa del agua a la tierra, de la infancia a la adultez. La forma más visible de la metamorfosis.', pt: 'O arquétipo do "Arauto do Limiar". A rã — aquela que passa da água à terra, da infância à idade adulta. A forma mais visível da metamorfose.', fr: 'L\'archétype du "Héraut du seuil". La grenouille — celle qui passe de l\'eau à la terre, de l\'enfance à l\'âge adulte. La forme la plus visible de la métamorphose.', ja: '「敷居の使者」の元型。カエル——水から陸へ、子ども時代から成人へと移る者。変態の最も目に見える姿。' },
    dream: { tr: 'Kurbağa rüyada — bir geçiş tamamlanıyor. Yağmurda görünüyorsa: temizlenme yaklaşıyor. Vıraklıyorsa: sesini bul, söyle.', en: 'Frog in dream — a transition is being completed. Appearing in rain: cleansing approaches. Croaking: find your voice and speak.', de: 'Frosch im Traum — ein Übergang vollendet sich. Erscheint er im Regen: Reinigung naht. Quakt er: Finde deine Stimme und sprich.', es: 'Rana en sueños — una transición se completa. Si aparece bajo la lluvia: la limpieza se acerca. Si croa: encuentra tu voz y habla.', pt: 'Rã em sonho — uma transição completa-se. Se aparece na chuva: a purificação aproxima-se. Se coaxa: encontra a tua voz e fala.', fr: 'Grenouille en rêve — une transition s\'achève. Apparaissant sous la pluie : la purification approche. Coassant : trouve ta voix et parle.', ja: '夢の中のカエル——一つの移行が完成しつつある。雨の中に現れるなら、浄めが近い。鳴くなら、自らの声を見いだして語れ。' },
    shadow: { tr: 'Yarı-dönüşüm. Bir hayatta hep iribaş kalmak — büyüyemeyen, sudan çıkamayan. Konfor geçişi engeller.', en: 'Half-transformation. Remaining a tadpole all one\'s life — unable to grow, unable to leave the water. Comfort prevents passage.', de: 'Halbverwandlung. Ein Leben lang Kaulquappe zu bleiben — unfähig zu wachsen, unfähig, das Wasser zu verlassen. Bequemlichkeit verhindert den Übergang.', es: 'Media transformación. Permanecer renacuajo toda la vida — incapaz de crecer, incapaz de salir del agua. La comodidad impide el paso.', pt: 'Meia transformação. Permanecer girino toda a vida — incapaz de crescer, incapaz de sair da água. O conforto impede a passagem.', fr: 'Demi-transformation. Rester têtard toute sa vie — incapable de grandir, incapable de quitter l\'eau. Le confort empêche le passage.', ja: '半ばの変容。一生オタマジャクシのままでいること——育つことも、水を出ることもできない。安逸が移行を妨げる。' },
    whenAppears: { tr: 'Bir eşikte (taşınma, evlilik, ayrılık), ruhsal/duygusal temizlenmede, sesini kullanma çağrısında.', en: 'At a threshold (moving, marriage, separation), in spiritual/emotional cleansing, at the call to use your voice.', de: 'An einer Schwelle (Umzug, Heirat, Trennung), bei geistiger/emotionaler Reinigung, beim Ruf, deine Stimme zu gebrauchen.', es: 'En un umbral (mudanza, matrimonio, separación), en la limpieza espiritual/emocional, en el llamado a usar tu voz.', pt: 'Num limiar (mudança, casamento, separação), na purificação espiritual/emocional, no chamado a usar a tua voz.', fr: 'À un seuil (déménagement, mariage, séparation), dans la purification spirituelle/émotionnelle, à l\'appel d\'user de ta voix.', ja: '敷居（引越し、結婚、別れ）にあるとき、霊的／感情的な浄めのうちに、自らの声を用いる呼びかけのときに。' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian', de: 'Ägyptisch', es: 'Egipcio', pt: 'Egípcio', fr: 'Égyptien', ja: 'エジプト' }, meaning: { tr: 'Heqet — kurbağa başlı tanrıça. Doğumun ve yenilenmenin koruyucusu. Nil taşkınının habercisi.', en: 'Heqet — the frog-headed goddess. Protector of birth and renewal. Herald of the Nile flood.', de: 'Heqet — die froschköpfige Göttin. Beschützerin der Geburt und der Erneuerung. Herold der Nilflut.', es: 'Heqet — la diosa con cabeza de rana. Protectora del nacimiento y la renovación. Heraldo de la crecida del Nilo.', pt: 'Heqet — a deusa com cabeça de rã. Protetora do nascimento e da renovação. Arauto da cheia do Nilo.', fr: 'Heqet — la déesse à tête de grenouille. Protectrice de la naissance et du renouveau. Héraut de la crue du Nil.', ja: 'ヘケト——カエルの頭をもつ女神。誕生と再生の守護者。ナイルの氾濫の使者。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Üç ayaklı kurbağa Jin Chan — ay ve zenginlik sembolü. Para getiren tılsım.', en: 'The three-legged frog Jin Chan — symbol of the moon and wealth. A talisman that draws money.', de: 'Der dreibeinige Frosch Jin Chan — Symbol des Mondes und des Reichtums. Ein Talisman, der Geld anzieht.', es: 'La rana de tres patas Jin Chan — símbolo de la luna y la riqueza. Un talismán que atrae el dinero.', pt: 'A rã de três patas Jin Chan — símbolo da lua e da riqueza. Um talismã que atrai o dinheiro.', fr: 'La grenouille à trois pattes Jin Chan — symbole de la lune et de la richesse. Un talisman qui attire l\'argent.', ja: '三本足のカエル金蟾（ジンチャン）——月と富の象徴。金を呼ぶ護符。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: '"Kurbağa öttü, yağmur yağdı" — bereketin habercisi. Köy ekonomisinde belirleyici sayılırdı.', en: '"The frog croaked, the rain came" — herald of abundance. Considered decisive in the village economy.', de: '"Der Frosch quakte, der Regen kam" — Herold des Überflusses. In der Dorfwirtschaft als entscheidend angesehen.', es: '"La rana croó, llegó la lluvia" — heraldo de la abundancia. Se consideraba decisiva en la economía aldeana.', pt: '"A rã coaxou, veio a chuva" — arauto da abundância. Considerada decisiva na economia da aldeia.', fr: '"La grenouille a coassé, la pluie est venue" — héraut de l\'abondance. Tenue pour décisive dans l\'économie villageoise.', ja: '「カエルが鳴いて、雨が降った」——豊穣の使者。村の経済において決定的とされた。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Şifa kuyularının koruyucusu. Toprak ile suyun birleştiği yerin bekçisi.', en: 'Guardian of healing wells. Keeper of the place where earth and water meet.', de: 'Hüter der Heilbrunnen. Wächter des Ortes, wo Erde und Wasser sich treffen.', es: 'Guardián de los pozos sanadores. Custodio del lugar donde la tierra y el agua se encuentran.', pt: 'Guardião dos poços curativos. Guardião do lugar onde a terra e a água se encontram.', fr: 'Gardienne des puits guérisseurs. Gardienne du lieu où la terre et l\'eau se rencontrent.', ja: '癒しの井戸の守り手。大地と水が出会う場の番人。' } },
      { culture: { tr: 'Aztek', en: 'Aztec', de: 'Aztekisch', es: 'Azteca', pt: 'Asteca', fr: 'Aztèque', ja: 'アステカ' }, meaning: { tr: 'Tlaltecuhtli — yer tanrıça, kurbağa formunda. Yaratılışın bedeni.', en: 'Tlaltecuhtli — the earth goddess in frog form. The body of creation.', de: 'Tlaltecuhtli — die Erdgöttin in Froschgestalt. Der Leib der Schöpfung.', es: 'Tlaltecuhtli — la diosa de la tierra en forma de rana. El cuerpo de la creación.', pt: 'Tlaltecuhtli — a deusa da terra em forma de rã. O corpo da criação.', fr: 'Tlaltecuhtli — la déesse de la terre sous forme de grenouille. Le corps de la création.', ja: 'トラルテクトリ——カエルの姿の大地の女神。創造の体。' } },
    ],
    myths: [
      { tr: 'Heqet ve Doğum: Mısır mitolojisinde kadın doğum yaparken kurbağa tanrıça Heqet\'in tılsımı bedeninin üzerinde taşınırdı. Suyun ve toprağın doğurgan birleşmesi.', en: 'Heqet and Birth: In Egyptian mythology, while a woman gave birth, the talisman of the frog goddess Heqet was worn on her body. The fertile union of water and earth.', de: 'Heqet und die Geburt: In der ägyptischen Mythologie trug eine Frau bei der Geburt den Talisman der Froschgöttin Heqet am Körper. Die fruchtbare Vereinigung von Wasser und Erde.', es: 'Heqet y el nacimiento: En la mitología egipcia, mientras una mujer daba a luz, el talismán de la diosa rana Heqet se llevaba sobre el cuerpo. La unión fértil del agua y la tierra.', pt: 'Heqet e o nascimento: Na mitologia egípcia, enquanto uma mulher dava à luz, o talismã da deusa rã Heqet era usado sobre o corpo. A união fértil da água e da terra.', fr: 'Heqet et la naissance : Dans la mythologie égyptienne, pendant qu\'une femme accouchait, le talisman de la déesse grenouille Heqet était porté sur son corps. L\'union féconde de l\'eau et de la terre.', ja: 'ヘケトと出産：エジプト神話において、女性が出産するあいだ、カエルの女神ヘケトの護符が体に着けられた。水と大地の実り豊かな結合。' },
      { tr: 'Prens Kurbağa: Grimm masalında prensesin öptüğü kurbağa prense dönüşür. Aşk ve kabul — gerçek kimliği ortaya çıkarır. Görünenin altındakini görmek.', en: 'The Frog Prince: In the Grimm tale, the frog the princess kisses turns into a prince. Love and acceptance — reveal the true identity. To see beneath what appears.', de: 'Der Froschkönig: Im Grimm-Märchen verwandelt sich der Frosch, den die Prinzessin küsst, in einen Prinzen. Liebe und Annahme — enthüllen die wahre Identität. Unter dem Schein zu sehen.', es: 'El príncipe rana: En el cuento de Grimm, la rana que la princesa besa se convierte en príncipe. El amor y la aceptación — revelan la verdadera identidad. Ver bajo lo que aparece.', pt: 'O príncipe rã: No conto de Grimm, a rã que a princesa beija transforma-se em príncipe. O amor e a aceitação — revelam a verdadeira identidade. Ver por baixo do que aparenta.', fr: 'Le prince grenouille : Dans le conte de Grimm, la grenouille que la princesse embrasse se change en prince. L\'amour et l\'acceptation — révèlent la véritable identité. Voir sous l\'apparence.', ja: 'カエルの王子：グリムの童話において、姫が口づけたカエルは王子に変わる。愛と受容——真の姿を顕わにする。見かけの下にあるものを見ること。' },
    ],
  },

  // ─── a044 Karga ─────────────────────────────────────────────────────────
  a044: {
    jung: { tr: '"Kolektif Bilge" arketipi. Karga — Kuzgun\'un sürü hâli. Bireysel zekanın paylaşıma açıldığı yer.', en: 'The "Collective Sage" archetype. The crow — the raven in its flock form. The place where individual intelligence opens to sharing.', de: 'Der Archetyp des "kollektiven Weisen". Die Krähe — der Rabe in seiner Schwarmgestalt. Der Ort, an dem sich die individuelle Intelligenz dem Teilen öffnet.', es: 'El arquetipo del "Sabio Colectivo". El cuervo común — el cuervo en su forma de bandada. El lugar donde la inteligencia individual se abre a compartir.', pt: 'O arquétipo do "Sábio Coletivo". A gralha — o corvo na sua forma de bando. O lugar onde a inteligência individual se abre à partilha.', fr: 'L\'archétype du "Sage collectif". La corneille — le corbeau dans sa forme de nuée. Le lieu où l\'intelligence individuelle s\'ouvre au partage.', ja: '「集団の賢者」の元型。カラス——ワタリガラスの群れの姿。個の知が分かち合いへと開かれる場。' },
    dream: { tr: 'Karga rüyada — kalabalığın akıllıca seçilmiş bir parçası olmaya çağrılıyorsun. Konuşuyorsa: bir mesaj iletmen lazım. Sürü hâlinde: kolektif karar zamanı.', en: 'Crow in dream — you are being called to become a wisely chosen part of the crowd. Speaking: you must convey a message. In flock: time for a collective decision.', de: 'Krähe im Traum — du wirst gerufen, ein klug gewählter Teil der Menge zu werden. Spricht sie: Du musst eine Botschaft überbringen. Im Schwarm: Zeit für eine kollektive Entscheidung.', es: 'Cuervo en sueños — eres llamado a convertirte en una parte sabiamente elegida de la multitud. Si habla: debes transmitir un mensaje. En bandada: tiempo de una decisión colectiva.', pt: 'Gralha em sonho — és chamado a tornar-te uma parte sabiamente escolhida da multidão. Se fala: deves transmitir uma mensagem. Em bando: tempo de uma decisão coletiva.', fr: 'Corneille en rêve — tu es appelé à devenir une part sagement choisie de la foule. Parlant : tu dois transmettre un message. En nuée : temps d\'une décision collective.', ja: '夢の中のカラス——あなたは群れの賢く選ばれた一部となるよう呼ばれている。語るなら、伝えるべき報せがある。群れをなすなら、集団の決断の時。' },
    shadow: { tr: '"Toplum baskısı" — kalabalık zihne kapılma. Karga sürüsü güçlüdür ama tek tek özgün kalmak da gerekir.', en: '"Social pressure" — being swept by the crowd mind. The murder of crows is strong, yet each must remain its own.', de: '"Gruppenzwang" — vom Massenverstand mitgerissen zu werden. Der Krähenschwarm ist stark, doch jeder muss er selbst bleiben.', es: '"Presión social" — ser arrastrado por la mente de la multitud. La bandada de cuervos es fuerte, pero cada uno debe seguir siendo él mismo.', pt: '"Pressão social" — ser arrastado pela mente da multidão. O bando de gralhas é forte, mas cada uma deve permanecer ela própria.', fr: '"Pression sociale" — être emporté par l\'esprit de la foule. La nuée de corneilles est forte, mais chacune doit rester elle-même.', ja: '「社会の圧力」——群衆の心に流されること。カラスの群れは強いが、一羽一羽が自分であり続けねばならない。' },
    whenAppears: { tr: 'Bir gruba katılırken, fikrini kalabalığa açıkça söylemen gerektiğinde, kolektif bir karara dahil olduğunda.', en: 'While joining a group, when you must speak your view openly to the crowd, when you are included in a collective decision.', de: 'Wenn du dich einer Gruppe anschließt, wenn du der Menge deine Meinung offen sagen musst, wenn du an einer kollektiven Entscheidung beteiligt bist.', es: 'Al unirte a un grupo, cuando debes decir tu opinión abiertamente a la multitud, cuando participas en una decisión colectiva.', pt: 'Ao juntares-te a um grupo, quando deves dizer a tua opinião abertamente à multidão, quando participas numa decisão coletiva.', fr: 'En rejoignant un groupe, quand tu dois dire ouvertement ton avis à la foule, quand tu participes à une décision collective.', ja: '集団に加わるとき、群衆に自分の意見をはっきり言わねばならぬとき、集団の決断に加わるときに。' },
    traditions: [
      { culture: { tr: 'Tibet', en: 'Tibetan', de: 'Tibetisch', es: 'Tibetano', pt: 'Tibetano', fr: 'Tibétain', ja: 'チベット' }, meaning: { tr: 'Mahakala\'nın haberci kuşu. Yıkıcı bilgeliğin habercisi.', en: 'The messenger bird of Mahakala. Herald of destructive wisdom.', de: 'Der Botenvogel des Mahakala. Herold der zerstörerischen Weisheit.', es: 'El ave mensajera de Mahakala. Heraldo de la sabiduría destructora.', pt: 'A ave mensageira de Mahakala. Arauto da sabedoria destruidora.', fr: 'L\'oiseau messager de Mahakala. Héraut de la sagesse destructrice.', ja: 'マハーカーラの使いの鳥。破壊的な知恵の使者。' } },
      { culture: { tr: 'Türk Halk', en: 'Turkish Folk', de: 'Türkische Volkskultur', es: 'Folclore Turco', pt: 'Folclore Turco', fr: 'Folklore Turc', ja: 'トルコ民俗' }, meaning: { tr: 'Karga zekası ile bilinir — bir kayalığa ceviz düşürerek kırması Anadolu masallarında geçer.', en: 'Known for the crow\'s wit — breaking a walnut by dropping it on a rock is told in Anatolian tales.', de: 'Bekannt für den Verstand der Krähe — dass sie eine Walnuss knackt, indem sie sie auf einen Felsen fallen lässt, wird in anatolischen Märchen erzählt.', es: 'Conocido por el ingenio del cuervo — que rompe una nuez dejándola caer sobre una roca se cuenta en los relatos anatolios.', pt: 'Conhecida pela esperteza da gralha — que parte uma noz deixando-a cair sobre uma rocha conta-se nos contos anatólios.', fr: 'Connue pour l\'esprit de la corneille — qu\'elle casse une noix en la laissant tomber sur un rocher est raconté dans les contes anatoliens.', ja: 'カラスの知恵で知られる——岩にクルミを落として割ることがアナトリアの物語に語られる。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Apollon\'un kuşu. Önce beyazdı, kötü haber getirdiği için tanrı tarafından siyaha boyandı.', en: 'Apollo\'s bird. Once white, painted black by the god for bringing bad news.', de: 'Apollons Vogel. Einst weiß, vom Gott für eine schlechte Nachricht schwarz gefärbt.', es: 'El ave de Apolo. Antes blanca, teñida de negro por el dios por traer malas noticias.', pt: 'A ave de Apolo. Outrora branca, tingida de negro pelo deus por trazer más notícias.', fr: 'L\'oiseau d\'Apollon. Jadis blanc, teint en noir par le dieu pour avoir apporté une mauvaise nouvelle.', ja: 'アポロンの鳥。かつては白かったが、悪い報せを運んだために神に黒く染められた。' } },
      { culture: { tr: 'Avustralya Aborjin', en: 'Australian Aboriginal', de: 'Australische Aborigines', es: 'Aborigen Australiano', pt: 'Aborígene Australiano', fr: 'Aborigène Australien', ja: 'オーストラリア・アボリジニ' }, meaning: { tr: 'Waa — yaratıcı ata. Ateşi insanlığa getiren trickster.', en: 'Waa — the creator ancestor. The trickster who brought fire to humanity.', de: 'Waa — der Schöpferahn. Der Trickster, der der Menschheit das Feuer brachte.', es: 'Waa — el ancestro creador. El embaucador que trajo el fuego a la humanidad.', pt: 'Waa — o ancestral criador. O trapaceiro que trouxe o fogo à humanidade.', fr: 'Waa — l\'ancêtre créateur. Le filou qui apporta le feu à l\'humanité.', ja: 'ワー——創造の祖。人類に火をもたらしたトリックスター。' } },
      { culture: { tr: 'Hint', en: 'Hindu', de: 'Hinduistisch', es: 'Hindú', pt: 'Hindu', fr: 'Hindou', ja: 'ヒンドゥー' }, meaning: { tr: 'Şani (Satürn) tanrısının bineği. Karma ve adaletin habercisi.', en: 'The mount of the god Shani (Saturn). Herald of karma and justice.', de: 'Das Reittier des Gottes Shani (Saturn). Herold von Karma und Gerechtigkeit.', es: 'La montura del dios Shani (Saturno). Heraldo del karma y la justicia.', pt: 'A montaria do deus Shani (Saturno). Arauto do carma e da justiça.', fr: 'La monture du dieu Shani (Saturne). Héraut du karma et de la justice.', ja: 'シャニ（土星）神の乗り物。カルマと正義の使者。' } },
    ],
    myths: [
      { tr: 'Apollon\'un Beyaz Kargası: Yunan mitolojisinde karga eskiden beyazdı. Apollon\'a sevgilisi Koronis\'in sadakatsizliğini söyleyince, tanrı haberin acısını kuşa yansıttı — karganın rengi siyah oldu, sesi cızırdadı.', en: 'Apollo\'s White Crow: In Greek mythology, the crow was once white. When it told Apollo of his beloved Coronis\'s unfaithfulness, the god transferred the pain of the news onto the bird — the crow\'s color became black and its voice grew harsh.', de: 'Apollons weiße Krähe: In der griechischen Mythologie war die Krähe einst weiß. Als sie Apollon die Untreue seiner Geliebten Koronis meldete, übertrug der Gott den Schmerz der Nachricht auf den Vogel — die Farbe der Krähe wurde schwarz und ihre Stimme rau.', es: 'El cuervo blanco de Apolo: En la mitología griega, el cuervo era antes blanco. Cuando le dijo a Apolo la infidelidad de su amada Corónide, el dios transfirió el dolor de la noticia al ave — el color del cuervo se volvió negro y su voz se hizo áspera.', pt: 'A gralha branca de Apolo: Na mitologia grega, a gralha era outrora branca. Quando contou a Apolo a infidelidade da sua amada Corónis, o deus transferiu a dor da notícia para a ave — a cor da gralha tornou-se negra e a sua voz áspera.', fr: 'La corneille blanche d\'Apollon : Dans la mythologie grecque, la corneille était jadis blanche. Lorsqu\'elle révéla à Apollon l\'infidélité de sa bien-aimée Coronis, le dieu reporta la douleur de la nouvelle sur l\'oiseau — la couleur de la corneille devint noire et sa voix rauque.', ja: 'アポロンの白いカラス：ギリシア神話において、カラスはかつて白かった。愛するコロニスの不貞をアポロンに告げると、神は報せの痛みを鳥に移した——カラスの色は黒くなり、その声はしわがれた。' },
      { tr: 'Waa ve Ateş: Avustralya Aborjin mitolojisinde karga Waa, kadınların gizlediği ateşi çalar ve insanlığa getirir. Trickster yaratıcı — kuralı bozarak hayatı kolaylaştıran.', en: 'Waa and Fire: In Australian Aboriginal mythology, the crow Waa steals the fire hidden by the women and brings it to humanity. The trickster-creator — the one who eases life by breaking the rule.', de: 'Waa und das Feuer: In der Mythologie der australischen Aborigines stiehlt die Krähe Waa das von den Frauen verborgene Feuer und bringt es der Menschheit. Der Trickster-Schöpfer — der, der das Leben erleichtert, indem er die Regel bricht.', es: 'Waa y el fuego: En la mitología aborigen australiana, el cuervo Waa roba el fuego escondido por las mujeres y lo trae a la humanidad. El embaucador-creador — el que facilita la vida rompiendo la regla.', pt: 'Waa e o fogo: Na mitologia aborígene australiana, o corvo Waa rouba o fogo escondido pelas mulheres e traz-no à humanidade. O trapaceiro-criador — aquele que facilita a vida quebrando a regra.', fr: 'Waa et le feu : Dans la mythologie aborigène australienne, le corbeau Waa vole le feu caché par les femmes et l\'apporte à l\'humanité. Le filou-créateur — celui qui facilite la vie en brisant la règle.', ja: 'ワーと火：オーストラリア・アボリジニの神話において、カラスのワーは女たちが隠した火を盗み、人類にもたらす。トリックスターたる創造者——掟を破ることで生を楽にする者。' },
    ],
  },

  // ─── a045 Sincap ────────────────────────────────────────────────────────
  a045: {
    jung: { tr: '"Mütevazı Hazırlayıcı" arketipi. Sincap — küçük olduğunu bilen, ama planını yapan. Kollektif değil, bireysel hazırlığın sembolü.', en: 'The "Humble Preparer" archetype. The squirrel — knowing it is small, yet making its plan. Symbol of individual, not collective, preparation.', de: 'Der Archetyp des "bescheidenen Vorbereiters". Das Eichhörnchen — es weiß, dass es klein ist, doch macht es seinen Plan. Symbol der individuellen, nicht der kollektiven Vorbereitung.', es: 'El arquetipo del "Preparador Humilde". La ardilla — sabe que es pequeña, pero hace su plan. Símbolo de la preparación individual, no colectiva.', pt: 'O arquétipo do "Preparador Humilde". O esquilo — sabe que é pequeno, mas faz o seu plano. Símbolo da preparação individual, não coletiva.', fr: 'L\'archétype du "Préparateur humble". L\'écureuil — il sait qu\'il est petit, mais il fait son plan. Symbole de la préparation individuelle, non collective.', ja: '「謙虚な備え手」の元型。リス——自分が小さいと知りつつ、計画を立てる。集団ではなく個の備えの象徴。' },
    dream: { tr: 'Sincap rüyada — geleceğe hazırlık zamanı. Yiyecek saklıyorsa: ekonomik/duygusal güvenlik için tedbir al. Atlıyorsa: çevik bir hamle gerekiyor.', en: 'Squirrel in dream — time to prepare for the future. Hoarding food: take measures for economic/emotional security. Leaping: an agile move is needed.', de: 'Eichhörnchen im Traum — Zeit, sich auf die Zukunft vorzubereiten. Hortet es Nahrung: Triff Vorkehrungen für wirtschaftliche/emotionale Sicherheit. Springt es: Ein flinker Zug ist nötig.', es: 'Ardilla en sueños — tiempo de prepararse para el futuro. Si guarda comida: toma medidas para la seguridad económica/emocional. Si salta: se necesita un movimiento ágil.', pt: 'Esquilo em sonho — tempo de te preparares para o futuro. Se guarda comida: toma medidas para a segurança económica/emocional. Se salta: é preciso um movimento ágil.', fr: 'Écureuil en rêve — le temps de se préparer à l\'avenir. Amassant de la nourriture : prends des mesures pour la sécurité économique/émotionnelle. Bondissant : un mouvement agile est nécessaire.', ja: '夢の中のリス——未来への備えの時。食べ物を蓄えるなら、経済的／感情的な安全のための手立てを取れ。跳ぶなら、機敏な一手が要る。' },
    shadow: { tr: 'Kaygılı biriktiricilik. "Yetmez" duygusuyla durmadan istiflemek — neşeyi kaçırır. Sincap aynı zamanda oynar; sadece çalışmaz.', en: 'Anxious hoarding. Stockpiling endlessly out of the feeling of "not enough" — joy is missed. The squirrel also plays; it does not only work.', de: 'Ängstliches Horten. Aus dem Gefühl "nicht genug" endlos zu bunkern — die Freude geht verloren. Das Eichhörnchen spielt auch; es arbeitet nicht nur.', es: 'Acumulación ansiosa. Almacenar sin fin por la sensación de "no es suficiente" — se pierde la alegría. La ardilla también juega; no solo trabaja.', pt: 'Acumulação ansiosa. Armazenar sem fim pela sensação de "não chega" — perde-se a alegria. O esquilo também brinca; não só trabalha.', fr: 'Accumulation anxieuse. Stocker sans fin par le sentiment de "pas assez" — la joie se perd. L\'écureuil joue aussi ; il ne fait pas que travailler.', ja: '不安からの溜め込み。「足りない」という思いから際限なく蓄えること——歓びを取り逃がす。リスは遊びもする。働くばかりではない。' },
    whenAppears: { tr: 'Bir kış dönemine girmeden önce, tasarruf veya enerji birikimine ihtiyaç duyulurken, hayatın size çeviklik gösterdiği anlarda.', en: 'Before entering a winter season, when savings or energy reserves are needed, in moments when life shows you agility.', de: 'Bevor du in eine Winterzeit eintrittst, wenn Ersparnisse oder Energiereserven nötig sind, in Momenten, in denen das Leben dir Wendigkeit zeigt.', es: 'Antes de entrar en una estación de invierno, cuando se necesitan ahorros o reservas de energía, en momentos en que la vida te muestra agilidad.', pt: 'Antes de entrar numa estação de inverno, quando são necessárias poupanças ou reservas de energia, em momentos em que a vida te mostra agilidade.', fr: 'Avant d\'entrer dans une saison d\'hiver, quand des économies ou des réserves d\'énergie sont nécessaires, dans les moments où la vie te montre l\'agilité.', ja: '冬の季節に入る前、蓄えやエネルギーの備えが要るとき、人生があなたに機敏さを示す瞬間に。' },
    traditions: [
      { culture: { tr: 'İskandinav', en: 'Norse', de: 'Nordisch', es: 'Nórdico', pt: 'Nórdico', fr: 'Nordique', ja: '北欧' }, meaning: { tr: 'Ratatoskr — dünya ağacı Yggdrasil\'de yukarı aşağı koşan haberci sincap. Tanrılar ile devler arasında mesaj taşır.', en: 'Ratatoskr — the messenger squirrel running up and down the world-tree Yggdrasil. Carries messages between the gods and the giants.', de: 'Ratatöskr — das Boten-Eichhörnchen, das den Weltenbaum Yggdrasil auf und ab läuft. Es trägt Botschaften zwischen Göttern und Riesen.', es: 'Ratatoskr — la ardilla mensajera que corre arriba y abajo del árbol del mundo Yggdrasil. Lleva mensajes entre los dioses y los gigantes.', pt: 'Ratatoskr — o esquilo mensageiro que corre para cima e para baixo na árvore do mundo Yggdrasil. Leva mensagens entre os deuses e os gigantes.', fr: 'Ratatoskr — l\'écureuil messager qui court de haut en bas de l\'arbre-monde Yggdrasil. Il porte des messages entre les dieux et les géants.', ja: 'ラタトスク——世界樹ユグドラシルを上下に駆ける使いのリス。神々と巨人のあいだで言葉を運ぶ。' } },
      { culture: { tr: 'Kelt', en: 'Celtic', de: 'Keltisch', es: 'Celta', pt: 'Celta', fr: 'Celtique', ja: 'ケルト' }, meaning: { tr: 'Hazırlık ve ileri görüşün sembolü. Druidlerin doğa öğretmenlerinden.', en: 'Symbol of preparation and foresight. One of the nature-teachers of the Druids.', de: 'Symbol der Vorbereitung und der Voraussicht. Einer der Naturlehrer der Druiden.', es: 'Símbolo de la preparación y la previsión. Uno de los maestros de la naturaleza de los druidas.', pt: 'Símbolo da preparação e da previsão. Um dos mestres da natureza dos druidas.', fr: 'Symbole de la préparation et de la prévoyance. L\'un des maîtres de la nature des druides.', ja: '備えと先見の象徴。ドルイドの自然の師の一つ。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Cherokee geleneğinde — küçüklüğünüze rağmen büyük katkı yapabilirsiniz mesajının habercisi.', en: 'In Cherokee tradition — the herald of the message that you can make a great contribution despite your smallness.', de: 'In der Cherokee-Tradition — der Herold der Botschaft, dass du trotz deiner Kleinheit einen großen Beitrag leisten kannst.', es: 'En la tradición cheroqui — el heraldo del mensaje de que puedes hacer una gran contribución pese a tu pequeñez.', pt: 'Na tradição cherokee — o arauto da mensagem de que podes dar uma grande contribuição apesar da tua pequenez.', fr: 'Dans la tradition cherokee — le héraut du message selon lequel tu peux apporter une grande contribution malgré ta petitesse.', ja: 'チェロキーの伝統において——小ささにもかかわらず大きな貢献ができるという報せの使者。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Karadeniz ormanlarında sevimli yoldaş. Çocuk masallarının küçük zeki kahramanı.', en: 'A beloved companion in the Black Sea forests. The small clever hero of children\'s tales.', de: 'Ein geliebter Gefährte in den Wäldern des Schwarzen Meeres. Der kleine kluge Held der Kindermärchen.', es: 'Un compañero querido en los bosques del Mar Negro. El pequeño héroe astuto de los cuentos infantiles.', pt: 'Um companheiro querido nas florestas do Mar Negro. O pequeno herói astuto dos contos infantis.', fr: 'Un compagnon aimé dans les forêts de la mer Noire. Le petit héros rusé des contes pour enfants.', ja: '黒海の森の愛される相棒。子どもの昔話の小さく賢い英雄。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Rama\'nın köprü inşasına yardım eden küçük sincap — büyük işlerde küçük katkılar.', en: 'The small squirrel that helps Rama build the bridge — small contributions to great works.', de: 'Das kleine Eichhörnchen, das Rama beim Brückenbau hilft — kleine Beiträge zu großen Werken.', es: 'La pequeña ardilla que ayuda a Rama a construir el puente — pequeñas contribuciones a grandes obras.', pt: 'O pequeno esquilo que ajuda Rama a construir a ponte — pequenas contribuições a grandes obras.', fr: 'Le petit écureuil qui aide Rama à construire le pont — petites contributions aux grandes œuvres.', ja: 'ラーマの橋づくりを助ける小さなリス——大いなる業への小さな貢献。' } },
    ],
    myths: [
      { tr: 'Ratatoskr ve Yggdrasil: İskandinav mitolojisinde dünya ağacı Yggdrasil\'in tepesindeki kartal ile köklerindeki ejderha arasında mesaj taşıyan haberci sincap. Çatışmayı körükler — söylenti yayıcı kötülük mü, gerekli aracı mı?', en: 'Ratatoskr and Yggdrasil: In Norse mythology, the messenger squirrel that carries messages between the eagle atop the world-tree Yggdrasil and the dragon at its roots. He stirs conflict — is he a gossip-spreading evil, or a necessary intermediary?', de: 'Ratatöskr und Yggdrasil: In der nordischen Mythologie das Boten-Eichhörnchen, das Botschaften zwischen dem Adler an der Spitze des Weltenbaums Yggdrasil und dem Drachen an seinen Wurzeln trägt. Es schürt den Streit — ist es ein gerüchteverbreitendes Übel oder ein notwendiger Vermittler?', es: 'Ratatoskr e Yggdrasil: En la mitología nórdica, la ardilla mensajera que lleva mensajes entre el águila en la copa del árbol del mundo Yggdrasil y el dragón en sus raíces. Aviva el conflicto — ¿es un mal que esparce chismes, o un intermediario necesario?', pt: 'Ratatoskr e Yggdrasil: Na mitologia nórdica, o esquilo mensageiro que leva mensagens entre a águia no topo da árvore do mundo Yggdrasil e o dragão nas suas raízes. Atiça o conflito — é um mal que espalha boatos, ou um intermediário necessário?', fr: 'Ratatoskr et Yggdrasil : Dans la mythologie nordique, l\'écureuil messager qui porte des messages entre l\'aigle au sommet de l\'arbre-monde Yggdrasil et le dragon à ses racines. Il attise le conflit — est-il un mal colporteur de ragots, ou un intermédiaire nécessaire ?', ja: 'ラタトスクとユグドラシル：北欧神話において、世界樹ユグドラシルの梢の鷲と根の竜のあいだで言葉を運ぶ使いのリス。争いをあおる——噂を撒く悪なのか、必要な仲立ちなのか?' },
      { tr: 'Rama\'nın Sincabı: Hint destanı Ramayana\'da Rama köprü inşa ederken küçük bir sincap kuma bulanıp suya atlayarak yardım eder. Rama parmaklarıyla sırtını okşar — sincapların sırtındaki üç çizgi o izden gelir. Büyük işte küçük katkı.', en: 'Rama\'s Squirrel: In the Hindu epic Ramayana, while Rama is building the bridge, a small squirrel helps by rolling in sand and leaping into the water. Rama strokes its back with his fingers — the three stripes on squirrels\' backs come from that touch. A small contribution to a great work.', de: 'Ramas Eichhörnchen: Im hinduistischen Epos Ramayana hilft beim Brückenbau ein kleines Eichhörnchen, indem es sich im Sand wälzt und ins Wasser springt. Rama streicht ihm mit den Fingern über den Rücken — die drei Streifen auf dem Rücken der Eichhörnchen stammen von jener Berührung. Ein kleiner Beitrag zu einem großen Werk.', es: 'La ardilla de Rama: En la epopeya hindú Ramayana, mientras Rama construye el puente, una pequeña ardilla ayuda revolcándose en la arena y saltando al agua. Rama le acaricia el lomo con los dedos — las tres rayas del lomo de las ardillas vienen de aquel toque. Una pequeña contribución a una gran obra.', pt: 'O esquilo de Rama: Na epopeia hindu Ramayana, enquanto Rama constrói a ponte, um pequeno esquilo ajuda rolando na areia e saltando para a água. Rama acaricia-lhe as costas com os dedos — as três riscas nas costas dos esquilos vêm desse toque. Uma pequena contribuição a uma grande obra.', fr: 'L\'écureuil de Rama : Dans l\'épopée hindoue Ramayana, alors que Rama construit le pont, un petit écureuil aide en se roulant dans le sable et en sautant dans l\'eau. Rama lui caresse le dos de ses doigts — les trois rayures sur le dos des écureuils viennent de ce contact. Une petite contribution à une grande œuvre.', ja: 'ラーマのリス：ヒンドゥー叙事詩ラーマーヤナにおいて、ラーマが橋を築くとき、小さなリスが砂にまみれて水に飛び込み手伝う。ラーマは指でその背を撫でる——リスの背の三本の筋はその触れ跡から来ている。大いなる業への小さな貢献。' },
    ],
  },

  // ─── a046 Yarasa ────────────────────────────────────────────────────────
  a046: {
    jung: { tr: '"Eşik Bekçisi" arketipi. Yarasa — gece ile gündüz, yer ile gök, ölüm ile hayat arasında. Liminal varlık.', en: 'The "Threshold Keeper" archetype. The bat — between night and day, earth and sky, death and life. A liminal being.', de: 'Der Archetyp des "Schwellenhüters". Die Fledermaus — zwischen Nacht und Tag, Erde und Himmel, Tod und Leben. Ein liminales Wesen.', es: 'El arquetipo del "Guardián del Umbral". El murciélago — entre la noche y el día, la tierra y el cielo, la muerte y la vida. Un ser liminal.', pt: 'O arquétipo do "Guardião do Limiar". O morcego — entre a noite e o dia, a terra e o céu, a morte e a vida. Um ser liminar.', fr: 'L\'archétype du "Gardien du seuil". La chauve-souris — entre la nuit et le jour, la terre et le ciel, la mort et la vie. Un être liminal.', ja: '「敷居の番人」の元型。コウモリ——夜と昼、地と天、死と生のあいだに。境界の存在。' },
    dream: { tr: 'Yarasa rüyada — bir geçiş eşiğindesin, eski sen ölüyor. Mağaradan çıkıyorsa: gölge çalışmandan dönüyorsun. Sana yaklaşıyorsa: sezgi mesajı taşıyor.', en: 'Bat in dream — you are at a threshold of passage, the old self is dying. Coming out of the cave: you are returning from shadow work. Approaching you: it carries an intuitive message.', de: 'Fledermaus im Traum — du stehst an einer Schwelle des Übergangs, das alte Selbst stirbt. Kommt sie aus der Höhle: Du kehrst aus der Schattenarbeit zurück. Nähert sie sich dir: Sie trägt eine intuitive Botschaft.', es: 'Murciélago en sueños — estás en un umbral de paso, el viejo yo muere. Si sale de la cueva: regresas del trabajo de sombra. Si se acerca: porta un mensaje intuitivo.', pt: 'Morcego em sonho — estás num limiar de passagem, o velho eu morre. Se sai da caverna: regressas do trabalho de sombra. Se se aproxima: carrega uma mensagem intuitiva.', fr: 'Chauve-souris en rêve — tu es à un seuil de passage, l\'ancien soi meurt. Sortant de la grotte : tu reviens du travail de l\'ombre. S\'approchant : elle porte un message intuitif.', ja: '夢の中のコウモリ——あなたは移行の境にあり、古い自己が死につつある。洞窟から出てくるなら、影の仕事から戻っている。近づくなら、直感の報せを運んでいる。' },
    shadow: { tr: 'Yapışkan korkular. Yarasalardan korkanlar genelde dönüşümden korkar. Yarasa fobisi — eski kimliği bırakmaktan kaçınma.', en: 'Clinging fears. Those who fear bats generally fear transformation. Bat-phobia — avoidance of releasing the old identity.', de: 'Klammernde Ängste. Wer Fledermäuse fürchtet, fürchtet meist die Verwandlung. Fledermausphobie — die Vermeidung, die alte Identität loszulassen.', es: 'Miedos aferrados. Quienes temen a los murciélagos suelen temer la transformación. La fobia al murciélago — la evitación de soltar la vieja identidad.', pt: 'Medos agarrados. Quem teme os morcegos geralmente teme a transformação. A fobia do morcego — a evitação de largar a velha identidade.', fr: 'Peurs accrochées. Ceux qui craignent les chauves-souris craignent généralement la transformation. La phobie de la chauve-souris — l\'évitement de lâcher l\'ancienne identité.', ja: 'まとわりつく恐れ。コウモリを恐れる者はたいてい変容を恐れる。コウモリ恐怖症——古いアイデンティティを手放すことの回避。' },
    whenAppears: { tr: 'Karanlık dönemlerde, ölüm-yas süreçlerinde, sezgini körlemesine kullanman gerekirken (ekolokasyon — görmeden duyma).', en: 'In dark periods, in death-grief processes, when you must use your intuition blindly (echolocation — hearing without seeing).', de: 'In dunklen Zeiten, in Trauerprozessen um den Tod, wenn du deine Intuition blind gebrauchen musst (Echolot — Hören ohne Sehen).', es: 'En períodos oscuros, en procesos de duelo por la muerte, cuando debes usar tu intuición a ciegas (ecolocalización — oír sin ver).', pt: 'Em períodos sombrios, em processos de luto pela morte, quando deves usar a tua intuição às cegas (ecolocalização — ouvir sem ver).', fr: 'Dans les périodes sombres, dans les processus de deuil de la mort, quand tu dois user de ton intuition à l\'aveugle (écholocation — entendre sans voir).', ja: '暗い時期、死と喪の過程において、見えぬまま直感を使わねばならぬとき（反響定位——見ずして聞くこと）に。' },
    traditions: [
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Fu — "yarasa" ve "şans" aynı sesle telaffuz edilir. Beş yarasa = beş kutsama (uzun ömür, zenginlik, sağlık, erdem, doğal ölüm).', en: 'Fu — "bat" and "fortune" are pronounced alike. Five bats = the five blessings (longevity, wealth, health, virtue, a natural death).', de: 'Fu — "Fledermaus" und "Glück" werden gleich ausgesprochen. Fünf Fledermäuse = die fünf Segnungen (Langlebigkeit, Reichtum, Gesundheit, Tugend, natürlicher Tod).', es: 'Fu — "murciélago" y "fortuna" se pronuncian igual. Cinco murciélagos = las cinco bendiciones (longevidad, riqueza, salud, virtud, muerte natural).', pt: 'Fu — "morcego" e "fortuna" pronunciam-se igual. Cinco morcegos = as cinco bênçãos (longevidade, riqueza, saúde, virtude, morte natural).', fr: 'Fu — "chauve-souris" et "fortune" se prononcent de même. Cinq chauves-souris = les cinq bénédictions (longévité, richesse, santé, vertu, mort naturelle).', ja: '福（フー）——「コウモリ」と「幸運」は同じ音で読まれる。五匹のコウモリ＝五福（長寿、富、健康、徳、天寿）。' } },
      { culture: { tr: 'Maya/Aztek', en: 'Mayan/Aztec', de: 'Maya/Aztekisch', es: 'Maya/Azteca', pt: 'Maia/Asteca', fr: 'Maya/Aztèque', ja: 'マヤ／アステカ' }, meaning: { tr: 'Camazotz — yarasa tanrı. Geçişin ve gece âleminin habercisi.', en: 'Camazotz — the bat god. Herald of passage and the nocturnal realm.', de: 'Camazotz — der Fledermausgott. Herold des Übergangs und des nächtlichen Reichs.', es: 'Camazotz — el dios murciélago. Heraldo del paso y del reino nocturno.', pt: 'Camazotz — o deus morcego. Arauto da passagem e do reino noturno.', fr: 'Camazotz — le dieu chauve-souris. Héraut du passage et du royaume nocturne.', ja: 'カマソッツ——コウモリの神。移行と夜の領域の使者。' } },
      { culture: { tr: 'Anadolu Halk', en: 'Anatolian Folk', de: 'Anatolische Volkskultur', es: 'Folclore Anatolio', pt: 'Folclore Anatólio', fr: 'Folklore Anatolien', ja: 'アナトリア民俗' }, meaning: { tr: 'Uğursuz sayılır ama eski Şaman geleneğinde — ata ruhların habercisi.', en: 'Considered ill-omened, yet in the old shamanic tradition — the messenger of ancestral spirits.', de: 'Als Unglücksbote angesehen, doch in der alten schamanischen Tradition — der Bote der Ahnengeister.', es: 'Considerado de mal agüero, pero en la antigua tradición chamánica — el mensajero de los espíritus ancestrales.', pt: 'Considerado de mau agouro, mas na antiga tradição xamânica — o mensageiro dos espíritos ancestrais.', fr: 'Tenu pour de mauvais augure, mais dans l\'ancienne tradition chamanique — le messager des esprits ancestraux.', ja: '不吉とされるが、古のシャーマンの伝統では——祖霊の使者。' } },
      { culture: { tr: 'Hristiyan', en: 'Christian', de: 'Christlich', es: 'Cristiano', pt: 'Cristão', fr: 'Chrétien', ja: 'キリスト教' }, meaning: { tr: 'Orta Çağ\'da şeytanın kuşu sayıldı — gece ve karanlıkla özdeşleştirildi.', en: 'In the Middle Ages, considered the devil\'s bird — identified with night and darkness.', de: 'Im Mittelalter galt sie als Vogel des Teufels — mit Nacht und Finsternis gleichgesetzt.', es: 'En la Edad Media, considerado el ave del diablo — identificado con la noche y la oscuridad.', pt: 'Na Idade Média, considerado a ave do diabo — identificado com a noite e a escuridão.', fr: 'Au Moyen Âge, tenue pour l\'oiseau du diable — identifiée à la nuit et aux ténèbres.', ja: '中世においては悪魔の鳥とされた——夜と闇に同一視された。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Bazı kabilelerde — eski kişinin ölüp yeni kişinin doğuşu için rehber.', en: 'In some tribes — the guide for the death of the old self and the birth of the new.', de: 'In manchen Stämmen — der Führer für den Tod des alten Selbst und die Geburt des neuen.', es: 'En algunas tribus — el guía para la muerte del viejo yo y el nacimiento del nuevo.', pt: 'Em algumas tribos — o guia para a morte do velho eu e o nascimento do novo.', fr: 'Dans certaines tribus — le guide pour la mort de l\'ancien soi et la naissance du nouveau.', ja: '一部の部族において——古い自己の死と新しい自己の誕生のための導き手。' } },
    ],
    myths: [
      { tr: 'Çin\'in Beş Yarasası: Çin geleneğinde beş yarasa motifi (wufu) — şans, zenginlik, uzun ömür, erdem, doğal ölüm. Düğün ve yılbaşı süslemelerinde çok kullanılır. Korkulan hayvan kutsama olur.', en: 'China\'s Five Bats: In Chinese tradition, the motif of five bats (wufu) — fortune, wealth, longevity, virtue, a natural death. Widely used in wedding and New Year decorations. The feared animal becomes a blessing.', de: 'Chinas fünf Fledermäuse: In der chinesischen Tradition das Motiv der fünf Fledermäuse (wufu) — Glück, Reichtum, Langlebigkeit, Tugend, natürlicher Tod. Häufig in Hochzeits- und Neujahrsdekorationen. Das gefürchtete Tier wird zum Segen.', es: 'Los cinco murciélagos de China: En la tradición china, el motivo de los cinco murciélagos (wufu) — fortuna, riqueza, longevidad, virtud, muerte natural. Muy usado en decoraciones de boda y Año Nuevo. El animal temido se vuelve bendición.', pt: 'Os cinco morcegos da China: Na tradição chinesa, o motivo dos cinco morcegos (wufu) — fortuna, riqueza, longevidade, virtude, morte natural. Muito usado em decorações de casamento e Ano Novo. O animal temido torna-se bênção.', fr: 'Les cinq chauves-souris de Chine : Dans la tradition chinoise, le motif des cinq chauves-souris (wufu) — fortune, richesse, longévité, vertu, mort naturelle. Très utilisé dans les décorations de mariage et de Nouvel An. L\'animal craint devient bénédiction.', ja: '中国の五匹のコウモリ：中国の伝統における五匹のコウモリの文様（五福）——幸運、富、長寿、徳、天寿。婚礼や正月の飾りに多く用いられる。恐れられた動物が祝福となる。' },
      { tr: 'Camazotz Mağarası: Maya mitolojisinde kahramanlar ölüler diyarı Xibalba\'da Yarasa Mağarası\'ndan geçmek zorundadır. Yarasalar onları sınar — bilgeliği almak için ölüme yaklaşmak gerek.', en: 'The Cave of Camazotz: In Mayan mythology, heroes must pass through the Bat Cave in Xibalba, the land of the dead. The bats test them — to receive wisdom, one must draw near to death.', de: 'Die Höhle des Camazotz: In der Maya-Mythologie müssen die Helden in Xibalba, dem Totenreich, die Fledermaushöhle durchqueren. Die Fledermäuse prüfen sie — um Weisheit zu empfangen, muss man sich dem Tod nähern.', es: 'La cueva de Camazotz: En la mitología maya, los héroes deben atravesar la Cueva de los Murciélagos en Xibalbá, la tierra de los muertos. Los murciélagos los ponen a prueba — para recibir sabiduría, hay que acercarse a la muerte.', pt: 'A caverna de Camazotz: Na mitologia maia, os heróis devem atravessar a Caverna dos Morcegos em Xibalba, a terra dos mortos. Os morcegos põem-nos à prova — para receber a sabedoria, é preciso aproximar-se da morte.', fr: 'La grotte de Camazotz : Dans la mythologie maya, les héros doivent traverser la Grotte des Chauves-souris à Xibalba, le pays des morts. Les chauves-souris les éprouvent — pour recevoir la sagesse, il faut s\'approcher de la mort.', ja: 'カマソッツの洞窟：マヤ神話において、英雄たちは死者の国シバルバーのコウモリの洞窟を通らねばならない。コウモリは彼らを試す——知恵を得るには、死に近づかねばならない。' },
    ],
  },

  // ─── a047 Yengeç ────────────────────────────────────────────────────────
  a047: {
    jung: { tr: '"Ana-Kabuk" arketipi. Yengeç — evi bedeninde taşır. Duygusal güvenliğin, içe çekilmenin, sınırın sembolü.', en: 'The "Mother-Shell" archetype. The crab — carrying its home on its body. Symbol of emotional safety, withdrawal, and boundary.', de: 'Der Archetyp der "Mutter-Schale". Die Krabbe — trägt ihr Heim am Leib. Symbol der emotionalen Geborgenheit, des Rückzugs und der Grenze.', es: 'El arquetipo de la "Madre-Caparazón". El cangrejo — lleva su hogar en el cuerpo. Símbolo de la seguridad emocional, el repliegue y el límite.', pt: 'O arquétipo da "Mãe-Carapaça". O caranguejo — carrega o seu lar no corpo. Símbolo da segurança emocional, do recolhimento e do limite.', fr: 'L\'archétype de la "Mère-Carapace". Le crabe — il porte sa demeure sur son corps. Symbole de la sécurité émotionnelle, du repli et de la limite.', ja: '「母なる甲羅」の元型。カニ——我が家を体に背負う。感情の安全、内へ退くこと、境界の象徴。' },
    dream: { tr: 'Yengeç rüyada — bir savunma ihtiyacın var. Kabuğunun içine girmen meşru. Pençeleriyle bir şey tutuyorsa: bırakmıyorsun, bırak mı bırakma mı bir bak.', en: 'Crab in dream — you have a need for defense. To withdraw into your shell is legitimate. Holding something in its claws: you are not letting go — look at whether you should release it or not.', de: 'Krabbe im Traum — du hast ein Bedürfnis nach Verteidigung. Sich in den Panzer zurückzuziehen ist legitim. Hält sie etwas in den Scheren: Du lässt nicht los — sieh nach, ob du es loslassen solltest oder nicht.', es: 'Cangrejo en sueños — tienes una necesidad de defensa. Replegarte en tu caparazón es legítimo. Si sujeta algo con sus pinzas: no sueltas — mira si debes soltarlo o no.', pt: 'Caranguejo em sonho — tens uma necessidade de defesa. Recolheres-te na carapaça é legítimo. Se segura algo nas pinças: não largas — vê se deves soltá-lo ou não.', fr: 'Crabe en rêve — tu as un besoin de défense. Te replier dans ta carapace est légitime. Tenant quelque chose dans ses pinces : tu ne lâches pas — regarde si tu dois le relâcher ou non.', ja: '夢の中のカニ——あなたには防御の必要がある。甲羅に引きこもるのは正当だ。爪で何かを掴んでいるなら、あなたは手放していない——放すべきか否か、見極めよ。' },
    shadow: { tr: 'Kabuğa kapanma takıntısı. Yengeç hep içe çekilirse — duygusal hareketsizlik. Pençeler de bir şeyi hiç bırakmamak da olabilir.', en: 'The compulsion to close into the shell. If the crab always withdraws — emotional paralysis. The claws may also mean never letting anything go.', de: 'Der Zwang, sich in den Panzer zu verschließen. Zieht sich die Krabbe stets zurück — emotionale Erstarrung. Die Scheren können auch bedeuten, niemals etwas loszulassen.', es: 'La compulsión de cerrarse en el caparazón. Si el cangrejo siempre se repliega — parálisis emocional. Las pinzas también pueden significar no soltar nunca nada.', pt: 'A compulsão de fechar-se na carapaça. Se o caranguejo se recolhe sempre — paralisia emocional. As pinças também podem significar nunca largar nada.', fr: 'La compulsion de se fermer dans la carapace. Si le crabe se replie toujours — paralysie émotionnelle. Les pinces peuvent aussi signifier ne jamais rien lâcher.', ja: '甲羅に閉じこもる強迫。カニが常に引きこもれば——感情の麻痺。爪は、何ひとつ手放さないことを意味することもある。' },
    whenAppears: { tr: 'Sınır koymak gerektiğinde, eve dönmek istediğinde, ay döngüsünün etkili olduğu duygusal anlarda, geri çekilme zamanında.', en: 'When you must set a boundary, when you wish to return home, in emotional moments under the moon\'s influence, in a time of withdrawal.', de: 'Wenn du eine Grenze setzen musst, wenn du nach Hause zurückkehren willst, in emotionalen Momenten unter dem Einfluss des Mondes, in einer Zeit des Rückzugs.', es: 'Cuando debes poner un límite, cuando deseas volver a casa, en momentos emocionales bajo la influencia de la luna, en un tiempo de repliegue.', pt: 'Quando deves impor um limite, quando desejas regressar a casa, em momentos emocionais sob a influência da lua, num tempo de recolhimento.', fr: 'Quand tu dois poser une limite, quand tu souhaites rentrer à la maison, dans les moments émotionnels sous l\'influence de la lune, en un temps de repli.', ja: '境界を引かねばならぬとき、家に帰りたいとき、月の影響下の感情的な瞬間に、退く時に。' },
    traditions: [
      { culture: { tr: 'Astroloji', en: 'Astrology', de: 'Astrologie', es: 'Astrología', pt: 'Astrologia', fr: 'Astrologie', ja: '占星術' }, meaning: { tr: 'Yengeç burcu — Ay ile yönetilen ev, anne, duygusal kök. Suyun ilk burcu.', en: 'The sign of Cancer — moon-ruled home, mother, emotional root. The first water sign.', de: 'Das Sternzeichen Krebs — das mondbeherrschte Heim, die Mutter, die emotionale Wurzel. Das erste Wasserzeichen.', es: 'El signo de Cáncer — el hogar regido por la luna, la madre, la raíz emocional. El primer signo de agua.', pt: 'O signo de Caranguejo — o lar regido pela lua, a mãe, a raiz emocional. O primeiro signo de água.', fr: 'Le signe du Cancer — le foyer régi par la lune, la mère, la racine émotionnelle. Le premier signe d\'eau.', ja: '蟹座——月に支配される家、母、感情の根。最初の水の星座。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Hera, Herakles\'i öldürmek için bir yengeç gönderir. Yengeç ezilir — Hera onu gökyüzüne, Yengeç takımyıldızına koyar.', en: 'Hera sends a crab to kill Heracles. The crab is crushed — Hera places it in the sky as the constellation Cancer.', de: 'Hera sendet eine Krabbe, um Herakles zu töten. Die Krabbe wird zerquetscht — Hera setzt sie als Sternbild Krebs an den Himmel.', es: 'Hera envía un cangrejo para matar a Heracles. El cangrejo es aplastado — Hera lo coloca en el cielo como la constelación de Cáncer.', pt: 'Hera envia um caranguejo para matar Héracles. O caranguejo é esmagado — Hera coloca-o no céu como a constelação de Caranguejo.', fr: 'Héra envoie un crabe pour tuer Héraclès. Le crabe est écrasé — Héra le place dans le ciel comme la constellation du Cancer.', ja: 'ヘラはヘラクレスを殺すためカニを送る。カニは押し潰される——ヘラはそれを天に置き、蟹座とする。' } },
      { culture: { tr: 'Çin', en: 'Chinese', de: 'Chinesisch', es: 'Chino', pt: 'Chinês', fr: 'Chinois', ja: '中国' }, meaning: { tr: 'Sonbahar ve hasat sembolü. Mooncake döneminde yenir.', en: 'Symbol of autumn and harvest. Eaten in the mooncake season.', de: 'Symbol des Herbstes und der Ernte. Wird zur Mondkuchen-Zeit gegessen.', es: 'Símbolo del otoño y la cosecha. Se come en la temporada de los pasteles de luna.', pt: 'Símbolo do outono e da colheita. Come-se na época dos bolos da lua.', fr: 'Symbole de l\'automne et de la récolte. On le mange à la saison des gâteaux de lune.', ja: '秋と収穫の象徴。月餅の時期に食べられる。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Karkata rashi — Ay\'ın evi. Anneliğin ve emosyonel zeminin yıldız evi.', en: 'Karkata rashi — the Moon\'s house. The stellar house of motherhood and emotional ground.', de: 'Karkata rashi — das Haus des Mondes. Das Sternenhaus der Mutterschaft und des emotionalen Grundes.', es: 'Karkata rashi — la casa de la Luna. La casa estelar de la maternidad y el suelo emocional.', pt: 'Karkata rashi — a casa da Lua. A casa estelar da maternidade e do solo emocional.', fr: 'Karkata rashi — la maison de la Lune. La maison stellaire de la maternité et du sol émotionnel.', ja: 'カルカタ・ラーシ——月の宮。母性と感情の基盤の星宮。' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian', de: 'Anatolisch', es: 'Anatolio', pt: 'Anatólio', fr: 'Anatolien', ja: 'アナトリア' }, meaning: { tr: 'Akdeniz balıkçı köylerinde "kara yengeç" — uğurlu sayılır, asla öldürülmez sadece yakalandığı yere bırakılır.', en: 'In Mediterranean fishing villages, the "black crab" — considered fortunate; never killed, only returned to where it was caught.', de: 'In Fischerdörfern am Mittelmeer die "schwarze Krabbe" — gilt als Glücksbringer; nie getötet, nur dorthin zurückgesetzt, wo sie gefangen wurde.', es: 'En los pueblos pesqueros mediterráneos, el "cangrejo negro" — se considera afortunado; nunca se mata, solo se devuelve al lugar donde fue capturado.', pt: 'Nas aldeias piscatórias mediterrânicas, o "caranguejo negro" — considerado afortunado; nunca é morto, apenas devolvido ao lugar onde foi apanhado.', fr: 'Dans les villages de pêcheurs méditerranéens, le "crabe noir" — tenu pour porte-bonheur ; jamais tué, seulement remis là où il a été pris.', ja: '地中海の漁村における「黒カニ」——縁起がよいとされ、決して殺されず、捕らえた場所へ戻されるだけ。' } },
    ],
    myths: [
      { tr: 'Herakles ve Yengeç: Hera yengeci Herakles\'in topuğunu ısırması için gönderir. Kahraman ezer, ama Hera kuşun sadakatine değer verir ve onu gökyüzüne yerleştirir — Yengeç (Cancer) takımyıldızı. Küçük sadakat bile kutsanır.', en: 'Heracles and the Crab: Hera sends the crab to bite Heracles\'s heel. The hero crushes it, but Hera values the creature\'s loyalty and places it in the sky — the constellation Cancer. Even small loyalty is blessed.', de: 'Herakles und die Krabbe: Hera sendet die Krabbe, um Herakles in die Ferse zu beißen. Der Held zertritt sie, doch Hera schätzt die Treue des Geschöpfs und setzt es an den Himmel — das Sternbild Krebs. Selbst kleine Treue wird gesegnet.', es: 'Heracles y el cangrejo: Hera envía al cangrejo a morder el talón de Heracles. El héroe lo aplasta, pero Hera valora la lealtad de la criatura y la coloca en el cielo — la constelación de Cáncer. Incluso la pequeña lealtad es bendecida.', pt: 'Héracles e o caranguejo: Hera envia o caranguejo para morder o calcanhar de Héracles. O herói esmaga-o, mas Hera valoriza a lealdade da criatura e coloca-a no céu — a constelação de Caranguejo. Até a pequena lealdade é abençoada.', fr: 'Héraclès et le crabe : Héra envoie le crabe mordre le talon d\'Héraclès. Le héros l\'écrase, mais Héra estime la loyauté de la créature et la place dans le ciel — la constellation du Cancer. Même la petite loyauté est bénie.', ja: 'ヘラクレスとカニ：ヘラはヘラクレスの踵を噛ませるためカニを送る。英雄は押し潰すが、ヘラはその生き物の忠誠を尊び、天に据える——蟹座。小さな忠誠さえも祝福される。' },
      { tr: 'Yengeç Hareketi: "Yengeç yürüyüşü" deyimi — geri geri gitmek, dolambaçlı yol. Ama yengeç boş yere geri gitmez; tehlikeyi kabuğuyla geriye iter. Sezgisel savunma.', en: 'The Crab\'s Movement: The expression "crab walk" — moving backward, on a winding path. Yet the crab does not retreat in vain; it pushes danger back with its shell. Intuitive defense.', de: 'Die Bewegung der Krabbe: Der Ausdruck "Krebsgang" — rückwärtsgehen, auf gewundenem Weg. Doch die Krabbe weicht nicht umsonst zurück; sie drängt mit ihrem Panzer die Gefahr ab. Intuitive Verteidigung.', es: 'El movimiento del cangrejo: La expresión "andar de cangrejo" — moverse hacia atrás, por un camino sinuoso. Pero el cangrejo no retrocede en vano; empuja el peligro con su caparazón. Defensa intuitiva.', pt: 'O movimento do caranguejo: A expressão "andar de caranguejo" — mover-se para trás, por um caminho sinuoso. Mas o caranguejo não recua em vão; empurra o perigo com a carapaça. Defesa intuitiva.', fr: 'Le mouvement du crabe : L\'expression "marche du crabe" — reculer, sur un chemin sinueux. Mais le crabe ne recule pas en vain ; il repousse le danger de sa carapace. Défense intuitive.', ja: 'カニの動き：「カニ歩き」という言い回し——後ろ向きに、曲がりくねった道を進むこと。だがカニは無駄に後退するのではない。甲羅で危険を押し返す。直感的な防御。' },
    ],
  },

  // ─── a048 Fil ───────────────────────────────────────────────────────────
  a048: {
    jung: { tr: '"Büyük Hafıza" arketipi. Fil — yıllar boyu hatırlar, ama hatırlamayla yaşamaz. Yargısız bellek.', en: 'The "Great Memory" archetype. The elephant — remembers across years, yet does not live by remembering. Memory without judgment.', de: 'Der Archetyp des "großen Gedächtnisses". Der Elefant — erinnert sich über Jahre, doch lebt er nicht vom Erinnern. Gedächtnis ohne Urteil.', es: 'El arquetipo de la "Gran Memoria". El elefante — recuerda a lo largo de los años, pero no vive del recuerdo. Memoria sin juicio.', pt: 'O arquétipo da "Grande Memória". O elefante — recorda ao longo dos anos, mas não vive do recordar. Memória sem juízo.', fr: 'L\'archétype de la "Grande Mémoire". L\'éléphant — se souvient au fil des ans, mais ne vit pas du souvenir. Mémoire sans jugement.', ja: '「大いなる記憶」の元型。ゾウ——長年にわたり覚えているが、覚えていることで生きはしない。裁きなき記憶。' },
    dream: { tr: 'Fil rüyada — geçmişten gelen bir bilgi/duygu yüzeye çıkıyor. Aileyle: kolektif bellek. Yalnız: kişisel ağırlık.', en: 'Elephant in dream — a knowledge or feeling from the past is surfacing. With family: collective memory. Alone: personal weight.', de: 'Elefant im Traum — ein Wissen oder Gefühl aus der Vergangenheit steigt an die Oberfläche. Mit Familie: kollektives Gedächtnis. Allein: persönliche Last.', es: 'Elefante en sueños — un conocimiento o sentimiento del pasado aflora. Con la familia: memoria colectiva. Solo: peso personal.', pt: 'Elefante em sonho — um conhecimento ou sentimento do passado aflora. Com a família: memória coletiva. Sozinho: peso pessoal.', fr: 'Éléphant en rêve — un savoir ou un sentiment du passé remonte à la surface. Avec la famille : mémoire collective. Seul : poids personnel.', ja: '夢の中のゾウ——過去から来る知や感情が浮かび上がる。家族とともになら、集団の記憶。一頭なら、個人の重み。' },
    shadow: { tr: '"Hiçbir şeyi unutmama" yükü. Affediş olmadan bellek hapse dönüşür. Fil hatırlar — ama bilge fil yara izini hayata değil tarihe bırakır.', en: 'The burden of "forgetting nothing". Without forgiveness, memory becomes a prison. The elephant remembers — but the wise elephant leaves the scar to history, not to life.', de: 'Die Last des "Nichts-Vergessens". Ohne Vergebung wird das Gedächtnis zum Gefängnis. Der Elefant erinnert sich — doch der weise Elefant überlässt die Narbe der Geschichte, nicht dem Leben.', es: 'La carga de "no olvidar nada". Sin perdón, la memoria se vuelve prisión. El elefante recuerda — pero el elefante sabio deja la cicatriz a la historia, no a la vida.', pt: 'O fardo de "não esquecer nada". Sem perdão, a memória torna-se prisão. O elefante recorda — mas o elefante sábio deixa a cicatriz à história, não à vida.', fr: 'Le fardeau de "ne rien oublier". Sans pardon, la mémoire devient prison. L\'éléphant se souvient — mais l\'éléphant sage laisse la cicatrice à l\'histoire, non à la vie.', ja: '「何ひとつ忘れない」という重荷。許しなくば、記憶は牢獄となる。ゾウは覚えている——だが賢いゾウは傷跡を人生にではなく歴史に委ねる。' },
    whenAppears: { tr: 'Geçmişle yüzleşme zamanlarında, atalardan miras gelen yükleri taşırken, büyük ailedeki rolünü kabul ettiğinde.', en: 'In times of facing the past, while carrying burdens inherited from the ancestors, when you accept your role in the larger family.', de: 'In Zeiten, in denen du dich der Vergangenheit stellst, während du von den Ahnen ererbte Lasten trägst, wenn du deine Rolle in der größeren Familie annimmst.', es: 'En tiempos de enfrentar el pasado, mientras cargas con fardos heredados de los antepasados, cuando aceptas tu papel en la familia más amplia.', pt: 'Em tempos de enfrentar o passado, enquanto carregas fardos herdados dos antepassados, quando aceitas o teu papel na família mais ampla.', fr: 'Dans les temps où tu affrontes le passé, en portant des fardeaux hérités des ancêtres, quand tu acceptes ton rôle dans la famille élargie.', ja: '過去と向き合う時に、先祖から受け継いだ重荷を担うとき、より大きな家族の中での役割を受け入れるときに。' },
    traditions: [
      { culture: { tr: 'Hint', en: 'Hindu', de: 'Hinduistisch', es: 'Hindú', pt: 'Hindu', fr: 'Hindou', ja: 'ヒンドゥー' }, meaning: { tr: 'Ganeşa — fil başlı tanrı. Engellerin kaldırıcısı, başlangıçların koruyucusu.', en: 'Ganesha — the elephant-headed god. Remover of obstacles, protector of beginnings.', de: 'Ganesha — der elefantenköpfige Gott. Beseitiger der Hindernisse, Beschützer der Anfänge.', es: 'Ganesha — el dios con cabeza de elefante. Removedor de obstáculos, protector de los comienzos.', pt: 'Ganesha — o deus com cabeça de elefante. Removedor de obstáculos, protetor dos começos.', fr: 'Ganesha — le dieu à tête d\'éléphant. Ôteur d\'obstacles, protecteur des commencements.', ja: 'ガネーシャ——ゾウの頭をもつ神。障害を取り除く者、始まりの守護者。' } },
      { culture: { tr: 'Budist', en: 'Buddhist', de: 'Buddhistisch', es: 'Budista', pt: 'Budista', fr: 'Bouddhiste', ja: '仏教' }, meaning: { tr: 'Buddha\'nın annesi Maya, hamile kalırken rüyasında beyaz bir fil görür — kutsal doğumun habercisi.', en: 'Buddha\'s mother Maya, while conceiving, dreams of a white elephant — herald of the sacred birth.', de: 'Buddhas Mutter Maya träumt bei der Empfängnis von einem weißen Elefanten — Herold der heiligen Geburt.', es: 'La madre de Buda, Maya, al concebir, sueña con un elefante blanco — heraldo del nacimiento sagrado.', pt: 'A mãe de Buda, Maya, ao conceber, sonha com um elefante branco — arauto do nascimento sagrado.', fr: 'La mère de Bouddha, Maya, en concevant, rêve d\'un éléphant blanc — héraut de la naissance sacrée.', ja: 'ブッダの母マーヤーは、懐妊の際に白いゾウの夢を見る——聖なる誕生の使者。' } },
      { culture: { tr: 'Vedik', en: 'Vedic', de: 'Vedisch', es: 'Védico', pt: 'Védico', fr: 'Védique', ja: 'ヴェーダ' }, meaning: { tr: 'Airavata — Indra\'nın beyaz fil bineği. Yağmur ve bereketin getiricisi.', en: 'Airavata — Indra\'s white elephant mount. Bringer of rain and abundance.', de: 'Airavata — Indras weißes Elefantenreittier. Bringer von Regen und Überfluss.', es: 'Airavata — la montura de elefante blanco de Indra. Portador de lluvia y abundancia.', pt: 'Airavata — a montaria de elefante branco de Indra. Portador de chuva e abundância.', fr: 'Airavata — la monture éléphant blanc d\'Indra. Porteur de pluie et d\'abondance.', ja: 'アイラーヴァタ——インドラの白いゾウの乗り物。雨と豊穣をもたらす者。' } },
      { culture: { tr: 'Sufi-İslam', en: 'Sufi-Islamic', de: 'Sufisch-Islamisch', es: 'Sufí-Islámico', pt: 'Sufi-Islâmico', fr: 'Soufi-Islamique', ja: 'スーフィー・イスラーム' }, meaning: { tr: 'Mevlana\'nın "Karanlıkta Fil" hikayesi — herkes filin farklı parçasına dokunur, farklı şeyler tarif eder. Gerçek — bütünündedir.', en: 'Rumi\'s story "The Elephant in the Dark" — each touches a different part of the elephant and describes different things. The truth lies in the whole.', de: 'Rumis Geschichte "Der Elefant im Dunkeln" — jeder berührt einen anderen Teil des Elefanten und beschreibt anderes. Die Wahrheit liegt im Ganzen.', es: 'La historia de Rumi "El elefante en la oscuridad" — cada uno toca una parte distinta del elefante y describe cosas distintas. La verdad reside en el todo.', pt: 'A história de Rumi "O elefante na escuridão" — cada um toca uma parte diferente do elefante e descreve coisas diferentes. A verdade reside no todo.', fr: 'L\'histoire de Rûmî "L\'éléphant dans l\'obscurité" — chacun touche une partie différente de l\'éléphant et décrit des choses différentes. La vérité réside dans le tout.', ja: 'ルーミーの物語「闇の中のゾウ」——めいめいがゾウの異なる部分に触れ、異なるものを述べる。真理は全体のうちにある。' } },
      { culture: { tr: 'Afrika', en: 'African', de: 'Afrikanisch', es: 'Africano', pt: 'Africano', fr: 'Africain', ja: 'アフリカ' }, meaning: { tr: 'Maasai\'de — kabilenin liderliğinin sembolü. Filin yürüyüşü "aile yürüyüşü"dür.', en: 'Among the Maasai — symbol of tribal leadership. The elephant\'s walk is the "family walk".', de: 'Bei den Maasai — Symbol der Stammesführung. Der Gang des Elefanten ist der "Familiengang".', es: 'Entre los masái — símbolo del liderazgo tribal. El andar del elefante es la "marcha de la familia".', pt: 'Entre os masai — símbolo da liderança tribal. O andar do elefante é a "marcha da família".', fr: 'Chez les Massaï — symbole du leadership tribal. La marche de l\'éléphant est la "marche de la famille".', ja: 'マサイにおいて——部族の指導力の象徴。ゾウの歩みは「家族の歩み」である。' } },
    ],
    myths: [
      { tr: 'Ganeşa\'nın Başı: Hint mitolojisinde Parvati oğlu Ganeşa\'yı yaratır. Şiva, oğlunu tanımayıp başını keser. Pişman olunca ilk gördüğü canlının başını takar — fil. Ganeşa böyle doğar: engellerin kaldırıcısı, başlangıçların tanrısı.', en: 'Ganesha\'s Head: In Hindu mythology, Parvati creates her son Ganesha. Not recognizing his son, Shiva severs his head. Repenting, he attaches the head of the first creature he sees — an elephant. Thus Ganesha is born: remover of obstacles, god of beginnings.', de: 'Ganeshas Kopf: In der hinduistischen Mythologie erschafft Parvati ihren Sohn Ganesha. Da Shiva seinen Sohn nicht erkennt, schlägt er ihm den Kopf ab. Reuig setzt er den Kopf des ersten Wesens an, das er sieht — eines Elefanten. So wird Ganesha geboren: Beseitiger der Hindernisse, Gott der Anfänge.', es: 'La cabeza de Ganesha: En la mitología hindú, Parvati crea a su hijo Ganesha. Sin reconocer a su hijo, Shiva le corta la cabeza. Arrepentido, le coloca la cabeza de la primera criatura que ve — un elefante. Así nace Ganesha: removedor de obstáculos, dios de los comienzos.', pt: 'A cabeça de Ganesha: Na mitologia hindu, Parvati cria o seu filho Ganesha. Não reconhecendo o filho, Shiva corta-lhe a cabeça. Arrependido, coloca-lhe a cabeça da primeira criatura que vê — um elefante. Assim nasce Ganesha: removedor de obstáculos, deus dos começos.', fr: 'La tête de Ganesha : Dans la mythologie hindoue, Parvati crée son fils Ganesha. Ne reconnaissant pas son fils, Shiva lui tranche la tête. Repentant, il lui attache la tête de la première créature qu\'il voit — un éléphant. Ainsi naît Ganesha : ôteur d\'obstacles, dieu des commencements.', ja: 'ガネーシャの頭：ヒンドゥー神話において、パールヴァティーは息子ガネーシャを創る。シヴァは息子と気づかず首を刎ねる。悔いて、最初に見た生き物の頭を付ける——ゾウ。こうしてガネーシャが生まれる——障害を取り除く者、始まりの神。' },
      { tr: 'Mevlana\'nın Fili: "Bir karanlık odada filin yanına farklı insanlar girer. Biri hortumuna dokunur, yılan sanır. Biri kulağına, yelpaze. Biri ayağına, sütun." Mevlana\'da: hakikat bir parçayla değil, bütünle bilinir.', en: 'Rumi\'s Elephant: "Different people enter a dark room where an elephant stands. One touches its trunk and takes it for a snake. Another, its ear, and calls it a fan. Another, its leg, and calls it a pillar." For Rumi: truth is known not by a part but by the whole.', de: 'Rumis Elefant: "Verschiedene Menschen betreten einen dunklen Raum, in dem ein Elefant steht. Einer berührt seinen Rüssel und hält ihn für eine Schlange. Ein anderer sein Ohr und nennt es einen Fächer. Ein anderer sein Bein und nennt es eine Säule." Für Rumi: Die Wahrheit erkennt man nicht durch einen Teil, sondern durch das Ganze.', es: 'El elefante de Rumi: "Distintas personas entran en un cuarto oscuro donde hay un elefante. Una toca su trompa y la cree una serpiente. Otra, su oreja, y la llama abanico. Otra, su pata, y la llama columna." Para Rumi: la verdad se conoce no por una parte sino por el todo.', pt: 'O elefante de Rumi: "Pessoas diferentes entram num quarto escuro onde está um elefante. Uma toca a tromba e julga-a uma serpente. Outra, a orelha, e chama-lhe leque. Outra, a pata, e chama-lhe coluna." Para Rumi: a verdade conhece-se não por uma parte, mas pelo todo.', fr: 'L\'éléphant de Rûmî : "Différentes personnes entrent dans une pièce sombre où se tient un éléphant. L\'une touche sa trompe et la prend pour un serpent. Une autre, son oreille, et l\'appelle éventail. Une autre, sa patte, et l\'appelle colonne." Pour Rûmî : la vérité se connaît non par une partie mais par le tout.', ja: 'ルーミーのゾウ：「暗い部屋にゾウがいて、さまざまな人が入ってくる。一人は鼻に触れ、蛇だと思う。一人は耳に触れ、扇だと言う。一人は脚に触れ、柱だと言う。」ルーミーにとって——真理は部分ではなく全体によって知られる。' },
    ],
  },

  // ─── a049 Vaşak ─────────────────────────────────────────────────────────
  a049: {
    jung: { tr: '"Sırların Bekçisi" arketipi. Vaşak — gördüklerini söylemeyen, ama hakikati en derinden bilen.', en: 'The "Keeper of Secrets" archetype. The lynx — the one who does not tell what it sees, yet knows the truth most deeply.', de: 'Der Archetyp des "Hüters der Geheimnisse". Der Luchs — der, der nicht sagt, was er sieht, doch die Wahrheit am tiefsten kennt.', es: 'El arquetipo del "Guardián de los Secretos". El lince — el que no dice lo que ve, pero conoce la verdad más profundamente.', pt: 'O arquétipo do "Guardião dos Segredos". O lince — aquele que não diz o que vê, mas conhece a verdade mais profundamente.', fr: 'L\'archétype du "Gardien des secrets". Le lynx — celui qui ne dit pas ce qu\'il voit, mais connaît la vérité le plus profondément.', ja: '「秘密の番人」の元型。オオヤマネコ——見たものを語らず、しかし真実を最も深く知る者。' },
    dream: { tr: 'Vaşak rüyada — bir gerçeği biliyorsun ama henüz söylenmemeli. Gizli gözlemiyorsa: aksiyon zamanı yaklaşıyor. Yaklaşırsa: derin bir bilgi sana açılıyor.', en: 'Lynx in dream — you know a truth, but it must not yet be told. Watching in secret: the time of action approaches. Drawing near: a deep knowledge is opening to you.', de: 'Luchs im Traum — du kennst eine Wahrheit, doch sie darf noch nicht gesagt werden. Beobachtet er heimlich: Die Zeit zu handeln naht. Nähert er sich: Ein tiefes Wissen öffnet sich dir.', es: 'Lince en sueños — conoces una verdad, pero aún no debe decirse. Si observa en secreto: el tiempo de actuar se acerca. Si se acerca: un conocimiento profundo se te abre.', pt: 'Lince em sonho — conheces uma verdade, mas ainda não deve ser dita. Se observa em segredo: o tempo de agir aproxima-se. Se se aproxima: um conhecimento profundo abre-se a ti.', fr: 'Lynx en rêve — tu connais une vérité, mais elle ne doit pas encore être dite. Observant en secret : le temps d\'agir approche. S\'approchant : un savoir profond s\'ouvre à toi.', ja: '夢の中のオオヤマネコ——あなたはある真実を知っているが、まだ語ってはならない。密かに見つめているなら、行動の時が近づいている。近づくなら、深い知があなたに開かれていく。' },
    shadow: { tr: 'Soğuk gizem. Sırrın hayat tarzı olursa — yalnızlık. Vaşak yalnızdır ama küskün değildir; ayrım var.', en: 'Cold mystery. If the secret becomes a way of life — loneliness. The lynx is solitary but not resentful; there is a distinction.', de: 'Kalte Verschwiegenheit. Wird das Geheimnis zur Lebensweise — Einsamkeit. Der Luchs ist einzelgängerisch, doch nicht verbittert; es gibt einen Unterschied.', es: 'Misterio frío. Si el secreto se vuelve una forma de vida — soledad. El lince es solitario pero no resentido; hay una distinción.', pt: 'Mistério frio. Se o segredo se torna um modo de vida — solidão. O lince é solitário mas não ressentido; há uma distinção.', fr: 'Mystère froid. Si le secret devient un mode de vie — la solitude. Le lynx est solitaire mais non aigri ; il y a une distinction.', ja: '冷たい秘めごと。秘密が生き方になれば——孤独。オオヤマネコは孤高だが恨みは抱かない。そこに違いがある。' },
    whenAppears: { tr: 'Bir sırrı taşıman/saklamian gerektiğinde, derin gözlem zamanında, kalabalıktan çekilip görüye girdiğinde.', en: 'When you must carry or keep a secret, in a time of deep observation, when withdrawing from the crowd into vision.', de: 'Wenn du ein Geheimnis tragen oder hüten musst, in einer Zeit tiefer Beobachtung, wenn du dich aus der Menge in die Schau zurückziehst.', es: 'Cuando debes portar o guardar un secreto, en un tiempo de observación profunda, al retirarte de la multitud hacia la visión.', pt: 'Quando deves carregar ou guardar um segredo, num tempo de observação profunda, ao retirar-te da multidão para a visão.', fr: 'Quand tu dois porter ou garder un secret, en un temps d\'observation profonde, en te retirant de la foule vers la vision.', ja: '秘密を担う、あるいは守らねばならぬとき、深い観察の時に、群衆から退いて洞察へ入るときに。' },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Lynx — adından geliyor "lynx eyed" deyimi: keskin bakış. Görünmeyeni gören.', en: 'Lynx — from its name comes the expression "lynx-eyed": piercing sight. The one who sees the unseen.', de: 'Luchs — von seinem Namen stammt der Ausdruck "luchsäugig": durchdringender Blick. Der, der das Ungesehene sieht.', es: 'Lince — de su nombre viene la expresión "ojos de lince": vista penetrante. El que ve lo invisible.', pt: 'Lince — do seu nome vem a expressão "olhos de lince": vista penetrante. Aquele que vê o invisível.', fr: 'Lynx — de son nom vient l\'expression "œil de lynx" : vue perçante. Celui qui voit l\'invisible.', ja: 'オオヤマネコ（リュンクス）——その名から「リンクスの目」（鋭い眼）という言い回しが生まれた。見えぬものを見る者。' } },
      { culture: { tr: 'Kuzey Avrupa', en: 'Northern European', de: 'Nordeuropäisch', es: 'Norte-Europeo', pt: 'Norte-Europeu', fr: 'Nord-Européen', ja: '北欧州' }, meaning: { tr: 'İskandinav, Finlandiya geleneğinde — orman ruhlarının habercisi.', en: 'In Scandinavian and Finnish tradition — messenger of the forest spirits.', de: 'In skandinavischer und finnischer Tradition — Bote der Waldgeister.', es: 'En la tradición escandinava y finlandesa — mensajero de los espíritus del bosque.', pt: 'Na tradição escandinava e finlandesa — mensageiro dos espíritos da floresta.', fr: 'Dans la tradition scandinave et finlandaise — messager des esprits de la forêt.', ja: 'スカンジナビア、フィンランドの伝統において——森の精霊の使者。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Sırların hayvanı. Vaşak bilenlere bilgi verir, bilmeyenlere görünmez.', en: 'The animal of secrets. The lynx gives knowledge to those who know; to those who do not, it remains invisible.', de: 'Das Tier der Geheimnisse. Der Luchs gibt jenen Wissen, die wissen; jenen, die nicht wissen, bleibt er unsichtbar.', es: 'El animal de los secretos. El lince da conocimiento a los que saben; a los que no, permanece invisible.', pt: 'O animal dos segredos. O lince dá conhecimento aos que sabem; aos que não sabem, permanece invisível.', fr: 'L\'animal des secrets. Le lynx donne le savoir à ceux qui savent ; pour ceux qui ne savent pas, il reste invisible.', ja: '秘密の動物。オオヤマネコは知る者に知を与え、知らぬ者には見えぬまま。' } },
      { culture: { tr: 'Anadolu Halk', en: 'Anatolian Folk', de: 'Anatolische Volkskultur', es: 'Folclore Anatolio', pt: 'Folclore Anatólio', fr: 'Folklore Anatolien', ja: 'アナトリア民俗' }, meaning: { tr: 'Toroslar\'ın gölgesi. Görenin görüldüğü ama söyleyemediği hayvan — saygı sınırı.', en: 'The shadow of the Taurus. An animal whose sighter is seen but cannot tell — the boundary of reverence.', de: 'Der Schatten des Taurus. Ein Tier, dessen Beobachter gesehen wird, aber nicht sprechen kann — die Grenze der Ehrfurcht.', es: 'La sombra del Tauro. Un animal cuyo observador es visto pero no puede contarlo — el límite de la reverencia.', pt: 'A sombra do Tauro. Um animal cujo observador é visto mas não pode contá-lo — o limite da reverência.', fr: 'L\'ombre du Taurus. Un animal dont l\'observateur est vu mais ne peut le dire — la limite du respect.', ja: 'トロス山脈の影。見た者が見られながらも語れぬ動物——敬意の境界。' } },
      { culture: { tr: 'Roma', en: 'Roman', de: 'Römisch', es: 'Romano', pt: 'Romano', fr: 'Romain', ja: 'ローマ' }, meaning: { tr: 'Vaşak ışığın tüm renklerini görür sanılırdı — gizli olanı bile parça parça çözer.', en: 'The lynx was thought to see all the colors of light — unraveling even the hidden, piece by piece.', de: 'Man glaubte, der Luchs sehe alle Farben des Lichts — er entwirre selbst das Verborgene, Stück für Stück.', es: 'Se creía que el lince veía todos los colores de la luz — desentrañando incluso lo oculto, pieza a pieza.', pt: 'Acreditava-se que o lince via todas as cores da luz — desvendando até o oculto, peça a peça.', fr: 'On croyait que le lynx voyait toutes les couleurs de la lumière — démêlant même le caché, pièce par pièce.', ja: 'オオヤマネコは光のあらゆる色を見ると信じられた——隠れたものさえ一片ずつ解き明かす。' } },
    ],
    myths: [
      { tr: 'Lynx\'in Bakışı: Antik kaynaklara göre vaşağın bakışı taşları bile delerdi. Onun ışıltısı kıymetli taşların oluşumunu açıklarmış — gizli kırılmanın görüsü.', en: 'The Lynx\'s Gaze: According to ancient sources, the lynx\'s gaze could pierce even stones. Its luster was said to explain the formation of precious gems — the vision of hidden refraction.', de: 'Der Blick des Luchses: Antiken Quellen zufolge konnte der Blick des Luchses sogar Steine durchdringen. Sein Glanz soll die Entstehung der Edelsteine erklären — die Schau der verborgenen Brechung.', es: 'La mirada del lince: Según fuentes antiguas, la mirada del lince podía atravesar incluso las piedras. Se decía que su brillo explicaba la formación de las gemas preciosas — la visión de la refracción oculta.', pt: 'O olhar do lince: Segundo fontes antigas, o olhar do lince podia atravessar até as pedras. Dizia-se que o seu brilho explicava a formação das gemas preciosas — a visão da refração oculta.', fr: 'Le regard du lynx : Selon les sources antiques, le regard du lynx pouvait percer même les pierres. Son éclat passait pour expliquer la formation des pierres précieuses — la vision de la réfraction cachée.', ja: 'オオヤマネコのまなざし：古代の記録によれば、オオヤマネコの視は石さえ貫いた。その輝きは宝石の生成を説き明かすとされた——隠れた屈折の視。' },
      { tr: 'Anadolu Toros Vaşağı: Modern zamanlarda neredeyse soyu tükenmiş. Onu son görenler "bakışı seni durdurur" dermiş — biliyor olma duygusunun katlanılmaz ağırlığı.', en: 'The Anatolian Taurus Lynx: Nearly extinct in modern times. Those who last saw it said "its gaze stops you" — the unbearable weight of being known.', de: 'Der anatolische Taurus-Luchs: In der Neuzeit fast ausgestorben. Die ihn zuletzt sahen, sagten "sein Blick hält dich an" — die unerträgliche Last, gekannt zu sein.', es: 'El lince del Tauro anatolio: Casi extinto en tiempos modernos. Quienes lo vieron por última vez decían "su mirada te detiene" — el peso insoportable de ser conocido.', pt: 'O lince do Tauro anatólio: Quase extinto nos tempos modernos. Quem o viu por último dizia "o seu olhar detém-te" — o peso insuportável de ser conhecido.', fr: 'Le lynx du Taurus anatolien : Presque éteint à l\'époque moderne. Ceux qui l\'ont vu en dernier disaient "son regard t\'arrête" — le poids insoutenable d\'être connu.', ja: 'アナトリアのトロスのオオヤマネコ：現代ではほぼ絶滅した。最後に見た者たちは「そのまなざしはあなたを立ち止まらせる」と言った——知られていることの耐えがたい重み。' },
    ],
  },

  // ─── a050 Örümcek ───────────────────────────────────────────────────────
  a050: {
    jung: { tr: '"Yaratıcı Dokumacı" arketipi. Örümcek — kaderini kendi dokuyan. Hem yaratıcı hem avcı; sabırlı sanatçı.', en: 'The "Creative Weaver" archetype. The spider — the one who weaves her own fate. Both creator and hunter; the patient artist.', de: 'Der Archetyp der "schöpferischen Weberin". Die Spinne — die, die ihr eigenes Schicksal webt. Schöpferin und Jägerin zugleich; die geduldige Künstlerin.', es: 'El arquetipo de la "Tejedora Creadora". La araña — la que teje su propio destino. Creadora y cazadora a la vez; la artista paciente.', pt: 'O arquétipo da "Tecelã Criadora". A aranha — aquela que tece o próprio destino. Criadora e caçadora ao mesmo tempo; a artista paciente.', fr: 'L\'archétype de la "Tisseuse créatrice". L\'araignée — celle qui tisse son propre destin. Créatrice et chasseuse à la fois ; l\'artiste patiente.', ja: '「創造する織り手」の元型。クモ——自らの運命を織る者。創造者にして狩人、忍耐の芸術家。' },
    dream: { tr: 'Örümcek rüyada — yaratım sürecinde dikkatli olmalısın. Ağ kuruyorsa: planlı bir yaratımdasın. Sana yaklaşıyorsa: bir tuzak ya da fırsat — ayırt et.', en: 'Spider in dream — you must be careful in your creative process. Spinning a web: you are in a planned creation. Approaching you: a trap or an opportunity — discern between them.', de: 'Spinne im Traum — du musst in deinem schöpferischen Prozess achtsam sein. Webt sie ein Netz: Du bist in einer geplanten Schöpfung. Nähert sie sich dir: eine Falle oder eine Gelegenheit — unterscheide zwischen ihnen.', es: 'Araña en sueños — debes ser cuidadoso en tu proceso creativo. Si teje una tela: estás en una creación planificada. Si se acerca: una trampa o una oportunidad — discierne entre ellas.', pt: 'Aranha em sonho — deves ter cuidado no teu processo criativo. Se tece uma teia: estás numa criação planeada. Se se aproxima: uma armadilha ou uma oportunidade — discerne entre elas.', fr: 'Araignée en rêve — tu dois être prudent dans ton processus créatif. Tissant une toile : tu es dans une création planifiée. S\'approchant : un piège ou une occasion — discerne entre les deux.', ja: '夢の中のクモ——あなたは創造の過程で注意せねばならない。網を張るなら、計画された創造のうちにある。近づくなら、罠か好機か——見分けよ。' },
    shadow: { tr: 'Ağına başkalarını dolama. Manipülatif kontrol. Örümcek yaratır ama bağımlılaştırırsa — kendi ağında boğulur.', en: 'Entangling others in your web. Manipulative control. The spider creates, but if she fosters dependence — she drowns in her own web.', de: 'Andere in dein Netz zu verstricken. Manipulative Kontrolle. Die Spinne erschafft, doch fördert sie Abhängigkeit — ertrinkt sie im eigenen Netz.', es: 'Enredar a otros en tu tela. Control manipulador. La araña crea, pero si fomenta la dependencia — se ahoga en su propia tela.', pt: 'Enredar outros na tua teia. Controlo manipulador. A aranha cria, mas se fomenta a dependência — afoga-se na própria teia.', fr: 'Empêtrer les autres dans ta toile. Contrôle manipulateur. L\'araignée crée, mais si elle favorise la dépendance — elle se noie dans sa propre toile.', ja: '他者を自分の網に絡め取ること。操作による支配。クモは創るが、依存を育てれば——自らの網に溺れる。' },
    whenAppears: { tr: 'Yaratıcı projelere başlarken, kaderini yeniden örmek istediğinde, sabırla iplik iplik kurman gereken bir hayatta.', en: 'When beginning creative projects, when you wish to reweave your fate, in a life you must build thread by thread with patience.', de: 'Beim Beginn schöpferischer Vorhaben, wenn du dein Schicksal neu weben willst, in einem Leben, das du geduldig Faden um Faden errichten musst.', es: 'Al comenzar proyectos creativos, cuando deseas reentretejer tu destino, en una vida que debes construir hilo a hilo con paciencia.', pt: 'Ao começar projetos criativos, quando desejas tecer de novo o teu destino, numa vida que deves construir fio a fio com paciência.', fr: 'En commençant des projets créatifs, quand tu souhaites retisser ton destin, dans une vie que tu dois bâtir fil par fil avec patience.', ja: '創造的な企てを始めるとき、自らの運命を織り直したいとき、辛抱強く一糸ずつ築かねばならぬ人生において。' },
    traditions: [
      { culture: { tr: 'İslam', en: 'Islamic', de: 'Islamisch', es: 'Islámico', pt: 'Islâmico', fr: 'Islamique', ja: 'イスラーム' }, meaning: { tr: 'Sevr Mağarası — Hz. Muhammed ve Ebubekir kaçarken mağaranın ağzında bir örümcek ağ örer, düşmanlar geçer ama kimsenin orada saklanmadığını sanır.', en: 'The Cave of Thawr — as the Prophet Muhammad and Abu Bakr flee, a spider weaves a web at the cave\'s mouth; the enemies pass by, thinking no one could be hiding there.', de: 'Die Höhle von Thawr — als der Prophet Mohammed und Abu Bakr fliehen, webt eine Spinne ein Netz am Höhleneingang; die Feinde ziehen vorbei und meinen, dort könne sich niemand verbergen.', es: 'La cueva de Thawr — mientras el profeta Mahoma y Abu Bakr huyen, una araña teje una tela en la boca de la cueva; los enemigos pasan, creyendo que nadie podría esconderse allí.', pt: 'A caverna de Thawr — enquanto o profeta Maomé e Abu Bakr fogem, uma aranha tece uma teia na boca da caverna; os inimigos passam, julgando que ninguém poderia ali esconder-se.', fr: 'La grotte de Thawr — tandis que le prophète Mahomet et Abou Bakr fuient, une araignée tisse une toile à l\'entrée de la grotte ; les ennemis passent, croyant que nul ne pourrait s\'y cacher.', ja: 'サウルの洞窟——預言者ムハンマドとアブー・バクルが逃れる際、クモが洞窟の入口に網を張る。敵は通り過ぎ、そこに誰も隠れていないと思い込む。' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Arakhne — dokumada Athena\'yı yenince tanrıça onu örümceğe çevirir. İlk dokumacı.', en: 'Arachne — when she surpasses Athena at weaving, the goddess turns her into a spider. The first weaver.', de: 'Arachne — als sie Athene im Weben übertrifft, verwandelt die Göttin sie in eine Spinne. Die erste Weberin.', es: 'Aracne — cuando supera a Atenea en el tejido, la diosa la convierte en araña. La primera tejedora.', pt: 'Aracne — quando supera Atena na tecelagem, a deusa transforma-a numa aranha. A primeira tecelã.', fr: 'Arachné — quand elle surpasse Athéna au tissage, la déesse la change en araignée. La première tisseuse.', ja: 'アラクネ——機織りでアテナを凌ぐと、女神は彼女をクモに変える。最初の織り手。' } },
      { culture: { tr: 'Afrika', en: 'African', de: 'Afrikanisch', es: 'Africano', pt: 'Africano', fr: 'Africain', ja: 'アフリカ' }, meaning: { tr: 'Anansi — örümcek-trickster tanrı. Hikayelerin kralı. Akıllı zayıfın gücü.', en: 'Anansi — the spider-trickster god. King of stories. The power of the clever underdog.', de: 'Anansi — der Spinnen-Trickster-Gott. König der Geschichten. Die Macht des klugen Schwächeren.', es: 'Anansi — el dios araña-embaucador. Rey de las historias. El poder del débil astuto.', pt: 'Anansi — o deus aranha-trapaceiro. Rei das histórias. O poder do fraco astuto.', fr: 'Anansi — le dieu araignée-filou. Roi des histoires. La puissance du faible rusé.', ja: 'アナンシ——クモにしてトリックスターの神。物語の王。賢き弱者の力。' } },
      { culture: { tr: 'Kızılderili', en: 'Native American', de: 'Indianisch', es: 'Nativo Americano', pt: 'Nativo-Americano', fr: 'Amérindien', ja: 'ネイティブ・アメリカン' }, meaning: { tr: 'Spider Grandmother — yaratıcı ana. Dünyayı dokuyan ve yıldız haritasını gönderen.', en: 'Spider Grandmother — the creator mother. The one who weaves the world and sends the star map.', de: 'Spinnen-Großmutter — die Schöpfermutter. Die, die die Welt webt und die Sternenkarte sendet.', es: 'Abuela Araña — la madre creadora. La que teje el mundo y envía el mapa estelar.', pt: 'Avó Aranha — a mãe criadora. Aquela que tece o mundo e envia o mapa estelar.', fr: 'Grand-mère Araignée — la mère créatrice. Celle qui tisse le monde et envoie la carte des étoiles.', ja: 'クモのおばあさん——創造の母。世界を織り、星の地図を送る者。' } },
      { culture: { tr: 'Anadolu Halk', en: 'Anatolian Folk', de: 'Anatolische Volkskultur', es: 'Folclore Anatolio', pt: 'Folclore Anatólio', fr: 'Folklore Anatolien', ja: 'アナトリア民俗' }, meaning: { tr: '"Örümcek ağı bozulmuş" — terkedilmişliği ifade eder. Ama aynı zamanda örümcek sebatıyla yeniden örer.', en: '"The spider\'s web is broken" — expresses abandonment. Yet the spider, with perseverance, weaves it again.', de: '"Das Spinnennetz ist zerrissen" — drückt Verlassenheit aus. Doch die Spinne webt es mit Beharrlichkeit aufs Neue.', es: '"La tela de la araña está rota" — expresa abandono. Pero la araña, con perseverancia, la teje de nuevo.', pt: '"A teia da aranha está rasgada" — exprime abandono. Mas a aranha, com perseverança, tece-a de novo.', fr: '"La toile de l\'araignée est déchirée" — exprime l\'abandon. Mais l\'araignée, avec persévérance, la tisse de nouveau.', ja: '「クモの巣が壊れた」——見捨てられたさまを表す。だがクモは粘り強く再び織る。' } },
    ],
    myths: [
      { tr: 'Sevr Mağarası: İslam tarihinde Hz. Muhammed Mekke\'den Medine\'ye hicret ederken Ebubekir ile Sevr Mağarası\'na sığınır. Bir örümcek mağaranın ağzında hızla ağ örer, bir güvercin yuva yapar. Mekkeli düşmanlar gelir, ağ ve yuva el değmemiş görünür — kimse orada olamaz sanırlar. En küçük yaratık peygamberi korur.', en: 'The Cave of Thawr: In Islamic history, as the Prophet Muhammad emigrates from Mecca to Medina with Abu Bakr, he takes refuge in the Cave of Thawr. A spider swiftly weaves a web at the cave\'s mouth, and a dove builds a nest. The Meccan pursuers arrive; the web and nest appear untouched — they think no one could be inside. The smallest creature protects the prophet.', de: 'Die Höhle von Thawr: In der islamischen Geschichte sucht der Prophet Mohammed bei seiner Auswanderung von Mekka nach Medina mit Abu Bakr Zuflucht in der Höhle von Thawr. Eine Spinne webt rasch ein Netz am Höhleneingang, eine Taube baut ein Nest. Die mekkanischen Verfolger kommen; Netz und Nest scheinen unberührt — sie meinen, niemand könne drinnen sein. Das kleinste Geschöpf schützt den Propheten.', es: 'La cueva de Thawr: En la historia islámica, mientras el profeta Mahoma emigra de La Meca a Medina con Abu Bakr, se refugia en la cueva de Thawr. Una araña teje rápidamente una tela en la boca de la cueva, y una paloma hace un nido. Los perseguidores mecanos llegan; la tela y el nido parecen intactos — creen que nadie podría estar dentro. La criatura más pequeña protege al profeta.', pt: 'A caverna de Thawr: Na história islâmica, enquanto o profeta Maomé emigra de Meca para Medina com Abu Bakr, refugia-se na caverna de Thawr. Uma aranha tece depressa uma teia na boca da caverna, e uma pomba faz um ninho. Os perseguidores de Meca chegam; a teia e o ninho parecem intactos — julgam que ninguém poderia estar lá dentro. A mais pequena criatura protege o profeta.', fr: 'La grotte de Thawr : Dans l\'histoire islamique, lors de l\'émigration du prophète Mahomet de La Mecque à Médine avec Abou Bakr, il se réfugie dans la grotte de Thawr. Une araignée tisse vite une toile à l\'entrée de la grotte, et une colombe fait un nid. Les poursuivants mecquois arrivent ; la toile et le nid semblent intacts — ils croient que nul ne pourrait être à l\'intérieur. La plus petite créature protège le prophète.', ja: 'サウルの洞窟：イスラーム史において、預言者ムハンマドはアブー・バクルとともにメッカからメディナへ移住する際、サウルの洞窟に身を隠す。クモが素早く洞窟の入口に網を張り、ハトが巣を作る。メッカの追っ手が来るが、網も巣も手つかずに見える——中に誰もいるはずがないと思う。最も小さな生き物が預言者を守る。' },
      { tr: 'Anansi\'nin Hikayeleri: Batı Afrika geleneğinde dünyanın bütün hikayeleri başlangıçta gök tanrısının elindedir. Örümcek Anansi onları zekasıyla alır ve insanlığa dağıtır — hikaye anlatmanın atası.', en: 'Anansi\'s Stories: In West African tradition, all the world\'s stories were originally in the hands of the sky god. The spider Anansi takes them by his cleverness and gives them to humanity — the ancestor of storytelling.', de: 'Anansis Geschichten: In der westafrikanischen Tradition lagen alle Geschichten der Welt anfangs in den Händen des Himmelsgottes. Die Spinne Anansi nimmt sie durch ihre Klugheit und gibt sie der Menschheit — der Ahn des Geschichtenerzählens.', es: 'Las historias de Anansi: En la tradición de África Occidental, todas las historias del mundo estaban al principio en manos del dios del cielo. La araña Anansi las toma con su astucia y las da a la humanidad — el ancestro de la narración.', pt: 'As histórias de Anansi: Na tradição da África Ocidental, todas as histórias do mundo estavam no início nas mãos do deus do céu. A aranha Anansi toma-as pela sua esperteza e dá-as à humanidade — o ancestral da narração.', fr: 'Les histoires d\'Anansi : Dans la tradition ouest-africaine, toutes les histoires du monde étaient au départ entre les mains du dieu du ciel. L\'araignée Anansi les prend par sa ruse et les donne à l\'humanité — l\'ancêtre du conte.', ja: 'アナンシの物語：西アフリカの伝統において、世界のすべての物語ははじめ天空の神の手にあった。クモのアナンシはその知略で物語を奪い、人類に分け与える——語りの祖。' },
    ],
  },

  // ─── a051 Kuğu ──────────────────────────────────────────────────────────
  a051: {
    jung: { tr: '"Saflık ve Dönüşüm" arketipi. Kuğu, bilinçdışında ham güzelliğin en olgun biçimine geçişi temsil eder — çirkin ördek yavrusundan beyaz Kuğu\'ya uzanan yol, ruhun öz gerçekliğini bulmasıdır. Zarif yüzeyin altında güçlü, yorulmaz ayaklar yüzer: görünen ile görünmeyen arasındaki bu sırrı taşır.', en: 'The "Purity and Transformation" archetype. The Swan represents the transition to the most mature form of raw beauty in the unconscious — the path from ugly duckling to white Swan is the soul\'s discovery of its true nature. Beneath the graceful surface, powerful tireless legs paddle: it carries this secret between the visible and the invisible.', de: 'Der Archetyp "Reinheit und Verwandlung". Der Schwan verkörpert den Übergang der rohen Schönheit zu ihrer reifsten Gestalt im Unbewussten — der Weg vom hässlichen Entlein zum weißen Schwan ist die Entdeckung der wahren Natur der Seele. Unter der anmutigen Oberfläche rudern kräftige, unermüdliche Füße: Er trägt dieses Geheimnis zwischen dem Sichtbaren und dem Unsichtbaren.', es: 'El arquetipo de la "Pureza y Transformación". El cisne representa la transición de la belleza en bruto a su forma más madura en el inconsciente — el camino del patito feo al cisne blanco es el descubrimiento de la verdadera naturaleza del alma. Bajo la superficie grácil, unas patas poderosas e incansables reman: porta este secreto entre lo visible y lo invisible.', pt: 'O arquétipo da "Pureza e Transformação". O cisne representa a transição da beleza em bruto à sua forma mais madura no inconsciente — o caminho do patinho feio ao cisne branco é a descoberta da verdadeira natureza da alma. Sob a superfície graciosa, patas poderosas e incansáveis remam: carrega este segredo entre o visível e o invisível.', fr: 'L\'archétype de la "Pureté et Transformation". Le cygne représente le passage de la beauté brute à sa forme la plus mûre dans l\'inconscient — le chemin du vilain petit canard au cygne blanc est la découverte de la vraie nature de l\'âme. Sous la surface gracieuse, de puissantes pattes infatigables rament : il porte ce secret entre le visible et l\'invisible.', ja: '「清らかさと変容」の元型。白鳥は、無意識における素朴な美が最も成熟した姿へと至る移行を表す——醜いアヒルの子から白鳥への道は、魂が自らの本性を見いだすこと。優美な水面の下で力強く飽くなき脚が漕ぐ——見えるものと見えないもののあいだのこの秘密を担う。' },
    dream: { tr: 'Kuğu rüyada görünürse — güzelliğini henüz tanımadığın bir yönün sana seslenmesi. Uçuyorsa: ruhsal yükseliş ve özgürleşme eşiğinde. Suda süzülüyorsa: duygusal derinlikle barış içindesin, ama yüzeyi korumayı unutma.', en: 'If Swan appears in a dream — a facet of your beauty not yet recognized is calling to you. If it flies: you are on the threshold of spiritual ascent and liberation. If it glides on water: you are at peace with emotional depth, but do not forget to maintain the surface.', de: 'Erscheint der Schwan im Traum — eine Seite deiner Schönheit, die du noch nicht erkannt hast, ruft dich. Fliegt er: Du stehst an der Schwelle des geistigen Aufstiegs und der Befreiung. Gleitet er auf dem Wasser: Du bist im Frieden mit der emotionalen Tiefe, doch vergiss nicht, die Oberfläche zu wahren.', es: 'Si el cisne aparece en sueños — una faceta de tu belleza aún no reconocida te llama. Si vuela: estás en el umbral del ascenso espiritual y la liberación. Si se desliza sobre el agua: estás en paz con la profundidad emocional, pero no olvides cuidar la superficie.', pt: 'Se o cisne aparece em sonho — uma faceta da tua beleza ainda não reconhecida chama-te. Se voa: estás no limiar da ascensão espiritual e da libertação. Se desliza sobre a água: estás em paz com a profundidade emocional, mas não te esqueças de cuidar da superfície.', fr: 'Si le cygne apparaît en rêve — une facette de ta beauté encore non reconnue t\'appelle. S\'il vole : tu es au seuil de l\'ascension spirituelle et de la libération. S\'il glisse sur l\'eau : tu es en paix avec la profondeur émotionnelle, mais n\'oublie pas d\'entretenir la surface.', ja: '夢に白鳥が現れるなら——あなたがまだ気づいていない美の一面が呼びかけている。飛んでいるなら、霊的な上昇と解放の境にある。水を滑るなら、あなたは感情の深みと和解しているが、水面を保つことを忘れるな。' },
    shadow: { tr: 'Zarafet takıntısına dönüşebilir — her şeyin "güzel" görünmesi uğruna gerçeği örtbas etmek. Kuğu gölgesi: kibir ve soğukluk, "benim seviyemde değil" duygusuyla sağlıklı bağlardan kopmak.', en: 'Can turn into an obsession with grace — concealing truth for the sake of everything appearing "beautiful". The Swan shadow: pride and coldness, severing healthy bonds with the feeling of "not at my level".', de: 'Kann zur Besessenheit von Anmut werden — die Wahrheit zu verhüllen, damit alles "schön" erscheint. Der Schwanenschatten: Hochmut und Kälte, das Zerschneiden gesunder Bindungen mit dem Gefühl "nicht auf meinem Niveau".', es: 'Puede volverse una obsesión con la gracia — ocultar la verdad para que todo parezca "hermoso". La sombra del cisne: orgullo y frialdad, romper vínculos sanos con la sensación de "no está a mi nivel".', pt: 'Pode tornar-se uma obsessão pela graça — ocultar a verdade para que tudo pareça "belo". A sombra do cisne: orgulho e frieza, cortar laços saudáveis com a sensação de "não está ao meu nível".', fr: 'Peut tourner à l\'obsession de la grâce — dissimuler la vérité pour que tout paraisse "beau". L\'ombre du cygne : orgueil et froideur, rompre des liens sains avec le sentiment de "pas à mon niveau".', ja: '優美への執着に転じうる——すべてが「美しく」見えるよう真実を覆い隠すこと。白鳥の影——傲慢と冷たさ、「私の水準ではない」という思いで健やかな絆を断つこと。' },
    whenAppears: { tr: 'Kendinizi çirkin ya da yetersiz hissettiğinizde, bir dönüşümün tam ortasında olduğunuzda veya sanatsal/estetik bir yolculuğun başında.', en: 'When you feel ugly or inadequate, when you are in the midst of a transformation, or at the beginning of an artistic or aesthetic journey.', de: 'Wenn du dich hässlich oder unzulänglich fühlst, wenn du mitten in einer Verwandlung bist oder am Beginn einer künstlerischen oder ästhetischen Reise.', es: 'Cuando te sientes feo o inadecuado, cuando estás en medio de una transformación, o al comienzo de un viaje artístico o estético.', pt: 'Quando te sentes feio ou inadequado, quando estás no meio de uma transformação, ou no início de uma viagem artística ou estética.', fr: 'Quand tu te sens laid ou inadéquat, quand tu es au milieu d\'une transformation, ou au début d\'un voyage artistique ou esthétique.', ja: '自分を醜い、あるいは不十分だと感じるとき、変容の只中にあるとき、芸術的・美的な旅の始まりに。' },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Zeus Kuğu kılığına girerek Leda ile birleşti — böylece ilahi ile beşeri arasındaki geçişkenliği simgeler. Ayrıca Apollo\'nun kuşudur: kehanet ve müziğin taşıyıcısı.', en: 'Zeus transformed into a Swan to unite with Leda — symbolizing the permeability between the divine and the human. It is also Apollo\'s bird: carrier of prophecy and music.', de: 'Zeus verwandelte sich in einen Schwan, um sich mit Leda zu vereinen — er symbolisiert so die Durchlässigkeit zwischen dem Göttlichen und dem Menschlichen. Er ist auch Apollons Vogel: Träger der Prophezeiung und der Musik.', es: 'Zeus se transformó en cisne para unirse con Leda — simbolizando así la permeabilidad entre lo divino y lo humano. Es también el ave de Apolo: portador de la profecía y la música.', pt: 'Zeus transformou-se em cisne para se unir a Leda — simbolizando assim a permeabilidade entre o divino e o humano. É também a ave de Apolo: portador da profecia e da música.', fr: 'Zeus se transforma en cygne pour s\'unir à Léda — symbolisant ainsi la perméabilité entre le divin et l\'humain. Il est aussi l\'oiseau d\'Apollon : porteur de la prophétie et de la musique.', ja: 'ゼウスは白鳥に化けてレダと結ばれた——こうして神と人のあいだの通い合いを象徴する。アポロンの鳥でもある——予言と音楽の担い手。' } },
      { culture: { tr: 'Kelt Geleneği', en: 'Celtic Tradition', de: 'Keltische Tradition', es: 'Tradición Celta', pt: 'Tradição Celta', fr: 'Tradition Celtique', ja: 'ケルトの伝統' }, meaning: { tr: 'Kuğular öteki dünyayla bağlantılı kutsal varlıklardır. Öldürülmeleri lanet getirir. Çoğunlukla büyülenmiş insan ruhlarını taşırlar.', en: 'Swans are sacred beings connected to the otherworld. Killing them brings a curse. They often carry enchanted human souls.', de: 'Schwäne sind heilige Wesen, mit dem Jenseits verbunden. Sie zu töten bringt einen Fluch. Oft tragen sie verzauberte Menschenseelen.', es: 'Los cisnes son seres sagrados ligados al otro mundo. Matarlos trae una maldición. A menudo portan almas humanas encantadas.', pt: 'Os cisnes são seres sagrados ligados ao outro mundo. Matá-los traz uma maldição. Muitas vezes carregam almas humanas encantadas.', fr: 'Les cygnes sont des êtres sacrés liés à l\'autre monde. Les tuer attire une malédiction. Ils portent souvent des âmes humaines enchantées.', ja: '白鳥は彼岸とつながる聖なる存在。殺せば呪いを招く。しばしば魔法をかけられた人の魂を宿す。' } },
      { culture: { tr: 'Hint Mitolojisi', en: 'Hindu Mythology', de: 'Hinduistische Mythologie', es: 'Mitología Hindú', pt: 'Mitologia Hindu', fr: 'Mythologie Hindoue', ja: 'ヒンドゥー神話' }, meaning: { tr: 'Hamsa — Brahma\'nın bineği, ruh ile maddeyi ayırt etme yetisinin simgesi. "Ham-sa" nefes mantrası ile özdeşleştirilir: "Ben O\'yum".', en: 'Hamsa — Brahma\'s vehicle, symbol of the ability to discern spirit from matter. Identified with the breath mantra "Ham-sa": "I am That".', de: 'Hamsa — das Reittier Brahmas, Symbol der Fähigkeit, Geist von Materie zu unterscheiden. Mit dem Atemmantra "Ham-sa" gleichgesetzt: "Ich bin Das".', es: 'Hamsa — el vehículo de Brahma, símbolo de la capacidad de discernir el espíritu de la materia. Se identifica con el mantra de la respiración "Ham-sa": "Yo soy Eso".', pt: 'Hamsa — o veículo de Brahma, símbolo da capacidade de discernir o espírito da matéria. Identificado com o mantra da respiração "Ham-sa": "Eu sou Aquilo".', fr: 'Hamsa — le véhicule de Brahmâ, symbole de la faculté de discerner l\'esprit de la matière. Identifié au mantra du souffle "Ham-sa" : "Je suis Cela".', ja: 'ハンサ——ブラフマーの乗り物、霊と物質を見分ける力の象徴。呼吸のマントラ「ハン・サ」（我はそれなり）と同一視される。' } },
      { culture: { tr: 'Fin-Ugor Geleneği', en: 'Finno-Ugric Tradition', de: 'Finnougrische Tradition', es: 'Tradición Finougria', pt: 'Tradição Fino-Úgrica', fr: 'Tradition Finno-Ougrienne', ja: 'フィン・ウゴル系の伝統' }, meaning: { tr: 'Kalevala destanında Kuğu, ölüler nehri Tuonela\'nın sularında süzülür — ölüm ile yaşam arasındaki sessiz bekçi.', en: 'In the Kalevala epic, the Swan glides upon the waters of Tuonela, the river of the dead — the silent guardian between death and life.', de: 'Im Kalevala-Epos gleitet der Schwan über die Wasser von Tuonela, dem Fluss der Toten — der stille Wächter zwischen Tod und Leben.', es: 'En la epopeya Kalevala, el cisne se desliza sobre las aguas de Tuonela, el río de los muertos — el guardián silencioso entre la muerte y la vida.', pt: 'Na epopeia Kalevala, o cisne desliza sobre as águas de Tuonela, o rio dos mortos — o guardião silencioso entre a morte e a vida.', fr: 'Dans l\'épopée du Kalevala, le cygne glisse sur les eaux de Tuonela, le fleuve des morts — le gardien silencieux entre la mort et la vie.', ja: 'カレワラ叙事詩において、白鳥は死者の川トゥオネラの水面を滑る——死と生のあいだの静かな番人。' } },
      { culture: { tr: 'Anadolu Halk Geleneği', en: 'Anatolian Folk Tradition', de: 'Anatolische Volkstradition', es: 'Tradición Popular Anatolia', pt: 'Tradição Popular Anatólia', fr: 'Tradition Populaire Anatolienne', ja: 'アナトリア民俗の伝統' }, meaning: { tr: 'Kuğu, gelin kuşudur — düğün türkülerinde saflığın ve soyun simgesidir. "Kuğu boyunlu" deyimi en güzel övgüdür.', en: 'The Swan is the bride\'s bird — in wedding songs it is the symbol of purity and lineage. "Swan-necked" is the highest compliment.', de: 'Der Schwan ist der Vogel der Braut — in Hochzeitsliedern Symbol der Reinheit und der Abstammung. "Schwanenhalsig" ist das schönste Lob.', es: 'El cisne es el ave de la novia — en las canciones de boda es símbolo de la pureza y el linaje. "Cuello de cisne" es el mayor elogio.', pt: 'O cisne é a ave da noiva — nas canções de casamento é símbolo da pureza e da linhagem. "Pescoço de cisne" é o maior elogio.', fr: 'Le cygne est l\'oiseau de la mariée — dans les chants de noces, symbole de la pureté et de la lignée. "Cou de cygne" est le plus beau compliment.', ja: '白鳥は花嫁の鳥——婚礼の歌において清らかさと血筋の象徴。「白鳥の首」とは最高の褒め言葉。' } },
    ],
    myths: [
      { tr: 'Lohengrin efsanesi: Kutsal Kase\'nin şövalyesi Lohengrin, bir Kuğu\'nun çektiği kayıkla belirsiz bir yerden gelir ve bir prensesi kurtarır. Tek şartı: kimliğini sormaması. Sorulduğu an, kuğu-kayık onu alıp götürür — koşulsuz güvenin olmadığı yerde ilahi armağan da durmaz.', en: 'The legend of Lohengrin: The knight of the Holy Grail, Lohengrin, arrives from an unknown place in a boat drawn by a Swan and rescues a princess. His only condition: she must not ask his identity. The moment she does, the swan-boat takes him away — where unconditional trust is absent, the divine gift cannot remain.', de: 'Die Lohengrin-Legende: Der Gralsritter Lohengrin kommt aus einem unbekannten Ort in einem von einem Schwan gezogenen Boot und rettet eine Prinzessin. Seine einzige Bedingung: Sie darf nicht nach seiner Identität fragen. Im Augenblick, da sie es tut, trägt das Schwanenboot ihn fort — wo das bedingungslose Vertrauen fehlt, kann auch die göttliche Gabe nicht bleiben.', es: 'La leyenda de Lohengrin: El caballero del Santo Grial, Lohengrin, llega de un lugar desconocido en una barca tirada por un cisne y rescata a una princesa. Su única condición: que ella no pregunte su identidad. En el momento en que lo hace, la barca-cisne se lo lleva — donde falta la confianza incondicional, el don divino no puede permanecer.', pt: 'A lenda de Lohengrin: O cavaleiro do Santo Graal, Lohengrin, chega de um lugar desconhecido num barco puxado por um cisne e salva uma princesa. A sua única condição: que ela não pergunte a sua identidade. No momento em que o faz, o barco-cisne leva-o embora — onde falta a confiança incondicional, o dom divino não pode permanecer.', fr: 'La légende de Lohengrin : Le chevalier du Saint-Graal, Lohengrin, arrive d\'un lieu inconnu dans une barque tirée par un cygne et sauve une princesse. Sa seule condition : qu\'elle ne demande pas son identité. À l\'instant où elle le fait, la barque-cygne l\'emporte — là où manque la confiance inconditionnelle, le don divin ne peut demeurer.', ja: 'ローエングリン伝説：聖杯の騎士ローエングリンは、白鳥が曳く小舟で未知の地から現れ、姫を救う。唯一の条件——その素性を問わぬこと。問うた瞬間、白鳥の舟は彼を連れ去る——無条件の信頼なきところに、神の賜物もとどまらない。' },
      { tr: 'Hint efsanesinde Hamsa Kuşu, süt ile suyu birbirinden ayırt edebilme özelliğine sahiptir. Bu yüzden bilge kişiye "Paramahamsa" — büyük Hamsa — denir. Gerçeği yanlıştan ayırt etmek, ruhun en yüce erdemidir.', en: 'In Hindu legend, the Hamsa Bird has the ability to separate milk from water. This is why the wise person is called "Paramahamsa" — the great Swan. Discerning truth from falsehood is the soul\'s highest virtue.', de: 'In der hinduistischen Legende besitzt der Hamsa-Vogel die Fähigkeit, Milch vom Wasser zu trennen. Darum nennt man den Weisen "Paramahamsa" — der große Schwan. Wahrheit von Falschheit zu unterscheiden ist die höchste Tugend der Seele.', es: 'En la leyenda hindú, el ave Hamsa tiene la capacidad de separar la leche del agua. Por eso al sabio se le llama "Paramahamsa" — el gran cisne. Discernir la verdad de la falsedad es la más alta virtud del alma.', pt: 'Na lenda hindu, a ave Hamsa tem a capacidade de separar o leite da água. Por isso o sábio é chamado "Paramahamsa" — o grande cisne. Discernir a verdade da falsidade é a mais alta virtude da alma.', fr: 'Dans la légende hindoue, l\'oiseau Hamsa a la faculté de séparer le lait de l\'eau. C\'est pourquoi le sage est appelé "Paramahamsa" — le grand cygne. Discerner le vrai du faux est la plus haute vertu de l\'âme.', ja: 'ヒンドゥーの伝説において、ハンサ鳥は乳と水を分かつ力をもつ。ゆえに賢者は「パラマハンサ」——偉大なるハンサ——と呼ばれる。真と偽を見分けることは魂の最も高き徳。' },
    ],
  },

  // ─── a052 Kondor ─────────────────────────────────────────────────────────
  a052: {
    jung: { tr: '"Üst Dünya Elçisi" arketipi. Kondor, bilinçdışının en yüksek katmanını — kolektif atalar belleğini — temsil eder. Ölü etin üzerinde süzülmesi, dönüşümün vahşi ama zorunlu yüzünü gösterir: yaşam ancak ölümün işini kabul ederek sürebilir.', en: 'The "Upper World Emissary" archetype. The Condor represents the highest layer of the unconscious — the collective ancestral memory. Its gliding over carrion reveals the wild yet necessary face of transformation: life can only continue by accepting the work of death.', de: 'Der Archetyp des "Gesandten der Oberwelt". Der Kondor verkörpert die höchste Schicht des Unbewussten — das kollektive Ahnengedächtnis. Sein Gleiten über dem Aas zeigt das wilde, doch notwendige Gesicht der Verwandlung: Das Leben kann nur fortbestehen, indem es das Werk des Todes annimmt.', es: 'El arquetipo del "Emisario del Mundo Superior". El cóndor representa la capa más alta del inconsciente — la memoria ancestral colectiva. Su planear sobre la carroña revela el rostro salvaje pero necesario de la transformación: la vida solo puede continuar aceptando la obra de la muerte.', pt: 'O arquétipo do "Emissário do Mundo Superior". O condor representa a camada mais alta do inconsciente — a memória ancestral coletiva. O seu planar sobre a carniça revela o rosto selvagem mas necessário da transformação: a vida só pode continuar aceitando a obra da morte.', fr: 'L\'archétype de l\'"Émissaire du monde supérieur". Le condor représente la couche la plus haute de l\'inconscient — la mémoire ancestrale collective. Son vol plané au-dessus de la charogne révèle le visage sauvage mais nécessaire de la transformation : la vie ne peut continuer qu\'en acceptant l\'œuvre de la mort.', ja: '「上界の使者」の元型。コンドルは無意識の最も高い層——集団の祖先の記憶——を表す。屍肉の上を滑空する姿は、変容の荒々しくも不可欠な顔を示す——生は死の働きを受け入れてこそ続きうる。' },
    dream: { tr: 'Kondor rüyada görünürse — ata ruhları bir mesaj taşıyor; geçmişten gelen bilgelik seni bekliyor. Başının üzerinde daireler çiziyorsa: yüksek perspektiften bak, şu an içinde kaybolduğun sorun küçüktür. Yere konuyorsa: toprağa, köke, bedene dön.', en: 'If Condor appears in a dream — ancestral spirits carry a message; wisdom from the past awaits you. If it circles above your head: look from a high perspective, the problem you are lost in right now is small. If it lands: return to the earth, the root, the body.', de: 'Erscheint der Kondor im Traum — Ahnengeister tragen eine Botschaft; Weisheit aus der Vergangenheit erwartet dich. Kreist er über deinem Kopf: Betrachte es aus hoher Perspektive, das Problem, in dem du dich gerade verlierst, ist klein. Landet er: Kehre zur Erde, zur Wurzel, zum Körper zurück.', es: 'Si el cóndor aparece en sueños — los espíritus ancestrales portan un mensaje; la sabiduría del pasado te aguarda. Si traza círculos sobre tu cabeza: mira desde una perspectiva alta, el problema en que ahora te pierdes es pequeño. Si se posa: vuelve a la tierra, a la raíz, al cuerpo.', pt: 'Se o condor aparece em sonho — os espíritos ancestrais carregam uma mensagem; a sabedoria do passado aguarda-te. Se traça círculos sobre a tua cabeça: olha de uma perspetiva alta, o problema em que agora te perdes é pequeno. Se pousa: regressa à terra, à raiz, ao corpo.', fr: 'Si le condor apparaît en rêve — les esprits ancestraux portent un message ; la sagesse du passé t\'attend. S\'il décrit des cercles au-dessus de ta tête : regarde d\'une perspective élevée, le problème dans lequel tu te perds en ce moment est petit. S\'il se pose : reviens à la terre, à la racine, au corps.', ja: '夢にコンドルが現れるなら——祖霊が報せを運んでいる。過去から来る知恵があなたを待つ。頭上で輪を描くなら、高い視座から見よ。今あなたが迷い込んでいる問題は小さい。地に降りるなら、大地へ、根へ、体へ戻れ。' },
    shadow: { tr: 'Ölüme ve yıkıma fazla yakınlık — melankoliye, nihilizme kayma. "Her şey geçici zaten" düşüncesinin yaşam sevincini yok etmesi. Ya da tam tersi: ölümden patolojik kaçış, dönüşümü reddeden donukluk.', en: 'Too much proximity to death and destruction — sliding into melancholy and nihilism. The thought "everything is transient anyway" destroying joy in life. Or the opposite: pathological flight from death, the rigidity that refuses transformation.', de: 'Zu große Nähe zu Tod und Zerstörung — das Abgleiten in Melancholie und Nihilismus. Der Gedanke "alles ist ohnehin vergänglich", der die Lebensfreude zerstört. Oder das Gegenteil: krankhafte Flucht vor dem Tod, die Starrheit, die die Verwandlung verweigert.', es: 'Demasiada cercanía a la muerte y la destrucción — deslizarse hacia la melancolía y el nihilismo. El pensamiento "todo es transitorio de todos modos" destruyendo la alegría de vivir. O lo contrario: huida patológica de la muerte, la rigidez que rechaza la transformación.', pt: 'Demasiada proximidade da morte e da destruição — deslizar para a melancolia e o niilismo. O pensamento "tudo é transitório, afinal" destruindo a alegria de viver. Ou o oposto: fuga patológica da morte, a rigidez que recusa a transformação.', fr: 'Trop de proximité avec la mort et la destruction — glisser dans la mélancolie et le nihilisme. La pensée "de toute façon tout est éphémère" détruisant la joie de vivre. Ou l\'inverse : fuite pathologique de la mort, la rigidité qui refuse la transformation.', ja: '死と破壊に近づきすぎること——憂鬱や虚無主義への滑落。「どうせすべては移ろう」という思いが生の歓びを蝕む。あるいはその逆——死からの病的な逃避、変容を拒む硬直。' },
    whenAppears: { tr: 'Bir yakının ölümü sonrasında, kuşaktan kuşağa geçen bir örüntüyü kırmaya çalışırken ya da köklü bir karar arifesinde.', en: 'After the death of a loved one, when trying to break a pattern passed down through generations, or on the eve of a pivotal decision.', de: 'Nach dem Tod eines Angehörigen, beim Versuch, ein über Generationen vererbtes Muster zu durchbrechen, oder am Vorabend einer grundlegenden Entscheidung.', es: 'Tras la muerte de un ser querido, al intentar romper un patrón transmitido de generación en generación, o en la víspera de una decisión crucial.', pt: 'Após a morte de um ente querido, ao tentar quebrar um padrão transmitido de geração em geração, ou na véspera de uma decisão crucial.', fr: 'Après la mort d\'un proche, en tentant de briser un schéma transmis de génération en génération, ou à la veille d\'une décision décisive.', ja: '近しい者の死ののち、世代から世代へ受け継がれた型を断とうとするとき、根本的な決断の前夜に。' },
    traditions: [
      { culture: { tr: 'And Uygarlıkları (Quechua)', en: 'Andean Civilizations (Quechua)', de: 'Andine Zivilisationen (Quechua)', es: 'Civilizaciones Andinas (Quechua)', pt: 'Civilizações Andinas (Quechua)', fr: 'Civilisations Andines (Quechua)', ja: 'アンデス文明（ケチュア）' }, meaning: { tr: 'Kondor üst dünyayı (Hanan Pacha) temsil eder. Üçlü And kozmolojisinde Jaguar yeryüzü, Yılan yeraltı, Kondor ise gök-alem arasındaki köprüdür.', en: 'The Condor represents the upper world (Hanan Pacha). In the triple Andean cosmology, the Jaguar is the earth, the Serpent the underworld, and the Condor is the bridge to the sky-realm.', de: 'Der Kondor verkörpert die Oberwelt (Hanan Pacha). In der dreigeteilten andinen Kosmologie ist der Jaguar die Erde, die Schlange die Unterwelt und der Kondor die Brücke zum Himmelsreich.', es: 'El cóndor representa el mundo superior (Hanan Pacha). En la triple cosmología andina, el jaguar es la tierra, la serpiente el inframundo, y el cóndor es el puente hacia el reino celeste.', pt: 'O condor representa o mundo superior (Hanan Pacha). Na tripla cosmologia andina, o jaguar é a terra, a serpente o submundo, e o condor é a ponte para o reino celeste.', fr: 'Le condor représente le monde supérieur (Hanan Pacha). Dans la triple cosmologie andine, le jaguar est la terre, le serpent les enfers, et le condor le pont vers le royaume céleste.', ja: 'コンドルは上界（ハナン・パチャ）を表す。三層からなるアンデスの宇宙観において、ジャガーは地、蛇は地下界、コンドルは天界への橋。' } },
      { culture: { tr: 'İnka İmparatorluğu', en: 'Inca Empire', de: 'Inka-Reich', es: 'Imperio Inca', pt: 'Império Inca', fr: 'Empire Inca', ja: 'インカ帝国' }, meaning: { tr: 'İnka\'da güneş tanrısı İnti\'nin temsilcisi. Ölmüş İnka imparatorlarının ruhu Kondor biçimini alırdı ve halkını gökyüzünden izlerdi.', en: 'In the Inca Empire, representative of the sun god Inti. The spirits of deceased Inca emperors took the form of the Condor and watched over their people from the sky.', de: 'Im Inka-Reich Vertreter des Sonnengottes Inti. Die Seelen verstorbener Inka-Kaiser nahmen die Gestalt des Kondors an und wachten vom Himmel über ihr Volk.', es: 'En el Imperio Inca, representante del dios solar Inti. Los espíritus de los emperadores incas difuntos tomaban la forma del cóndor y velaban por su pueblo desde el cielo.', pt: 'No Império Inca, representante do deus solar Inti. Os espíritos dos imperadores incas falecidos tomavam a forma do condor e velavam pelo seu povo a partir do céu.', fr: 'Dans l\'Empire inca, représentant du dieu solaire Inti. Les esprits des empereurs incas défunts prenaient la forme du condor et veillaient sur leur peuple depuis le ciel.', ja: 'インカ帝国において、太陽神インティの代理。亡くなったインカ皇帝の魂はコンドルの姿をとり、天から民を見守った。' } },
      { culture: { tr: 'Mapuche Geleneği', en: 'Mapuche Tradition', de: 'Mapuche-Tradition', es: 'Tradición Mapuche', pt: 'Tradição Mapuche', fr: 'Tradition Mapuche', ja: 'マプチェの伝統' }, meaning: { tr: 'Kondor ölümün habercisi değil, ruhun taşıyıcısıdır. Şaman (Machi) ruhunu Kondor\'a binerek öteki dünyaya taşıyabilir.', en: 'The Condor is not a harbinger of death but a carrier of the soul. The shaman (Machi) can carry their spirit to the other world by riding the Condor.', de: 'Der Kondor ist kein Vorbote des Todes, sondern ein Träger der Seele. Der Schamane (Machi) kann seinen Geist auf dem Kondor reitend in die andere Welt tragen.', es: 'El cóndor no es heraldo de la muerte sino portador del alma. El chamán (Machi) puede llevar su espíritu al otro mundo montando el cóndor.', pt: 'O condor não é arauto da morte mas portador da alma. O xamã (Machi) pode levar o seu espírito ao outro mundo cavalgando o condor.', fr: 'Le condor n\'est pas un présage de mort mais un porteur de l\'âme. Le chamane (Machi) peut porter son esprit dans l\'autre monde en chevauchant le condor.', ja: 'コンドルは死の前触れではなく、魂の運び手。シャーマン（マチ）はコンドルに乗って自らの霊を異界へ運びうる。' } },
      { culture: { tr: 'Navajo Geleneği (Kuzey Amerika)', en: 'Navajo Tradition (North America)', de: 'Navajo-Tradition (Nordamerika)', es: 'Tradición Navajo (Norteamérica)', pt: 'Tradição Navajo (América do Norte)', fr: 'Tradition Navajo (Amérique du Nord)', ja: 'ナバホの伝統（北米）' }, meaning: { tr: 'Büyük Kondor benzeri kuşlar yaratılış destanlarında dünyanın ilk temizleyicileri olarak görülür — yeryüzünü ilk insanlar için hazırlarlar.', en: 'Great Condor-like birds in creation epics are seen as the world\'s first purifiers — they prepare the earth for the first humans.', de: 'Große, kondorähnliche Vögel gelten in den Schöpfungsepen als die ersten Reiniger der Welt — sie bereiten die Erde für die ersten Menschen.', es: 'Grandes aves semejantes al cóndor en las epopeyas de creación son vistas como los primeros purificadores del mundo — preparan la tierra para los primeros humanos.', pt: 'Grandes aves semelhantes ao condor nas epopeias da criação são vistas como os primeiros purificadores do mundo — preparam a terra para os primeiros humanos.', fr: 'De grands oiseaux semblables au condor, dans les épopées de la création, sont vus comme les premiers purificateurs du monde — ils préparent la terre pour les premiers humains.', ja: '創造叙事詩における巨大なコンドルに似た鳥は、世界最初の浄め手とされる——最初の人々のために大地を整える。' } },
      { culture: { tr: 'Kolomb Öncesi Sanatı', en: 'Pre-Columbian Art', de: 'Präkolumbische Kunst', es: 'Arte Precolombino', pt: 'Arte Pré-Colombiana', fr: 'Art Précolombien', ja: 'コロンブス以前の美術' }, meaning: { tr: 'Nazca çizgilerindeki dev Kondor figürü, gökyüzü tanrılarına yapılan mesaj olarak yorumlanmaktadır — yeryüzünden göğe açılan bir dua.', en: 'The giant Condor figure in the Nazca lines is interpreted as a message to sky gods — a prayer opening from earth to heaven.', de: 'Die riesige Kondorfigur in den Nazca-Linien wird als Botschaft an die Himmelsgötter gedeutet — ein Gebet, das sich von der Erde zum Himmel öffnet.', es: 'La gigantesca figura del cóndor en las líneas de Nazca se interpreta como un mensaje a los dioses del cielo — una oración que se abre de la tierra al cielo.', pt: 'A gigantesca figura do condor nas linhas de Nazca é interpretada como uma mensagem aos deuses do céu — uma oração que se abre da terra ao céu.', fr: 'La gigantesque figure du condor dans les lignes de Nazca est interprétée comme un message aux dieux du ciel — une prière qui s\'ouvre de la terre au ciel.', ja: 'ナスカの地上絵の巨大なコンドルの図は、天空の神々への伝言と解される——地から天へ開かれる祈り。' } },
    ],
    myths: [
      { tr: 'And efsanesinde Kondor bir zamanlar yerden çok alçak uçarmış ve günde üç öğün yemek yermiş. Bir gün gökyüzüne çıkmaya karar vermiş, açlık ve rüzgara katlanmayı öğrenmiş. Artık haftalar boyunca yemeden uçabiliyormuş. Feragat, özgürlüğün bedelidir.', en: 'In Andean legend, the Condor once flew very close to the ground and ate three meals a day. One day it decided to ascend to the sky, and learned to endure hunger and wind. It could now fly for weeks without eating. Renunciation is the price of freedom.', de: 'In der andinen Legende flog der Kondor einst sehr niedrig über dem Boden und aß dreimal täglich. Eines Tages beschloss er, zum Himmel aufzusteigen, und lernte, Hunger und Wind zu ertragen. Nun konnte er wochenlang ohne Nahrung fliegen. Der Verzicht ist der Preis der Freiheit.', es: 'En la leyenda andina, el cóndor volaba antaño muy cerca del suelo y comía tres veces al día. Un día decidió ascender al cielo y aprendió a soportar el hambre y el viento. Ya podía volar semanas sin comer. La renuncia es el precio de la libertad.', pt: 'Na lenda andina, o condor voava outrora muito perto do chão e comia três refeições por dia. Um dia decidiu subir ao céu e aprendeu a suportar a fome e o vento. Já podia voar semanas sem comer. A renúncia é o preço da liberdade.', fr: 'Dans la légende andine, le condor volait jadis très près du sol et mangeait trois repas par jour. Un jour il décida de monter au ciel et apprit à endurer la faim et le vent. Il pouvait désormais voler des semaines sans manger. Le renoncement est le prix de la liberté.', ja: 'アンデスの伝説では、コンドルはかつて地に近く飛び、一日三度食べていた。ある日、天へ昇ろうと決め、飢えと風に耐えることを学んだ。今や幾週も食べずに飛べるようになった。放棄こそ自由の代償。' },
      { tr: 'Quechua geleneğinde "Kondor ile Kartal Dansı" kehaneti: Batı\'nın Kartalı ile Doğu\'nun Kondoru her 500 yılda bir bir araya gelir ve insan bilincinde yeni bir çağ açılır. Son buluşma 1990\'larda gerçekleşmiş — zihin ile kalbin birleşme çağıdır.', en: 'In Quechua tradition, the prophecy of the "Dance of the Condor and Eagle": the Eagle of the West and the Condor of the East meet every 500 years, opening a new era in human consciousness. The last meeting occurred in the 1990s — it is the age of the union of mind and heart.', de: 'In der Quechua-Tradition die Prophezeiung des "Tanzes von Kondor und Adler": Der Adler des Westens und der Kondor des Ostens treffen sich alle 500 Jahre und eröffnen eine neue Ära im menschlichen Bewusstsein. Das letzte Treffen geschah in den 1990er Jahren — es ist das Zeitalter der Vereinigung von Verstand und Herz.', es: 'En la tradición quechua, la profecía de la "Danza del Cóndor y el Águila": el Águila del Oeste y el Cóndor del Este se encuentran cada 500 años, abriendo una nueva era en la conciencia humana. El último encuentro ocurrió en los años 1990 — es la era de la unión de la mente y el corazón.', pt: 'Na tradição quechua, a profecia da "Dança do Condor e da Águia": a Águia do Oeste e o Condor do Leste encontram-se a cada 500 anos, abrindo uma nova era na consciência humana. O último encontro ocorreu nos anos 1990 — é a era da união da mente e do coração.', fr: 'Dans la tradition quechua, la prophétie de la "Danse du Condor et de l\'Aigle" : l\'Aigle de l\'Ouest et le Condor de l\'Est se rencontrent tous les 500 ans, ouvrant une nouvelle ère dans la conscience humaine. La dernière rencontre eut lieu dans les années 1990 — c\'est l\'âge de l\'union de l\'esprit et du cœur.', ja: 'ケチュアの伝統における「コンドルとワシの踊り」の予言——西のワシと東のコンドルは五百年ごとに出会い、人間の意識に新たな時代を開く。最後の出会いは一九九〇年代に起きた——心と頭が一つになる時代である。' },
    ],
  },

  // ─── a053 Somon ──────────────────────────────────────────────────────────
  a053: {
    jung: { tr: '"Köke Dönüş" arketipi. Somon, kolektif bilinçdışında en derin özlem dürtüsünü taşır — kaynağa dönme, doğduğun yerde ölme, tamamlanma iştiyakı. Nehre karşı yüzme imgesi, bilinçdışı direncin bilinçli azimle aşılmasını simgeler.', en: 'The "Return to the Root" archetype. The Salmon carries the deepest longing impulse in the collective unconscious — returning to the source, dying where you were born, the yearning for completion. The image of swimming against the river symbolizes overcoming unconscious resistance with conscious determination.', de: 'Der Archetyp der "Rückkehr zur Wurzel". Der Lachs trägt den tiefsten Sehnsuchtsimpuls im kollektiven Unbewussten — die Rückkehr zur Quelle, das Sterben dort, wo man geboren wurde, die Sehnsucht nach Vollendung. Das Bild des Schwimmens gegen den Strom versinnbildlicht die Überwindung unbewussten Widerstands durch bewusste Entschlossenheit.', es: 'El arquetipo del "Retorno a la Raíz". El salmón porta el impulso de anhelo más profundo en el inconsciente colectivo — volver a la fuente, morir donde naciste, el ansia de plenitud. La imagen de nadar contra el río simboliza vencer la resistencia inconsciente con determinación consciente.', pt: 'O arquétipo do "Regresso à Raiz". O salmão carrega o impulso de anseio mais profundo no inconsciente coletivo — regressar à fonte, morrer onde nasceste, o desejo de plenitude. A imagem de nadar contra o rio simboliza superar a resistência inconsciente com determinação consciente.', fr: 'L\'archétype du "Retour à la racine". Le saumon porte la pulsion de nostalgie la plus profonde de l\'inconscient collectif — revenir à la source, mourir là où l\'on est né, l\'aspiration à l\'accomplissement. L\'image de nager à contre-courant symbolise le dépassement de la résistance inconsciente par la détermination consciente.', ja: '「根への回帰」の元型。サケは集合的無意識の最も深い憧れの衝動を担う——源へ帰ること、生まれた場所で死ぬこと、成就への渇望。川を遡る姿は、無意識の抵抗を意識的な不屈で越えることを象徴する。' },
    dream: { tr: 'Somon rüyada görünürse — köküne, ailenle ya da özünle olan bağına dikkat çekiliyor. Nehre karşı yüzüyorsa: zorlu ama doğru bir yoldayısın, bırakma. Ölüp nehre düşüyorsa: bir misyonun tamamlandı, verdiğin şey senden çok daha büyük bir hayatı besleyecek.', en: 'If Salmon appears in a dream — attention is drawn to your root, your bond with family or your core self. If it swims upstream: you are on a difficult but right path, do not quit. If it dies and falls into the river: a mission has been completed, what you have given will nourish a life far greater than yourself.', de: 'Erscheint der Lachs im Traum — die Aufmerksamkeit richtet sich auf deine Wurzel, deine Bindung an die Familie oder dein Kernselbst. Schwimmt er stromaufwärts: Du bist auf einem schweren, aber richtigen Weg, gib nicht auf. Stirbt er und fällt in den Fluss: Eine Mission ist vollendet, was du gegeben hast, wird ein Leben nähren, das weit größer ist als du.', es: 'Si el salmón aparece en sueños — se llama la atención sobre tu raíz, tu vínculo con la familia o tu yo esencial. Si nada río arriba: vas por un camino difícil pero correcto, no abandones. Si muere y cae al río: una misión se ha cumplido, lo que has dado nutrirá una vida mucho mayor que tú.', pt: 'Se o salmão aparece em sonho — chama-se a atenção para a tua raiz, o teu vínculo com a família ou o teu eu essencial. Se nada rio acima: estás num caminho difícil mas certo, não desistas. Se morre e cai no rio: uma missão cumpriu-se, o que deste nutrirá uma vida muito maior do que tu.', fr: 'Si le saumon apparaît en rêve — l\'attention est attirée sur ta racine, ton lien avec la famille ou ton soi essentiel. S\'il nage à contre-courant : tu es sur un chemin difficile mais juste, n\'abandonne pas. S\'il meurt et tombe dans le fleuve : une mission est accomplie, ce que tu as donné nourrira une vie bien plus grande que toi.', ja: '夢にサケが現れるなら——あなたの根、家族や本質との絆に注意が向けられている。川を遡るなら、険しくも正しい道にある。やめるな。死んで川に落ちるなら、一つの使命が果たされた。あなたが与えたものは、あなたよりはるかに大きな命を養うだろう。' },
    shadow: { tr: '"Geri dönmek zorundayım" takıntısı nostaljiye, gerçek anlamda ilerlemeyi reddeden bir geçmiş hapsolmasına dönüşebilir. Ya da tam tersi: köksüzlük, kaynaktan tamamen kopuş, hafıza yoksunluğu.', en: 'The obsession with "I must return" can turn into nostalgia, imprisonment in the past that truly refuses forward movement. Or the opposite: rootlessness, complete severance from the source, deprivation of memory.', de: 'Die Besessenheit von "Ich muss zurück" kann zur Nostalgie werden, zu einer Gefangenschaft in der Vergangenheit, die echtes Vorwärtsschreiten verweigert. Oder das Gegenteil: Wurzellosigkeit, völlige Abtrennung von der Quelle, Verlust der Erinnerung.', es: 'La obsesión de "debo volver" puede convertirse en nostalgia, en una prisión del pasado que de verdad rechaza avanzar. O lo contrario: desarraigo, ruptura total con la fuente, privación de memoria.', pt: 'A obsessão de "tenho de voltar" pode tornar-se nostalgia, uma prisão no passado que verdadeiramente recusa avançar. Ou o oposto: desenraizamento, rutura total com a fonte, privação de memória.', fr: 'L\'obsession de "je dois revenir" peut tourner à la nostalgie, à un emprisonnement dans le passé qui refuse vraiment d\'avancer. Ou l\'inverse : déracinement, rupture totale avec la source, privation de mémoire.', ja: '「戻らねばならない」という強迫は、郷愁へ、真に前進を拒む過去への囚われへと転じうる。あるいはその逆——根を失うこと、源からの完全な断絶、記憶の欠如。' },
    whenAppears: { tr: 'Göç sonrası özlem dönemlerinde, aile kökenlerinizi araştırırken ya da büyük bir projeyi tamamlamak için son güçlerinizi toplarken.', en: 'During periods of longing after migration, while researching your family origins, or when gathering your final strength to complete a great project.', de: 'In Zeiten der Sehnsucht nach einer Migration, während du deine familiären Ursprünge erforschst, oder wenn du deine letzten Kräfte sammelst, um ein großes Vorhaben zu vollenden.', es: 'En períodos de añoranza tras una migración, mientras investigas tus orígenes familiares, o al reunir tus últimas fuerzas para completar un gran proyecto.', pt: 'Em períodos de saudade após uma migração, ao investigares as tuas origens familiares, ou ao reunires as tuas últimas forças para completar um grande projeto.', fr: 'Dans les périodes de nostalgie après une migration, en recherchant tes origines familiales, ou en rassemblant tes dernières forces pour achever un grand projet.', ja: '移住ののちの郷愁の時期に、家族の起源を調べるとき、あるいは大いなる企てを成し遂げるため最後の力を振り絞るときに。' },
    traditions: [
      { culture: { tr: 'Kelt Geleneği', en: 'Celtic Tradition', de: 'Keltische Tradition', es: 'Tradición Celta', pt: 'Tradição Celta', fr: 'Tradition Celtique', ja: 'ケルトの伝統' }, meaning: { tr: 'Fionn\'un efsanevi Bilgelik Somonu — kim yerse evrenin tüm bilgisini kazanır. Druid geleneğinde Somon, akarsularda yaşayan en eski bilge varlıktır.', en: 'The legendary Salmon of Wisdom of Fionn — whoever eats it gains all the knowledge of the universe. In Druid tradition, the Salmon is the oldest wise being living in watercourses.', de: 'Der legendäre Weisheitslachs des Fionn — wer ihn isst, erlangt alles Wissen des Universums. In der Druidentradition ist der Lachs das älteste weise Wesen, das in Gewässern lebt.', es: 'El legendario Salmón de la Sabiduría de Fionn — quien lo come gana todo el conocimiento del universo. En la tradición druida, el salmón es el ser sabio más antiguo que vive en los cursos de agua.', pt: 'O lendário Salmão da Sabedoria de Fionn — quem o come ganha todo o conhecimento do universo. Na tradição druida, o salmão é o ser sábio mais antigo que vive nos cursos de água.', fr: 'Le légendaire Saumon de la Sagesse de Fionn — quiconque le mange acquiert tout le savoir de l\'univers. Dans la tradition druidique, le saumon est le plus ancien être sage vivant dans les cours d\'eau.', ja: 'フィンの伝説的な知恵のサケ——食した者は宇宙のすべての知を得る。ドルイドの伝統において、サケは川に棲む最も古き賢者。' } },
      { culture: { tr: 'Kuzeybatı Amerika Yerlileri', en: 'Pacific Northwest Indigenous Peoples', de: 'Indigene Völker des pazifischen Nordwestens', es: 'Pueblos Indígenas del Noroeste del Pacífico', pt: 'Povos Indígenas do Noroeste do Pacífico', fr: 'Peuples Autochtones du Nord-Ouest Pacifique', ja: '太平洋岸北西部の先住民' }, meaning: { tr: 'Somon kutsal bir armağandır — nehre geri döner ve ölümüyle ormanı besler. "Somon Halkı" kozmolojisinde Somon ruhları gönüllü olarak kurban olur.', en: 'Salmon is a sacred gift — it returns to the river and with its death nourishes the forest. In the "Salmon People" cosmology, Salmon spirits sacrifice themselves voluntarily.', de: 'Der Lachs ist ein heiliges Geschenk — er kehrt in den Fluss zurück und nährt mit seinem Tod den Wald. In der Kosmologie des "Lachsvolkes" opfern sich die Lachsgeister freiwillig.', es: 'El salmón es un regalo sagrado — vuelve al río y con su muerte nutre el bosque. En la cosmología del "Pueblo Salmón", los espíritus del salmón se sacrifican voluntariamente.', pt: 'O salmão é um presente sagrado — regressa ao rio e com a sua morte nutre a floresta. Na cosmologia do "Povo Salmão", os espíritos do salmão sacrificam-se voluntariamente.', fr: 'Le saumon est un don sacré — il retourne à la rivière et par sa mort nourrit la forêt. Dans la cosmologie du "Peuple Saumon", les esprits du saumon se sacrifient volontairement.', ja: 'サケは聖なる贈り物——川へ戻り、その死によって森を養う。「サケの民」の宇宙観において、サケの霊は自ら進んで犠牲となる。' } },
      { culture: { tr: 'Japon Geleneği', en: 'Japanese Tradition', de: 'Japanische Tradition', es: 'Tradición Japonesa', pt: 'Tradição Japonesa', fr: 'Tradition Japonaise', ja: '日本の伝統' }, meaning: { tr: 'Sake (Somon) döngüsü, Japon Shinto geleneğinde doğanın mükemmel çemberi olarak anlatılır. Tanrı Watatsumi\'nin hediyesidir.', en: 'The salmon (sake) cycle is described in Japanese Shinto tradition as the perfect circle of nature. It is the gift of the god Watatsumi.', de: 'Der Lachszyklus (sake) wird in der japanischen Shinto-Tradition als der vollkommene Kreis der Natur beschrieben. Er ist das Geschenk des Gottes Watatsumi.', es: 'El ciclo del salmón (sake) se describe en la tradición sintoísta japonesa como el círculo perfecto de la naturaleza. Es el regalo del dios Watatsumi.', pt: 'O ciclo do salmão (sake) é descrito na tradição xintoísta japonesa como o círculo perfeito da natureza. É o presente do deus Watatsumi.', fr: 'Le cycle du saumon (sake) est décrit dans la tradition shinto japonaise comme le cercle parfait de la nature. C\'est le don du dieu Watatsumi.', ja: 'サケ（鮭）の循環は、日本の神道の伝統において自然の完全な円として語られる。神ワタツミの贈り物。' } },
      { culture: { tr: 'İskandinav Mitolojisi', en: 'Norse Mythology', de: 'Nordische Mythologie', es: 'Mitología Nórdica', pt: 'Mitologia Nórdica', fr: 'Mythologie Nordique', ja: '北欧神話' }, meaning: { tr: 'Hileci Loki Somon kılığına girerek tanrılardan kaçtı. Ağlara takılınca tanrılar onu yakaladı. Somon burada dönüşüm ve tespit edilemeyen zekânın simgesidir.', en: 'The trickster Loki disguised himself as a Salmon to escape the gods. When caught in nets, the gods captured him. Here the Salmon is a symbol of transformation and undetectable intelligence.', de: 'Der Trickster Loki verkleidete sich als Lachs, um den Göttern zu entkommen. Als er sich in Netzen verfing, fingen die Götter ihn. Hier ist der Lachs Symbol der Verwandlung und der unentdeckbaren Klugheit.', es: 'El embaucador Loki se disfrazó de salmón para escapar de los dioses. Al quedar atrapado en las redes, los dioses lo capturaron. Aquí el salmón es símbolo de la transformación y la inteligencia indetectable.', pt: 'O trapaceiro Loki disfarçou-se de salmão para escapar aos deuses. Ao ficar preso nas redes, os deuses capturaram-no. Aqui o salmão é símbolo da transformação e da inteligência indetetável.', fr: 'Le filou Loki se déguisa en saumon pour échapper aux dieux. Pris dans les filets, les dieux le capturèrent. Ici le saumon est symbole de la transformation et de l\'intelligence indétectable.', ja: 'トリックスターのロキは神々から逃れるためサケに化けた。網にかかると、神々は彼を捕らえた。ここでサケは変容と見破られぬ知の象徴。' } },
      { culture: { tr: 'Anadolu Su Kültleri', en: 'Anatolian Water Cults', de: 'Anatolische Wasserkulte', es: 'Cultos Acuáticos Anatolios', pt: 'Cultos Aquáticos Anatólios', fr: 'Cultes de l\'Eau Anatoliens', ja: 'アナトリアの水の祭祀' }, meaning: { tr: 'Kutsal su kaynakları çevresinde yaşayan büyük balıklar, Anadolu halk inancında dile getirilmez — onlara dokunmak kehaneti bozmak demektir.', en: 'Large fish living around sacred springs cannot be touched in Anatolian folk belief — to touch them is to break the prophecy.', de: 'Große Fische, die um heilige Quellen leben, dürfen im anatolischen Volksglauben nicht berührt werden — sie zu berühren heißt, die Weissagung zu brechen.', es: 'Los grandes peces que viven alrededor de los manantiales sagrados no pueden tocarse en la creencia popular anatolia — tocarlos es romper la profecía.', pt: 'Os grandes peixes que vivem em torno das nascentes sagradas não podem ser tocados na crença popular anatólia — tocá-los é quebrar a profecia.', fr: 'Les grands poissons vivant autour des sources sacrées ne peuvent être touchés dans la croyance populaire anatolienne — les toucher, c\'est briser la prophétie.', ja: '聖なる泉のまわりに棲む大きな魚は、アナトリアの民間信仰では触れてはならぬ——触れることは予言を破ること。' } },
    ],
    myths: [
      { tr: 'İrlanda\'da Fionn mac Cumhaill efsanesi: Yaşlı şair Finnegas yıllarca Boyne Nehri\'nde Bilgelik Somonu\'nu avlamaya çalışır. Sonunda yakalar ve pişirmesi için genç Fionn\'a verir. Fionn yanlışlıkla başparmağını yakar, emer — tüm bilgelik ona geçer. Bilgelik her zaman hazırlanana değil, hazır olana gelir.', en: 'The legend of Fionn mac Cumhaill in Ireland: The old poet Finnegas tries for years to catch the Salmon of Wisdom in the River Boyne. He finally catches it and gives it to young Fionn to cook. Fionn accidentally burns his thumb, sucks it — all wisdom passes to him. Wisdom always comes not to the one who is prepared, but to the one who is ready.', de: 'Die Legende von Fionn mac Cumhaill in Irland: Der alte Dichter Finnegas versucht jahrelang, den Weisheitslachs im Fluss Boyne zu fangen. Endlich fängt er ihn und gibt ihn dem jungen Fionn zum Kochen. Fionn verbrennt sich versehentlich den Daumen und saugt daran — alle Weisheit geht auf ihn über. Weisheit kommt stets nicht zu dem, der sich vorbereitet hat, sondern zu dem, der bereit ist.', es: 'La leyenda de Fionn mac Cumhaill en Irlanda: El viejo poeta Finnegas intenta durante años pescar el Salmón de la Sabiduría en el río Boyne. Por fin lo pesca y se lo da al joven Fionn para que lo cocine. Fionn se quema sin querer el pulgar y lo chupa — toda la sabiduría pasa a él. La sabiduría siempre llega no al que se ha preparado, sino al que está listo.', pt: 'A lenda de Fionn mac Cumhaill na Irlanda: O velho poeta Finnegas tenta durante anos pescar o Salmão da Sabedoria no rio Boyne. Por fim apanha-o e dá-o ao jovem Fionn para cozinhar. Fionn queima sem querer o polegar e chupa-o — toda a sabedoria passa para ele. A sabedoria chega sempre não a quem se preparou, mas a quem está pronto.', fr: 'La légende de Fionn mac Cumhaill en Irlande : Le vieux poète Finnegas tente des années durant de pêcher le Saumon de la Sagesse dans la rivière Boyne. Il l\'attrape enfin et le donne au jeune Fionn pour le cuire. Fionn se brûle par mégarde le pouce, le suce — toute la sagesse passe en lui. La sagesse vient toujours non à celui qui s\'est préparé, mais à celui qui est prêt.', ja: 'アイルランドのフィン・マックール伝説：老いた詩人フィネガスは何年もボイン川で知恵のサケを釣ろうとする。ついに釣り上げ、若いフィンに焼くよう託す。フィンはうっかり親指を焼き、しゃぶる——すべての知恵が彼に移る。知恵は、備えた者にではなく、用意ある者に訪れる。' },
      { tr: 'Kuzey Amerika\'nın Haida geleneğinde Somon Halkı, okyanus dibinde insan biçiminde yaşar. Her yıl insanlara armağan olmak için Somon kılığına girer ve nehirlere çıkar. Kemikleri özenle suya iade edilirse, bir sonraki yıl yeniden gelirler. Bu efsane, minnetle karşılanan her armağanın yenileneceğini anlatır.', en: 'In the Haida tradition of North America, the Salmon People live in human form at the ocean floor. Each year they take the form of Salmon to be a gift to humans and ascend the rivers. If their bones are returned carefully to the water, they come again the following year. This legend tells that every gift received with gratitude will be renewed.', de: 'In der Haida-Tradition Nordamerikas lebt das Lachsvolk in menschlicher Gestalt auf dem Meeresgrund. Jedes Jahr nimmt es Lachsgestalt an, um den Menschen ein Geschenk zu sein, und steigt die Flüsse hinauf. Werden ihre Knochen sorgsam ins Wasser zurückgegeben, kommen sie im nächsten Jahr wieder. Diese Legende lehrt, dass jedes mit Dankbarkeit empfangene Geschenk sich erneuert.', es: 'En la tradición haida de Norteamérica, el Pueblo Salmón vive en forma humana en el fondo del océano. Cada año toma forma de salmón para ser un regalo a los humanos y remonta los ríos. Si sus huesos se devuelven con cuidado al agua, vuelven al año siguiente. Esta leyenda enseña que todo regalo recibido con gratitud se renovará.', pt: 'Na tradição haida da América do Norte, o Povo Salmão vive em forma humana no fundo do oceano. Cada ano toma a forma de salmão para ser um presente aos humanos e sobe os rios. Se os seus ossos forem devolvidos com cuidado à água, voltam no ano seguinte. Esta lenda ensina que todo o presente recebido com gratidão se renovará.', fr: 'Dans la tradition haïda d\'Amérique du Nord, le Peuple Saumon vit sous forme humaine au fond de l\'océan. Chaque année il prend la forme du saumon pour être un don aux humains et remonte les rivières. Si leurs os sont rendus avec soin à l\'eau, ils reviennent l\'année suivante. Cette légende enseigne que tout don reçu avec gratitude se renouvellera.', ja: '北米のハイダの伝統において、サケの民は海の底で人の姿で暮らす。毎年、人々への贈り物となるためサケの姿をとり、川を遡る。その骨が丁寧に水へ返されれば、翌年また訪れる。この伝説は、感謝をもって受け取られた贈り物はすべて新たになると説く。' },
    ],
  },

  // ─── a054 Sinek Kuşu ─────────────────────────────────────────────────────
  a054: {
    jung: { tr: '"Ebedi Neşe ve Savaşçı Hafiflik" arketipi. Sinek Kuşu, bilinçdışında paradoksu taşır: en küçük beden, en büyük enerji. Saniyede yüz kez kanat çırpmak — bu, varoluşun tam yoğunluğuyla yaşanmasının imgesidir. Tatlılığa yönelim (çiçekten çiçeğe) ise ruhun yaşamın özünü aramasını simgeler.', en: 'The "Eternal Joy and Warrior Lightness" archetype. The Hummingbird carries the paradox in the unconscious: the smallest body, the greatest energy. Beating wings a hundred times per second — this is the image of life lived at full intensity. The orientation toward sweetness (flower to flower) symbolizes the soul\'s search for life\'s essence.', de: 'Der Archetyp der "ewigen Freude und kriegerischen Leichtigkeit". Der Kolibri trägt im Unbewussten das Paradox: der kleinste Leib, die größte Energie. Hundert Flügelschläge pro Sekunde — das ist das Bild eines mit voller Intensität gelebten Lebens. Die Hinwendung zur Süße (von Blüte zu Blüte) versinnbildlicht die Suche der Seele nach dem Wesen des Lebens.', es: 'El arquetipo de la "Alegría Eterna y Ligereza Guerrera". El colibrí porta la paradoja en el inconsciente: el cuerpo más pequeño, la energía más grande. Batir las alas cien veces por segundo — esta es la imagen de la vida vivida a plena intensidad. La orientación hacia la dulzura (de flor en flor) simboliza la búsqueda del alma por la esencia de la vida.', pt: 'O arquétipo da "Alegria Eterna e Leveza Guerreira". O beija-flor carrega o paradoxo no inconsciente: o corpo mais pequeno, a maior energia. Bater as asas cem vezes por segundo — esta é a imagem da vida vivida em plena intensidade. A orientação para a doçura (de flor em flor) simboliza a busca da alma pela essência da vida.', fr: 'L\'archétype de la "Joie éternelle et Légèreté guerrière". Le colibri porte le paradoxe dans l\'inconscient : le plus petit corps, la plus grande énergie. Battre des ailes cent fois par seconde — c\'est l\'image de la vie vécue à pleine intensité. L\'orientation vers la douceur (de fleur en fleur) symbolise la quête de l\'âme pour l\'essence de la vie.', ja: '「永遠の歓びと戦士の軽やかさ」の元型。ハチドリは無意識のうちに逆説を担う——最も小さな体、最も大きなエネルギー。一秒に百度羽ばたくこと——それは存在を全き強度で生きることの像。甘美への向き（花から花へ）は、魂が生の本質を求めることを象徴する。' },
    dream: { tr: 'Sinek Kuşu rüyada — baskı altında bile neşeyi korumanın mümkün olduğuna dair bir hatırlatma. Çiçeğe konuyorsa: en küçük zevklerden beslen. Kaçıp gidiyorsa: güzelliği yakalamanın yolu onu kovalamak değil, kendini güzelliğe açmaktır.', en: 'Hummingbird in a dream — a reminder that it is possible to maintain joy even under pressure. If it lands on a flower: nourish yourself from the smallest pleasures. If it flies away: the way to capture beauty is not to chase it but to open yourself to beauty.', de: 'Kolibri im Traum — eine Erinnerung daran, dass es möglich ist, selbst unter Druck die Freude zu bewahren. Landet er auf einer Blüte: Nähre dich an den kleinsten Freuden. Fliegt er davon: Der Weg, Schönheit zu erfassen, ist nicht, sie zu jagen, sondern sich der Schönheit zu öffnen.', es: 'Colibrí en sueños — un recordatorio de que es posible mantener la alegría incluso bajo presión. Si se posa en una flor: nútrete de los placeres más pequeños. Si vuela lejos: el modo de capturar la belleza no es perseguirla, sino abrirte a ella.', pt: 'Beija-flor em sonho — uma lembrança de que é possível manter a alegria mesmo sob pressão. Se pousa numa flor: nutre-te dos prazeres mais pequenos. Se voa para longe: o modo de capturar a beleza não é persegui-la, mas abrires-te à beleza.', fr: 'Colibri en rêve — un rappel qu\'il est possible de garder la joie même sous pression. S\'il se pose sur une fleur : nourris-toi des plus petits plaisirs. S\'il s\'envole : la façon de saisir la beauté n\'est pas de la poursuivre mais de t\'ouvrir à elle.', ja: '夢の中のハチドリ——重圧のもとでさえ歓びを保てるという思い出させ。花に止まるなら、最も小さな喜びから養われよ。飛び去るなら、美を捉える道はそれを追うことではなく、自らを美へ開くこと。' },
    shadow: { tr: 'Aşırı hız ve enerjinin tükenmişliğe dönüşmesi — sürekli hareket halinde olmak derinleşmeyi engeller. Sinek Kuşu gölgesi: yüzeysellik, bir şeyde uzun süre kalmamak, doyumsuzluk.', en: 'Excessive speed and energy turning into burnout — being in constant motion prevents deepening. The Hummingbird shadow: superficiality, not staying in one thing for long, insatiability.', de: 'Übermäßige Schnelligkeit und Energie, die zur Erschöpfung wird — die ständige Bewegung verhindert die Vertiefung. Der Kolibrischatten: Oberflächlichkeit, nicht lange bei einer Sache zu bleiben, Unersättlichkeit.', es: 'La velocidad y la energía excesivas convirtiéndose en agotamiento — estar en constante movimiento impide profundizar. La sombra del colibrí: superficialidad, no permanecer mucho en una cosa, insaciabilidad.', pt: 'A velocidade e a energia excessivas tornando-se esgotamento — estar em constante movimento impede o aprofundamento. A sombra do beija-flor: superficialidade, não permanecer muito numa coisa, insaciabilidade.', fr: 'La vitesse et l\'énergie excessives tournant à l\'épuisement — être en mouvement constant empêche d\'approfondir. L\'ombre du colibri : superficialité, ne pas rester longtemps sur une chose, insatiabilité.', ja: '過度の速さとエネルギーが燃え尽きに転じること——絶えず動き続けることは深まりを妨げる。ハチドリの影——浅薄さ、一つのことに長くとどまらぬこと、飽くなさ。' },
    whenAppears: { tr: 'Hayatın ağırlaştığı dönemlerde, neşeyi unuttuğunuzda ya da küçük anlardaki güzelliği göremez hale geldiğinizde.', en: 'During periods when life has grown heavy, when you have forgotten joy, or when you can no longer see the beauty in small moments.', de: 'In Zeiten, in denen das Leben schwer geworden ist, wenn du die Freude vergessen hast oder die Schönheit in kleinen Augenblicken nicht mehr sehen kannst.', es: 'En períodos en que la vida se ha vuelto pesada, cuando has olvidado la alegría, o cuando ya no puedes ver la belleza en los pequeños momentos.', pt: 'Em períodos em que a vida se tornou pesada, quando esqueceste a alegria, ou quando já não consegues ver a beleza nos pequenos momentos.', fr: 'Dans les périodes où la vie s\'est alourdie, quand tu as oublié la joie, ou quand tu ne peux plus voir la beauté dans les petits instants.', ja: '人生が重くなった時期に、歓びを忘れたとき、あるいは小さな瞬間の美が見えなくなったときに。' },
    traditions: [
      { culture: { tr: 'Aztek Mitolojisi', en: 'Aztec Mythology', de: 'Aztekische Mythologie', es: 'Mitología Azteca', pt: 'Mitologia Asteca', fr: 'Mythologie Aztèque', ja: 'アステカ神話' }, meaning: { tr: 'Huitzilopochtli — Azteklerin güneş ve savaş tanrısı, Sinek Kuşu anlamına gelir. Savaşta ölen savaşçıların ruhları Sinek Kuşu olarak yeniden doğar ve güneşe refakat ederdi.', en: 'Huitzilopochtli — the Aztec god of sun and war, means Hummingbird. The souls of warriors who died in battle were reborn as Hummingbirds and accompanied the sun.', de: 'Huitzilopochtli — der aztekische Gott der Sonne und des Krieges, bedeutet Kolibri. Die Seelen der im Kampf gefallenen Krieger wurden als Kolibris wiedergeboren und begleiteten die Sonne.', es: 'Huitzilopochtli — el dios azteca del sol y la guerra, significa colibrí. Las almas de los guerreros muertos en batalla renacían como colibríes y acompañaban al sol.', pt: 'Huitzilopochtli — o deus asteca do sol e da guerra, significa beija-flor. As almas dos guerreiros mortos em batalha renasciam como beija-flores e acompanhavam o sol.', fr: 'Huitzilopochtli — le dieu aztèque du soleil et de la guerre, signifie colibri. Les âmes des guerriers morts au combat renaissaient en colibris et accompagnaient le soleil.', ja: 'ウィツィロポチトリ——アステカの太陽と戦の神。ハチドリを意味する。戦で死んだ戦士の魂はハチドリとして生まれ変わり、太陽に付き従った。' } },
      { culture: { tr: 'Kızılderili Taíno Geleneği', en: 'Taíno Indigenous Tradition', de: 'Indigene Taíno-Tradition', es: 'Tradición Indígena Taína', pt: 'Tradição Indígena Taína', fr: 'Tradition Autochtone Taïno', ja: 'タイノ先住民の伝統' }, meaning: { tr: 'Zunzuncito — barışın ve sevginin elçisi. İki düşman kabilenin aşk hikâyesini birbirine taşıyan kutsal haberci.', en: 'Zunzuncito — messenger of peace and love. The sacred herald carrying love stories between two enemy tribes.', de: 'Zunzuncito — Bote des Friedens und der Liebe. Der heilige Herold, der Liebesgeschichten zwischen zwei verfeindeten Stämmen trägt.', es: 'Zunzuncito — mensajero de la paz y el amor. El heraldo sagrado que lleva historias de amor entre dos tribus enemigas.', pt: 'Zunzuncito — mensageiro da paz e do amor. O arauto sagrado que leva histórias de amor entre duas tribos inimigas.', fr: 'Zunzuncito — messager de la paix et de l\'amour. Le héraut sacré qui porte des histoires d\'amour entre deux tribus ennemies.', ja: 'スンスンシート——平和と愛の使者。敵対する二つの部族のあいだに愛の物語を運ぶ聖なる伝令。' } },
      { culture: { tr: 'Hopi Geleneği', en: 'Hopi Tradition', de: 'Hopi-Tradition', es: 'Tradición Hopi', pt: 'Tradição Hopi', fr: 'Tradition Hopi', ja: 'ホピの伝統' }, meaning: { tr: 'Sinek Kuşu kuraklık zamanlarında yağmur tanrıları için araya girer. Çiçek poleni taşıdığı için bereketin simgesidir.', en: 'The Hummingbird intercedes with the rain gods in times of drought. Because it carries flower pollen, it is a symbol of abundance.', de: 'Der Kolibri legt in Dürrezeiten bei den Regengöttern Fürsprache ein. Weil er Blütenpollen trägt, ist er ein Symbol des Überflusses.', es: 'El colibrí intercede ante los dioses de la lluvia en tiempos de sequía. Por llevar polen de flores, es símbolo de la abundancia.', pt: 'O beija-flor intercede junto aos deuses da chuva em tempos de seca. Por carregar pólen das flores, é símbolo da abundância.', fr: 'Le colibri intercède auprès des dieux de la pluie en temps de sécheresse. Parce qu\'il porte le pollen des fleurs, il est symbole d\'abondance.', ja: 'ハチドリは干ばつの時に雨の神々へとりなす。花粉を運ぶため、豊穣の象徴。' } },
      { culture: { tr: 'Kolombiya Yerlileri', en: 'Colombian Indigenous Peoples', de: 'Indigene Völker Kolumbiens', es: 'Pueblos Indígenas de Colombia', pt: 'Povos Indígenas da Colômbia', fr: 'Peuples Autochtones de Colombie', ja: 'コロンビアの先住民' }, meaning: { tr: 'Sinek Kuşu\'nun tüyleri aşk tılsımlarında kullanılır. Onu rüyada görmek, uzak bir sevgilinin özlemini taşıdığına işaret eder.', en: 'Hummingbird feathers are used in love talismans. To see it in a dream indicates that a distant beloved carries longing for you.', de: 'Kolibrifedern werden in Liebestalismanen verwendet. Ihn im Traum zu sehen, deutet darauf hin, dass eine ferne Geliebte Sehnsucht nach dir trägt.', es: 'Las plumas de colibrí se usan en talismanes de amor. Verlo en un sueño indica que un amado lejano lleva añoranza por ti.', pt: 'As penas de beija-flor usam-se em talismãs de amor. Vê-lo num sonho indica que um amado distante carrega saudade por ti.', fr: 'Les plumes de colibri sont utilisées dans les talismans d\'amour. Le voir en rêve indique qu\'un bien-aimé lointain porte de la nostalgie pour toi.', ja: 'ハチドリの羽は愛の護符に用いられる。夢に見ることは、遠くの恋人があなたへの憧れを抱いている徴。' } },
      { culture: { tr: 'Jamaika Halk Geleneği', en: 'Jamaican Folk Tradition', de: 'Jamaikanische Volkstradition', es: 'Tradición Popular Jamaicana', pt: 'Tradição Popular Jamaicana', fr: 'Tradition Populaire Jamaïcaine', ja: 'ジャマイカ民俗の伝統' }, meaning: { tr: '"Doctor Bird" olarak bilinir — şifa ve dönüşümün simgesi. Uğurlu sayılır, yakalanmaya çalışılmaz; yalnızca izlenir.', en: 'Known as "Doctor Bird" — symbol of healing and transformation. Considered lucky, not to be captured; only observed.', de: 'Bekannt als "Doctor Bird" — Symbol der Heilung und Verwandlung. Gilt als Glücksbringer; man fängt ihn nicht, man beobachtet ihn nur.', es: 'Conocido como "Doctor Bird" — símbolo de la curación y la transformación. Considerado afortunado; no se captura, solo se observa.', pt: 'Conhecido como "Doctor Bird" — símbolo da cura e da transformação. Considerado afortunado; não se captura, apenas se observa.', fr: 'Connu sous le nom de "Doctor Bird" — symbole de la guérison et de la transformation. Tenu pour porte-bonheur ; on ne le capture pas, on l\'observe seulement.', ja: '「ドクターバード」として知られる——癒しと変容の象徴。縁起がよいとされ、捕らえようとはせず、ただ見守られる。' } },
    ],
    myths: [
      { tr: 'Aztek yaratılış destanında Huitzilopochtli annesi Coatlicue\'nin rahminde Sinek Kuşu tüyünden doğar. Kardeşlerinin saldırısına karşı doğar doğmaz silahlanıp savaşa girer. Bu destan, küçük ama tam donanımlı doğanın — savunmaya hazır neşenin — imgesidir.', en: 'In the Aztec creation epic, Huitzilopochtli is born in his mother Coatlicue\'s womb from a hummingbird feather. Against the attack of his siblings he arms himself and enters battle the moment he is born. This epic is the image of one born small but fully equipped — joy ready to defend itself.', de: 'Im aztekischen Schöpfungsepos wird Huitzilopochtli im Mutterleib der Coatlicue aus einer Kolibrifeder geboren. Gegen den Angriff seiner Geschwister wappnet er sich und tritt in dem Augenblick, da er geboren wird, in den Kampf. Dieses Epos ist das Bild eines klein, doch vollständig gerüstet Geborenen — der zur Verteidigung bereiten Freude.', es: 'En la epopeya de creación azteca, Huitzilopochtli nace en el vientre de su madre Coatlicue a partir de una pluma de colibrí. Contra el ataque de sus hermanos se arma y entra en batalla en el momento de nacer. Esta epopeya es la imagen de quien nace pequeño pero plenamente equipado — la alegría lista para defenderse.', pt: 'Na epopeia da criação asteca, Huitzilopochtli nasce no ventre da sua mãe Coatlicue a partir de uma pena de beija-flor. Contra o ataque dos seus irmãos arma-se e entra em batalha no momento em que nasce. Esta epopeia é a imagem de quem nasce pequeno mas plenamente equipado — a alegria pronta a defender-se.', fr: 'Dans l\'épopée de la création aztèque, Huitzilopochtli naît dans le ventre de sa mère Coatlicue d\'une plume de colibri. Contre l\'attaque de ses frères et sœurs, il s\'arme et entre au combat à l\'instant même de sa naissance. Cette épopée est l\'image de celui qui naît petit mais pleinement équipé — la joie prête à se défendre.', ja: 'アステカの創造叙事詩において、ウィツィロポチトリは母コアトリクエの胎内でハチドリの羽から生まれる。兄弟姉妹の襲撃に対し、生まれた瞬間に武装して戦いに入る。この叙事詩は、小さくとも完全に武装して生まれた者——身を守る備えのある歓び——の像である。' },
      { tr: 'Güney Amerika\'nın Quechua anlatısında, dünya henüz çok karanlıkken ve çiçekler açmayı bilmezken, Sinek Kuşu tanrıya gidip yalvarmış: "Bize renk ver." Tanrı Sinek Kuşu\'nun gagasını çiçeğin içine batırmış — ilk nektar böyle doğmuş, çiçekler de o gün renk kazanmış.', en: 'In a Quechua narrative from South America, when the world was still very dark and flowers did not know how to bloom, the Hummingbird went to the god and pleaded: "Give us color." The god dipped the Hummingbird\'s beak inside a flower — the first nectar was thus born, and that day flowers gained their color.', de: 'In einer Quechua-Erzählung aus Südamerika ging der Kolibri, als die Welt noch sehr dunkel war und die Blumen das Blühen nicht kannten, zum Gott und flehte: "Gib uns Farbe." Der Gott tauchte den Schnabel des Kolibris in eine Blüte — so entstand der erste Nektar, und an jenem Tag erhielten die Blumen ihre Farbe.', es: 'En un relato quechua de Sudamérica, cuando el mundo aún era muy oscuro y las flores no sabían florecer, el colibrí fue al dios y suplicó: "Danos color." El dios sumergió el pico del colibrí dentro de una flor — así nació el primer néctar, y ese día las flores ganaron su color.', pt: 'Num relato quechua da América do Sul, quando o mundo era ainda muito escuro e as flores não sabiam florir, o beija-flor foi ao deus e suplicou: "Dá-nos cor." O deus mergulhou o bico do beija-flor dentro de uma flor — assim nasceu o primeiro néctar, e nesse dia as flores ganharam a sua cor.', fr: 'Dans un récit quechua d\'Amérique du Sud, quand le monde était encore très sombre et que les fleurs ne savaient pas éclore, le colibri alla auprès du dieu et supplia : "Donne-nous la couleur." Le dieu plongea le bec du colibri dans une fleur — le premier nectar naquit ainsi, et ce jour-là les fleurs acquirent leur couleur.', ja: '南米のケチュアの語りでは、世界がまだ暗く、花が咲くことを知らなかったころ、ハチドリは神のもとへ行き嘆願した——「私たちに色を与えてください。」神はハチドリの嘴を花の中に浸した——こうして最初の蜜が生まれ、その日に花は色を得た。' },
    ],
  },

  // ─── a055 Yaban Domuzu ───────────────────────────────────────────────────
  a055: {
    jung: { tr: '"Ham Güç ve Savaşçı Yürek" arketipi. Yaban Domuzu, bilinçdışındaki dizginlenmemiş yaşam enerjisini — id\'in en ham biçimini — temsil eder. Cesareti korkuyu yokmuş gibi hareket etmek değil, korku içinde yine de ilerlemektir. Dişleri hem silah hem de toprağı kazan araç: bu, yıkıcılık ile verimliliğin aynı kökten çıkmasıdır.', en: 'The "Raw Power and Warrior Heart" archetype. The Wild Boar represents the untamed life energy in the unconscious — the rawest form of the id. Its courage is not acting as if fear does not exist, but moving forward despite fear. Its tusks are both weapon and tool for digging the earth: this is destructiveness and fertility arising from the same root.', de: 'Der Archetyp der "rohen Kraft und des Kriegerherzens". Der Wildschwein verkörpert die ungezähmte Lebensenergie im Unbewussten — die roheste Form des Es. Sein Mut bedeutet nicht, zu handeln, als gäbe es keine Furcht, sondern trotz der Furcht voranzuschreiten. Seine Hauer sind Waffe und Werkzeug zum Graben der Erde zugleich: So entspringen Zerstörung und Fruchtbarkeit derselben Wurzel.', es: 'El arquetipo del "Poder en Bruto y el Corazón Guerrero". El jabalí representa la energía vital indómita en el inconsciente — la forma más cruda del ello. Su coraje no es actuar como si el miedo no existiera, sino avanzar a pesar del miedo. Sus colmillos son a la vez arma y herramienta para cavar la tierra: la destructividad y la fertilidad brotan de la misma raíz.', pt: 'O arquétipo do "Poder em Bruto e Coração Guerreiro". O javali representa a energia vital indomada no inconsciente — a forma mais crua do id. A sua coragem não é agir como se o medo não existisse, mas avançar apesar do medo. As suas presas são ao mesmo tempo arma e ferramenta para cavar a terra: a destrutividade e a fertilidade brotam da mesma raiz.', fr: 'L\'archétype de la "Puissance brute et du Cœur guerrier". Le sanglier représente l\'énergie vitale indomptée de l\'inconscient — la forme la plus brute du ça. Son courage n\'est pas d\'agir comme si la peur n\'existait pas, mais d\'avancer malgré la peur. Ses défenses sont à la fois arme et outil pour creuser la terre : la destructivité et la fertilité jaillissent de la même racine.', ja: '「素の力と戦士の心」の元型。イノシシは無意識のうちの飼い馴らされぬ生命エネルギー——イドの最も素朴な形——を表す。その勇気とは恐れがないかのように振る舞うことではなく、恐れの中でなお進むこと。その牙は武器であると同時に土を掘る道具——破壊と豊穣が同じ根から生じる。' },
    dream: { tr: 'Yaban Domuzu rüyada saldırıyorsa — bastırılmış öfke ya da savunma ihtiyacı yüzeye çıkıyor; bu enerjiyle yüzleş. Orman içinde sakin yürüyorsa: ham gücünle barışıksın, onu yönlendirme vakti. Sürüyle görünürse: klanına, kolektif güce yaslan.', en: 'If Wild Boar attacks in a dream — suppressed anger or a need for defense is surfacing; confront this energy. If it walks calmly in the forest: you are at peace with your raw power, it is time to channel it. If it appears with a herd: lean on your clan, on collective strength.', de: 'Greift das Wildschwein im Traum an — unterdrückter Zorn oder ein Bedürfnis nach Verteidigung steigt an die Oberfläche; stelle dich dieser Energie. Geht es ruhig durch den Wald: Du bist im Frieden mit deiner rohen Kraft, es ist Zeit, sie zu lenken. Erscheint es mit einer Rotte: Stütze dich auf deinen Klan, auf die kollektive Stärke.', es: 'Si el jabalí ataca en sueños — la ira reprimida o una necesidad de defensa aflora; enfrenta esta energía. Si camina tranquilo por el bosque: estás en paz con tu poder en bruto, es hora de canalizarlo. Si aparece con una manada: apóyate en tu clan, en la fuerza colectiva.', pt: 'Se o javali ataca em sonho — a ira reprimida ou uma necessidade de defesa aflora; enfrenta esta energia. Se caminha calmo na floresta: estás em paz com o teu poder em bruto, é hora de o canalizar. Se aparece com uma vara: apoia-te no teu clã, na força coletiva.', fr: 'Si le sanglier attaque en rêve — une colère réprimée ou un besoin de défense remonte à la surface ; affronte cette énergie. S\'il marche calmement dans la forêt : tu es en paix avec ta puissance brute, il est temps de la canaliser. S\'il apparaît avec une harde : appuie-toi sur ton clan, sur la force collective.', ja: '夢の中でイノシシが襲うなら——抑え込まれた怒りや防御の必要が浮かび上がっている。このエネルギーと向き合え。森を静かに歩むなら、あなたは素の力と和解している。それを導く時。群れで現れるなら、一族、集団の力に寄りかかれ。' },
    shadow: { tr: 'Kontrolsüz saldırganlık — her şeyi kafa kafaya çözme ısrarı, müzakere ve incelik yetisinin körelmesi. Yaban Domuzu gölgesi: kör öfke, etrafındakilere zarar veren savunmacılık, "ben haklıyım" katılığı.', en: 'Uncontrolled aggression — insisting on solving everything head-on, dulling the ability for negotiation and subtlety. The Wild Boar shadow: blind rage, defensiveness that harms those around you, the rigidity of "I am right".', de: 'Unkontrollierte Aggression — auf der Stirn-gegen-Stirn-Lösung aller Dinge zu beharren, die Fähigkeit zu Verhandlung und Feinheit abzustumpfen. Der Wildschweinschatten: blinder Zorn, eine Verteidigungshaltung, die die Umstehenden verletzt, die Starrheit des "Ich habe recht".', es: 'Agresión descontrolada — insistir en resolverlo todo de frente, embotando la capacidad de negociación y sutileza. La sombra del jabalí: ira ciega, una defensividad que daña a quienes te rodean, la rigidez de "yo tengo razón".', pt: 'Agressão descontrolada — insistir em resolver tudo de frente, embotando a capacidade de negociação e subtileza. A sombra do javali: ira cega, uma defensividade que prejudica os que te rodeiam, a rigidez de "eu tenho razão".', fr: 'Agressivité incontrôlée — s\'obstiner à tout résoudre de front, émoussant la capacité de négociation et de subtilité. L\'ombre du sanglier : colère aveugle, une attitude défensive qui blesse l\'entourage, la rigidité du "j\'ai raison".', ja: '制御なき攻撃性——何もかも真正面から解こうと固執し、交渉と機微の力を鈍らせること。イノシシの影——盲目的な怒り、周囲を傷つける防御性、「私が正しい」という硬直。' },
    whenAppears: { tr: 'Kendi sınırlarını korumakta zorlandığınızda, cesaret gerektiren bir karar arifesinde ya da uzun süre bastırdığınız öfkenin nihayet sizi harekete geçirdiğinde.', en: 'When you struggle to protect your own boundaries, on the eve of a decision requiring courage, or when anger long suppressed finally moves you to action.', de: 'Wenn du Mühe hast, deine eigenen Grenzen zu schützen, am Vorabend einer mutfordernden Entscheidung oder wenn lange unterdrückter Zorn dich endlich zum Handeln bewegt.', es: 'Cuando te cuesta proteger tus propios límites, en la víspera de una decisión que exige coraje, o cuando la ira largamente reprimida por fin te mueve a la acción.', pt: 'Quando te custa proteger os teus próprios limites, na véspera de uma decisão que exige coragem, ou quando a ira longamente reprimida finalmente te move à ação.', fr: 'Quand tu peines à protéger tes propres limites, à la veille d\'une décision qui exige du courage, ou quand une colère longtemps réprimée te pousse enfin à agir.', ja: '自らの境界を守るのに苦しむとき、勇気を要する決断の前夜、長く抑え込んだ怒りがついにあなたを行動へと駆り立てるときに。' },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology', de: 'Griechische Mythologie', es: 'Mitología Griega', pt: 'Mitologia Grega', fr: 'Mythologie Grecque', ja: 'ギリシア神話' }, meaning: { tr: 'Ares ve Artemis\'in kutsal hayvanı. Kaledonia Domuzu, Yunanistan\'ın en büyük kahramanlarını bir araya getiren efsanevi av. Herakles\'in dokuzuncu görevi: Erymanthia Domuzu\'nu canlı yakalamak.', en: 'Sacred animal of Ares and Artemis. The Calydonian Boar, the legendary hunt that brought together Greece\'s greatest heroes. Heracles\' ninth labor: to capture the Erymanthian Boar alive.', de: 'Heiliges Tier des Ares und der Artemis. Der Kalydonische Eber, die legendäre Jagd, die Griechenlands größte Helden zusammenführte. Herakles\' neunte Tat: den Erymanthischen Eber lebend zu fangen.', es: 'Animal sagrado de Ares y Artemisa. El jabalí de Calidón, la legendaria cacería que reunió a los más grandes héroes de Grecia. El noveno trabajo de Heracles: capturar vivo al jabalí de Erimanto.', pt: 'Animal sagrado de Ares e Ártemis. O javali de Calidão, a lendária caçada que reuniu os maiores heróis da Grécia. O nono trabalho de Héracles: capturar vivo o javali de Erimanto.', fr: 'Animal sacré d\'Arès et d\'Artémis. Le sanglier de Calydon, la chasse légendaire qui rassembla les plus grands héros de Grèce. Le neuvième travail d\'Héraclès : capturer vivant le sanglier d\'Érymanthe.', ja: 'アレスとアルテミスの聖なる動物。カリュドンのイノシシは、ギリシア最大の英雄たちを集めた伝説の狩り。ヘラクレスの第九の難業——エリュマントスのイノシシを生け捕りにすること。' } },
      { culture: { tr: 'Kelt Geleneği', en: 'Celtic Tradition', de: 'Keltische Tradition', es: 'Tradición Celta', pt: 'Tradição Celta', fr: 'Tradition Celtique', ja: 'ケルトの伝統' }, meaning: { tr: 'Yaban Domuzu Kelt savaşçısının simgesidir — miğferler, kalkanlar ve bayraklarda görülür. Öteki dünyanın kapısını da bekler: kutsal bir yaban domuzu avı çoğunlukla kahramanı öteki âleme taşır.', en: 'The Wild Boar is the symbol of the Celtic warrior — seen on helmets, shields, and banners. It also guards the gateway to the otherworld: a sacred boar hunt often carries the hero to the other realm.', de: 'Der Eber ist das Symbol des keltischen Kriegers — auf Helmen, Schilden und Bannern zu sehen. Er bewacht auch das Tor zum Jenseits: Eine heilige Eberjagd trägt den Helden oft in das andere Reich.', es: 'El jabalí es el símbolo del guerrero celta — se ve en cascos, escudos y estandartes. También custodia la puerta del otro mundo: una cacería sagrada de jabalí a menudo lleva al héroe al otro reino.', pt: 'O javali é o símbolo do guerreiro celta — visto em capacetes, escudos e estandartes. Guarda também o portal do outro mundo: uma caçada sagrada de javali leva muitas vezes o herói ao outro reino.', fr: 'Le sanglier est le symbole du guerrier celte — vu sur les casques, boucliers et bannières. Il garde aussi la porte de l\'autre monde : une chasse sacrée au sanglier emporte souvent le héros vers l\'autre royaume.', ja: 'イノシシはケルトの戦士の象徴——兜、盾、軍旗に見られる。彼岸の門も守る——聖なるイノシシ狩りはしばしば英雄を異界へ運ぶ。' } },
      { culture: { tr: 'Japon Shinto', en: 'Japanese Shinto', de: 'Japanischer Shinto', es: 'Sintoísmo Japonés', pt: 'Xintoísmo Japonês', fr: 'Shinto Japonais', ja: '日本の神道' }, meaning: { tr: 'İnoshishi (Yaban Domuzu) Bishamonten\'in — savaş ve servet tanrısının — bineğidir. Korkmadan ilerlemek ve sezgiyle hareket etmek anlamına gelir.', en: 'Inoshishi (Wild Boar) is the mount of Bishamonten — the god of war and wealth. It means advancing without fear and acting with intuition.', de: 'Inoshishi (Wildschwein) ist das Reittier des Bishamonten — des Gottes des Krieges und des Reichtums. Es bedeutet, furchtlos voranzuschreiten und aus Intuition zu handeln.', es: 'Inoshishi (jabalí) es la montura de Bishamonten — el dios de la guerra y la riqueza. Significa avanzar sin miedo y actuar con intuición.', pt: 'Inoshishi (javali) é a montaria de Bishamonten — o deus da guerra e da riqueza. Significa avançar sem medo e agir com intuição.', fr: 'Inoshishi (sanglier) est la monture de Bishamonten — le dieu de la guerre et de la richesse. Il signifie avancer sans peur et agir par intuition.', ja: '猪（いのしし）は毘沙門天——戦と富の神——の乗り物。恐れずに進み、直感で動くことを意味する。' } },
      { culture: { tr: 'İskandinav Mitolojisi', en: 'Norse Mythology', de: 'Nordische Mythologie', es: 'Mitología Nórdica', pt: 'Mitologia Nórdica', fr: 'Mythologie Nordique', ja: '北欧神話' }, meaning: { tr: 'Freyr\'in altın yaban domuzu Gullinbursti geceyi aydınlatırdı. Freya\'nın domuzu Hildisvíni ise bilgeliğin ve savaşın birleşimiydi.', en: 'Freyr\'s golden boar Gullinbursti illuminated the night. Freya\'s boar Hildisvíni was the union of wisdom and war.', de: 'Freyrs goldener Eber Gullinbursti erhellte die Nacht. Freyas Eber Hildisvíni war die Vereinigung von Weisheit und Krieg.', es: 'El jabalí dorado de Freyr, Gullinbursti, iluminaba la noche. El jabalí de Freya, Hildisvíni, era la unión de la sabiduría y la guerra.', pt: 'O javali dourado de Freyr, Gullinbursti, iluminava a noite. O javali de Freya, Hildisvíni, era a união da sabedoria e da guerra.', fr: 'Le sanglier d\'or de Freyr, Gullinbursti, illuminait la nuit. Le sanglier de Freya, Hildisvíni, était l\'union de la sagesse et de la guerre.', ja: 'フレイの黄金のイノシシ、グリンブルスティは夜を照らした。フレイヤのイノシシ、ヒルディスヴィーニは知恵と戦の結合だった。' } },
      { culture: { tr: 'Anadolu ve Mezopotamya', en: 'Anatolia and Mesopotamia', de: 'Anatolien und Mesopotamien', es: 'Anatolia y Mesopotamia', pt: 'Anatólia e Mesopotâmia', fr: 'Anatolie et Mésopotamie', ja: 'アナトリアとメソポタミア' }, meaning: { tr: 'Çatal Höyük buluntularında Yaban Domuzu avı ritüeli, erkeğin doğayla hesaplaşmasının simgesidir. Ham gücü dönüştürmek uygarlığın temeli sayılmıştır.', en: 'In the finds of Çatal Höyük, the Wild Boar hunt ritual is the symbol of man\'s reckoning with nature. Transforming raw power has been considered the foundation of civilization.', de: 'In den Funden von Çatalhöyük ist das Eberjagd-Ritual das Symbol der Auseinandersetzung des Menschen mit der Natur. Die rohe Kraft zu verwandeln, galt als Grundlage der Zivilisation.', es: 'En los hallazgos de Çatalhöyük, el ritual de la caza del jabalí es el símbolo del enfrentamiento del hombre con la naturaleza. Transformar el poder en bruto se ha considerado el fundamento de la civilización.', pt: 'Nos achados de Çatalhöyük, o ritual da caça ao javali é o símbolo do confronto do homem com a natureza. Transformar o poder em bruto foi considerado o fundamento da civilização.', fr: 'Dans les trouvailles de Çatal Höyük, le rituel de la chasse au sanglier est le symbole de l\'affrontement de l\'homme avec la nature. Transformer la puissance brute a été tenu pour le fondement de la civilisation.', ja: 'チャタル・ヒュユクの出土品において、イノシシ狩りの儀礼は人間が自然と対峙することの象徴。素の力を変えることが文明の礎とされた。' } },
    ],
    myths: [
      { tr: 'Kaledonia Domuzu Avı: Tanrıça Artemis, Kaledonia Kralı\'nın kendisine sunağı ihmal etmesi üzerine kocaman bir yaban domuzu gönderir. Tüm Yunan kahramanları — Jason, Theseus, Peleus — bir araya gelip onu avlamak için bu topraklara koşar. İlk yaralayanın ödülü, Atalanta adlı bir kadın avcıdır. Güç, zafer hakkını herkese eşit açar.', en: 'The Calydonian Boar Hunt: The goddess Artemis sends a massive wild boar when the King of Calydon neglects her altar. All the Greek heroes — Jason, Theseus, Peleus — rush to these lands to hunt it together. The reward for the first to wound it goes to a female hunter named Atalanta. Power opens the right to victory equally to everyone.', de: 'Die Kalydonische Eberjagd: Die Göttin Artemis sendet einen riesigen Eber, als der König von Kalydon ihren Altar vernachlässigt. Alle griechischen Helden — Jason, Theseus, Peleus — eilen in dieses Land, um ihn gemeinsam zu jagen. Der Lohn für die Erste, die ihn verwundet, geht an eine Jägerin namens Atalante. Die Kraft öffnet das Recht auf Sieg allen gleichermaßen.', es: 'La cacería del jabalí de Calidón: La diosa Artemisa envía un enorme jabalí cuando el rey de Calidón descuida su altar. Todos los héroes griegos — Jasón, Teseo, Peleo — corren a estas tierras para cazarlo juntos. La recompensa para el primero en herirlo va a una cazadora llamada Atalanta. El poder abre el derecho a la victoria por igual a todos.', pt: 'A caçada do javali de Calidão: A deusa Ártemis envia um enorme javali quando o rei de Calidão negligencia o seu altar. Todos os heróis gregos — Jasão, Teseu, Peleu — correm a estas terras para o caçar juntos. A recompensa para o primeiro a feri-lo cabe a uma caçadora chamada Atalanta. O poder abre o direito à vitória por igual a todos.', fr: 'La chasse au sanglier de Calydon : La déesse Artémis envoie un énorme sanglier lorsque le roi de Calydon néglige son autel. Tous les héros grecs — Jason, Thésée, Pélée — accourent sur ces terres pour le chasser ensemble. La récompense pour la première à le blesser revient à une chasseuse nommée Atalante. La puissance ouvre le droit à la victoire à tous également.', ja: 'カリュドンのイノシシ狩り：女神アルテミスは、カリュドンの王が祭壇をないがしろにしたため巨大なイノシシを送る。すべてのギリシアの英雄——イアソン、テセウス、ペレウス——がこの地に駆けつけ、ともに狩る。最初に傷つけた者への褒美は、アタランタという女狩人のものとなる。力は勝利の権利を万人に等しく開く。' },
      { tr: 'İrlanda destanında Diarmuid, büyülü bir yaban domuzu tarafından öldürülmek üzere doğmuştur — bu kader değiştirilemez. Kahraman bunu bildiği halde domuzun izine çıkar. Bilinen sona rağmen cesaretle yürümek, Kelt kahramanlık anlayışının özüdür.', en: 'In an Irish epic, Diarmuid is fated to be killed by an enchanted wild boar — this fate cannot be changed. Knowing this, the hero still sets out on the boar\'s trail. Walking with courage despite a known ending is the essence of Celtic heroism.', de: 'In einem irischen Epos ist es Diarmuid bestimmt, von einem verzauberten Eber getötet zu werden — dieses Schicksal lässt sich nicht ändern. Obwohl er es weiß, macht sich der Held auf die Fährte des Ebers. Mit Mut zu gehen trotz eines bekannten Endes ist das Wesen des keltischen Heldentums.', es: 'En una epopeya irlandesa, Diarmuid está destinado a morir a manos de un jabalí encantado — este destino no puede cambiarse. Aun sabiéndolo, el héroe sale al rastro del jabalí. Caminar con coraje a pesar de un final conocido es la esencia del heroísmo celta.', pt: 'Numa epopeia irlandesa, Diarmuid está destinado a ser morto por um javali encantado — este destino não pode ser mudado. Sabendo-o, o herói parte na pista do javali. Caminhar com coragem apesar de um fim conhecido é a essência do heroísmo celta.', fr: 'Dans une épopée irlandaise, Diarmuid est destiné à être tué par un sanglier enchanté — ce destin ne peut être changé. Le sachant, le héros se met pourtant sur la piste du sanglier. Marcher avec courage malgré une fin connue est l\'essence de l\'héroïsme celte.', ja: 'アイルランドの叙事詩において、ディルムッドは魔法のイノシシに殺される定めに生まれた——この運命は変えられない。それを知りながら、英雄はイノシシの跡を追う。定められた結末にもかかわらず勇気をもって進むこと、それがケルトの英雄精神の核心。' },
    ],
  },

  // ─── a056 Kedi ───────────────────────────────────────────────────────────
  a056: {
    jung: { tr: '"Bağımsız Benlik ve Gece Sezgisi" arketipi. Kedi, bilinçdışında sahiplenilemeyen, evcilleştirilemeyen özün simgesidir — sevgi verir ama teslim olmaz. Gece görme yetisi, bilinçdışının karanlık katmanlarına erişimi; pençesini çekip uzatabilmek ise saldırganlık ile zarafeti aynı anda taşıyabilmeyi simgeler.', en: 'The "Independent Self and Nocturnal Intuition" archetype. The Cat is the symbol of an essence that cannot be possessed or domesticated in the unconscious — it gives love but does not surrender. The ability to see at night symbolizes access to the dark layers of the unconscious; the ability to retract and extend claws symbolizes carrying both aggression and grace simultaneously.', de: 'Der Archetyp des "unabhängigen Selbst und der nächtlichen Intuition". Die Katze ist im Unbewussten das Symbol eines Wesens, das nicht besessen oder gezähmt werden kann — sie schenkt Liebe, ergibt sich aber nicht. Die Fähigkeit, im Dunkeln zu sehen, versinnbildlicht den Zugang zu den dunklen Schichten des Unbewussten; das Ein- und Ausfahren der Krallen versinnbildlicht, Aggression und Anmut zugleich zu tragen.', es: 'El arquetipo del "Yo Independiente y la Intuición Nocturna". El gato es el símbolo de una esencia que no puede poseerse ni domesticarse en el inconsciente — da amor pero no se rinde. La capacidad de ver de noche simboliza el acceso a las capas oscuras del inconsciente; la de retraer y extender las garras simboliza portar a la vez la agresión y la gracia.', pt: 'O arquétipo do "Eu Independente e a Intuição Noturna". O gato é o símbolo de uma essência que não pode ser possuída nem domesticada no inconsciente — dá amor mas não se rende. A capacidade de ver à noite simboliza o acesso às camadas escuras do inconsciente; a de retrair e estender as garras simboliza carregar ao mesmo tempo a agressão e a graça.', fr: 'L\'archétype du "Soi indépendant et de l\'Intuition nocturne". Le chat est le symbole d\'une essence qui ne peut être possédée ni domestiquée dans l\'inconscient — il donne de l\'amour mais ne se rend pas. La faculté de voir la nuit symbolise l\'accès aux couches sombres de l\'inconscient ; celle de rétracter et de sortir les griffes symbolise porter à la fois l\'agressivité et la grâce.', ja: '「独立した自己と夜の直感」の元型。ネコは無意識のうちの、所有も家畜化もできぬ本質の象徴——愛を与えるが、屈服はしない。夜に見る力は無意識の暗い層への通路を、爪を引っ込め伸ばす力は攻撃性と優美を同時に担うことを象徴する。' },
    dream: { tr: 'Kedi rüyada görünürse — sezgin, fısıltılı bir bilgi sana ulaşmaya çalışıyor; acele etme, bekle. Saldırıyorsa: bağımsızlığına ya da sezgine saygı gösterilmiyor. Kucağına kuruluyorsa: içindeki vahşi olanla barış kuruldu, güvendesin.', en: 'If Cat appears in a dream — an intuitive, whispered knowledge is trying to reach you; do not rush, wait. If it attacks: your independence or intuition is not being respected. If it settles in your lap: peace has been made with what is wild inside you, you are safe.', de: 'Erscheint die Katze im Traum — ein intuitives, geflüstertes Wissen versucht, dich zu erreichen; hetze nicht, warte. Greift sie an: Deine Unabhängigkeit oder Intuition wird nicht geachtet. Macht sie es sich auf deinem Schoß bequem: Mit dem Wilden in dir wurde Frieden geschlossen, du bist sicher.', es: 'Si el gato aparece en sueños — un conocimiento intuitivo, susurrado, trata de alcanzarte; no te apresures, espera. Si ataca: no se respeta tu independencia o tu intuición. Si se acomoda en tu regazo: se ha hecho la paz con lo salvaje que hay en ti, estás a salvo.', pt: 'Se o gato aparece em sonho — um conhecimento intuitivo, sussurrado, tenta alcançar-te; não te apresses, espera. Se ataca: a tua independência ou intuição não está a ser respeitada. Se se aninha no teu colo: fez-se a paz com o que há de selvagem em ti, estás seguro.', fr: 'Si le chat apparaît en rêve — un savoir intuitif, murmuré, tente de t\'atteindre ; ne te précipite pas, attends. S\'il attaque : ton indépendance ou ton intuition n\'est pas respectée. S\'il s\'installe sur tes genoux : la paix a été faite avec le sauvage en toi, tu es en sécurité.', ja: '夢にネコが現れるなら——直感的な、ささやかれた知があなたに届こうとしている。急がず、待て。襲うなら、あなたの独立や直感が尊重されていない。膝に丸くなるなら、あなたの内なる野生と和解がなされた。あなたは安全。' },
    shadow: { tr: 'Kontrolsüz bağımsızlık — gerçek bağ kurmaktan kaçınma, duygusal mesafeyi hep koruma. Kedi gölgesi: manipülatif sevgi (sadece işine gelince yakınlaşmak), soğukluk, narsisizm.', en: 'Uncontrolled independence — avoiding forming real bonds, always maintaining emotional distance. The Cat shadow: manipulative love (approaching only when convenient), coldness, narcissism.', de: 'Unkontrollierte Unabhängigkeit — das Meiden echter Bindungen, das stete Wahren emotionaler Distanz. Der Katzenschatten: manipulative Liebe (sich nur zu nähern, wenn es gelegen kommt), Kälte, Narzissmus.', es: 'Independencia descontrolada — evitar formar vínculos reales, mantener siempre la distancia emocional. La sombra del gato: amor manipulador (acercarse solo cuando conviene), frialdad, narcisismo.', pt: 'Independência descontrolada — evitar formar laços reais, manter sempre a distância emocional. A sombra do gato: amor manipulador (aproximar-se só quando convém), frieza, narcisismo.', fr: 'Indépendance incontrôlée — éviter de tisser de vrais liens, garder toujours la distance émotionnelle. L\'ombre du chat : amour manipulateur (s\'approcher seulement quand cela arrange), froideur, narcissisme.', ja: '制御なき独立——真の絆を結ぶのを避け、常に感情の距離を保つこと。ネコの影——操作的な愛（都合のいいときだけ近づくこと）、冷たさ、自己愛。' },
    whenAppears: { tr: 'Sınırlarınızı kaybettiğinizde, birinin baskısı altında kendinizden uzaklaştığınızda ya da sezgilerinize kulak vermeyi bıraktığınızda.', en: 'When you have lost your boundaries, when you have drifted from yourself under someone\'s pressure, or when you have stopped listening to your intuitions.', de: 'Wenn du deine Grenzen verloren hast, wenn du unter dem Druck eines anderen von dir selbst abgedriftet bist oder aufgehört hast, auf deine Intuitionen zu hören.', es: 'Cuando has perdido tus límites, cuando te has alejado de ti mismo bajo la presión de alguien, o cuando has dejado de escuchar tus intuiciones.', pt: 'Quando perdeste os teus limites, quando te afastaste de ti mesmo sob a pressão de alguém, ou quando deixaste de escutar as tuas intuições.', fr: 'Quand tu as perdu tes limites, quand tu t\'es éloigné de toi-même sous la pression de quelqu\'un, ou quand tu as cessé d\'écouter tes intuitions.', ja: '境界を失ったとき、誰かの圧力のもとで自分から離れてしまったとき、あるいは自らの直感に耳を傾けるのをやめたときに。' },
    traditions: [
      { culture: { tr: 'Mısır Medeniyeti', en: 'Egyptian Civilization', de: 'Ägyptische Zivilisation', es: 'Civilización Egipcia', pt: 'Civilização Egípcia', fr: 'Civilisation Égyptienne', ja: 'エジプト文明' }, meaning: { tr: 'Bastet — kedi başlı tanrıça. Evin, doğurganlığın ve güneşin koruyucusu. Kedilere zarar vermek ölümle cezalandırılırdı. Mumyalanmış kediler Bastet tapınaklarına sunulurdu.', en: 'Bastet — the cat-headed goddess. Protector of home, fertility, and the sun. Harming cats was punishable by death. Mummified cats were offered at the temples of Bastet.', de: 'Bastet — die katzenköpfige Göttin. Beschützerin des Heims, der Fruchtbarkeit und der Sonne. Katzen zu schaden wurde mit dem Tode bestraft. Mumifizierte Katzen wurden in den Tempeln der Bastet dargebracht.', es: 'Bastet — la diosa con cabeza de gato. Protectora del hogar, la fertilidad y el sol. Dañar a los gatos se castigaba con la muerte. Se ofrecían gatos momificados en los templos de Bastet.', pt: 'Bastet — a deusa com cabeça de gato. Protetora do lar, da fertilidade e do sol. Prejudicar os gatos era punido com a morte. Gatos mumificados eram oferecidos nos templos de Bastet.', fr: 'Bastet — la déesse à tête de chat. Protectrice du foyer, de la fertilité et du soleil. Nuire aux chats était puni de mort. Des chats momifiés étaient offerts aux temples de Bastet.', ja: 'バステト——ネコの頭をもつ女神。家、豊穣、そして太陽の守護者。ネコに害をなすことは死をもって罰せられた。ミイラにされたネコがバステトの神殿に捧げられた。' } },
      { culture: { tr: 'İslam Geleneği', en: 'Islamic Tradition', de: 'Islamische Tradition', es: 'Tradición Islámica', pt: 'Tradição Islâmica', fr: 'Tradition Islamique', ja: 'イスラームの伝統' }, meaning: { tr: 'Hz. Muhammed\'in kedisi Müezza\'yı çok severdi; namaz vakti uyuyan Müezza\'yı uyandırmamak için cüppesinin kolunu kestiği rivayet edilir. Kedi İslam\'da temiz ve mübarek bir hayvandır.', en: 'The Prophet Muhammad loved his cat Muezza greatly; it is narrated that he cut the sleeve of his robe rather than wake sleeping Muezza when it was time for prayer. The cat is a clean and blessed animal in Islam.', de: 'Der Prophet Mohammed liebte seine Katze Muezza sehr; es wird überliefert, dass er den Ärmel seines Gewandes abschnitt, statt die schlafende Muezza zur Gebetszeit zu wecken. Die Katze ist im Islam ein reines und gesegnetes Tier.', es: 'El profeta Mahoma amaba mucho a su gata Muezza; se narra que cortó la manga de su túnica en lugar de despertar a Muezza dormida cuando llegó la hora de la oración. El gato es un animal limpio y bendito en el islam.', pt: 'O profeta Maomé amava muito a sua gata Muezza; narra-se que cortou a manga da sua túnica em vez de acordar a Muezza adormecida quando chegou a hora da oração. O gato é um animal limpo e abençoado no islão.', fr: 'Le prophète Mahomet aimait beaucoup sa chatte Muezza ; on raconte qu\'il coupa la manche de sa robe plutôt que de réveiller Muezza endormie à l\'heure de la prière. Le chat est un animal pur et béni dans l\'islam.', ja: '預言者ムハンマドは愛猫ムエッザをこよなく愛した。礼拝の時、眠るムエッザを起こさぬよう、衣の袖を切ったと伝えられる。ネコはイスラームにおいて清浄で祝福された動物。' } },
      { culture: { tr: 'Japon Geleneği', en: 'Japanese Tradition', de: 'Japanische Tradition', es: 'Tradición Japonesa', pt: 'Tradição Japonesa', fr: 'Tradition Japonaise', ja: '日本の伝統' }, meaning: { tr: 'Maneki-neko (çağıran kedi) — bir pençesini kaldırmış kedi figürü bolluk ve şans getirir. Kara kedi ise bazı bölgelerde koruyucu, bazılarında tehlikeli sayılır.', en: 'Maneki-neko (beckoning cat) — the cat figurine with one paw raised brings abundance and luck. A black cat is considered protective in some regions, dangerous in others.', de: 'Maneki-neko (winkende Katze) — die Katzenfigur mit einer erhobenen Pfote bringt Überfluss und Glück. Eine schwarze Katze gilt in manchen Gegenden als schützend, in anderen als gefährlich.', es: 'Maneki-neko (gato que saluda) — la figura del gato con una pata levantada trae abundancia y suerte. El gato negro se considera protector en unas regiones, peligroso en otras.', pt: 'Maneki-neko (gato acenante) — a figura do gato com uma pata levantada traz abundância e sorte. O gato preto é considerado protetor em algumas regiões, perigoso noutras.', fr: 'Maneki-neko (chat qui appelle) — la figurine du chat à une patte levée apporte abondance et chance. Le chat noir est tenu pour protecteur dans certaines régions, dangereux dans d\'autres.', ja: '招き猫——片方の前足を上げたネコの像は豊かさと幸運をもたらす。黒猫は地域によって守り手とも、危険ともされる。' } },
      { culture: { tr: 'Kuzey Avrupa / Vik Geleneği', en: 'Northern Europe / Norse Tradition', de: 'Nordeuropa / Nordische Tradition', es: 'Norte de Europa / Tradición Nórdica', pt: 'Norte da Europa / Tradição Nórdica', fr: 'Europe du Nord / Tradition Nordique', ja: '北欧／ヴァイキングの伝統' }, meaning: { tr: 'Tanrıça Freya\'nın arabası iki büyük kedi tarafından çekilir. Kedi, Freya\'nın özgürlük, sihir ve tutku enerjisini taşır.', en: 'The goddess Freya\'s chariot is pulled by two large cats. The Cat carries Freya\'s energy of freedom, magic, and passion.', de: 'Der Wagen der Göttin Freya wird von zwei großen Katzen gezogen. Die Katze trägt Freyas Energie von Freiheit, Magie und Leidenschaft.', es: 'El carro de la diosa Freya es tirado por dos grandes gatos. El gato porta la energía de libertad, magia y pasión de Freya.', pt: 'O carro da deusa Freya é puxado por dois grandes gatos. O gato carrega a energia de liberdade, magia e paixão de Freya.', fr: 'Le char de la déesse Freya est tiré par deux grands chats. Le chat porte l\'énergie de liberté, de magie et de passion de Freya.', ja: '女神フレイヤの車は二匹の大きなネコに曳かれる。ネコはフレイヤの自由、魔法、情熱のエネルギーを担う。' } },
      { culture: { tr: 'Anadolu Halk İnancı', en: 'Anatolian Folk Belief', de: 'Anatolischer Volksglaube', es: 'Creencia Popular Anatolia', pt: 'Crença Popular Anatólia', fr: 'Croyance Populaire Anatolienne', ja: 'アナトリア民間信仰' }, meaning: { tr: 'Kedi eve girdiğinde o evi "seçmiş" sayılır — kovulmaz, misafir edilir. Yedi can imgesi, kedinin ölüm ve diriliş arasındaki sınırda yaşadığına dair yaygın bir Anadolu inancını yansıtır.', en: 'When a cat enters a home it is considered to have "chosen" that house — it is not driven away, it is welcomed. The image of nine lives reflects a widespread Anatolian belief that the cat lives on the border between death and resurrection.', de: 'Betritt eine Katze ein Heim, so gilt sie als jemand, der dieses Haus "erwählt" hat — sie wird nicht vertrieben, sondern bewirtet. Das Bild der sieben Leben spiegelt einen weit verbreiteten anatolischen Glauben, dass die Katze an der Grenze zwischen Tod und Auferstehung lebt.', es: 'Cuando un gato entra en una casa se considera que ha "elegido" ese hogar — no se le echa, se le acoge. La imagen de las siete vidas refleja una creencia anatolia muy extendida de que el gato vive en la frontera entre la muerte y la resurrección.', pt: 'Quando um gato entra numa casa considera-se que "escolheu" esse lar — não é enxotado, é acolhido. A imagem das sete vidas reflete uma crença anatólia difundida de que o gato vive na fronteira entre a morte e a ressurreição.', fr: 'Quand un chat entre dans une maison, on considère qu\'il a "choisi" ce foyer — on ne le chasse pas, on l\'accueille. L\'image des sept vies reflète une croyance anatolienne répandue selon laquelle le chat vit à la frontière entre la mort et la résurrection.', ja: 'ネコが家に入ると、その家を「選んだ」とみなされる——追い払われず、迎え入れられる。七つの命の像は、ネコが死と復活の境に生きるというアナトリアに広く伝わる信仰を映している。' } },
    ],
    myths: [
      { tr: 'Mısır\'da Ra her gece Apep yılanıyla savaşır ve sabah galip çıkar — bu savaşta Ra\'ya yardım eden Büyük Kedi\'dir. Heliopolis\'teki kutsal ağacın dibinde Apep\'i her gece yenen kedi, güneşin doğmasını sağlar. Sezgi ve sabır, kaosun üstesinden gelir.', en: 'In Egypt, Ra battles the serpent Apep each night and emerges victorious in the morning — the Great Cat helps Ra in this battle. The cat that defeats Apep each night at the foot of the sacred tree in Heliopolis enables the sun to rise. Intuition and patience overcome chaos.', de: 'In Ägypten kämpft Ra jede Nacht gegen die Schlange Apep und geht am Morgen als Sieger hervor — in diesem Kampf hilft die Große Katze dem Ra. Die Katze, die Apep jede Nacht am Fuße des heiligen Baumes in Heliopolis besiegt, lässt die Sonne aufgehen. Intuition und Geduld überwinden das Chaos.', es: 'En Egipto, Ra combate cada noche a la serpiente Apep y sale victorioso por la mañana — el Gran Gato ayuda a Ra en esta batalla. El gato que vence a Apep cada noche al pie del árbol sagrado de Heliópolis permite que el sol salga. La intuición y la paciencia vencen al caos.', pt: 'No Egito, Rá combate cada noite a serpente Apep e sai vitorioso de manhã — o Grande Gato ajuda Rá nesta batalha. O gato que vence Apep cada noite ao pé da árvore sagrada de Heliópolis permite que o sol nasça. A intuição e a paciência vencem o caos.', fr: 'En Égypte, Rê combat chaque nuit le serpent Apep et sort victorieux au matin — le Grand Chat aide Rê dans ce combat. Le chat qui vainc Apep chaque nuit au pied de l\'arbre sacré d\'Héliopolis permet au soleil de se lever. L\'intuition et la patience triomphent du chaos.', ja: 'エジプトでは、ラーは夜ごと蛇アペプと戦い、朝に勝者として現れる——この戦いでラーを助けるのが偉大なるネコ。ヘリオポリスの聖なる樹の根もとで夜ごとアペプを打ち倒すネコが、太陽を昇らせる。直感と忍耐が混沌に打ち勝つ。' },
      { tr: 'Japon\'un Gotokuji Tapınağı efsanesi: Yoksul bir rahip kedisini paylaştığı az yemeği bile verir. Bir gün büyük bir savaş lordu tapınağın önünden geçerken kedi pençesini kaldırır ve lordu içeri davet eder. Lord içeri girer; dışarıda fırtına kopar. Minnettar lord tapınağa servet bağışlar. Şükranla karşılanan küçük sevgiler, büyük dönüşümleri doğurur.', en: 'The legend of Japan\'s Gotokuji Temple: A poor monk gives his cat even from the little food he shares. One day as a great warlord passes before the temple, the cat raises its paw and invites the lord inside. The lord enters; outside a storm breaks. The grateful lord donates his wealth to the temple. Small loves received with gratitude give birth to great transformations.', de: 'Die Legende des japanischen Gotokuji-Tempels: Ein armer Mönch gibt seiner Katze selbst von dem wenigen Essen, das er teilt. Eines Tages, als ein großer Kriegsfürst am Tempel vorbeizieht, hebt die Katze die Pfote und lädt den Fürsten herein. Der Fürst tritt ein; draußen bricht ein Sturm los. Der dankbare Fürst stiftet dem Tempel sein Vermögen. Kleine, mit Dankbarkeit empfangene Liebe gebiert große Verwandlungen.', es: 'La leyenda del templo japonés Gotokuji: Un monje pobre da a su gato incluso de la poca comida que comparte. Un día, mientras un gran señor de la guerra pasa ante el templo, el gato levanta la pata e invita al señor a entrar. El señor entra; afuera estalla una tormenta. El señor agradecido dona su fortuna al templo. Los pequeños amores recibidos con gratitud dan a luz grandes transformaciones.', pt: 'A lenda do templo japonês Gotokuji: Um monge pobre dá ao seu gato até da pouca comida que partilha. Um dia, quando um grande senhor da guerra passa diante do templo, o gato levanta a pata e convida o senhor a entrar. O senhor entra; lá fora rebenta uma tempestade. O senhor agradecido doa a sua fortuna ao templo. Pequenos amores recebidos com gratidão dão origem a grandes transformações.', fr: 'La légende du temple japonais Gotokuji : Un moine pauvre donne à son chat même du peu de nourriture qu\'il partage. Un jour, alors qu\'un grand seigneur de guerre passe devant le temple, le chat lève la patte et invite le seigneur à entrer. Le seigneur entre ; dehors éclate une tempête. Le seigneur reconnaissant fait don de sa fortune au temple. Les petits amours reçus avec gratitude enfantent de grandes transformations.', ja: '日本の豪徳寺の伝説：貧しい僧は分かち合うわずかな食べ物さえネコに与える。ある日、大いなる戦国大名が寺の前を通りかかると、ネコが前足を上げて大名を中へ招く。大名が入ると、外では嵐が起こる。感謝した大名は寺に財を寄進する。感謝をもって受け取られた小さな愛が、大いなる変容を生む。' },
    ],
  },

  // ─── a057 Yusufçuk ───────────────────────────────────────────────────────
  a057: {
    jung: { tr: '"İllüzyon ve Işık Dönüşümü" arketipi. Yusufçuk, bilinçdışında yanılsamanın ve ardından gelen aydınlanmanın simgesidir — görüneni değil, görünmeyeni görmek. Renk değiştiren kanatları, gerçekliğin algıya göre değiştiğini anlatır; hayatının büyük bölümünü su altında (bilinçdışında) geçirip sonunda havalanmak ise köklü dönüşümü simgeler.', en: 'The "Illusion and Light Transformation" archetype. The Dragonfly is the symbol of illusion and subsequent illumination in the unconscious — seeing not what is visible but what is invisible. Its color-shifting wings tell that reality changes according to perception; spending most of its life underwater (in the unconscious) and finally taking flight symbolizes profound transformation.', de: 'Der Archetyp der "Illusion und Lichtverwandlung". Die Libelle ist im Unbewussten das Symbol der Täuschung und der darauffolgenden Erleuchtung — nicht das Sichtbare, sondern das Unsichtbare zu sehen. Ihre farbwechselnden Flügel sagen, dass sich die Wirklichkeit je nach Wahrnehmung wandelt; den größten Teil ihres Lebens unter Wasser (im Unbewussten) zu verbringen und schließlich aufzusteigen, versinnbildlicht die tiefgreifende Verwandlung.', es: 'El arquetipo de la "Ilusión y Transformación de la Luz". La libélula es el símbolo de la ilusión y la iluminación que le sigue en el inconsciente — ver no lo visible sino lo invisible. Sus alas que cambian de color dicen que la realidad cambia según la percepción; pasar la mayor parte de su vida bajo el agua (en el inconsciente) y finalmente alzar el vuelo simboliza la transformación profunda.', pt: 'O arquétipo da "Ilusão e Transformação da Luz". A libélula é o símbolo da ilusão e da iluminação que se lhe segue no inconsciente — ver não o visível mas o invisível. As suas asas que mudam de cor dizem que a realidade muda conforme a perceção; passar a maior parte da vida debaixo de água (no inconsciente) e finalmente alçar voo simboliza a transformação profunda.', fr: 'L\'archétype de l\'"Illusion et Transformation de la lumière". La libellule est le symbole de l\'illusion et de l\'illumination qui la suit dans l\'inconscient — voir non le visible mais l\'invisible. Ses ailes changeant de couleur disent que la réalité change selon la perception ; passer la plus grande partie de sa vie sous l\'eau (dans l\'inconscient) puis enfin s\'envoler symbolise la transformation profonde.', ja: '「幻と光の変容」の元型。トンボは無意識のうちの幻と、それに続く照明（悟り）の象徴——見えるものではなく見えないものを見ること。色を変える翅は、現実が知覚に応じて変わることを語る。生涯の大半を水中（無意識）で過ごし、ついに飛び立つことは、根源的な変容を象徴する。' },
    dream: { tr: 'Yusufçuk rüyada görünürse — algılarını sorgula; gördüğün şey gerçekliğin tamamı değil. Üzerine konuyorsa: bu an, bu nefes yeterli — sadeliğe dön. Birden çok yönde uçuyorsa: çevik düşünme yetisi açılıyor, farklı perspektifleri dene.', en: 'If Dragonfly appears in a dream — question your perceptions; what you see is not the whole of reality. If it lands on you: this moment, this breath is enough — return to simplicity. If it flies in multiple directions: the ability for agile thinking is opening, try different perspectives.', de: 'Erscheint die Libelle im Traum — hinterfrage deine Wahrnehmungen; was du siehst, ist nicht die ganze Wirklichkeit. Landet sie auf dir: Dieser Augenblick, dieser Atemzug genügt — kehre zur Einfachheit zurück. Fliegt sie in mehrere Richtungen: Die Fähigkeit zu flinkem Denken öffnet sich, erprobe verschiedene Perspektiven.', es: 'Si la libélula aparece en sueños — cuestiona tus percepciones; lo que ves no es la totalidad de la realidad. Si se posa en ti: este momento, este aliento basta — vuelve a la sencillez. Si vuela en varias direcciones: se abre la capacidad de pensamiento ágil, prueba distintas perspectivas.', pt: 'Se a libélula aparece em sonho — questiona as tuas perceções; o que vês não é a totalidade da realidade. Se pousa em ti: este momento, este fôlego basta — regressa à simplicidade. Se voa em várias direções: abre-se a capacidade de pensamento ágil, experimenta diferentes perspetivas.', fr: 'Si la libellule apparaît en rêve — interroge tes perceptions ; ce que tu vois n\'est pas la totalité de la réalité. Si elle se pose sur toi : cet instant, ce souffle suffit — reviens à la simplicité. Si elle vole en plusieurs directions : la faculté de pensée agile s\'ouvre, essaie différentes perspectives.', ja: '夢にトンボが現れるなら——知覚を問え。見えているものは現実のすべてではない。あなたに止まるなら、この瞬間、この一息で十分——簡素さに戻れ。複数の方向へ飛ぶなら、機敏な思考の力が開かれている。異なる視座を試せ。' },
    shadow: { tr: 'Gerçeklikten kaçış için illüzyona sığınma — hayal ile gerçeği ayırt edememe. Yusufçuk gölgesi: kararsızlık, sürekli fikir değiştirme, derinlik yerine parlaklığa kapılma.', en: 'Taking refuge in illusion to escape reality — inability to distinguish dream from reality. The Dragonfly shadow: indecision, constantly changing one\'s mind, being captivated by brilliance rather than depth.', de: 'Zuflucht in der Illusion vor der Wirklichkeit — die Unfähigkeit, Traum von Wirklichkeit zu unterscheiden. Der Libellenschatten: Unentschlossenheit, ständiges Ändern der Meinung, sich vom Glanz statt von der Tiefe fesseln zu lassen.', es: 'Refugiarse en la ilusión para escapar de la realidad — incapacidad de distinguir el sueño de la realidad. La sombra de la libélula: indecisión, cambiar de opinión constantemente, dejarse cautivar por el brillo en lugar de la profundidad.', pt: 'Refugiar-se na ilusão para fugir da realidade — incapacidade de distinguir o sonho da realidade. A sombra da libélula: indecisão, mudar de opinião constantemente, deixar-se cativar pelo brilho em vez da profundidade.', fr: 'Se réfugier dans l\'illusion pour fuir la réalité — l\'incapacité de distinguer le rêve de la réalité. L\'ombre de la libellule : indécision, changer sans cesse d\'avis, se laisser captiver par l\'éclat plutôt que par la profondeur.', ja: '現実から逃れるため幻に逃げ込むこと——夢と現実を見分けられぬこと。トンボの影——優柔不断、絶え間ない心変わり、深みではなく輝きに惹かれること。' },
    whenAppears: { tr: 'Bir durumu olduğundan farklı gördüğünüzde, büyük bir dönüşümün eşiğinde olduğunuzda ya da hayata daha hafif bir gözle bakma ihtiyacı duyduğunuzda.', en: 'When you see a situation differently from what it is, when you are on the threshold of a great transformation, or when you feel the need to look at life with a lighter eye.', de: 'Wenn du eine Lage anders siehst, als sie ist, wenn du an der Schwelle einer großen Verwandlung stehst oder das Bedürfnis verspürst, das Leben mit leichterem Blick zu betrachten.', es: 'Cuando ves una situación distinta de lo que es, cuando estás en el umbral de una gran transformación, o cuando sientes la necesidad de mirar la vida con ojos más ligeros.', pt: 'Quando vês uma situação diferente do que é, quando estás no limiar de uma grande transformação, ou quando sentes a necessidade de olhar a vida com um olhar mais leve.', fr: 'Quand tu vois une situation autrement qu\'elle n\'est, quand tu es au seuil d\'une grande transformation, ou quand tu ressens le besoin de regarder la vie d\'un œil plus léger.', ja: 'ある状況を実際とは違って見るとき、大いなる変容の境にあるとき、あるいは人生をより軽やかなまなざしで眺める必要を感じるときに。' },
    traditions: [
      { culture: { tr: 'Japon Kültürü', en: 'Japanese Culture', de: 'Japanische Kultur', es: 'Cultura Japonesa', pt: 'Cultura Japonesa', fr: 'Culture Japonaise', ja: '日本文化' }, meaning: { tr: 'Akitsu-shima — "Yusufçuk Adası" — Japonya\'nın eski adı. Yusufçuk zafer ve güç sembolüdür; Japon savaşçıları zırhlarına yusufçuk motifi işlerdi. Ayrıca sonbaharın ve gelip geçiciliğin imgesidir.', en: 'Akitsu-shima — "Island of the Dragonfly" — the ancient name of Japan. The Dragonfly is a symbol of victory and power; Japanese warriors embroidered dragonfly motifs onto their armor. It is also the image of autumn and transience.', de: 'Akitsu-shima — "Insel der Libelle" — der alte Name Japans. Die Libelle ist ein Symbol des Sieges und der Macht; japanische Krieger stickten Libellenmotive auf ihre Rüstungen. Sie ist auch das Bild des Herbstes und der Vergänglichkeit.', es: 'Akitsu-shima — "Isla de la Libélula" — el nombre antiguo de Japón. La libélula es símbolo de victoria y poder; los guerreros japoneses bordaban motivos de libélula en sus armaduras. Es también la imagen del otoño y de lo efímero.', pt: 'Akitsu-shima — "Ilha da Libélula" — o nome antigo do Japão. A libélula é símbolo de vitória e poder; os guerreiros japoneses bordavam motivos de libélula nas suas armaduras. É também a imagem do outono e da transitoriedade.', fr: 'Akitsu-shima — "Île de la Libellule" — l\'ancien nom du Japon. La libellule est un symbole de victoire et de puissance ; les guerriers japonais brodaient des motifs de libellule sur leurs armures. Elle est aussi l\'image de l\'automne et de l\'éphémère.', ja: '秋津島（あきつしま）——「トンボの島」——日本の古名。トンボは勝利と力の象徴。日本の武士は甲冑にトンボの文様を施した。秋とはかなさの像でもある。' } },
      { culture: { tr: 'Lakota Yerlileri', en: 'Lakota Indigenous People', de: 'Lakota-Indigene', es: 'Pueblo Indígena Lakota', pt: 'Povo Indígena Lakota', fr: 'Peuple Autochtone Lakota', ja: 'ラコタ先住民' }, meaning: { tr: 'Yusufçuk aldatıcı düşmanlara karşı koruma sağlar. Savaşçılar atlarına ve kalkanlarına yusufçuk çizerdi — hızlı ve öngörülemeyen olmak için.', en: 'The Dragonfly provides protection against deceptive enemies. Warriors drew dragonflies on their horses and shields — to be swift and unpredictable.', de: 'Die Libelle bietet Schutz vor trügerischen Feinden. Krieger zeichneten Libellen auf ihre Pferde und Schilde — um schnell und unvorhersehbar zu sein.', es: 'La libélula brinda protección contra enemigos engañosos. Los guerreros dibujaban libélulas en sus caballos y escudos — para ser veloces e impredecibles.', pt: 'A libélula oferece proteção contra inimigos enganadores. Os guerreiros desenhavam libélulas nos seus cavalos e escudos — para serem velozes e imprevisíveis.', fr: 'La libellule offre une protection contre les ennemis trompeurs. Les guerriers dessinaient des libellules sur leurs chevaux et leurs boucliers — pour être rapides et imprévisibles.', ja: 'トンボは欺く敵から守る。戦士は馬や盾にトンボを描いた——素早く、読まれぬ存在となるために。' } },
      { culture: { tr: 'Kelt Geleneği', en: 'Celtic Tradition', de: 'Keltische Tradition', es: 'Tradición Celta', pt: 'Tradição Celta', fr: 'Tradition Celtique', ja: 'ケルトの伝統' }, meaning: { tr: 'Peri dünyasının habercisi. Yusufçuğun göründüğü yerde peri kapısı açılmış demektir — dikkatli ol, yanılabilirsin.', en: 'Messenger of the fairy world. Where a dragonfly appears, a fairy gate has opened — be careful, you may be deceived.', de: 'Bote der Feenwelt. Wo eine Libelle erscheint, hat sich ein Feentor geöffnet — sei vorsichtig, du könntest getäuscht werden.', es: 'Mensajera del mundo de las hadas. Donde aparece una libélula, se ha abierto una puerta de las hadas — ten cuidado, puedes ser engañado.', pt: 'Mensageira do mundo das fadas. Onde aparece uma libélula, abriu-se um portal das fadas — tem cuidado, podes ser enganado.', fr: 'Messagère du monde des fées. Là où une libellule apparaît, une porte des fées s\'est ouverte — sois prudent, tu peux être trompé.', ja: '妖精の世界の使者。トンボが現れるところには妖精の門が開いている——気をつけよ、欺かれることがある。' } },
      { culture: { tr: 'İsveç Halk İnancı', en: 'Swedish Folk Belief', de: 'Schwedischer Volksglaube', es: 'Creencia Popular Sueca', pt: 'Crença Popular Sueca', fr: 'Croyance Populaire Suédoise', ja: 'スウェーデン民間信仰' }, meaning: { tr: 'Yusufçuk iblislerin gözü olarak düşünülmüş, ruhları tartmaya gelir. Ama aynı zamanda ev tanrılarının koruyucu habercisi de sayılmıştır.', en: 'The Dragonfly has been thought of as the eye of demons, coming to weigh souls. But it has also been considered the protective messenger of household gods.', de: 'Die Libelle galt als das Auge der Dämonen, das kommt, um die Seelen zu wiegen. Doch sie galt auch als der schützende Bote der Hausgötter.', es: 'La libélula se ha considerado el ojo de los demonios, que viene a pesar las almas. Pero también se la ha tenido por la mensajera protectora de los dioses del hogar.', pt: 'A libélula tem sido considerada o olho dos demónios, que vem pesar as almas. Mas também tem sido tida como a mensageira protetora dos deuses do lar.', fr: 'La libellule a été tenue pour l\'œil des démons, venant peser les âmes. Mais elle a aussi été considérée comme la messagère protectrice des dieux du foyer.', ja: 'トンボは悪霊の目とされ、魂を量りに来ると考えられた。だが同時に家庭の神々の守りの使者ともされた。' } },
      { culture: { tr: 'Çin Geleneği', en: 'Chinese Tradition', de: 'Chinesische Tradition', es: 'Tradición China', pt: 'Tradição Chinesa', fr: 'Tradition Chinoise', ja: '中国の伝統' }, meaning: { tr: 'Yusufçuk uyum ve başarının simgesidir. Suyun üzerinde uçması — iki dünya arasında; görünen ile görünmeyenin kesişim noktasında yaşamak.', en: 'The Dragonfly is a symbol of harmony and success. Flying over water — living between two worlds; at the intersection of the visible and the invisible.', de: 'Die Libelle ist ein Symbol der Harmonie und des Erfolgs. Über dem Wasser zu fliegen — zwischen zwei Welten zu leben; am Schnittpunkt des Sichtbaren und des Unsichtbaren.', es: 'La libélula es símbolo de la armonía y el éxito. Volar sobre el agua — vivir entre dos mundos; en la intersección de lo visible y lo invisible.', pt: 'A libélula é símbolo da harmonia e do sucesso. Voar sobre a água — viver entre dois mundos; na interseção do visível e do invisível.', fr: 'La libellule est un symbole d\'harmonie et de réussite. Voler au-dessus de l\'eau — vivre entre deux mondes ; à l\'intersection du visible et de l\'invisible.', ja: 'トンボは調和と成功の象徴。水の上を飛ぶこと——二つの世界のあいだに、見えるものと見えないものの交わる点に生きること。' } },
    ],
    myths: [
      { tr: 'Japon efsanesinde ilk Yusufçuk, tanrı İzanagi\'nin gözyaşından doğmuştur. Kayıp sevgilisi İzanami için yas tutarken döktüğü gözyaşı suya düşmüş, o damla kanat takınmış ve uçmuş. Acı dönüşümle güzelliğe kavuştuğunda, en kırılgan an en güzel yaratığı doğurur.', en: 'In Japanese legend, the first Dragonfly was born from the tear of the god Izanagi. The tear he shed while mourning for his lost beloved Izanami fell to the water, that drop took wings and flew. When pain meets transformation and becomes beauty, the most fragile moment gives birth to the most beautiful creature.', de: 'In der japanischen Legende wurde die erste Libelle aus der Träne des Gottes Izanagi geboren. Die Träne, die er in Trauer um seine verlorene Geliebte Izanami vergoss, fiel ins Wasser, jener Tropfen bekam Flügel und flog. Wenn der Schmerz die Verwandlung trifft und zur Schönheit wird, gebiert der zerbrechlichste Augenblick das schönste Geschöpf.', es: 'En la leyenda japonesa, la primera libélula nació de la lágrima del dios Izanagi. La lágrima que derramó mientras lloraba a su amada perdida Izanami cayó al agua, esa gota tomó alas y voló. Cuando el dolor se encuentra con la transformación y se vuelve belleza, el momento más frágil da a luz a la criatura más hermosa.', pt: 'Na lenda japonesa, a primeira libélula nasceu da lágrima do deus Izanagi. A lágrima que derramou ao chorar a sua amada perdida Izanami caiu na água, essa gota ganhou asas e voou. Quando a dor encontra a transformação e se torna beleza, o momento mais frágil dá à luz a criatura mais bela.', fr: 'Dans la légende japonaise, la première libellule naquit de la larme du dieu Izanagi. La larme qu\'il versa en pleurant sa bien-aimée perdue Izanami tomba dans l\'eau, cette goutte prit des ailes et s\'envola. Quand la douleur rencontre la transformation et devient beauté, l\'instant le plus fragile enfante la plus belle créature.', ja: '日本の伝説において、最初のトンボは神イザナギの涙から生まれた。失った愛するイザナミを悼んで流した涙が水に落ち、その雫が翅を得て飛んだ。苦しみが変容と出会い美となるとき、最も脆い瞬間が最も美しい生き物を生む。' },
      { tr: 'Navajo yaratılış anlatısında Yusufçuk, eski dünyadaki halkın yeni dünyaya geçerken arkasında bıraktığı bilinç kıvılcımıdır. İki dünya arasında asılı kalmış, ne tam öteki âlemde ne de bu dünyada — o yüzden hem gerçek hem yanılsama taşır.', en: 'In the Navajo creation narrative, the Dragonfly is the spark of consciousness left behind by the people of the old world as they crossed into the new. It remained suspended between two worlds, neither fully in the other realm nor in this one — that is why it carries both reality and illusion.', de: 'In der Schöpfungserzählung der Navajo ist die Libelle der Funke des Bewusstseins, den das Volk der alten Welt beim Übergang in die neue zurückließ. Sie blieb zwischen zwei Welten in der Schwebe, weder ganz im anderen Reich noch in diesem — darum trägt sie sowohl Wirklichkeit als auch Illusion.', es: 'En el relato de creación navajo, la libélula es la chispa de conciencia que dejó tras de sí el pueblo del viejo mundo al cruzar al nuevo. Quedó suspendida entre dos mundos, ni del todo en el otro reino ni en este — por eso porta a la vez realidad e ilusión.', pt: 'No relato da criação navajo, a libélula é a faísca de consciência deixada para trás pelo povo do velho mundo ao atravessar para o novo. Ficou suspensa entre dois mundos, nem totalmente no outro reino nem neste — por isso carrega ao mesmo tempo realidade e ilusão.', fr: 'Dans le récit de la création navajo, la libellule est l\'étincelle de conscience laissée derrière par le peuple de l\'ancien monde en passant dans le nouveau. Elle resta suspendue entre deux mondes, ni tout à fait dans l\'autre royaume ni dans celui-ci — c\'est pourquoi elle porte à la fois la réalité et l\'illusion.', ja: 'ナバホの創造の語りにおいて、トンボは旧き世界の民が新たな世界へ渡る際に後に残した意識の火花。二つの世界のあいだに宙づりとなり、異界にも、この世にも完全には属さない——ゆえに現実と幻の双方を担う。' },
    ],
  },

  // ─── a058 Hüdhüd ─────────────────────────────────────────────────────────
  a058: {
    jung: { tr: '"İlahi Rehber ve Ruhsal Mesaj" arketipi. Hüdhüd, bilinçdışında Öz\'ün (Self) sesi olarak belirir — yüksekten görür, derinliği sezar ve ikisi arasında köprü kurar. Tepesindeki taç, bilgeliğin tacını taşıyan kişinin özel bir görev üstlendiğini anlatır; üst dünyayla alt dünya arasındaki haberciliği ise ego ile ruhun diyaloğunu simgeler.', en: 'The "Divine Guide and Spiritual Message" archetype. The Hoopoe appears as the voice of the Self in the unconscious — it sees from above, senses depth, and bridges the two. The crown on its head tells that one who carries the crown of wisdom has taken on a special mission; its role as messenger between the upper and lower worlds symbolizes the dialogue between ego and soul.' },
    dream: { tr: 'Hüdhüd rüyada görünürse — bir rehberlik geliyor; dikkatlice dinle. Sana yaklaşıyorsa: içindeki bilge sesin önünü tıkama, konuşmasına izin ver. Uzaklaşıyorsa: görmezden geldiğin bir ilahi işareti kaçırdın — ama henüz geç değil.', en: 'If Hoopoe appears in a dream — guidance is coming; listen carefully. If it approaches you: do not block the wise voice within you, allow it to speak. If it moves away: you missed a divine sign you ignored — but it is not yet too late.' },
    shadow: { tr: '"Ben seçilmiş rehberim" kibrinin tuzağı. Hüdhüd gölgesi: manevi üstünlük iddiası, gerçek rehberliği sahte peygamberlikle karıştırmak, herkese danışılmadan öğüt vermek.', en: 'The trap of the arrogance "I am the chosen guide". The Hoopoe shadow: claiming spiritual superiority, confusing genuine guidance with false prophecy, giving advice to everyone without being asked.' },
    whenAppears: { tr: 'Önemli bir kararın arifesinde ruhsal yönlendirmeye ihtiyaç duyduğunuzda, bir öğretmen ya da lider rolü üstlenmeniz gerektiğinde ya da kayıp hissedip pusulaya baktığınızda.', en: 'When you need spiritual guidance on the eve of an important decision, when you need to assume a role as teacher or leader, or when you feel lost and look to your compass.' },
    traditions: [
      { culture: { tr: 'İslam-Sufi Geleneği', en: 'Islamic-Sufi Tradition' }, meaning: { tr: 'Feridüddin Attar\'ın Mantıku\'t-Tayr\'ında (Kuşların Dili) Hüdhüd, ruhsal yolculuğa çıkan kuşların rehberi ve sözcüsüdür. Simurg\'u arayan kuşları yönetir — bilgeliğin önderi.', en: 'In Fariduddin Attar\'s Mantiq ut-Tayr (The Conference of the Birds), the Hoopoe is the guide and spokesperson of the birds who set out on the spiritual journey. It leads the birds seeking the Simurgh — the forerunner of wisdom.' } },
      { culture: { tr: 'Kuran\'ı Kerim', en: 'The Quran' }, meaning: { tr: 'Neml Suresi\'nde Hüdhüd, Hz. Süleyman\'ın habercisi olarak Sebe Kraliçesi Belkıs\'ın haberini getirir. İlahi bilgi ile dünyevi iktidar arasındaki köprüdür.', en: 'In Surah An-Naml, the Hoopoe brings the news of Queen Bilqis of Sheba as the messenger of the Prophet Solomon. It is the bridge between divine knowledge and earthly power.' } },
      { culture: { tr: 'Mısır Hiyeroglifleri', en: 'Egyptian Hieroglyphs' }, meaning: { tr: 'Hüdhüd hiyeroglifi "şükran" ve "babanı onurlandır" anlamına gelir. Ebeveynlere bakmanın kutsal hayvanı olarak bilinir.', en: 'The Hoopoe hieroglyph means "gratitude" and "honor your father". It is known as the sacred animal of caring for parents.' } },
      { culture: { tr: 'İran Edebiyatı', en: 'Persian Literature' }, meaning: { tr: 'Hüdhüd Hafız ve Rumi şiirlerinde sıkça anılır. Mürşidin sesi, içsel rehberin sembolü. "Hüdhüd gibi haber getir" — doğru zamanı, doğru sözü bil.', en: 'The Hoopoe is frequently referenced in the poetry of Hafez and Rumi. The voice of the guide, the symbol of the inner guide. "Bring news like the Hoopoe" — know the right time, know the right word.' } },
      { culture: { tr: 'İsrail Geleneği', en: 'Israelite Tradition' }, meaning: { tr: 'Hz. Süleyman\'ın kuşu. Talmud\'da hüdhüd Hz. Süleyman\'a çölde gölge yapar — yönetici ile korunan arasındaki karşılıklı hizmetin simgesi.', en: 'The bird of King Solomon. In the Talmud, the Hoopoe shades King Solomon in the desert — symbol of mutual service between ruler and protected.' } },
    ],
    myths: [
      { tr: 'Attar\'ın Mantıku\'t-Tayr\'ında tüm kuşlar Simurg\'u bulmak için yola çıkar. Rehberleri Hüdhüd\'dür. Yedi derin vadiden geçerler: Aşk, Sezgi, Bilgi, İsteksizlik, Tevhid, Şaşkınlık ve son olarak Yokluğun Vadisi. Yolculuk sona erdiğinde geriye 30 kuş kalmıştır ve aynaya bakarlar — Simurg onlardır. Hüdhüd\'ün rehberliği, rehberi gereksiz kılan bilgeliğe ulaştırır.', en: 'In Attar\'s Mantiq ut-Tayr, all the birds set out to find the Simurgh. Their guide is the Hoopoe. They pass through seven deep valleys: Love, Intuition, Knowledge, Detachment, Unity, Bewilderment, and finally the Valley of Nothingness. When the journey ends, thirty birds remain and look into a mirror — they are the Simurgh. The Hoopoe\'s guidance leads to the wisdom that makes the guide unnecessary.' },
      { tr: 'Hz. Süleyman\'ın Hüdhüdü: Kuşların sultanı Süleyman, Hüdhüd\'ün yokluğunu fark eder ve öfkelenir. Hüdhüd döner ve der ki: "Senin bilmediğin bir şeyi öğrendim — Yemen\'de güneşe tapan bir kraliçe var." Bu haberle Belkıs İslam\'a girer. Küçük bir haberci, büyük bir uyanışı başlatabilir.', en: 'The Hoopoe of King Solomon: Solomon, sultan of birds, notices the Hoopoe\'s absence and grows angry. The Hoopoe returns and says: "I have learned something you do not know — there is a queen in Yemen who worships the sun." With this news, Bilqis accepts the faith of Solomon. A small messenger can initiate a great awakening.' },
    ],
  },

  // ─── a059 Akbaba ─────────────────────────────────────────────────────────
  a059: {
    jung: { tr: '"Arınma ve Ölümü Kucaklama" arketipi. Akbaba, kolektif bilinçdışında en derin tabu ile yüzleşmeyi — ölümle barışmayı — temsil eder. Pisliği yiyen ama kendisi temiz kalan bu kuş, gölge materyalini sindirerek onu dönüştürmenin simgesidir. Onu itici bulmak, kendi ölümlülüğümüzle yüzleşmekten kaçışın bir yansımasıdır.', en: 'The "Purification and Embracing Death" archetype. The Vulture represents confronting the deepest taboo in the collective unconscious — making peace with death. This bird that eats filth yet remains clean itself is the symbol of transforming shadow material by digesting it. Finding it repulsive is a reflection of our flight from confronting our own mortality.' },
    dream: { tr: 'Akbaba rüyada görünürse — bir şeyin gerçekten bittiğini kabul etme vakti; yas tutmayı erteledin. Yemek yiyorsa: dönüşüm sürüyor, bekle. Başının üzerinde dönüyorsa: bir durumu senin yerine çözmeye çalışmıyorlar, sadece zamanı geldiğinde temizlenecek.', en: 'If Vulture appears in a dream — it is time to accept that something has truly ended; you have been postponing mourning. If it is eating: transformation is ongoing, wait. If it circles above your head: they are not trying to solve a situation in your place, only what will be cleansed when the time comes.' },
    shadow: { tr: 'Ölümle sağlıklı temas yerine ölüme büyülenme — katastrof beklentisi, başkalarının çöküşünden beslenme. Akbaba gölgesi: fırsatçılık, başkasının zayıflığından kazanç sağlama, kötümserlik.', en: 'Instead of healthy contact with death, fascination with death — catastrophic expectation, feeding on the collapse of others. The Vulture shadow: opportunism, profiting from the weakness of others, pessimism.' },
    whenAppears: { tr: 'Uzun süre bitmesi gereken bir şeyi tutunmaya devam ettiğinizde, derin bir kaybı sindirmeniz gerektiğinde ya da eskiyi temizleyip yeniye alan açmanız gereken dönemlerde.', en: 'When you continue to hold on to something that should have ended long ago, when you need to digest a deep loss, or during periods when you need to cleanse the old and make room for the new.' },
    traditions: [
      { culture: { tr: 'Mısır Medeniyeti', en: 'Egyptian Civilization' }, meaning: { tr: 'Nekhbet — akbaba başlı tanrıça, Yukarı Mısır\'ın koruyucusu. Anne ve kraliçe sembolü. Firavunlar tacının üzerinde Nekhbet akbabası taşırdı. Ölümü ve yeniden doğumu yöneten kutsal varlık.', en: 'Nekhbet — the vulture-headed goddess, protector of Upper Egypt. Symbol of mother and queen. Pharaohs bore the vulture of Nekhbet on their crown. The sacred being governing death and rebirth.' } },
      { culture: { tr: 'Tibet Budizmi', en: 'Tibetan Buddhism' }, meaning: { tr: 'Gökyüzü Gömüsü (Jhator) ritüelinde Akbabalar kutsal temizleyicilerdir. Ölen kişinin bedenini yiyen Akbabalar ruhu gökyüzüne taşır. Ölüm korkulacak değil, döngünün bir halkasıdır.', en: 'In the Sky Burial (Jhator) ritual, Vultures are sacred purifiers. Vultures that consume the body of the deceased carry the soul to the sky. Death is not to be feared, it is a link in the cycle.' } },
      { culture: { tr: 'Zerdüşt Geleneği', en: 'Zoroastrian Tradition' }, meaning: { tr: 'Ateşin ve toprağın kirlenmemesi için cesetler Sessizlik Kulesi\'nde Akbabalara bırakılır. Akbaba, maddeyi spiritüele dönüştüren kutsal araçtır.', en: 'So that fire and earth are not defiled, corpses are left to Vultures in the Tower of Silence. The Vulture is the sacred instrument transforming matter into the spiritual.' } },
      { culture: { tr: 'Maya Takvimi', en: 'Maya Calendar' }, meaning: { tr: 'Kibich (Akbaba) — Maya takvimine göre güneşin yeniden doğuşuyla ilişkilendirilir. Şaman ölümünü ve ruhsal yeniden doğumunu sembolize eder.', en: 'Kibich (Vulture) — associated with the rebirth of the sun according to the Maya calendar. Symbolizes the shaman\'s death and spiritual rebirth.' } },
      { culture: { tr: 'Yunan-Anadolu Geleneği', en: 'Greco-Anatolian Tradition' }, meaning: { tr: 'Prometheus\'u karaciğerinden her gün yiyen kartal değil, bazı anlatılarda akbabadır. Süregelen acının içinde bile yenileme ve arınma döngüsü işler.', en: 'In some narratives it is not the eagle but the vulture that eats from Prometheus\'s liver each day. Even within enduring pain, the cycle of renewal and purification works.' } },
    ],
    myths: [
      { tr: 'Tibet\'in Jhator (Gökyüzü Gömüsü) ritüeli: Lama bedeni 108 parçaya böler, Akbabalara sunar. Akbabalar yedikçe ruh bedenin ağırlığından kurtulur ve Bardo\'ya — ölüm ile yeniden doğuş arası berzah — geçer. "Beden zaten ödünç alınmıştı; şimdi geri veriyoruz" — Budist ölüm felsefesinin özü.', en: 'Tibet\'s Jhator (Sky Burial) ritual: The Lama divides the body into 108 pieces and offers them to the Vultures. As the Vultures eat, the soul is freed from the weight of the body and passes to Bardo — the intermediate state between death and rebirth. "The body was borrowed to begin with; now we return it" — the essence of Buddhist death philosophy.' },
      { tr: 'Mısır yaratılış mitinde Nekhbet ve Wadjet — Akbaba ve Kobra — birlikte Firavun\'un tacını oluştururlar. Biri Güney\'i, biri Kuzey\'i temsil eder; biri ölümü, biri yaşamı. Taç bu iki gücü birleştirir. Gerçek egemenlik, zıtları bir arada tutabilmektir.', en: 'In the Egyptian creation myth, Nekhbet and Wadjet — Vulture and Cobra — together form the Pharaoh\'s crown. One represents the South, the other the North; one death, the other life. The crown unites these two forces. True sovereignty is the ability to hold opposites together.' },
    ],
  },

  // ─── a060 Jaguar ─────────────────────────────────────────────────────────
  a060: {
    jung: { tr: '"Gece Güneşi ve Şaman Dönüşümü" arketipi. Jaguar, bilinçdışının en derin katmanını — Gölge\'nin tahtını — temsil eder. Geceleri parlayan gözleri, karanlığın içinde bilinçle görmeyi simgeler. Dönüştürücü güç: Jaguar şaman yalnızca hayvanı çağırmaz, kendisi Jaguar olur — ego sınırlarının tamamen eridiği birleşme hali.', en: 'The "Night Sun and Shamanic Transformation" archetype. The Jaguar represents the deepest layer of the unconscious — the throne of the Shadow. Its eyes that shine in the night symbolize seeing with consciousness inside the darkness. The transformative power: the Jaguar shaman does not merely summon the animal, he becomes the Jaguar — the state of union where ego boundaries completely dissolve.' },
    dream: { tr: 'Jaguar rüyada görünürse — bilinçdışının en derin mesajı yüzeye çıkıyor; korkma, bak. Seni kovalıyorsa: yüzleşmekten kaçtığın güçlü bir içsel güç var. Yanında sessizce yürüyorsa: gücünle barışıksın, şaman yolculuğuna hazırsın.', en: 'If Jaguar appears in a dream — the deepest message of the unconscious is surfacing; do not be afraid, look. If it chases you: there is a powerful inner force you are running from confronting. If it walks silently beside you: you are at peace with your power, you are ready for the shamanic journey.' },
    shadow: { tr: 'Karanlığa çekilme, toplumdan kopuş ve yıkıcı yalnızlık. Jaguar gölgesi: zalimlik, güç üzerinden kurulmuş ilişkiler, merhametsizlik. Ya da güçten tamamen kopma — kendi Jaguarından kaçış.', en: 'Being drawn to the darkness, withdrawal from society, and destructive solitude. The Jaguar shadow: cruelty, relationships built on power, mercilessness. Or complete disconnection from power — fleeing from one\'s own Jaguar.' },
    whenAppears: { tr: 'Derinliklerle — bilinçdışınızla, ölümle, seksüalite ya da güçle — yüzleşmeniz gereken dönemlerde; şamanistik ya da spiritüel bir dönüşüm sürecinin içindeyken.', en: 'During periods when you must confront the depths — your unconscious, death, sexuality or power; when you are within a shamanistic or spiritual transformation process.' },
    traditions: [
      { culture: { tr: 'Olmek Medeniyeti', en: 'Olmec Civilization' }, meaning: { tr: 'Olmek sanatının merkezinde İnsan-Jaguar melezi figürü vardır — şaman ile kutsal hayvanın birleşimi. Jaguar dönüşümü, ilk Amerikan uygarlığının temel ruhsal pratiğidir.', en: 'At the center of Olmec art is the human-jaguar hybrid figure — the union of the shaman and the sacred animal. Jaguar transformation is the fundamental spiritual practice of the first American civilization.' } },
      { culture: { tr: 'Maya Uygarlığı', en: 'Maya Civilization' }, meaning: { tr: 'Ix\'Chel — Maya\'nın ay tanrıçası, Jaguar\'ın gücünü taşır. Yöneticiler "Jaguar" unvanı alırdı. Alt dünya yöneticisi Ah Puch\'un tapınağında Jaguar derisi kutsal örtüdür.', en: 'Ix\'Chel — the Maya moon goddess, carries the power of the Jaguar. Rulers received the title "Jaguar". In the temple of the underworld ruler Ah Puch, jaguar skin is the sacred covering.' } },
      { culture: { tr: 'Aztek Uygarlığı', en: 'Aztec Civilization' }, meaning: { tr: 'Jaguar Savaşçıları — Ocēlōtl — Aztek\'in seçkin askeri sınıfı. Jaguarın gücünü içselleştirmiş savaşçılar. Güneş tanrısı Tezcatlipoca gece gökyüzünde Jaguar biçimine girer.', en: 'Jaguar Warriors — Ocēlōtl — the elite military class of the Aztecs. Warriors who have internalized the power of the Jaguar. The sun god Tezcatlipoca takes the form of the Jaguar in the night sky.' } },
      { culture: { tr: 'And Şamanizmi', en: 'Andean Shamanism' }, meaning: { tr: 'Ayahuasca seremonilerinde Jaguar ruhunun görülmesi şamanın olgunlaştığının işaretidir. Jaguar alt dünyayla iletişimi sağlar; karanlığı taşıyabilmek ruhsal güç gerektirir.', en: 'Seeing the spirit of the Jaguar in ayahuasca ceremonies is a sign that the shaman has matured. The Jaguar enables communication with the underworld; being able to carry darkness requires spiritual strength.' } },
      { culture: { tr: 'Toltec Bilgeliği', en: 'Toltec Wisdom' }, meaning: { tr: 'Don Miguel Ruiz\'in aktardığı Toltec geleneğinde Jaguar, rüyanın efendisidir — hem bireysel rüyalar hem de toplumsal yanılsamalar üzerinde hakimiyet anlamında. Gerçek savaşçı kendi zihnine hükmeder.', en: 'In the Toltec tradition as conveyed by Don Miguel Ruiz, the Jaguar is the master of the dream — in the sense of mastery over both individual dreams and collective illusions. The true warrior rules their own mind.' } },
    ],
    myths: [
      { tr: 'Aztek yaratılış mitinde Tezcatlipoca ve Quetzalcoatl dünyanın yaratıcılarıdır ve sürekli mücadele halindedir. Tezcatlipoca, Quetzalcoatl tarafından devrilen her güneş döngüsünde Jaguar biçimine girerek geceyi yönetir. Gece güneşi, gündüz güneşi kadar güçlüdür — karanlık yalnızca yokluğun değil, gizli gücün adıdır.', en: 'In the Aztec creation myth, Tezcatlipoca and Quetzalcoatl are the creators of the world and are in perpetual struggle. In each solar cycle overthrown by Quetzalcoatl, Tezcatlipoca takes the form of the Jaguar to rule the night. The night sun is as powerful as the day sun — darkness is not merely the name of absence, but of hidden power.' },
      { tr: 'Amazon şamanizmi: Büyük bir şaman ilk kez Jaguar ruhunu çağırdığında, ruh onu sınar — o gece şaman hem avlanır hem avdır. Sabah güneşiyle birlikte ayağa kalkarsa, artık iki dünyada birden yürüyebilir demektir. İlk dönüşüm her zaman ölümcül görünür; hayatta kalanlar şaman olur.', en: 'Amazon shamanism: When a great shaman calls the Jaguar spirit for the first time, the spirit tests them — that night the shaman is both hunter and hunted. If they rise with the morning sun, it means they can now walk in both worlds simultaneously. The first transformation always appears lethal; those who survive become shamans.' },
    ],
  },

  // ─── a061 Kobra ─────────────────────────────────────────────────────────
  a061: {
    jung: { tr: '"İlahi Koruyucu" ve "Kundalini Enerjisi" arketipi. Kobra, bilinçaltının en derin katmanlarında yatan dönüştürücü gücü temsil eder — uyandırıldığında ne iyileştirir ne de yıkım getirir, ikisini birden yapar. Kral işareti olarak taç giyen yılan, ego\'nun aşılıp evrensel bilince erişmenin simgesidir.', en: 'The "Divine Protector" and "Kundalini Energy" archetype. The cobra represents the transformative power coiled in the deepest layers of the unconscious — when awakened it neither heals nor destroys alone, it does both at once. The serpent crowned as a royal mark is the symbol of transcending ego to access universal consciousness.' },
    dream: { tr: 'Kobra rüyada dikilip sana bakıyorsa — içindeki uyuyan güç uyanmak üzere. Saldırıyorsa: bastırılmış hayat enerjisi dışa çıkmak istiyor, artık kaçmak mümkün değil. Başında taç varsa ya da dans ediyorsa: kutsal bir koruma altındasın, içgüdülerine güven.', en: 'If a cobra stands and watches you in a dream — the sleeping power within is about to awaken. If it strikes: suppressed life energy wants to emerge, escape is no longer possible. If it wears a crown or dances: you are under sacred protection, trust your instincts.' },
    shadow: { tr: 'Kobra gölgesi — zehri dışarı değil içe sıkıştırmak. Baskılanmış öfke, ifade edilemeyen güç kimliği çürütür. Öteki uçta: gücünü başkalarını felç etmek için kullanmak, gözdağı ve manipülasyon.', en: 'The cobra\'s shadow — injecting venom inward rather than outward. Suppressed rage, unexpressed power corrodes identity. At the other extreme: using power to paralyze others, through intimidation and manipulation.' },
    whenAppears: { tr: 'Kundalini deneyimi eşiğinde, ruhsal bir uyanışın tam öncesinde, iyileşme krizi anında ya da liderliğin kaçınılmaz hale geldiği dönemeçlerde.', en: 'On the threshold of kundalini experience, in the moment just before spiritual awakening, during a healing crisis, or at crossroads where leadership becomes unavoidable.' },
    traditions: [
      { culture: { tr: 'Hindu', en: 'Hindu' }, meaning: { tr: 'Şiva\'nın boynundaki kobra — Kundalini Shakti\'nin sembolü. Omurga boyunca yükselen ilahi enerjiyi temsil eder.', en: 'The cobra around Shiva\'s neck — symbol of Kundalini Shakti. Represents the divine energy rising along the spine.' } },
      { culture: { tr: 'Mısır', en: 'Egyptian' }, meaning: { tr: 'Uraeus — firavunların taçlarında kobra. İlahi otorite, koruyucu ateş ve Ra\'nın gücünün simgesi.', en: 'Uraeus — the cobra on pharaohs\' crowns. Symbol of divine authority, protective fire, and the power of Ra.' } },
      { culture: { tr: 'Budizm', en: 'Buddhism' }, meaning: { tr: 'Mucalinda yılanı — meditasyon eden Buda\'yı yağmurdan korumak için başının üstünde açılan dev kobra. İlahi koruma imgesi.', en: 'Mucalinda serpent — the great cobra that spread its hood over the meditating Buddha to shield him from rain. An image of divine protection.' } },
      { culture: { tr: 'Yunan', en: 'Greek' }, meaning: { tr: 'Asklepios\'un asasındaki yılan — iyileştirici bilgelik ve dönüşümün simgesi. Zehir hem öldürür hem de şifalandırır.', en: 'The serpent on the staff of Asclepius — symbol of healing wisdom and transformation. Venom both kills and cures.' } },
      { culture: { tr: 'Anadolu / Hitit', en: 'Anatolian / Hittite' }, meaning: { tr: 'Tarkan yılanı — tanrıların haberini taşıyan kutsal sürüngen. Kayalara kazınan yılan figürleri koruyucu ruh olarak kabul edilirdi.', en: 'The sacred serpent of Hittite tradition — the reptile that carried the gods\' messages. Serpent figures carved into rock were regarded as protective spirits.' } },
    ],
    myths: [
      { tr: 'Hint mitolojisinde Adi Şesha, evrenin yükünü sırtında taşıyan bin başlı kobradır; Vişnu onun üzerinde uyur. Yaratılış ve yıkım arasındaki denge, bu yılanın nefesiyle tutulur.', en: 'In Hindu mythology, Adi Shesha is the thousand-headed cobra who bears the weight of the universe; Vishnu sleeps upon him. The balance between creation and destruction is held by this serpent\'s breath.' },
      { tr: 'Mısır\'da İsis, kobra biçimine bürünerek Osiris\'i ölüler diyarından geri çekmiştir. Yılanın yeniden doğuşu — her yıl derisini dökmesi — sonsuzluğun döngüsel simgesi olarak tapınıldı.', en: 'In Egypt, Isis took the form of a cobra to draw Osiris back from the realm of the dead. The serpent\'s renewal — shedding its skin every year — was venerated as a cyclical symbol of eternity.' },
    ],
  },

  // ─── a062 Puma ───────────────────────────────────────────────────────────
  a062: {
    jung: { tr: '"Sessiz Lider" ve "Gizli Güç" arketipi. Puma gürlemez — varlığıyla yönetir. Jung\'un gölge çalışmasında puma, ego\'nun sessizliğe çekilip gerçek gücünü keşfettiği o kristal ana karşılık gelir. Yalnızlık burada zayıflık değil, özgünlüğün koşuludur.', en: 'The "Silent Leader" and "Hidden Power" archetype. The puma does not roar — it leads with presence. In Jungian shadow work, the puma corresponds to that crystalline moment when ego withdraws into silence and discovers its true power. Solitude here is not weakness — it is the condition for authenticity.' },
    dream: { tr: 'Puma rüyanda seni izliyorsa — içindeki liderlik seni takip ediyor, henüz kabul etmedin. Peşinden geliyorsa: liderlikten kaçma, o güç zaten senin. Hareketsiz duruyorsa: karar zamanı, çevrenin gürültüsüne değil içindeki sessizliğe kulak ver.', en: 'If the puma watches you in a dream — the leadership within is following you, you have not yet accepted it. If it comes after you: do not flee from leadership, that power is already yours. If it stands motionless: it is time to decide, listen to the silence within rather than the noise around you.' },
    shadow: { tr: 'Gücünü gizlemeyi bir silaha dönüştürmek — manipülatif sessizlik, soğuk mesafe. Aşırı uçta: dünyanın geri kalanını küçümseyerek tam yalnızlığa çekilmek ve gerçek bağlantıdan kopuş.', en: 'Turning the concealment of power into a weapon — manipulative silence, cold distance. At the extreme: withdrawing into total isolation while contemning the rest of the world, severing genuine connection.' },
    whenAppears: { tr: 'Liderlik rolünü üstlenmekte tereddüt ettiğinde, başkalarının sesi altında kendi sesini kaybettiğinde ya da yalnız bir karar almanın tam eşiğinde.', en: 'When you hesitate to take on a leadership role, when your own voice is lost under the voices of others, or on the precise threshold of making a solitary decision.' },
    traditions: [
      { culture: { tr: 'İnka / And Medeniyeti', en: 'Inca / Andean' }, meaning: { tr: 'Puma — Inca kozmolojisinin üç dünyasından biri olan Kay Pacha\'nın (bu dünya) simgesi. Cuzco şehri puma biçiminde inşa edilmiştir.', en: 'Puma — symbol of Kay Pacha (this world), one of the three realms of Inca cosmology. The city of Cuzco was built in the shape of a puma.' } },
      { culture: { tr: 'Kuzey Amerika Yerlileri (Quechua)', en: 'Native North American (Quechua)' }, meaning: { tr: 'Dağ aslanı — hem avcı hem de adil yargıç. Liderlik gücünü sessiz ve dengeli kullananların totemine sahip çıkar.', en: 'Mountain lion — both hunter and fair judge. Claims the totem of those who wield leadership power silently and in balance.' } },
      { culture: { tr: 'Aztec', en: 'Aztec' }, meaning: { tr: 'Ocelotl savaşçıları — puma ve jaguar derisi giyen seçkin savaş birliği. Karanlıkta görme ve gizli güç sembolü.', en: 'Ocelotl warriors — the elite combat unit wearing puma and jaguar skins. Symbol of seeing in the dark and concealed power.' } },
      { culture: { tr: 'Mapuche (Şili)', en: 'Mapuche (Chile)' }, meaning: { tr: 'Puma, atalardan gelen koruyucu ruh. Şamanlar puma biçimine bürünerek ata dünyasıyla iletişim kurduğuna inanılır.', en: 'The puma is the ancestral protective spirit. Shamans are believed to take puma form to communicate with the world of ancestors.' } },
      { culture: { tr: 'Anadolu / Halk İnancı', en: 'Anatolian / Folk Belief' }, meaning: { tr: 'Yırtıcı kediler Anadolu\'da "dağ sultanı" sayılır; gücü sessiz taşıyan ve haksızlığa uğramış ruhları koruyan kutsal varlıklar olarak anılır.', en: 'Large wild cats are considered "mountain sultans" in Anatolia; they are revered as sacred beings who silently carry power and protect souls that have been wronged.' } },
    ],
    myths: [
      { tr: 'İnka söylencesine göre Viracocha tanrı, dünyanın ilk insanlarını puma biçiminde yarattı; sonra onları insan yaptı ama puma ruhu içlerinde kaldı. Her büyük lider bu gizli puma ruhunu taşır.', en: 'According to Inca legend, the god Viracocha first created the world\'s first humans in the form of a puma; then he made them human, but the puma spirit remained within them. Every great leader carries this hidden puma spirit.' },
      { tr: 'And şamanizminde puma, ölüler ve yaşayanlar arasındaki sınırda yürür. Geçiş törenlerinde genç savaşçı yalnız dağa gönderilir — pumayı görürse ruhsal olgunluğa erişmiş sayılır, çünkü puma yalnızca hazıra görünür.', en: 'In Andean shamanism, the puma walks the boundary between the dead and the living. In initiation rites a young warrior is sent alone to the mountain — if he sees the puma he is deemed to have attained spiritual maturity, for the puma appears only to those who are ready.' },
    ],
  },

  // ─── a063 Su Samuru ──────────────────────────────────────────────────────
  a063: {
    jung: { tr: '"Oyuncu Kadın Bilgeliği" ve "Akan Şans" arketipi. Su samuru, Jungian anima figürünün en hafif ve en özgür tezahürüdür — ağırlığı yoktur, her şeyin üzerinden kayar. Bilgeliği oyunun içinde taşır; ciddiyet gerektiren yerlerde bile şakasını yapar, çünkü gerçek anlayış kasılmadan gelir.', en: 'The "Playful Feminine Wisdom" and "Flowing Luck" archetype. The otter is the lightest and most liberated expression of the Jungian anima — it carries no weight, gliding over everything. It holds wisdom inside play; it jokes even where seriousness is expected, because true understanding comes without tension.' },
    dream: { tr: 'Su samuru rüyanda suyun üstünde kayarak geçiyorsa — hayatın daha hafif tutulması gerekiyor, zorla değil akışla. Seninle oynuyorsa: içindeki çocuk özgürlük istiyor. Suya dalıp kayboluyorsa: bilinçdışının derinliklerine mutlu bir yolculuk yapıyorsun.', en: 'If the otter slides across water in your dream — life needs to be held more lightly, through flow not force. If it plays with you: the child within wants freedom. If it dives and disappears: you are making a joyful journey into the depths of the unconscious.' },
    shadow: { tr: 'Hiçbir şeyi ciddiye almamak, sorumluluktan kaçmak için oyunu kalkan olarak kullanmak. Öte yanda: kaygıdan doğan aşırı kontrol — suyun akışını durdurmaya çalışmak, şansı zorlamak.', en: 'Taking nothing seriously, using play as a shield to escape responsibility. On the other side: excessive control born of anxiety — trying to stop the flow of water, forcing luck.' },
    whenAppears: { tr: 'Hayatın ağırlığı altında ezilirken, yaratıcılığını kaybettiğini hissedince ya da bir ilişkide ya da işte sevinci yeniden bulmak gerektiğinde.', en: 'When crushed under the weight of life, when you feel you have lost your creativity, or when joy needs to be rediscovered in a relationship or vocation.' },
    traditions: [
      { culture: { tr: 'Kelt', en: 'Celtic' }, meaning: { tr: 'Su samuru Kelt efsanelerinde kutsal nehirlerin koruyucusudur. İrlanda geleneğinde "dobhar-chú" — nehir tanrıçasının elçisi.', en: 'In Celtic legend the otter is the guardian of sacred rivers. In Irish tradition "dobhar-chú" — the messenger of the river goddess.' } },
      { culture: { tr: 'Japon', en: 'Japanese' }, meaning: { tr: 'Kawa-uso — nehirlerde yaşayan dönüşebilen ruh. Şansı beraberinde getirir ama kandırılmayı da sever.', en: 'Kawa-uso — a shape-shifting spirit living in rivers. It brings luck but also enjoys trickery.' } },
      { culture: { tr: 'Kuzey Amerika Yerlileri (Haida)', en: 'Native North American (Haida)' }, meaning: { tr: 'Su samuru dişil ruhun simgesi; aile bağını, neşeyi ve topluluk içindeki kadın bilgeliğini temsil eder.', en: 'The otter is a symbol of the feminine spirit; it represents family bonds, joy, and feminine wisdom within the community.' } },
      { culture: { tr: 'İran / Fars', en: 'Iranian / Persian' }, meaning: { tr: 'Avesta\'da su samuru kutsal sayılır — Ahura Mazda\'nın yaratığı. Onu öldürmek günahtır, nehrin bereketini keser.', en: 'In the Avesta the otter is considered sacred — a creature of Ahura Mazda. Killing one is a sin that cuts off the river\'s abundance.' } },
      { culture: { tr: 'Anadolu / Halk İnancı', en: 'Anatolian / Folk Belief' }, meaning: { tr: 'Nehir kenarlarında görülen su samuru, "suların şans getiren beyi" olarak bilinir; balıkçılar onu görürse o gün ağ dolacağına inanır.', en: 'The otter seen along riverbanks is known as "the luck-bringing lord of the waters"; fishermen believe that seeing one means the net will be full that day.' } },
    ],
    myths: [
      { tr: 'İrlanda efsanesinde Fionn mac Cumhaill\'in dostu, nehir tanrıçasının gönderdiği bir su samurudur. Samur, kahramana görünmez bir zırh giyer ve su altındaki hazineyi gösterir — bilgelik her zaman oyunun içinde gizlidir.', en: 'In Irish legend, the companion of Fionn mac Cumhaill is an otter sent by the river goddess. The otter clothes the hero in invisible armor and reveals the treasure beneath the water — wisdom is always hidden inside play.' },
      { tr: 'Zerdüştlükte anlatılır: Bir samur öldürüldüğünde rüzgarlar durur, mahsul kurur, çocuklar hastalanır. Yeniden dirilmesi için yüzlerce kurban gerekir. Su samurunun şansı tüm topluluğu taşır.', en: 'It is told in Zoroastrianism: when an otter is killed the winds stop, crops wither, children fall ill. Hundreds of offerings are required for its resurrection. The otter\'s luck carries the whole community.' },
    ],
  },

  // ─── a064 Balıkçıl ──────────────────────────────────────────────────────
  a064: {
    jung: { tr: '"Öz-Belirlenim" ve "Temaşa Bilgeliği" arketipi. Balıkçıl, saatlerce kıpırdamadan durabilir — dışarıdan hareketsizlik, içeride mutlak farkındalık. Jung\'un "individuasyon" sürecinde bu kuş, egonun gürültüsü sustuğunda ortaya çıkan derin öz-bilgiyi simgeler. Sabır burada pasiflik değil, zamanın doğru biçimde kullanılmasıdır.', en: 'The "Self-Determination" and "Contemplative Wisdom" archetype. The heron can stand motionless for hours — outwardly stillness, inwardly absolute awareness. In Jung\'s process of individuation this bird symbolizes the deep self-knowledge that emerges when the ego\'s noise falls silent. Patience here is not passivity — it is the proper use of time.' },
    dream: { tr: 'Balıkçıl rüyanda suda hareketsiz duruyorsa — bekle, henüz doğru an gelmedin. Uçuyorsa: yalnız bir karar almanın vakti geldi, kimseye danışma. Su içinden balık tutuyorsa: bilinçdışından net bir cevap geliyor, dikkat et.', en: 'If the heron stands motionless in water in your dream — wait, the right moment has not yet arrived. If it flies: the time has come to make a solitary decision, consult no one. If it catches a fish from the water: a clear answer is coming from the unconscious, pay attention.' },
    shadow: { tr: 'Bekleyişi sonsuza uzatmak — fırsatları hareketsizliğin arkasına saklanarak kaçırmak. Öte yanda: izolasyonu erdem saymak, yardımı reddetmek ve başkalardan üstün bir yalnızlık içinde donup kalmak.', en: 'Extending the wait into infinity — missing opportunities by hiding behind stillness. On the other side: mistaking isolation for virtue, refusing help, and freezing in a solitude that considers itself superior to others.' },
    whenAppears: { tr: 'Aceleci kararların bedel ödettirdiği bir dönemde, meditasyon ya da inzivayı düşünürken ya da kendi içsel bilgeliğine güvenmeyi öğrenmen gereken anda.', en: 'In a period when hasty decisions have exacted a price, when you are thinking of meditation or retreat, or at the moment you must learn to trust your own inner wisdom.' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian' }, meaning: { tr: 'Bennu kuşu (balıkçıl tabanlı) — yaratılışın ilk anında Nun\'un sularından yükselen güneş ruhu. Zaman ve yeniden doğuşun efendisi.', en: 'The Bennu bird (heron-based) — the solar spirit rising from the waters of Nun at the first moment of creation. Master of time and rebirth.' } },
      { culture: { tr: 'Japon', en: 'Japanese' }, meaning: { tr: 'Sagi — Shinto geleneğinde saflık ve öz-denetim sembolü. Beyaz balıkçıl, ruhun arınmasının habercisidir.', en: 'Sagi — in Shinto tradition a symbol of purity and self-discipline. The white heron heralds the purification of the spirit.' } },
      { culture: { tr: 'Kelt', en: 'Celtic' }, meaning: { tr: 'Corr — kelt mitinde balıkçıl, yalnız bilge ve öteki dünyanın sınırında duran bekçidir. Druidlerin kutsal kuşu sayılır.', en: 'Corr — in Celtic myth the heron is the solitary sage and guardian standing at the boundary of the otherworld. It is considered the sacred bird of the Druids.' } },
      { culture: { tr: 'Çin', en: 'Chinese' }, meaning: { tr: 'Cangbai — sabır ve uzun ömür sembolü. Balıkçıl tüyleri üst düzey yetkililerin tacını süslüyordu; öz-denetimin sosyal statü getirdiği inancıyla.', en: 'Cangbai — symbol of patience and longevity. Heron feathers adorned the crowns of high-ranking officials, reflecting the belief that self-discipline brings social standing.' } },
      { culture: { tr: 'Anadolu / Halk Şiiri', en: 'Anatolian / Folk Poetry' }, meaning: { tr: 'Türk halk şiirinde "balıkçıl" sabırlı aşkın simgesidir — yıllar boyunca aynı kıyıda bekleyen âşık imgesi.', en: 'In Turkish folk poetry the heron is a symbol of patient love — the image of a lover waiting years on the same shore.' } },
    ],
    myths: [
      { tr: 'Mısır yaratılış anlatısında Bennu kuşu, var olmayan bir zamanda, karanlık sulardan yükselen tek kayaya kondu ve ilk sesi çıkardı. O ses yaratılışı başlattı. Balıkçıl hareketsizliği kaos öncesindeki sonsuz potansiyeli taşır.', en: 'In the Egyptian creation narrative, the Bennu bird alighted on the single rock rising from dark waters at a time before time, and uttered the first cry. That cry initiated creation. The heron\'s stillness carries the infinite potential that precedes chaos.' },
      { tr: 'İrlanda efsanesinde Fionnuala adlı kız üvey annesi tarafından balıkçıla dönüştürülür; dokuz yüz yıl boyunca üç göl arasında uçar. Her kış soğuğunda bile şarkı söylemeyi bırakmaz — çünkü sabır ve öz-belirlenim, büyüyü çözen tek anahtardır.', en: 'In Irish legend a girl named Fionnuala is turned into a heron by her stepmother; for nine hundred years she flies among three lakes. Even through every winter\'s cold she never stops singing — because patience and self-determination are the only key that breaks the enchantment.' },
    ],
  },

  // ─── a065 Çakal ─────────────────────────────────────────────────────────
  a065: {
    jung: { tr: '"Trickster Öğretici" ve "Geçiş Rehberi" arketipi. Çakal, Jung\'un en derin trickster figürüdür — saçma görünen davranışların ardında evrenin işleyişini anlatır. Sınırda yürür: ne tam yaşam ne tam ölüm, ne tam bilge ne tam aptal. Anubis geleneğinde olduğu gibi, ölü ruhları karanlıkta yol göstermeksizin kaybedeceği labirentin içinden çıkarır.', en: 'The "Trickster Teacher" and "Guide of Passage" archetype. The jackal is Jung\'s deepest trickster figure — behind seemingly absurd behavior it narrates the workings of the universe. It walks the boundary: not quite life, not quite death, not quite wise, not quite fool. As in the Anubis tradition, it leads dead souls out of the labyrinth where they would be lost in the dark without guidance.' },
    dream: { tr: 'Çakal rüyanda gülerken görülüyorsa — dikkat et, şu an anlamadığın bir ders veriliyor. Geceleri uluryorsa: bir geçiş döneminin ortasındasın, yönünü bil. Seni rehberliğinde götürüyorsa: bilinçdışı seni daha derin bir hakikate doğru çekiyor.', en: 'If you see the jackal laughing in a dream — pay attention, a lesson you do not yet understand is being given. If it howls at night: you are in the middle of a transition, know your direction. If it leads you in guidance: the unconscious is drawing you toward a deeper truth.' },
    shadow: { tr: 'Trickster enerjisinin karanlık yüzü: aldatma, istismar, kaosu amaç haline getirmek. Çakalın gölgesi her şeyle alay eden, hiçbir şeyi kutsal saymayan sinik zihindir.', en: 'The dark face of trickster energy: deception, exploitation, making chaos an end in itself. The jackal\'s shadow is the cynical mind that mocks everything and holds nothing sacred.' },
    whenAppears: { tr: 'Bir dönem kapanıp yenisi başlamak üzereyken, yasın ortasında anlam arayışında ya da başkasının öğretemediği bir dersi hayat sana verirken.', en: 'When one chapter is closing and another is about to begin, in the midst of grief searching for meaning, or when life itself is giving you a lesson no one else could teach.' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian' }, meaning: { tr: 'Anubis — çakal başlı ölüler tanrısı. Ölünün kalbini tüy ile tartar; ruhları Duat\'tan geçirir. Adil yargı ve geçiş rehberliğinin efendisi.', en: 'Anubis — the jackal-headed god of the dead. He weighs the heart of the deceased against the feather; he guides souls through the Duat. Master of just judgment and guidance through passage.' } },
      { culture: { tr: 'Afrika / Yoruba', en: 'African / Yoruba' }, meaning: { tr: 'Çakal benzeri hilekâr hayvan figürleri, bilgeliğin gülünç görünen kılığa büründüğü anlatıları temsil eder.', en: 'Jackal-like trickster animal figures represent narratives where wisdom takes on a ridiculous disguise.' } },
      { culture: { tr: 'Kuzey Amerika Yerlileri (Navajo)', en: 'Native North American (Navajo)' }, meaning: { tr: 'Coyote (çakalla özdeşleşir) — dünyayı yaratan ve bozan trickster. Her düzeni bozuşu yeni bir denge doğurur.', en: 'Coyote (identified with the jackal) — the trickster who creates and undoes the world. Each disruption of order gives birth to a new balance.' } },
      { culture: { tr: 'Hint', en: 'Indian' }, meaning: { tr: 'Panchatantra masallarında çakal — kurnaz ancak adil rehber. Gücü olmayanın zekâsıyla zafere ulaşmasını anlatan hikayelerin kahramanı.', en: 'In the Panchatantra the jackal is the cunning yet just guide. The hero of stories where one without power achieves victory through intelligence.' } },
      { culture: { tr: 'Anadolu / Halk Geleneği', en:  'Anatolian / Folk Tradition' }, meaning: { tr: '"Çakal derisi" deyimi Anadolu\'da gerçeği örtbas edenleri anlatır; ama halk anlatısında çakal aynı zamanda zayıfı güçlüden koruyan kurnaz adil figürdür.', en: 'The phrase "jackal skin" in Anatolia refers to those who cover up truth; but in folk narrative the jackal is also the cunningly just figure that protects the weak from the powerful.' } },
    ],
    myths: [
      { tr: 'Mısır\'da Osiris\'in parçalanmış bedeni toplandığında Anubis, cesedi ilk mumyalayan tanrıdır. Ölümden diriliş mümkündür — ama yalnızca doğru geçiş rehberi eşliğinde. Çakal olmadan ruh çorak çölde kaybolur.', en: 'In Egypt, when the dismembered body of Osiris was gathered, Anubis was the god who performed the first mummification. Resurrection from death is possible — but only in the company of the right guide of passage. Without the jackal the soul is lost in barren desert.' },
      { tr: 'Hint masalında üç çakal bir aslanı kandırarak güçlü olmadan nasıl hayatta kalınacağını öğretir. Sonunda aslan tuzağa düşer, çakallar serbest kalır. Trickster öğretisinin özü: güç değil, farkındalık kazandırır.', en: 'In an Indian tale three jackals trick a lion and teach how to survive without power. In the end the lion falls into the trap and the jackals go free. The essence of trickster teaching: it is not strength but awareness that wins.' },
    ],
  },

  // ─── a066 Ketsal Kuşu ────────────────────────────────────────────────────
  a066: {
    jung: { tr: '"Kutsal Güzellik" ve "Özgür Ruh" arketipi. Ketsal, Jung\'un "Özbenlik" kavramının en görünür kılığıdır — varlığı salt bir tezahür, bir anlık mükemmellik parlaması. Esarette ölür: gerçek öz de baskı altında solar. Özgürlük burada bir hak değil, varoluşun kendisidir.', en: 'The "Sacred Beauty" and "Free Spirit" archetype. The quetzal is the most visible guise of Jung\'s concept of the "Self" — its existence is pure manifestation, a momentary flash of perfection. It dies in captivity: the true self also fades under oppression. Freedom here is not a right — it is existence itself.' },
    dream: { tr: 'Ketsal rüyanda uçuyorsa — ruhun en özgür hali seni çağırıyor, takip et. Kafeste görülüyorsa: hangi konfor alanı seni kısıtlıyor, farkında mısın? Kanatlarını açıp size bakıyorsa: kutsal bir güzelliği görme zamanı, belki de kendin.', en: 'If the quetzal flies in your dream — your soul\'s most liberated state is calling you, follow it. If it appears in a cage: which comfort zone is constraining you, are you aware? If it spreads its wings and looks at you: it is time to see a sacred beauty, perhaps yourself.' },
    shadow: { tr: 'Güzelliği sadece kendisinde görmek — kibir, estetik tiranlık. Öte yanda: güzelliği yaşamaktan korkmak, sıradanlığa saklanmak, kendini dünyaya açmayı reddeden çekingenlik.', en: 'Seeing beauty only in oneself — arrogance, aesthetic tyranny. On the other side: fearing to live beauty, hiding in ordinariness, a timidity that refuses to open oneself to the world.' },
    whenAppears: { tr: 'Yaratıcı ifadeni bastırdığında, özgünlüğünden taviz verdiğinde ya da başkalarının gözünde kaybolmak pahasına da olsa kendin olman gerektiği anda.', en: 'When you suppress your creative expression, when you compromise your authenticity, or at the moment you must be yourself even at the cost of disappearing in the eyes of others.' },
    traditions: [
      { culture: { tr: 'Maya', en: 'Maya' }, meaning: { tr: 'Kukulkan — tüylü yılan tanrısı, ketsal tüyleri ve yılan bedeninden oluşur. Gökle yerin, özgürlükle gücün birleşimi.', en: 'Kukulcan — the feathered serpent deity, composed of quetzal feathers and a serpent body. The union of sky and earth, of freedom and power.' } },
      { culture: { tr: 'Aztek', en: 'Aztec' }, meaning: { tr: 'Quetzalcoatl — tüylü yılan. Ketsal tüyleri yalnızca tanrılar ve kral sınıfına aitti; kuşu öldürmek ölümle cezalandırılırdı.', en: 'Quetzalcoatl — the feathered serpent. Quetzal feathers belonged only to the gods and the royal class; killing the bird was punishable by death.' } },
      { culture: { tr: 'Guatemala Yerlileri (Kiche Maya)', en: 'Guatemalan Indigenous (Kiche Maya)' }, meaning: { tr: 'Ketsal, ulusal kuş ve özgürlük simgesi. "Özgür doğarım ya da ölürüm" prensibiyle özdeşleşmiştir; para birimi bile ketsal adını taşır.', en: 'The quetzal is the national bird and symbol of freedom. It is identified with the principle "I am born free or I die"; even the currency bears the name quetzal.' } },
      { culture: { tr: 'Sufi / İslam', en: 'Sufi / Islamic' }, meaning: { tr: 'Anka ve Hüma gibi efsanevi kuşlar Sufi geleneğinde özgür ruhun sembolüdür; ketsal da bu kutsallığı taşır — görülmesi şans, dokunulması kutsanmak demektir.', en: 'Legendary birds like the Phoenix and Huma are symbols of the free spirit in Sufi tradition; the quetzal also carries this sanctity — to see it is luck, to touch it is to be blessed.' } },
      { culture: { tr: 'Anadolu / Alevi-Bektaşi', en: 'Anatolian / Alevi-Bektashi' }, meaning: { tr: 'Hüma kuşu — Anadolu\'da özgürlüğün ve kutsal güzelliğin simgesi. Gölgesi üzerine düşen kişi sultan olur. Ketsal\'ın Anadolu yankısı.', en: 'The Huma bird — symbol of freedom and sacred beauty in Anatolia. Whoever its shadow falls upon becomes a sultan. The Anatolian echo of the quetzal.' } },
    ],
    myths: [
      { tr: 'Maya efsanesine göre savaşçı Tecun Uman İspanyol fatihi Alvarado\'ya karşı savaşırken ketsal onun saç süsüydü. Savaşçı öldüğünde ketsal göğsüne kondu ve kırmızıya boyandı — o günden beri ketsal\'ın göğsü kırmızıdır, özgürlük şehitlerinin kanıyla.', en: 'According to Maya legend, when the warrior Tecun Uman fought the Spanish conquistador Alvarado, the quetzal was his headdress. When the warrior died the quetzal alighted on his chest and was stained red — since that day the quetzal\'s breast has been red, with the blood of martyrs of freedom.' },
      { tr: 'Aztek mitinde Quetzalcoatl\'ın yaratılış anında ketsal tüylerinden dünyanın ilk insanları yapılmıştır. Güzellik ve özgürlük, insanın en köklü özüdür — kaybedildiğinde insan olmaktan çıkılır.', en: 'In Aztec myth, at the moment of Quetzalcoatl\'s creation, the world\'s first humans were fashioned from quetzal feathers. Beauty and freedom are the most fundamental essence of the human being — when lost, one ceases to be human.' },
    ],
  },

  // ─── a067 Maymun ────────────────────────────────────────────────────────
  a067: {
    jung: { tr: '"Oyuncu Zihin" ve "Yaratıcı Zekâ" arketipi. Maymun, Jung\'un "trickster" ve "puer aeternus" figürlerinin birleşimidir — sonsuz merak, sonsuz enerji, ancak odak sorunu. Evrimsel olarak en yakın akrabamız olduğu için maymunda aynı zamanda kendi hayvani doğamızın aynasını görürüz: ne kadar insanız, ne kadar içgüdüsel.', en: 'The "Playful Mind" and "Creative Intelligence" archetype. The monkey is the union of Jung\'s "trickster" and "puer aeternus" figures — infinite curiosity, infinite energy, but a problem of focus. As our evolutionarily closest relative, in the monkey we also see the mirror of our own animal nature: how human we are, how instinctual.' },
    dream: { tr: 'Maymun rüyanda sıçrayıp duruyorsa — zihnin bir yerden bir yere atlamasını durduramıyorsun, meditasyon yardımcı olur. Seninle oynuyorsa: yaratıcılığını özgürce ifade et, bu dönem bunun için. Aynaya bakıyorsa: kendini daha derin gör, yüzeyselliğin ötesine geç.', en: 'If the monkey keeps leaping in a dream — you cannot stop your mind jumping from place to place, meditation would help. If it plays with you: express your creativity freely, this period is for that. If it looks in a mirror: see yourself more deeply, move beyond the surface.' },
    shadow: { tr: 'Dağıtıcı zekâ — her şeyle ilgilenen ama hiçbirini tamamlamayan, sabırsız, dikkat süresi kısa bir zihin. Öte yanda: zekâyı manipülasyon için kullanmak, başkalarını küçümsemek ve alaycı üstünlük.', en: 'Dispersive intelligence — a mind interested in everything but completing nothing, impatient, with a short attention span. On the other side: using intelligence for manipulation, belittling others, and sarcastic superiority.' },
    whenAppears: { tr: 'Yaratıcı bir projeye başlarken, zihni sakinleştirmenin gereği ortaya çıktığında ya da oyundan ve eğlenceden hayatı uzaklaştırdığın dönemlerde.', en: 'When beginning a creative project, when the need to calm the mind arises, or in periods when you have driven play and joy away from life.' },
    traditions: [
      { culture: { tr: 'Hint / Hindu', en: 'Indian / Hindu' }, meaning: { tr: 'Hanuman — rüzgar tanrısının oğlu, sonsuz güç ve bağlılığın maymun tanrısı. Rama\'ya olan sevgisi, onu tanrısal güce kavuşturur.', en: 'Hanuman — son of the wind god, the monkey deity of infinite strength and devotion. His love for Rama elevates him to divine power.' } },
      { culture: { tr: 'Çin / Budizm', en: 'Chinese / Buddhism' }, meaning: { tr: 'Sun Wukong — Taş Maymun. Kendi kendine doğan, ölümsüzlük kazanan ve cennet ordusuyla savaşan trickster kahraman. Ego\'nun yolculuğu.', en: 'Sun Wukong — the Monkey King. A trickster hero born of stone, who wins immortality and battles the armies of heaven. The journey of the ego.' } },
      { culture: { tr: 'Maya', en: 'Maya' }, meaning: { tr: 'Hunahpu — Maya ikiz kahramanlarından biri maymuna dönüştürülür. Yaratıcılık ve sanat tanrısı olur. Dönüşüm bilgeliği taşır.', en: 'Hunahpu — one of the Maya twin heroes is transformed into a monkey. He becomes a deity of creativity and art. He carries the wisdom of transformation.' } },
      { culture: { tr: 'Afrika / Yoruba', en: 'African / Yoruba' }, meaning: { tr: 'Maymun figürü bilgeliğin naif ama derin taşıyıcısıdır; öğretileri doğrudan değil, göstererek anlatır.', en: 'The monkey figure is the naive but profound carrier of wisdom; it teaches not directly but by showing.' } },
      { culture: { tr: 'Anadolu / Osmanlı Minyatürü', en: 'Anatolian / Ottoman Miniature' }, meaning: { tr: 'Osmanlı minyatürlerinde maymun zaman zaman insanın karikatürü olarak çizilir — toplumsal eleştirinin zarif kılığı.', en: 'In Ottoman miniatures the monkey is sometimes drawn as a caricature of the human — the elegant guise of social criticism.' } },
    ],
    myths: [
      { tr: 'Ramayana\'da Hanuman Sita\'yı aramak için Lanka\'ya geçer. Okyanusu tek sıçramada aşar — çünkü gerçek inanç, fiziksel sınırları aşar. Maymunun zekâsı ile kalbin bağlılığı birleşince mucize doğar.', en: 'In the Ramayana, Hanuman crosses to Lanka to seek Sita. He leaps across the ocean in a single bound — because true faith transcends physical limits. When the monkey\'s intelligence unites with the heart\'s devotion, miracle is born.' },
      { tr: 'Çin\'de Taş Maymun\'un Batı\'ya Yolculuğu destanında Sun Wukong Buda\'nın elinden kaçamayacağını anlar. Kendi gücünün sınırını öğrenmek, gerçek zekânın başlangıcıdır. Tüm bilgelik yolculukları bir gurur sınavıyla başlar.', en: 'In China\'s "Journey to the West" epic, Sun Wukong learns that he cannot escape the hand of the Buddha. Learning the limits of one\'s own power is the beginning of true intelligence. All journeys of wisdom begin with a test of pride.' },
    ],
  },

  // ─── a068 Papağan ────────────────────────────────────────────────────────
  a068: {
    jung: { tr: '"İletişim Aynası" ve "Öğretici Ses" arketipi. Papağan, Jung\'un persona kavramıyla derin bir ilişki içindedir — duyduğunu yansıtır, ama bu yansıtma bazen gerçeği ortaya çıkarır. Hafıza ve ses, bilincin en kadim araçlarıdır; papağan bu araçları sahiplenerek ritüel bir öğretici olur.', en: 'The "Communication Mirror" and "Teaching Voice" archetype. The parrot bears a deep relationship with Jung\'s concept of the persona — it reflects what it hears, but that reflection sometimes reveals truth. Memory and voice are the most ancient instruments of consciousness; the parrot, by claiming these instruments, becomes a ritual teacher.' },
    dream: { tr: 'Papağan rüyanda senin sözlerini tekrarlıyorsa — söylediklerini duyuyor musun, gerçekten? Konuşamıyorsa ya da susmuyorsa: iletişim kanallarında bir tıkanma var. Renkli tüylerini sergiliyorsa: yaratıcı ifadenin zamanı geldi, sesini duyur.', en: 'If the parrot in your dream repeats your own words — are you really hearing what you say? If it cannot speak or will not stop: there is a blockage in your communication channels. If it displays its colourful feathers: the time for creative expression has come, make your voice heard.' },
    shadow: { tr: 'Anlam olmadan tekrarlamak — başkalarının fikirlerini özümsemeden aktarmak, sahte bir bilgelik. Öte yanda: sözcükleri silah haline getirmek, gıybet ve dedikodu zinciri, sesin zehre dönüşmesi.', en: 'Repeating without meaning — conveying others\' ideas without absorbing them, a counterfeit wisdom. On the other side: turning words into weapons, a chain of gossip and slander, the voice becoming venom.' },
    whenAppears: { tr: 'İletişim sorunlarının had safhaya ulaştığı ilişkilerde, yaratıcı ifadenin bastırıldığı dönemlerde ya da başkalarının sözlerini mi yoksa kendi sesini mi taşıdığını sorguladığında.', en: 'In relationships where communication problems have reached a peak, in periods when creative expression is suppressed, or when you question whether you carry others\' words or your own voice.' },
    traditions: [
      { culture: { tr: 'Hint / Sanskrit', en: 'Indian / Sanskrit' }, meaning: { tr: 'Shuka — Vişnu\'nun elçisi papağan. Bhagavata Purana\'yı Kral Parikshit\'e aktarır. Kutsal bilginin taşıyıcısı ve öğretici ses.', en: 'Shuka — the parrot messenger of Vishnu. He conveys the Bhagavata Purana to King Parikshit. Bearer of sacred knowledge and teaching voice.' } },
      { culture: { tr: 'İslam / Sufi', en: 'Islamic / Sufi' }, meaning: { tr: 'Rumi\'nin Mesnevi\'sinde papağan aynı şehveti öğreten tacirin metaforu — gerçek özgürlük bilgiyle değil, aşkla kazanılır. Kafes dünya, papağan nefstir.', en: 'In Rumi\'s Masnavi the parrot is the metaphor of the merchant teaching the same desire — true freedom is won not with knowledge but with love. The cage is the world, the parrot is the ego-soul.' } },
      { culture: { tr: 'Amazon Yerlileri', en: 'Amazonian Indigenous' }, meaning: { tr: 'Papağan, bitki dünyasıyla insan arasındaki çevirmendir. Şamanlar papağanın sesini duyarak ormandaki değişimleri okur.', en: 'The parrot is the interpreter between the plant world and humanity. Shamans read changes in the forest by hearing the parrot\'s voice.' } },
      { culture: { tr: 'Yunan / Roma', en: 'Greek / Roman' }, meaning: { tr: 'Psittacus — Alexander\'ın keşifleriyle Yunanistan\'a giren papağan, antik dünyada fal ve kehanet kuşu sayıldı.', en: 'Psittacus — the parrot that entered Greece with Alexander\'s explorations was considered a divination and oracle bird in the ancient world.' } },
      { culture: { tr: 'Anadolu / Osmanlı', en: 'Anatolian / Ottoman' }, meaning: { tr: 'Osmanlı sarayında papağan konuşturmak sanat sayılırdı; divan edebiyatında papağan, aşk haberini taşıyan elçidir.', en: 'In the Ottoman palace, teaching a parrot to speak was considered an art; in divan literature the parrot is the messenger carrying the news of love.' } },
    ],
    myths: [
      { tr: 'Rumi\'nin Mesnevi\'sinde bir tüccarın Hindistan\'a giden arkadaşına papağanı selamlattırmasını ister. Tüccar mesajı iletir; papağanlar yere düşüp ölür. Tüccar eve döner, kendi papağanı da ölü numarası yapar. Sonra uçar gider — özgürlük, ölmesini bilmekten geçer.', en: 'In Rumi\'s Masnavi, a merchant asks a friend traveling to India to greet the parrots on his behalf. The friend delivers the message; the parrots fall and die. The merchant returns home, and his own parrot plays dead. Then it flies away — freedom passes through knowing how to die.' },
      { tr: 'Hint geleneğinde Shuka, anne karnındayken Vişnu\'nun hikâyelerini işitip doğmamayı tercih eder — dünya kirletir. On iki yıl sonra doğar ve tüm kutsal bilgiyi hafızasında taşır. Sesin hafızası, bedenin hafızasından güçlüdür.', en: 'In Indian tradition, Shuka hears the stories of Vishnu while still in the womb and chooses not to be born — the world would corrupt him. After twelve years he is born and carries all sacred knowledge in his memory. The memory of voice is stronger than the memory of the body.' },
    ],
  },

  // ─── a069 Bizon ─────────────────────────────────────────────────────────
  a069: {
    jung: { tr: '"Kutsal Bereket" ve "Topluluk Ruhu" arketipi. Bizon, Jung\'un kolektif bilinçdışında yükselen "Büyük Anne" figürünün en güçlü eril karşılığıdır — toprağın vericiliği, toplulukla paylaşımın kutsallığı. Bireyin toprakla, toplumla ve evrenin cömertliğiyle bütünleşmesini temsil eder.', en: 'The "Sacred Abundance" and "Community Spirit" archetype. The bison is the most powerful masculine counterpart of the "Great Mother" figure rising in Jung\'s collective unconscious — the generosity of the earth, the sanctity of sharing within community. It represents the individual\'s integration with earth, community, and the generosity of the universe.' },
    dream: { tr: 'Bizon rüyanda sürü halinde koşuyorsa — büyük bir güç geliyor, toprak gibi sağlam dur. Tek başınaysa ve sana bakıyorsa: topluluğuna geri dön, yalnızlık bu dönem sana hizmet etmiyor. Seninle birlikte yürüyorsa: doğru yoldasın, minnettarlığı unutma.', en: 'If bison run in a herd in your dream — great power is coming, stand firm as the earth. If it is alone and looks at you: return to your community, solitude does not serve you in this period. If it walks alongside you: you are on the right path, do not forget gratitude.' },
    shadow: { tr: 'Bereket içinde vurdumduymazlık — minnetsiz tüketim, topluluğa katkısız alma. Öte yanda: sürü zihniyeti, bireyin kolektif baskı altında ezilmesi ve kör itaat.', en: 'Indifference within abundance — ungrateful consumption, taking without contributing to the community. On the other side: herd mentality, the individual crushed under collective pressure, and blind obedience.' },
    whenAppears: { tr: 'Minnettarlıktan koptuğun dönemlerde, topluluğunla ilişkinin yeniden kurulması gerektiğinde ya da refahın kaynağını sorguladığında.', en: 'In periods when you have disconnected from gratitude, when your relationship with your community needs to be rebuilt, or when you question the source of your wellbeing.' },
    traditions: [
      { culture: { tr: 'Lakota / Siyu (Kuzey Amerika Yerlileri)', en: 'Lakota / Sioux (Native North American)' }, meaning: { tr: 'Tatanka Oyate — Bizon Halkı. Kutsal Beyaz Bufalo İneği efsanesi: Wakan Tanka\'nın mesajını getiren kutsal kadın, barış pipasını ve yaşam öğretilerini getirir.', en: 'Tatanka Oyate — the Buffalo Nation. The legend of the White Buffalo Calf Woman: the sacred woman who brings Wakan Tanka\'s message, carrying the peace pipe and life teachings.' } },
      { culture: { tr: 'Kuzey Amerika (Blackfoot)', en: 'North American (Blackfoot)' }, meaning: { tr: 'Bizon, kutsal bir antlaşmanın simgesidir — hayvan kendini verir, insan şükranla alır. Bu döngü bozulursa hem hayvan hem insan yok olur.', en: 'The bison is a symbol of a sacred covenant — the animal gives itself, the human receives with gratitude. If this cycle is broken, both animal and human are destroyed.' } },
      { culture: { tr: 'Tibet / Budizm', en: 'Tibetan / Buddhism' }, meaning: { tr: 'Yak (bizonun kutsal akrabası) — Himalaya\'da yaşamı mümkün kılan kutsal varlık. Tanrıların arabasını çektiğine inanılır.', en: 'The yak (the sacred relative of the bison) — the sacred being that makes life possible in the Himalayas. It is believed to pull the chariot of the gods.' } },
      { culture: { tr: 'Anadolu / Neolitik', en: 'Anatolian / Neolithic' }, meaning: { tr: 'Çatalhöyük\'te boğa kafatasları tapınakları süslüyor — toprağın bereketini temsil eden kutsal hayvan imgesi. Bizonun Anadolu kökenli kardeşi.', en: 'At Çatalhöyük, bull skulls adorn shrines — the image of the sacred animal representing the earth\'s abundance. The Anatolian cousin of the bison.' } },
      { culture: { tr: 'Sümer / Mezopotamya', en: 'Sumerian / Mesopotamian' }, meaning: { tr: 'Gugalanna — gökyüzü boğası. Gilgamış destanında yeraltı tanrıçası İnanna\'nın eski eşi. Toprak gücünün kozmik boyutu.', en: 'Gugalanna — the Bull of Heaven. In the Gilgamesh epic, the ancient husband of the underworld goddess Inanna. The cosmic dimension of earthly power.' } },
    ],
    myths: [
      { tr: 'Lakota söylencesinde Kutsal Beyaz Bufalo İneği iki avcıya görünür. Biri açgözlü bakışlarla bakınca toz olup uçar; öteki saygıyla eğilir. Kadın barış piposunu ve minnettarlık öğretilerini getirir. Bereket, saygıyla gelir — açgözlülükle değil.', en: 'In Lakota legend, the White Buffalo Calf Woman appears to two hunters. When one looks at her with greedy eyes he turns to dust; the other bows with reverence. The woman brings the peace pipe and the teachings of gratitude. Abundance comes with respect — not with greed.' },
      { tr: 'Kuzey Amerika düzlüklerinde milyonlarca bizon yaşardı; Yerli halklar her avdan önce dua eder, her parçasını kullanır ve hiçbir şeyi çöpe atmazlardı. Avrupalıların gelişiyle bizonlar soykırıma uğradı — ve halklar açlığa. Topluluk ile doğa arasındaki kutsal sözleşmenin ihlali, her şeyi çökertti.', en: 'Millions of bison once lived on the North American plains; Indigenous peoples prayed before each hunt, used every part, and wasted nothing. With the arrival of Europeans the bison were subjected to genocide — and the peoples to starvation. The violation of the sacred covenant between community and nature collapsed everything.' },
    ],
  },

  // ─── a070 Kanguru ────────────────────────────────────────────────────────
  a070: {
    jung: { tr: '"İleri Atılış" ve "Cesur Sıçrama" arketipi. Kanguru geriye gidemez — anatomisi bunu engeller. Bu biyo-sembolik gerçek, Jung\'un "geleceğe yönelme" ilkesini cisimleştirir: geçmişe dönüş yoktur, yalnızca ileri gidilir. Keseyi — hem korumayı hem de yeni hayatı taşımayı — aynı anda yapabilmek, olgunluğun sembolüdür.', en: 'The "Leap Forward" and "Courageous Bound" archetype. The kangaroo cannot move backward — its anatomy prevents it. This bio-symbolic truth embodies Jung\'s principle of "future-orientation": there is no return to the past, only forward movement. Being able to carry the pouch — both protection and new life — at the same time is a symbol of maturity.' },
    dream: { tr: 'Kanguru rüyanda zıplayıp gidiyorsa — geçmişe bakma, hareket et. Kesesinde yavru taşıyorsa: hem kendi hayatını hem de bir başkasının (fikir, proje, çocuk) hayatını koruyorsun. Saldırıyorsa: atılmaktan kaçındığın o karar artık seni zoruyor.', en: 'If the kangaroo leaps away in a dream — do not look back, move. If it carries a joey in its pouch: you are protecting both your own life and another\'s (an idea, a project, a child). If it attacks: that decision you have been avoiding leaping into is now pressing you.' },
    shadow: { tr: 'Sürekli sıçramak — bir şeyden diğerine geçerek hiçbirini tamamlamamak, sabırsızlık. Öte yanda: ilerlemenin zorluğu karşısında donmak, geriye gidemezken önüne de adım atamamak — varoluşsal felç.', en: 'Constantly leaping — passing from one thing to another without completing any of them, impatience. On the other side: freezing before the difficulty of progress, unable to move backward yet unable to step forward either — existential paralysis.' },
    whenAppears: { tr: 'Büyük bir değişimin eşiğinde, geçmişe bağlılığın ilerlemeni engellediği dönemde ya da hem kendin hem de bir şeyi (proje, çocuk, vizyon) taşıma sorumluluğunu üstlendiğinde.', en: 'On the threshold of a major change, in a period when attachment to the past is blocking your progress, or when you take on the responsibility of carrying both yourself and something else (a project, a child, a vision).' },
    traditions: [
      { culture: { tr: 'Avustralya Yerlileri / Aborijin', en: 'Australian Aboriginal' }, meaning: { tr: 'Kanguru, Rüya Zamanı\'nın (Dreamtime) kutsal yaratığıdır. Totem olarak onun enerjisini taşıyan klan, ileri görüşlülük ve aile koruyuculuğuyla anılır.', en: 'The kangaroo is a sacred creature of the Dreamtime. The clan that carries its energy as totem is known for foresight and protection of the family.' } },
      { culture: { tr: 'Aborijin (Batı Avustralya)', en: 'Aboriginal (Western Australia)' }, meaning: { tr: 'Kanguru derisi, törensel giysilerin en değerlisi sayılırdı. Dansçılar kanguru hareketlerini taklit ederek bereket ve ileri atılış ruhunu çağırırdı.', en: 'Kangaroo skin was considered the most precious of ceremonial garments. Dancers imitated kangaroo movements to invoke the spirit of abundance and forward momentum.' } },
      { culture: { tr: 'Avustralya (Aranda / Arrernte)', en: 'Australian (Aranda / Arrernte)' }, meaning: { tr: 'Kanguru Atası Rüya Zamanı\'nda yeryüzünü şekillendirmiştir; izlediği yollar kutsal toprak hatlarını (songlines) oluşturur.', en: 'The Kangaroo Ancestor shaped the earth during Dreamtime; the paths it travelled form the sacred land lines (songlines).' } },
      { culture: { tr: 'Çağdaş / Evrensel Sembol', en: 'Contemporary / Universal Symbol' }, meaning: { tr: 'Avustralya armasındaki kanguru — sadece ileri gidebilen hayvan. Ulusun "daima ileriye" felsefesinin simgesi.', en: 'The kangaroo on the Australian coat of arms — an animal that can only move forward. Symbol of the nation\'s philosophy of "always forward".' } },
      { culture: { tr: 'Anadolu / Halk Söylemi', en: 'Anatolian / Folk Saying' }, meaning: { tr: '"Geriye dönme, will" deyiminin cisimleşmiş hali — kanguru Anadolu\'da tanınmasa da ileri atılış cesareti "yiğit" kavramıyla örtüşür.', en: 'The embodied form of the saying "do not look back" — though the kangaroo is not native to Anatolia, the courage of leaping forward aligns with the concept of "yiğit" (the valiant).' } },
    ],
    myths: [
      { tr: 'Aborijin Rüya Zamanı\'nda Büyük Kanguru Atası kıtanın dört bir yanını zıplayarak geçti ve her ayak basışında bir nehir, her duruşunda bir dağ oluştu. Yolculuk bitmedi — hâlâ devam ediyor. Kanguru totemini taşıyan ruh bu sonsuz yolculuğun bir parçasıdır.', en: 'In the Aboriginal Dreamtime, the Great Kangaroo Ancestor leapt across the continent in every direction, and at each footfall a river formed, at each pause a mountain rose. The journey did not end — it continues still. The soul that carries the kangaroo totem is part of this endless journey.' },
      { tr: 'Arrernte söylencesinde kanguru, tanrıların çocuklara verdiği hediyeyi kesesinde taşıdı. Yıllarca zıpladı, bıkmadı, teslim olmadı. Kese her sarsıntıda sıkılaştı ama yavru zarar görmedi. Korumak ile ilerlemek — birbirini engellemez, birbirini tamamlar.', en: 'In Arrernte legend the kangaroo carried the gift the gods gave to the children in its pouch. For years it leapt, never tired, never surrendered. The pouch tightened with every jolt but the joey was unharmed. Protecting and moving forward — they do not hinder each other, they complete each other.' },
    ],
  },

  // ─── a071 Ren Geyiği ────────────────────────────────────────────────────
  a071: {
    jung: { tr: '"Şaman Yolcusu" arketipi. İki dünya arasında köprü kuran, görünür ile görünmez arasında gezinen bilinç. Ren Geyiği antleri gök ile yeri birleştirir — bu enerji, sıradan yaşamı kutsal bir yolculuğa dönüştürme çağrısıdır.', en: 'The "Shaman Traveler" archetype. A consciousness that bridges two worlds, wandering between the visible and the invisible. The reindeer\'s antlers join sky to earth — this energy is a call to transform ordinary life into a sacred journey.' },
    dream: { tr: 'Ren Geyiği rüyada — atalar seni çağırıyor, köklere dön. Karlı bir ormanda yürüyorsa: zorlu bir yolu yalnız ama rehberli geçiyorsun. Seninle konuşuyorsa: bilinçdışından gelen mesaj yakın, susarak dinle.', en: 'Reindeer in dream — the ancestors call you, return to your roots. If it walks through a snowy forest: you are crossing a difficult path alone but guided. If it speaks to you: a message from the unconscious is near, listen in silence.' },
    shadow: { tr: 'Sürekli öteki dünyalara kaçış, buradaki sorumluluklardan ruhsallık kisvesi altında sıyrılma. Köksüzlük ve aşiret bağlarının ihmal edilmesi — rehber olmak için önce yerde durabilmek gerekir.', en: 'Constant escape into other realms, evading responsibilities here under the guise of spirituality. Rootlessness and neglect of ancestral bonds — to be a guide, one must first be able to stand on the ground.' },
    whenAppears: { tr: 'Aile ve köken sorularının yoğunlaştığı dönemlerde, şamanik ya da spiritüel bir çağrı hissedildiğinde, uzun bir yolculuğun eşiğinde.', en: 'During periods when questions of family and origin intensify, when a shamanic or spiritual calling is felt, on the threshold of a long journey.' },
    traditions: [
      { culture: { tr: 'Sibirya Şamanizmi', en: 'Siberian Shamanism' }, meaning: { tr: 'Ren Geyiği şamanın ruhu olarak kabul edilir; kurban ritüellerinde şamanı öteki dünyaya taşıyan kutsal araçtır.', en: 'Reindeer is regarded as the shaman\'s spirit; in sacrifice rituals it is the sacred vehicle that carries the shaman to the other world.' } },
      { culture: { tr: 'Sami (İskandinav) Geleneği', en: 'Sámi (Scandinavian) Tradition' }, meaning: { tr: 'Ren sürüleri kutsal yaşamın merkezi sayılır; geyiğin yönü kehanet için okunur, her hayvanın bir ruhu olduğuna inanılır.', en: 'Reindeer herds are considered the centre of sacred life; the animal\'s direction is read for divination, and every reindeer is believed to have a spirit.' } },
      { culture: { tr: 'Kuzey Amerika Yerli Gelenekleri', en: 'North American Indigenous Traditions' }, meaning: { tr: 'Caribou — Büyük Yolculuğun sembolü. Göç eden sürüler mevsimin döngüsünü ve yaşamın devamlılığını temsil eder.', en: 'Caribou — symbol of the Great Journey. The migrating herds represent the cycle of seasons and the continuity of life.' } },
      { culture: { tr: 'Moğol Geleneği', en: 'Mongolian Tradition' }, meaning: { tr: 'Gök Geyiği, Tengri\'nin habercisidir; antleri yıldız haritasına benzetilir ve kozmik düzeni simgeler.', en: 'The Celestial Deer is the messenger of Tengri; its antlers are likened to a star map and symbolize the cosmic order.' } },
      { culture: { tr: 'Fin-Ugor Mitolojisi', en: 'Finno-Ugric Mythology' }, meaning: { tr: 'Ilmatar\'ın geyiği ölüm ile yaşam arasındaki sınırı korur; şamanlar onu çağırarak ruh yolculuğuna çıkar.', en: 'The deer of Ilmatar guards the boundary between death and life; shamans call upon it to embark on soul journeys.' } },
    ],
    myths: [
      { tr: 'Sibirya\'nın Evenk halkı anlatır: Zamanın başında Büyük Geyiği, güneşi her sabah boynuzlarıyla gökyüzüne taşırdı. Bir gün avcı onu vurdu — güneş düştü. Şaman, geyiğin ruhunu bulup özür diledi; geyik güneşi yerine koydu. O günden beri şamanlar "güneşi geri getiren insanlar" olarak anılır.', en: 'The Evenk people of Siberia tell: at the beginning of time, the Great Reindeer carried the sun into the sky each morning on its antlers. One day a hunter shot it — the sun fell. The shaman found the reindeer\'s spirit and asked forgiveness; the reindeer restored the sun. Since then shamans are known as "the people who bring back the sun".' },
      { tr: 'Sami geleneğinde, beyaz bir ren geyiği görülmesi ataların mesaj gönderdiğinin işaretidir. O geyiği takip eden kişi, yaşayanlar ile ölüler arasındaki nehre ulaşır; orada bir soru sormak için tek bir nefes hakkı vardır.', en: 'In Sámi tradition, seeing a white reindeer is a sign that the ancestors are sending a message. The person who follows that reindeer reaches the river between the living and the dead; there one has the right to ask a single question in a single breath.' },
    ],
  },

  // ─── a072 Kirpi ─────────────────────────────────────────────────────────
  a072: {
    jung: { tr: '"İçe Dönük Bilge" arketipi. Dışarıya diken gösteren ama içi yumuşak olan bu varlık, savunma ile kırılganlığın bir arada yaşayabileceğini öğretir. Kirpi enerjisi, sınır koymanın şiddete değil, özün korunmasına hizmet ettiğini hatırlatır.', en: 'The "Introverted Sage" archetype. This creature that shows spines outward but is soft within teaches that defense and vulnerability can coexist. Hedgehog energy reminds us that boundary-setting serves not violence but the protection of the core.' },
    dream: { tr: 'Kirpi rüyada — korunmaya ihtiyacın var, ama dikenlerin seni de hapsediyor olabilir. Diken açıyorsa: bir tehdit hissediyorsun, gerçek mi değerlendirmelisin. Top olmuş yatıyorsa: içine çekilmek seni güvende tutmuyor, açılma zamanı.', en: 'Hedgehog in dream — you need protection, but your spines may be imprisoning you too. If it raises its spines: you sense a threat, ask whether it is real. If it lies curled up: withdrawing into yourself is not keeping you safe, it is time to open up.' },
    shadow: { tr: 'Aşırı savunmacılık ve güvensizliğin kronikleşmesi. Her yakınlaşmada diken açmak, sevgiyi bile tehdit olarak algılamak — kirpi enerjisinin gölgesi, kalıcı yalnızlığa ve duygusal donukluğa yol açar.', en: 'Excessive defensiveness and the chronic calcification of distrust. Raising spines at every approach, perceiving even love as a threat — the shadow of hedgehog energy leads to permanent isolation and emotional numbness.' },
    whenAppears: { tr: 'Duygusal yaralanma sonrası kapanma dönemlerinde, sınırları öğrenme ya da sınırları çözme sürecinde, uzun bir içe dönüklüğün ardından dünyaya adım atma eşiğinde.', en: 'During periods of withdrawal after emotional wounding, in the process of learning or dissolving boundaries, on the threshold of stepping back into the world after long introversion.' },
    traditions: [
      { culture: { tr: 'Anadolu Halk Geleneği', en: 'Anatolian Folk Tradition' }, meaning: { tr: 'Kirpi, "dağın akıllısı" olarak bilinir; tıbbi bitkileri bulduğuna, yaralı insanlara gece yol gösterdiğine inanılır.', en: 'The hedgehog is known as "the wise one of the mountain"; it is believed to find medicinal plants and guide wounded people at night.' } },
      { culture: { tr: 'Mısır Mitolojisi', en: 'Egyptian Mythology' }, meaning: { tr: 'Kirpi, ölüm ve yeniden doğuşun sembolüdür; lahit kaplarına kazınmış betimlemeler ruhun korunmasına adanmıştır.', en: 'The hedgehog is a symbol of death and rebirth; depictions carved on canopic jars are dedicated to the protection of the soul.' } },
      { culture: { tr: 'İran-Zerdüşt Geleneği', en: 'Iranian-Zoroastrian Tradition' }, meaning: { tr: 'Avesta\'da kirpi kutsal sayılır; Ehriman\'ın yaratıklarına karşı dünyanın savunucusu olarak betimlenmiştir.', en: 'In the Avesta the hedgehog is considered sacred; it is described as a defender of the world against the creatures of Ahriman.' } },
      { culture: { tr: 'Kelt Geleneği', en: 'Celtic Tradition' }, meaning: { tr: 'Kirpi, yer altının habercisidir; toprağın sırlarını bilen, geceleri büyü alanlarında dolaşan varlık olarak anılır.', en: 'The hedgehog is the herald of the underworld; it is mentioned as a being that knows the secrets of the earth and wanders the magical fields at night.' } },
      { culture: { tr: 'Afrika (Hausa) Geleneği', en: 'African (Hausa) Tradition' }, meaning: { tr: 'Kirpi hikayelerde zekâ ve hayatta kalma ustasıdır; büyük hayvanları kurnazlıkla alt eden küçük ama yenilmez kahraman.', en: 'In Hausa stories the hedgehog is a master of intelligence and survival; the small but invincible hero who outwits great animals through cunning.' } },
    ],
    myths: [
      { tr: 'Eski Mısır\'da anlatılır: Kirpi, Ra\'nın güneş kayığına her gece binen ve sabah güneşin yeniden doğmasını sağlayan koruyucuydu. Dikenleri karanlığın oklarını geri yansıtır, yumuşak karnı ise sabahın ışığını taşır.', en: 'As told in ancient Egypt: the hedgehog was the guardian who boarded Ra\'s solar boat each night and ensured the sun was reborn each morning. Its spines reflect the arrows of darkness back, while its soft belly carries the light of dawn.' },
      { tr: 'Anadolu\'da anlatılan bir masalda kirpi, padişahın bahçesinden meyve çalan bir hırsızı fark eder. Padişaha söylemek için saraya gider ama kimse onu dikkate almaz. Kirpi, hırsızı kendi başına dikenlerine takarak tutar — o günden beri "küçük ama söz dinletebilen" olarak saygı görür.', en: 'In an Anatolian tale, the hedgehog notices a thief stealing fruit from the sultan\'s garden. It goes to the palace to tell the sultan, but no one heeds it. The hedgehog catches the thief alone by snagging him on its spines — from that day it is respected as "small but able to make itself heard".' },
    ],
  },

  // ─── a073 Kertenkele ─────────────────────────────────────────────────────
  a073: {
    jung: { tr: '"Rüya Görücü" arketipi. Kertenkele güneşte hareketsiz beklerken bile içi kaynar — bu enerji, görünür eylemsizlik içinde yoğun iç işlem gücünü simgeler. Bilinçdışının mesajlarını yakalamak için önce ısınmak, yani hazırlanmak gerekir.', en: 'The "Dreamer" archetype. While the lizard waits motionless in the sun its interior seethes — this energy symbolises intense inner processing within apparent stillness. To catch the messages of the unconscious, one must first warm up, that is, prepare.' },
    dream: { tr: 'Kertenkele rüyada — hızlı bir karar gerekiyor ya da hızla geri çekilmek gerekiyor. Kuyruğunu bırakıyorsa: bir parçandan vazgeç, hayatta kalmak daha önemli. Güneşte yatıyorsa: enerjini yenilemeden harekete geçme.', en: 'Lizard in dream — a swift decision is needed, or a swift retreat. If it drops its tail: let go of a part of yourself, survival matters more. If it basks in the sun: do not act before renewing your energy.' },
    shadow: { tr: 'Adaptasyonun yüzeyselleşmesi — her ortama uyum sağlayan ama hiçbirine kök atmayan kaypak kişilik. Isı peşinde koşmak, yani onay ve ilgi bağımlılığı da kertenkelenin gölgesidir.', en: 'Adaptation becoming superficial — the slippery personality that adjusts to every environment but takes root in none. Chasing warmth, meaning addiction to approval and attention, is also the shadow of the lizard.' },
    whenAppears: { tr: 'Hızlı değişen koşullarda esneklik çağrısı geldiğinde, rüyalardan gelen sinyallerin güçlendiği dönemlerde, güneşe ve yaşam enerjisine yeniden bağlanma ihtiyacında.', en: 'When the call for flexibility arises in rapidly changing conditions, during periods when signals from dreams intensify, in the need to reconnect with the sun and life energy.' },
    traditions: [
      { culture: { tr: 'Aborijin (Avustralya)', en: 'Aboriginal (Australian)' }, meaning: { tr: 'Gökkuşağı kertenkele, Rüya Zamanı\'nın koruyucusudur; toprağın altındaki su damarlarını bildiği için kurak mevsimlerde rehber kabul edilir.', en: 'The rainbow lizard is the guardian of Dreamtime; knowing the water veins beneath the earth, it is considered a guide in dry seasons.' } },
      { culture: { tr: 'Mısır Mitolojisi', en: 'Egyptian Mythology' }, meaning: { tr: 'Kertenkele hiyerogliflerinde "bol olan" anlamına gelir; bereket ve güneş ışığının taşıyıcısı olarak kapılara kazınmıştır.', en: 'In Egyptian hieroglyphs the lizard means "that which is abundant"; it is carved on doorways as a bearer of fertility and sunlight.' } },
      { culture: { tr: 'Aztek Geleneği', en: 'Aztec Tradition' }, meaning: { tr: 'Cipactli — deniz canavarı kertenkele — dünyanın yaratıldığı ilk varlıktır; hem kaos hem zemin, hem yıkım hem temel.', en: 'Cipactli — the sea-monster lizard — is the first being from which the world was created; both chaos and ground, both destruction and foundation.' } },
      { culture: { tr: 'Yunan-Roma Geleneği', en: 'Greco-Roman Tradition' }, meaning: { tr: 'Kertenkele Apollon\'un kutsal hayvanıdır; güneş tanrısının yanında uyuyarak kehanet rüyaları gördüğüne inanılır.', en: 'The lizard is the sacred animal of Apollo; it is believed to sleep beside the sun god and receive prophetic dreams.' } },
      { culture: { tr: 'Güney Afrika Zulu Geleneği', en: 'South African Zulu Tradition' }, meaning: { tr: 'Kertenkele, atalardan gelen mesajları yaşayanlara ileten ruh habercisidir; evin içine girerse şans, dışarı çıkarılırsa keder getirir.', en: 'The lizard is a spirit messenger conveying ancestral messages to the living; if it enters the house it brings luck, if driven out it brings sorrow.' } },
    ],
    myths: [
      { tr: 'Navajo geleneğinde anlatılır: Yaratılışın başında kertenkele, güneşin nasıl tutulacağını bilmeyen insanlara öğretti. "Önce onu gözlemle, sonra onunla otur, sonra ondan öğren" dedi. Bu yüzden Navajo şamanları hâlâ kertenkele pozisyonunda — yere uzanarak, güneşe dönerek — rüya alırlar.', en: 'As told in Navajo tradition: at the beginning of creation, the lizard taught humans who did not know how to receive the sun. "First observe it, then sit with it, then learn from it," it said. That is why Navajo shamans still receive dreams in the lizard position — lying on the ground, turned toward the sun.' },
      { tr: 'Eski Yunan\'da Apollon\'un tapınağında yaşayan bir kertenkele vardı. Tapınağa giren herkes ona bir soru sorardı; kertenkele uyursa "evet", kaçarsa "henüz değil" anlamına gelirdi. Delphi kahininden önce, kertenkele insanlığın ilk kehanet aracıydı.', en: 'In ancient Greece there lived a lizard in Apollo\'s temple. Everyone who entered the temple would ask it a question; if the lizard slept it meant "yes", if it fled it meant "not yet". Before the oracle of Delphi, the lizard was humanity\'s first tool of divination.' },
    ],
  },

  // ─── a074 Koç ────────────────────────────────────────────────────────────
  a074: {
    jung: { tr: '"İlahi Öncü" arketipi. Kendi başını taşla dövmekten korkmayan lider — bu enerji, dünyayı değiştirmek için önce kendi içinde yıkım-yaratım döngüsünü yaşayan bilinçtir. Koç, ateşten doğar ve ateşe döner; her yeni başlangıç bir yanmayı gerektirir.', en: 'The "Divine Pioneer" archetype. The leader who is not afraid to strike its own head against stone — this energy is a consciousness that lives the cycle of destruction-creation within itself before changing the world. The ram is born of fire and returns to fire; every new beginning requires a burning.' },
    dream: { tr: 'Koç rüyada — ilerleme zamanı, duraksama lüksün yok. Sana koşuyorsa: içindeki güç seni zorluyor, kendi potansiyelinden kaçıyorsun. Başını taşa vuruyorsa: engelin gerçek olmayabilir, sadece ısrar gerektiriyor.', en: 'Ram in dream — it is time to advance, you have no luxury of hesitation. If it charges at you: the power within is pushing you, you are fleeing your own potential. If it butts its head against stone: the obstacle may not be real, it simply requires persistence.' },
    shadow: { tr: 'Düşünmeden öne atılma ve başkalarını ezmek pahasına ilerleme. Koç enerjisinin gölgesi, ego savaşlarına dönüşen liderlik isteğidir — "ben açarım" yerini "ben geçerim" alır ve güç tahakküme kaymaya başlar.', en: 'Rushing forward without thought and advancing at the cost of trampling others. The shadow of ram energy is the desire to lead that turns into ego battles — "I will open the way" is replaced by "I will get past" and power begins to slide into domination.' },
    whenAppears: { tr: 'Yeni bir girişimin başladığı dönemlerde, liderlik rolü üstlenme ya da reddetme krizlerinde, bir kapıyı zorla açmak gerektiği anda.', en: 'During periods when a new venture begins, in crises of taking on or refusing a leadership role, at the moment when a door must be forced open.' },
    traditions: [
      { culture: { tr: 'Mezopotamya', en: 'Mesopotamia' }, meaning: { tr: 'Koç, Ea/Enki\'nin kutsal hayvanıdır; boynuzları yaratıcı bilgeliği, güçlü bedeni ise ilahi iradeyi simgeler.', en: 'The ram is the sacred animal of Ea/Enki; its horns symbolise creative wisdom and its powerful body the divine will.' } },
      { culture: { tr: 'Mısır Mitolojisi', en: 'Egyptian Mythology' }, meaning: { tr: 'Amun, koç başlı tanrı — "gizli olan" anlamına gelir. Yaratıcı güneş enerjisini ve evrensel bereket gücünü taşır.', en: 'Amun, the ram-headed god — means "the hidden one". He carries the creative solar energy and the force of universal abundance.' } },
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology' }, meaning: { tr: 'Altın Post\'un koçu, Aries burcu olarak gökyüzüne yerleştirilmiştir; ilkbaharın ve yeni başlangıçların habercisidir.', en: 'The ram of the Golden Fleece is placed in the sky as the constellation Aries; it is the herald of spring and new beginnings.' } },
      { culture: { tr: 'Anadolu (Hitit)', en: 'Anatolian (Hittite)' }, meaning: { tr: 'Fırtına tanrısı Tarhunna\'nın kurban törenlerinde koç baş tacı takar; bereketin ve ilahi ateşin taşıyıcısıdır.', en: 'In the sacrificial rites of the storm god Tarhunna the ram wears the crown; it is the bearer of fertility and divine fire.' } },
      { culture: { tr: 'İslam Geleneği', en: 'Islamic Tradition' }, meaning: { tr: 'Hz. İbrahim\'in kurban anlatısında koç, teslimiyet ve ilahi merhametin simgesidir; en yüce adanmışlığın ödülü olarak cennetten gönderilmiştir.', en: 'In the narrative of Ibrahim\'s sacrifice the ram is the symbol of submission and divine mercy; sent from paradise as the reward of supreme devotion.' } },
    ],
    myths: [
      { tr: 'Yunan mitolojisinde altın postu olan koç, Helle ile Phrixus\'u zalim üvey annelerinden kurtarmak için Poseidon tarafından gönderildi. Helle yolda denize düştü — Hellespont onun adını taşır. Phrixus\'u Kolkhis\'e götüren koç, gökyüzünde Aries olarak ebedileşti. Kurtuluş, her zaman bir kayıp içerir.', en: 'In Greek mythology the golden-fleeced ram was sent by Poseidon to rescue Helle and Phrixus from their cruel stepmother. Helle fell into the sea along the way — the Hellespont bears her name. The ram that carried Phrixus to Colchis was immortalised in the sky as Aries. Salvation always contains a loss.' },
      { tr: 'Türk-Moğol geleneklerinde anlatılır: Gökyüzünün ilk ışığı, bir koçun alnından çıkan aleve benzetilir. Bu yüzden güneşin doğduğu yön "koç yönü" olarak bilinir ve yeni kurulan çadırın kapısı o tarafa açılır.', en: 'As told in Turkic-Mongol traditions: the first light of the sky is likened to the flame that leaps from a ram\'s forehead. That is why the direction from which the sun rises is known as "the direction of the ram" and the door of a newly erected tent opens toward that quarter.' },
    ],
  },

  // ─── a075 Koi Balığı ─────────────────────────────────────────────────────
  a075: {
    jung: { tr: '"Azimli Dönüşümcü" arketipi. Koi, akıntıya karşı yüzer — bu enerji, zorluğu başarısızlığın değil büyümenin işareti olarak okuyan bilinçtir. Su içinde ateş gibi parlar; dönüşümün enerjisi ne elemental sınıra ne de zamana boyun eğer.', en: 'The "Resolute Transformer" archetype. The koi swims against the current — this energy is a consciousness that reads difficulty as a sign not of failure but of growth. It glitters like fire within water; the energy of transformation bows neither to elemental boundaries nor to time.' },
    dream: { tr: 'Koi rüyada — azmin ödüllendirileceği bir süreçtesin, bırakma. Suyun tersine yüzüyorsa: direniş doğru yoldasın demek, pes etme. Altın rengi parlıyorsa: bereket ve kabul kapıdadır, hazır ol.', en: 'Koi in dream — you are in a process where persistence will be rewarded, do not give up. If it swims against the current: resistance means you are on the right path, do not surrender. If its golden colour gleams: abundance and acceptance are at the door, be ready.' },
    shadow: { tr: 'İnatçılığın körü körüne sürdürülmesi, değişmesi gereken bir şeye tutunmak. Koi enerjisinin gölgesi, akıntıya direncin ne zaman bilgelik ne zaman ego olduğunu ayırt edememektir.', en: 'Persisting blindly in stubbornness, clinging to something that needs to change. The shadow of koi energy is the inability to discern when resistance to the current is wisdom and when it is ego.' },
    whenAppears: { tr: 'Uzun süredir çalışılan bir hedefin sonuçlanmadığı dönemlerde, vazgeçme ile sebat arasındaki kararda, bereket ve büyüme için sabır gerektiren eşiklerde.', en: 'During periods when a long-pursued goal has not yet borne fruit, at the decision between giving up and persisting, on thresholds that require patience for abundance and growth.' },
    traditions: [
      { culture: { tr: 'Çin Geleneği', en: 'Chinese Tradition' }, meaning: { tr: 'Koi — "li yu" — Sarı Nehir\'in şelalelerini aşan balık ejderhaya dönüşür; bu mit akademik başarının ve mesleki yükselişin sembolüdür.', en: 'Koi — "li yu" — the fish that surmounts the falls of the Yellow River transforms into a dragon; this myth is the symbol of academic success and professional advancement.' } },
      { culture: { tr: 'Japon Geleneği', en: 'Japanese Tradition' }, meaning: { tr: 'Koi, "nishikigoi" — samuray cesaretinin simgesi. Yakalandığında oltayı kesmez, kılıç darbesi bekler — bu soğukkanlılık erdem sayılır.', en: 'Koi, "nishikigoi" — symbol of samurai courage. When caught it does not thrash, it awaits the sword stroke — this composure is considered a virtue.' } },
      { culture: { tr: 'Kore Geleneği', en: 'Korean Tradition' }, meaning: { tr: 'Koi, han ile hüznü aşan ruhun simgesidir; uzun ömür ve ata bağlılığı için havuzlarda kutsal kabul edilir.', en: 'Koi is the symbol of the spirit that transcends han and sorrow; it is regarded as sacred in ponds for longevity and ancestral devotion.' } },
      { culture: { tr: 'Feng Shui Geleneği', en: 'Feng Shui Tradition' }, meaning: { tr: 'Dokuz koi, bolluğun zirvesidir; dokuz "nian nian you yu" — "her yıl artık" demektir. Havuzun yönü ve balık sayısı enerji akışını belirler.', en: 'Nine koi represent the peak of abundance; nine "nian nian you yu" means "ever more each year". The direction of the pond and the number of fish determine the flow of energy.' } },
      { culture: { tr: 'Budist Gelenek', en: 'Buddhist Tradition' }, meaning: { tr: 'Koi, acıdan özgürleşen ruhun simgesidir; suyun içinde özgürce yüzmek, saṃsāra\'nın akıntısına kapılmadan var olmaktır.', en: 'Koi is the symbol of the soul freed from suffering; to swim freely within the water is to exist without being swept away by the current of saṃsāra.' } },
    ],
    myths: [
      { tr: 'Çin\'in en ünlü efsanelerinden biri: Sarı Nehir\'in yukarısında, ejderha kapısı denen çağlayanlar vardır. Her bahar pek çok koi bu çağlayanları aşmaya çalışır; çoğu döner, geri çekilir. Ama her bin yılda bir, bir koi aşar. O an gökler açılır, ejderha kapısından geçen balık altın ejderhaya dönüşür ve gökyüzüne çıkar. Bu yüzden "kapıyı aşan balık" ifadesi Çincede büyük bir başarının simgesidir.', en: 'One of China\'s most celebrated legends: above the Yellow River there are rapids called the Dragon Gate. Each spring many koi attempt to ascend these rapids; most turn back, retreat. But once every thousand years, one koi succeeds. At that moment the heavens open, the fish that passes through the dragon gate transforms into a golden dragon and rises into the sky. That is why the expression "the fish that passes the gate" is in Chinese a symbol of great achievement.' },
      { tr: 'Japon anlatısında, bir samuray ölmeden önce havuzundaki en yaşlı koi\'ye son dileğini fısıldar. Koi bir kez kuyruğunu çarpar ve dalar — samurayın ailesi, o gece koi\'nin rüyalarında samurayın sesini duyar. Koi, iki dünya arasında mesaj taşıyan suya gömülü bir ruh postasıdır.', en: 'In a Japanese tale, before a samurai dies he whispers his last wish to the oldest koi in his pond. The koi slaps its tail once and dives — that night the samurai\'s family hears his voice in their dreams through the koi. The koi is a spiritual postal service embedded in water, carrying messages between two worlds.' },
    ],
  },

  // ─── a076 Bukalemun ──────────────────────────────────────────────────────
  a076: {
    jung: { tr: '"Bağlam Okuyucusu" arketipi. Bukalemun her rengi bilir çünkü hiçbir renge mahkûm değildir — bu enerji, dünyanın çoğulluğunu tehdit olarak değil bilgelik kaynağı olarak kavrayan bilinçtir. Gözler ayrı yönlere bakar, yani her şeyin iki yüzünü aynı anda görmek mümkündür.', en: 'The "Context Reader" archetype. The chameleon knows every colour because it is prisoner to none — this energy is a consciousness that grasps the plurality of the world not as a threat but as a source of wisdom. Its eyes look in separate directions, meaning it is possible to see both sides of everything simultaneously.' },
    dream: { tr: 'Bukalemun rüyada — hangi maskeyi taktığını soruyor. Renk değiştiriyorsa: ortama uyum sağlıyorsun ama kendin neredesin? Sabit duruyorsa: artık saklanmana gerek yok, gerçek rengini gösterme zamanı.', en: 'Chameleon in dream — it is asking which mask you are wearing. If it changes colour: you are adapting to your environment, but where are you yourself? If it stands still: you no longer need to hide, it is time to show your true colour.' },
    shadow: { tr: 'Kendini kaybetme pahasına uyum sağlamak. Bukalemun enerjisinin en derin gölgesi, "gerçek renk" diye bir şeyin kalmadığını hissetmektir — kimlik çözülmesi ve kameleonvari manipülasyon bunun ürünüdür.', en: 'Adapting at the cost of losing oneself. The deepest shadow of chameleon energy is the feeling that there is no such thing as a "true colour" anymore — identity dissolution and chameleonic manipulation are its products.' },
    whenAppears: { tr: 'Yeni bir ortama girişte, birden fazla kimlik arasında sıkışıldığında, gerçek benliğin ile sosyal benliğin arasındaki mesafeyi hissettiğin dönemlerde.', en: 'At entry into a new environment, when caught between multiple identities, during periods when you feel the distance between your true self and your social self.' },
    traditions: [
      { culture: { tr: 'Afrika (Yoruba) Geleneği', en: 'African (Yoruba) Tradition' }, meaning: { tr: 'Bukalemun, Obatala\'nın kutsal hayvanıdır; saflık ve çoğulluğun bir arada var olabileceğini öğretir. Renk değiştirmesi, dünyanın sonsuz katmanlarına tanıklık etmektir.', en: 'The chameleon is the sacred animal of Obatala; it teaches that purity and plurality can coexist. Its colour-changing is a witnessing of the infinite layers of the world.' } },
      { culture: { tr: 'Malagasy (Madagaskar) Geleneği', en: 'Malagasy (Madagascar) Tradition' }, meaning: { tr: 'Bukalemun, atalar ile yaşayanlar arasında habercilir; yavaş yürüyüşü hesaplı olmayı, dört bir yana bakan gözleri ise hiçbir şeyi kaçırmamayı simgeler.', en: 'The chameleon mediates between ancestors and the living; its slow gait symbolises deliberateness, and its eyes looking in all directions symbolise missing nothing.' } },
      { culture: { tr: 'Antik Yunan', en: 'Ancient Greek' }, meaning: { tr: 'Aristoteles bukalemunu renkleri içine çeken değil, kendi içindeki renkleri dışarı vuran bir varlık olarak betimler — bu, öz-yansıtmanın erken bir metaforudur.', en: 'Aristotle describes the chameleon not as a creature that absorbs colours but as one that projects inner colours outward — an early metaphor for self-reflection.' } },
      { culture: { tr: 'Hint Geleneği', en: 'Indian Tradition' }, meaning: { tr: 'Bukalemun, Maya\'nın — yanılsamanın — simgesi olarak Hindu ikonografisinde yer alır; gerçek ile görünen arasındaki perdenin habercisidir.', en: 'The chameleon appears in Hindu iconography as a symbol of Māyā — illusion; it is the herald of the veil between the real and the apparent.' } },
      { culture: { tr: 'Anadolu Halk Anlatısı', en: 'Anatolian Folk Narrative' }, meaning: { tr: 'Halk arasında "yüzü bin türlü" deyimi bukalemundan gelir; hem kötü anlamda (iki yüzlü) hem iyi anlamda (çok boyutlu) kullanılır.', en: 'The popular saying "a thousand faces" derives from the chameleon; it is used both pejoratively (two-faced) and positively (multi-dimensional).' } },
    ],
    myths: [
      { tr: 'Yoruba yaratılış anlatısında, Obatala insanları şekillendirirken bukalemunu gözlemcisi olarak yanına aldı. Bukalemun her insana bakarken renk değiştirdi — kırmızı öfkeyi, beyaz saflığı, yeşil umudu yansıttı. Obatala, "Bu hayvan insanın içini görüyor" dedi ve onu kutsal ilan etti.', en: 'In the Yoruba creation narrative, when Obatala was shaping humans he took the chameleon as his observer. As the chameleon watched each person it changed colour — red reflected anger, white purity, green hope. Obatala said, "This animal sees the interior of humans," and declared it sacred.' },
      { tr: 'Madagaskar\'da anlatılır: Tanrı Zanahary, dünyayı yarattıktan sonra bukalemunu gönderdi — "git, insanlar ölümlü mü olsun ölümsüz mü, anlaşın ve haber ver" dedi. Bukalemun yavaş yürüdü, geç döndü. Tanrı beklemekten usandı ve ölümü zaten koydu. Bukalemunun yavaşlığı, insanlığın ölümlülüğünün nedeni sayılır.', en: 'As told in Madagascar: after creating the world, God Zanahary sent the chameleon — "go, settle whether humans should be mortal or immortal, and bring word." The chameleon walked slowly and returned late. God grew weary of waiting and had already appointed death. The chameleon\'s slowness is considered the reason for human mortality.' },
    ],
  },

  // ─── a077 Porsuk ─────────────────────────────────────────────────────────
  a077: {
    jung: { tr: '"Toprak Koruyucusu" arketipi. Porsuk savaşmaktan çekinmez ama savaşı aramaz — bu enerji, neyin savunulmaya değer olduğunu bilen ve o değer için her şeyi göze alabilen kararlı bilinçtir. Toprağın altındaki kökleri bilmek, yüzeyin geçici gürültüsüne kapılmamaktır.', en: 'The "Earth Guardian" archetype. The badger does not shy from fighting but does not seek it — this energy is a resolute consciousness that knows what is worth defending and is willing to risk everything for that value. Knowing the roots beneath the earth means not being swept away by the transient noise of the surface.' },
    dream: { tr: 'Porsuk rüyada — savaşman gereken bir şey var, çekilme. Ini kazıyorsa: temelleri güçlendirme vakti, derine in. Saldırıyorsa: korktuğun şeyle yüzleş, porsuk gibi dur — geriye adım atmadan.', en: 'Badger in dream — there is something you must fight for, do not withdraw. If it digs its burrow: it is time to strengthen foundations, go deep. If it attacks: face what you fear, stand like a badger — without stepping back.' },
    shadow: { tr: 'İnatçılığın katılığa dönmesi ve değişmemek için direniş. Porsuk enerjisinin gölgesi, bir inin içinde tüm dünyaya kapanmak — koruyucu yalnızlığın hapishaneye dönüşmesi.', en: 'Stubbornness hardening into rigidity and resistance to change. The shadow of badger energy is closing off to the entire world inside a burrow — protective solitude transforming into a prison.' },
    whenAppears: { tr: 'Sınırları ihlal edildiğinde ve kararlı bir duruş gerektiğinde, topluluk veya aile için mücadele edilmesi gereken dönemlerde, köklere dönüş ve temel güçlendirme zamanlarında.', en: 'When boundaries are violated and a resolute stance is required, during periods when one must fight for community or family, in times of returning to roots and strengthening foundations.' },
    traditions: [
      { culture: { tr: 'Kelt Geleneği', en: 'Celtic Tradition' }, meaning: { tr: 'Porsuk, toprağın en kadim bilgeliğinin bekçisidir; Druitlerin sırlarını sakladığı yerin altında porsuk inlerinin bulunduğuna inanılırdı.', en: 'The badger is the guardian of the most ancient wisdom of the earth; it was believed that badger burrows lay beneath the places where Druids stored their secrets.' } },
      { culture: { tr: 'Kuzey Amerika Yerli Gelenekleri (Lakota)', en: 'North American Indigenous Traditions (Lakota)' }, meaning: { tr: 'Porsuk, şifa klanının sembolüdür; tıbbi bitkilerin köklerini bulma bilgisini taşır ve yer altının iyileştirici güçlerine aracılık eder.', en: 'The badger is the symbol of the healing clan; it carries the knowledge of finding the roots of medicinal plants and mediates the healing powers of the underground.' } },
      { culture: { tr: 'Japon Geleneği (Tanuki)', en: 'Japanese Tradition (Tanuki)' }, meaning: { tr: 'Tanuki (rakun köpeği/porsuk akrabası), şekil değiştiren trickster ve bereket ruhudur; saflık ile kurnazlığı bir arada barındırır.', en: 'Tanuki (raccoon dog/badger relative) is a shape-shifting trickster and spirit of abundance; it combines innocence and cunning.' } },
      { culture: { tr: 'İngiliz Halk Geleneği', en: 'English Folk Tradition' }, meaning: { tr: 'Porsuk, Badger\'s Moon — porsuk ayı — dedikleri sonbahar dolunayında en güçlü kabul edilir; bu gecede yapılan antlaşmalar bozulmaz sayılır.', en: 'The badger is considered most powerful at the autumn full moon they call the Badger\'s Moon; agreements made on this night are considered unbreakable.' } },
      { culture: { tr: 'Anadolu Halk İnancı', en: 'Anatolian Folk Belief' }, meaning: { tr: 'Porsuk yağının şifa gücü olduğuna inanılır; köy bilgeleri porsukla karşılaşmayı "toprağın sizi kabul ettiğinin işareti" olarak yorumlar.', en: 'The fat of the badger is believed to have healing power; village sages interpret encountering a badger as "a sign that the earth has accepted you".' } },
    ],
    myths: [
      { tr: 'Lakota anlatısında, bir zamanlar insanlar şifa bitkilerini bulmayı bilmiyordu. Porsuk Büyük Ruh\'tan şifa bilgisini istedi. Büyük Ruh, "Yerin altına in ve her kökün sesini dinle" dedi. Porsuk aylarca yer altında kaldı, her köke kulak verdi. Yeryüzüne döndüğünde, şaman oldu. O günden beri porsuk, toprağın en derin şifa sırlarını taşıyan yol göstericidir.', en: 'In a Lakota narrative, long ago humans did not know how to find healing plants. The badger asked the Great Spirit for healing knowledge. The Great Spirit said, "Go underground and listen to the voice of every root." The badger remained underground for months, lending an ear to every root. When it returned to the surface, it had become a shaman. Since that day the badger is the guide who carries the deepest healing secrets of the earth.' },
      { tr: 'İskoçya\'da anlatılır: Porsuk ve Kartal bir gün kimin daha güçlü olduğunu tartıştı. Kartal gökyüzünden hâkim olduğunu söyledi; porsuk yeraltından. "O zaman savaşalım" dedi kartal. Porsuk "Hayır" dedi, "Ben savaşmayı seçerim, savaş beni seçmez." Kartal bu sözün bilgeliğini anlayamadı. Porsuk döndü, inine girdi. Kartal hâlâ bekliyor.', en: 'As told in Scotland: the badger and the eagle argued one day about who was more powerful. The eagle said it dominated from the sky; the badger from underground. "Then let us fight," said the eagle. "No," said the badger, "I choose to fight, fight does not choose me." The eagle could not understand the wisdom of these words. The badger turned and entered its burrow. The eagle is still waiting.' },
    ],
  },

  // ─── a078 Kunduz ─────────────────────────────────────────────────────────
  a078: {
    jung: { tr: '"Yaratıcı Mimar" arketipi. Kunduz doğayı dönüştürerek dünya inşa eder — bu enerji, hayal ile eylemi birleştiren, topluluk için çalışmayı bireysel tatminden üstün tutan bilinçtir. Barajlar, tek bir el değil, kolektif iradenin eseridir.', en: 'The "Creative Architect" archetype. The beaver transforms nature to build a world — this energy is a consciousness that unites imagination and action, placing work for the community above individual satisfaction. Dams are not the work of a single hand but of collective will.' },
    dream: { tr: 'Kunduz rüyada — inşa etme, yaratma, birleştirme çağrısı. Ağaç kesiyorsa: engelini yıkarak kullanıyorsun, engel malzemeye dönüşüyor. Baraj kuruyorsa: çevrendeki akıntıları kontrol etmeyi öğreniyor, yönlendiriyorsun.', en: 'Beaver in dream — a call to build, create, unite. If it fells a tree: you are using your obstacle by dismantling it, the obstacle is becoming material. If it builds a dam: you are learning to control the currents around you, you are directing them.' },
    shadow: { tr: 'Kontrolcülük ve inşa ettiğin yapıların içine hapsolmak. Kunduz enerjisinin gölgesi, sürekli çalışma bağımlılığı ve "bitirmek" yerine "yapmaya devam etmek" ısrarıdır — baraj asla tamamlanmaz çünkü tamamlanmak duraksatır.', en: 'Controlling behaviour and being imprisoned within the structures one has built. The shadow of beaver energy is continuous workaholism and the insistence on "continuing to do" rather than "finishing" — the dam is never completed because completion means pausing.' },
    whenAppears: { tr: 'Bir projenin ya da ilişkinin temel yapısı kurulurken, topluluk inşasında liderlik üstlenildiğinde, yaratıcı azmin ve pratik uygulamanın bir araya gelmesi gerektiğinde.', en: 'While the foundational structure of a project or relationship is being built, when leadership in community-building is assumed, when creative determination and practical application need to come together.' },
    traditions: [
      { culture: { tr: 'Kuzey Amerika Yerli Gelenekleri (Algonkin)', en: 'North American Indigenous Traditions (Algonquin)' }, meaning: { tr: 'Kunduz, yaratıcı ruhun habercisidir; Büyük Kunduz Amik, dünyanın sularını şekillendiren kutsal varlıktır ve su ile kara arasındaki dengeyi korur.', en: 'The beaver is the herald of the creative spirit; the Great Beaver Amik is the sacred being that shaped the waters of the world and maintains the balance between water and land.' } },
      { culture: { tr: 'Kanada Yerli Geleneği (Haudenosaunee)', en: 'Canadian Indigenous Tradition (Haudenosaunee)' }, meaning: { tr: 'Kunduz Klanı, barışçı inşacıların klanıdır; anlaşmazlıkları çözen, topluluğu bir arada tutan mimarlar olarak saygı görür.', en: 'The Beaver Clan is the clan of peaceful builders; it is respected as the architects who resolve disputes and hold the community together.' } },
      { culture: { tr: 'Kelt Geleneği', en: 'Celtic Tradition' }, meaning: { tr: 'Dobhar-chú — su köpeği, kunduz akrabası — İrlanda mitolojisinde su ruhlarının koruyucusudur ve nehirlerin belleğini taşır.', en: 'Dobhar-chú — the water hound, kunduz kin — is the guardian of water spirits in Irish mythology and carries the memory of rivers.' } },
      { culture: { tr: 'Sibirya (Buryat) Geleneği', en: 'Siberian (Buryat) Tradition' }, meaning: { tr: 'Kunduz derisi şamanın törensel kıyafetinde kullanılır; hayvanın nehir bilgeliğini ve inşa gücünü taşıyan totem parçasıdır.', en: 'Beaver hide is used in the shaman\'s ceremonial garment; it is the totem piece carrying the animal\'s river wisdom and constructive power.' } },
      { culture: { tr: 'Anadolu Halk Geleneği', en: 'Anatolian Folk Tradition' }, meaning: { tr: 'Anadolu nehirlerinde yaşayan kunduz, "suyun ustası" olarak bilinir; köylüler onun baraj kurduğu yeri bereketli toprak sayar ve o alanlara yakın ev kurar.', en: 'The beaver living in Anatolian rivers is known as "the master of water"; villagers consider the place where it builds its dam fertile land and build homes close to those areas.' } },
    ],
    myths: [
      { tr: 'Algonkin yaratılış anlatısında, büyük tufan sonrası dünya su altındaydı. Büyük Kunduz Amik, Yaratıcı ile birlikte suların altına daldı ve çamurla ilk kara parçasını şekillendirdi. Her baraj kurduğumuzda, Amik\'in ilk eylemine saygı duyuyoruz.', en: 'In the Algonquin creation narrative, after the great flood the world was underwater. The Great Beaver Amik dived beneath the waters together with the Creator and shaped the first piece of land from mud. Every time we build a dam, we pay homage to Amik\'s first act.' },
      { tr: 'Haudenosaunee geleneğinde anlatılır: Uzun savaş dönemlerinde kunduzlar nehirden çekildi. Su azaldı, balıklar gitti, kuşlar sustı. Halk anladı ki kunduz savaştan nefret eder. Büyükler bir araya geldi, barış anlaşması imzaladı. Ertesi sabah kunduzlar geri döndü — barajları yeniden kuruldu, su aktı, yaşam başladı.', en: 'As told in Haudenosaunee tradition: during long periods of war the beavers withdrew from the river. The water diminished, the fish left, the birds fell silent. The people understood that the beaver loathes war. The elders gathered and signed a peace treaty. The next morning the beavers returned — their dams were rebuilt, water flowed, life began.' },
    ],
  },

  // ─── a079 Guguk Kuşu ─────────────────────────────────────────────────────
  a079: {
    jung: { tr: '"Zaman Bilinci" arketipi. Guguk kuşu görünmeden sesini duyurur — bu enerji, varlığını ispat etmeden etki yaratan, zamanlama bilgeliğini beden dili değil ses aracılığıyla taşıyan bilinçtir. Her sesi bir sayıdır, her sayı bir döngünün habercisidir.', en: 'The "Time Consciousness" archetype. The cuckoo makes its voice heard without being seen — this energy is a consciousness that creates impact without proving its presence, carrying the wisdom of timing not through body language but through voice. Every call is a number, every number the herald of a cycle.' },
    dream: { tr: 'Guguk kuşu rüyada — bir döngü kapanıyor ya da açılıyor, zamanlamaya dikkat et. Sesi yakından geliyorsa: karar anı yakın, hazırlan. Sesi uzaktan geliyorsa: henüz zamanı değil, bekle ve dinle.', en: 'Cuckoo in dream — a cycle is closing or opening, pay attention to timing. If its voice comes from nearby: the moment of decision is near, prepare. If its voice comes from afar: the time has not yet come, wait and listen.' },
    shadow: { tr: 'Başkasının yuvasına kurma yumurta — kendi sorumluluğunu başkasına bırakma, parazitik bağımlılık. Guguk kuşunun gölgesi, zamanlama bilgeliğinin hesapçılığa, haberciliğin manipülasyona dönüşmesidir.', en: 'Laying eggs in another\'s nest — leaving one\'s own responsibility to others, parasitic dependency. The shadow of the cuckoo is timing wisdom turning into calculation, and the herald\'s role turning into manipulation.' },
    whenAppears: { tr: 'Bir dönemin kapandığını hissedip yeni dönemin açılışını beklerken, zaman ve ritim algısının yeniden ayarlanması gerektiğinde, doğru anı bekleme sabrının sınandığı dönemlerde.', en: 'While sensing that one period has closed and awaiting the opening of a new one, when the perception of time and rhythm needs to be recalibrated, during periods when the patience of waiting for the right moment is tested.' },
    traditions: [
      { culture: { tr: 'Anadolu ve Türk Geleneği', en: 'Anatolian and Turkish Tradition' }, meaning: { tr: 'Guguk kuşunun ilk sesini duyan kişi, dileklerini sayısınca tekrarlar; o yıl ne kadar "guguk" duyulursa o kadar yıl daha yaşanacağına inanılır.', en: 'The person who hears the cuckoo\'s first call repeats their wish as many times as the count; it is believed that however many times "cuckoo" is heard that year, that many more years of life remain.' } },
      { culture: { tr: 'Slav Geleneği', en: 'Slavic Tradition' }, meaning: { tr: 'Guguk kuşu, ölülerin ruhlarını taşıyan kutsal bir varlıktır; ötüşü ölümün değil dönüşümün habercisi olarak okunur. Yaz geldiğinde geçmiş yılın ruhları onun sesiyle vedalaşır.', en: 'The cuckoo is a sacred being that carries the souls of the dead; its call is read not as a herald of death but of transformation. When summer arrives the souls of past years bid farewell through its voice.' } },
      { culture: { tr: 'Yunan-Roma Geleneği', en: 'Greco-Roman Tradition' }, meaning: { tr: 'Zeus, Hera\'yı baştan çıkarmak için guguk kuşuna dönüştü — bu mit, guguk kuşunu dönüşüm ve aşkın trickster gücüyle özdeşleştirir.', en: 'Zeus transformed into a cuckoo to seduce Hera — this myth identifies the cuckoo with the trickster power of transformation and love.' } },
      { culture: { tr: 'Japon Geleneği', en: 'Japanese Tradition' }, meaning: { tr: 'Hototogisu — Japon guguku — ölüler diyarının habercisidir; yaz geceleri onun sesi duyulduğunda atalar ziyarete gelir.', en: 'Hototogisu — the Japanese cuckoo — is the herald of the land of the dead; when its voice is heard on summer nights the ancestors come to visit.' } },
      { culture: { tr: 'İskandinav Geleneği', en: 'Scandinavian Tradition' }, meaning: { tr: 'Guguk kuşu, yılın dört yönünden birini temsil eden kutsal habercidir; ilkbaharda duyulduğunda tanrılar dünyanın döngüsünü onaylamış demektir.', en: 'The cuckoo is a sacred herald representing one of the four directions of the year; when heard in spring it means the gods have approved the cycle of the world.' } },
    ],
    myths: [
      { tr: 'Hesiodos yazan bir Yunan anlatısına göre, dünya henüz soğukken Zeus kısıtlamaları tanımayan bir güce sahip olmak istedi. Hera\'nın kucağına yumurta koymak için küçük, titreyen bir guguk kuşuna dönüştü. Hera onu ısıtmak için sardığında Zeus kendi formuna döndü. O günden beri guguk kuşu, "gücünü küçüklük içinde saklayan" varlığın simgesidir.', en: 'According to a Greek narrative cited by Hesiod, when the world was still cold Zeus wished to possess a power that acknowledged no constraints. He transformed into a small, shivering cuckoo to lay an egg in Hera\'s lap. When Hera wrapped it to warm it, Zeus returned to his own form. Since that day the cuckoo is the symbol of the being that "hides its power within smallness".' },
      { tr: 'Anadolu\'da anlatılır: Bir zamanlar guguk kuşu tüm yıl boyunca şarkı söylerdi. Ama insanlar onun sesini duyunca işi bırakır, dinlemeye dalar, zamanı unuturlardı. Tanrı, "Bu öyle olmaz" dedi ve guguk kuşuna yalnızca ilkbahar ile yazın ötme izni verdi. Guguk kuşu kabul etti — çünkü nadir olan değerlidir, her an ötülürse sesi anlamsızlaşır.', en: 'As told in Anatolia: once upon a time the cuckoo sang throughout the whole year. But whenever people heard its voice they would stop working, fall into listening, forget time. God said, "This will not do," and gave the cuckoo permission to call only in spring and summer. The cuckoo accepted — because what is rare is precious; if it called at every moment its voice would lose meaning.' },
    ],
  },

  // ─── a080 Saksağan ──────────────────────────────────────────────────────
  a080: {
    jung: { tr: '"İkili Doğa Bilgesi" arketipi. Saksağan siyah ile beyazı bedeninde taşır — bu enerji, zıtlıkları sentezleyen, her şeyin iki yüzünü bir arada gören, trickster ile bilge arasında gidip gelen bilinçtir. Parlak nesneleri toplamak, dünyayı anlama açlığının simgesidir.', en: 'The "Dual Nature Sage" archetype. The magpie carries black and white in its body — this energy is a consciousness that synthesises opposites, sees both sides of everything simultaneously, and moves between trickster and sage. Collecting shiny objects is the symbol of a hunger to understand the world.' },
    dream: { tr: 'Saksağan rüyada — bir haber geliyor ya da gönderilmesi gereken bir mesaj var. Tek saksağan görülürse: beklenmedik bir değişim, uyanık kal. Çift saksağan: bir ilişkide denge kuruldu ya da kurulacak.', en: 'Magpie in dream — news is coming, or there is a message that needs to be sent. If a single magpie is seen: an unexpected change, stay alert. Two magpies: balance has been or will be established in a relationship.' },
    shadow: { tr: 'Parlak olan her şeye kapılmak — derinliksiz merak ve dikkat dağınıklığı. Saksağan enerjisinin gölgesi, bilgi toplarken bilgelik üretememek ve başkasının değerlisine sahip çıkma eğilimidir — hoarding ve ödünç kimlikler.', en: 'Being swept away by everything that glitters — superficial curiosity and scattered attention. The shadow of magpie energy is collecting information while failing to produce wisdom, and the tendency to claim what is valuable to others — hoarding and borrowed identities.' },
    whenAppears: { tr: 'Önemli bir haberin beklediği ya da verilmesi gereken dönemlerde, zıt güçleri bir arada tutmayı öğrenme sürecinde, zekânın ve gözlem yetisinin ön plana çıkması gereken anlarda.', en: 'During periods when important news is awaited or must be delivered, in the process of learning to hold opposing forces together, at moments when intelligence and the power of observation need to come to the fore.' },
    traditions: [
      { culture: { tr: 'Çin Geleneği', en: 'Chinese Tradition' }, meaning: { tr: 'Saksağan "xi que" — mutlu kuş. İki saksağan beraber görülürse "çift mutluluk" (双喜) işaretidir; düğünlerde ve kutlamalarda iyiye yorulur.', en: 'The magpie "xi que" — the happy bird. Two magpies seen together are a sign of "double happiness" (双喜); it is read as a good omen at weddings and celebrations.' } },
      { culture: { tr: 'Kore Geleneği', en: 'Korean Tradition' }, meaning: { tr: 'Saksağan, Kore\'nin ulusal kuşudur; iyilik, cesaret ve sevincin simgesidir. Sabah saksağan görülürse misafir geleceğine inanılır.', en: 'The magpie is the national bird of Korea; it is the symbol of goodness, courage, and joy. If a magpie is seen in the morning it is believed that a guest will arrive.' } },
      { culture: { tr: 'İngiliz ve İskoç Halk Geleneği', en: 'English and Scottish Folk Tradition' }, meaning: { tr: '"Bir saksağan keder, iki saksağan sevinç" — saksağan sayısını kehanet için sayan bu gelenek yüzyıllardır sürmektedir. Her sayı farklı bir kaderi işaret eder.', en: '"One for sorrow, two for joy" — the tradition of counting the number of magpies for divination has continued for centuries. Each count points to a different fate.' } },
      { culture: { tr: 'Sibirya Şaman Geleneği', en: 'Siberian Shamanic Tradition' }, meaning: { tr: 'Saksağan, şamanın ruhlar dünyasındaki habercisidir; iki dünya arasında mektup taşır ve şamanın gittiği yerlerin haritasını bilir.', en: 'The magpie is the shaman\'s messenger in the spirit world; it carries letters between two worlds and knows the map of the places the shaman travels.' } },
      { culture: { tr: 'Anadolu Halk İnancı', en: 'Anatolian Folk Belief' }, meaning: { tr: 'Saksağan eve konarsa yakın zamanda misafir gelir ya da bir haber ulaşır. Bir dala konup gitmeden bekliyorsa "söylemesi gereken bir şey var" denir — sessizce dinlenir.', en: 'If a magpie perches on a house, a guest will arrive or news will reach soon. If it perches on a branch and waits without leaving, it is said "it has something to say" — one listens in silence.' } },
    ],
    myths: [
      { tr: 'Kore\'nin Gyeonu ile Jiknyeo efsanesinde, iki âşık Samanyolu\'nun iki yakasına ayrılmıştır. Yılda yalnızca bir gece — Tanabata\'da — buluşabilirler. Bu geceye ulaşmak için tüm saksağanlar birleşerek gökyüzünde köprü kurar: kanatları birbirine geçmiş binlerce saksağan, iki yıldız âşığı birleştirir. Sabah saksağanların başı dazlak görülürse, o gece köprü kurduklarının işaretidir.', en: 'In the Korean legend of Gyeonwoo and Jiknyeo, two lovers are separated on opposite sides of the Milky Way. Only one night a year — on Tanabata — can they meet. To reach this night, all the magpies unite to build a bridge in the sky: thousands of magpies with wings interlocked unite the two star-crossed lovers. If magpies are seen with bare heads in the morning, it is a sign that they built the bridge that night.' },
      { tr: 'Çin\'de anlatılır: Saksağan bir gün güneşe uçmaya karar verdi. "Seni bulacağım ve en parlak nesneyi yanına koyacağım" dedi. Aylarca uçtu, güneşe ulaşamadı. Dönerken gördü ki dünya zaten güneşle doluydu — her damlada, her yaprakta, her gözde. O günden beri saksağan yalnızca parlayan şeyleri değil, parlakın içinde gizlenmiş derin şeyleri de taşır.', en: 'As told in China: one day the magpie decided to fly to the sun. "I will find you and place the shiniest object beside you," it said. It flew for months and could not reach the sun. On its return it saw that the world was already full of sunlight — in every drop, every leaf, every eye. Since that day the magpie carries not only shining things but also the deep things hidden within the shine.' },
    ],
  },

  // ─── a081 Simurg ────────────────────────────────────────────────────────
  a081: {
    jung: { tr: '"Kolektif Benlik" arketipi. Simurg, bireysel egonun erimesiyle ortaya çıkan evrensel farkındalığın simgesidir. Jung\'un "bütünleşme" kavramını en yüce noktasına taşır — 30 kuş aynaya baktığında gördüğü tek varlık, ayrılığın illüzyon olduğunu fısıldar.', en: '"Collective Self" archetype. The Simurgh represents the universal awareness that emerges when individual ego dissolves. It carries Jung\'s concept of "individuation" to its highest peak — when 30 birds look in the mirror and see one being, it whispers that separation is illusion.' },
    dream: { tr: 'Simurg rüyada — kolektife ait bir hakikati aramaktasın. Kanatlarını görüyorsan: bilgelik sende zaten var, aramayı bırak. Çok kuş olarak uçuyorsan: topluluğunla bütünleşme zamanı gelmiş.', en: 'Simurgh in dream — you are seeking a truth that belongs to the collective. If you see its wings: the wisdom already resides in you, stop searching. If you fly as many birds: the time has come to merge with your community.' },
    shadow: { tr: 'Aşkınlık adına yalnızlığa çekilme. "Ben herkeste varım" düşüncesi, somut ilişkilerden kaçışın mistik örtüsü olabilir. Evrensel sevgiden bahsedip yakınlarını görmezden gelmek.', en: 'Withdrawing into solitude in the name of transcendence. The thought "I exist in everyone" can become a mystical veil over escape from concrete relationships. Speaking of universal love while ignoring those close to you.' },
    whenAppears: { tr: 'Bir topluluğa ait olmak ya da tam bağımsızlık arasında kaldığında; "ben kimim" sorusunun kalabalığın içinde kaybolduğu dönemlerde.', en: 'When you are caught between belonging to a community and complete independence; in periods when the question "who am I" is lost within the crowd.' },
    traditions: [
      { culture: { tr: 'Sufi-İran', en: 'Sufi-Persian' }, meaning: { tr: 'Feridüddin Attar\'ın Mantıku\'t-Tayr\'ında 30 kuş Simurg\'u arar; sonunda ayna karşısında kendilerinin Simurg olduğunu görürler.', en: 'In Attar\'s Conference of the Birds, 30 birds seek the Simurgh; before the mirror they finally realize they themselves are the Simurgh.' } },
      { culture: { tr: 'Zerdüşt', en: 'Zoroastrian' }, meaning: { tr: 'Saena kuşu — Hayat Ağacı\'nın tepesinde yuvalanan, tüm bitkilerin tohumlarını dağıtan kutsal koruyucu.', en: 'The Saena bird — sacred guardian nesting atop the Tree of Life, scattering seeds of all plants across the world.' } },
      { culture: { tr: 'Şahnâme', en: 'Shahnameh' }, meaning: { tr: 'Rüstem\'in babası Zal\'ı büyüten Simurg, bilgeliğini ve tüyünü insanlığa armağan eder; ihtiyaç anında yakılacak bir tüydür o.', en: 'The Simurgh who raised Zal, father of Rostam, gifts its wisdom and a feather to humanity — a feather to be burned in the moment of need.' } },
      { culture: { tr: 'Türk Destanları', en: 'Turkic Epics' }, meaning: { tr: 'Anka ya da Zümrüdüanka olarak bilinir — "Yeşil Anka" — ulaşılamaz dağlarda yaşayan, yiğitleri sınayan dönüşüm kuşu.', en: 'Known as Anka or Zümrüdüanka — "Emerald Phoenix" — the bird of transformation dwelling in unreachable mountains, testing the worthy.' } },
      { culture: { tr: 'Hint', en: 'Indian' }, meaning: { tr: 'Garuda ile Simurg paralel koşar — her ikisi de güneş enerjisini taşır, tanrısal bilgiyi insana aktarır.', en: 'Garuda runs parallel to the Simurgh — both carry solar energy, both transmit divine knowledge to humanity.' } },
    ],
    myths: [
      { tr: 'Attar\'ın Kuş Konferansı\'nda 30 kuş, yedi vadiden geçerek Simurg\'un dağına ulaşır: Talep, Aşk, Marifet, Kanaat, Tevhid, Hayret ve Yokluk. Her vadide bir kuş düşer. Kalanlar aynaya baktığında tek bir varlık görür — hem kendileri hem Simurg. Ayrılık hiç olmamıştır.', en: 'In Attar\'s Conference of the Birds, 30 birds cross seven valleys to reach the Simurgh\'s mountain: Quest, Love, Knowledge, Contentment, Unity, Wonder, and Annihilation. In each valley a bird falls. When the remaining look into the mirror they see a single being — both themselves and the Simurgh. Separation never existed.' },
      { tr: 'Şahnâme\'de Zal, doğumundan itibaren Simurg\'un yuvasında büyür. Rüstem yaralı düştüğünde babası Simurg\'un tüyünü yakar — kuş gelir, deva verir ve der ki: "Ben hem sizi hem sizin acınızı bilirim, çünkü ben sizin içinizdeki bilgeliktim."', en: 'In the Shahnameh, Zal grows up in the Simurgh\'s nest from birth. When Rostam falls wounded, his father burns the Simurgh\'s feather — the bird arrives, brings remedy and says: "I know both you and your pain, for I was the wisdom within you."' },
    ],
  },

  // ─── a082 Garuda ────────────────────────────────────────────────────────
  a082: {
    jung: { tr: '"İlahi Araç" arketipi. Garuda, egonun ilahi iradenin hizmetine girdiği anı simgeler — artık bireysel istek değil, evrensel düzen taşınır. Jung\'un "numinous" deneyimi: benliğin büyük bir güç tarafından seçildiği o titreşimli an.', en: '"Divine Vehicle" archetype. Garuda symbolizes the moment the ego enters the service of divine will — it no longer carries individual desire but universal order. Jung\'s "numinous" experience: that trembling moment when the self is chosen by a greater power.' },
    dream: { tr: 'Garuda rüyada — bir misyon üstlenme zamanı gelmiştir. Kanatlarını açıyorsa: engellerden üstünsün, yüksek bir amacın seni taşıyor. Yılanla savaşıyorsa: bilinçdışındaki zehri dönüştürme süreci başlamış.', en: 'Garuda in dream — the time has come to take on a mission. If it spreads wings: you are above obstacles, a higher purpose carries you. If it battles a serpent: the process of transforming the poison in the unconscious has begun.' },
    shadow: { tr: '"Tanrı adına" öfke ve yargı. Garuda\'nın ateşi yanlış yöne döndüğünde, kişi kendini kutsal bir savaşçı sanıp başkalarını yok etmeye kalkar. Ego, ilahiliği kendi gücüne sarıp onu araçsallaştırır.', en: 'Anger and judgment "in the name of God." When Garuda\'s fire turns the wrong way, a person fancies themselves a holy warrior and sets out to destroy others. The ego wraps divinity around its own power and instrumentalizes it.' },
    whenAppears: { tr: 'Büyük bir haksızlıkla yüz yüze geldiğinde ya da uzun süredir kaçındığın bir görevi nihayet üstlenmek zorunda kaldığında.', en: 'When you face a great injustice or when you are finally compelled to take on a duty you have long been avoiding.' },
    traditions: [
      { culture: { tr: 'Hindu', en: 'Hindu' }, meaning: { tr: 'Vişnu\'nun vahana\'sı — ilahi düzenin taşıyıcısı. Nagaraja\'nın, yılanların efendisinin ezeli düşmanı; zehri arındırır.', en: 'Vahana of Vishnu — carrier of divine order. Eternal enemy of Nagaraja, lord of serpents; it purifies venom.' } },
      { culture: { tr: 'Budist', en: 'Buddhist' }, meaning: { tr: 'Sekiz büyük varlıktan biri. Bilgelik ve merhameti simgeler; naga\'ları (yılanları) farkındalıkla ehlileştirir.', en: 'One of the eight great beings. Symbolizes wisdom and compassion; tames the nagas (serpents) with mindfulness.' } },
      { culture: { tr: 'Endonezya', en: 'Indonesian' }, meaning: { tr: 'Garuda, Endonezya\'nın ulusal amblemi — birlik, güç ve bağımsızlık ruhu. Pancasila ilkelerini kanatlarında taşır.', en: 'Garuda is Indonesia\'s national emblem — the spirit of unity, strength, and independence. It bears the Pancasila principles on its wings.' } },
      { culture: { tr: 'Tayland-Khmer', en: 'Thai-Khmer' }, meaning: { tr: 'Kraliyet gücünün sembolü. Kral Garuda\'nın üzerinde tahtına oturur — ilahi düzenin yeryüzündeki yansıması.', en: 'Symbol of royal power. The king sits on his throne atop Garuda — the earthly reflection of divine order.' } },
      { culture: { tr: 'Japon', en: 'Japanese' }, meaning: { tr: 'Karura — Budist koruyucu dört tanrısından biri. Ağzından alev çıkar, naga\'ları yer; negatif enerjiyi dönüştürür.', en: 'Karura — one of the four Buddhist guardian deities. Flames burst from its mouth, it devours nagas; it transforms negative energy.' } },
    ],
    myths: [
      { tr: 'Hindu mitiyle Garuda, annesini köle eden yılanlardan kurtarmak için amritu, ölümsüzlük iksirini çalar. Vişnu\'nun karşısına çıkar; tanrı onun cesaretine o denli hayran kalır ki onu tahtının karşısına kondurmak yerine kendi aracı yapar. Böylece Garuda hem özgürlüğü hem sonsuzluğu kazanır — ama iktidar değil, hizmet yoluyla.', en: 'In Hindu myth, Garuda steals the amrita, the elixir of immortality, to free his mother enslaved by serpents. He stands before Vishnu; the god is so awed by his courage that instead of punishing him he makes him his vehicle. Thus Garuda wins both freedom and eternity — not through power, but through service.' },
      { tr: 'Bir Japon efsanesine göre Karura gökyüzünde ağlar — çünkü yalnızca naga yiyebilir ama onları yemek onu da acıya sürükler. Bir Budist aziz yaklaşır ve sorar: "Neden ağlıyorsun?" Karura der ki: "Hem öldürüyorum hem de acı çekiyorum." Aziz cevaplar: "Bu farkındalık, seni Budha\'ya yaklaştıran şeydir."', en: 'According to a Japanese legend, Karura weeps in the sky — for it can only eat nagas, but eating them fills it with sorrow. A Buddhist saint approaches and asks: "Why do you weep?" Karura says: "I both kill and suffer." The saint replies: "This awareness is what brings you closer to Buddha."' },
    ],
  },

  // ─── a083 Keçi ──────────────────────────────────────────────────────────
  a083: {
    jung: { tr: '"Yaratıcı Özgürlük" ve "İçgüdüsel Bilgelik" arketipi. Keçi, egonun katı yapılarını aşıp dağın sarp kayalıklarında — yani sınırın tam kenarında — denge bulan bilinçdışı yaratıcılığı simgeler. Pan ile özdeşleştirilen bu enerji, medeniyetin bastırdığı doğal yaşam sevincini geri çağırır.', en: '"Creative Freedom" and "Instinctual Wisdom" archetype. The goat symbolizes the unconscious creativity that transcends the ego\'s rigid structures and finds balance on the steep cliffs of the mountain — right at the edge of the limit. This energy, identified with Pan, recalls the natural joy of life suppressed by civilization.' },
    dream: { tr: 'Keçi rüyada — imkânsız görünen bir yolda ilerleyebilirsin. Kayalıkta tırmanıyorsa: kendi özgün yolunu bul, kimsenin geçmediği yerden geç. Düşüyorsa: yaratıcı cesaretini korkuya kurban ediyorsun.', en: 'Goat in dream — you can move forward on a path that seems impossible. If it climbs cliffs: find your own unique path, pass where no one has gone. If it falls: you are sacrificing your creative courage to fear.' },
    shadow: { tr: 'İnatçılık ve sürüye katılmama. Keçinin bağımsızlık enerjisi sapkınlaştığında, kişi işbirliğini tamamen reddeder, her çiti yıkar ama hiçbir bahçe kurmaz. Özgürlük, sorumsuzluğun kılığına bürünür.', en: 'Stubbornness and refusal to join the herd. When the goat\'s independence energy turns perverse, the person completely rejects cooperation, breaks every fence but builds no garden. Freedom disguises itself as irresponsibility.' },
    whenAppears: { tr: '"Bu yol benim için değil" dediğin anda ama korkudan geri çekildiğinde; yaratıcı bir proje için alışılmadık bir yol aramak zorunda kaldığında.', en: 'At the moment you say "this path is not for me" but retreat out of fear; when you are compelled to seek an unconventional path for a creative project.' },
    traditions: [
      { culture: { tr: 'Yunan', en: 'Greek' }, meaning: { tr: 'Pan — yarı keçi, yarı insan tanrı. Doğanın, verimliliğin ve serbest müziğin tanrısı. Panik kelimesi ondan gelir — derin ormanlarda duyulan ilkel korku sesi.', en: 'Pan — half-goat, half-human god. God of nature, fertility, and free music. The word panic comes from him — the primal sound of terror heard in deep forests.' } },
      { culture: { tr: 'İskandinav', en: 'Norse' }, meaning: { tr: 'Tanngrisnir ve Tanngnjóstr — Thor\'un keçileri. Her gece yenir, her sabah dirilirler. Yeniden doğuş ve sonsuz besin kaynağı.', en: 'Tanngrisnir and Tanngnjóstr — Thor\'s goats. Eaten every night, resurrected every morning. Rebirth and the inexhaustible source of nourishment.' } },
      { culture: { tr: 'Çin', en: 'Chinese' }, meaning: { tr: 'Onikilik takvimin sekizinci hayvanı. Keçi yılı; sanat, zarafet, sezgi ve sürüden farklı düşünme enerjisini taşır.', en: 'The eighth animal of the twelve-year cycle. The Year of the Goat carries the energy of art, grace, intuition, and thinking differently from the herd.' } },
      { culture: { tr: 'Anadolu', en: 'Anatolian' }, meaning: { tr: 'Kıl keçisi Anadolu\'nun dört mevsim yoldaşı — süt, yün, deri, et verir. "Keçi gibi inat" deyimi hem zorluk hem direnciyle büyük saygı taşır.', en: 'The Angora goat is Anatolia\'s companion across four seasons — giving milk, wool, leather, meat. The saying "stubborn as a goat" carries deep respect for both its difficulty and its resilience.' } },
      { culture: { tr: 'Batı Afrika', en: 'West African' }, meaning: { tr: 'Yoruba geleneğinde Eşu\'nun keçisi — tanrılar ve insanlar arasındaki mesajcı, sınırları aşan, sürpriz getiren varlık.', en: 'In Yoruba tradition, Eshu\'s goat — the messenger between gods and humans, crossing boundaries, bringing surprises.' } },
    ],
    myths: [
      { tr: 'Pan bir gün nehir kıyısında uyuyan Syrinx\'e âşık olur. Syrinx kaçar, nehre ulaşınca su perilerine dönüşmesini diler. Pan ellerini uzattığında kamışları kavrar — ve kamışın iniltisini duyunca o sesi müziğe dönüştürür. Böylece Pan flütü doğar: kaybedilen güzellik, yaratıcılığa dönüşür.', en: 'One day Pan falls in love with Syrinx sleeping by the river. Syrinx flees, and upon reaching the river prays to be transformed by the water nymphs. When Pan reaches out he grasps reeds — and hearing the moan of the reed he transforms that sound into music. Thus the Pan flute is born: lost beauty becomes creativity.' },
      { tr: 'Thor\'un keçilerini bir gece bir çiftçi ailesi yemiştir. Sabah Thor kemikleri toplar, büyüsüyle keçileri diriltir — ama biri aksıyor. Bir kemik kırılmıştır. Thor öfkesini bastırır, çiftçi ailesini affeder ve keçinin bacağındaki izin "bağışlama" gücünü hatırlatır.', en: 'One night a farmer\'s family has eaten Thor\'s goats. In the morning Thor gathers the bones, resurrects the goats with his magic — but one limps. A bone was broken. Thor suppresses his anger, forgives the farmer\'s family, and the mark on the goat\'s leg becomes a reminder of the power of "forgiveness."' },
    ],
  },

  // ─── a084 İbis ──────────────────────────────────────────────────────────
  a084: {
    jung: { tr: '"İlahi Aracı" ve "Hermeneut" arketipi. İbis, bilinçdışının gizemli dil katmanlarına nüfuz eden, bu katmanları yazıya, sembole, anlama dönüştüren zihinsel ilkeyi simgeler. Thoth enerjisi — ham deneyimi kutsal anlama çeviren tercüman.', en: '"Divine Mediator" and "Hermeneutic" archetype. The ibis symbolizes the mental principle that penetrates the mysterious language layers of the unconscious and transforms them into writing, symbol, and meaning. The Thoth energy — the translator who turns raw experience into sacred sense.' },
    dream: { tr: 'İbis rüyada — bir mesajı doğru okuman gerekmektedir. Yazı yazıyorsa: içindeki bilgeliği dışa vurma zamanı. Ayakta ve hareketsiz duruyorsa: acele etme, doğru kelimeleri bulmak için sabret.', en: 'Ibis in dream — you need to read a message correctly. If it writes: the time has come to externalize the wisdom within. If it stands still and motionless: do not rush, be patient to find the right words.' },
    shadow: { tr: 'Entelektüel kibir ve bilginin tekelleştirilmesi. İbis enerjisi karanlığa döndüğünde, kişi bilgiyi güç olarak kullanır, paylaşmaz, anlaşılmaz dilde konuşarak diğerlerini küçümser. Kutsal bilgi, ego aracına dönüşür.', en: 'Intellectual arrogance and the monopolization of knowledge. When ibis energy turns dark, the person uses knowledge as power, does not share it, and belittles others by speaking in incomprehensible language. Sacred knowledge becomes a tool of the ego.' },
    whenAppears: { tr: 'Yazmak, öğretmek ya da bir gerçeği ifade etmek için doğru kelimeler aradığında; hayatının büyük bir bölümünü anlamlandırmaya çalıştığın dönemlerde.', en: 'When you search for the right words to write, teach, or express a truth; in periods when you are trying to make sense of a large chapter of your life.' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian' }, meaning: { tr: 'Thoth\'un kutsal hayvanı. Tanrı Thoth ibis başlıdır — bilgelik, ay, yazı, matematik ve ölüler kitabının yazıcısı.', en: 'The sacred animal of Thoth. The god Thoth has an ibis head — scribe of wisdom, the moon, writing, mathematics, and the Book of the Dead.' } },
      { culture: { tr: 'Antik Yunan', en: 'Ancient Greek' }, meaning: { tr: 'Yunanlılar ibisi Hermes\'le ilişkilendirdi — tanrılar arası mesajcı, ölüler âleminin rehberi, sözün ve anlamın efendisi.', en: 'The Greeks associated the ibis with Hermes — messenger between gods, guide of the underworld, master of word and meaning.' } },
      { culture: { tr: 'Roma', en: 'Roman' }, meaning: { tr: 'Nil\'in kutsal koruyucusu. İbis yılanları yer, salgını önler — beden sağlığı ve zihin temizliği bir arada.', en: 'Sacred guardian of the Nile. The ibis eats serpents, prevents plague — bodily health and mental clarity combined.' } },
      { culture: { tr: 'Batı Afrika', en: 'West African' }, meaning: { tr: 'Bazı Vodou geleneklerinde ibis tüyleri kehanet ritüellerinde kullanılır — bilgelik ve ilahi iletişimin simgesi.', en: 'In some Vodou traditions ibis feathers are used in divination rituals — a symbol of wisdom and divine communication.' } },
      { culture: { tr: 'Japon', en: 'Japanese' }, meaning: { tr: 'Toki — Japonya\'nın neredeyse nesli tükenen kutsal kuşu. Narinlikle, zarafetle, koruma gerektiren nadir bilgelik olarak yeniden canlandırıldı.', en: 'Toki — Japan\'s nearly extinct sacred bird. Revived as a symbol of rarity, grace, and wisdom that requires protection.' } },
    ],
    myths: [
      { tr: 'Mısır mitinde Thoth, Ra ile Ay arasında oynanan bir oyunda Ay\'dan beş ek gün kazanır — böylece Nut\'un çocukları, Osiris, İsis, Set, Nephthys ve Horus yeryüzüne gelebilir. Thoth yalnızca bir bilge değildir; zamanı, çözülmez görünen düğümleri çözen bilgeliğidir.', en: 'In Egyptian myth, Thoth wins five extra days from the Moon in a game played between Ra and the Moon — allowing Nut\'s children, Osiris, Isis, Set, Nephthys, and Horus, to come into the world. Thoth is not merely a sage; he is the wisdom that unravels time and seemingly impossible knots.' },
      { tr: 'Osiris öldürüldükten sonra İsis parçalanmış bedenini arar. Her şeyi kaydeden Thoth\'tur — kayıp parçaları, söylenmesi gereken büyü sözlerini, ölümden dönüşün şifresini yazar. Kutsal bilgelik, yas içinde bile kalemine devam eder.', en: 'After Osiris is killed, Isis searches for his dismembered body. It is Thoth who records everything — the missing pieces, the magic words that must be spoken, the cipher of the return from death. Sacred wisdom continues writing even within grief.' },
    ],
  },

  // ─── a085 İskarabe ──────────────────────────────────────────────────────
  a085: {
    jung: { tr: '"Yeniden Doğuş" ve "Dönüşüm" arketipi. İskarabe, Jung\'un meşhur eserinde sinkoronisiteyle ilişkilendirilir — rasyonel aklın tıkandığı yerde doğanın simgesel cevabıdır. Gübre topunda yeni güneşi yuvarlayan bu küçük varlık, en karanlık maddeden kutsal yaratımın mümkün olduğunu gösterir.', en: '"Rebirth" and "Transformation" archetype. The scarab is associated with synchronicity in Jung\'s famous work — it is nature\'s symbolic answer where the rational mind reaches a dead end. This small being rolling the new sun in a dung ball shows that sacred creation from the darkest matter is possible.' },
    dream: { tr: 'İskarabe rüyada — köklü bir dönüşüm başlamak üzeredir. Güneşe doğru yuvarlıyorsa: içinden geçtiğin zor süreç seni aydınlatacak. Çoğalıyorsa: küçük ama sürekli adımlar büyük değişimi getirir.', en: 'Scarab in dream — a fundamental transformation is about to begin. If it rolls toward the sun: the difficult process you are passing through will illuminate you. If they multiply: small but continuous steps bring great change.' },
    shadow: { tr: 'Kirli olanı kutsallaştırma takıntısı. İskarabe enerjisi sapkınlaştığında, kişi her çukuru "dönüşüm fırsatı" diye sahiplenir ve asıl temizlenme işini süresiz erteler. Gübre içinde kalmayı maneviyatla örtmek.', en: 'The obsession with sanctifying what is filthy. When scarab energy turns perverse, the person claims every pit as a "transformation opportunity" and indefinitely postpones the actual work of cleansing. Covering remaining in dung with spirituality.' },
    whenAppears: { tr: 'En altta hissettiğinde, utanç ya da başarısızlık içindeyken; anlamsız görünen bir sürecin ortasında anlam aradığında.', en: 'When you feel at rock bottom, inside shame or failure; when you search for meaning in the middle of a process that seems meaningless.' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian' }, meaning: { tr: 'Khepri — doğan güneşin tanrısı, skarabeus başlı. Her sabah güneşi ufuktan yukarı iter. "Kheper" = "olmak", "var olmak", "dönüşmek".', en: 'Khepri — god of the rising sun, scarab-headed. Every morning he pushes the sun up from the horizon. "Kheper" = "to be," "to exist," "to transform."' } },
      { culture: { tr: 'Mısır Muskası', en: 'Egyptian Amulet' }, meaning: { tr: 'Kalp skarabeusu — ölünün mumyasının üstüne konur. Ruhun yargılanması sırasında kalbi aleyhine tanıklık etmemesi için dua yazılıdır.', en: 'Heart scarab — placed over the mummy of the deceased. A prayer is inscribed so the heart does not testify against the soul at judgment.' } },
      { culture: { tr: 'Jung Psikolojisi', en: 'Jungian Psychology' }, meaning: { tr: 'Jung\'un meşhur vakasında bir hasta Altın Skarabeus rüyasını anlatırken pencereye bir skarabeus böceği çarpar — sinkonisitenin simgesi olur.', en: 'In Jung\'s famous case, while a patient recounts a dream of the Golden Scarab, a scarab beetle strikes the window — it becomes the symbol of synchronicity.' } },
      { culture: { tr: 'Roma', en: 'Roman' }, meaning: { tr: 'Mısır kültünün yayılmasıyla Roma\'ya taşınan skarabeus muskası, uğur, yeniden doğuş ve koruma sembolü olarak kullanıldı.', en: 'Carried to Rome with the spread of Egyptian cult, the scarab amulet was used as a symbol of luck, rebirth, and protection.' } },
      { culture: { tr: 'Modern Sembolizm', en: 'Modern Symbolism' }, meaning: { tr: 'İskarabe günümüzde atık ve dönüşümün simgesi olarak çevre etiğinde yeniden anlam kazanıyor — hiçbir şey ziyan olmaz, her şey dönüşür.', en: 'Today the scarab is regaining meaning in environmental ethics as a symbol of waste and transformation — nothing is wasted, everything transforms.' } },
    ],
    myths: [
      { tr: 'Mısır kozmolojisinde dünya her gece Nun\'un ilk sularına — yokluğa — döner. Khepri, sabahın ilk ışığında güneş topunu ufuktan iter ve "ben bugün de varım" der. İskarabenin gübre topunda yuvarlayıp gömdüğü yumurtalar, karanlık topraktan patlayan larvalardır — yaratım, çürümeden doğar.', en: 'In Egyptian cosmology the world returns each night to the primordial waters of Nun — to nothingness. Khepri, at the first light of morning, pushes the sun ball up from the horizon and says "I exist again today." The eggs the scarab rolls in its dung ball and buries are larvae that burst from dark earth — creation is born from decay.' },
      { tr: 'Jung\'un bir hastası rüyasında ona altın bir skarabeus böceği uzatır. Aynı anda, terapi odasının penceresine gerçek bir skarabeus böceği çarpar. Jung pencereyi açar, böceği içeri alır ve hastaya verir. O an, hastanın yıllarca dirençle koruduğu rasyonalizmi çözülmeye başlar. İçeriden gelen simge, dışarıdan bir sesle yankılanmıştır.', en: 'A patient of Jung\'s extends a golden scarab beetle to him in a dream. At the very same moment, a real scarab beetle strikes the window of the therapy room. Jung opens the window, takes the beetle inside, and hands it to the patient. At that moment, the rationalism the patient had guarded with resistance for years begins to dissolve. The symbol from within has echoed with a voice from without.' },
    ],
  },

  // ─── a086 Piton ─────────────────────────────────────────────────────────
  a086: {
    jung: { tr: '"Ata Ruhu" ve "Chthonic Ana" arketipi. Piton, toprağın derinliklerinden gelen, ata bilgeliğini ve kolektif belleği taşıyan bilinçdışı güçleri simgeler. Jung\'un "Büyük Ana" figürünün en eski, en köklü biçimi — hem besleyen hem yutan, hem koruyan hem dönüştüren.', en: '"Ancestral Spirit" and "Chthonic Mother" archetype. The python symbolizes the unconscious forces coming from the depths of earth, carrying ancestral wisdom and collective memory. The oldest, most rooted form of Jung\'s "Great Mother" figure — both nourishing and engulfing, both protecting and transforming.' },
    dream: { tr: 'Piton rüyada — ata sesleri konuşuyor. Sarıyorsa ama boğmuyorsa: köklerinle bütünleş, geçmişin seni taşıyor. Boğuyorsa: ailenin ya da geleneğin baskısından nefes alamıyorsun.', en: 'Python in dream — ancestral voices are speaking. If it coils but does not constrict: integrate with your roots, the past carries you. If it constricts: you cannot breathe under the pressure of family or tradition.' },
    shadow: { tr: 'Özgürlüğü kıstıran gelenekçilik. Piton\'un toprak enerjisi sapkınlaştığında, atalar adına baskı, yenilik karşıtlığı ve "böyle gördük böyle yaparız" katılığı devreye girer. Kök, kanat olacak yerde pranga olur.', en: 'Traditionalism that constricts freedom. When python\'s earth energy turns perverse, pressure in the name of ancestors, opposition to innovation, and the rigidity of "we saw it this way, we do it this way" take over. The root becomes a shackle where it should become a wing.' },
    whenAppears: { tr: 'Aile mirası ya da kültürel köklerle yüzleşmen gerektiğinde; bir döngünün kapandığını ve yenisine geçiş için derin bir arınma gerektiğini hissettiğinde.', en: 'When you need to face your family heritage or cultural roots; when you sense that a cycle is closing and deep purification is needed to transition to the next.' },
    traditions: [
      { culture: { tr: 'Yunan', en: 'Greek' }, meaning: { tr: 'Python — Delphi kehanet merkezinin koruyucusu. Gaia\'nın oğlu, toprağın sesi. Apollon onu öldürür ama onun adını taşır: Pythia, yer altından konuşur.', en: 'Python — guardian of the Delphic oracle center. Son of Gaia, voice of the earth. Apollo slays it but bears its name: the Pythia speaks from underground.' } },
      { culture: { tr: 'Batı Afrika — Dahomey', en: 'West African — Dahomey' }, meaning: { tr: 'Ayida-Weddo ve Damballa — Vodou\'nun gökkuşağı yılanı çifti. Toprak ve gökyüzünü, ölümlü ve ölümsüzü birleştirir.', en: 'Ayida-Weddo and Damballa — the Vodou rainbow serpent couple. Uniting earth and sky, mortal and immortal.' } },
      { culture: { tr: 'Avustralya Aborijin', en: 'Australian Aboriginal' }, meaning: { tr: 'Gökkuşağı Yılanı — yaratılış miti. Yer altından çıkıp nehirleri, dağları, yaşam biçimlerini şekillendirir. Hem yaratıcı hem yıkıcı, hem ata hem tanrı.', en: 'Rainbow Serpent — creation myth. Rising from underground it shapes rivers, mountains, and ways of life. Both creator and destroyer, both ancestor and god.' } },
      { culture: { tr: 'Mısır', en: 'Egyptian' }, meaning: { tr: 'Apophis — Ra\'nın geceleyin geçtiği yolun tehlikesi. Ama Mehen yılanı Ra\'yı korur — aynı enerji hem tehdit hem kalkan olabilir.', en: 'Apophis — the danger on the path Ra traverses at night. But the serpent Mehen protects Ra — the same energy can be both threat and shield.' } },
      { culture: { tr: 'Zulu', en: 'Zulu' }, meaning: { tr: 'İnhlwathi — büyük piton, ataların ruhu. Ata mezarı yakınında görülmesi, koruyucu bir mesajın geldiğini gösterir.', en: 'Inhlwathi — the great python, spirit of the ancestors. Being seen near an ancestral burial site signals that a protective message has arrived.' } },
    ],
    myths: [
      { tr: 'Apollon Delphi\'ye geldiğinde orası Python\'un egemenliğindedir — toprağın, bilinçdışının, ham kehanetin krallığı. Apollon Python\'u öldürür ve mabedi kurar. Ama kehanetin ruhu kaybolmaz: Pythia, Python\'un nefesinin çıktığı yarıktan yükselen buharı içerek kehanet söyler. Öldürülen güç, taşıyıcı değişince de konuşmaya devam eder.', en: 'When Apollo arrives at Delphi it is under the sovereignty of Python — the kingdom of earth, the unconscious, raw prophecy. Apollo slays Python and builds the temple. But the spirit of prophecy does not vanish: the Pythia speaks prophecy breathing the vapors rising from the fissure where Python\'s breath emerged. The slain power continues to speak even as the carrier changes.' },
      { tr: 'Zulu geleneğinde bir savaşçı, pitonun köy yakınında göründüğünü söyler. Köylüler korkar, onu öldürmek ister. Yaşlı şaman durur: "Bu Python, dedenin ruhudur. Sizi uyarıyor." O gece köy ateş tehlikesinden kurtulur. Piton ertesi sabah kaybolmuştur; ama onun gittiği yöne bir su kaynağı bulunur.', en: 'In Zulu tradition a warrior reports a python seen near the village. The villagers are afraid and want to kill it. The elder shaman stops them: "This python is the spirit of your grandfather. It is warning you." That night the village is saved from the danger of fire. By morning the python has gone; but in the direction it left, a water source is found.' },
    ],
  },

  // ─── a087 Albatros ──────────────────────────────────────────────────────
  a087: {
    jung: { tr: '"Sonsuz Yolcu" ve "Rüzgâr Gezgini" arketipi. Albatros, hedef olmaksızın yolun kendisi olan, varışa değil yolculuğa teslim olmuş bilinçdışı özgürlük dürtüsünü simgeler. Jung\'un "individuasyon" yolculuğunu en isabetli imgeleyen hayvan — yıllarca okyanusta, kıyıya değmeden uçar.', en: '"Eternal Wanderer" and "Wind Traveler" archetype. The albatross symbolizes the unconscious impulse of freedom that is the path itself without destination, surrendered not to arrival but to the journey. The animal that most aptly images Jung\'s "individuation" journey — it flies for years over the ocean, never touching shore.' },
    dream: { tr: 'Albatros rüyada — uzun ve yorucu bir yolculuğun tam ortasındasın. Süzülüyorsa: çaba değil teslim, rüzgâra bırak kendini. Yorgunsa ve alçak uçuyorsa: dinlenme vakti; güç toplamadan ilerleyemezsin.', en: 'Albatross in dream — you are right in the middle of a long and exhausting journey. If it glides: not effort but surrender, release yourself to the wind. If it is weary and flying low: time to rest; you cannot move forward without gathering strength.' },
    shadow: { tr: 'Köksüzlük ve yüzeysel özgürlük. Albatros enerjisi sapkınlaştığında, kişi hiçbir yere konmaz, hiçbir şeyle kök salmaz — derinliği olmayan bir gezginliğe sığınır. Bağ kurmaktan kaçınmak "özgürlük" diye sunulur.', en: 'Rootlessness and superficial freedom. When albatross energy turns perverse, the person lands nowhere, roots in nothing — takes refuge in a wandering that has no depth. Avoidance of forming bonds is presented as "freedom."' },
    whenAppears: { tr: 'Uzun bir süreç ya da ilişkinin ortasında tükendiğinde; hayatının büyük bir bölümünün anlamını sorguladığında.', en: 'When you are exhausted in the middle of a long process or relationship; when you question the meaning of a large portion of your life.' },
    traditions: [
      { culture: { tr: 'Denizci Geleneği', en: 'Sailor Tradition' }, meaning: { tr: 'Albatros, denizde ölen denizcilerin ruhunu taşır — öldürülmesi büyük uğursuzluk getirir. Coleridge\'in Eski Denizci\'sinde bu inanç trajik olarak işlenir.', en: 'The albatross carries the souls of sailors who died at sea — killing one brings great misfortune. This belief is tragically explored in Coleridge\'s Rime of the Ancient Mariner.' } },
      { culture: { tr: 'Polinesya', en: 'Polynesian' }, meaning: { tr: 'Büyük kanatla uçan kuşlar, deniz yolcularına yön gösterir. Albatros varlığı, karaya yaklaşıldığını ya da güvenli suyun işaretini verir.', en: 'Birds flying with great wings guide ocean voyagers. The presence of the albatross signals that land is near or marks safe water.' } },
      { culture: { tr: 'İngiliz Romantizmi', en: 'English Romanticism' }, meaning: { tr: 'Coleridge — "Eski Denizci\'nin Türküsü": Bir denizci albatrosu öldürür; lanet başlar. Doğa ile insanlık arasındaki ahdin ihlali, yalnızlık ve sürgünü getirir.', en: 'Coleridge — "The Rime of the Ancient Mariner": A sailor kills an albatross; the curse begins. Violation of the covenant between nature and humanity brings solitude and exile.' } },
      { culture: { tr: 'Maori', en: 'Māori' }, meaning: { tr: 'Toroa — dev albatros. Tangaroa\'nın, deniz tanrısının temsilcisi. Okyanusun sınırsızlığını ve atalar ruhunu taşır.', en: 'Toroa — the great albatross. Representative of Tangaroa, god of the sea. Carries the boundlessness of the ocean and the spirit of ancestors.' } },
      { culture: { tr: 'Bilimsel Gözlem', en: 'Scientific Observation' }, meaning: { tr: 'Albatros, rüzgâr olmadan hareket etmez — "dinamik süzülme" denen teknikle, sıfır kas enerjisiyle binlerce kilometre kat eder. Doğanın mükemmel verimliliği.', en: 'The albatross does not move without wind — using a technique called "dynamic soaring," it covers thousands of kilometers with zero muscular energy. Nature\'s perfect efficiency.' } },
    ],
    myths: [
      { tr: 'Coleridge\'in şiirinde Eski Denizci, yolculuklarında kendisine eşlik eden albatrosu hiç sebep vermeksizin öldürür. Mürettebat önce kızar, sonra fırtınanın durmasıyla denizciye hak verir. Ama denizci lanetlenmiştir: tüm arkadaşları ölür, o yaşar — boynunda albatrosu ile. Lanet, ancak başka canlıları kalp dolusu sevdiğinde çözülür. Suç değil sevememe; arınma değil sevinçle sevmek.', en: 'In Coleridge\'s poem the Ancient Mariner kills the albatross that accompanied him on his voyages for no reason. The crew first grows angry, then vindicates the sailor when the storm stops. But the mariner is cursed: all his companions die, he lives — with the albatross around his neck. The curse is lifted only when he loves other creatures with a full heart. Not the crime but the inability to love; not purification but loving with joy.' },
      { tr: 'Polinesya yolculuk mitlerinde büyük kanatçılar, bir adadan ötekine giden kanoculara eşlik eder. Bir efsaneye göre bir denizci kaybolmuş ve üç gün yön bulamazken, ufukta beliren tek albatros onu kıyıya götürür. Denizci döndüğünde albatrosun gözünde babasının bakışını gördüğünü anlatır.', en: 'In Polynesian voyage myths, great-winged birds accompany canoe paddlers from one island to the next. According to one legend, a sailor who is lost and cannot find direction for three days is led to shore by a single albatross appearing on the horizon. When the sailor returns he says he saw his father\'s gaze in the albatross\'s eye.' },
    ],
  },

  // ─── a088 Flamingo ──────────────────────────────────────────────────────
  a088: {
    jung: { tr: '"Zarafet" ve "Topluluk Dengesi" arketipi. Flamingo, bireyselliği yok etmeden topluluğun ritminde bütünleşen, hem estetik hem sosyal bilinci simgeler. Jung\'un "persona" ile "gerçek benlik" arasındaki ince denge — toplulukla dans ederken kendini kaybetmemek.', en: '"Grace" and "Community Balance" archetype. The flamingo symbolizes both aesthetic and social consciousness that integrates into the rhythm of community without erasing individuality. The fine balance between Jung\'s "persona" and "true self" — not losing oneself while dancing with the community.' },
    dream: { tr: 'Flamingo rüyada — topluluk içindeki yerine dair mesajlar var. Pembe toplu dans ediyorsa: topluluğuna katıl, uyum gücünü küçümseme. Tek başına solgunsa: kendini bastırarak uyum sağlamaya çalışıyorsun.', en: 'Flamingo in dream — there are messages about your place within community. If they dance pink together: join your community, do not underestimate the power of harmony. If alone and faded: you are trying to conform by suppressing yourself.' },
    shadow: { tr: '"Hep birlikte" baskısı ve farklılığın yok edilmesi. Flamingo enerjisi sapkınlaştığında, topluluk adına bireysel ses bastırılır. "Herkes böyle" çoğulculuğu, gerçek dönüşümü engeller. Pembe görünmek zorunlu olur.', en: 'The pressure of "all together" and the erasure of difference. When flamingo energy turns perverse, the individual voice is suppressed in the name of community. The pluralism of "everyone does so" blocks genuine transformation. Appearing pink becomes compulsory.' },
    whenAppears: { tr: 'Bir gruba ait olup olmama sorusunu yaşarken; kendini göstermek ile uyum arasında sıkışıp kaldığında.', en: 'While living the question of whether to belong to a group; when you are caught between showing yourself and conforming.' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian' }, meaning: { tr: 'Ra\'nın erken biçimi flamingo olarak tasvir edilmiştir. Kızıl-pembe rengi, doğan güneşin alevini simgeler — gün başlangıcının kuşu.', en: 'An early form of Ra was depicted as a flamingo. Its red-pink color symbolizes the flame of the rising sun — the bird of the day\'s beginning.' } },
      { culture: { tr: 'Aztek', en: 'Aztec' }, meaning: { tr: 'Quetzal\'ın pembe kardeşi olarak görülen flamingo, adak törenlerinde soyluluğu ve güneşin yeryüzündeki yansımasını simgeler.', en: 'Seen as the pink sibling of the quetzal, the flamingo symbolizes nobility and the earth\'s reflection of the sun in offering ceremonies.' } },
      { culture: { tr: 'Hint', en: 'Indian' }, meaning: { tr: 'Hans — ruhsal saflığın kuşu. Beyaz veya pembe rengiyle maddi kirlilikten arınmış zihin halini simgeler; bilge kişi "hansa" olarak anılır.', en: 'Hans — the bird of spiritual purity. With its white or pink color it symbolizes a mental state purified of material impurity; a wise person is called "hansa."' } },
      { culture: { tr: 'Karayip', en: 'Caribbean' }, meaning: { tr: 'Bahamalar\'ın ulusal kuşu. Lagün sularının pembeye boyandığı manzara, cömertliğin ve bolluğun imgesidir.', en: 'National bird of the Bahamas. The landscape of lagoon waters dyed pink is an image of generosity and abundance.' } },
      { culture: { tr: 'Modern Sembolizm', en: 'Modern Symbolism' }, meaning: { tr: 'Flamingo, 1950\'lerden itibaren pop kültürde eğlence, zarafet ve anti-konformizmin ironik simgesi olmuştur — toplu uyumun içinde bireysel estetik jest.', en: 'Since the 1950s the flamingo has become an ironic symbol of amusement, grace, and anti-conformism in pop culture — an individual aesthetic gesture within collective conformity.' } },
    ],
    myths: [
      { tr: 'Mısır mitinde Ra\'nın ilk biçimi, kılıçbaltası gaga taşıyan pembe bir kuştu. Nun\'un ilk sularından yükseldiğinde, kanadını çırpması güneşin ilk ışıklarını yarattı. O zamandan beri flamingo her şafakta o ilk anı hatırlar ve rengini güneşe borçlu olduğunu bilir.', en: 'In Egyptian myth Ra\'s first form was a pink bird bearing a scimitar beak. When it rose from the primordial waters of Nun, its wing beat created the first rays of sunlight. Since then the flamingo remembers that first moment at every dawn and knows it owes its color to the sun.' },
      { tr: 'Bir Karayip efsanesine göre flamingolar eski bir göçün kaybolan halkının ruhlarıdır. Denizde boğulanlar, günbatımının rengine boyanmış kuşlara dönüşür. Toplu dans ettiklerinde atalarını anarlar; tek kaldıklarında o kayboluşun acısını taşırlar. Bu yüzden flamingo hiçbir zaman tam yalnız kalmak istemez.', en: 'According to a Caribbean legend, flamingos are the souls of a lost people from an ancient migration. Those who drowned at sea transform into birds dyed in the color of sunset. When they dance together they honor their ancestors; when alone they carry the pain of that disappearance. This is why the flamingo never wishes to be completely alone.' },
    ],
  },

  // ─── a089 Manta Vatoz ───────────────────────────────────────────────────
  a089: {
    jung: { tr: '"Derinlik Yolcusu" ve "Özgür Ruh" arketipi. Manta vatoz, bilinçdışının en derin, en karanlık sularında akıntıya direnmeden süzülme becerisini simgeler. Jung\'un "okyanusal duygu" kavramıyla örtüşür — sınırların eridiği, benliğin evrensele açıldığı o geniş su altı sessizliği.', en: '"Depth Traveler" and "Free Spirit" archetype. The manta ray symbolizes the ability to glide without resisting the current in the deepest, darkest waters of the unconscious. It overlaps with Jung\'s concept of "oceanic feeling" — that vast underwater silence where boundaries dissolve and the self opens to the universal.' },
    dream: { tr: 'Manta vatoz rüyada — derin duygusal sularda bir yolculuk var. Kanatlarını açıp yavaş süzülüyorsa: teslim ol, akışa bırak kendini, mücadele etme. Suyun yüzeyine çıkıp atlıyorsa: bilinçdışından bir gerçek yüzeye vurmak üzere.', en: 'Manta ray in dream — there is a journey in deep emotional waters. If it opens wings and glides slowly: surrender, release yourself to the flow, do not struggle. If it breaches the surface and leaps: a truth from the unconscious is about to surface.' },
    shadow: { tr: 'Derinliğe kaçış ve gerçeklikten kopuş. Manta enerjisi sapkınlaştığında, kişi yüzeyde yaşamı reddeder ve sürekli "daha derin" bir anlam arar — gündelik sorumluluktan, ilişkilerden ve bedensellikten kaçış mistik bir kılık giyer.', en: 'Escape into depth and disconnection from reality. When manta energy turns perverse, the person rejects life on the surface and constantly seeks a "deeper" meaning — escape from everyday responsibility, relationships, and embodiment wears a mystical disguise.' },
    whenAppears: { tr: 'Duygusal bir konuyu bastırıp bastırmadığını sorguladığında; hayatın büyük akışına kendini bırakmakla kontrol arasında kaldığında.', en: 'When you question whether you are suppressing an emotional subject; when you are caught between surrendering to the great flow of life and maintaining control.' },
    traditions: [
      { culture: { tr: 'Polinesya', en: 'Polynesian' }, meaning: { tr: 'Manta vatoz, Tangaroa\'nın — deniz tanrısının — elçisi. Deniz yolculuklarında görülmesi iyi hava ve güvenli geçişin işareti.', en: 'The manta ray is the messenger of Tangaroa — god of the sea. Sighting one during ocean voyages is a sign of good weather and safe passage.' } },
      { culture: { tr: 'Meksika-Pasifik', en: 'Mexican-Pacific' }, meaning: { tr: 'Mantanın kanatlarını açık uçuşu, okyanusun "uçan kardeşi" olarak görülür. Balıkçılar mantayı selamlayarak okyanus ruhunu onurlandırır.', en: 'The manta\'s open-winged flight is seen as the ocean\'s "flying sibling." Fishermen greet the manta to honor the ocean spirit.' } },
      { culture: { tr: 'Endonezya', en: 'Indonesian' }, meaning: { tr: 'Komodo adaları çevresinde manta, ata ruhunu taşıdığına inanılan kutsal hayvan. Zarar vermek yasaktır; onunla yüzmek kutsama sayılır.', en: 'Around the Komodo islands, the manta is a sacred animal believed to carry ancestral spirit. Harming one is forbidden; swimming with one is considered a blessing.' } },
      { culture: { tr: 'Modern Okyanografi', en: 'Modern Oceanography' }, meaning: { tr: 'Manta vatozun beyninin oransal büyüklüğü, balıklar arasında en yüksek olanlardan biridir. Ayna testinde kendini tanıyan nadir canlılardandır — derin zekânın simgesi.', en: 'The proportional brain size of the manta ray is among the highest of any fish. It is one of the rare creatures that recognizes itself in the mirror test — a symbol of deep intelligence.' } },
      { culture: { tr: 'Japon', en: 'Japanese' }, meaning: { tr: 'Okinawa balıkçı geleneklerinde manta "denizin hâkimi" olarak adlandırılır. Rüyada görülmesi, bir yolculuğun ya da büyük bir kararın eşiğinde olunduğunu gösterir.', en: 'In Okinawa fishing traditions the manta is called "sovereign of the sea." Seeing one in dream signals that one stands on the threshold of a journey or major decision.' } },
    ],
    myths: [
      { tr: 'Polinesya deniz mitolojisinde Tangaroa bir gün okyanusun dibine iner ve orada hiçbir ışık olmadan yaşayan varlıkları bulur. En büyüğü, kanatlarını okyanusun tabanına açmış bir Manta vatozdur. Tangaroa sorar: "Işıksız nasıl yaşarsın?" Manta cevaplar: "Işık arama, dalga ol." O günden beri manta, karanlık sulardaki bilgeliğin simgesidir.', en: 'In Polynesian sea mythology, Tangaroa one day descends to the ocean\'s floor and finds beings living there without any light. The greatest of them is a Manta ray with wings spread across the ocean floor. Tangaroa asks: "How do you live without light?" The manta answers: "Do not seek light, be the wave." From that day the manta has been the symbol of wisdom in dark waters.' },
      { tr: 'Bir Meksika balıkçı hikâyesinde genç bir denizci büyük fırtınada kaybolur. Üç gün sonra kıyıya döner ve dev bir manta vatozun sırtında denizi geçtiğini anlatır. Kimse inanmaz. Ama sonraki yıl aynı manta, bu kez bir başka kayık içindeki çocuğu güvene taşır. Bazı şeyler inanılmak için değil, yaşanmak için vardır.', en: 'In a Mexican fisherman\'s story, a young sailor is lost in a great storm. Three days later he returns to shore and tells of crossing the sea on the back of a giant manta ray. No one believes him. But the following year the same manta carries a child in another stranded boat to safety. Some things exist not to be believed, but to be lived.' },
    ],
  },

  // ─── a090 Yele Kurdu ────────────────────────────────────────────────────
  a090: {
    jung: { tr: '"Yalnız Kahraman" ve "Köprü Kurucu" arketipi. Yele kurdu, ne tam sürüye ne tam yabana ait olan, bu araf konumuyla iki dünyanın arasındaki geçişi mümkün kılan enerjiyi simgeler. Jung\'un "individue" figürü — toplumdan ayrışmadan özgünleşen, sınır koruyucu.', en: '"Solitary Hero" and "Bridge Builder" archetype. The maned wolf symbolizes the energy that belongs neither fully to the pack nor fully to the wild, and through this liminal position makes passage between two worlds possible. Jung\'s "individual" figure — becoming authentic without separating from society, the boundary guardian.' },
    dream: { tr: 'Yele kurdu rüyada — ait olmama hissini taşıyorsun ama bu yalnızlık güçtür. Koşuyorsa ve yalnızsa: özgün yolunda devam et, sürü seni yavaşlatır. Sana bakıyorsa ve gözleri parlıyorsa: kendi özgünlüğünü görme vakti geldi.', en: 'Maned wolf in dream — you carry the feeling of not belonging but this solitude is strength. If it runs and is alone: continue on your authentic path, the pack will slow you down. If it looks at you and its eyes gleam: the time has come to see your own uniqueness.' },
    shadow: { tr: 'Cronizm ve anlaşılamamışlık saplantısı. Yele kurdunun "ne sürü ne yabani" enerjisi sapkınlaştığında, kişi hiçbir yere ait olmama acısını kronik yalnızlık ve başkalarını anlayamama biçiminde yaşar. "Kimse beni anlamaz" anlatısı, gerçek bağ kurmanın önüne geçer.', en: 'Chronicism and obsession with being misunderstood. When the maned wolf\'s "neither pack nor wild" energy turns perverse, the person experiences the pain of belonging nowhere as chronic loneliness and inability to understand others. The narrative "no one understands me" blocks the formation of genuine bonds.' },
    whenAppears: { tr: 'Hiçbir kategoriye uymadığını fark ettiğinde; özgün bir yol açmak zorunda olduğunu bildiğin ama yalnızlığından korktuğun anlarda.', en: 'When you realize you fit no category; in moments when you know you must open an original path but fear your solitude.' },
    traditions: [
      { culture: { tr: 'Brezilya', en: 'Brazilian' }, meaning: { tr: 'Guará — Cerrado\'nun sembolü, sınır hayvanı. Ne kurt ne tilki. Brezilya halk inanışında hem şifacı hem tehlikeli, hem ormancı hem savanacı.', en: 'Guará — symbol of the Cerrado, the border animal. Neither wolf nor fox. In Brazilian folk belief, both healer and dangerous, both forest dweller and savanna creature.' } },
      { culture: { tr: 'Guaraní Yerli Kültürü', en: 'Guaraní Indigenous Culture' }, meaning: { tr: 'Yele kurdu, ruhların taşıyıcısı. Ormanlıktan savana geçerken ata ruhlarına eşlik eder. Görülmesi, dönüşümün habercisi sayılır.', en: 'The maned wolf is a carrier of spirits. It accompanies ancestral spirits in passing from forest to savanna. Being sighted is considered a herald of transformation.' } },
      { culture: { tr: 'Bilimsel Gözlem', en: 'Scientific Observation' }, meaning: { tr: '"Tek tür cins" — Chrysocyon brachyurus. Ne Canis ailesinde ne başka bir grupta. Evrimsel yalnızlık; en yakın akrabasından 6 milyon yıl önce ayrılmış.', en: '"Single species genus" — Chrysocyon brachyurus. Neither in the Canis family nor in any other group. Evolutionary solitude; separated from its nearest relative 6 million years ago.' } },
      { culture: { tr: 'Modern Koruma Etiği', en: 'Modern Conservation Ethics' }, meaning: { tr: 'Yele kurdu, biyoçeşitlilik göstergesi — Cerrado ekosistemi sağlıklıysa o orada. Kayboluşu tüm ekosistemin krizi demektir; köprü olmadan iki taraf da çöker.', en: 'The maned wolf is a biodiversity indicator — if the Cerrado ecosystem is healthy, it is there. Its disappearance means crisis for the entire ecosystem; without the bridge both sides collapse.' } },
      { culture: { tr: 'Şaman Geleneği — Güney Amerika', en: 'Shamanic Tradition — South America' }, meaning: { tr: 'Yele kurdu şamanın yol hayvanı. Sınır geçişlerinde, iki dünya arasındaki geçişlerde şamana rehberlik eden köprü varlığı.', en: 'The maned wolf is the shaman\'s path animal. The bridge being that guides the shaman through border crossings, in transitions between two worlds.' } },
    ],
    myths: [
      { tr: 'Guaraní geleneğinde yele kurdu, yaratılışın tamamlanmamış bir parçasıdır. Tanrı Ñamandú her hayvanı bir kategoriye koyarken, yele kurdunu tam yaratmayı unutur. Ama bu "unutuluş" onu özgür kılar: ne sürüde ne tümüyle yalnız, ne ormanda ne savanada — iki dünyanın tüm bilgisini taşır ve bu yüzden şifacıdır.', en: 'In Guaraní tradition the maned wolf is an uncompleted piece of creation. While the god Ñamandú places every animal into a category, he forgets to finish creating the maned wolf. But this "forgetting" sets it free: neither in the pack nor entirely alone, neither in forest nor savanna — it carries the full knowledge of two worlds and for this reason it is a healer.' },
      { tr: 'Bir Brezilya efsanesine göre Cerrado\'nun ruhları bir gün toplanır ve en büyük tehlikeyi konuşur. Ormandan savanaya geçen yangın her şeyi yakacaktır. Küçük hayvanlar panikler, büyük hayvanlar kaçar. Yalnızca yele kurdu, iki bölgeyi de bilen tek varlık olarak, bir su yolu keşfeder ve iki halkı birbirine bağlar. Yangın geçer; yele kurdu ne bir tarafın ne ötekinin kahramanıdır — yalnızca köprüdür.', en: 'According to a Brazilian legend, the spirits of the Cerrado gather one day and speak of the greatest danger. A fire crossing from forest to savanna will burn everything. Small animals panic, large animals flee. Only the maned wolf, as the single being who knows both regions, discovers a waterway and connects the two peoples to each other. The fire passes; the maned wolf is neither the hero of one side nor the other — it is simply the bridge.' },
    ],
  },

  // ─── a091 Ateş Kuşu ─────────────────────────────────────────────────────
  a091: {
    jung: { tr: '"Arzu ve İlham" arketipi. İçteki yaratıcı ateşin kişileşmiş hâli — bastırıldığında söner, serbest bırakıldığında dünyayı aydınlatır. Ateş Kuşu, ruhun en canlı anını simgeler: peşinden koşmayı hak ettiğin o şeyin kendisi.', en: '"Desire and Inspiration" archetype. The personified form of the inner creative fire — when suppressed it dims, when released it illuminates the world. The Firebird embodies the most vivid moment of the soul: the very thing you deserve to pursue.' },
    dream: { tr: 'Ateş Kuşu rüyada — içindeki bir arzunun artık susturulamayacağının işareti. Uzaklaşıyorsa: onu kovalamaktan vazgeçiyorsun; yaklaşıyorsa: ilham kapına gelmiş, kapıyı açmak sana kalmış.', en: 'The Firebird in dream — a sign that a desire within you can no longer be silenced. If it flies away: you are giving up the chase; if it approaches: inspiration has come to your door, opening it is up to you.' },
    shadow: { tr: 'Ateşin yıkıcı yüzü: arzu bir tutkuya değil, bir saplantıya dönüştüğünde her şeyi yakar. Başkalarının enerjisini tüketmek ya da kendi hayalinde kaybolup somut adım atmamak — Ateş Kuşu\'nun gölgesidir.', en: 'The destructive face of fire: when desire turns not into passion but obsession, it burns everything. Consuming others\' energy or losing oneself in one\'s own dream without taking concrete steps — these are the shadows of the Firebird.' },
    whenAppears: { tr: 'Yıllardır ertelediğin bir hayalin kapısında durduğunda, ya da bir tutkuyu "bana göre değil" diyerek içine gömdüğünde.', en: 'When you stand at the door of a dream you have postponed for years, or when you bury a passion inside yourself saying "it\'s not for me".' },
    traditions: [
      { culture: { tr: 'Slav Mitolojisi', en: 'Slavic Mythology' }, meaning: { tr: 'Zhar-Ptitsa — tüyleri şans ve lanet getiren, yakalanması imkânsız ışık kuşu.', en: 'Zhar-Ptitsa — the luminous bird whose feathers bring fortune and curse alike, impossible to capture.' } },
      { culture: { tr: 'Japon', en: 'Japanese' }, meaning: { tr: 'Hō-ō (Feniks) — dürüstlük ve refahın habercisi; yalnızca erdemli bir hükümdar döneminde görünür.', en: 'Hō-ō (Phoenix) — herald of virtue and prosperity; seen only in the reign of a righteous ruler.' } },
      { culture: { tr: 'Türk-Altay Şamanizmi', en: 'Turkic-Altaic Shamanism' }, meaning: { tr: 'Alev ruhlu kuş — şamanın gökyüzü yolculuğunda rehberi; ilham ruhunun dışa vurumu.', en: 'The flame-souled bird — guide of the shaman\'s celestial journey; the outward expression of the spirit of inspiration.' } },
      { culture: { tr: 'Hint', en: 'Indian' }, meaning: { tr: 'Garuda\'nın ateş formu — tanrısal gücün ve yaratıcı enerjinin taşıyıcısı.', en: 'The fire form of Garuda — carrier of divine power and creative energy.' } },
      { culture: { tr: 'İran Mitolojisi', en: 'Iranian Mythology' }, meaning: { tr: 'Hüma kuşu — başının üzerinden geçtiği kişiyi tahta çıkaran, hükümdarlık kaderini ateşleyen kuş.', en: 'The Huma bird — the bird that crowns whoever passes beneath its shadow, igniting the destiny of kingship.' } },
    ],
    myths: [
      { tr: 'Rus masalında Ivan Çareviç, Ateş Kuşu\'nun düşürdüğü bir tüyü bulur. Babası onu getirmesini ister — bu yolculuk onu dünyanın ucuna götürür, imkânsız görevler verilir. Her seferinde tüyü bırakmayı düşünür ama içindeki o küçük ışık onu ileri iter. Kuşu yakalar; ama artık kuş değil, kendi cesareti ödüldür.', en: 'In a Russian tale, Ivan Tsarevich finds a feather dropped by the Firebird. His father bids him bring the bird — the journey takes him to the ends of the earth, impossible tasks are set before him. Each time he thinks of abandoning the feather, yet that small inner light pushes him forward. He captures the bird; but by then, the prize is not the bird — it is his own courage.' },
      { tr: 'Anadolu ozanları Ateş Kuşu\'nu içteki ilham sesine benzetir: "Onu bir kez görürsen artık sıradan hayata dönemezsin." Görmek bile insanı dönüştürür; çünkü arzu, onu taşıyan kişinin bizzat kendisidir.', en: 'Anatolian bards liken the Firebird to the voice of inner inspiration: "Once you have seen it, you can no longer return to an ordinary life." Even the seeing transforms a person; for desire is none other than the one who carries it.' },
    ],
  },

  // ─── a092 Deve Kuşu ──────────────────────────────────────────────────────
  a092: {
    jung: { tr: '"Gerçekle Yüzleşme" arketipi. Deve Kuşu\'nun başını kuma gömmesi bir efsanedir — gerçekte en hızlı kaçan değil, en sert koşan o\'dur. Psikolojik olarak: topraktan güç alan, gerçeği ne kadar ağır olursa olsun taşıma kapasitesini simgeler.', en: '"Confronting Reality" archetype. The ostrich burying its head in the sand is a myth — in truth it is not the fastest to flee, but the hardest to run. Psychologically: it embodies drawing power from the earth, the capacity to carry truth no matter how heavy.' },
    dream: { tr: 'Deve Kuşu rüyada — kaçınmakta olduğun bir gerçeğin varlığına işaret eder. Koşuyorsa: yüzleşme zamanı gelmiş, hız senin yanındadır; bekliyor ya da duruyorsa: saklamaya çalıştığın şey zaten görünüyor.', en: 'The ostrich in dream — points to the presence of a truth you are avoiding. If it runs: the time for confrontation has come, speed is on your side; if it stands still or waits: what you try to hide is already visible.' },
    shadow: { tr: '"Baş kuma gömme" sendromu — sorunları görmezden gelerek büyümelerine izin vermek. Deve Kuşu gölgesindeki kişi kriz çıkmadan önce işaret fişeklerini fark etmeyi reddeder; toprak gücünü savunmaya değil inkâra kullanır.', en: 'The "head in the sand" syndrome — ignoring problems and allowing them to grow. The person in ostrich\'s shadow refuses to notice the warning signals before a crisis erupts; uses the power of earth not for defense but for denial.' },
    whenAppears: { tr: 'Uzun süredir görmezden geldiğin bir durumun artık kaçınılmaz hale geldiği anlarda; gerçeği söylemenin ya da duymanın tam sırası olduğunda.', en: 'At the moments when a situation you have long ignored becomes unavoidable; when it is exactly time to speak or hear the truth.' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian' }, meaning: { tr: 'Deve Kuşu tüyü Ma\'at\'ın sembolüydü — ölçekte ruha karşı tartılırdı; eşit ağırlıkta olan ruh arınmış sayılırdı.', en: 'The ostrich feather was the symbol of Ma\'at — weighed against the soul on the scales; the soul balanced by it was deemed pure.' } },
      { culture: { tr: 'Afrika (Maasai)', en: 'African (Maasai)' }, meaning: { tr: 'Deve Kuşu yumurtası doğurganlık ve uzun ömür armağanı olarak kabul edilir; büyük törenlerde sunulur.', en: 'The ostrich egg is regarded as a gift of fertility and long life; offered at great ceremonies.' } },
      { culture: { tr: 'Arap Kültürü', en: 'Arab Culture' }, meaning: { tr: '"Devekuşu aklı" deyimi kararlılıkla hareket etmek yerine bekleyip seyretmeyi anlatır — ama deve kuşu aslında en hızlı kara kuşudur.', en: 'The expression "ostrich mind" describes watching and waiting instead of acting decisively — yet the ostrich is in fact the fastest of all land birds.' } },
      { culture: { tr: 'Roma', en: 'Roman' }, meaning: { tr: 'Romalılar deve kuşunu dayanıklılığın simgesi olarak ziyafetlerde sunardı; sindiremeyeceği hiçbir şey yok denirdi.', en: 'Romans offered ostrich at feasts as a symbol of endurance; it was said there was nothing it could not digest.' } },
      { culture: { tr: 'Hristiyanlık (Orta Çağ)', en: 'Christianity (Medieval)' }, meaning: { tr: 'Ortaçağ ressamları deve kuşunu terk edilmiş yumurtasıyla çizerdi — insanın ilahi ilgiyi unutması metaforu.', en: 'Medieval painters depicted the ostrich with its abandoned egg — a metaphor for humanity forgetting divine attention.' } },
    ],
    myths: [
      { tr: 'Afrika\'nın bir efsanesine göre deve kuşu eskiden uçabilirdi. Ama bir gün gökyüzünden yere bir çocuğun ağlamasını duydu, indi ve bir daha çıkamadı. Toprak onu tuttu — çünkü merhametle yere inen, artık toprağın gücünü taşır.', en: 'According to an African legend the ostrich could once fly. But one day it heard a child crying from the earth below, descended, and could never rise again. The earth held it — for one who descends with compassion henceforth carries the power of the earth.' },
    ],
  },

  // ─── a093 Kilin ──────────────────────────────────────────────────────────
  a093: {
    jung: { tr: '"Kutsal Nadir" arketipi. Kilin varlığı bile bir lütuf sayılır; Jung\'un "numinous" kavramını cisimleştirir — karşılaşıldığında akıl susar, yalnızca hayret konuşur. Dürüstlüğün ve içsel erdeminun dışa vurumudur: görünmez olmak için değil, yalnızca hazır olanların görebileceği şekilde var olmak.', en: '"Sacred Rarity" archetype. Even the existence of the qilin is considered a grace; it embodies Jung\'s concept of the "numinous" — when encountered, reason falls silent, only wonder speaks. It is the outward form of honesty and inner virtue: not to be invisible, but to exist in a way that only those who are ready can perceive.' },
    dream: { tr: 'Kilin rüyada — olağanüstü bir dönemin eşiğindesin ya da hayatına kutsal bir varlık giriyor. Uzaktan görüyorsan: erdem kazanmaya henüz başlıyorsun; yanına geliyorsa: ruhun olgunlaşmış, saf olanı çekmeye hazır.', en: 'The qilin in dream — you stand on the threshold of an extraordinary period, or a sacred presence is entering your life. If you see it from afar: you are just beginning to earn virtue; if it approaches: your spirit has matured, ready to attract what is pure.' },
    shadow: { tr: 'Nadirliği bir kibire dönüştürmek: "Ben seçilmişim, sıradan insanlar beni anlayamaz" yanılgısı. Kilin gölgesi, erdemi performansa çeviren kişide yaşar — gösteriş için dürüst olan, dürüstlüğünü kaybetmiş demektir.', en: 'Turning rarity into arrogance: the delusion of "I am chosen, ordinary people cannot understand me." The shadow of the qilin lives in the one who turns virtue into performance — one who is honest for show has already lost their honesty.' },
    whenAppears: { tr: 'Uzun bir arayıştan sonra gerçek bir bilginin ya da eşin hayatına girdiğinde; sahici erdem ile gösterişli erdemin arasını ayırt etmen gereken anlarda.', en: 'When a truly wise person or soulmate enters your life after a long search; at the moments you must distinguish genuine virtue from its performance.' },
    traditions: [
      { culture: { tr: 'Çin', en: 'Chinese' }, meaning: { tr: 'Kilin — Dört Kutsal Hayvan\'dan biri; yalnızca erdemli bir hükümdarın saltanatında belirir, ot bile çiğnemez.', en: 'The Qilin — one of the Four Sacred Creatures; appears only in the reign of a virtuous ruler, and does not even trample grass.' } },
      { culture: { tr: 'Japon', en: 'Japanese' }, meaning: { tr: 'Kirin — uzun ömür, bereket ve iyi yönetimin simgesi; görülmesi bir kehanet gibi yorumlanır.', en: 'Kirin — symbol of longevity, abundance, and good governance; its sighting is interpreted as a prophecy.' } },
      { culture: { tr: 'Kore', en: 'Korean' }, meaning: { tr: 'Girin — efsanevi adaletli liderlerin doğumunu müjdeleyen kutsal varlık.', en: 'Girin — the sacred being that heralds the birth of legendarily just leaders.' } },
      { culture: { tr: 'Vietnam', en: 'Vietnamese' }, meaning: { tr: 'Kỳ lân — halk şenliklerinde saf niyetin ve bereketin dansçısı olarak kutlanır.', en: 'Kỳ lân — celebrated in folk festivals as the dancer of pure intention and abundance.' } },
      { culture: { tr: 'Türk-Çin İpek Yolu Kültürü', en: 'Turkic-Chinese Silk Road Culture' }, meaning: { tr: 'Kilin imgesi İpek Yolu kervanlarında uğur sembolü olarak taşınırdı — ticaretin dürüstlüğünün koruyucusu.', en: 'The image of the qilin was carried by Silk Road caravans as a talisman of good fortune — guardian of honesty in trade.' } },
    ],
    myths: [
      { tr: 'Konfüçyüs\'ün annesi, doğumdan önce kilinle karşılaştığını ve hayvanın ona bir jade tablet bıraktığını söyler. Üzerinde "Sui\'nin oğlu, taht devrildiğinde kristal gibi bir kral olacak" yazıyordu. Konfüçyüs dünyaya geldi; ama kral olmadı — bilgeliğiyle bütün bir medeniyetin tahtını kurdu.', en: 'Confucius\'s mother says that before his birth she encountered a qilin, and the creature left her a jade tablet. On it was written: "Son of Sui, when the throne falls, he shall be a king of crystal." Confucius was born; but he became no king — with his wisdom he built the throne of an entire civilization.' },
    ],
  },

  // ─── a094 Su Aygırı ──────────────────────────────────────────────────────
  a094: {
    jung: { tr: '"Dişil Güç ve Doğum" arketipi. Su Aygırı, Büyük Ana\'nın su altındaki yüzüdür — hem besleyici hem sınır koyan, hem doğuran hem koruyandır. Sular üzerindeki egemenliği, dişil bilincin bilinçdışı derinliklerini yönetme kapasitesini temsil eder.', en: '"Feminine Power and Birth" archetype. The hippo is the submerged face of the Great Mother — both nourishing and boundary-setting, both birth-giving and protective. Its sovereignty over the waters represents the feminine mind\'s capacity to govern the depths of the unconscious.' },
    dream: { tr: 'Su Aygırı rüyada — ana karnındaki bir yaratıcılık ya da proje; ya da sınırlarının çiğnendiğinin işareti. Saldırıyorsa: güç alanın ihlal edilmiş, kendini savunma zamanı; suda sessizce duruyorsa: derinlerde bir şey olgunlaşıyor.', en: 'The hippo in dream — a creativity or project still in the womb; or a sign that your boundaries are being violated. If attacking: your power field has been breached, time to defend yourself; if standing silently in water: something is ripening in the depths.' },
    shadow: { tr: 'Su Aygırı\'nın gölgesi: koruma içgüdüsünün bir tahakküme dönüşmesi. Sevdiklerini "koruma" adına boğmak, kendi sularını o kadar sahiplenmek ki başkası nefes alamaz hale gelir — aşırı sahiplenme ve kontrol ihtiyacı.', en: 'The hippo\'s shadow: the protective instinct transforming into domination. Smothering loved ones in the name of "protection," claiming one\'s own waters so completely that others cannot breathe — excessive possessiveness and the need for control.' },
    whenAppears: { tr: 'Bir şeyi ya da birini koruma güdüsünün zirveye çıktığı anlarda; annelik, doğurganlık ya da yaratıcılık temalarının hayatına hâkim olduğu dönemlerde.', en: 'At the moments when the drive to protect something or someone reaches its peak; during periods when themes of motherhood, fertility, or creativity dominate your life.' },
    traditions: [
      { culture: { tr: 'Mısır', en: 'Egyptian' }, meaning: { tr: 'Taweret — hamile kadınların ve doğumun koruyucu tanrıçası; su aygırı başlı, aslan pençeli, timsah kuyruklu.', en: 'Taweret — guardian goddess of pregnant women and childbirth; with a hippo head, lion claws, and a crocodile tail.' } },
      { culture: { tr: 'Mısır (Set)', en: 'Egyptian (Set)' }, meaning: { tr: 'Set bazen su aygırı formunda tasvir edilir — Nil\'deki kaotik gücün ve fırtınanın cisimleşmesi.', en: 'Set is sometimes depicted in hippo form — the embodiment of chaotic power and storm in the Nile.' } },
      { culture: { tr: 'Yunan', en: 'Greek' }, meaning: { tr: 'Hippopotamos — "nehir atı"; Yunanlar onu Nil\'in efendisi olarak hayranlıkla tanımladı.', en: 'Hippopotamos — "river horse"; the Greeks described it with admiration as the master of the Nile.' } },
      { culture: { tr: 'Afrika (Batı Afrika Halkları)', en: 'African (West African Peoples)' }, meaning: { tr: 'Su Aygırı, nehirlerin ve yağmurun ruhudur; ona saygı göstermek sular üzerinde güvenlik sağlar.', en: 'The hippo is the spirit of rivers and rain; showing it respect ensures safety on the waters.' } },
      { culture: { tr: 'İncil (Eyüp Kitabı)', en: 'Biblical (Book of Job)' }, meaning: { tr: 'Behemot — Tanrı\'nın en büyük yaratığı; gücün ve yeryüzü kuvvetinin simgesi.', en: 'Behemoth — God\'s greatest creature; symbol of power and earthly might.' } },
    ],
    myths: [
      { tr: 'Mısır\'ın doğum odalarında Taweret heykeli hep vardı. Doğum yaparken ağrılar dayanılmaz olduğunda kadınlar ona seslenirdi: "Su Ana, ellerini uzat." Nil\'in derinliklerinden güç çektiğine inanılırdı — su nasıl her şeyi doğurursa, Taweret de her doğumda anaya su aygırının direncini verirdi.', en: 'The statue of Taweret was always present in Egyptian birthing rooms. When the pain of labor became unbearable, women would call to her: "Water Mother, extend your hands." She was believed to draw power from the depths of the Nile — just as water gives birth to everything, so Taweret gave every laboring mother the resilience of the hippo.' },
    ],
  },

  // ─── a095 Anakonda ───────────────────────────────────────────────────────
  a095: {
    jung: { tr: '"Kozmik Yılan ve Su Bilgeliği" arketipi. Anakonda, Uroboros\'un Amazon teki — başını yutan yılan değil, suyu saran yılan. Bilinçdışının en ilkel katmanını, dönüşümün sessiz ve yavaş ama kaçınılmaz doğasını simgeler. Bir şeyi kavradığında bırakmaz; kavrama gücü, neye sarıldığının bilincinde olmayı gerektirir.', en: '"Cosmic Serpent and Water Wisdom" archetype. The anaconda is the Amazon\'s Uroboros — not the serpent swallowing its tail, but the serpent embracing the water. It embodies the most primal layer of the unconscious, the silent and slow yet inevitable nature of transformation. When it grasps something it does not let go; the power of grasping requires awareness of what one holds.' },
    dream: { tr: 'Anakonda rüyada — psikenin derinliklerinden bir dönüşüm mesajı. Sarıyorsa: hayatındaki bir durum seni dönüştürüyor, direnmek değil teslim olmak gerekiyor; suda kayboluyorsa: bilinçaltın bir sırrı yutmuş, hazır olduğunda yüzeyine çıkacak.', en: 'The anaconda in dream — a message of transformation from the depths of the psyche. If it coils around you: a situation in your life is transforming you, not resistance but surrender is needed; if it disappears into water: your unconscious has swallowed a secret, it will surface when you are ready.' },
    shadow: { tr: 'Boğma enerjisi: kontrolü ele geçirmek için etrafındakileri yavaş yavaş sıkıştırmak. Anakonda gölgesindeki kişi sevgi adına özgürlüğü söndürür; sahip olduğu her şeyi o kadar sıkı sarar ki içindeki yaşam kımıldayamaz hale gelir.', en: 'The smothering energy: slowly tightening around those nearby to seize control. The person in anaconda\'s shadow extinguishes freedom in the name of love; wraps everything they possess so tightly that the life within can no longer stir.' },
    whenAppears: { tr: 'Derin bir dönüşüm geçirmekte olduğun ve buna direnmekten vazgeçmen gereken dönemlerde; ya da bilinçdışının bir mesajını artık görmezden gelemeyeceğin anlarda.', en: 'During periods of deep transformation when you must cease resisting it; or at moments when you can no longer ignore a message from your unconscious.' },
    traditions: [
      { culture: { tr: 'Amazon Yerlileri (Desana)', en: 'Amazon Peoples (Desana)' }, meaning: { tr: 'Büyük Yılan Anaconda — nehirlerin atası; dünyanın yaratılışında suyu taşıyan omurga.', en: 'The Great Serpent Anaconda — ancestor of rivers; the spine that carried the waters at the creation of the world.' } },
      { culture: { tr: 'Amazon Yerlileri (Yawalpiti)', en: 'Amazon Peoples (Yawalpiti)' }, meaning: { tr: 'Şamanlar anacondayla özdeşleşerek sular altına iner, ölülerin ruhlarıyla konuşur ve şifa getirir.', en: 'Shamans identify with the anaconda to descend beneath the waters, speak with the souls of the dead, and bring healing.' } },
      { culture: { tr: 'Hint', en: 'Indian' }, meaning: { tr: 'Naga yılanları — suların koruyucuları; anakondayla akraba imge, doğurganlık ve dönüşümün simgesi.', en: 'Naga serpents — guardians of the waters; a kindred image to the anaconda, symbol of fertility and transformation.' } },
      { culture: { tr: 'Afrika (Yoruba)', en: 'African (Yoruba)' }, meaning: { tr: 'Oshumare — gökkuşağı yılanı; yaşam döngüsünü, suyu ve dönüşümü yöneten ilahi güç.', en: 'Oshumare — the rainbow serpent; the divine power governing the life cycle, water, and transformation.' } },
      { culture: { tr: 'Avustralya Aborijin', en: 'Australian Aboriginal' }, meaning: { tr: 'Gökkuşağı Yılanı Yurlunggur — su kaynaklarının ve yaratılışın efendisi; totem ve dönüşümün babası.', en: 'Rainbow Serpent Yurlunggur — master of water sources and creation; totem and father of transformation.' } },
    ],
    myths: [
      { tr: 'Amazon şamanları ayahuasca seremonilerinde büyük yılanın geldiğini anlatır: "O seni yuttu mu, dünyayı içinden görürsün." Yutulmak ölüm değil, derinleşmedir. Yılanın karnında dünyanın sırrı saklıdır; oraya giren kişi geri döndüğünde başkadır — kelimenin tam anlamıyla.', en: 'Amazon shamans tell of the great serpent\'s coming in ayahuasca ceremonies: "Once it swallows you, you see the world from inside." Being swallowed is not death, but deepening. The secret of the world is held within the serpent\'s belly; whoever enters it returns as another — in the fullest sense of the word.' },
    ],
  },

  // ─── a096 Tukan ──────────────────────────────────────────────────────────
  a096: {
    jung: { tr: '"Yaratıcı İfade ve Tropik Bilgelik" arketipi. Tukan\'ın devasa, renkli gagası orantısız görünür — ama bu orantısızlık onun gücüdür. Psikolojik olarak: kendi sesini, renklerini ve ifade biçimini aşırı bulmaktan korkmamak demektir. Gaga ne kadar büyükse, söylenecek söz o kadar cesur.', en: '"Creative Expression and Tropical Wisdom" archetype. The toucan\'s enormous, colorful beak appears disproportionate — but this disproportion is its power. Psychologically: it means not being afraid of finding one\'s own voice, colors, and manner of expression excessive. The larger the beak, the bolder the word to be spoken.' },
    dream: { tr: 'Tukan rüyada — ifade etmek isteyip susturduğun bir şeyin sesi yükseliyor. Gagasını açıyorsa: artık konuşma zamanı; renkleri parlıyorsa: özgün olduğun zaman doğru yoldayısındır.', en: 'The toucan in dream — the voice of something you wished to express but silenced is rising. If it opens its beak: it is time to speak at last; if its colors shine: you are on the right path when you are authentic.' },
    shadow: { tr: 'Görünür olmak için her rengi kullanmak — derinliksiz parlaklık. Tukan gölgesi, özgünlük yerine sansasyon arayan kişide belirir; söylemin içeriği değil, rengi öne çıkar. Gösteriş bilgeliğin yerini aldığında tukan susar.', en: 'Using every color just to be visible — brightness without depth. The toucan\'s shadow appears in the person seeking sensation rather than authenticity; it is not the content of speech that comes forward, but the color. When show replaces wisdom, the toucan falls silent.' },
    whenAppears: { tr: 'Yaratıcı sesini bulmak ya da var olan sesini daha özgürce kullanmak üzere olduğunda; renkli, alışılmadık bir ifade biçiminin sana kapı araladığı anlarda.', en: 'When you are about to find your creative voice or use your existing voice more freely; at moments when a colorful, unconventional mode of expression opens a door for you.' },
    traditions: [
      { culture: { tr: 'Maya', en: 'Mayan' }, meaning: { tr: 'Tukan gagası şamanların baş süslemesinde kullanılırdı — öteki âlemlerle konuşmanın sembolü.', en: 'Toucan beaks were used in shamanic headdresses — a symbol of speaking with other realms.' } },
      { culture: { tr: 'Amazon Yerlileri (Kayapó)', en: 'Amazon Peoples (Kayapó)' }, meaning: { tr: 'Tukan tüyleri ritüel giysisinin parçasıdır; ruh dünyasına gidişin renkli rehberi sayılır.', en: 'Toucan feathers are part of ritual dress; considered the colorful guide for journeys to the spirit world.' } },
      { culture: { tr: 'Aztekler', en: 'Aztec' }, meaning: { tr: 'Quetzalcoatl\'ın tropik kuşları arasında tukan da vardır — ilahi iletişimin ve güneşin renkleriyle bezenmiş haberci.', en: 'Among Quetzalcoatl\'s tropical birds the toucan is also counted — a messenger adorned with the colors of divine communication and the sun.' } },
      { culture: { tr: 'Brezilya Halk Kültürü', en: 'Brazilian Folk Culture' }, meaning: { tr: 'Tukan sesi yağmurun habercisi sayılır — doğanın döngüsünde değişimin müjdecisi.', en: 'The toucan\'s call is considered a harbinger of rain — the herald of change in nature\'s cycle.' } },
      { culture: { tr: 'Kolombiya Yerli Kültürleri', en: 'Colombian Indigenous Cultures' }, meaning: { tr: 'Renkli gagası güneşin ve bereketin simgesi; topluluk törenlerinde neşeyi ve şükrü temsil eder.', en: 'Its colorful beak is a symbol of the sun and abundance; in community ceremonies it represents joy and gratitude.' } },
    ],
    myths: [
      { tr: 'Amazon\'un bir efsanesine göre ilk insanlar gri ve sessizdi. Tukan tanrıdan renk istedi: "Dünyayı güzel yapacak sesin ve rengin tek kaynağı benim" dedi. Tanrı güldü ve her renge bir anlam verdi — sarı cesareti, mavi huzuru, kırmızı tutkuyu. Tukan hem bunları taşır hem söyler; bu yüzden söylediğimiz her renkli söz bir tutukun hediyesidir.', en: 'According to an Amazon legend, the first humans were grey and silent. The toucan asked the god for color: "I am the sole source of the voice and color that will make the world beautiful," it said. The god laughed and gave each color a meaning — yellow for courage, blue for peace, red for passion. The toucan both carries and speaks them; thus every colorful word we utter is a gift of the toucan.' },
    ],
  },

  // ─── a097 Dingo ──────────────────────────────────────────────────────────
  a097: {
    jung: { tr: '"Ehlileşmemiş Özgürlük" arketipi. Dingo ne tam evcil köpektir ne de tam yaban hayvanı — bu arada oluş onun özüdür. Psikolojik olarak: medeniyetin kalıplarına tam sığmayan, ama vahşeti de seçmeyen bilinç hâlini simgeler. İçgüdüyle aklın tam sınırında yaşamak.', en: '"Untamed Freedom" archetype. The dingo is neither a fully domesticated dog nor a purely wild animal — this in-between state is its essence. Psychologically: it embodies the state of consciousness that does not fully fit civilization\'s molds, yet does not choose savagery either. Living precisely on the border of instinct and reason.' },
    dream: { tr: 'Dingo rüyada — ehlileştirilemeyen bir parçanın sesi. Yalnız koşuyorsa: özgürlük ihtiyacın çığlık atıyor; seni izliyorsa: içgüdülerine kulak vermelisin, aklın onları bastırmaya çalışıyor olabilir.', en: 'The dingo in dream — the voice of an untameable part. If running alone: your need for freedom is crying out; if watching you: you should listen to your instincts, your mind may be trying to suppress them.' },
    shadow: { tr: 'Ehlileşmemeyi bir erdem sanmak: bağlanmaktan, sorumluluktan, topluluğun kurallarından kaçmak için "özgürlük" söylemini kullanmak. Dingo gölgesi, her çitin dışına çıkar ama hiçbir yuvada kalmaz — sonsuz bir arayış, sonsuz bir yalnızlık.', en: 'Mistaking untameability for virtue: using the discourse of "freedom" to flee attachment, responsibility, the community\'s rules. The dingo\'s shadow leaps outside every fence but stays in no home — an endless search, an endless solitude.' },
    whenAppears: { tr: 'Toplumsal beklentilerle içsel özgürlük ihtiyacın arasında sıkıştığında; ya da saf içgüdüne güvenmen gerektiği ama aklının onu bastırdığı anlarda.', en: 'When you are caught between social expectations and your inner need for freedom; or at moments when you need to trust your pure instinct but your mind is suppressing it.' },
    traditions: [
      { culture: { tr: 'Avustralya Aborijin', en: 'Australian Aboriginal' }, meaning: { tr: 'Dingo Rüya Zamanı\'nın parçasıdır — atalardan gelen yabani ruhun toprağa bağlı özgür hâlidir.', en: 'The dingo is part of the Dreamtime — the earthbound free form of the wild spirit inherited from the ancestors.' } },
      { culture: { tr: 'Avustralya Aborijin (Toas)', en: 'Australian Aboriginal (Toas)' }, meaning: { tr: 'Dingo, seyahat ve yön işaretlerinde; bir yerin ruhunu ve yolun nasıl izleneceğini anlatmak için kullanılır.', en: 'The dingo appears in travel and direction markers; used to tell of a place\'s spirit and how a path is to be followed.' } },
      { culture: { tr: 'Sömürge Dönemi Avustralya', en: 'Colonial Australia' }, meaning: { tr: 'Avrupalı yerleşimciler dingoyu tehdit olarak gördü; bu yüzden uzun çitler inşa edildi. Ama dingo çitleri aştı — özgürlük duvarlardan büyüktür.', en: 'European settlers saw the dingo as a threat; long fences were built as a result. But the dingo crossed the fences — freedom is greater than walls.' } },
      { culture: { tr: 'Modern Avustralya Kültürü', en: 'Modern Australian Culture' }, meaning: { tr: 'Dingo ulusal bir sembol olarak tartışmalıdır — ehlileştirilemeyen, ne içeride ne dışarıda tam yerini bulan bir kimlik imgesi.', en: 'The dingo is a contested national symbol — an image of identity that cannot be domesticated, fully at home neither inside nor outside.' } },
      { culture: { tr: 'Güneydoğu Asya Kökeni', en: 'Southeast Asian Origin' }, meaning: { tr: 'Araştırmalar dingoyu Güneydoğu Asya\'dan gelen ilk denizci halkların köpeğiyle ilişkilendirir — kıtalar arası bir göçün izini taşır.', en: 'Research connects the dingo to the dogs of the first seafaring peoples arriving from Southeast Asia — it carries the trace of an intercontinental migration.' } },
    ],
    myths: [
      { tr: 'Aborijin anlatılarında Dingo, Rüya Zamanı\'nda Büyük Ata\'nın habercisiydi. Ne köyde ne ormanda kalmayı seçti; sınırda yaşadı. Bu yüzden o sınırı geçen her insan için yol arkadaşı oldu. Onu evcilleştirmeye çalışan kayboldu; onunla birlikte koşmayı öğrenen ise hem doğayı hem kendini buldu.', en: 'In Aboriginal stories, in the Dreamtime the Dingo was the messenger of the Great Ancestor. It chose to remain neither in the village nor in the forest; it lived on the border. For this reason it became the traveling companion of every person who crossed that boundary. Those who tried to domesticate it were lost; those who learned to run alongside it found both nature and themselves.' },
    ],
  },

  // ─── a098 Platipus ───────────────────────────────────────────────────────
  a098: {
    jung: { tr: '"Sınıflandırılamaz Güzellik" arketipi. Platipus hem memeliydi hem yumurtluyordu, hem memeli hem kuş özelliği taşıyordu — bilim onu gördüğünde sahte sandı. Bu, psikede kategorilerin dışında kalan her şeyi temsil eder: kendini tanımlamakta zorlandığın, ama gerçek olan benliğin.', en: '"Unclassifiable Beauty" archetype. The platypus was both mammal and egg-layer, carrying features of both mammal and bird — when science first saw it, they thought it a hoax. This represents in the psyche everything that falls outside categories: the self you struggle to define, yet which is real.' },
    dream: { tr: 'Platipus rüyada — kendini bir kategoriye sığdırma baskısından kurtulma zamanı. Suda yüzüyorsa: bilinçdışın zıtlıkları bütünleştiriyor; seni izliyorsa: benzersizliğin artık görünür olmak istiyor.', en: 'The platypus in dream — time to free yourself from the pressure of fitting into a category. If swimming in water: your unconscious is integrating opposites; if watching you: your uniqueness wishes to become visible now.' },
    shadow: { tr: '"Ben kategoriye sığmıyorum" söylemini bir sorumsuzluk kalkanına dönüştürmek. Platipus gölgesi, her sistemi reddeder ama kendi sistemini de kuramaz; zıtlığı entegre etmek yerine onların arasında kaybolur.', en: 'Turning the discourse of "I don\'t fit into a category" into a shield of irresponsibility. The platypus shadow rejects every system but cannot build its own either; instead of integrating opposites it becomes lost between them.' },
    whenAppears: { tr: 'Kendini toplumun ya da ailenin beklentilerine sığdıramadığını hissettiğinde; ya da zıt özelliklerini bir bütünde harmanlama fırsatının doğduğu dönemlerde.', en: 'When you feel you cannot fit into society\'s or family\'s expectations; or during periods when the opportunity arises to blend your opposing qualities into a whole.' },
    traditions: [
      { culture: { tr: 'Avustralya Aborijin (Wiradjuri)', en: 'Australian Aboriginal (Wiradjuri)' }, meaning: { tr: 'Platipus (Bilarr), hem su hem toprak dünyasına ait olduğu için iki âlem arasında arabuluculuk yapar.', en: 'The platypus (Bilarr), belonging to both the water and land worlds, mediates between the two realms.' } },
      { culture: { tr: 'Avustralya Aborijin (Dreamtime)', en: 'Australian Aboriginal (Dreamtime)' }, meaning: { tr: 'Platipus, Rüya Zamanı\'nda bir tartışmadan doğdu: hayvanlar birbirini dışlarken platipus hepsinin özelliklerini aldı. Ata onun için dedi ki: "Sen hepsindensin."', en: 'In the Dreamtime the platypus was born from a dispute: while animals excluded one another, the platypus took on the features of all. The Ancestor said of it: "You belong to all of them."' } },
      { culture: { tr: 'Batı Bilimi (18. yy)', en: 'Western Science (18th c.)' }, meaning: { tr: 'İlk platipus örneği İngiltere\'ye ulaştığında doğa bilimciler sahte olduğunu iddia etti — gerçek, tanımların dışına çıktığında inkâr edilir.', en: 'When the first platypus specimen reached England, naturalists claimed it was a fake — reality is denied when it exceeds definitions.' } },
      { culture: { tr: 'Modern Ekoloji', en: 'Modern Ecology' }, meaning: { tr: 'Platipus elektroresepsiyon yeteneğiyle sualtında görmeden avlanır — altıncı hissin, sezginin biyolojik karşılığı.', en: 'The platypus hunts underwater without seeing using electroreception — the biological counterpart of sixth sense, of intuition.' } },
      { culture: { tr: 'Çağdaş Spiritüelite', en: 'Contemporary Spirituality' }, meaning: { tr: 'Platipus totem hayvanı olarak "ben kendimim" mesajını verir — başkasının kategorisinde var olmak yerine kendi bütünlüğünde yaşamak.', en: 'As a totem animal the platypus gives the message "I am myself" — living in one\'s own wholeness rather than existing within another\'s category.' } },
    ],
    myths: [
      { tr: 'Aborijin anlatısında su faresi ile ördek arasında uzun bir tartışma vardır: ikisi de platipusu kendi türünden sayar. Platipus onları dinler, sonra suya dalar. Derinliklerde Büyük Ata ona şunu söyler: "Tartışmalarını dinle ama adlarına inanma. Sen suyla toprak arasındaki sırrın kendisisin."', en: 'In an Aboriginal story there is a long dispute between the water rat and the duck: each counts the platypus as its own kind. The platypus listens to them, then dives into the water. In the depths the Great Ancestor says to it: "Listen to their arguments but do not believe their names. You are the secret itself between water and earth."' },
    ],
  },

  // ─── a099 Dalgıç Kuşu ────────────────────────────────────────────────────
  a099: {
    jung: { tr: '"Bilinçaltı Sesi ve İçsel Çığlık" arketipi. Dalgıç kuşunun çığlığı, psikede bastırılmış duyguların yüzeye çıkma anını simgeler — hem rüyanın hem gözyaşının hem de öfkenin sesidir. Jung\'un "gölge"sinin su yüzeyinde yankılanan yankısıdır.', en: '"Voice of the Unconscious and Inner Cry" archetype. The loon\'s cry symbolizes the moment repressed emotions surface in the psyche — it is the voice of both the dream, and the tear, and the rage. It is the echo of Jung\'s "shadow" reverberating on the surface of water.' },
    dream: { tr: 'Dalgıç Kuşu rüyada — bilinçaltından gelen bir mesaj artık duyulabilir seviyeye çıktı. Çığlık atıyorsa: uzun süredir bastırdığın bir duygunun serbest bırakılması gerekiyor; suya dalıyorsa: cevabı derinlerde ara, yüzeyde değil.', en: 'The loon in dream — a message from the unconscious has now risen to an audible level. If crying out: an emotion long suppressed needs to be released; if diving: seek the answer in the depths, not on the surface.' },
    shadow: { tr: 'Çığlığı duymayı reddetmek ya da sonsuz çığlık. Dalgıç Kuşu gölgesinde ya içini tamamen susturmak — duygusal donukluk — ya da durdurulamayan bir iç ses: sonsuz bir hüzün, giderilemeyen bir yalnızlık hissi vardır.', en: 'Refusing to hear the cry, or the endless cry. In the loon\'s shadow there is either completely silencing the inner voice — emotional numbness — or an unstoppable inner sound: an endless sorrow, an irremedable sense of loneliness.' },
    whenAppears: { tr: 'İçindeki bir sesin artık duyulması gerektiği anlarda; ya da yalnızlık ve derinlik temalarının seni en güçlü biçimde sardığı dönemlerde.', en: 'At moments when an inner voice must now be heard; or during periods when themes of solitude and depth surround you most powerfully.' },
    traditions: [
      { culture: { tr: 'Yerli Kuzey Amerika (Anishinaabe)', en: 'Native North America (Anishinaabe)' }, meaning: { tr: 'Dalgıç Kuşu rüya rehberidir — sesi bilinçaltının kapısını açar, su şamanının yoldaşıdır.', en: 'The loon is a dream guide — its voice opens the door of the unconscious, it is the companion of the water shaman.' } },
      { culture: { tr: 'Kuzey Amerika Yerlileri (Cree)', en: 'North American Indigenous (Cree)' }, meaning: { tr: 'Dalgıç Kuşu\'nun çığlığı, kaybedilen sevdiklerin ruhu olarak yorumlanır — yas ve bağ arasındaki köprü.', en: 'The loon\'s cry is interpreted as the spirit of lost loved ones — the bridge between grief and connection.' } },
      { culture: { tr: 'İskandinav', en: 'Scandinavian' }, meaning: { tr: 'Dalgıç Kuşu kuzey göllerinin sesi; fırtına öncesi çığlığı denizcileri uyarır, değişimin habercisidir.', en: 'The loon is the voice of northern lakes; its cry before a storm warns sailors, it is the herald of change.' } },
      { culture: { tr: 'İnuit', en: 'Inuit' }, meaning: { tr: 'Dalgıç Kuşu körlerin gözlerini açtığına inanılır — ruhsal görüşü restore eden kutsal varlık.', en: 'The loon is believed to restore sight to the blind — the sacred being that restores spiritual vision.' } },
      { culture: { tr: 'Kanada Ulusal Sembolizmi', en: 'Canadian National Symbolism' }, meaning: { tr: 'Kanada\'nın bir dolarlık sikkesinde yaşayan "loonie" — ulusal kimliğin derinlik ve sessizlik içindeki yankısı.', en: 'Living on Canada\'s one-dollar coin as the "loonie" — the echo of national identity within depth and silence.' } },
    ],
    myths: [
      { tr: 'İnuit efsanesinde kör bir yaşlı adam Dalgıç Kuşu\'ndan iyileşmesini diler. Kuş onu suyun altına üç kez götürür. Her seferinde bir ışık daha açılır gözlerinde. Üçüncüde yüzeye çıkar ve tüm dünyayı görür — hem dışarıdaki hem içindeki. Dalgıç Kuşu\'nun hediyesi sadece görme değil, derinliğe bakabilmedir.', en: 'In an Inuit legend a blind old man prays to the Loon for healing. The bird takes him underwater three times. Each time another light opens in his eyes. On the third he surfaces and sees the entire world — both outside and within. The Loon\'s gift is not sight alone, but the ability to look into the depths.' },
    ],
  },

  // ─── a100 Beyaz Geyik ────────────────────────────────────────────────────
  a100: {
    jung: { tr: '"İlahi Çağrı ve Kutsal Belirti" arketipi. Beyaz Geyik, psikede nadiren görülen ama görüldüğünde her şeyi değiştiren anlara karşılık gelir — aşkınlık deneyimi. Kişinin kendi kaderine çağrıldığı o eşik anı; tam anlamıyla bir "numinos" tezahürüdür, kutsal olanın sıradan içinde görünmesidir.', en: '"Divine Call and Sacred Sign" archetype. The White Deer corresponds to the rarely seen moments in the psyche that change everything when they appear — the transcendence experience. That threshold moment when one is called to one\'s own destiny; it is a true "numinous" manifestation, the appearance of the sacred within the ordinary.' },
    dream: { tr: 'Beyaz Geyik rüyada — olağanüstü bir çağrının, bir dönüm noktasının eşiğindesin. Dur bakıyorsa: henüz hazır mısın sorusunu soruyor; kaçıyorsa: çağrıyı duyuyorsun ama henüz kabul etmiyorsun; seni takip ediyorsa: kaçış yok, bu sefer yüzleşmek zorundasın.', en: 'The White Deer in dream — you stand on the threshold of an extraordinary call, a turning point. If it stands and gazes: it asks whether you are yet ready; if it flees: you hear the call but have not yet accepted it; if it follows you: there is no escape, this time you must face it.' },
    shadow: { tr: '"İşaret bekleme" tuzağı: her beyaz geyiği beklerken sıradan anda sunulan lütfu görmemek. Beyaz Geyik gölgesi, olağanüstü olanı öyle özler ki sıradan anın kutsallığına kör olur — mucize arar, yanıbaşındaki yaşamı kaçırır.', en: 'The "waiting for a sign" trap: while waiting for every white deer, failing to see the grace offered in the ordinary moment. The White Deer\'s shadow longs so deeply for the extraordinary that it goes blind to the sacredness of the ordinary instant — it searches for a miracle and misses the life right beside it.' },
    whenAppears: { tr: 'Hayatının gerçek yönünü bulman gereken dönüm noktalarında; ya da sıradan bir anın içinde kutsal olanı fark ettiğin o nadiren gelen anlarda.', en: 'At the turning points where you must find the true direction of your life; or at those rarely arriving moments when you perceive the sacred within an ordinary instant.' },
    traditions: [
      { culture: { tr: 'Kelt Mitolojisi', en: 'Celtic Mythology' }, meaning: { tr: 'Beyaz Geyik Öteki Dünya\'nın habercisidir — onu kovalayan kahraman, ölümlü dünyadan kutsal aleme geçer.', en: 'The White Deer is the herald of the Otherworld — the hero who chases it crosses from the mortal world to the sacred realm.' } },
      { culture: { tr: 'Arthurian Efsaneleri', en: 'Arthurian Legends' }, meaning: { tr: 'Beyaz Geyik Graal arayışının tetikleyicisidir — şövalyeler onu yakalamanın imkânsız olduğunu bilir ama peşinden gitmek zorunludur.', en: 'The White Deer triggers the Grail quest — the knights know catching it is impossible but following it is compulsory.' } },
      { culture: { tr: 'Çin', en: 'Chinese' }, meaning: { tr: 'Beyaz Geyik uzun ömrün ve bilgeliğin sembolüdür; Shou tanrısının yanında dururdu.', en: 'The white deer is a symbol of longevity and wisdom; it stood beside the god Shou.' } },
      { culture: { tr: 'Kore', en: 'Korean' }, meaning: { tr: 'Beyaz Geyik efsanevi yöneticilerin ya da bilgelerin doğumunu müjdeleyen kutsal belirti olarak görülür.', en: 'The white deer is seen as a sacred sign heralding the birth of legendary rulers or sages.' } },
      { culture: { tr: 'Yerli Kuzey Amerika (Lakota)', en: 'Native North America (Lakota)' }, meaning: { tr: 'Beyaz Bufalo Kadını\'nın dönüşümünde olduğu gibi, beyaz hayvan genellikle ilahi mesajın taşıyıcısıdır; dönüşüm ve barışın simgesi.', en: 'As with the transformation of White Buffalo Woman, the white animal is generally the carrier of divine message; a symbol of transformation and peace.' } },
    ],
    myths: [
      { tr: 'Kelt efsanesinde genç bir avcı ormanda Beyaz Geyik\'in izini sürer. Tam oklarını çekeceği anda geyik dönüp ona bakar — gözleri insan gözü gibidir. Avcı yayını bırakır. Geyik onu gece boyu ormanın içine götürür; sabah çıktığında avcı, köyün çoktandır kaybettiği şifacı bilgeye ulaşmıştır. Beyaz Geyik yakalanmaz; o yalnızca yolu gösterir.', en: 'In a Celtic legend a young hunter tracks the White Deer through the forest. Just as he is about to loose his arrow, the deer turns and looks at him — its eyes are like human eyes. The hunter lets fall his bow. The deer leads him through the forest all night; when he emerges at dawn, the hunter has reached the healing sage the village had long since lost. The White Deer is not caught; it only shows the way.' },
      { tr: 'Anadolu\'da beyaz hayvan görümü her zaman bir işaret sayılmıştır. Halk arasında "Beyaz geyik gördüm" demek, "Hayatımda bir şey değişecek" demektir. Sufiler bunu Hakk\'ın kalbine doğru çekiş olarak yorumlar: hayvan kaçar, sen koşarsın — ama varış yeri geyiğin yurdu değil, kendi kalbinin derinliğidir.', en: 'In Anatolia a vision of a white animal has always been considered a sign. Among the people, to say "I saw a white deer" is to say "something in my life will change." Sufis interpret this as the pull toward the heart of the Divine: the animal flees, you run — but the destination is not the deer\'s home, it is the depth of your own heart.' },
    ],
  },

  // ─── a101 Balina ────────────────────────────────────────────────────────
  a101: {
    jung: {
      tr: 'Balina, kolektif bilinçaltının kendisidir — yüzeyin çok altında uzanan o uçsuz derinlik. Jung\'un "okyanus" dediği bilinçdışına dalış; Yunus\'un balığın karnındaki üç günü gibi, egonun ölüp dönüştüğü kuluçka karanlığı. Bastırılan her duygunun saklandığı dipsiz arşiv.',
      en: 'The Whale is the Collective Unconscious itself — that boundless depth stretching far beneath the surface. The dive into the unconscious that Jung called "the ocean"; like Jonah\'s three days in the belly, the incubating darkness where the ego dies and is transformed. The bottomless archive where every suppressed emotion is kept.',
    },
    dream: {
      tr: 'Rüyada balina — bilinçaltından yüzeye doğru yükselen kocaman bir şeyin habercisidir: uzun süredir bastırdığın bir duygu, bir hakikat ya da yaratıcı bir çağrı. Sular durgunsa huzur, fırtınalıysa yüzleşilmeyi bekleyen dipsel bir akıntı.',
      en: 'A whale in dream — heralds something immense rising from the unconscious toward the surface: a long-suppressed emotion, a truth, or a creative calling. Calm waters mean peace; stormy ones, a deep current waiting to be faced.',
    },
    shadow: {
      tr: 'Duygunun ağırlığında o kadar derine dalmak ki yüzeye, nefese ve ışığa dönmeyi unutmak — melankoliye, geçmişe ya da başkalarının acısına boğulmak. Balina gölgesi dipte kalmayı derinlik sanır; oysa balina bile nefes almak için yükselir.',
      en: 'Diving so deep into the weight of feeling that you forget to return to the surface, to breath and light — drowning in melancholy, in the past, or in others\' pain. The Whale\'s shadow mistakes staying at the bottom for depth; yet even the whale rises to breathe.',
    },
    whenAppears: {
      tr: 'Eski bir yası ya da duyguyu işlemen gereken dönemlerde; içindeki kadim belleğe ve ailenden gelen sessiz mirasa kulak verme zamanında; ya da yaratıcı bir şarkının derinlerden yüzeye çıkmak istediği anda.',
      en: 'In times when you must process an old grief or emotion; when it is time to listen to the ancient memory within you and the silent inheritance from your lineage; or when a creative song wishes to rise from the depths to the surface.',
    },
    traditions: [
      { culture: { tr: 'Maori (Polinezya)', en: 'Māori (Polynesia)' }, meaning: { tr: 'Balina kutsal atadır (tipuna). Paikea efsanesinde ata, okyanusu bir balinanın sırtında aşarak yeni topraklara ulaşır — insanla deniz arasındaki kutsal sözleşmenin taşıyıcısı.', en: 'The whale is a sacred ancestor (tipuna). In the Paikea legend the ancestor crosses the ocean on a whale\'s back to reach new lands — carrier of the sacred covenant between humanity and the sea.' } },
      { culture: { tr: 'Pasifik Kuzeybatı Yerlileri', en: 'Pacific Northwest Peoples' }, meaning: { tr: 'Haida ve Makah geleneğinde balina bereketin ve toplumsal armağanın simgesidir; totem direklerinde yer alır, gelişi tüm köyü doyuran kutsal bir cömertlik anlatısıdır.', en: 'In Haida and Makah tradition the whale symbolizes abundance and communal gift; it appears on totem poles, and its arrival is a sacred story of generosity that feeds an entire village.' } },
      { culture: { tr: 'İbrani / İslam', en: 'Hebrew / Islamic' }, meaning: { tr: 'Yunus peygamber kıssasında balinanın karnı bir ölüm-yeniden doğuş eşiğidir; karanlığın içine inip teslim olarak ve dönüşerek çıkmanın simgesi.', en: 'In the account of the prophet Jonah, the whale\'s belly is a threshold of death and rebirth; the symbol of descending into darkness, surrendering, and emerging transformed.' } },
      { culture: { tr: 'İnuit', en: 'Inuit' }, meaning: { tr: 'Deniz tanrıçası Sedna\'nın çocukları ve halka rızık veren kutsal varlıklar; deniz canlılarıyla insan arasındaki saygı dengesinin bekçileri.', en: 'Children of the sea goddess Sedna and sacred beings that provide for the people; guardians of the balance of respect between humanity and the creatures of the sea.' } },
      { culture: { tr: 'Japon Shinto', en: 'Japanese Shinto' }, meaning: { tr: 'Balina (kujira) okyanus tanrısının lütfu sayılır; Ebisu\'nun bolluğunu taşıyan, kıyı köylerine bereket getiren deniz kamisidir.', en: 'The whale (kujira) is seen as a grace of the ocean god; a sea kami that carries Ebisu\'s abundance and brings bounty to coastal villages.' } },
    ],
    myths: [
      { tr: 'Paikea (Balina Binicisi): Maori atası Paikea, kardeşinin ihaneti yüzünden denizde boğulmak üzereyken bir balina onu sırtına alır ve okyanusu aşarak Aotearoa\'ya (Yeni Zelanda) ulaştırır. Onun soyu, balinayla kurulan o kutsal bağı bugün de taşır.', en: 'Paikea (the Whale Rider): the Māori ancestor Paikea, about to drown at sea through his brother\'s betrayal, is taken upon a whale\'s back and carried across the ocean to Aotearoa (New Zealand). His descendants still carry that sacred bond with the whale today.' },
      { tr: 'Yunus ile Balina: Görevinden kaçan Yunus fırtınada denize atılır ve büyük bir balık onu yutar. Karanlığın içinde üç gün dua eder, teslim olur; balina onu kıyıya bırakır. Karnın karanlığı bir mezar değil bir rahimdir — Yunus oradan yeniden doğmuş olarak çıkar.', en: 'Jonah and the Whale: fleeing his calling, Jonah is cast into the sea in a storm and a great fish swallows him. Within the darkness he prays for three days and surrenders; the whale releases him to shore. The darkness of the belly is not a grave but a womb — Jonah emerges from it reborn.' },
    ],
  },

  // ─── a102 İspermeçet Balinası ───────────────────────────────────────────
  a102: {
    jung: {
      tr: 'İspermeçet balinası, bilinçaltının en dibine inip oradan sağ dönen "Derin Dalgıç" arketipidir — okyanusun ışıksız diplerine ego olmadan, yalnızca yankıyla yolunu bulan ruh. Beyninin ağırlığı ona değil, içindeki sessizliğe işaret eder: en büyük zihin, en derin karanlıkta avlanır.',
      en: 'The Sperm Whale is the "Deep Diver" archetype that descends to the very bottom of the unconscious and returns alive — the soul that finds its way through the lightless deeps without ego, by echo alone. The weight of its brain points not to itself but to the silence within: the largest mind hunts in the deepest dark.',
    },
    dream: {
      tr: 'Rüyada ispermeçet balinası — derin bir hakikate dalmaya çağrıldığını söyler: yüzeyde bulunamayacak bir cevap, ışığın ulaşmadığı bir derinlikte seni bekliyor. Dipten yükseliyorsa, uzun bir içsel keşfin sonunda nefes almak üzeresin.',
      en: 'A sperm whale in dream — tells you that you are called to dive into a deep truth: an answer that cannot be found at the surface awaits you in a depth where light does not reach. If it rises from below, you are about to draw breath at the end of a long inner descent.',
    },
    shadow: {
      tr: 'Derinliğe takıntı: bilgiye ve gizemin dibine o kadar dalmak ki gündelik ışığa, sıradan sevince yabancılaşmak. İspermeçet gölgesi, Ahab gibi tek bir karanlık takıntının peşinde tüm hayatını harcar — derinlik bir bilgelik değil, bir saplantı olur.',
      en: 'Obsession with depth: diving so far into knowledge and the bottom of mystery that you become a stranger to everyday light and ordinary joy. The sperm whale\'s shadow, like Ahab, spends a whole life chasing a single dark obsession — depth becomes not wisdom but fixation.',
    },
    whenAppears: {
      tr: 'Yüzeysel cevapların yetmediği, bir sorunun köküne inmen gereken dönemlerde; sessizliğe çekilip iç sesini yankıyla dinlemen gerektiği anda belirir.',
      en: 'It appears in times when surface answers no longer suffice and you must descend to the root of a question; when you must withdraw into silence and listen to your inner voice by its echo.',
    },
    traditions: [
      { culture: { tr: 'Azor / Portekiz Denizcileri', en: 'Azorean / Portuguese Whalers' }, meaning: { tr: 'İspermeçet balinası okyanusun "büyük efendisi" sayılır; geçmişin balina avcıları için hem rızık hem de karşılaşıldığında insanı küçülten kadim bir güçtür — denizin sınırını çizen varlık.', en: 'The sperm whale is regarded as the "great lord" of the ocean; for the whalers of the past it was both sustenance and an ancient power that humbled whoever met it — the being that drew the boundary of the sea.' } },
      { culture: { tr: 'Polinezya', en: 'Polynesian' }, meaning: { tr: 'İspermeçet dişi (parāoa) Maori şefliğinin kutsal simgesidir; reisin yetkesini ve atasal bağı taşıyan, denizin armağanı olan kutsal nesne.', en: 'The sperm whale tooth (parāoa) is a sacred emblem of Māori chieftainship; a hallowed object, a gift of the sea, that carries the chief\'s authority and the ancestral bond.' } },
      { culture: { tr: 'Yeni İngiltere (Nantucket)', en: 'New England (Nantucket)' }, meaning: { tr: 'Melville\'in Moby Dick\'inde beyaz ispermeçet, doğanın anlaşılamaz, ele geçirilemez gizemidir; insanın takıntısına ayna tutan aşkın bir varlık.', en: 'In Melville\'s Moby-Dick the white sperm whale is the unknowable, ungraspable mystery of nature; a transcendent being that mirrors human obsession back at it.' } },
      { culture: { tr: 'İnuit', en: 'Inuit' }, meaning: { tr: 'Derin deniz canlıları Sedna\'nın çocukları sayılır; ispermeçet, insanın ulaşamayacağı diplerin bekçisi, saygı gösterilmesi gereken kadim bir ruhtur.', en: 'The deep-sea creatures are counted among Sedna\'s children; the sperm whale is the keeper of depths beyond human reach, an ancient spirit that must be honored.' } },
    ],
    myths: [
      { tr: 'Moby Dick: Kaptan Ahab, bir bacağını koparan beyaz balina Moby Dick\'in peşine düşer ve bütün mürettebatını bu intikam takıntısının içine sürükler. Balina yenilmez kalır; Ahab\'ı da gemisini de dibe çeker. Anlatı, anlaşılmazın peşinde benliğini yitiren insanın trajedisidir.', en: 'Moby-Dick: Captain Ahab pursues the white whale that tore off his leg, dragging his entire crew into the vortex of his vengeful obsession. The whale remains unconquered and pulls both Ahab and his ship to the deep. The tale is the tragedy of a man who loses himself chasing the unknowable.' },
    ],
  },

  // ─── a103 Orka ──────────────────────────────────────────────────────────
  a103: {
    jung: {
      tr: 'Orka, "Dönüştürücü Şef" arketipidir — derin sularda dolaşan, ailesini kuşaktan kuşağa aktarılan bir bilgiyle yöneten anaerkil bilgelik. Hem zarif hem ölümcül; karanlık ile aydınlığı (siyah-beyaz) tek bedende taşıyan, bütünlüğün dengelenmiş gücü.',
      en: 'The Orca is the "Transformer Chief" archetype — the matriarchal wisdom that roams the deep waters and leads its family by knowledge passed down through generations. At once graceful and lethal; carrying dark and light (black and white) in a single body, the balanced power of wholeness.',
    },
    dream: {
      tr: 'Rüyada orka — güçlü bir topluluğa ya da aile bağına ait olduğunu hatırlatır; etrafında seni koruyan görünmez bir sürü var. Tek başına süzülüyorsa, kendi gücüne ve sezgine güvenme zamanı.',
      en: 'An orca in dream — reminds you that you belong to a powerful community or family bond; an unseen pod surrounds and protects you. If it glides alone, it is time to trust your own power and intuition.',
    },
    shadow: {
      tr: 'Sürünün gücünü baskıya çevirmek: aileye ya da gruba o kadar sıkı bağlanmak ki dışarıdakine acımasızlaşmak, "biz" ve "onlar" diye keskin bir sınır çizmek. Orka gölgesi, koruyuculuğu hükmetmeye dönüştüren liderdir.',
      en: 'Turning the pod\'s power into domination: bonding so tightly to family or group that you become merciless to the outsider, drawing a sharp line of "us" and "them." The orca\'s shadow is the leader who turns protection into rule.',
    },
    whenAppears: {
      tr: 'Aileni ya da topluluğunu yönetmen, bir grubu bir arada tutman gereken dönemlerde; sezgine güvenip avına (hedefine) kararlı bir koordinasyonla gitmen gerektiği anda belirir.',
      en: 'It appears when you must lead your family or community, hold a group together; when you must trust your intuition and move toward your quarry (your goal) with decisive coordination.',
    },
    traditions: [
      { culture: { tr: 'Haida (Pasifik Kuzeybatı)', en: 'Haida (Pacific Northwest)' }, meaning: { tr: 'Orka (skana) su altı dünyasının şefidir; ölülerin ruhlarını öteki âleme taşıyan, denizin altında insan biçiminde yaşayan kutsal halk. Totem direklerinin başlıca koruyucu figürü.', en: 'The orca (skana) is the chief of the underwater world; the sacred people who carry the souls of the dead to the otherworld and live in human form beneath the sea. A principal guardian figure on totem poles.' } },
      { culture: { tr: 'Tlingit', en: 'Tlingit' }, meaning: { tr: 'Orka (keet) klan atasıdır; bir avcının yonttuğu ilk orka heykelinin canlanıp denize dalmasıyla doğduğuna inanılır — sadakatin ve aile koruyuculuğunun simgesi.', en: 'The orca (keet) is a clan ancestor; believed born when the first orca a hunter carved came to life and dove into the sea — a symbol of loyalty and family guardianship.' } },
      { culture: { tr: 'Nuu-chah-nulth', en: 'Nuu-chah-nulth' }, meaning: { tr: 'Orka, şeflerin ruhunun denizdeki devamı sayılır; bir orka görmek, ölmüş bir reisin halkını ziyarete geldiğine işarettir.', en: 'The orca is regarded as the continuation at sea of chiefs\' souls; to see one is a sign that a departed leader has come to visit his people.' } },
      { culture: { tr: 'Maori', en: 'Māori' }, meaning: { tr: 'Orkalar (maki) okyanusun bekçileri ve taonga (hazine) sayılır; Tangaroa\'nın, deniz tanrısının koruması altındaki kutsal canlılardır.', en: 'Orcas (maki) are regarded as guardians of the ocean and taonga (treasure); sacred creatures under the protection of Tangaroa, the god of the sea.' } },
    ],
    myths: [
      { tr: 'Natsilane ve Katil Balina: Tlingit efsanesinde kıskanç kayınbiraderleri tarafından ıssız bir adaya terk edilen avcı Natsilane, deniz ruhlarının yardımıyla ahşaptan ilk orkayı yontar. Heykele can verir ve onu kendisini terk edenlerin peşine salar; o günden beri orka denizin adaletini ve sadakatini taşır.', en: 'Natsilane and the Killer Whale: in Tlingit legend the hunter Natsilane, marooned on a barren island by his jealous brothers-in-law, carves the first orca from wood with the help of sea spirits. He gives the figure life and sends it after those who abandoned him; ever since, the orca carries the justice and loyalty of the sea.' },
    ],
  },

  // ─── a104 Ahtapot ───────────────────────────────────────────────────────
  a104: {
    jung: {
      tr: 'Ahtapot, "Uyum Sağlayan Zekâ" arketipidir — sekiz kolu ve dağılmış zihni ile her duruma akan, biçim değiştiren bilinç. Kemiksiz bedeni, katı egonun yokluğunu temsil eder: sınırlarını yumuşatabilen, her deliğe sığabilen, gerektiğinde görünmez olabilen ruhsal esneklik.',
      en: 'The Octopus is the "Adaptive Intelligence" archetype — a shape-shifting consciousness that flows into every situation with its eight arms and distributed mind. Its boneless body represents the absence of a rigid ego: a spiritual flexibility that can soften its boundaries, fit into any crevice, and become invisible when it must.',
    },
    dream: {
      tr: 'Rüyada ahtapot — bir durumu her yönden kavradığını ya da kavraman gerektiğini söyler; çok şeyi aynı anda tutan zekâna güven. Seni sarıyorsa: kontrol altına almaya çalıştığın bir bağdan ya da duygudan kurtulma zamanı.',
      en: 'An octopus in dream — tells you that you grasp, or must grasp, a situation from every direction; trust the intelligence that holds many things at once. If it wraps around you: it is time to free yourself from a bond or emotion you are trying to control.',
    },
    shadow: {
      tr: 'Kamuflajın gölgesi: o kadar iyi uyum sağlamak ki gerçek benliğini kaybetmek, her ortama göre renk değiştirip kim olduğunu unutmak. Sekiz kolla her şeyi kontrol etmeye çalışmak da manipülasyona, başkalarını sarıp tutmaya dönüşebilir.',
      en: 'The shadow of camouflage: adapting so well that you lose your true self, changing color for every setting until you forget who you are. Trying to control everything with eight arms can also turn into manipulation, into wrapping around and gripping others.',
    },
    whenAppears: {
      tr: 'Karmaşık, çok katmanlı bir soruna esneklikle yaklaşman gereken dönemlerde; sıkışıp kaldığın bir yerden zekânla sıyrılman ya da bir süre görünmez kalıp kendini koruman gerektiği anda belirir.',
      en: 'It appears when you must approach a complex, many-layered problem with flexibility; when you must slip free of a tight place by your wits, or stay invisible for a while to protect yourself.',
    },
    traditions: [
      { culture: { tr: 'Hawaii (Polinezya)', en: 'Hawaiian (Polynesian)' }, meaning: { tr: 'Kanaloa, okyanus ve yeraltı tanrısı, sıklıkla ahtapot (heʻe) biçiminde tasvir edilir; bazı anlatılarda ahtapot, önceki bir evrenin tek hayatta kalanıdır — kadim, gizemli bir bilginin taşıyıcısı.', en: 'Kanaloa, god of the ocean and underworld, is often depicted in the form of an octopus (heʻe); in some accounts the octopus is the lone survivor of a previous universe — bearer of ancient, mysterious knowledge.' } },
      { culture: { tr: 'Japon', en: 'Japanese' }, meaning: { tr: 'Akkorokamui — Ainu geleneğinin devasa, kızıl ahtapot ruhu; hem korkulan hem de şifa ve denizcilik için yardımına başvurulan, çift yönlü güce sahip bir kami.', en: 'Akkorokamui — the colossal red octopus spirit of Ainu tradition; a kami of dual power, both feared and appealed to for healing and safe passage at sea.' } },
      { culture: { tr: 'Antik Akdeniz (Minos)', en: 'Ancient Mediterranean (Minoan)' }, meaning: { tr: 'Minos seramiğinde ahtapot, kolları sarmal dolanmış biçimde bereketin, denizin canlılığının ve sonsuz akışkanlığın simgesidir.', en: 'On Minoan pottery the octopus, its arms coiling in spirals, is a symbol of abundance, the vitality of the sea, and endless fluidity.' } },
      { culture: { tr: 'İskandinav / Denizci Folkloru', en: 'Norse / Seafarers\' Folklore' }, meaning: { tr: 'Devasa kafadanbacaklı Kraken efsanesi, ahtaposun derinliklerin bilinmezini ve insanın gözünden saklı kadim gücünü cisimleştirmesinden doğar.', en: 'The legend of the giant cephalopod Kraken arises from the octopus embodying the unknown of the depths and an ancient power hidden from human sight.' } },
    ],
    myths: [
      { tr: 'Kanaloa ve Ahtapot: Hawaii kozmolojisinde ahtapot, mevcut yaratılıştan önceki bir dünyadan kaçıp gelen tek varlıktır. Sekiz kolunda önceki evrenin sırlarını taşır; bu yüzden kadim, başka türlü bir zekânın simgesi sayılır — bizimkinden önceki bir aklın hayatta kalan parçası.', en: 'Kanaloa and the Octopus: in Hawaiian cosmology the octopus is the sole being that escaped from a world prior to the present creation. In its eight arms it carries the secrets of the earlier universe; hence it is regarded as a symbol of an ancient, alien intelligence — the surviving fragment of a mind that came before ours.' },
    ],
  },

  // ─── a105 Denizatı ──────────────────────────────────────────────────────
  a105: {
    jung: {
      tr: 'Denizatı, "Nazik Baba" arketipidir — gücün şiddetle değil sabırla, korumayla ve incelikle taşındığı eril enerji. Yavrularını kendi bedeninde taşıyan tek erkek olarak, içsel ataerkil/anaerkil kutupları birleştirir: hassasiyetin de bir güç olduğunu öğreten varlık.',
      en: 'The Seahorse is the "Gentle Father" archetype — a masculine energy in which strength is carried not by force but by patience, protection, and delicacy. As the only male to bear its young in its own body, it unites the inner paternal and maternal poles: a being that teaches that tenderness, too, is a power.',
    },
    dream: {
      tr: 'Rüyada denizatı — sabırla bekleyip beslediğin bir şeyin (bir proje, bir ilişki, bir çocuk) olgunlaşmakta olduğunu söyler. Yavaş ve nazik akışına güven; bu canlı acele etmeyi bilmez, korumayı bilir.',
      en: 'A seahorse in dream — tells you that something you have patiently waited upon and nurtured (a project, a relationship, a child) is maturing. Trust its slow and gentle current; this creature knows nothing of haste, only of protection.',
    },
    shadow: {
      tr: 'Naziklik gölgesi: o kadar kırılgan ve yavaş olmak ki akıntıya tutunamayıp sürüklenmek, kendini koruyamamak. Ya da koruyuculuğu fazla sahiplenmeye, taşıdığını asla bırakmamaya çevirip büyümesine izin vermemek.',
      en: 'The shadow of gentleness: being so fragile and slow that you cannot hold to the current and are swept along, unable to protect yourself. Or turning protectiveness into possessiveness, never releasing what you carry and so not letting it grow.',
    },
    whenAppears: {
      tr: 'Bir şeyi (ya da birini) sabırla, şiddet kullanmadan büyütmen gereken dönemlerde; eril gücünü sertlikle değil incelikle ifade etmen gerektiği anda belirir.',
      en: 'It appears when you must raise something (or someone) patiently, without force; when you must express your masculine strength through delicacy rather than harshness.',
    },
    traditions: [
      { culture: { tr: 'Yunan Mitolojisi', en: 'Greek Mythology' }, meaning: { tr: 'Hippokampos — yarı at yarı balık deniz atı, Poseidon\'un arabasını çeker. Denizin yumuşatılmış, evcilleştirilmiş gücünü; suyun üzerinde gezen ilahi iradeyi simgeler.', en: 'Hippocampus — the half-horse, half-fish sea steed that draws Poseidon\'s chariot. It symbolizes the gentled, tamed power of the sea; the divine will that travels upon the water.' } },
      { culture: { tr: 'Antik Roma', en: 'Ancient Rome' }, meaning: { tr: 'Neptün\'ün maiyetinde resmedilen denizatı, denizcilere güç ve koruma getiren uğurlu bir simge; mozaiklerde bereket ve emniyetli yolculuk işareti.', en: 'Depicted in Neptune\'s retinue, the seahorse is an auspicious emblem bringing strength and protection to sailors; in mosaics, a sign of abundance and safe passage.' } },
      { culture: { tr: 'Çin', en: 'Chinese' }, meaning: { tr: 'Denizatı küçük bir su ejderhası sayılır; güç, kararlılık ve geleneksel tıpta erkek hayat enerjisinin (yang) yenilenmesinin simgesidir.', en: 'The seahorse is regarded as a small water dragon; a symbol of power, perseverance, and, in traditional medicine, the renewal of masculine life energy (yang).' } },
      { culture: { tr: 'Avrupa Denizci Folkloru', en: 'European Seafarers\' Folklore' }, meaning: { tr: 'Denizatı, kaybolan ruhları öbür dünyaya güvenle taşıyan bir rehber sayılırdı; nazik ama kararlı yol göstericiliğin simgesi.', en: 'The seahorse was held to be a guide that safely carries lost souls to the otherworld; a symbol of gentle yet steadfast guidance.' } },
    ],
    myths: [
      { tr: 'Poseidon\'un Hippokamposları: Yunan mitinde deniz tanrısı Poseidon, dalgaların üzerinde altından arabasını yarı at yarı balık hippokamposlara çektirir. Bu varlıklar fırtınayı sükûnete çevirebilir; denizin vahşi gücünün, ilahi bir iradeyle nasıl nazik ve yönlendirilebilir kılındığını anlatır.', en: 'Poseidon\'s Hippocampi: in Greek myth the sea god Poseidon has his golden chariot drawn over the waves by the half-horse, half-fish hippocampi. These beings can turn storm into calm; the tale tells how the wild power of the sea is made gentle and steerable by a divine will.' },
    ],
  },

  // ─── a106 Denizanası ────────────────────────────────────────────────────
  a106: {
    jung: {
      tr: 'Denizanası, "Biçimsiz Akış" arketipidir — egonun, omurganın, sabit benliğin olmadığı saf teslimiyet. Akıntıya direnmeyip onunla bir olan bilinç; ışık geçiren saydam bedeniyle, hiçbir şeyi tutmadan her şeye izin veren bir varlık. Neredeyse ölümsüzlüğü, ölümü bile bir dönüşüm hâline getirir.',
      en: 'The Jellyfish is the "Formless Flow" archetype — pure surrender, without ego, without spine, without a fixed self. A consciousness that does not resist the current but becomes one with it; with its translucent, light-passing body, a being that grasps nothing and allows everything. Its near-immortality turns even death into a transformation.',
    },
    dream: {
      tr: 'Rüyada denizanası — kontrolü bırakıp hayatın akışına teslim olma çağrısıdır; direnmediğin sürece taşınacaksın. Yakıyorsa: pasifliğin ya da sınırsızlığın seni yaraladığı, bir biçim/sınır kurman gerektiği uyarısı.',
      en: 'A jellyfish in dream — is a call to release control and surrender to the flow of life; so long as you do not resist, you will be carried. If it stings: a warning that passivity or boundlessness is wounding you, that you must form a shape, a boundary.',
    },
    shadow: {
      tr: 'Biçimsizliğin gölgesi: hiçbir omurgası, sınırı, kararı olmamak — her akıntıya kapılıp kendi yönünü asla seçememek. Pasif teslimiyet, sorumluluktan kaçışa dönüşür; ve dokununca yakan zehir, savunmasız görünenin sessiz öfkesini ele verir.',
      en: 'The shadow of formlessness: having no spine, no boundary, no decision — drifting with every current and never choosing your own direction. Passive surrender becomes flight from responsibility; and the venom that stings on touch betrays the silent rage of the seemingly defenseless.',
    },
    whenAppears: {
      tr: 'Çok savaştığın, fazla kontrol etmeye çalıştığın bir süreçte bırakmayı öğrenmen gereken dönemlerde; ya da bir dönüşümün (eski benliğin ölüp yenisinin doğmasının) eşiğinde belirir.',
      en: 'It appears when you must learn to let go in a process you have fought too hard, tried too much to control; or on the threshold of a transformation — the old self dying, the new being born.',
    },
    traditions: [
      { culture: { tr: 'Budist', en: 'Buddhist' }, meaning: { tr: 'Denizanasının biçimsiz, geçici varlığı anicca (gelip-geçicilik) öğretisinin canlı bir simgesidir; tutunmamanın, akışa direnmemenin ve benliğin akışkanlığının hatırlatıcısı.', en: 'The jellyfish\'s formless, transient existence is a living emblem of the teaching of anicca (impermanence); a reminder of non-attachment, of not resisting the flow, and of the fluidity of the self.' } },
      { culture: { tr: 'Japon', en: 'Japanese' }, meaning: { tr: 'Bir yaratılış efsanesinde başlangıçtaki dünya, henüz katılaşmamış "denizanası gibi yüzen" bir biçimsizlikti; kurage böylece var oluşun ilk, henüz şekillenmemiş hâlini temsil eder.', en: 'In one creation myth the primordial world was a not-yet-solidified formlessness that "floated like a jellyfish"; the kurage thus represents the first, unshaped state of existence.' } },
      { culture: { tr: 'Polinezya', en: 'Polynesian' }, meaning: { tr: 'Saydam denizanası, ay ışığını ve okyanus ruhlarını taşıyan bir varlık sayılır; gece denizinde parıldaması, görünmez âlemlerin yüzeye dokunuşu olarak okunur.', en: 'The translucent jellyfish is regarded as a being that carries moonlight and ocean spirits; its glow in the night sea is read as the touch of unseen realms upon the surface.' } },
      { culture: { tr: 'Modern Deniz Bilimi / Sembolizm', en: 'Modern Marine Science / Symbolism' }, meaning: { tr: 'Turritopsis dohrnii — "ölümsüz denizanası" yaşlandığında genç polip hâline geri dönebilir; ölümü bir başlangıca çeviren bu döngü, biyolojik yeniden doğuşun çağdaş simgesi olmuştur.', en: 'Turritopsis dohrnii — the "immortal jellyfish" can revert to its young polyp stage when it ages; this cycle, turning death into a beginning, has become a contemporary emblem of biological rebirth.' } },
    ],
    myths: [
      { tr: 'Maymun ve Denizanası (Japon Masalı): Deniz ejderhası kralının vezirine maymun karaciğeri gerekince, görevi yumuşak ve saf denizanasına verir. Maymun kurnazlıkla onu kandırır; başarısızlığının cezası olarak ejderha kral denizanasının kemiklerini ezer — bu yüzden bugün denizanası omurgasız, biçimsizdir. Masal, fazla saf ve biçimsiz olmanın bedelini anlatır.', en: 'The Monkey and the Jellyfish (Japanese Tale): when the dragon king of the sea needs a monkey\'s liver, he gives the task to the soft, naïve jellyfish. The monkey tricks it cleverly; as punishment for its failure the dragon king crushes the jellyfish\'s bones — and so today the jellyfish is spineless and formless. The tale tells the price of being too naïve and too shapeless.' },
    ],
  },

  // ─── a107 Fok ───────────────────────────────────────────────────────────
  a107: {
    jung: {
      tr: 'Fok, "İki Dünya Arasındaki Yolcu" arketipidir — denizin (bilinçaltı, duygu) ve karanın (bilinç, toplum) eşiğinde yaşayan, iki âleme de ait ama hiçbirine tam ait olmayan ruh. Selkie\'nin derisini çıkarması gibi, görünüşün altındaki gerçek özlemi ve duygusal hakikati taşır.',
      en: 'The Seal is the "Traveler Between Two Worlds" archetype — a soul that lives on the threshold of the sea (the unconscious, emotion) and the land (consciousness, society), belonging to both realms yet wholly to neither. Like the selkie shedding its skin, it carries the true longing and emotional truth beneath appearances.',
    },
    dream: {
      tr: 'Rüyada fok — duyguların ile gündelik hayatın arasında bir köprü kurman gerektiğini söyler; bastırdığın bir özlem yüzeye çıkmak istiyor. Karaya çıkıyorsa: derindeki bir duyguyu nihayet dünyada ifade etme zamanı.',
      en: 'A seal in dream — tells you that you must bridge your emotions and your everyday life; a suppressed longing wishes to surface. If it comes ashore: it is time at last to express a deep feeling in the world.',
    },
    shadow: {
      tr: 'Eşikte sıkışmak: ne tamamen denize (duyguya) ne karaya (gerçekliğe) ait olamamak, sürekli bir özlemle iki dünya arasında savrulmak. Selkie gölgesi, kendi "derisini" (özgürlüğünü, gerçek doğasını) başkasının saklamasına izin verip esir düşmektir.',
      en: 'Stuck at the threshold: belonging fully neither to the sea (emotion) nor the land (reality), tossed forever between two worlds in a constant longing. The selkie\'s shadow is to let another hide your "skin" (your freedom, your true nature) and so fall captive.',
    },
    whenAppears: {
      tr: 'Derin bir duyguyla ya da özlemle yüzleşmen gereken dönemlerde; gerçek doğanı bir süre saklamış olup onu geri istemen, "derini" yeniden giyinmen gerektiği anda belirir.',
      en: 'It appears when you must face a deep emotion or longing; when you have hidden your true nature for a time and must reclaim it, must put your "skin" back on.',
    },
    traditions: [
      { culture: { tr: 'İskoç / İrlanda Kelt', en: 'Scottish / Irish Celtic' }, meaning: { tr: 'Selkie — denizde fok, karada insan biçimine giren şekil değiştirici. Derisi çalınırsa karada esir kalır; geri bulduğunda hep denize döner. Özgürlük, özlem ve gerçek doğaya sadakatin simgesi.', en: 'Selkie — a shape-shifter, seal at sea and human form on land. If its skin is stolen it remains captive ashore; when it recovers it, it always returns to the sea. A symbol of freedom, longing, and fidelity to one\'s true nature.' } },
      { culture: { tr: 'İnuit', en: 'Inuit' }, meaning: { tr: 'Foklar deniz tanrıçası Sedna\'nın parmaklarından doğan çocuklarıdır; halkın temel rızkı ve denizle insan arasındaki saygı sözleşmesinin kutsal teminatı.', en: 'Seals are the children born of the sea goddess Sedna\'s fingers; the people\'s essential sustenance and the sacred pledge of the covenant of respect between the sea and humanity.' } },
      { culture: { tr: 'İskandinav (Faroe / İzlanda)', en: 'Norse (Faroe / Iceland)' }, meaning: { tr: 'Yılda bir gece insan biçimine girip karada dans eden fok-insanlar; suya geri dönen ruhların, kayıpların ve karşılıksız özlemin anlatısı.', en: 'Seal-folk who once a year take human form and dance ashore; a narrative of souls returning to the water, of the lost, and of unrequited longing.' } },
      { culture: { tr: 'Çukçi / Sibirya', en: 'Chukchi / Siberian' }, meaning: { tr: 'Fok, kutup denizlerinin koruyucu ruhu ve avcının kendisine saygı göstermesi gereken bir armağan; doğru ritüelle avlanmazsa rızkını geri çeker.', en: 'The seal is a guardian spirit of the polar seas and a gift the hunter must honor; if not taken with the proper rite, it withdraws its sustenance.' } },
    ],
    myths: [
      { tr: 'Selkie Gelini: Bir balıkçı, kayalıkta derisini çıkarıp insana dönüşen bir selkie kadını görür ve derisini gizler. Kadın karada onunla evlenir, çocukları olur, ama gözleri hep denizdedir. Yıllar sonra çocuklarından biri saklı deriyi bulur; selkie onu giyer ve denize, gerçek evine geri döner. Hikâye, başkasının seni elinde tutması için gerçek doğanı bastırmanın sürmeyeceğini anlatır.', en: 'The Selkie Bride: a fisherman sees a selkie woman shed her skin on the rocks and turn human, and he hides the skin. She marries him ashore, bears children, yet her eyes are ever on the sea. Years later one of the children finds the hidden skin; the selkie dons it and returns to the sea, her true home. The tale tells that suppressing your true nature so another may keep you cannot last.' },
    ],
  },

  // ─── a108 Narval ────────────────────────────────────────────────────────
  a108: {
    jung: {
      tr: 'Narval, "Yanılsamayı Delen Hakikat" arketipidir — "denizin tek boynuzlu atı". Buzlu sularda görünmez gezen, alnındaki tek dişiyle (aslında uzamış bir azı diş) hakikatin tek bir noktaya odaklanmış gücünü taşır: yüzeyin altındaki gizli gerçeği delip geçen sezgi.',
      en: 'The Narwhal is the "Truth That Pierces Illusion" archetype — "the unicorn of the sea." Roaming unseen in icy waters, with the single tusk on its brow (in truth an elongated tooth) it carries the focused power of a single-pointed truth: the intuition that pierces the hidden reality beneath the surface.',
    },
    dream: {
      tr: 'Rüyada narval — bir yanılsamanın, bir yalanın ya da bir karmaşanın içinden tek bir net hakikate ulaşmak üzere olduğunu söyler. Boynuzu sana dönükse: keskin sezginle delmen gereken bir gizem var.',
      en: 'A narwhal in dream — tells you that you are about to reach a single clear truth through an illusion, a lie, or a confusion. If its tusk turns toward you: there is a mystery you must pierce with your keen intuition.',
    },
    shadow: {
      tr: 'Hakikat kılıcının gölgesi: keskin sezgiyi başkalarını delip geçen acımasız bir doğrulukla kullanmak, "ben gerçeği söylüyorum" diye yaralamak. Ya da kendi boynuzunun (yeteneğinin, farkının) onu garip ve yalnız kıldığını sanıp buzlu sulara saklanmak.', en: 'The shadow of the sword of truth: using keen intuition with a merciless rightness that pierces others, wounding under the banner of "I am only telling the truth." Or hiding away in icy waters, believing one\'s tusk (one\'s gift, one\'s difference) makes one strange and alone.',
    },
    whenAppears: {
      tr: 'Bir karmaşanın ya da aldatmanın içinden gerçeği görmen gereken dönemlerde; seni farklı kılan tekil yeteneğini saklamak yerine onurlandırman gerektiği anda belirir.',
      en: 'It appears when you must see the truth through a confusion or a deception; when you must honor rather than hide the singular gift that sets you apart.',
    },
    traditions: [
      { culture: { tr: 'İnuit', en: 'Inuit' }, meaning: { tr: 'Bir efsanede narval, denize sürüklenen kör ya da zalim bir kadının saçlarının burularak boynuza dönüşmesiyle doğar; arktik denizin gizemini ve kaderin dönüşümünü taşır.', en: 'In one legend the narwhal is born when the twisted hair of a blind or cruel woman swept into the sea becomes its horn; it carries the mystery of the Arctic sea and the turning of fate.' } },
      { culture: { tr: 'Ortaçağ Avrupası', en: 'Medieval Europe' }, meaning: { tr: 'Narval dişleri "tek boynuzlu at boynuzu" (alicorn) diye satılır, zehri etkisizleştirdiğine ve şifa verdiğine inanılırdı; kralların hazinelerinde en kıymetli, en mucizevi nesnelerdendi.', en: 'Narwhal tusks were sold as "unicorn horns" (alicorn), believed to neutralize poison and to heal; among the most precious and miraculous objects in royal treasuries.' } },
      { culture: { tr: 'Viking / Norse', en: 'Viking / Norse' }, meaning: { tr: 'Vikingler narval dişlerini uzak diyarlara büyük servet karşılığı satar, kaynağını sır olarak saklardı; diş, gizli bilgiyle korunan efsanevi bir hazinenin simgesiydi.', en: 'Vikings sold narwhal tusks to distant lands for great fortunes, keeping their source a secret; the tusk became a symbol of a legendary treasure guarded by hidden knowledge.' } },
      { culture: { tr: 'Çağdaş Sembolizm', en: 'Contemporary Symbolism' }, meaning: { tr: 'Tek boynuzlu atla kurulan bağ nedeniyle narval; saflık, sezgi ve maddi dünyanın ötesindeki gizli bilgiye erişimin simgesi sayılır.', en: 'Through its link to the unicorn, the narwhal is regarded as a symbol of purity, intuition, and access to hidden knowledge beyond the material world.' } },
    ],
    myths: [
      { tr: 'Narvalın Doğuşu (İnuit): Bir avlanma efsanesinde, oğlunu denize sürükleyen bir beyaz balinaya bağlı kadının kendisi de suya çekilir; saçları burularak narvalın spiral dişine dönüşür ve o, denizin kadim bir ruhu olur. Anlatı, kederin ve kaderin nasıl başka bir varlığa dönüştüğünü işler.', en: 'The Birth of the Narwhal (Inuit): in a hunting legend a woman bound to a beluga that drags her son to the sea is herself pulled into the water; her hair twists into the narwhal\'s spiral tusk and she becomes an ancient spirit of the sea. The tale works through how grief and fate are transformed into another being.' },
      { tr: 'Tek Boynuzlu At Aldatmacası: Ortaçağ Avrupası\'nda tüccarlar, kuzey denizlerinden gelen narval dişlerini efsanevi tek boynuzlu atın boynuzu diye satardı. Krallar zehre karşı bu "alicorn"a servetler ödedi. Yüzeydeki yanılsama (unicorn) altındaki gerçeği (narval) gizlerken, narval da yanılsamayı delen hakikatin simgesi oldu.', en: 'The Unicorn Deception: in medieval Europe merchants sold narwhal tusks from the northern seas as the horn of the legendary unicorn. Kings paid fortunes for this "alicorn" against poison. While the surface illusion (the unicorn) hid the reality beneath it (the narwhal), the narwhal itself became the symbol of the truth that pierces illusion.' },
    ],
  },

  // ─── a109 Gergedan ──────────────────────────────────────────────────────
  a109: {
    jung: {
      tr: 'Gergedan, "Zırhlı Yalnız" arketipidir — kadim, ağır, sarsılmaz bir güç; kalın derisiyle (sınırlarıyla) dünyaya karşı korunan ama yalnızlığını da onunla taşıyan benlik. Gözleri zayıf görse de toprağa kök salmış varlığıyla, dış görünüşe değil köke ve güce dayanan bir duruşu temsil eder.',
      en: 'The Rhinoceros is the "Armored Solitary" archetype — an ancient, heavy, unshakable power; a self protected against the world by its thick skin (its boundaries) yet bearing its solitude through that same hide. Though its eyes see poorly, with its earth-rooted presence it represents a stance grounded not in appearance but in root and strength.',
    },
    dream: {
      tr: 'Rüyada gergedan — sarsılmaz bir güce ve sınır koyma hakkına sahip olduğunu hatırlatır; kimse seni kolayca itemez. Sana doğru hücum ediyorsa: bastırdığın ham bir öfke ya da bir hakikat, yüzleşilmek için üzerine geliyor.',
      en: 'A rhinoceros in dream — reminds you that you possess an unshakable strength and the right to set boundaries; no one can easily push you. If it charges at you: a raw anger or a truth you have suppressed is bearing down on you to be confronted.',
    },
    shadow: {
      tr: 'Zırhın gölgesi: kalın deri öyle kalınlaşır ki kimseyi içeri almamak, sevgiye ve değişime kapanmak. Zayıf gören gözler ise körlüğe döner: yalnızca önündeki tek hedefe odaklanıp, körü körüne hücum edip etrafı çiğnemek.',
      en: 'The shadow of the armor: the thick skin thickens until it lets no one in, closing off to love and change. The weak-sighted eyes turn to blindness: fixating on the single target ahead, charging blindly and trampling all around.',
    },
    whenAppears: {
      tr: 'Sınırlarını savunman, sarsılmaz bir kararlılıkla durman gereken dönemlerde; dış baskıya karşı kendi ağırlığına ve köküne güvenmen gerektiği anda belirir.',
      en: 'It appears when you must defend your boundaries and stand with unshakable resolve; when you must trust your own weight and root against outer pressure.',
    },
    traditions: [
      { culture: { tr: 'Afrika (Çeşitli Halklar)', en: 'African (Various Peoples)' }, meaning: { tr: 'Gergedan, savanın kadim ve güçlü bir bekçisi sayılır; bazı geleneklerde gücün, dayanıklılığın ve yağmurla bağlantılı toprak enerjisinin simgesidir.', en: 'The rhinoceros is regarded as an ancient and powerful guardian of the savanna; in some traditions a symbol of strength, endurance, and an earth energy linked to the rains.' } },
      { culture: { tr: 'Hint / Vedik', en: 'Indian / Vedic' }, meaning: { tr: 'Tek boynuzlu Hint gergedanı, kralların gücünü ve kadim toprağın dayanıklılığını simgeler; bazı anlatılarda kutsal arınma törenlerinde anılır.', en: 'The single-horned Indian rhinoceros symbolizes the power of kings and the endurance of the ancient earth; in some accounts it is invoked in sacred rites of purification.' } },
      { culture: { tr: 'Rönesans Avrupası', en: 'Renaissance Europe' }, meaning: { tr: 'Dürer\'in 1515 tarihli ünlü gravüründe gergedan, zırhlı, yenilmez bir kadim güç olarak resmedildi; canlıyı görmeden çizilen bu imge yüzyıllarca Avrupa\'nın gergedan tahayyülünü belirledi.', en: 'In Dürer\'s famous 1515 woodcut the rhinoceros was depicted as an armored, invincible ancient power; drawn without ever seeing the living animal, this image shaped Europe\'s imagination of the rhino for centuries.' } },
      { culture: { tr: 'Çin', en: 'Chinese' }, meaning: { tr: 'Eski Çin\'de gergedan boynuzu kupaları koruyucu ve arındırıcı sayılırdı; gergedan, kötülüğü uzak tutan ve uzun ömür getiren bir güç simgesiydi.', en: 'In old China cups of rhino horn were held to be protective and purifying; the rhinoceros was a symbol of a power that warded off evil and brought long life.' } },
    ],
    myths: [
      { tr: 'Dürer\'in Gergedanı: 1515\'te Lizbon\'a getirilen bir Hint gergedanını hiç görmeyen Albrecht Dürer, yalnızca bir mektup tarifine dayanarak onu zırh plakalarıyla kaplı, neredeyse mitolojik bir savaş canavarı olarak çizdi. Bu hayalî zırhlı imge gerçeğinden daha güçlü çıktı ve yüzyıllar boyunca insanların zihnindeki "gergedan" oldu — algının gerçeği nasıl bükebildiğinin simgesi.', en: 'Dürer\'s Rhinoceros: Albrecht Dürer, who never saw the Indian rhinoceros brought to Lisbon in 1515, drew it from a written description alone as a near-mythological war-beast plated in armor. This imagined armored image proved more powerful than the reality and became, for centuries, the "rhinoceros" in people\'s minds — a symbol of how perception can bend the truth.' },
    ],
  },

  // ─── a110 Zürafa ────────────────────────────────────────────────────────
  a110: {
    jung: {
      tr: 'Zürafa, "Uzak Görüşlü Nazik" arketipidir — en yükseğe uzanan boynuyla geniş ufku gören, ama hareketleri zarif ve sakin olan bilgelik. Kalbinden başına kadar uzanan o uzun yol, sezgi (gönül) ile idrak (akıl) arasında köprü kuran; yükseklikten bakarken bile şiddete başvurmayan asil duruşu temsil eder.',
      en: 'The Giraffe is the "Far-Sighted Gentle One" archetype — a wisdom that, with its highest-reaching neck, sees the wide horizon, yet whose movements are graceful and calm. That long road from heart to head represents a bridge between intuition (the heart) and comprehension (the mind); a noble bearing that, even while looking down from a height, never resorts to violence.',
    },
    dream: {
      tr: 'Rüyada zürafa — olaylara daha yüksek, daha geniş bir perspektiften bakman gerektiğini söyler; uzaktaki bir fırsatı ya da tehlikeyi görme yetin açılıyor. Sana doğru eğiliyorsa: yüksek bilgeliği nazikçe sana iletiyor.',
      en: 'A giraffe in dream — tells you to look at things from a higher, wider perspective; your capacity to see a distant opportunity or danger is opening. If it bends toward you: it is gently passing high wisdom down to you.',
    },
    shadow: {
      tr: 'Yüksekten bakmanın gölgesi: o kadar uzağı ve yükseği görmek ki ayağının dibindekini, anı ve yakınındakileri ihmal etmek; tepeden bakmaya, kibre ve kopukluğa dönüşmek. Ya da boynunu uzatıp her şeyi görmek isterken kendini fazla açıkta, savunmasız bırakmak.',
      en: 'The shadow of looking down from on high: seeing so far and so high that you neglect what is at your feet, the present moment, and those nearby; turning to condescension, pride, and detachment. Or, stretching your neck to see everything, leaving yourself too exposed and defenseless.',
    },
    whenAppears: {
      tr: 'Bir duruma yukarıdan, geniş bir bakışla yaklaşman gereken dönemlerde; gücünü ve görüşünü incelikle, sertliğe başvurmadan kullanman gerektiği anda belirir.',
      en: 'It appears when you must approach a situation from above, with a wide view; when you must use your strength and sight with grace, without resorting to harshness.',
    },
    traditions: [
      { culture: { tr: 'San / Buşman (Güney Afrika)', en: 'San / Bushmen (Southern Africa)' }, meaning: { tr: 'Zürafa, yağmur dansı ritüellerinde ve kaya resimlerinde kutsal bir hayvandır; zarif yürüyüşü yağmurun ve şifanın gelişiyle ilişkilendirilen bir "yağmur hayvanı"dır.', en: 'The giraffe is a sacred animal in rain-dance rituals and rock paintings; a "rain animal" whose graceful gait is associated with the coming of rain and of healing.' } },
      { culture: { tr: 'Antik Mısır', en: 'Ancient Egypt' }, meaning: { tr: 'Zürafa (mmy) bir hiyeroglif işaretidir ve "öngörmek, kehanette bulunmak" anlamı taşır; uzaktan görme yetisi, geleceği görmenin simgesi sayılırdı.', en: 'The giraffe (mmy) is a hieroglyphic sign meaning "to foretell, to prophesy"; its ability to see from afar was regarded as a symbol of seeing the future.' } },
      { culture: { tr: 'Çin (Ming Hanedanı)', en: 'Chinese (Ming Dynasty)' }, meaning: { tr: 'Afrika\'dan getirilen ilk zürafa imparatorluk sarayında efsanevi qilin (kutsal, hayırlı yaratık) sanıldı; barışın, erdemli yönetimin ve göksel onayın uğurlu habercisi olarak kutlandı.', en: 'The first giraffe brought from Africa was taken at the imperial court for the legendary qilin (a sacred, auspicious creature); celebrated as a fortunate herald of peace, virtuous rule, and heavenly approval.' } },
      { culture: { tr: 'Doğu Afrika (Çeşitli Halklar)', en: 'East African (Various Peoples)' }, meaning: { tr: 'Zürafa, sessizliği ve narin duruşuyla zarafetin, sabrın ve geniş görüşün simgesi sayılır; sürüsünü yüksekten kollayan nazik bir gözcüdür.', en: 'With its silence and delicate bearing the giraffe is regarded as a symbol of grace, patience, and broad vision; a gentle watcher that keeps guard over its herd from on high.' } },
    ],
    myths: [
      { tr: 'Zürafa Nasıl Uzun Boylu Oldu (Afrika Halk Masalı): Bir kuraklık döneminde tüm hayvanlar otlakları tükenince, zürafa ve bir başka hayvan, sihirli bir bitkinin kökünü çiğneyerek boyunun uzamasını ister. Açgözlülük etmeyip sabırla bekleyen zürafanın boynu, en yüksek ağaçların yapraklarına uzanacak kadar uzar; böylece kuraklıkta hayatta kalır. Masal, yükseğe ulaşmanın sabır ve ölçüyle geldiğini anlatır.', en: 'How the Giraffe Got Its Height (African Folk Tale): in a time of drought, when all the animals\' pastures run dry, the giraffe and another animal chew the root of a magic plant to grow taller. The patient, ungreedy giraffe\'s neck lengthens until it can reach the leaves of the tallest trees, and so it survives the drought. The tale tells that reaching high comes through patience and measure.' },
    ],
  },

  // ─── a111 Goril ─────────────────────────────────────────────────────────
  a111: {
    jung: {
      tr: 'Goril, "Nazik Dev" arketipidir — muazzam fiziksel güce sahip ama onu gösterişe değil koruma ve dinginliğe adamış eril otorite. Gümüşsırt liderliği gibi, gerçek gücün kükremekte değil, ailenin huzurunu sessizce sağlamakta olduğunu öğreten vakarlı, ölçülü baba enerjisi.',
      en: 'The Gorilla is the "Gentle Giant" archetype — a masculine authority of immense physical strength devoted not to display but to protection and stillness. Like the silverback\'s leadership, a dignified, measured paternal energy that teaches that true power lies not in roaring but in quietly securing the family\'s peace.',
    },
    dream: {
      tr: 'Rüyada goril — içindeki sakin gücü ve koruyucu otoriteyi hatırlatır; saygı görmek için bağırmana gerek yok. Göğsünü dövüyorsa: bir sınır çizmen, varlığını sakince ama net biçimde ortaya koyman gerekiyor.',
      en: 'A gorilla in dream — reminds you of the calm strength and protective authority within you; you need not shout to be respected. If it beats its chest: you must draw a boundary, asserting your presence calmly but clearly.',
    },
    shadow: {
      tr: 'Gücün gölgesi: dinginlik bastırılmış öfkeye dönüşür ve gümüşsırt, koruyuculuğunu hükmetmeye, otoritesini zorbalığa çevirir. Ya da tersi: muazzam gücünü hiç kullanmamak, çatışmadan kaçınmak için kendini sürekli geri çekip ailesini savunamamak.',
      en: 'The shadow of strength: stillness turns into suppressed rage, and the silverback turns its protection into domination, its authority into tyranny. Or the reverse: never using its immense strength, withdrawing endlessly to avoid conflict and so failing to defend its family.',
    },
    whenAppears: {
      tr: 'Bir grubu ya da aileyi sakin bir otoriteyle korumana ihtiyaç duyulan dönemlerde; gücünü kanıtlamak yerine onu ölçülü ve vakarlı biçimde taşıman gerektiği anda belirir.',
      en: 'It appears when a group or family needs to be protected by a calm authority; when you must carry your strength with measure and dignity rather than proving it.',
    },
    traditions: [
      { culture: { tr: 'Orta Afrika (Çeşitli Halklar)', en: 'Central African (Various Peoples)' }, meaning: { tr: 'Goril, ormanın güçlü ve saygın bir varlığı sayılır; bazı geleneklerde atalarla ya da orman ruhlarıyla bağlantılı, gücüne saygı duyulması gereken bir akraba olarak görülür.', en: 'The gorilla is regarded as a powerful and respected being of the forest; in some traditions seen as a kin linked to the ancestors or forest spirits, whose strength must be honored.' } },
      { culture: { tr: 'Antik Kartaca', en: 'Ancient Carthage' }, meaning: { tr: 'Kâşif Hanno\'nun M.Ö. 5. yüzyıldaki Batı Afrika seferinde karşılaştığı "gorillai" adlı tüylü, vahşi varlıklar; "goril" adının ve Avrupa hayalindeki gizemli orman devinin kökeni.', en: 'The hairy, wild beings called "gorillai" that the explorer Hanno met on his 5th-century BCE voyage along West Africa; the origin of the name "gorilla" and of the mysterious forest giant in the European imagination.' } },
      { culture: { tr: 'Bantu Geleneği', en: 'Bantu Tradition' }, meaning: { tr: 'Büyük maymunlar, bazı Bantu anlatılarında insan ile orman arasındaki sınırda yaşayan, hem korkulan hem saygı duyulan akrabalar; doğanın gücünü ve aile düzenini temsil eder.', en: 'The great apes, in some Bantu narratives, are kin who live on the border between humanity and the forest, both feared and respected; they represent the power of nature and the order of the family.' } },
      { culture: { tr: 'Modern Sembolizm', en: 'Modern Symbolism' }, meaning: { tr: 'Gümüşsırt goril çağdaş kültürde sessiz liderliğin, aile koruyuculuğunun ve gereksiz şiddete başvurmayan asil gücün simgesi hâline gelmiştir.', en: 'The silverback gorilla has become, in contemporary culture, a symbol of quiet leadership, family protection, and a noble strength that does not stoop to needless violence.' } },
    ],
    myths: [
      { tr: 'Hanno\'nun Gorillaisi: Kartacalı denizci Hanno, Batı Afrika kıyısını keşfederken bir adada tüylü, vahşi varlıklarla karşılaşır; yerli rehberleri onlara "gorillai" der. Hanno\'nun kayıtları yüzyıllar sonra bu büyük maymunlara adını verir. Anlatı, bilinmeyenin sınırındaki güçlü, gizemli varlığın insan hayalinde nasıl efsaneleştiğini gösterir.', en: 'Hanno\'s Gorillai: the Carthaginian seafarer Hanno, exploring the West African coast, encounters hairy, wild beings on an island; his native guides call them "gorillai." Hanno\'s account, centuries later, gives these great apes their name. The narrative shows how a powerful, mysterious being on the edge of the unknown is mythologized in the human imagination.' },
    ],
  },

  // ─── a112 Panda ─────────────────────────────────────────────────────────
  a112: {
    jung: {
      tr: 'Panda, "Dengelenmiş Zıtlık" arketipidir — siyah ve beyazı, gücü ve nazikliği, yalnızlığı ve sevimliliği tek bedende uzlaştıran yin-yang varlığı. Ayı gücüne sahip olduğu hâlde bambunun sadeliğiyle yetinen; çatışmayı değil dinginliği seçen, az ile çok yaşamayı bilen Tao bilgeliği.',
      en: 'The Panda is the "Reconciled Opposites" archetype — a yin-yang being that harmonizes black and white, strength and gentleness, solitude and endearment in a single body. Though it possesses the strength of a bear, it is content with the simplicity of bamboo; a Taoist wisdom that chooses stillness over conflict and knows how to live abundantly with little.',
    },
    dream: {
      tr: 'Rüyada panda — hayatındaki zıtlıkları (iş ve dinlenme, güç ve yumuşaklık) dengelemen gerektiğini söyler; sadeliğe ve barışa dönme çağrısı. Huzurla bambu yiyorsa: ihtiyacın olan şey daha fazlası değil, sahip olduğunla dingin olmak.',
      en: 'A panda in dream — tells you to balance the opposites in your life (work and rest, strength and softness); a call to return to simplicity and peace. If it eats bamboo in serenity: what you need is not more, but stillness with what you already have.',
    },
    shadow: {
      tr: 'Dengenin gölgesi: barışı korumak için her şeyden geri çekilmek, çatışmadan o kadar kaçmak ki edilgenliğe ve yalıtılmışlığa gömülmek. Ya da sadeliği bahane edip büyümeyi, gücünü kullanmayı reddetmek — bambunun konforunda uyuşmak.',
      en: 'The shadow of balance: withdrawing from everything to keep the peace, fleeing conflict so thoroughly that you sink into passivity and isolation. Or using simplicity as an excuse to refuse growth and the use of your strength — going numb in the comfort of bamboo.',
    },
    whenAppears: {
      tr: 'Hayatındaki uçları dengelemen, sadeliğe ve iç huzura dönmen gereken dönemlerde; güçlü olduğun hâlde nazik ve barışçıl kalmayı seçmen gerektiği anda belirir.',
      en: 'It appears when you must balance the extremes in your life and return to simplicity and inner peace; when you must choose to remain gentle and peaceful even though you are strong.',
    },
    traditions: [
      { culture: { tr: 'Çin (Tao)', en: 'Chinese (Taoist)' }, meaning: { tr: 'Pandanın siyah-beyaz deseni yin ve yang\'ın mükemmel dengesini cisimleştirir; karşıt güçlerin uyumunu, ölçüyü ve doğayla akış içinde yaşamayı simgeler.', en: 'The panda\'s black-and-white pattern embodies the perfect balance of yin and yang; it symbolizes the harmony of opposing forces, measure, and living in flow with nature.' } },
      { culture: { tr: 'Eski Çin (Han Hanedanı)', en: 'Ancient China (Han Dynasty)' }, meaning: { tr: 'Panda kadim Çin\'de barışın ve diplomasinin simgesi sayılırdı; bir efsaneye göre savaşan taraflar pandanın bayrağı altında ateşkes ilan ederdi, çünkü panda hiçbir canlıyı incitmez.', en: 'In ancient China the panda was regarded as a symbol of peace and diplomacy; by one legend warring sides declared truce under the panda\'s banner, for the panda harms no living thing.' } },
      { culture: { tr: 'Tibet / Çin Sınır Halkları', en: 'Tibetan / Sino-Border Peoples' }, meaning: { tr: 'Bir efsanede pandanın kara lekeleri, ölen bir çobanı yası tutan pandaların gözlerini, kollarını ve kulaklarını kül-gözyaşıyla karartmasından doğar; pandayı şefkat ve yas ile ilişkilendirir.', en: 'In one legend the panda\'s black markings arise when pandas mourning a dead shepherdess blacken their eyes, arms, and ears with ash and tears; it links the panda with compassion and grief.' } },
      { culture: { tr: 'Modern Çin', en: 'Modern China' }, meaning: { tr: 'Panda ulusal bir simge ve "panda diplomasisi" aracı hâline gelmiştir; barış, dostluk ve uluslar arası uyumun çağdaş elçisidir.', en: 'The panda has become a national symbol and the instrument of "panda diplomacy"; a contemporary envoy of peace, friendship, and harmony among nations.' } },
    ],
    myths: [
      { tr: 'Pandanın Kara Lekeleri: Bir Çin efsanesinde pandalar bir zamanlar bembeyazdı. Onları leoparlardan koruyan genç bir çoban kız bir gün bir yavru pandayı kurtarırken can verir. Pandalar cenazesinde yas tutarken, geleneğe göre kollarına kül sürerler; ağlarken gözlerini sildiklerinde, kucaklaştıklarında ve kulaklarını kapattıklarında kül her yere bulaşır. O günden beri pandalar yaslarını siyah lekeler olarak taşır — şefkatin ve kaybın izi.', en: 'The Panda\'s Black Markings: in a Chinese legend pandas were once pure white. A young shepherdess who protected them from leopards dies one day saving a panda cub. As the pandas mourn at her funeral, by custom they smear ash on their arms; when they wipe their weeping eyes, embrace one another, and cover their ears, the ash spreads everywhere. Ever since, pandas carry their grief as black markings — the trace of compassion and loss.' },
    ],
  },

  // ─── a113 Köstebek ──────────────────────────────────────────────────────
  a113: {
    jung: {
      tr: 'Köstebek, "Yeraltının Bilgesi" arketipidir — gözleri görmese de toprağın altında, karanlıkta yolunu bulan iç görü. Dış dünyanın ışığına değil, sezgiye ve dokunuşa güvenen bilinçaltı kâşifi; gizli olanı, bastırılmışı, kökleri eşeleyip yüzeye çıkaran sessiz emek.',
      en: 'The Mole is the "Sage of the Underground" archetype — an inner sight that finds its way in the dark beneath the earth, though its eyes do not see. An explorer of the unconscious that trusts not the light of the outer world but intuition and touch; a silent labor that digs up the hidden, the repressed, the roots, and brings them to the surface.',
    },
    dream: {
      tr: 'Rüyada köstebek — gözle görülmeyeni, yüzeyin altındaki gizli bir gerçeği sezginle bulman gerektiğini söyler. Yeraltında ilerliyorsa: görünmeyen, sabırlı bir emek seni hedefe götürüyor; sonuç henüz yüzeyde görünmese de.',
      en: 'A mole in dream — tells you to find with your intuition what the eye does not see, a hidden truth beneath the surface. If it tunnels underground: an unseen, patient labor is carrying you toward your goal, though the result is not yet visible at the surface.',
    },
    shadow: {
      tr: 'Yeraltının gölgesi: ışığa, yüzeye, başkalarına hiç çıkmamak; sürekli kendi karanlık tünellerinde, geçmişte ya da takıntılarda eşelenip dünyaya kör kalmak. Köstebek gölgesi, içe dönüklüğü saplantılı bir izolasyona ve görünmeyene takılı bir körlüğe çevirir.',
      en: 'The shadow of the underground: never coming up to the light, to the surface, to others; forever digging in your own dark tunnels, in the past or in obsessions, and staying blind to the world. The mole\'s shadow turns introversion into an obsessive isolation and a blindness fixed on the unseen.',
    },
    whenAppears: {
      tr: 'Yüzeydeki gürültüden çekilip içe, derine, gizli olana yönelmen gereken dönemlerde; görünmez ve sabırlı bir emekle, sonucu hemen görmeden çalışman gerektiği anda belirir.',
      en: 'It appears when you must withdraw from the noise of the surface and turn inward, deep, to the hidden; when you must work with an unseen and patient labor, without seeing the result at once.',
    },
    traditions: [
      { culture: { tr: 'Kızılderili (Çeşitli Halklar)', en: 'Native American (Various Peoples)' }, meaning: { tr: 'Köstebek, yeraltı dünyasının ve toprak enerjisinin bekçisi sayılır; körlüğü bir eksiklik değil, iç görüye ve toprağa kulak verme yetisi olarak yorumlanır.', en: 'The mole is regarded as a keeper of the underworld and of earth energy; its blindness is read not as a lack but as the capacity for inner sight and for listening to the earth.' } },
      { culture: { tr: 'Avrupa Folkloru', en: 'European Folklore' }, meaning: { tr: 'Köstebek tepecikleri ve gizli yolları nedeniyle köstebek; saklı bilginin, görünmez emeğin ve toprağın altındaki sırların simgesidir. Bazı geleneklerde uğurlu, bazılarında ise alttan iş çeviren kurnazlığın işareti.', en: 'For its molehills and hidden paths the mole is a symbol of secret knowledge, of unseen labor, and of secrets beneath the earth. In some traditions auspicious, in others a sign of cunning that works from below.' } },
      { culture: { tr: 'Antik Yunan', en: 'Ancient Greek' }, meaning: { tr: 'Kör kâhin Tiresias\'ın bir versiyonunda köstebeğe dönüştürüldüğü anlatılır; körlük ile içsel bilgelik, görünenin ötesini görme yetisi arasında bağ kurulur.', en: 'In one version of the blind seer Tiresias he is said to be turned into a mole; a link is drawn between blindness and inner wisdom, the capacity to see beyond the visible.' } },
      { culture: { tr: 'Slav Folkloru', en: 'Slavic Folklore' }, meaning: { tr: 'Köstebek yeraltının ve ölüler diyarının eşiğinde duran bir varlık sayılır; toprağı bilen, gizli zenginlikleri ve kökleri tanıyan kadim bir işçi olarak görülür.', en: 'The mole is regarded as a being standing at the threshold of the underground and the realm of the dead; seen as an ancient laborer that knows the earth, the hidden riches, and the roots.' } },
    ],
    myths: [
      { tr: 'Köstebek ile Güneş (Halk Masalı): Bir efsaneye göre köstebek bir zamanlar gören gözlere sahipti, ama yeraltının zenginliklerine ve sırlarına o kadar tutkundu ki güneşe ve yüzeyin dünyasına sırtını döndü. Karanlıkta yaşamayı seçtiği için gözleri zamanla kapandı; karşılığında dokunuşu ve sezgisi öyle keskinleşti ki toprağın altında hiç yolunu şaşırmaz oldu. Masal, bir duyuyu kaybedenin bir başkasını nasıl bilgeliğe çevirdiğini anlatır.', en: 'The Mole and the Sun (Folk Tale): by one legend the mole once had seeing eyes, but it was so enamored of the riches and secrets of the underground that it turned its back on the sun and the world of the surface. Because it chose to live in darkness its eyes closed over time; in return its touch and intuition grew so keen that it never loses its way beneath the earth. The tale tells how one who loses a sense turns another into wisdom.' },
    ],
  },

  // ─── a114 Pangolin ──────────────────────────────────────────────────────
  a114: {
    jung: {
      tr: 'Pangolin, "Korunan Kutsal" arketipidir — tehlike anında kıvrılıp pulları dışta tek bir küre olan, kendini şiddetle değil teslimiyetle ve sabırla koruyan varlık. Zırhının altındaki yumuşaklığı saklayan; saldırmadan, yalnızca toparlanıp bekleyerek hayatta kalan içsel sığınak ve dokunulmazlık.',
      en: 'The Pangolin is the "Protected Sacred" archetype — a being that, in danger, curls into a single sphere with its scales facing out, defending itself not by force but by surrender and patience. It hides the softness beneath its armor; an inner sanctuary and inviolability that survives without attacking, only by gathering in and waiting.',
    },
    dream: {
      tr: 'Rüyada pangolin — kendini koruman, bir süre içine çekilip dış dünyaya kapanman gerektiğini söyler; bu bir kaçış değil, kutsal bir savunmadır. Kıvrılıp top oluyorsa: saldırmadan, yalnızca sınır koyup yumuşak özünü koruyarak güvende kalabilirsin.',
      en: 'A pangolin in dream — tells you to protect yourself, to withdraw inward for a time and close off to the outer world; this is not flight but a sacred defense. If it curls into a ball: you can stay safe without attacking, only by setting a boundary and guarding your soft core.',
    },
    shadow: {
      tr: 'Zırhın gölgesi: tehlike geçtikten çok sonra bile açılamamak, sürekli kıvrılıp herkese ve her şeye kapanmak; korunmayı bir hapishaneye çevirmek. Pangolin gölgesi, yumuşak özünü o kadar saklar ki sevgiye, temasa ve hayata kapanır — güvenlik, yalnızlığa dönüşür.',
      en: 'The shadow of the armor: being unable to unfurl long after the danger has passed, forever curling up and closing off to everyone and everything; turning protection into a prison. The pangolin\'s shadow hides its soft core so well that it shuts out love, touch, and life — safety turns into solitude.',
    },
    whenAppears: {
      tr: 'Kendini koruman, hassas özünü dış tehditten sakınman gereken dönemlerde; savaşmak yerine sabırla içine çekilip fırtınanın geçmesini beklemen gerektiği anda belirir.',
      en: 'It appears when you must protect yourself and shield your tender core from outer threat; when you must withdraw inward with patience and wait out the storm rather than fight.',
    },
    traditions: [
      { culture: { tr: 'Güney Afrika (Tswana / Venda)', en: 'Southern African (Tswana / Venda)' }, meaning: { tr: 'Pangolin son derece kutsal ve nadir bir armağan sayılır; bir pangolin görmek ya da bulmak büyük bir uğur ve yağmurla, bereketle ilişkili kutsal bir işarettir — şefe sunulacak kadar değerlidir.', en: 'The pangolin is regarded as an exceedingly sacred and rare gift; to see or find one is great fortune, a sacred sign linked with rain and abundance — precious enough to be presented to the chief.' } },
      { culture: { tr: 'Lele (Kongo)', en: 'Lele (Congo)' }, meaning: { tr: 'Lele halkı için pangolin, sınıflandırmaya sığmayan kutsal bir varlıktır (pullu ama memeli, ağaca da çıkar, suya da girer); şifa ve bereket törenlerinde merkezde yer alan kutsal bir aracı.', en: 'For the Lele people the pangolin is a sacred being that defies classification (scaled yet a mammal, climbing trees and entering water); a sacred mediator at the heart of rites of healing and fertility.' } },
      { culture: { tr: 'Çin / Güneydoğu Asya', en: 'Chinese / Southeast Asian' }, meaning: { tr: 'Pangolin geleneksel olarak yeraltını ve yerüstünü birbirine bağlayan bir varlık (chuan shan jia — "dağı delen") sayılır; gizli geçitlerin ve dünyalar arası bağın simgesi.', en: 'The pangolin is traditionally regarded as a being that connects the underworld and the surface (chuan shan jia — "the one that bores through the mountain"); a symbol of hidden passages and of the link between worlds.' } },
      { culture: { tr: 'Batı Afrika (Çeşitli Halklar)', en: 'West African (Various Peoples)' }, meaning: { tr: 'Pangolin, zararsızlığı ve kendini yalnızca savunmayla koruması nedeniyle barışın, masumiyetin ve şiddetsiz dayanıklılığın simgesi sayılır; bazı geleneklerde dokunulmaz, korunması gereken kutsal hayvan.', en: 'For its harmlessness and its purely defensive self-protection the pangolin is regarded as a symbol of peace, innocence, and nonviolent endurance; in some traditions an inviolable, sacred animal that must be protected.' } },
    ],
    myths: [
      { tr: 'Pangolin Armağanı (Güney Afrika): Birçok Güney Afrika geleneğinde, bir pangolinle karşılaşmak son derece nadir ve kutsal bir olaydır. Bulunan bir pangolinin yağmur getirdiğine, kuraklığı sona erdirdiğine inanılır; bu yüzden onu bulan kişi onu şefe ya da yağmur yapıcıya sunar. Şiddete başvurmadan yalnızca kıvrılıp kendini koruyan bu varlık, savunmasız görünenin nasıl kutsal sayılabileceğini gösterir.', en: 'The Pangolin Gift (Southern Africa): in many Southern African traditions, to encounter a pangolin is an exceedingly rare and sacred event. A pangolin that is found is believed to bring rain and end drought; so the one who finds it presents it to the chief or the rainmaker. This being, which protects itself only by curling up without recourse to violence, shows how the seemingly defenseless can be held sacred.' },
    ],
  },

  // ─── a115 Grifon ────────────────────────────────────────────────────────
  a115: {
    jung: {
      tr: 'Grifon, "Hazinenin Bekçisi" arketipidir — aslanın (yerin, gücün kralı) ve kartalın (göğün, ruhun kralı) birleşmesi; madde ile ruhun, içgüdü ile bilgeliğin tek bedendeki sentezi. Altını ve kutsal sırrı koruyan ilahi muhafız: gerçek değere ancak onun denemesini geçenin erişebildiği eşik bekçisi.',
      en: 'The Griffin is the "Guardian of Treasure" archetype — the union of the lion (king of earth and strength) and the eagle (king of sky and spirit); the synthesis, in one body, of matter and spirit, of instinct and wisdom. A divine guardian that protects gold and the sacred secret: a threshold-keeper to whose treasure only the one who passes its trial may reach.',
    },
    dream: {
      tr: 'Rüyada grifon — değerli bir şeyi (bir yeteneği, bir hakikati, bir mirası) koruman ya da onu hak ederek kazanman gerektiğini söyler. Bir kapıda nöbet tutuyorsa: önemli bir eşiğin önündesin ve geçmek için bir sınavın var.',
      en: 'A griffin in dream — tells you to guard something precious (a gift, a truth, an inheritance) or to earn it by deserving it. If it stands watch at a gate: you are before an important threshold and have a trial to pass to cross it.',
    },
    shadow: {
      tr: 'Bekçinin gölgesi: koruduğun hazinenin (gücünün, bilginin, sevdiklerinin) üzerine öyle abanmak ki onu kimseyle paylaşamamak, kıskanç ve saldırgan bir muhafıza dönüşmek. Grifon gölgesi, koruma içgüdüsünü cimriliğe ve kapalılığa; bekçiliği hapishane gardiyanlığına çevirir.',
      en: 'The shadow of the guardian: clinging so tightly to the treasure you protect (your power, your knowledge, your loved ones) that you can share it with no one, turning into a jealous and aggressive sentinel. The griffin\'s shadow turns the instinct to protect into miserliness and closure; the keeper into a prison warden.',
    },
    whenAppears: {
      tr: 'Değerli bir şeyi koruman ya da bir eşikten geçmeyi hak etmen gereken dönemlerde; içindeki yer (güç) ile gök (ruh) güçlerini birleştirip bütünlüğüne sahip çıkman gerektiği anda belirir.',
      en: 'It appears when you must guard something precious or earn passage across a threshold; when you must unite the earth (strength) and sky (spirit) powers within you and claim your wholeness.',
    },
    traditions: [
      { culture: { tr: 'Antik Yunan', en: 'Ancient Greek' }, meaning: { tr: 'Grifonlar, kuzeyin uçlarındaki altın yataklarını tek gözlü Arimaspların hırsızlığından koruyan efsanevi bekçilerdir; hazinenin ve dokunulmaz kutsalın muhafızı.', en: 'Griffins are the legendary guardians that protect the gold deposits at the edges of the north from the theft of the one-eyed Arimaspians; keepers of treasure and of the inviolable sacred.' } },
      { culture: { tr: 'Pers / İran', en: 'Persian / Iranian' }, meaning: { tr: 'Pers sanatında (Persepolis kabartmaları) grifon, kraliyet gücünün ve ilahi korumanın simgesidir; tahtın ve kutsal düzenin bekçisi olarak saray kapılarını süsler.', en: 'In Persian art (the Persepolis reliefs) the griffin is a symbol of royal power and divine protection; adorning palace gates as guardian of the throne and of the sacred order.' } },
      { culture: { tr: 'İskit', en: 'Scythian' }, meaning: { tr: 'İskit altın işçiliğinde grifon en sık işlenen figürlerdendir; bozkırın altınını ve ölülerin hazinesini koruyan, göçebe gücünün ve öteki dünyanın muhafızı.', en: 'In Scythian goldwork the griffin is among the most frequently wrought figures; guardian of the steppe\'s gold and of the treasure of the dead, sentinel of nomadic power and of the otherworld.' } },
      { culture: { tr: 'Ortaçağ Hristiyan', en: 'Medieval Christian' }, meaning: { tr: 'Grifon, aslanın (yer) ve kartalın (gök) birliğiyle hem insani hem ilahi doğayı taşıyan İsa\'nın bir simgesi sayıldı; göğü ve yeri birleştiren, sadakatin ve gücün bekçisi.', en: 'The griffin, uniting the lion (earth) and the eagle (sky), was taken as a symbol of Christ bearing both human and divine natures; a keeper of fidelity and strength that unites heaven and earth.' } },
    ],
    myths: [
      { tr: 'Grifonlar ve Arimasplar: Antik Yunan coğrafyacılarının (Herodotos, Aristeas) anlattığına göre, dünyanın kuzey uçlarında, soğuk dağların ardında grifonlar altın madenlerini korur. Tek gözlü göçebe halk Arimasplar bu altını çalmaya çalışır ve grifonlarla bitmek bilmez bir savaş içindedir. Anlatı, en büyük hazineye ancak en güçlü bekçiyi aşabilenin ulaşabileceğini söyler — değer, onu koruyan tehlikeyle ölçülür.', en: 'Griffins and the Arimaspians: as the ancient Greek geographers (Herodotus, Aristeas) tell, at the northern edges of the world, beyond the cold mountains, griffins guard the gold mines. The one-eyed nomadic Arimaspians try to steal this gold and are locked in endless war with the griffins. The tale says that only the one who can overcome the strongest guardian may reach the greatest treasure — worth is measured by the danger that protects it.' },
    ],
  },

  // ─── a116 Sfenks ────────────────────────────────────────────────────────
  a116: {
    jung: {
      tr: 'Sfenks, "Eşik Bekçisi ve Bilmecenin Sahibi" arketipidir — insan başı (bilinç, akıl) ile aslan bedeninin (içgüdü, güç) birliği; iki dünya arasındaki kapıda duran, geçmek isteyene bir sır soran muhafız. Cevabı kendi içinde olan bir bilmeceyle, kişiyi gerçek benliğiyle yüzleşmeye zorlayan kadim bilgelik.',
      en: 'The Sphinx is the "Threshold Guardian and Keeper of the Riddle" archetype — the union of a human head (consciousness, reason) and a lion\'s body (instinct, strength); a guardian standing at the gate between two worlds, posing a secret to whoever would pass. An ancient wisdom that, with a riddle whose answer lies within, forces a person to confront their true self.',
    },
    dream: {
      tr: 'Rüyada sfenks — önemli bir eşikte olduğunu ve geçmek için bir bilmeceyi (bir hayat sorusunu, bir sırrı) çözmen gerektiğini söyler. Sana bir soru soruyorsa: cevabı dışarıda arama, o senin içinde gizli.',
      en: 'A sphinx in dream — tells you that you are at an important threshold and must solve a riddle (a life question, a secret) to pass. If it poses a question: do not seek the answer outside; it is hidden within you.',
    },
    shadow: {
      tr: 'Bilmecenin gölgesi: her şeyi gizemle, sırla ve çözülmez bilmecelerle örtmek; açık ve dürüst olmak yerine başkalarını sonu gelmez bir muammada bırakmak. Sfenks gölgesi, bilgisini bir güç oyununa çevirir ve cevaplanamayan soruyu çözenleri yutar — kibrin ve manipülasyonun bekçisi.',
      en: 'The shadow of the riddle: veiling everything in mystery, secrecy, and unsolvable riddles; leaving others in an endless enigma instead of being open and honest. The sphinx\'s shadow turns its knowledge into a power game and devours those who cannot solve the unanswerable question — a guardian of pride and manipulation.',
    },
    whenAppears: {
      tr: 'Bir hayat eşiğinde, büyük bir sırrı ya da kendine dair bir soruyu çözmen gereken dönemlerde; gizli bir bilgiye ancak iç dürüstlükle erişebileceğin anda belirir.',
      en: 'It appears at a threshold of life, when you must solve a great secret or a question about yourself; when you can reach a hidden knowledge only through inner honesty.',
    },
    traditions: [
      { culture: { tr: 'Antik Mısır', en: 'Ancient Egypt' }, meaning: { tr: 'Giza\'nın Büyük Sfenksi, kutsal mabedlerin ve kralın mezarının bekçisidir; firavunun gücünü, güneş tanrısını ve görünen ile görünmez âlemin eşiğini koruyan hayırlı bir muhafız.', en: 'The Great Sphinx of Giza is the guardian of the sacred temples and the king\'s tomb; a benevolent protector of the pharaoh\'s power, of the sun god, and of the threshold between the seen and unseen realms.' } },
      { culture: { tr: 'Antik Yunan', en: 'Ancient Greek' }, meaning: { tr: 'Thebai Sfenksi, kente musallat olan, bilmecesini çözemeyenleri öldüren bir canavardır; bilginin sınavını ve cevaplanamayan sorunun ölümcül eşiğini temsil eder.', en: 'The Sphinx of Thebes is a monster that plagues the city and kills those who cannot solve its riddle; it represents the trial of knowledge and the deadly threshold of the unanswerable question.' } },
      { culture: { tr: 'Mezopotamya / Yakın Doğu', en: 'Mesopotamian / Near Eastern' }, meaning: { tr: 'İnsan başlı, kanatlı aslan-boğa muhafızlar (lamassu/şedu), saray ve tapınak kapılarını kötülükten koruyan eşik bekçileridir; sfenks imgesinin kadim akrabaları.', en: 'The human-headed, winged lion-bull guardians (lamassu/shedu) are threshold-keepers protecting palace and temple gates from evil; ancient kin of the sphinx image.' } },
      { culture: { tr: 'Hellenistik / Roma', en: 'Hellenistic / Roman' }, meaning: { tr: 'Sfenks, sır saklamanın ve gizemli bilgeliğin simgesi olarak mezar taşlarını ve tapınak girişlerini bekler; bilginin sessiz, gizemli bekçisi.', en: 'The sphinx, as a symbol of keeping secrets and of mysterious wisdom, watches over tombstones and temple entrances; the silent, enigmatic guardian of knowledge.' } },
    ],
    myths: [
      { tr: 'Oidipus ve Sfenks: Thebai\'yi kuşatan Sfenks, kente girmek isteyen herkese şu bilmeceyi sorar: "Sabah dört, öğlen iki, akşam üç ayak üstünde yürüyen nedir?" Cevap veremeyeni boğar. Oidipus cevabı bulur: "İnsan — bebekken emekler, yetişkinken iki ayakla, yaşlanınca bastonla yürür." Bilmece çözülünce Sfenks kendini uçurumdan atar. Anlatı, en büyük eşik bekçisinin sorusunun aslında insanın kendisi olduğunu gösterir.', en: 'Oedipus and the Sphinx: the Sphinx besieging Thebes asks all who would enter the city this riddle: "What walks on four legs in the morning, two at noon, and three in the evening?" It strangles whoever cannot answer. Oedipus finds the answer: "Man — as an infant he crawls, as an adult he walks on two legs, in old age he leans on a cane." When the riddle is solved the Sphinx throws itself from the cliff. The tale shows that the greatest threshold guardian\'s question is, in truth, the human being itself.' },
    ],
  },

  // ─── a117 Pegasus ───────────────────────────────────────────────────────
  a117: {
    jung: {
      tr: 'Pegasus, "Yaratıcı Yükseliş" arketipidir — kanatlı at; yaşam gücünün (atın) ruhsal ilhamla (kanatların) birleşip yere bağlı içgüdüyü göğe taşımasıdır. Medusa\'nın (bastırılmış dehşetin, gölgenin) kanından doğması, en karanlık yaranın bile şiirsel ilhama ve yükselişe dönüşebileceğini söyler.',
      en: 'Pegasus is the "Creative Ascent" archetype — the winged horse; the life force (the horse) uniting with spiritual inspiration (the wings) to carry earthbound instinct to the sky. Its birth from the blood of Medusa (the repressed terror, the shadow) tells that even the darkest wound can be transformed into poetic inspiration and ascent.',
    },
    dream: {
      tr: 'Rüyada Pegasus — yaratıcı bir ilhamın ya da bir hayalin seni yükseltmek üzere olduğunu söyler; ayakların yerden kesilecek. Onu eyerleyebiliyorsan: ham tutkunu ilhama dönüştürüp yükselebilirsin. Seni düşürüyorsa: kibre kapılmadan, ölçüyle uç.',
      en: 'Pegasus in dream — tells you that a creative inspiration or a dream is about to lift you; your feet will leave the ground. If you can saddle it: you can transform raw passion into inspiration and rise. If it throws you down: fly with measure, without falling into pride.',
    },
    shadow: {
      tr: 'Yükselişin gölgesi: ilhamın ve hayal gücünün kanatlarıyla o kadar yükseğe çıkmak ki gerçeklikten kopmak, ayağın yerden kesilip Bellerophon gibi kibre kapılarak düşmek. Ya da tam tersi: kanatları olduğu hâlde hiç uçmamak, ilhamı eyerleyip kullanamadan yerde tutmak.',
      en: 'The shadow of ascent: rising so high on the wings of inspiration and imagination that you break from reality, your feet leaving the ground until, like Bellerophon, you fall through pride. Or the opposite: never flying though you have wings, keeping inspiration grounded, unable to saddle and use it.',
    },
    whenAppears: {
      tr: 'Yaratıcı bir ilhamın, bir hayalin ya da bir tutkunun seni yeni bir yüksekliğe taşımak istediği dönemlerde; bir yarayı ya da karanlığı sanata ve yükselişe dönüştürmen gerektiği anda belirir.',
      en: 'It appears when a creative inspiration, a dream, or a passion wishes to carry you to a new height; when you must transform a wound or a darkness into art and ascent.',
    },
    traditions: [
      { culture: { tr: 'Antik Yunan', en: 'Ancient Greek' }, meaning: { tr: 'Pegasus, Medusa\'nın kesilen başından doğan kanatlı attır; Olympos\'a Zeus\'un şimşeklerini taşır ve ilham perilerinin (Musaların) dağında yaşar — şiirsel ilhamın ve göksel yükselişin simgesi.', en: 'Pegasus is the winged horse born from Medusa\'s severed head; he bears Zeus\'s thunderbolts to Olympus and dwells on the mountain of the Muses — a symbol of poetic inspiration and heavenly ascent.' } },
      { culture: { tr: 'Yunan (Musalar / Helikon)', en: 'Greek (Muses / Helicon)' }, meaning: { tr: 'Pegasus toynağını yere vurduğunda Helikon Dağı\'nda Hippokrene ("at pınarı") kaynağı fışkırır; bu sudan içen şairlere ilham geleceğine inanılır — yaratıcılığın kaynağı.', en: 'When Pegasus strikes the earth with his hoof, the spring Hippocrene ("the horse\'s fountain") gushes forth on Mount Helicon; poets who drink from this water are believed to receive inspiration — the wellspring of creativity.' } },
      { culture: { tr: 'Rönesans / Avrupa', en: 'Renaissance / European' }, meaning: { tr: 'Pegasus, Rönesans\'tan beri sanatın, şiirin ve dehanın amblemi olmuştur; yer ile gök arasında köprü kuran, maddi olandan ilahi ilhama yükselişin simgesi.', en: 'Since the Renaissance Pegasus has been the emblem of art, poetry, and genius; a symbol of the bridge between earth and sky, of the ascent from the material to divine inspiration.' } },
      { culture: { tr: 'Astronomi / Babil-Yunan', en: 'Astronomy / Babylonian-Greek' }, meaning: { tr: 'Pegasus gökyüzüne bir takımyıldız olarak yerleştirilir; sonsuz yükselişin, ölümlü olanın ölümsüzlüğe kavuşmasının ve ruhun göğe yazılmasının simgesidir.', en: 'Pegasus is set in the sky as a constellation; a symbol of endless ascent, of the mortal attaining immortality, and of the soul inscribed upon the heavens.' } },
    ],
    myths: [
      { tr: 'Pegasus\'un Doğuşu ve Bellerophon: Perseus, Medusa\'nın başını kestiğinde, gorgonun kanından kanatlı at Pegasus fışkırır — dehşetin içinden doğan güzellik. Kahraman Bellerophon onu Athena\'nın armağanı altın bir gemle ehlileştirir ve sırtında Khimera canavarını öldürür. Ama zafer kibre dönüşünce Bellerophon Pegasus\'la Olympos\'a, tanrıların katına çıkmaya kalkar; Zeus bir at sineği gönderir, Pegasus şahlanır ve Bellerophon yere düşer. Pegasus tek başına göğe yükselip yıldızlar arasına yerleşir. Anlatı, ilhamın yükseltebileceğini ama kibrin düşüreceğini söyler.', en: 'The Birth of Pegasus and Bellerophon: when Perseus severs Medusa\'s head, the winged horse Pegasus springs from the gorgon\'s blood — beauty born from terror. The hero Bellerophon tames him with a golden bridle, Athena\'s gift, and on his back slays the Chimera. But when victory turns to pride, Bellerophon tries to ride Pegasus to Olympus, to the seat of the gods; Zeus sends a gadfly, Pegasus rears, and Bellerophon falls to earth. Pegasus alone ascends to the sky and takes his place among the stars. The tale says that inspiration can raise you up, but pride will cast you down.' },
    ],
  },

  // ─── a118 Mamut ─────────────────────────────────────────────────────────
  a118: {
    jung: {
      tr: 'Mamut, "Atasal Bellek" arketipidir — buzun altında korunmuş derin zaman; kişisel hayatın çok ötesindeki kadim güç ve kolektif hafıza. Soyu tükenmiş ama hâlâ rüyalarımızda yürüyen dev, atalarımızın ve dünyanın en eski belleğinin taşıyıcısıdır: unutulanın, kemikleşmiş kökenin sessiz çağrısı.',
      en: 'The Mammoth is the "Ancestral Memory" archetype — deep time preserved beneath the ice; an ancient power and collective memory far beyond personal life. The extinct giant that still walks in our dreams, the bearer of the oldest memory of our ancestors and of the world: the silent call of the forgotten, of the fossilized origin.',
    },
    dream: {
      tr: 'Rüyada mamut — atalarından, geçmişinden ya da çok eski bir bellekten gelen bir gücün yüzeye çıkmak istediğini söyler; kadim, sabırlı bir dayanıklılık seninle. Buzdan çıkıyorsa: uzun süre donmuş, unutulmuş bir hakikat ya da yetenek yeniden canlanıyor.',
      en: 'A mammoth in dream — tells you that a power from your ancestors, your past, or a very ancient memory wishes to surface; an ancient, patient endurance is with you. If it emerges from ice: a long-frozen, forgotten truth or gift is coming back to life.',
    },
    shadow: {
      tr: 'Derin zamanın gölgesi: geçmişe, atalara, "eski güzel günlere" o kadar bağlanmak ki şimdide yaşayamamak; soyu tükenmiş bir dünyaya, eskinin buzuna gömülüp değişime ve yeniye kapanmak. Mamut gölgesi, kadim gücü bir nostaljiye ve donmuş bir geçmişe hapseder.',
      en: 'The shadow of deep time: clinging so tightly to the past, to the ancestors, to "the good old days" that you cannot live in the present; buried in an extinct world, in the ice of the old, closed off to change and the new. The mammoth\'s shadow imprisons ancient power in nostalgia and a frozen past.',
    },
    whenAppears: {
      tr: 'Atasal bir güce, kökenlerine ya da çok eski bir belleğe bağlanman gereken dönemlerde; donmuş, unutulmuş bir gücü ya da hakikati yeniden hayata çağırman gerektiği anda belirir.',
      en: 'It appears when you must connect to an ancestral power, to your origins, or to a very ancient memory; when you must call a frozen, forgotten power or truth back to life.',
    },
    traditions: [
      { culture: { tr: 'Sibirya (Hanti / Yakut / Evenki)', en: 'Siberian (Khanty / Yakut / Evenki)' }, meaning: { tr: 'Buzdan çıkan mamut dişlerinden ötürü mamut, yeraltında yaşayan dev bir "toprak/su öküzü" sayılırdı; ışığa çıkınca öldüğüne inanılan, yeraltı dünyasına ait kadim bir ruh.', en: 'Because of the mammoth tusks emerging from the ice, the mammoth was held to be a giant "earth/water ox" living underground; an ancient spirit of the underworld believed to die when it came into the light.' } },
      { culture: { tr: 'Çin', en: 'Chinese' }, meaning: { tr: 'Eski Çin kayıtlarında mamut, kuzeyin donmuş topraklarında yaşayan, asla güneş görmeyen dev bir yeraltı yaratığı (yin shu — "gizli sıçan/fare") olarak anlatılır; toprağın derinindeki gizemin simgesi.', en: 'In old Chinese records the mammoth is described as a giant underground creature (yin shu — "the hidden rat") that lives in the frozen lands of the north and never sees the sun; a symbol of the mystery deep within the earth.' } },
      { culture: { tr: 'Kuzey Amerika Yerlileri', en: 'Native North American' }, meaning: { tr: 'Bazı yerli geleneklerde dev kemikler, kadim bir "büyük canavar" ya da atasal dev hayvan olarak anlatılır; geçmiş çağların gücünü ve dünyanın gençliğindeki devleri hatırlatan kemik-belleği.', en: 'In some Native traditions the giant bones are told of as an ancient "great monster" or ancestral giant beast; a bone-memory recalling the power of past ages and the giants of the world\'s youth.' } },
      { culture: { tr: 'Buz Çağı / Tarih Öncesi', en: 'Ice Age / Prehistoric' }, meaning: { tr: 'Mamut, Avrupa mağara resimlerinin (Chauvet, Rouffignac) en eski ve en güçlü figürlerindendir; insanlığın ilk sanatının ve atasal belleğinin merkezindeki dev, kadim bir bereket ve güç simgesi.', en: 'The mammoth is among the oldest and most powerful figures of European cave painting (Chauvet, Rouffignac); the giant at the heart of humanity\'s first art and ancestral memory, an ancient symbol of abundance and power.' } },
    ],
    myths: [
      { tr: 'Yeraltının Toprak Devi (Sibirya): Sibirya halkları, donmuş toprakta ortaya çıkan dev mamut kemiklerini ve dişlerini, yeraltında yaşayan kör bir dev yaratığın kalıntıları sanırdı. Bu varlığın köstebek gibi toprağı kazarak ilerlediğine, ama yanlışlıkla gün ışığına çıkarsa anında öldüğüne inanılırdı; bu yüzden onu hiç kimse canlı görmemişti. Anlatı, derin zamanın ve yeraltının gücünün ışığın dünyasına ait olmadığını, ancak kemik ve bellek olarak yüzeye sızdığını söyler.', en: 'The Earth Giant of the Underworld (Siberia): the peoples of Siberia took the giant mammoth bones and tusks that surfaced from the frozen ground to be the remains of a blind giant creature living underground. This being was believed to burrow through the earth like a mole, but to die at once if it came by accident into daylight; and so no one had ever seen it alive. The tale says that the power of deep time and the underworld does not belong to the world of light, but seeps to the surface only as bone and memory.' },
    ],
  },

};

export function getAnimalLore(id: string): AnimalLore | undefined {
  return ANIMAL_LORE[id];
}
